window.RECARE_EXPLANATIONS=(window.RECARE_EXPLANATIONS||[]).concat([{"id":"111-AM-002","record":{"id":"111-AM-002","choice_explanations":[{"choice":1,"correct":false,"title":"98 万人","explanation":"98万人は2019年の死亡数より少ない値です。出生数など別の人口統計と混同せず、何年の何の件数かを確認します。"},{"choice":2,"correct":false,"title":"118 万人","explanation":"118万人も当該年の死亡数を下回ります。人口動態統計の死亡数は、その年に死亡した人数を示します。"},{"choice":3,"correct":true,"title":"138 万人","explanation":"2019年の死亡数は約138万人です。将来の推計値ではなく、問題に指定された年の人口動態統計の値を答えます。"},{"choice":4,"correct":false,"title":"158 万人","explanation":"158万人は当該年の死亡数より多い値です。死亡数は年によって変わるため、最近の数値を過去の問題に当てはめません。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"日本の令和元年(2019 年)の死亡数に近いのはどれか。","choices":["98 万人","118 万人","138 万人","158 万人"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":2,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[7],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A002"},"exam":111,"year":2022,"session":"AM","number":2},"sources":[{"title":"厚生労働省：2019年人口動態総覧","url":"https://www.mhlw.go.jp/toukei/saikin/hw/jinkou/kakutei19/dl/03_h1.pdf"}]},{"id":"111-AM-003","record":{"id":"111-AM-003","choice_explanations":[{"choice":1,"correct":false,"title":"アスベスト","explanation":"アスベストは吸入による石綿肺や中皮腫などとの関係が重要です。本問で問われる室内の化学物質による症状の代表とは異なります。"},{"choice":2,"correct":false,"title":"ダイオキシン類","explanation":"ダイオキシン類は環境中の汚染物質として健康影響が問題になりますが、シックハウス症候群の代表的な原因物質ではありません。"},{"choice":3,"correct":false,"title":"放射性セシウム","explanation":"放射性セシウムでは放射線被ばくが問題になります。建材などから出る揮発性物質による室内環境の問題とは区別します。"},{"choice":4,"correct":true,"title":"ホルムアルデヒド","explanation":"建材や接着剤などから放散されるホルムアルデヒドは、目・鼻・喉の刺激などに関係します。室内の化学物質への対策では発生源と換気に着目します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"シックハウス症候群に関係する物質はどれか。\nsick house syndrome","choices":["アスベスト","ダイオキシン類","放射性セシウム","ホルムアルデヒド"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":3,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[7],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A003"},"exam":111,"year":2022,"session":"AM","number":3},"sources":[]},{"id":"111-AM-004","record":{"id":"111-AM-004","choice_explanations":[{"choice":1,"correct":false,"title":"70","explanation":"70歳は制度の一般的な加入年齢ではありません。65歳以上で一定の障害認定を受ける場合という例外と、原則の年齢を分けて覚えます。"},{"choice":2,"correct":true,"title":"75","explanation":"原則75歳以上が対象です。また65歳以上75歳未満で一定の障害があり、広域連合の認定を受けた人も対象となります。"},{"choice":3,"correct":false,"title":"80","explanation":"80歳を待って加入する制度ではありません。後期高齢者医療制度の原則の区切りは75歳です。"},{"choice":4,"correct":false,"title":"85","explanation":"85歳は加入の原則年齢ではありません。高齢者という日常語の印象で選ばず、制度の対象年齢を確認します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"後期高齢者医療制度の被保険者は、区域内に住居を有する( )歳以上の者、お\nよび 65 歳以上( )歳未満であって、政令で定める程度の障害の状態にあるとし\nて後期高齢者医療広域連合の認定を受けた者である。\n( )に入るのはどれか。","choices":["70","75","80","85"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":4,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[7],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A004"},"exam":111,"year":2022,"session":"AM","number":4},"sources":[{"title":"厚生労働省：高齢者医療確保法50条","url":"https://www.mhlw.go.jp/web/t_doc?dataId=82115000&dataType=0&pageNo=1"}]},{"id":"111-AM-005","record":{"id":"111-AM-005","choice_explanations":[{"choice":1,"correct":false,"title":"父権主義","explanation":"父権主義は、専門家が本人の利益になると考えて判断を主導する考え方です。本人が説明を受け、自分で選択する権利を最も促すものではありません。"},{"choice":2,"correct":false,"title":"医師の裁量権","explanation":"医師の裁量権は診療上の専門的判断に関わります。医師の判断だけで患者の意思が代替されるわけではなく、患者自身の選択を支える説明が必要です。"},{"choice":3,"correct":false,"title":"コンプライアンス","explanation":"コンプライアンスは治療上の指示を守ることに着目した概念です。患者が複数の選択肢を理解して自由に決める過程そのものではありません。"},{"choice":4,"correct":true,"title":"インフォームド・コンセント","explanation":"十分な説明を受けて理解し、本人の自由な意思で同意する過程です。利益・不利益や代替案を知ることで、自分に合った選択を行いやすくなります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"患者の選択権の行使を最も促進するのはどれか。","choices":["父権主義","医師の裁量権","コンプライアンス","インフォームド・コンセント"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":5,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[8],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A005"},"exam":111,"year":2022,"session":"AM","number":5},"sources":[]},{"id":"111-AM-006","record":{"id":"111-AM-006","choice_explanations":[{"choice":1,"correct":false,"title":"安全の欲求","explanation":"安全の欲求は、危険を避けて安定した環境で生活したいという欲求です。帰属や他者からの承認とは異なる階層として扱います。"},{"choice":2,"correct":true,"title":"帰属の欲求","explanation":"集団の一員でありたい、他者とつながりたいという欲求です。本問は公式に2または3の単独解答を正答としており、2つ同時に選ぶ問題ではありません。"},{"choice":3,"correct":true,"title":"承認の欲求","explanation":"他者に認められたいという欲求です。帰属とは別の階層ですが、本問では3も公式に正答扱いです。「社会的欲求」の範囲が一意でない特別な採点として理解します。"},{"choice":4,"correct":false,"title":"睡眠の欲求","explanation":"睡眠は生命を維持するための生理的欲求です。他者との関係を求める欲求より基礎となる身体的な必要に位置付けられます。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"マズロー, A. H. の基本的欲求の階層で社会的欲求はどれか。\nMaslow, A. H.","choices":["安全の欲求","帰属の欲求","承認の欲求","睡眠の欲求"],"correct_answers":[2,3],"accepted_answer_sets":[[2],[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":6,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[8],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A006"},"exam":111,"year":2022,"session":"AM","number":6},"sources":[{"title":"厚生労働省：第111回看護師国家試験 午前6 採点上の取扱い","url":"https://www.mhlw.go.jp/general/sikaku/successlist/2022/siken03_04_05/dl/kangoshi_am06.pdf"}]},{"id":"111-AM-007","record":{"id":"111-AM-007","choice_explanations":[{"choice":1,"correct":false,"title":"総頸動脈","explanation":"総頸動脈は頭頸部へ血液を送る血管です。胎盤と胎児を結ぶ血管ではありません。"},{"choice":2,"correct":false,"title":"肺動脈","explanation":"肺動脈は心臓から肺へ向かう血管です。胎児の肺循環は出生後と異なりますが、胎盤へ向かう血管は臍動脈です。"},{"choice":3,"correct":true,"title":"臍動脈","explanation":"臍動脈は胎児から胎盤へ血液を送り、胎盤でガスや物質の交換を行います。動脈・静脈の名称は酸素量ではなく血流の向きで区別します。"},{"choice":4,"correct":false,"title":"臍静脈","explanation":"臍静脈は胎盤から胎児へ血液を戻す血管です。胎盤で酸素を受け取った血液が流れ、設問とは向きが逆です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"胎児循環で胎児から胎盤に血液を送るのはどれか。","choices":["総頸動脈","肺動脈","臍動脈","臍静脈"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":7,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[8],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A007"},"exam":111,"year":2022,"session":"AM","number":7},"sources":[]},{"id":"111-AM-008","record":{"id":"111-AM-008","choice_explanations":[{"choice":1,"correct":false,"title":"50〜 70/分","explanation":"学童期の安静時の代表値としては少ない範囲です。脈拍は運動や睡眠などでも変わるため、この範囲だけで個人を異常と決めるものではありません。"},{"choice":2,"correct":true,"title":"80〜100/分","explanation":"本問の学童期の安静時脈拍の目安は80〜100/分です。小児では成長に伴って脈拍数が減少し、成人の値に近づいていきます。"},{"choice":3,"correct":false,"title":"110〜130/分","explanation":"学童期の代表的な安静時脈拍としては多い範囲です。より低年齢では脈拍が多く、年齢による違いを考えて評価します。"},{"choice":4,"correct":false,"title":"140〜160/分","explanation":"学童期の安静時の目安としては多すぎます。泣いている時や発熱時などの変動と、年齢別の安静時の基準を区別します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"学童期の脈拍数の基準値はどれか。","choices":["50〜 70/分","80〜100/分","110〜130/分","140〜160/分"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":8,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[8],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A008"},"exam":111,"year":2022,"session":"AM","number":8},"sources":[{"title":"厚生労働統計協会：学童期の脈拍の目安","url":"https://www.hws-kyokai.or.jp/publishing/eiesei-kangoshiken-main/eiesei-kangoshiken-105-pm1.html"}]},{"id":"111-AM-009","record":{"id":"111-AM-009","choice_explanations":[{"choice":1,"correct":false,"title":"30 歳","explanation":"30歳は日本女性の平均閉経年齢より若い値です。若い年齢の無月経を、平均的な閉経として説明することはできません。"},{"choice":2,"correct":false,"title":"40 歳","explanation":"40歳で閉経する人もいますが、集団の平均に最も近い値ではありません。個人差と平均年齢を分けて考えます。"},{"choice":3,"correct":true,"title":"50 歳","explanation":"平均閉経年齢は50歳前後です。卵巣機能の低下に伴い月経が終わりますが、閉経を迎える年齢には個人差があります。"},{"choice":4,"correct":false,"title":"60 歳","explanation":"60歳は平均より高い値です。閉経年齢のばらつきがあることと、平均としてどの値が近いかは別の問いです。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"日本の女性における平均閉経年齢に最も近いのはどれか。","choices":["30 歳","40 歳","50 歳","60 歳"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":9,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[9],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A009"},"exam":111,"year":2022,"session":"AM","number":9},"sources":[{"title":"日本産婦人科医会：更年期障害","url":"https://www.jaog.or.jp/qa/menopause/更年期障害について教えて下さい。/"}]},{"id":"111-AM-010","record":{"id":"111-AM-010","choice_explanations":[{"choice":1,"correct":false,"title":"単独世帯","explanation":"単独世帯は一人で暮らす世帯です。2019年の調査では三世代世帯より多く、選択肢中の最少ではありません。"},{"choice":2,"correct":true,"title":"三世代世帯","explanation":"三世代世帯は、世帯主を中心とする直系三世代以上の世帯です。2019年の調査では、この4つの世帯構造の中で最も少ない区分です。"},{"choice":3,"correct":false,"title":"夫婦のみの世帯","explanation":"夫婦のみで構成される世帯です。子の独立後なども含まれ、当該年の調査では三世代世帯より多い区分です。"},{"choice":4,"correct":false,"title":"夫婦と未婚の子のみの世帯","explanation":"夫婦と未婚の子からなる世帯です。核家族の一形態であり、当該年の調査で選択肢中最少となる区分ではありません。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"令和元年(2019 年)の国民生活基礎調査で次の世帯構造のうち最も少ないのはど\nれか。","choices":["単独世帯","三世代世帯","夫婦のみの世帯","夫婦と未婚の子のみの世帯"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":10,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[9],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A010"},"exam":111,"year":2022,"session":"AM","number":10},"sources":[{"title":"厚生労働省：2019年国民生活基礎調査 世帯構造","url":"https://www.mhlw.go.jp/toukei/saikin/hw/k-tyosa/k-tyosa19/dl/02.pdf"}]},{"id":"111-AM-012","record":{"id":"111-AM-012","choice_explanations":[{"choice":1,"correct":false,"title":"胃","explanation":"胃は食物を一時的にため、胃酸や消化酵素で消化を進めます。有害物質の代謝・無毒化を代表する臓器ではありません。"},{"choice":2,"correct":true,"title":"肝 臓","explanation":"肝臓は体内外の物質を代謝し、有害性を低くしたり排泄しやすい形に変えたりします。消化管から吸収された物質が門脈を通って入ることと結び付けます。"},{"choice":3,"correct":false,"title":"膵 臓","explanation":"膵臓は消化酵素を分泌し、インスリンなどで血糖調節も行います。本問の解毒・代謝の中心となる臓器とは異なります。"},{"choice":4,"correct":false,"title":"大 腸","explanation":"大腸は水分の吸収や便の形成・排出を担います。便を排出する働きと、有害物質を化学的に処理する肝臓の働きは区別します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"有害物質を無毒化し排泄する臓器はどれか。","choices":["胃","肝 臓","膵 臓","大 腸"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":12,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[11],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A012"},"exam":111,"year":2022,"session":"AM","number":12},"sources":[]},{"id":"111-AM-013","record":{"id":"111-AM-013","choice_explanations":[{"choice":1,"correct":false,"title":"動 悸","explanation":"動悸は不整脈や貧血など多様な状態で起こります。黄疸に特徴的な随伴症状として最も結び付く選択肢ではありません。"},{"choice":2,"correct":false,"title":"難 聴","explanation":"難聴は聴覚の障害であり、黄疸のある成人に一般的に伴う症状ではありません。成人という条件も確認します。"},{"choice":3,"correct":false,"title":"関節痛","explanation":"関節痛が肝疾患に併存することはありますが、黄疸自体に典型的な随伴症状ではありません。"},{"choice":4,"correct":true,"title":"搔痒感","explanation":"胆汁うっ滞を伴う黄疸では、皮膚のかゆみが生じることがあります。皮膚の黄染だけでなく、搔き傷や睡眠への影響も観察します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"黄疸のある成人患者にみられる随伴症状はどれか。","choices":["動 悸","難 聴","関節痛","搔痒感"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":13,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[11],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A013"},"exam":111,"year":2022,"session":"AM","number":13},"sources":[]},{"id":"111-AM-014","record":{"id":"111-AM-014","choice_explanations":[{"choice":1,"correct":false,"title":"胃潰瘍\ngastric ulcer","explanation":"胃潰瘍では心窩部の痛みが代表的です。設問の左前胸部から頸部・左上肢へ広がる痛みは、心筋虚血を考える特徴です。"},{"choice":2,"correct":true,"title":"狭心症\nangina pectoris","explanation":"狭心症では心筋への酸素供給が不足し、胸部の痛みや圧迫感が頸部・左上肢などへ広がることがあります。痛みの部位だけでなく放散の方向も手掛かりです。"},{"choice":3,"correct":false,"title":"胆石症\ncholelithiasis","explanation":"胆石症では右上腹部などの痛みが代表的で、右肩や背部へ広がることがあります。設問の放散痛の特徴とは異なります。"},{"choice":4,"correct":false,"title":"尿管結石症\nureterolithiasis","explanation":"尿管結石症では側腹部から下腹部・鼠径部へ広がる強い痛みがみられます。胸部から左上肢へ向かう痛みとは区別します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"左前胸部から頸部や左上肢への放散痛が生じる疾患はどれか。","choices":["胃潰瘍\ngastric ulcer","狭心症\nangina pectoris","胆石症\ncholelithiasis","尿管結石症\nureterolithiasis"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":14,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[11],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A014"},"exam":111,"year":2022,"session":"AM","number":14},"sources":[]},{"id":"111-AM-015","record":{"id":"111-AM-015","choice_explanations":[{"choice":1,"correct":false,"title":"150〜250 万/μL","explanation":"成人女性の赤血球数としては少ない範囲です。貧血の評価では赤血球数だけでなく、ヘモグロビンなども併せて確認します。"},{"choice":2,"correct":true,"title":"350〜450 万/μL","explanation":"選択肢では350〜450万/μLが成人女性の基準に最も合います。基準範囲は施設等で異なるため、この数字だけで個人の診断を決めません。"},{"choice":3,"correct":false,"title":"550〜650 万/μL","explanation":"成人女性の基準値としては多い範囲です。脱水などの影響でも血球数は変わるため、基準との比較と原因の判断を分けます。"},{"choice":4,"correct":false,"title":"750〜850 万/μL","explanation":"成人女性の一般的な基準から大きく高い範囲です。赤血球・白血球・血小板の桁や単位を取り違えないようにします。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"成人女性の赤血球数の基準値はどれか。","choices":["150〜250 万/μL","350〜450 万/μL","550〜650 万/μL","750〜850 万/μL"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":15,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[11],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A015"},"exam":111,"year":2022,"session":"AM","number":15},"sources":[{"title":"国立病院機構東京病院：血液検査と施設の基準範囲","url":"https://tokyo-hp.hosp.go.jp/bumon/kensa/kensa.html"}]},{"id":"111-AM-016","record":{"id":"111-AM-016","choice_explanations":[{"choice":1,"correct":false,"title":"｢頭は痛みませんか｣","explanation":"頭痛の有無を「はい・いいえ」で答えられる質問です。確認したい事項を絞る閉じた質問に当たります。"},{"choice":2,"correct":false,"title":"｢昨夜は眠れましたか｣","explanation":"眠れたかどうかに回答を限定しやすい質問です。睡眠の状況を自由に語ってもらうには、どのような眠りだったかを尋ねます。"},{"choice":3,"correct":false,"title":"｢気分は悪くありませんか｣","explanation":"気分不良の有無に答えを限定する閉じた質問です。相手の自由な説明を促す形式ではありません。"},{"choice":4,"correct":true,"title":"｢自宅ではどのように過ごしていましたか｣","explanation":"過ごし方を本人の言葉で自由に説明できる質問です。回答の選択肢を限定せず、生活や思いを幅広く把握するときに役立ちます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"Open-ended question〈開かれた質問〉はどれか。","choices":["｢頭は痛みませんか｣","｢昨夜は眠れましたか｣","｢気分は悪くありませんか｣","｢自宅ではどのように過ごしていましたか｣"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":16,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[12],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A016"},"exam":111,"year":2022,"session":"AM","number":16},"sources":[]},{"id":"111-AM-017","record":{"id":"111-AM-017","choice_explanations":[{"choice":1,"correct":false,"title":"腋窩温","explanation":"腋窩温は測定しやすい一方、皮膚の状態や密着、外気の影響を受けます。選択肢中で深部体温に最も近い測定部位ではありません。"},{"choice":2,"correct":false,"title":"口腔温","explanation":"口腔温は飲食や口呼吸などの影響を受けます。測定条件を整える必要があり、本問では直腸温を選びます。"},{"choice":3,"correct":false,"title":"鼓膜温","explanation":"鼓膜温も深部体温を推定するために使われますが、機器や測定位置による影響があります。本問の代表的な測定部位としては直腸温が正答です。"},{"choice":4,"correct":true,"title":"直腸温","explanation":"直腸は外気の影響を受けにくく、深部体温に近い値が得られます。ただし測定には適応や粘膜損傷のリスクへの配慮が必要です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"深部体温に最も近いのはどれか。","choices":["腋窩温","口腔温","鼓膜温","直腸温"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":17,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[12],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A017"},"exam":111,"year":2022,"session":"AM","number":17},"sources":[]},{"id":"111-AM-019","record":{"id":"111-AM-019","choice_explanations":[{"choice":1,"correct":true,"title":"就寝時に外す。","explanation":"就寝時は通常義歯を外して粘膜を休ませ、義歯と口腔を清潔にします。個別の歯科指示がある場合は、その指示に従います。"},{"choice":2,"correct":false,"title":"熱湯で洗浄する。","explanation":"熱湯は義歯の変形などにつながるため避けます。材質に合った方法で、専用ブラシや洗浄剤を用いて清掃します。"},{"choice":3,"correct":false,"title":"保管時は乾燥させる。","explanation":"乾燥による変形を防ぐため、水など適切な方法で保管します。外しておくだけでなく、清掃と保管の両方が必要です。"},{"choice":4,"correct":false,"title":"総義歯は奥歯を起点に外す。","explanation":"奥歯を起点に無理にこじって外す方法は適切ではありません。前歯側から吸着を解除するなど、義歯に合った方法で粘膜を傷つけずに外します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"高齢者の義歯の取り扱い方法で正しいのはどれか。","choices":["就寝時に外す。","熱湯で洗浄する。","保管時は乾燥させる。","総義歯は奥歯を起点に外す。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":19,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[13],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A019"},"exam":111,"year":2022,"session":"AM","number":19},"sources":[]},{"id":"111-AM-020","record":{"id":"111-AM-020","choice_explanations":[{"choice":1,"correct":false,"title":"赤","explanation":"赤は血液など液状・泥状の感染性廃棄物の目印です。針は液体が付着していても、鋭利な物として安全に分別します。"},{"choice":2,"correct":true,"title":"黄","explanation":"黄は注射針など鋭利な物の目印です。針刺しを防ぐため、耐貫通性のある専用容器に廃棄します。"},{"choice":3,"correct":false,"title":"黒","explanation":"黒は、この性状別のバイオハザードマークの区分ではありません。鋭利な物は黄色と対応させます。"},{"choice":4,"correct":false,"title":"橙","explanation":"橙は血液の付着したガーゼなど固形状の感染性廃棄物の目印です。針は固体でも鋭利物として別に扱います。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"使用後の注射針を廃棄する容器のバイオハザードマークの色はどれか。","choices":["赤","黄","黒","橙"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":20,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[14],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A020"},"exam":111,"year":2022,"session":"AM","number":20},"sources":[{"title":"環境省：感染性廃棄物の性状別表示","url":"https://www.env.go.jp/hourei/11/000074.html"}]},{"id":"111-AM-021","record":{"id":"111-AM-021","choice_explanations":[{"choice":1,"correct":false,"title":"採血部位から2、3cm 中枢側に駆血帯を巻く。","explanation":"穿刺点のすぐ近くに巻くと操作を妨げます。採血する血管が見やすくなるよう、適切に離れた中枢側へ巻きます。"},{"choice":2,"correct":false,"title":"血管の走行に合わせ 60 度の角度で刺入する。","explanation":"60度では深く刺し込みやすく、血管を貫通したり周辺を傷つけたりする危険があります。表在静脈へは血管の走行に沿って浅い角度で刺入します。"},{"choice":3,"correct":false,"title":"採血後は刺入部位を圧迫しながら抜針する。","explanation":"針が血管内にあるうちから強く圧迫すると、組織を傷つけるおそれがあります。針を抜いてから穿刺部を圧迫して止血します。"},{"choice":4,"correct":true,"title":"刺入部位は5分以上圧迫し、止血する。","explanation":"採血後は穿刺部を十分に圧迫し、止血を確認します。本問では5分以上が適切で、出血しやすい患者では状態に応じてさらに確認が必要です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"成人の静脈血採血で適切なのはどれか。","choices":["採血部位から2、3cm 中枢側に駆血帯を巻く。","血管の走行に合わせ 60 度の角度で刺入する。","採血後は刺入部位を圧迫しながら抜針する。","刺入部位は5分以上圧迫し、止血する。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":21,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[14],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A021"},"exam":111,"year":2022,"session":"AM","number":21},"sources":[]},{"id":"111-AM-022","record":{"id":"111-AM-022","choice_explanations":[{"choice":1,"correct":false,"title":"嘔 吐","explanation":"吸引刺激で嘔吐を誘発することはありますが、長時間吸引を続けることから最も直接的に問題となるのは酸素化の低下です。"},{"choice":2,"correct":false,"title":"感 染","explanation":"感染予防には手指衛生や器具の清潔な取り扱いが重要です。30秒以上という吸引時間の延長から最も考える合併症ではありません。"},{"choice":3,"correct":true,"title":"低酸素血症","explanation":"吸引を続けると気道内の空気も吸い出され、換気が妨げられて酸素化が低下します。短時間で行い、呼吸状態や酸素飽和度を観察します。"},{"choice":4,"correct":false,"title":"気道粘膜の損傷","explanation":"粘膜損傷は過大な吸引圧やカテーテルの接触などでも起こります。本問では長い吸引時間による低酸素血症が最も適切です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"1回の気管内吸引を 30 秒以上実施した場合に生じるのはどれか。","choices":["嘔 吐","感 染","低酸素血症","気道粘膜の損傷"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":22,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[14],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A022"},"exam":111,"year":2022,"session":"AM","number":22},"sources":[]},{"id":"111-AM-023","record":{"id":"111-AM-023","choice_explanations":[{"choice":1,"correct":true,"title":"腋窩動脈","explanation":"出血部位より心臓側の動脈を圧迫して血流を減らします。上腕への血液供給を中枢側で抑えるため、腋窩動脈を選びます。"},{"choice":2,"correct":false,"title":"尺骨動脈","explanation":"尺骨動脈は上腕より末梢にあり、前腕・手へ血液を送ります。ここを圧迫しても上腕の出血への流入は抑えられません。"},{"choice":3,"correct":false,"title":"大腿動脈","explanation":"大腿動脈は下肢の血管です。上腕への血流を抑えるための圧迫部位ではありません。"},{"choice":4,"correct":false,"title":"橈骨動脈","explanation":"橈骨動脈は前腕の血管で、上腕の出血部位より末梢です。間接圧迫では出血部より心臓側を選びます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"上腕出血時の間接圧迫止血の部位はどれか。","choices":["腋窩動脈","尺骨動脈","大腿動脈","橈骨動脈"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":23,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[14],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A023"},"exam":111,"year":2022,"session":"AM","number":23},"sources":[]},{"id":"111-AM-024","record":{"id":"111-AM-024","choice_explanations":[{"choice":1,"correct":false,"title":"5","explanation":"5回ごとに人工呼吸を行う比率は、本問の成人BLSには合いません。胸骨圧迫を頻回に中断しないことが重要です。"},{"choice":2,"correct":false,"title":"10","explanation":"10対2は成人BLSの基本比率ではありません。圧迫の継続による血流確保と、人工呼吸による酸素供給を組み合わせます。"},{"choice":3,"correct":true,"title":"30","explanation":"成人で胸骨圧迫と人工呼吸を組み合わせる基本比率は30対2です。これは両者を行う場合の比率で、状況により胸骨圧迫のみを行う場合とは区別します。"},{"choice":4,"correct":false,"title":"50","explanation":"50対2は本問の基本比率ではありません。回数だけでなく、圧迫の中断を短くして適切な人工呼吸を行うことを理解します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"成人に対する一次救命処置〈BLS〉において、胸骨圧迫と人工呼吸の回数比は\n( )：2である。\n( )に入るのはどれか。","choices":["5","10","30","50"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":24,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[15],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A024"},"exam":111,"year":2022,"session":"AM","number":24},"sources":[{"title":"日本蘇生協議会：JRC蘇生ガイドライン2020 BLS","url":"https://www.jrc-cpr.org/wp-content/uploads/2022/07/JRC_0017-0046_BLS.pdf"}]},{"id":"111-AM-025","record":{"id":"111-AM-025","choice_explanations":[{"choice":1,"correct":false,"title":"一 類","explanation":"一類はエボラ出血熱などの感染症です。重症になるという印象だけで結核を一類に分類しないようにします。"},{"choice":2,"correct":true,"title":"二 類","explanation":"結核は二類感染症です。感染拡大防止のための届出や、病状・感染性に応じた入院などの公的な対策につながる分類です。"},{"choice":3,"correct":false,"title":"三 類","explanation":"三類には腸管出血性大腸菌感染症などが含まれます。結核の法的区分とは異なります。"},{"choice":4,"correct":false,"title":"四 類","explanation":"四類には動物や媒介生物などを介する感染症が含まれます。結核はこの区分ではありません。"},{"choice":5,"correct":false,"title":"五 類","explanation":"五類には流行状況を把握して対策につなげる感染症が含まれます。結核は五類ではなく二類として扱われます。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"感染症の予防及び感染症の患者に対する医療に関する法律〈感染症法〉において、\n結核が分類されるのはどれか。","choices":["一 類","二 類","三 類","四 類","五 類"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":25,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[15],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A025"},"exam":111,"year":2022,"session":"AM","number":25},"sources":[{"title":"厚生労働省：感染症法","url":"https://www.mhlw.go.jp/web/t_doc?dataId=79998826&dataType=0"}]},{"id":"111-AM-026","record":{"id":"111-AM-026","choice_explanations":[{"choice":1,"correct":false,"title":"心拍数の増加","explanation":"通常は心拍数が増えると単位時間の拍出量は増加します。ただし極端な頻脈では心室が満たされにくくなるため、無制限に増えるという意味ではありません。"},{"choice":2,"correct":true,"title":"大動脈圧の上昇","explanation":"大動脈圧が上がると、左心室が血液を押し出す際の抵抗である後負荷が増えます。そのため一回拍出量が減り、心拍出量が低下する方向に働きます。"},{"choice":3,"correct":false,"title":"静脈還流量の増加","explanation":"静脈還流が増すと心室への流入が増え、正常な心臓では拍出量を増やす方向に働きます。前負荷と拍出量の関係を考えます。"},{"choice":4,"correct":false,"title":"心筋収縮力の上昇","explanation":"心筋収縮力の上昇は、血液を押し出す力を強めます。通常は一回拍出量を増やす方向に働き、設問とは逆です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"正常な心臓で心拍出量が減少するのはどれか。","choices":["心拍数の増加","大動脈圧の上昇","静脈還流量の増加","心筋収縮力の上昇"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":26,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[15],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A026"},"exam":111,"year":2022,"session":"AM","number":26},"sources":[]},{"id":"111-AM-027","record":{"id":"111-AM-027","choice_explanations":[{"choice":1,"correct":false,"title":"ワクチン内の抗原を提示するのは好中球である。","explanation":"抗原提示の中心を担うのは樹状細胞などです。好中球は主に病原体の貪食などに働き、ワクチン応答の代表的な抗原提示細胞としては選びません。"},{"choice":2,"correct":false,"title":"抗原に対して最初に産生される抗体は IgA である。","explanation":"初めての抗原に対する応答では、一般にIgMが先に産生されます。IgAは粘膜面の防御との関連で理解します。"},{"choice":3,"correct":false,"title":"抗原に対して血中濃度が最も高くなる抗体は IgM である。","explanation":"IgMは初期応答で重要ですが、通常の血中免疫グロブリンではIgGが多くなります。初期の抗体と、その後の応答を区別します。"},{"choice":4,"correct":true,"title":"同じワクチンを2回接種すると抗原に対する抗体の産生量が増加する。","explanation":"初回接種で免疫記憶ができ、再び同じ抗原に接するとより強い応答が起こります。追加接種による増強を、免疫記憶と関連付けて覚えます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"ワクチン接種後の抗体産生について正しいのはどれか。","choices":["ワクチン内の抗原を提示するのは好中球である。","抗原に対して最初に産生される抗体は IgA である。","抗原に対して血中濃度が最も高くなる抗体は IgM である。","同じワクチンを2回接種すると抗原に対する抗体の産生量が増加する。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":27,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[16],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A027"},"exam":111,"year":2022,"session":"AM","number":27},"sources":[]},{"id":"111-AM-028","record":{"id":"111-AM-028","choice_explanations":[{"choice":1,"correct":false,"title":"マクロファージ","explanation":"マクロファージは異物の貪食や抗原提示を行います。B細胞が分化して抗体を大量に分泌する細胞ではありません。"},{"choice":2,"correct":true,"title":"形質細胞","explanation":"抗原に反応したB細胞は形質細胞へ分化し、抗体を分泌します。抗体を作る細胞と、抗体が結合した異物を処理する細胞を区別します。"},{"choice":3,"correct":false,"title":"肥満細胞","explanation":"肥満細胞はヒスタミンなどを放出し、アレルギー反応などに関与します。B細胞由来の抗体産生細胞ではありません。"},{"choice":4,"correct":false,"title":"T 細胞","explanation":"T細胞は免疫応答の調節や感染細胞への攻撃などを担います。B細胞がT細胞に変化して抗体を産生するわけではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"B 細胞が抗原認識によって分化した抗体産生細胞はどれか。","choices":["マクロファージ","形質細胞","肥満細胞","T 細胞"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":28,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[16],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A028"},"exam":111,"year":2022,"session":"AM","number":28},"sources":[]},{"id":"111-AM-029","record":{"id":"111-AM-029","choice_explanations":[{"choice":1,"correct":false,"title":"環状紅斑","explanation":"環状紅斑は輪のような形の発疹です。皮膚筋炎に特徴的な眼瞼の発疹として選ぶ所見ではありません。"},{"choice":2,"correct":false,"title":"蝶形紅斑","explanation":"蝶形紅斑は頬から鼻にかけてみられる発疹で、全身性エリテマトーデスとの関連が重要です。"},{"choice":3,"correct":false,"title":"ディスコイド疹","explanation":"ディスコイド疹は円板状の皮疹で、皮膚エリテマトーデスなどでみられます。皮膚筋炎の代表的な眼瞼の皮疹とは異なります。"},{"choice":4,"correct":true,"title":"ヘリオトロープ疹","explanation":"ヘリオトロープ疹は眼瞼にみられる紫紅色の皮疹で、皮膚筋炎に特徴的です。筋力低下などの筋症状と皮膚症状を結び付けて理解します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"皮膚筋炎の皮膚症状はどれか。\ndermatomyositis","choices":["環状紅斑","蝶形紅斑","ディスコイド疹","ヘリオトロープ疹"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":29,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[16],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A029"},"exam":111,"year":2022,"session":"AM","number":29},"sources":[]},{"id":"111-AM-030","record":{"id":"111-AM-030","choice_explanations":[{"choice":1,"correct":false,"title":"介護休業は分割して取得することはできない。","explanation":"出題時の制度では、対象家族1人につき3回まで分割できます。仕事との両立に必要な支援体制を整えるためにも利用する制度です。"},{"choice":2,"correct":false,"title":"介護の対象者1人につき半年を限度に取得できる。","explanation":"上限は対象家族1人につき通算93日で、半年ではありません。日数の上限と分割回数を分けて覚えます。"},{"choice":3,"correct":true,"title":"要介護状態にある配偶者を介護するために取得できる。","explanation":"要介護状態にある配偶者は対象家族に含まれます。介護保険の要介護認定の有無だけで利用対象が決まるわけではありません。"},{"choice":4,"correct":false,"title":"介護老人福祉施設に入所している家族の面会のために取得できる。","explanation":"単に面会することだけを理由に取得する制度ではありません。ただし施設に入所していても必要な介護や手続き等があれば、一律に対象外という意味ではありません。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"育児休業、介護休業等育児又は家族介護を行う労働者の福祉に関する法律〈育\n児・介護休業法〉における介護休業の取得で正しいのはどれか。","choices":["介護休業は分割して取得することはできない。","介護の対象者1人につき半年を限度に取得できる。","要介護状態にある配偶者を介護するために取得できる。","介護老人福祉施設に入所している家族の面会のために取得できる。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":30,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[16],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A030"},"exam":111,"year":2022,"session":"AM","number":30},"sources":[{"title":"厚生労働省：2022年資料 介護休業の対象・日数・分割","url":"https://www.mhlw.go.jp/churoi/chousei/chingin/22/dl/05.pdf"}]},{"id":"111-AM-031","record":{"id":"111-AM-031","choice_explanations":[{"choice":1,"correct":false,"title":"がん対策","explanation":"がん対策は予防・検診・治療体制などを含む政策です。社会福祉協議会が地域福祉のために推進する活動としては、ボランティア活動が最も適切です。"},{"choice":2,"correct":false,"title":"男女共同参画","explanation":"男女共同参画は性別によらず社会に参加できることを目指します。社会福祉法に基づく社会福祉協議会の代表的な活動を問う本問の答えではありません。"},{"choice":3,"correct":false,"title":"就労の支援活動","explanation":"就労支援に社会福祉協議会が関わることはあります。ただし本問で問う、地域住民の福祉活動への参加を促す代表的な事業とは異なります。"},{"choice":4,"correct":true,"title":"ボランティア活動","explanation":"社会福祉協議会は地域住民や団体と協力し、地域福祉を推進します。ボランティアの相談や参加支援などを通じ、住民の自主的な活動を支えます。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"社会福祉法に基づき社会福祉協議会が推進するのはどれか。","choices":["がん対策","男女共同参画","就労の支援活動","ボランティア活動"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":31,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[17],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A031"},"exam":111,"year":2022,"session":"AM","number":31},"sources":[{"title":"厚生労働省：社会福祉協議会の概要","url":"https://www.mhlw.go.jp/content/12602000/000954071.pdf"}]},{"id":"111-AM-032","record":{"id":"111-AM-032","choice_explanations":[{"choice":1,"correct":true,"title":"女性の死因の第3位は老衰である。","explanation":"2018年の女性の死因順位では、老衰が第3位です。死因順位は性別と年によって異なるので、両者を確認して覚えます。"},{"choice":2,"correct":false,"title":"男性の死因の第3位は肺炎である。\npneumonia","explanation":"2018年の男性で肺炎は第3位ではありません。男女合計の順位や、別の年の順位と混同しないようにします。"},{"choice":3,"correct":false,"title":"女性の平均寿命は 89 年を超えている。","explanation":"2018年の女性の平均寿命は約87年で、89年を超えていません。平均寿命はその年の死亡状況を基にした0歳の平均余命です。"},{"choice":4,"correct":false,"title":"男性の平均寿命は 83 年を超えている。","explanation":"2018年の男性の平均寿命は約81年で、83年を超えていません。女性の値や将来の推計値とは区別します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"日本の平成 30 年(2018 年)の健康に関する指標の記述で正しいのはどれか。","choices":["女性の死因の第3位は老衰である。","男性の死因の第3位は肺炎である。\npneumonia","女性の平均寿命は 89 年を超えている。","男性の平均寿命は 83 年を超えている。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":32,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[17],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A032"},"exam":111,"year":2022,"session":"AM","number":32},"sources":[{"title":"厚生労働省：2018年性別死因順位","url":"https://www.mhlw.go.jp/toukei/saikin/hw/jinkou/kakutei18/dl/10_h6.pdf"},{"title":"厚生労働省：2018年簡易生命表","url":"https://www.mhlw.go.jp/toukei/saikin/hw/life/life18/dl/life18-02.pdf"}]},{"id":"111-AM-033","record":{"id":"111-AM-033","choice_explanations":[{"choice":1,"correct":true,"title":"健康管理","explanation":"労働衛生の3管理は、作業環境管理・作業管理・健康管理です。健康診断やその後の措置など、働く人の健康状態に着目するのが健康管理です。"},{"choice":2,"correct":false,"title":"総括管理","explanation":"総括的な管理は職場の安全衛生活動を進めるうえで重要ですが、設問の3管理を構成する名称ではありません。"},{"choice":3,"correct":false,"title":"労務管理","explanation":"労務管理は労働条件や人事などを含む広い概念です。職場の有害要因と健康を管理する3つの区分とは区別します。"},{"choice":4,"correct":false,"title":"出退勤管理","explanation":"出退勤管理は労働時間の把握に必要ですが、労働衛生の3管理の一つとして挙げる名称ではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"労働衛生の｢3管理｣とは、作業環境管理と作業管理と( )である。\n( )に入るのはどれか。","choices":["健康管理","総括管理","労務管理","出退勤管理"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":33,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[17],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A033"},"exam":111,"year":2022,"session":"AM","number":33},"sources":[]},{"id":"111-AM-034","record":{"id":"111-AM-034","choice_explanations":[{"choice":1,"correct":true,"title":"世界保健機関〈WHO〉の健康に関する定義","explanation":"WHO憲章は、到達可能な最高水準の健康を享受することを基本的権利としています。本問は公式に1または3の単独解答を正答とする特別扱いです。"},{"choice":2,"correct":false,"title":"ジュネーブ宣言","explanation":"ジュネーブ宣言は医師の倫理的な誓約です。本問で健康を人々の権利として示した資料として正答扱いされるものではありません。"},{"choice":3,"correct":true,"title":"世界人権宣言","explanation":"世界人権宣言は健康・福祉に必要な生活水準への権利を示しています。本問では3も公式正答であり、1と3を同時に選ぶ問題ではありません。"},{"choice":4,"correct":false,"title":"リスボン宣言","explanation":"リスボン宣言は患者の権利を示す宣言です。適切な医療や自己決定などを扱いますが、本問の公式正答は1または3です。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"健康を人々の権利として明記したのはどれか。","choices":["世界保健機関〈WHO〉の健康に関する定義","ジュネーブ宣言","世界人権宣言","リスボン宣言"],"correct_answers":[1,3],"accepted_answer_sets":[[1],[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":34,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[17],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A034"},"exam":111,"year":2022,"session":"AM","number":34},"sources":[{"title":"WHO：WHO憲章","url":"https://www.who.int/about/governance/constitution"},{"title":"国際連合：世界人権宣言","url":"https://www.un.org/en/about-us/universal-declaration-of-human-rights"}]},{"id":"111-AM-035","record":{"id":"111-AM-035","choice_explanations":[{"choice":1,"correct":true,"title":"医療機関から在宅までの医療の継続的な提供","explanation":"急性期から回復期、在宅などへ移る際に治療・ケアの計画を共有し、継続した医療につなげます。施設を越えて見通しを共有することが中心です。"},{"choice":2,"correct":false,"title":"地域包括支援センターと地域住民との連携","explanation":"地域住民との連携は地域包括支援センターの重要な役割ですが、地域連携クリニカルパスの直接の目的とは異なります。"},{"choice":3,"correct":false,"title":"地域医療を担う医療専門職の資質向上","explanation":"専門職の教育に役立つことはありますが、主目的は個々の患者の診療計画を地域の関係者で共有し、継続性を確保することです。"},{"choice":4,"correct":false,"title":"患者が活用できる社会資源の紹介","explanation":"社会資源の紹介も退院支援に含まれますが、パスは紹介だけでなく、治療やケアの予定を複数機関で共有するものです。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"地域連携クリニカルパスの目的はどれか。","choices":["医療機関から在宅までの医療の継続的な提供","地域包括支援センターと地域住民との連携","地域医療を担う医療専門職の資質向上","患者が活用できる社会資源の紹介"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":35,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[18],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A035"},"exam":111,"year":2022,"session":"AM","number":35},"sources":[]},{"id":"111-AM-036","record":{"id":"111-AM-036","choice_explanations":[{"choice":1,"correct":false,"title":"胃全摘出術後の患者への退院指導","explanation":"胃全摘後は食事のとり方や症状、生活に合わせた個別調整が重要です。集団教育も可能ですが、この選択肢では個別の退院指導が優先されます。"},{"choice":2,"correct":true,"title":"1型糖尿病の学童を対象とした療養指導\ntype 1 diabetes mellitus","explanation":"同じ病気をもつ学童同士で経験や工夫を共有でき、仲間との交流が療養行動を支えます。個別の状態や理解力の評価も併せて行います。"},{"choice":3,"correct":false,"title":"子宮頸癌の術後の神経因性膀胱の患者への間欠的自己導尿の指導\ncancer of the uterine cervix","explanation":"自己導尿は本人の身体状態や手技の習得状況に合わせ、プライバシーに配慮した実技指導が必要です。まず個別の支援が適しています。"},{"choice":4,"correct":false,"title":"ヒト免疫不全ウイルス〈HIV〉感染者への生活指導\nhuman immunodeficiency virus infection","explanation":"本人の生活背景や情報開示の希望を踏まえた支援が必要です。本人が希望する交流は役立ち得ますが、一律の集団指導を優先する場面ではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"集団指導が望ましいのはどれか。","choices":["胃全摘出術後の患者への退院指導","1型糖尿病の学童を対象とした療養指導\ntype 1 diabetes mellitus","子宮頸癌の術後の神経因性膀胱の患者への間欠的自己導尿の指導\ncancer of the uterine cervix","ヒト免疫不全ウイルス〈HIV〉感染者への生活指導\nhuman immunodeficiency virus infection"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":36,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[18],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A036"},"exam":111,"year":2022,"session":"AM","number":36},"sources":[]},{"id":"111-AM-038","record":{"id":"111-AM-038","choice_explanations":[{"choice":1,"correct":true,"title":"仰臥位から側臥位 トルクの原理","explanation":"側臥位への回転では、身体の軸に対して回転させる力を使います。肩や骨盤に働く力による回転を、トルクと結び付けて考えます。"},{"choice":2,"correct":false,"title":"仰臥位から長座位 摩擦力","explanation":"起き上がりには重心移動や支点・力点の工夫が重要です。摩擦力そのものを利用する組合せとしては適切ではありません。"},{"choice":3,"correct":false,"title":"ベッドの片側への水平移動 力のモーメント","explanation":"水平移動では摩擦を減らし、患者を近づけて重心を安定させます。回転の作用を示す力のモーメントとの組合せではありません。"},{"choice":4,"correct":false,"title":"ベッドの頭部への水平移動 てこの第1種の原理","explanation":"頭部への水平移動は、身体全体を寝具上で移す動作です。支点を間に置く第1種のてこを代表する動作ではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"臥床患者の体位変換とボディメカニクスの原則との組合せで正しいのはどれか。","choices":["仰臥位から側臥位 トルクの原理","仰臥位から長座位 摩擦力","ベッドの片側への水平移動 力のモーメント","ベッドの頭部への水平移動 てこの第1種の原理"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":38,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[19],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A038"},"exam":111,"year":2022,"session":"AM","number":38},"sources":[]},{"id":"111-AM-039","record":{"id":"111-AM-039","choice_explanations":[{"choice":1,"correct":false,"title":"履物は A さんの左手側に置く。","explanation":"履物は、立ち上がる位置で足を入れやすく安全に置きます。左利きという理由だけで左手側に置くのではありません。"},{"choice":2,"correct":false,"title":"ベッド柵は A さんの右手側に設置する。","explanation":"右前腕には点滴があり、右側に柵を設けることを一律に適切とはいえません。起き上がる方向と、使える手で安全につかまれる位置を考えます。"},{"choice":3,"correct":false,"title":"輸液スタンドは A さんの左手側に置く。","explanation":"輸液スタンドは点滴側の動線とルートの長さを確認して配置します。左側へ置くと体をまたいでルートが引っ張られる可能性があります。"},{"choice":4,"correct":true,"title":"ベッドは端座位時に A さんの足底が床につく高さにする。","explanation":"端座位で足底が床につく高さなら、座位が安定して立ち上がりやすくなります。術後のふらつきも確認し、安全に移動できるよう援助します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さん(24 歳、男性)は急性虫垂炎の術後1日で、ベッド上で仰臥位になり右前\nacute appendicitis\n腕から点滴静脈内注射が行われている。A さんは左利きである。\n病室外のトイレまで A さんが移動するための適切な療養環境はどれか。","choices":["履物は A さんの左手側に置く。","ベッド柵は A さんの右手側に設置する。","輸液スタンドは A さんの左手側に置く。","ベッドは端座位時に A さんの足底が床につく高さにする。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":39,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[19],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A039"},"exam":111,"year":2022,"session":"AM","number":39},"sources":[]},{"id":"111-AM-040","record":{"id":"111-AM-040","choice_explanations":[{"choice":1,"correct":true,"title":"スポンジブラシは水を含ませた後、絞って使用する。","explanation":"水分が多いまま口に入れると誤嚥につながります。スポンジブラシは余分な水分を絞り、汚れを少しずつ取り除きます。"},{"choice":2,"correct":false,"title":"頸部を後屈した体位で実施する。","explanation":"頸部後屈は液体が咽頭へ流れ込みやすくなります。患者の状態に合わせ、誤嚥を防ぎやすい体位に整えます。"},{"choice":3,"correct":false,"title":"終了後は口腔内を乾燥させる。","explanation":"乾燥は粘膜の傷つきやすさや汚れの付着につながります。汚れと余分な水分を除いた後は、必要に応じて保湿します。"},{"choice":4,"correct":false,"title":"舌苔は強くこすって除去する。","explanation":"舌を強くこすると粘膜を傷つけます。舌苔は無理に一度で取ろうとせず、適切な用具でやさしく清掃します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"全介助が必要な臥床患者の口腔ケアで適切なのはどれか。","choices":["スポンジブラシは水を含ませた後、絞って使用する。","頸部を後屈した体位で実施する。","終了後は口腔内を乾燥させる。","舌苔は強くこすって除去する。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":40,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[19],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A040"},"exam":111,"year":2022,"session":"AM","number":40},"sources":[]},{"id":"111-AM-041","record":{"id":"111-AM-041","choice_explanations":[{"choice":1,"correct":true,"title":"創部の浮腫が起こる。","explanation":"術後早期は炎症期で、血管透過性が高まるため浮腫が生じます。ただし強い増悪や他の異常所見があれば、正常な反応と決めつけません。"},{"choice":2,"correct":false,"title":"肉芽組織が形成される。","explanation":"肉芽組織の形成は、その後の増殖期に進む変化です。術後1日の中心となる反応は炎症や止血です。"},{"choice":3,"correct":false,"title":"コラーゲンが成熟し瘢痕組織となる。","explanation":"コラーゲンの成熟や瘢痕の形成は、さらに後の再構築の過程です。術後1日の所見としては時期が早すぎます。"},{"choice":4,"correct":false,"title":"血管内皮細胞が新しい血管を形成する。","explanation":"新生血管の形成は増殖期の修復に関係します。術後1日の代表的な所見としては、炎症による浮腫を選びます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"術後1日の手術創の正常な治癒過程として正しいのはどれか。","choices":["創部の浮腫が起こる。","肉芽組織が形成される。","コラーゲンが成熟し瘢痕組織となる。","血管内皮細胞が新しい血管を形成する。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":41,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[19],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A041"},"exam":111,"year":2022,"session":"AM","number":41},"sources":[]},{"id":"111-AM-042","record":{"id":"111-AM-042","choice_explanations":[{"choice":1,"correct":false,"title":"喘 息\nasthma","explanation":"喘息は慢性の気道疾患ですが、2017年の患者調査では選択肢中の総患者数が最多ではありません。"},{"choice":2,"correct":false,"title":"糖尿病\ndiabetes mellitus","explanation":"糖尿病の患者数も多いものの、当該調査では高血圧性疾患より少なくなっています。疾患の重要度と人数の順位を混同しません。"},{"choice":3,"correct":false,"title":"脳血管疾患\ncerebrovascular disease","explanation":"脳血管疾患は後遺症や生活への影響が大きい疾患ですが、当該調査で選択肢中の総患者数が最多ではありません。"},{"choice":4,"correct":true,"title":"高血圧性疾患\nhypertensive disease","explanation":"2017年の患者調査では高血圧性疾患がこの中で最多です。総患者数は調査日に受診した人数だけでなく、継続して医療を受ける人を推計した指標です。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"平成 29 年(2017 年)の患者調査において医療機関を受診している総患者数が最も\n多いのはどれか。","choices":["喘 息\nasthma","糖尿病\ndiabetes mellitus","脳血管疾患\ncerebrovascular disease","高血圧性疾患\nhypertensive disease"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":42,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[20],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A042"},"exam":111,"year":2022,"session":"AM","number":42},"sources":[{"title":"厚生労働省：2017年患者調査 総患者数","url":"https://www.mhlw.go.jp/toukei/saikin/hw/kanja/17/dl/05.pdf"}]},{"id":"111-AM-043","record":{"id":"111-AM-043","choice_explanations":[{"choice":1,"correct":false,"title":"黄 疸","explanation":"黄疸はビリルビンの増加に関係し、破裂直後の大量出血を示す典型的な症状ではありません。"},{"choice":2,"correct":false,"title":"浮 腫","explanation":"浮腫は水分の貯留などに関係します。急激な循環血液量の減少を最も直接的に表す選択肢ではありません。"},{"choice":3,"correct":false,"title":"顔面紅潮","explanation":"出血性ショックでは末梢血管が収縮して皮膚が冷たく蒼白になりやすく、顔面紅潮は典型的ではありません。"},{"choice":4,"correct":true,"title":"呼吸不全","explanation":"不明：公式正答は呼吸不全です。ただし、大量出血による酸素供給不足だけで、破裂直後の呼吸不全まで説明できるとは限りません。この発症時点を含む正答理由は確認できていません。"}],"status":"UNKNOWN","review_reason":"破裂直後の呼吸不全と循環性の酸素供給不足を同一視できず、正答理由が未確定。","fixes_made":[]},"input_anchor":{"question":"解離性大動脈瘤の破裂直後に出血性ショックとなった患者の症状として正しいの\ndissecting aortic aneurysm hemorrhagic shock\nはどれか。","choices":["黄 疸","浮 腫","顔面紅潮","呼吸不全"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":43,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[20],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A043"},"exam":111,"year":2022,"session":"AM","number":43},"sources":[]},{"id":"111-AM-044","record":{"id":"111-AM-044","choice_explanations":[{"choice":1,"correct":false,"title":"海 藻","explanation":"海藻を一律に禁止する選択肢ではありません。ただし食品によって栄養成分は異なるため、極端な食事変更を避けて個別の指導に従います。"},{"choice":2,"correct":false,"title":"牛 乳","explanation":"牛乳は本問で特に避ける食品には該当しません。薬の相互作用は薬剤ごとに異なり、すべての薬で同じ食事制限を行うわけではありません。"},{"choice":3,"correct":true,"title":"納 豆","explanation":"納豆のビタミンKや納豆菌によるビタミンK産生は、ワルファリンの抗凝固作用を弱めます。服用時間とずらすだけで避けられる相互作用ではありません。"},{"choice":4,"correct":false,"title":"グレープフルーツ","explanation":"グレープフルーツは一部の薬の代謝に影響しますが、ワルファリン服用時に本問で優先して避ける食品は納豆です。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さん(60 歳、男性)は大動脈弁置換術を受け、ワルファリンの内服を開始する\nことになった。\nA さんが摂取を避けるべき食品はどれか。","choices":["海 藻","牛 乳","納 豆","グレープフルーツ"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":44,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[20],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A044"},"exam":111,"year":2022,"session":"AM","number":44},"sources":[{"title":"PMDA：ワルファリンと納豆","url":"https://www.pmda.go.jp/safety/consultation-for-patients/on-drugs/qa/0016.html"}]},{"id":"111-AM-045","record":{"id":"111-AM-045","choice_explanations":[{"choice":1,"correct":false,"title":"蛋白質","explanation":"蛋白質を一律に制限するのではなく、栄養状態に応じて必要量を確保します。消化吸収障害による低栄養にも注意します。"},{"choice":2,"correct":false,"title":"カリウム","explanation":"腎機能障害など別の条件がなければ、慢性膵炎というだけでカリウム制限を行うわけではありません。"},{"choice":3,"correct":false,"title":"食物繊維","explanation":"食物繊維を一律に制限することが本問の基本方針ではありません。症状や食事摂取状況に合わせて調整します。"},{"choice":4,"correct":true,"title":"アルコール","explanation":"アルコールは膵障害の進行や再燃に関係するため、禁酒が重要です。栄養管理とともに、飲酒習慣への支援を行います。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"慢性膵炎患者の食事療法で制限が必要なのはどれか。\nchronic pancreatitis","choices":["蛋白質","カリウム","食物繊維","アルコール"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":45,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[21],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A045"},"exam":111,"year":2022,"session":"AM","number":45},"sources":[]},{"id":"111-AM-046","record":{"id":"111-AM-046","choice_explanations":[{"choice":1,"correct":true,"title":"グルカゴン","explanation":"グルカゴンは血糖調節に関係し、食事による血糖やアミノ酸の変化の影響を受けます。採血時の食事条件をそろえる必要があります。"},{"choice":2,"correct":false,"title":"メラトニン","explanation":"メラトニンは主に明暗や睡眠・覚醒のリズムと関係します。本問で食事の影響を特に考えるホルモンではありません。"},{"choice":3,"correct":false,"title":"コルチゾール","explanation":"コルチゾールでは日内変動やストレスの影響が重要です。食事条件との関連を問う本問ではグルカゴンが最も適切です。"},{"choice":4,"correct":false,"title":"バゾプレシン","explanation":"バゾプレシンは浸透圧や循環血液量に応じて水分の保持を調節します。食事に伴う血糖変動を中心に考えるホルモンとは異なります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"血中濃度の測定にあたり食事の影響を考慮すべきホルモンはどれか。","choices":["グルカゴン","メラトニン","コルチゾール","バゾプレシン"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":46,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[21],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A046"},"exam":111,"year":2022,"session":"AM","number":46},"sources":[]},{"id":"111-AM-047","record":{"id":"111-AM-047","choice_explanations":[{"choice":1,"correct":false,"title":"前日に頭部の剃毛を行う。","explanation":"血管からカテーテルを入れる検査であり、頭部の剃毛を一律に行う必要はありません。必要な準備は穿刺部位と検査方法に合わせます。"},{"choice":2,"correct":false,"title":"検査中は患者に話しかけない。","explanation":"意識や言語などの変化を確認するため、必要に応じて患者に声をかけます。会話を避けることが安全につながるわけではありません。"},{"choice":3,"correct":true,"title":"穿刺部末梢側の動脈の拍動を確認する。","explanation":"穿刺部より末梢の動脈拍動を確認し、血流障害がないか観察します。検査前後の比較に加え、皮膚色・冷感・痛みなども確認します。"},{"choice":4,"correct":false,"title":"検査 30 分前まで食事摂取が可能である。","explanation":"検査直前まで食事を取れると一律に説明するのは不適切です。造影剤使用や処置に備え、指定された絶食時間に従います。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"脳血管造影を行う患者の看護について適切なのはどれか。","choices":["前日に頭部の剃毛を行う。","検査中は患者に話しかけない。","穿刺部末梢側の動脈の拍動を確認する。","検査 30 分前まで食事摂取が可能である。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":47,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[21],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A047"},"exam":111,"year":2022,"session":"AM","number":47},"sources":[]},{"id":"111-AM-048","record":{"id":"111-AM-048","choice_explanations":[{"choice":1,"correct":false,"title":"咽頭にたまった分泌物は飲み込んでも良い。","explanation":"血液を含む分泌物を飲み込むと出血量が分かりにくくなり、吐き気の原因にもなります。分泌物の状態を確認できるようにします。"},{"choice":2,"correct":true,"title":"物が二重に見えるときは看護師に伝える。","explanation":"副鼻腔は眼窩に近く、術後の複視は眼の周囲の合併症を考える徴候です。二重に見えるなどの変化は速やかに報告してもらいます。"},{"choice":3,"correct":false,"title":"手術当日から入浴が可能である。","explanation":"術当日の入浴は出血などのリスクを考慮する必要があり、一律に可能とは説明しません。術後の状態と医師の指示に合わせます。"},{"choice":4,"correct":false,"title":"臥床時は頭部を低く保つ。","explanation":"頭部を低くすると出血や腫脹を助長するおそれがあります。通常は頭部を適度に高くし、安楽と観察ができる姿勢にします。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さん(32 歳、男性)は慢性副鼻腔炎と診断され経過観察をしていたが、症状が\n改善せず手術を受けることになった。\nA さんへの術後の生活についての説明で適切なのはどれか。","choices":["咽頭にたまった分泌物は飲み込んでも良い。","物が二重に見えるときは看護師に伝える。","手術当日から入浴が可能である。","臥床時は頭部を低く保つ。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":48,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[21],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A048"},"exam":111,"year":2022,"session":"AM","number":48},"sources":[]},{"id":"111-AM-049","record":{"id":"111-AM-049","choice_explanations":[{"choice":1,"correct":false,"title":"術前から発症する。","explanation":"幻肢痛は切断で失われた部位に感じる痛みです。切断前にその部位にあった痛みとは区別します。"},{"choice":2,"correct":false,"title":"抗うつ薬は禁忌である。","explanation":"抗うつ薬が痛みの治療に用いられることがあります。薬の名前から精神症状にしか使わないと考えず、禁忌と断定しません。"},{"choice":3,"correct":false,"title":"細菌感染が原因である。","explanation":"切断部の感染による痛みとは別です。存在しない部位に痛みを感じる、神経系の変化に関係した痛みとして理解します。"},{"choice":4,"correct":true,"title":"切断し喪失した部位に生じる。","explanation":"失われた手足などが今もあるように感じ、その部分に痛みが生じます。実際のつらい体験であり、気のせいとして扱わず評価します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"幻肢痛について正しいのはどれか。","choices":["術前から発症する。","抗うつ薬は禁忌である。","細菌感染が原因である。","切断し喪失した部位に生じる。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":49,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[22],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A049"},"exam":111,"year":2022,"session":"AM","number":49},"sources":[{"title":"厚生労働科学研究：幻肢痛の治療","url":"https://mhlw-grants.niph.go.jp/system/files/2011/113041/201118011B/201118011B0075.pdf"}]},{"id":"111-AM-050","record":{"id":"111-AM-050","choice_explanations":[{"choice":1,"correct":false,"title":"｢検査当日は起床時から飲食をしないでください｣","explanation":"乳房超音波検査は、通常は食事制限を必要としません。腹部など別の部位の超音波検査の準備と混同しません。"},{"choice":2,"correct":false,"title":"｢乳房を器具で挟んで検査します｣","explanation":"乳房を板で挟んで圧迫するのはマンモグラフィの特徴です。超音波検査では探触子を皮膚に当てて観察します。"},{"choice":3,"correct":false,"title":"｢月経中は検査ができません｣","explanation":"月経中であることを理由に一律に検査できなくなるわけではありません。痛みなどは伝えてもらい、楽な状態で受けられるようにします。"},{"choice":4,"correct":true,"title":"｢仰向けで検査を行います｣","explanation":"通常は仰向けになり、必要に応じて腕や体の向きを調整します。乳房にゼリーを塗り、探触子を動かして内部を観察します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"乳房超音波検査を受ける女性患者への説明で正しいのはどれか。","choices":["｢検査当日は起床時から飲食をしないでください｣","｢乳房を器具で挟んで検査します｣","｢月経中は検査ができません｣","｢仰向けで検査を行います｣"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":50,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[22],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A050"},"exam":111,"year":2022,"session":"AM","number":50},"sources":[]},{"id":"111-AM-051","record":{"id":"111-AM-051","choice_explanations":[{"choice":1,"correct":true,"title":"｢治療前1週間は海藻類を摂取しないでください｣","explanation":"食品からのヨウ素が多いと、治療用の放射性ヨウ素が甲状腺へ取り込まれにくくなります。本問では治療前1週間の海藻制限が正答で、実際の期間は施設の指示に従います。"},{"choice":2,"correct":false,"title":"｢治療中は体を固定します｣","explanation":"放射性ヨウ素を内服して甲状腺に集積させる治療です。外から照射する治療のように、照射位置に合わせて身体を固定する方法ではありません。"},{"choice":3,"correct":false,"title":"｢治療後の副作用に脱毛があります｣","explanation":"脱毛は本治療の代表的な副作用として説明する内容ではありません。抗がん薬治療などの副作用と一括りにしないようにします。"},{"choice":4,"correct":false,"title":"｢治療後1週間は生野菜を摂取しないでください｣","explanation":"生野菜を一律に制限する根拠はありません。ヨウ素を多く含む食品への制限と、感染予防目的の食事制限は別のものです。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さん(54 歳、女性)は甲状腺機能亢進症と診断され、放射性ヨウ素内用療法を\nhyperthyroidism\n受けることとなった。\n看護師の説明で正しいのはどれか。","choices":["｢治療前1週間は海藻類を摂取しないでください｣","｢治療中は体を固定します｣","｢治療後の副作用に脱毛があります｣","｢治療後1週間は生野菜を摂取しないでください｣"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":51,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[22],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A051"},"exam":111,"year":2022,"session":"AM","number":51},"sources":[{"title":"日本核医学会：2018年放射性ヨウ素内用療法ガイドライン","url":"https://oncology.jsnm.org/sites/default/files/pdf/thyroid-guideline_2018-06.pdf"}]},{"id":"111-AM-052","record":{"id":"111-AM-052","choice_explanations":[{"choice":1,"correct":false,"title":"エリクソン\nErikson, E. H.","explanation":"エリクソンは老年期の課題を自我の統合と絶望として示しました。設問の3つの危機を挙げた人物ではありません。"},{"choice":2,"correct":false,"title":"レビンソン\nRevinson, D. J.","explanation":"レビンソンは成人の生活構造や人生の移行期に着目しました。設問の老年期の3つの危機とは異なります。"},{"choice":3,"correct":true,"title":"ペック\nPeck, R.","explanation":"ペックは職業役割へのとらわれ、身体へのとらわれ、自我へのとらわれを越える課題を示しました。引退・健康・死への適応と対応させます。"},{"choice":4,"correct":false,"title":"ユング\nJung, C. G.","explanation":"ユングは人生後半の内面的な発達などに着目しました。設問の3段階を示した理論家としてはペックを選びます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"老年期の発達課題を引退の危機、身体的健康の危機および死の危機の3つの段階\nで示したのはどれか。","choices":["エリクソン\nErikson, E. H.","レビンソン\nRevinson, D. J.","ペック\nPeck, R.","ユング\nJung, C. G."],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":52,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[22],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A052"},"exam":111,"year":2022,"session":"AM","number":52},"sources":[]},{"id":"111-AM-053","record":{"id":"111-AM-053","choice_explanations":[{"choice":1,"correct":true,"title":"介護医療院サービス","explanation":"介護医療院は長期的な医療と介護の必要に対応し、生活の場も提供する施設です。介護保険の施設サービスに位置付けられます。"},{"choice":2,"correct":false,"title":"小規模多機能型居宅介護","explanation":"通い・訪問・宿泊を組み合わせる地域密着型サービスです。宿泊を含んでいても、制度上の施設サービスとは別です。"},{"choice":3,"correct":false,"title":"サービス付き高齢者向け住宅","explanation":"高齢者向けの住まいであり、住宅そのものを介護保険の施設サービスとは呼びません。必要な介護サービスは契約や指定の状況に応じて利用します。"},{"choice":4,"correct":false,"title":"認知症対応型共同生活介護〈認知症高齢者グループホーム〉","explanation":"認知症の人が共同生活を送る地域密着型サービスです。建物に入居することと、介護保険上の施設サービスの分類は同じではありません。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"介護保険制度における施設サービスはどれか。","choices":["介護医療院サービス","小規模多機能型居宅介護","サービス付き高齢者向け住宅","認知症対応型共同生活介護〈認知症高齢者グループホーム〉"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":53,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[23],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A053"},"exam":111,"year":2022,"session":"AM","number":53},"sources":[{"title":"厚生労働省：介護サービスの分類","url":"https://www.kaigokensaku.mhlw.go.jp/commentary/service.html"}]},{"id":"111-AM-054","record":{"id":"111-AM-054","choice_explanations":[{"choice":1,"correct":false,"title":"基礎代謝率","explanation":"基礎代謝率も加齢で低下しますが、選択肢中で残存率が最も低くなる機能ではありません。身体機能はすべて同じ割合で低下するわけではありません。"},{"choice":2,"correct":true,"title":"最大換気量","explanation":"呼吸筋や胸郭の動きなどの変化により、最大限に換気する能力は大きく低下します。安静時の状態だけでなく、負荷に対応する予備力の低下として理解します。"},{"choice":3,"correct":false,"title":"細胞内水分量","explanation":"細胞内水分量は加齢で減少しますが、本問で示される機能の比較では最大換気量の低下がより大きくなります。"},{"choice":4,"correct":false,"title":"神経伝導速度","explanation":"神経伝導速度も低下しますが、最大換気量ほど大きな低下を示す指標ではありません。加齢変化には機能ごとの差があります。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"30 歳を 100 % とした生理機能と比較して、老年期において機能の残存率の平均\n値が最も低下するのは次のうちどれか。","choices":["基礎代謝率","最大換気量","細胞内水分量","神経伝導速度"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":54,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[23],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A054"},"exam":111,"year":2022,"session":"AM","number":54},"sources":[{"title":"厚生労働統計協会：加齢と最大換気量","url":"https://www.hws-kyokai.or.jp/publishing/eiesei-kangoshiken-main/eiesei-kangoshiken-105-pm1.html"}]},{"id":"111-AM-055","record":{"id":"111-AM-055","choice_explanations":[{"choice":1,"correct":false,"title":"症状の出現は定型である。","explanation":"高齢者では典型的な症状がはっきり出ないことがあります。発熱や痛みが目立たなくても、食欲や活動性の変化を手掛かりにします。"},{"choice":2,"correct":false,"title":"治療の効果が現れやすい。","explanation":"予備力の低下や複数疾患の影響があり、治療効果が一律に現れやすいとはいえません。効果と負担を個別に評価します。"},{"choice":3,"correct":false,"title":"疾患の発生に心理的要因の影響は少ない。","explanation":"喪失体験や孤立などの心理社会的要因も健康に影響します。身体面だけで判断しないことが大切です。"},{"choice":4,"correct":true,"title":"薬物の副作用〈有害事象〉が発生しやすい。","explanation":"薬物の代謝・排泄の変化や多剤使用により、有害事象が起こりやすくなります。薬の効果だけでなく、ふらつきや食欲低下などの変化も観察します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"高齢者の健康障害の特徴で正しいのはどれか。","choices":["症状の出現は定型である。","治療の効果が現れやすい。","疾患の発生に心理的要因の影響は少ない。","薬物の副作用〈有害事象〉が発生しやすい。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":55,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[23],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A055"},"exam":111,"year":2022,"session":"AM","number":55},"sources":[]},{"id":"111-AM-056","record":{"id":"111-AM-056","choice_explanations":[{"choice":1,"correct":true,"title":"嵌入便","explanation":"硬い便が直腸などにたまり、その周囲を液状の便が漏れ出すことがあります。少量の水様便が出ても便塊が排出されたとは限らず、残便感に注目します。"},{"choice":2,"correct":false,"title":"器質性便秘","explanation":"腫瘍や狭窄など器質的な原因を示す情報はありません。まず、排便がない後に水様便だけが漏れたという経過から嵌入便を考えます。"},{"choice":3,"correct":false,"title":"切迫性便失禁","explanation":"便意を感じても間に合わず漏れる状態です。本問では排便が滞った後の少量の水様便と残便感が、便塊の残存を示唆します。"},{"choice":4,"correct":false,"title":"非急性感染性下痢","explanation":"感染性下痢を示す情報はなく、便秘後に下剤を使った経過があります。水様便の見た目だけで下痢の原因を決めません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さん(83 歳)は寝たきり状態で、便意を訴えるが3日間排便がみられない。認\n知機能に問題はない。昨晩下剤を内服したところ、今朝、紙オムツに水様便が少量\n付着しており、残便感を訴えている。\nこのときの A さんの状態で考えられるのはどれか。","choices":["嵌入便","器質性便秘","切迫性便失禁","非急性感染性下痢"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":56,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[24],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A056"},"exam":111,"year":2022,"session":"AM","number":56},"sources":[]},{"id":"111-AM-057","record":{"id":"111-AM-057","choice_explanations":[{"choice":1,"correct":false,"title":"｢通常の反応です｣","explanation":"接種翌日から増悪する強い局所反応は、通常の時期より早い反応です。一般的な経過として経過観察だけを勧めるのは適切ではありません。"},{"choice":2,"correct":true,"title":"｢速やかに来院してください｣","explanation":"接種後早期の発赤・腫脹・化膿はコッホ現象などの確認が必要です。これだけで結核と断定はできませんが、速やかな受診につなげます。"},{"choice":3,"correct":false,"title":"｢1週間後にまた電話をください｣","explanation":"全身状態が良くても、早期に強い局所反応が出ているため確認が必要です。さらに1週間待つ案内は適切ではありません。"},{"choice":4,"correct":false,"title":"｢患部をアルコール消毒してください｣","explanation":"自己判断で消毒を追加するより、まず反応を診察で確認します。通常も接種部位は清潔に保ち、薬剤をむやみに塗らないようにします。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"発育と発達に遅れのない生後6か月の男児。BCG 接種の翌日に接種部位が赤く\n腫れ次第に増悪して膿がみられたため、母親は接種後4日目に医療機関に電話で相\n談し、看護師が対応した。児に発熱はなく、哺乳や機嫌は良好である。\nこのときの看護師の説明で適切なのはどれか。","choices":["｢通常の反応です｣","｢速やかに来院してください｣","｢1週間後にまた電話をください｣","｢患部をアルコール消毒してください｣"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":57,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[24],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A057"},"exam":111,"year":2022,"session":"AM","number":57},"sources":[{"title":"厚生労働省：BCG接種後のコッホ現象","url":"https://www.mhlw.go.jp/stf/seisakunitsuite/bunya/kenkou_iryou/kenkou/kekkaku-kansenshou/yobou-sesshu/vaccine/bcg/index.html"}]},{"id":"111-AM-058","record":{"id":"111-AM-058","choice_explanations":[{"choice":1,"correct":false,"title":"生後 48 時間以内には発症しない。","explanation":"ビタミンK欠乏による出血は出生後早期にも起こり得ます。48時間以内なら発症しないという断定はできません。"},{"choice":2,"correct":true,"title":"母乳栄養児は発症のリスクが高い。","explanation":"母乳中のビタミンKは少なく、新生児では蓄えや腸内細菌による供給も十分ではありません。母乳栄養児はリスクがあり、予防投与が重要です。"},{"choice":3,"correct":false,"title":"予防としてカルシウムを内服する。","explanation":"予防に用いるのはビタミンKです。凝固にカルシウムも関与しますが、この出血性疾患の予防薬とは異なります。"},{"choice":4,"correct":false,"title":"早期に現われる所見に蕁麻疹がある。\nurticaria","explanation":"蕁麻疹はアレルギーなどでみられる皮疹です。ビタミンK欠乏による出血の代表的な初期所見ではありません。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"新生児の出血性疾患で正しいのはどれか。","choices":["生後 48 時間以内には発症しない。","母乳栄養児は発症のリスクが高い。","予防としてカルシウムを内服する。","早期に現われる所見に蕁麻疹がある。\nurticaria"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":58,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[24],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A058"},"exam":111,"year":2022,"session":"AM","number":58},"sources":[{"title":"日本小児科学会：ビタミンK欠乏性出血症の予防","url":"https://www.jpeds.or.jp/society-activities/20398.html"}]},{"id":"111-AM-059","record":{"id":"111-AM-059","choice_explanations":[{"choice":1,"correct":false,"title":"見慣れない環境 新生児期","explanation":"新生児も刺激の影響を受けますが、見慣れた環境との違いに対する不安を主な特徴として捉える段階ではありません。"},{"choice":2,"correct":false,"title":"プライバシーの侵害 幼児期","explanation":"幼児でもプライバシーへの配慮は必要ですが、自意識や身体像との関係で特に問題となりやすいのは思春期です。"},{"choice":3,"correct":true,"title":"病気の予後への不安 学童期","explanation":"学童期は病気や治療について理解が進み、今後の生活や治るかどうかを心配するようになります。理解度に合った説明で不安を確かめます。"},{"choice":4,"correct":false,"title":"母子分離 思春期","explanation":"母子分離への不安は、特に乳幼児期で大きな問題となります。思春期は自立や仲間との関係、プライバシーへの配慮が重要です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"入院中の小児のストレス因子と発達段階の組合せで正しいのはどれか。","choices":["見慣れない環境 新生児期","プライバシーの侵害 幼児期","病気の予後への不安 学童期","母子分離 思春期"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":59,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[25],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A059"},"exam":111,"year":2022,"session":"AM","number":59},"sources":[]},{"id":"111-AM-060","record":{"id":"111-AM-060","choice_explanations":[{"choice":1,"correct":false,"title":"両親に判断してもらおうと話す。","explanation":"両親との相談は必要ですが、意識が清明な本人の希望を置き去りにして判断を委ねる対応ではありません。本人も意思決定に参加できるようにします。"},{"choice":2,"correct":false,"title":"今の状態では出席は難しいと話す。","explanation":"呼吸障害があっても、支援や参加方法を検討せずに不可能と決めるのは早計です。負担を減らして希望を実現する方法を考えます。"},{"choice":3,"correct":true,"title":"出席できるように準備しようと話す。","explanation":"本人にとって大切な卒業式への希望を受け止め、酸素や移動、休息などの支援をチームで調整します。状態に応じて参加方法を柔軟に考えます。"},{"choice":4,"correct":false,"title":"出席を決める前に体力をつけようと話す。","explanation":"終末期の本人に体力向上を参加の条件として求めると、負担や失望につながります。現在の力で実現できる方法を一緒に探します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A 君(小学6年生)は病院に併設された院内学級に通いながら骨肉腫の治療を続\nosteosarcoma\nけていた。現在、肺転移があり終末期にある。呼吸障害のため鼻腔カニューレで酸\n素(2L/分)を吸入中である。A 君の食事摂取量は減っているが意識は清明である。\n1週後に院内で卒業式が予定されている。A 君は｢卒業式に出席したい｣と話して\nいる。\n看護師の A 君への対応として適切なのはどれか。","choices":["両親に判断してもらおうと話す。","今の状態では出席は難しいと話す。","出席できるように準備しようと話す。","出席を決める前に体力をつけようと話す。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":60,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[25],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A060"},"exam":111,"year":2022,"session":"AM","number":60},"sources":[]},{"id":"111-AM-061","record":{"id":"111-AM-061","choice_explanations":[{"choice":1,"correct":false,"title":"生物学的な性","explanation":"生物学的な身体の性を指す概念はセックスです。社会の中で期待される役割や行動というジェンダーとは区別します。"},{"choice":2,"correct":true,"title":"社会的文化的な性","explanation":"ジェンダーは、社会や文化の中で形づくられた性別に関する役割や意味を指します。身体的な特徴だけで決まるものではありません。"},{"choice":3,"correct":false,"title":"自己認識している性","explanation":"自分の性をどのように認識しているかは性自認です。ジェンダーと関連しますが、本問の定義そのものではありません。"},{"choice":4,"correct":false,"title":"性的指向の対象となる性","explanation":"誰に恋愛感情や性的な関心が向くかは性的指向に関する概念です。社会的・文化的な性とは区別します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"ジェンダーの定義について正しいのはどれか。","choices":["生物学的な性","社会的文化的な性","自己認識している性","性的指向の対象となる性"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":61,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[25],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A061"},"exam":111,"year":2022,"session":"AM","number":61},"sources":[]},{"id":"111-AM-062","record":{"id":"111-AM-062","choice_explanations":[{"choice":1,"correct":false,"title":"新生児死亡は生後1週未満の死亡をいう。","explanation":"生後1週未満の死亡は早期新生児死亡です。新生児死亡全体は生後4週未満を指し、期間が異なります。"},{"choice":2,"correct":true,"title":"死産は妊娠満 12 週以後の死児の出産をいう。","explanation":"日本の死産統計では、妊娠満12週以後の死児の出産を死産とします。周産期死亡に用いる妊娠週数の区切りとは区別します。"},{"choice":3,"correct":false,"title":"妊産婦死亡は妊娠中又は妊娠終了後満 28 日未満の女性の死亡をいう。","explanation":"妊産婦死亡は妊娠中または妊娠終了後42日未満の、妊娠等に関連した死亡を扱います。28日未満という期間も、原因を問わない説明も適切ではありません。"},{"choice":4,"correct":false,"title":"令和元年(2019 年)の人口動態統計では自然死産数が人工死産数よりも多い。","explanation":"2019年の人口動態統計では人工死産数が自然死産数を上回っています。自然・人工の区分と、比較する年を確認します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"日本の周産期の死亡に関する記述で正しいのはどれか。","choices":["新生児死亡は生後1週未満の死亡をいう。","死産は妊娠満 12 週以後の死児の出産をいう。","妊産婦死亡は妊娠中又は妊娠終了後満 28 日未満の女性の死亡をいう。","令和元年(2019 年)の人口動態統計では自然死産数が人工死産数よりも多い。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":62,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[26],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A062"},"exam":111,"year":2022,"session":"AM","number":62},"sources":[{"title":"厚生労働省：人口動態調査の定義","url":"https://www.mhlw.go.jp/toukei/list/81-1b.html"},{"title":"厚生労働省：2019年人口動態総覧","url":"https://www.mhlw.go.jp/toukei/saikin/hw/jinkou/kakutei19/dl/03_h1.pdf"}]},{"id":"111-AM-063","record":{"id":"111-AM-063","choice_explanations":[{"choice":1,"correct":true,"title":"経口避妊薬は排卵を抑制する。","explanation":"経口避妊薬はホルモンの働きにより排卵を抑えるなどして避妊します。飲み忘れや相互作用などで効果が変わるため、正しい使用が必要です。"},{"choice":2,"correct":false,"title":"コンドーム法の避妊効果は 99 % 以上である。","explanation":"コンドームは使い方や破損・脱落の影響を受け、一般的な使用で99％以上の避妊効果が保証されるわけではありません。"},{"choice":3,"correct":false,"title":"基礎体温法は月経が不順な女性に有用である。","explanation":"月経が不順だと排卵時期を予測しにくくなります。基礎体温だけを頼りに安全な日を判断することは適切ではありません。"},{"choice":4,"correct":false,"title":"子宮内避妊器具〈IUD〉は性交のたびに挿入が必要である。","explanation":"IUDは医療機関で子宮内へ挿入し、一定期間留置します。性交のたびに自分で出し入れする器具ではありません。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"避妊法について適切なのはどれか。","choices":["経口避妊薬は排卵を抑制する。","コンドーム法の避妊効果は 99 % 以上である。","基礎体温法は月経が不順な女性に有用である。","子宮内避妊器具〈IUD〉は性交のたびに挿入が必要である。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":63,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[26],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A063"},"exam":111,"year":2022,"session":"AM","number":63},"sources":[{"title":"日本産婦人科医会：経口避妊薬の作用","url":"https://www.jaog.or.jp/sep2012/JAPANESE/jigyo/JYOSEI/PILL/doctor/section_1.htm"}]},{"id":"111-AM-064","record":{"id":"111-AM-064","choice_explanations":[{"choice":1,"correct":false,"title":"意欲低下が主症状である。","explanation":"一過性の涙もろさや不安、気分の変動などが特徴です。持続する意欲低下が目立つ場合は、産後うつなども考えて評価します。"},{"choice":2,"correct":false,"title":"症状は2週間以上持続する。","explanation":"通常は短期間で軽快します。2週間以上続く場合はマタニティブルーズと決めつけず、他の状態を含めて確認します。"},{"choice":3,"correct":false,"title":"好発時期は産後1か月ころである。","explanation":"典型的には出産後早期にみられ、産後1か月を好発時期とする説明は適切ではありません。発症時期と持続期間に注目します。"},{"choice":4,"correct":true,"title":"産後のホルモンの変動が要因となる。","explanation":"出産に伴う急激なホルモン変化に、疲労や生活環境の変化などが重なって起こると考えられます。本人を責めず休息と支援を整えます。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"マタニティブルーズについて正しいのはどれか。\nmaternity blues","choices":["意欲低下が主症状である。","症状は2週間以上持続する。","好発時期は産後1か月ころである。","産後のホルモンの変動が要因となる。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":64,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[26],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A064"},"exam":111,"year":2022,"session":"AM","number":64},"sources":[{"title":"厚生労働省：マタニティブルーズと産後うつ","url":"https://www.bosei-navi.mhlw.go.jp/health/depression.html"}]},{"id":"111-AM-065","record":{"id":"111-AM-065","choice_explanations":[{"choice":1,"correct":false,"title":"職場でうつ病患者を早期発見する。\ndepression","explanation":"病気を早く見つけて治療につなげる取り組みは二次予防です。発症する前の健康増進や予防とは区別します。"},{"choice":2,"correct":false,"title":"自殺企図者に精神科医療機関への受療を促す。","explanation":"すでに生じた危機に対して受療につなげる対応です。重要な支援ですが、発症前の集団に働きかける一次予防ではありません。"},{"choice":3,"correct":false,"title":"統合失調症患者の社会参加のための支援を行う。\nschizophrenia","explanation":"病気を持つ人の生活機能や社会参加を支える取り組みは三次予防に当たります。再発予防やリハビリテーションと関連します。"},{"choice":4,"correct":true,"title":"ストレスとその対処法に関する知識の啓発活動を行う。","explanation":"ストレスについて知り、適切に対処できるよう支援することで、心の不調を予防します。発症前から健康を守る一次予防の取り組みです。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"精神保健における一次予防はどれか。","choices":["職場でうつ病患者を早期発見する。\ndepression","自殺企図者に精神科医療機関への受療を促す。","統合失調症患者の社会参加のための支援を行う。\nschizophrenia","ストレスとその対処法に関する知識の啓発活動を行う。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":65,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[26],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A065"},"exam":111,"year":2022,"session":"AM","number":65},"sources":[]},{"id":"111-AM-066","record":{"id":"111-AM-066","choice_explanations":[{"choice":1,"correct":true,"title":"物事の捉え方のゆがみが修正される。","explanation":"自動的に浮かぶ考えと感情・行動の関係を整理し、偏った捉え方を柔軟にします。根拠を確かめたり別の見方を試したりすることが特徴です。"},{"choice":2,"correct":false,"title":"自ら催眠状態に導くことができるようになる。","explanation":"自分を催眠状態に導くことは、認知行動療法の中心的な目標ではありません。考え方と行動のパターンを扱う点が本問の焦点です。"},{"choice":3,"correct":false,"title":"過去の自分の態度についての自己洞察が深まる。","explanation":"過去の態度について内省する方法はありますが、認知行動療法の代表的な効果としては現在の捉え方や行動の修正を選びます。"},{"choice":4,"correct":false,"title":"自分の状態をあるがままに受け入れることができるようになる。","explanation":"受容を扱う療法もありますが、設問で期待される代表的な効果は物事の捉え方の修正です。療法ごとの中心的な働きかけを区別します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"認知行動療法で患者に期待できる効果はどれか。","choices":["物事の捉え方のゆがみが修正される。","自ら催眠状態に導くことができるようになる。","過去の自分の態度についての自己洞察が深まる。","自分の状態をあるがままに受け入れることができるようになる。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":66,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[27],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A066"},"exam":111,"year":2022,"session":"AM","number":66},"sources":[]},{"id":"111-AM-067","record":{"id":"111-AM-067","choice_explanations":[{"choice":1,"correct":false,"title":"行動援護","explanation":"行動に著しい困難がある人への外出等の支援です。一般企業への就職を目標に準備する支援として最も合うサービスではありません。"},{"choice":2,"correct":true,"title":"就労移行支援","explanation":"一般就労を希望する人に、働くための訓練や求職活動などの支援を行います。Aさんの就職希望に直接つながるサービスです。"},{"choice":3,"correct":false,"title":"自立生活援助","explanation":"地域での一人暮らしなどを支える、定期的な訪問や相談が中心です。一般企業への就職準備を主目的とするサービスではありません。"},{"choice":4,"correct":false,"title":"地域定着支援","explanation":"地域で暮らす人の緊急時の連絡・相談などを支えます。就職に向けた技能や求職活動の支援とは異なります。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さん(22 歳、統合失調症)は父親、母親、妹との4人暮らし。高校卒業後、ア\nschizophrenia\nルバイトをしていたが、症状の悪化によって初めて精神科病院に入院した。退院後\nに一般企業で働きたいと希望している。\n看護師が A さんに提案するサービスで適切なのはどれか。","choices":["行動援護","就労移行支援","自立生活援助","地域定着支援"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":67,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[27],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A067"},"exam":111,"year":2022,"session":"AM","number":67},"sources":[{"title":"厚生労働省：就労移行支援","url":"https://www.mhlw.go.jp/bunya/shougaihoken/shingikai01/pdf/5-2.pdf"}]},{"id":"111-AM-068","record":{"id":"111-AM-068","choice_explanations":[{"choice":1,"correct":false,"title":"｢A さんの介護用ベッドはリビングに置きましょう｣","explanation":"本人の希望、プライバシー、移動のしやすさなどを確認して部屋を決めます。複数の部屋があるため、最初からリビングに限定しません。"},{"choice":2,"correct":false,"title":"｢A さんの介護に家族の生活リズムを合わせましょう｣","explanation":"家族にも仕事や学業があり、介護だけに生活を合わせると負担が増します。本人と家族双方が続けられる生活を考えます。"},{"choice":3,"correct":false,"title":"｢活用できる在宅サービスをできる限り多く利用しましょう｣","explanation":"利用可能なものを多く入れるのではなく、本人の必要と希望、家族の状況に合うサービスを選びます。"},{"choice":4,"correct":true,"title":"｢特定の同居家族に介護負担が集中しないように家族で話し合いましょう｣","explanation":"役割を話し合い、特定の人に負担が偏らないようにします。家族だけで抱えず、必要な外部サービスと組み合わせることも大切です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さん(80 歳、女性)は1人暮らし。要介護2の認定を受け、長男(50 歳、会社\n員)、長男の妻(45 歳、会社員)、孫(大学生、男性)と同居することになった。長男\nの家の間取りは、洋室5部屋、リビング、台所である。A さんは同居後に訪問看\n護を利用する予定である。訪問看護を利用するにあたり A さんの家族から｢在宅介\n護は初めての経験なのでどうすればよいですか｣と訪問看護師に相談があった。\n訪問看護師の説明で最も適切なのはどれか。","choices":["｢A さんの介護用ベッドはリビングに置きましょう｣","｢A さんの介護に家族の生活リズムを合わせましょう｣","｢活用できる在宅サービスをできる限り多く利用しましょう｣","｢特定の同居家族に介護負担が集中しないように家族で話し合いましょう｣"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":68,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[27],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A068"},"exam":111,"year":2022,"session":"AM","number":68},"sources":[]},{"id":"111-AM-069","record":{"id":"111-AM-069","choice_explanations":[{"choice":1,"correct":false,"title":"入浴はシャワー浴にしている。","explanation":"シャワー浴は、湯につかる際の水圧などによる負担を減らす方法になり得ます。設問で最も直接的に問題となる行動ではありません。"},{"choice":2,"correct":false,"title":"椅子に座って更衣を行っている。","explanation":"座って更衣すると、立位での動作に比べ負担を減らせます。息切れを軽くする工夫として適切です。"},{"choice":3,"correct":true,"title":"洗髪時に鼻カニューレを外している。","explanation":"洗髪という動作中に処方された酸素を中断すると、必要な酸素供給が不足する可能性があります。入浴中も指示された方法で酸素を使用します。"},{"choice":4,"correct":false,"title":"浴室の扉を開けたまま入浴している。","explanation":"換気は浴室の熱気や湿気による不快感の軽減に役立つことがあります。寒さへの配慮は必要ですが、本問では酸素の中断に着目します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さん(73 歳、男性)は慢性閉塞性肺疾患で在宅酸素療法〈HOT〉を受けている。\nchronic obstructive pulmonary disease\n受診時に A さんが｢1人でお風呂に入っているが、息切れが強い｣と訴えたため、\n外来看護師は入浴時の具体的な状況を確認した。\n外来看護師が A さんに確認した内容で、息切れの原因と考えられるのはどれか。","choices":["入浴はシャワー浴にしている。","椅子に座って更衣を行っている。","洗髪時に鼻カニューレを外している。","浴室の扉を開けたまま入浴している。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":69,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[28],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A069"},"exam":111,"year":2022,"session":"AM","number":69},"sources":[]},{"id":"111-AM-070","record":{"id":"111-AM-070","choice_explanations":[{"choice":1,"correct":false,"title":"人工呼吸器の予備の回路を預かる。","explanation":"予備の回路は必要な時に利用者の場所で使えることが重要です。事業所に預かることだけでは、災害時の呼吸管理を支えられません。"},{"choice":2,"correct":true,"title":"災害時の個別支援マニュアルを作成する。","explanation":"電源、連絡先、避難方法、支援者の役割などを本人の状態に合わせて具体化します。家族や関係機関と共有し、実際に使える備えにします。"},{"choice":3,"correct":false,"title":"医療機関から非常用の人工呼吸器を借りる。","explanation":"機器の確保は医療機関等との調整が必要です。一律に借りることを計画するより、電源や代替手段を含む個別の支援計画を整えます。"},{"choice":4,"correct":false,"title":"事業所内に利用者が避難できる場所を確保する。","explanation":"訪問看護事業所が医療依存度の高い人を受け入れられるとは限りません。必要な医療が継続できる避難先を関係機関と調整します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"気管切開下で人工呼吸器を装着している利用者に対して、訪問看護事業所が災害\nに備えて行うことで適切なのはどれか。","choices":["人工呼吸器の予備の回路を預かる。","災害時の個別支援マニュアルを作成する。","医療機関から非常用の人工呼吸器を借りる。","事業所内に利用者が避難できる場所を確保する。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":70,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[28],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A070"},"exam":111,"year":2022,"session":"AM","number":70},"sources":[]},{"id":"111-AM-071","record":{"id":"111-AM-071","choice_explanations":[{"choice":1,"correct":true,"title":"｢栄養剤の注入後に白湯を注入してください｣","explanation":"栄養剤がチューブ内に残ると閉塞しやすくなります。注入後は指示された量の白湯などで流し、チューブ内を清潔に保ちます。"},{"choice":2,"correct":false,"title":"｢胃瘻のチューブはご家族で交換してください｣","explanation":"交換は誤挿入などの危険があり、家族が自己判断で行うものではありません。抜けた場合も無理に戻さず医療者へ連絡します。"},{"choice":3,"correct":false,"title":"｢胃瘻のチューブは同じ位置に固定してください｣","explanation":"同じ方向に圧がかかり続けると、皮膚や瘻孔の障害につながります。製品と状態に応じた固定方法を指導します。"},{"choice":4,"correct":false,"title":"｢下痢のときは栄養剤の注入速度を速めてください｣","explanation":"注入速度を速めると消化管への負担が増し、下痢を悪化させることがあります。速度や温度、衛生状態などを確認して調整します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"チューブ型の胃瘻の管理について、介護する家族に看護師が指導する内容で正し\nいのはどれか。","choices":["｢栄養剤の注入後に白湯を注入してください｣","｢胃瘻のチューブはご家族で交換してください｣","｢胃瘻のチューブは同じ位置に固定してください｣","｢下痢のときは栄養剤の注入速度を速めてください｣"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":71,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[28],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A071"},"exam":111,"year":2022,"session":"AM","number":71},"sources":[]},{"id":"111-AM-072","record":{"id":"111-AM-072","choice_explanations":[{"choice":1,"correct":false,"title":"計 画","explanation":"計画は目標や実施方法を決める段階です。担当者を集めて役割をつくる行為そのものとは区別します。"},{"choice":2,"correct":false,"title":"指 揮","explanation":"指揮は構成員に働きかけ、活動を進める段階です。担当チームを編成する行為の分類ではありません。"},{"choice":3,"correct":false,"title":"統 制","explanation":"統制は実施状況を評価して目標との差を修正することです。チームを作る段階とは異なります。"},{"choice":4,"correct":true,"title":"組織化","explanation":"組織化は目標達成に必要な人や役割を配置することです。口腔ケア改善の担当チームをつくる行為が該当します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"病棟で患者の口腔ケア改善に取り組むために担当チームを作った。\nこれは看護管理のプロセスのどれか。","choices":["計 画","指 揮","統 制","組織化"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":72,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[29],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A072"},"exam":111,"year":2022,"session":"AM","number":72},"sources":[]},{"id":"111-AM-073","record":{"id":"111-AM-073","choice_explanations":[{"choice":1,"correct":true,"title":"疼痛コントロールの状況","explanation":"多発骨転移では強い痛みが生じ得ます。現在の鎮痛方法、効果、突出痛などを共有し、転棟後も苦痛の緩和が途切れないようにします。"},{"choice":2,"correct":false,"title":"自宅の居住環境","explanation":"在宅移行を考える際には重要ですが、転棟直後の苦痛緩和を継続するための情報が先です。"},{"choice":3,"correct":false,"title":"大腸癌の術式\ncolon cancer","explanation":"治療歴として把握しますが、現在の状態と直結する疼痛コントロールの情報より優先度は低くなります。"},{"choice":4,"correct":false,"title":"夫の面会頻度","explanation":"家族支援に必要な情報ですが、まず患者の苦痛を把握してケアを継続します。付き添っていることだけで支援力を判断しません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"多発性骨転移がある終末期の大腸癌患者(53 歳、女性)が、外科病棟から緩和ケ\ncolon cancer\nア病棟に夫に付き添われ転棟してきた。\n転棟時の申し送りについて、緩和ケア病棟の看護師が外科病棟の看護師から収集\nする情報で最も優先すべきなのはどれか。","choices":["疼痛コントロールの状況","自宅の居住環境","大腸癌の術式\ncolon cancer","夫の面会頻度"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":73,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[29],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A073"},"exam":111,"year":2022,"session":"AM","number":73},"sources":[]},{"id":"111-AM-074","record":{"id":"111-AM-074","choice_explanations":[{"choice":1,"correct":true,"title":"看護師等免許保持者の届出","explanation":"離職時などに免許保持者の情報を届け出ることで、ナースセンターによる復職支援につなげる制度です。働いていない人との接点を保つ役割があります。"},{"choice":2,"correct":false,"title":"特定行為に係る研修","explanation":"特定行為研修は、一定の診療の補助を手順書により行うための研修です。離職者の把握と復職支援の届出制度とは異なります。"},{"choice":3,"correct":false,"title":"教育訓練給付金","explanation":"教育訓練給付は雇用保険に関係する制度です。本問の看護師等の人材確保に関する法律に基づく制度ではありません。"},{"choice":4,"correct":false,"title":"業務従事者届","explanation":"業務従事者届は現在業務に従事する看護職の把握などのための届出です。離職した免許保持者を復職支援につなげる届出とは別です。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"看護師等の人材確保の促進に関する法律に規定されている、離職した看護師の復\n職の支援に関連する制度はどれか。","choices":["看護師等免許保持者の届出","特定行為に係る研修","教育訓練給付金","業務従事者届"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":74,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[29],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A074"},"exam":111,"year":2022,"session":"AM","number":74},"sources":[{"title":"厚生労働省：看護師等免許保持者の届出制度","url":"https://www.mhlw.go.jp/stf/seisakunitsuite/bunya/0000095486.html"}]},{"id":"111-AM-075","record":{"id":"111-AM-075","choice_explanations":[{"choice":1,"correct":false,"title":"意 識","explanation":"意識の確認も行いますが、START法の最初の振り分けではありません。短時間で多数を評価する順序を理解します。"},{"choice":2,"correct":false,"title":"呼 吸","explanation":"呼吸は歩行可能者を分けた後に確認する項目です。呼吸の有無や状態は、その後の緊急度判定に重要です。"},{"choice":3,"correct":false,"title":"循 環","explanation":"循環も判定に用いますが、最初に行う項目ではありません。定められた順番に沿って評価します。"},{"choice":4,"correct":true,"title":"歩 行","explanation":"まず歩行できる人を分けます。その後、歩けない人の呼吸・循環・意識などを順に確認して緊急度を判断します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"災害発生時に行う START 法によるトリアージで最初に判定を行う項目はどれ\nか。","choices":["意 識","呼 吸","循 環","歩 行"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":75,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[30],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A075"},"exam":111,"year":2022,"session":"AM","number":75},"sources":[]},{"id":"111-AM-076","record":{"id":"111-AM-076","choice_explanations":[{"choice":1,"correct":false,"title":"世界保健機関〈WHO〉","explanation":"WHOは保健分野を担当する国連の専門機関です。日本の政府開発援助を実施する国内の機関とは異なります。"},{"choice":2,"correct":true,"title":"国際協力機構〈JICA〉","explanation":"JICAは日本の政府開発援助を担う実施機関です。技術協力などを通じ、相手国の課題への取り組みを支援します。"},{"choice":3,"correct":false,"title":"国連開発計画〈UNDP〉","explanation":"UNDPは国連の開発支援機関です。日本も協力していますが、日本のODAの実施機関の名称ではありません。"},{"choice":4,"correct":false,"title":"赤十字国際委員会〈ICRC〉","explanation":"ICRCは武力紛争などで人道支援を行う組織です。日本政府の開発援助の実施機関ではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"日本の政府開発援助〈ODA〉の実施機関はどれか。","choices":["世界保健機関〈WHO〉","国際協力機構〈JICA〉","国連開発計画〈UNDP〉","赤十字国際委員会〈ICRC〉"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":76,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[30],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A076"},"exam":111,"year":2022,"session":"AM","number":76},"sources":[]},{"id":"111-AM-078","record":{"id":"111-AM-078","choice_explanations":[{"choice":1,"correct":false,"title":"下斜筋","explanation":"下斜筋は眼球の向きを変える外眼筋です。水晶体の厚さを変える筋ではありません。"},{"choice":2,"correct":false,"title":"下直筋","explanation":"下直筋は主に眼球を下方へ向ける外眼筋です。遠近調節とは働きが異なります。"},{"choice":3,"correct":true,"title":"毛様体筋","explanation":"毛様体筋は水晶体の厚さの調節に関係します。近くを見るときは収縮し、毛様小帯の緊張が緩んで水晶体が厚くなります。"},{"choice":4,"correct":false,"title":"上眼瞼挙筋","explanation":"上眼瞼挙筋は上まぶたを持ち上げます。焦点を近くや遠くへ合わせる働きではありません。"},{"choice":5,"correct":false,"title":"瞳孔括約筋","explanation":"瞳孔括約筋は瞳孔を小さくし、入る光の量などを調節します。水晶体の厚さを変える毛様体筋と区別します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"眼の遠近調節を行う筋はどれか。","choices":["下斜筋","下直筋","毛様体筋","上眼瞼挙筋","瞳孔括約筋"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":78,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[31],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A078"},"exam":111,"year":2022,"session":"AM","number":78},"sources":[]},{"id":"111-AM-079","record":{"id":"111-AM-079","choice_explanations":[{"choice":1,"correct":false,"title":"嗅神経","explanation":"嗅神経はにおいを伝える感覚神経です。咀嚼筋の運動を支配しません。"},{"choice":2,"correct":false,"title":"滑車神経","explanation":"滑車神経は眼球を動かす筋の一つを支配します。食物をかむ動作とは異なります。"},{"choice":3,"correct":true,"title":"三叉神経","explanation":"三叉神経の下顎神経に含まれる運動線維が咀嚼筋を支配します。顔面の感覚だけでなく、かむ運動も担う点が重要です。"},{"choice":4,"correct":false,"title":"動眼神経","explanation":"動眼神経は眼球運動やまぶた、瞳孔などに関係します。咀嚼筋の運動神経ではありません。"},{"choice":5,"correct":false,"title":"内耳神経","explanation":"内耳神経は聴覚と平衡覚を伝えます。咀嚼筋を動かす働きはありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"咀嚼運動にかかわる脳神経はどれか。","choices":["嗅神経","滑車神経","三叉神経","動眼神経","内耳神経"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":79,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[32],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A079"},"exam":111,"year":2022,"session":"AM","number":79},"sources":[]},{"id":"111-AM-080","record":{"id":"111-AM-080","choice_explanations":[{"choice":1,"correct":false,"title":"精 囊","explanation":"精囊は精液の成分を分泌します。精子が精囊の内部を通って射出される経路ではありません。"},{"choice":2,"correct":false,"title":"尿 管","explanation":"尿管は腎臓から膀胱へ尿を運びます。射精時に精子が通る管ではありません。"},{"choice":3,"correct":true,"title":"尿 道","explanation":"精子は精管、射精管を経て尿道へ入り、体外へ射出されます。男性の尿道は尿と精液の通路ですが、同時に流れるわけではありません。"},{"choice":4,"correct":false,"title":"膀 胱","explanation":"膀胱は尿をためる臓器です。通常の射精で精子が膀胱内を通ることはありません。"},{"choice":5,"correct":false,"title":"前立腺","explanation":"前立腺は精液成分を分泌し、尿道などが内部を通ります。本問で精子の通路として選ぶのは臓器名ではなく尿道です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"射出される精子が通るのはどれか。","choices":["精 囊","尿 管","尿 道","膀 胱","前立腺"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":80,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[32],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A080"},"exam":111,"year":2022,"session":"AM","number":80},"sources":[]},{"id":"111-AM-082","record":{"id":"111-AM-082","choice_explanations":[{"choice":1,"correct":false,"title":"NYHA 分類","explanation":"NYHA分類は心疾患による身体活動の制限を評価します。大動脈解離の位置と手術方針を分ける分類ではありません。"},{"choice":2,"correct":true,"title":"スタンフォード分類","explanation":"上行大動脈に解離が及ぶかでA型・B型に分けます。A型は致命的合併症の危険が高く、緊急手術を検討する重要な指標です。"},{"choice":3,"correct":false,"title":"Killip〈キリップ〉分類","explanation":"Killip分類は急性心筋梗塞に伴う心不全の重症度を身体所見などから分類します。大動脈解離の分類ではありません。"},{"choice":4,"correct":false,"title":"DeBakey〈ドベーキー〉分類","explanation":"DeBakey分類も大動脈解離の起始部や範囲を表しますが、設問の緊急手術の判断に直結する区分としてはスタンフォード分類を選びます。"},{"choice":5,"correct":false,"title":"Forrester〈フォレスター〉分類","explanation":"Forrester分類は心拍出と肺うっ血などの血行動態を評価します。大動脈のどこに解離があるかを示す分類ではありません。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"急性大動脈解離において緊急手術を行うかどうかの観点で用いる分類はどれか。\nacute aortic dissection","choices":["NYHA 分類","スタンフォード分類","Killip〈キリップ〉分類","DeBakey〈ドベーキー〉分類","Forrester〈フォレスター〉分類"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":82,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[33],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A082"},"exam":111,"year":2022,"session":"AM","number":82},"sources":[{"title":"日本循環器学会：2020年大動脈瘤・大動脈解離診療ガイドライン","url":"https://www.j-circ.or.jp/cms/wp-content/uploads/2020/07/JCS2020_Ogino.pdf"}]},{"id":"111-AM-083","record":{"id":"111-AM-083","choice_explanations":[{"choice":1,"correct":true,"title":"患者の誤認","explanation":"処置開始前にチームで患者・部位・術式などを確認し、取り違えを防ぎます。全員で立ち止まって共通認識を持つ手順です。"},{"choice":2,"correct":false,"title":"抗癌薬の曝露","explanation":"抗がん薬曝露の予防には防護具や適切な調製・廃棄の手順が必要です。タイムアウトの直接の目的ではありません。"},{"choice":3,"correct":false,"title":"個人情報の漏洩","explanation":"個人情報の管理にはアクセス制限や情報共有時の配慮が必要です。患者・手術内容の確認とは別の対策です。"},{"choice":4,"correct":false,"title":"ベッドからの転落","explanation":"転落予防には状態評価や環境整備、移動時の支援が必要です。タイムアウトによって直接防ぐ事故の代表ではありません。"},{"choice":5,"correct":false,"title":"血液を媒介とする感染","explanation":"血液曝露を防ぐには標準予防策や針刺し防止が重要です。処置前の本人確認とは目的が異なります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"タイムアウトによって予防できるのはどれか。","choices":["患者の誤認","抗癌薬の曝露","個人情報の漏洩","ベッドからの転落","血液を媒介とする感染"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":83,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[33],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A083"},"exam":111,"year":2022,"session":"AM","number":83},"sources":[]},{"id":"111-AM-084","record":{"id":"111-AM-084","choice_explanations":[{"choice":1,"correct":false,"title":"1回換気量の増加","explanation":"臥床が続くと胸郭の動きや呼吸筋の活動が減り、換気量は低下する方向に働きます。増加は廃用の特徴ではありません。"},{"choice":2,"correct":false,"title":"循環血液量の増加","explanation":"長期臥床では循環血液量が減少し、起立時の循環調節も低下しやすくなります。増加するという説明は逆です。"},{"choice":3,"correct":false,"title":"基礎代謝の上昇","explanation":"活動量や筋肉量の低下に伴い、代謝は低下する方向に働きます。安静が基礎代謝を高めるわけではありません。"},{"choice":4,"correct":true,"title":"骨吸収の亢進","explanation":"骨への荷重が減ると骨吸収が進み、骨量が低下します。可能な範囲の離床や荷重が、廃用予防に関係する理由です。"},{"choice":5,"correct":false,"title":"食欲の増進","explanation":"活動量の低下は食欲低下や便秘などにつながり得ます。食欲増進を廃用の典型的な変化とは考えません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"安静臥床による廃用症候群で生じるのはどれか。\ndisuse syndrome","choices":["1回換気量の増加","循環血液量の増加","基礎代謝の上昇","骨吸収の亢進","食欲の増進"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":84,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[34],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A084"},"exam":111,"year":2022,"session":"AM","number":84},"sources":[]},{"id":"111-AM-085","record":{"id":"111-AM-085","choice_explanations":[{"choice":1,"correct":false,"title":"解 離","explanation":"解離は記憶や意識などのつながりが分断される働きです。不満の対象を上司から後輩へ変えることとは異なります。"},{"choice":2,"correct":false,"title":"昇 華","explanation":"昇華は受け入れにくい衝動を社会的に認められる活動へ向けることです。後輩を叱責する行動は該当しません。"},{"choice":3,"correct":false,"title":"合理化","explanation":"合理化は都合のよい理由を付け、感情や行動を正当化することです。本問では理由付けより対象の変更が中心です。"},{"choice":4,"correct":true,"title":"置き換え","explanation":"直接向けにくい感情を別の対象に向ける働きです。上司への不満を後輩へぶつけているため、置き換えに当たります。"},{"choice":5,"correct":false,"title":"反動形成","explanation":"反動形成は受け入れにくい感情と反対の態度を示すことです。本問は感情が反対になるのではなく、向ける相手が変わっています。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんは職場の上司に不満をぶつけたいと考えているが、それができないので、\n不満をぶつけやすい対象である後輩を叱責している。\nA さんの防衛機制で正しいのはどれか。","choices":["解 離","昇 華","合理化","置き換え","反動形成"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":85,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[34],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A085"},"exam":111,"year":2022,"session":"AM","number":85},"sources":[]},{"id":"111-AM-086","record":{"id":"111-AM-086","choice_explanations":[{"choice":1,"correct":false,"title":"測定値の上限は 10 % である。","explanation":"HbA1cが10％を超える場合もあります。10％は測定値の上限ではなく、高血糖が続けばさらに高くなり得ます。"},{"choice":2,"correct":true,"title":"赤血球の寿命によって測定値は変動する。","explanation":"赤血球が短期間で入れ替わる場合などは、血糖に比べHbA1cが低く出ることがあります。赤血球の寿命が検査値に影響します。"},{"choice":3,"correct":false,"title":"過去1、2週間の血糖値管理の指標である。","explanation":"HbA1cは主に過去1〜2か月の血糖状態を反映します。直近1〜2週間だけを示す指標ではありません。"},{"choice":4,"correct":false,"title":"グリコアルブミンより短期間の血糖値管理の指標である。","explanation":"グリコアルブミンの方が短い期間を反映します。赤血球とアルブミンの代謝回転の違いを考えて区別します。"},{"choice":5,"correct":true,"title":"ヘモグロビンにブドウ糖が結合した糖化蛋白質のことである。","explanation":"ヘモグロビンにブドウ糖が結合したもので、糖化ヘモグロビンと呼びます。血糖が高い状態が続くほど、その割合が高くなります。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"ヘモグロビン A1c〈HbA1c〉について正しいのはどれか。2つ選べ。","choices":["測定値の上限は 10 % である。","赤血球の寿命によって測定値は変動する。","過去1、2週間の血糖値管理の指標である。","グリコアルブミンより短期間の血糖値管理の指標である。","ヘモグロビンにブドウ糖が結合した糖化蛋白質のことである。"],"correct_answers":[2,5],"accepted_answer_sets":[[2,5]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":86,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[35],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A086"},"exam":111,"year":2022,"session":"AM","number":86},"sources":[{"title":"国立循環器病研究センター：HbA1cの意味","url":"https://www.ncvc.go.jp/hospital/section/ld/endocrinology/hba1c/"}]},{"id":"111-AM-088","record":{"id":"111-AM-088","choice_explanations":[{"choice":1,"correct":false,"title":"BMI","explanation":"栄養状態の評価では役立ちますが、CGA7で直接評価する項目ではありません。高齢者評価全般と特定の尺度を区別します。"},{"choice":2,"correct":true,"title":"意 欲","explanation":"自発的な反応などから意欲を評価します。身体機能だけでなく、活動へ向かう気持ちにも着目するのが総合機能評価の特徴です。"},{"choice":3,"correct":false,"title":"職業歴","explanation":"生活背景として重要ですが、CGA7の直接の評価項目ではありません。"},{"choice":4,"correct":false,"title":"新機器の利用","explanation":"新しい機器を使えるかだけを独立した項目として評価する尺度ではありません。生活機能は具体的な日常動作から確認します。"},{"choice":5,"correct":true,"title":"日常生活動作〈ADL〉","explanation":"手段的な動作も含め、日常生活でどの程度自立しているかを確認します。病名だけでは分からない支援の必要性を把握します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"高齢者の総合機能評価 CGA 簡易版〈CGA7〉で評価するのはどれか。2つ選べ。","choices":["BMI","意 欲","職業歴","新機器の利用","日常生活動作〈ADL〉"],"correct_answers":[2,5],"accepted_answer_sets":[[2,5]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":88,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[36],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A088"},"exam":111,"year":2022,"session":"AM","number":88},"sources":[{"title":"日本老年医学会：CGA7","url":"https://www.jpn-geriat-soc.or.jp/tool/"}]},{"id":"111-AM-089","record":{"id":"111-AM-089","choice_explanations":[{"choice":1,"correct":false,"title":"運動性チックが出現する。","explanation":"運動性チックはチック症などにみられます。併存することはありますが、自閉症スペクトラム障害の中核的特徴ではありません。"},{"choice":2,"correct":false,"title":"計算の習得が困難である。","explanation":"計算に特異的な困難は学習に関する障害で問題となります。自閉症スペクトラム障害がある人全員にみられる特徴ではありません。"},{"choice":3,"correct":false,"title":"不注意による間違いが多い。","explanation":"不注意によるミスは注意欠如・多動症との関連が重要です。併存の可能性と、診断の中心的な特徴を区別します。"},{"choice":4,"correct":true,"title":"習慣へのかたくななこだわりがある。","explanation":"いつもの手順や習慣に強くこだわり、変更に困難を感じることがあります。見通しを伝えるなど、特性に合わせた支援を考えます。"},{"choice":5,"correct":true,"title":"非言語的コミュニケーションの障害がある。","explanation":"視線、表情、身振りなどを使った意思疎通に困難がみられることがあります。話せるかどうかだけでコミュニケーション能力を判断しません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"自閉症スペクトラム障害にみられるのはどれか。2つ選べ。\nautism spectrum disorder","choices":["運動性チックが出現する。","計算の習得が困難である。","不注意による間違いが多い。","習慣へのかたくななこだわりがある。","非言語的コミュニケーションの障害がある。"],"correct_answers":[4,5],"accepted_answer_sets":[[4,5]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":89,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[36],"case_pages":[],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A089"},"exam":111,"year":2022,"session":"AM","number":89},"sources":[]},{"id":"111-AM-094","record":{"id":"111-AM-094","choice_explanations":[{"choice":1,"correct":true,"title":"｢食事療法が必要です｣","explanation":"CAPDを行っても塩分・水分や栄養の調整は必要です。透析液から吸収されるエネルギーや蛋白喪失なども考え、個別に食事を整えます。"},{"choice":2,"correct":false,"title":"｢通院は週に2、3回必要です｣","explanation":"週2、3回の通院を基本とする血液透析とは異なり、CAPDは自宅等で交換できます。定期通院の頻度は状態と施設の指示によります。"},{"choice":3,"correct":false,"title":"｢宿泊を伴う旅行はできません｣","explanation":"必要な物品と清潔な交換環境を確保し、事前に相談すれば旅行も可能です。宿泊を伴うだけで一律に禁止されるわけではありません。"},{"choice":4,"correct":false,"title":"｢カテーテル挿入術後の翌日から入浴できます｣","explanation":"術翌日からの入浴を一律に許可する説明は不適切です。創部の治癒や出口部の管理方法を確認し、指示された時期・方法に従います。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんに対する説明として正しいのはどれか。","choices":["｢食事療法が必要です｣","｢通院は週に2、3回必要です｣","｢宿泊を伴う旅行はできません｣","｢カテーテル挿入術後の翌日から入浴できます｣"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":"A さん(50 歳、男性、会社員)は妻と高校生の息子との3人暮らし。仕事を生きが\nいに働き続けていた。慢性腎不全のため透析治療が必要になったが、本人の希望で連\nchronic renal failure\n続携行式腹膜灌流法〈CAPD〉を導入することになり入院した。A さんはこれからの生\n活がどのようになるのかを看護師に質問した。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":94,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[40],"case_pages":[40],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A094"},"exam":111,"year":2022,"session":"AM","number":94},"sources":[]},{"id":"111-AM-095","record":{"id":"111-AM-095","choice_explanations":[{"choice":1,"correct":false,"title":"透析液を保管する冷蔵庫","explanation":"透析液は製品の指示に従って保管します。冷蔵庫が必須というわけではなく、交換に適した清潔な保管場所が必要です。"},{"choice":2,"correct":false,"title":"透析液を温める電子レンジ","explanation":"電子レンジでは加温むらやバッグの損傷などが問題となるため、専用の加温器など指定された方法を用います。"},{"choice":3,"correct":true,"title":"透析液の交換時に使用する個室","explanation":"交換時の清潔とプライバシーを保てる場所が必要です。人の出入りや気流などにも配慮し、落ち着いて操作できる環境を整えます。"},{"choice":4,"correct":true,"title":"CAPD の物品を保管する専用棚","explanation":"必要な物品を清潔かつ整理した状態で保管する場所を確保します。仕事中も手順を省略せず安全に交換できる備えです。"},{"choice":5,"correct":false,"title":"透析液の貯留中に使用するベッド","explanation":"透析液の貯留中も日常活動が可能で、横になるためのベッドが常に必要ではありません。交換と貯留の時間を区別します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんはできるだけ早い職場復帰を望んでおり、入院中は CAPD の操作に熱心\nに取り組んでいた。退院後、CAPD を1日4回(0時、6時、12 時、18 時)行うこ\nとになった。\nA さんが会社の昼休みに CAPD を行うために必要な設備はどれか。2つ選べ。","choices":["透析液を保管する冷蔵庫","透析液を温める電子レンジ","透析液の交換時に使用する個室","CAPD の物品を保管する専用棚","透析液の貯留中に使用するベッド"],"correct_answers":[3,4],"accepted_answer_sets":[[3,4]],"case_text":"A さん(50 歳、男性、会社員)は妻と高校生の息子との3人暮らし。仕事を生きが\nいに働き続けていた。慢性腎不全のため透析治療が必要になったが、本人の希望で連\nchronic renal failure\n続携行式腹膜灌流法〈CAPD〉を導入することになり入院した。A さんはこれからの生\n活がどのようになるのかを看護師に質問した。","preceding_context":[{"id":"111-AM-094","question":"A さんに対する説明として正しいのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":95,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[40],"case_pages":[40],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A095"},"exam":111,"year":2022,"session":"AM","number":95},"sources":[]},{"id":"111-AM-096","record":{"id":"111-AM-096","choice_explanations":[{"choice":1,"correct":true,"title":"腹 痛","explanation":"腹膜の炎症で腹痛が生じることがあります。痛みや排液の変化に気づいたら、自己判断で待たず医療機関へ連絡します。"},{"choice":2,"correct":false,"title":"体重の増加","explanation":"体重増加は主に体液量や栄養状態を評価する指標です。腹膜炎の早期発見に特に結び付く選択肢ではありません。"},{"choice":3,"correct":false,"title":"腹部の張り","explanation":"腹部の張りは貯留液などでも生じます。腹膜炎を見つける観察では腹痛や排液の混濁がより重要です。"},{"choice":4,"correct":false,"title":"下肢のむくみ","explanation":"下肢の浮腫は体液貯留などでみられます。腹膜炎に特徴的な所見として最優先するものではありません。"},{"choice":5,"correct":true,"title":"透析液の排液のにごり","explanation":"排液が白く濁るのは、腹膜炎を疑う重要な変化です。腹痛が目立たない場合もあるので、毎回排液の透明さを観察します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんは｢主治医から CAPD の合併症に腹膜炎があると聞きました。腹膜炎に早\nperitonitis peritonitis\nく気付くにはどうすればよいですか｣と看護師に質問した。\nA さんに指導する観察項目はどれか。2つ選べ。","choices":["腹 痛","体重の増加","腹部の張り","下肢のむくみ","透析液の排液のにごり"],"correct_answers":[1,5],"accepted_answer_sets":[[1,5]],"case_text":"A さん(50 歳、男性、会社員)は妻と高校生の息子との3人暮らし。仕事を生きが\nいに働き続けていた。慢性腎不全のため透析治療が必要になったが、本人の希望で連\nchronic renal failure\n続携行式腹膜灌流法〈CAPD〉を導入することになり入院した。A さんはこれからの生\n活がどのようになるのかを看護師に質問した。","preceding_context":[{"id":"111-AM-094","question":"A さんに対する説明として正しいのはどれか。"},{"id":"111-AM-095","question":"A さんはできるだけ早い職場復帰を望んでおり、入院中は CAPD の操作に熱心\nに取り組んでいた。退院後、CAPD を1日4回(0時、6時、12 時、18 時)行うこ\nとになった。\nA さんが会社の昼休みに CAPD を行うために必要な設備はどれか。2つ選べ。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":96,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[41],"case_pages":[40],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A096"},"exam":111,"year":2022,"session":"AM","number":96},"sources":[{"title":"日本透析医学会：腹膜透析ガイドライン2019 腹膜炎管理","url":"https://www.jsdt.or.jp/tools/file/download.cgi/2658/PDGL2019_09Part1%E7%AC%AC%E5%85%AD%E7%AB%A0_%E8%85%B9%E8%86%9C%E7%82%8E%E7%AE%A1%E7%90%86.pdf"}]},{"id":"111-AM-097","record":{"id":"111-AM-097","choice_explanations":[{"choice":1,"correct":false,"title":"通院の方法","explanation":"通院方法は生活支援に必要ですが、呼吸症状と浮腫があるため、まず心不全悪化に関係する体液貯留を把握します。"},{"choice":2,"correct":true,"title":"最近の体重の増減","explanation":"急な体重増加は体液の貯留を示す手掛かりです。もとの体重と現在を比較し、浮腫や息切れと併せて評価します。"},{"choice":3,"correct":false,"title":"パートの仕事内容","explanation":"仕事内容は活動負荷を考える際に重要ですが、今あるうっ血の程度を把握する情報が優先です。"},{"choice":4,"correct":false,"title":"自宅での1日の過ごし方","explanation":"生活全体の把握も必要ですが、まず症状に直結する体重の変化を確認し、緊急度や治療につながる情報を集めます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"外来看護師が A さんに対して優先して確認するのはどれか。","choices":["通院の方法","最近の体重の増減","パートの仕事内容","自宅での1日の過ごし方"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(70 歳、女性)は1人暮らし。夫とは1年前に死別した。近くの診療所で\n高血圧症と心不全と診断され、内服治療をしていた。月1回は診療所で内服薬の処方\nhypertension heart failure\nと食事指導や体重測定などの生活指導を受けていたが、時々薬を飲んだことを忘れて\nしまうことがあった。日常生活は自立しており、認知機能は問題ない。週2日、事務\n職のパートとして働いており、電車を使って通勤していた。息子(42 歳)と娘(37 歳)\nは仕事のため遠方に住んでいる。1か月前から A さんは家事や外出するときに軽い\n息切れを感じるようになり、2、3日前からは咳と痰が出るようになった。両足のむ\nくみが出てきたため、診療所から自宅近くの病院を紹介され外来受診した。\n身体所見：意識は清明。身長 159 cm、体重 61.3 kg。\n体温 37.1 ℃、呼吸数 21/分、脈拍 95/分、不整、血圧 164/96 mmHg、\n経皮的動脈血酸素飽和度〈SpO2〉92 %(room air)。\n両下肢に軽度の浮腫を認めた。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":97,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[42],"case_pages":[42],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A097"},"exam":111,"year":2022,"session":"AM","number":97},"sources":[]},{"id":"111-AM-098","record":{"id":"111-AM-098","choice_explanations":[{"choice":1,"correct":false,"title":"終日、病室を明るくする。","explanation":"昼夜とも明るい環境では生活リズムが整いにくくなります。昼は明るく、夜は休める環境にして昼夜の違いを作ります。"},{"choice":2,"correct":true,"title":"日中眠っていたら覚醒を促す。","explanation":"昼間の覚醒を支え、可能な活動を取り入れて睡眠・覚醒リズムを整えます。急な見当識の変化はせん妄も考え、身体状態の確認も必要です。"},{"choice":3,"correct":false,"title":"睡眠導入薬の使用を医師に相談する。","explanation":"薬剤が必要になる場合はありますが、まず身体状態と環境を整えます。睡眠薬を一律に追加すると、せん妄や転倒を悪化させる場合があります。"},{"choice":4,"correct":false,"title":"夜間覚醒している場合は、夜は眠るよう説得する。","explanation":"混乱している患者を説得しても、睡眠が改善するとは限りません。安心できる関わりと、昼夜のリズムを整える支援を行います。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"診察の結果、A さんは心不全の悪化を認めたため入院することになり、個室を\nheart failure\n希望した。入院後、酸素マスクによる酸素療法や利尿薬による薬物療法、塩分制限\nなどの食事療法が開始された。入院3日、夜勤の看護師から日勤の看護師への朝の\n申し送りで、昨晩の A さんは夜間全く眠っていないこと、｢ここはどこですか｣と\n繰り返し尋ねてきたこと、娘が学校から帰ってくるのを待っていると言って病室の\n入り口を気にしていたことが報告された。日勤の看護師は、A さんの睡眠状況を\n改善する必要があると考え、A さんへの対応について検討した。\n看護師の A さんへの対応で適切なのはどれか。","choices":["終日、病室を明るくする。","日中眠っていたら覚醒を促す。","睡眠導入薬の使用を医師に相談する。","夜間覚醒している場合は、夜は眠るよう説得する。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(70 歳、女性)は1人暮らし。夫とは1年前に死別した。近くの診療所で\n高血圧症と心不全と診断され、内服治療をしていた。月1回は診療所で内服薬の処方\nhypertension heart failure\nと食事指導や体重測定などの生活指導を受けていたが、時々薬を飲んだことを忘れて\nしまうことがあった。日常生活は自立しており、認知機能は問題ない。週2日、事務\n職のパートとして働いており、電車を使って通勤していた。息子(42 歳)と娘(37 歳)\nは仕事のため遠方に住んでいる。1か月前から A さんは家事や外出するときに軽い\n息切れを感じるようになり、2、3日前からは咳と痰が出るようになった。両足のむ\nくみが出てきたため、診療所から自宅近くの病院を紹介され外来受診した。\n身体所見：意識は清明。身長 159 cm、体重 61.3 kg。\n体温 37.1 ℃、呼吸数 21/分、脈拍 95/分、不整、血圧 164/96 mmHg、\n経皮的動脈血酸素飽和度〈SpO2〉92 %(room air)。\n両下肢に軽度の浮腫を認めた。","preceding_context":[{"id":"111-AM-097","question":"外来看護師が A さんに対して優先して確認するのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":98,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[43],"case_pages":[42],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A098"},"exam":111,"year":2022,"session":"AM","number":98},"sources":[]},{"id":"111-AM-099","record":{"id":"111-AM-099","choice_explanations":[{"choice":1,"correct":true,"title":"｢薬の管理はお薬カレンダーを使いましょう｣","explanation":"服薬したことを忘れることがあるため、服用の記録が目で確認できる方法が役立ちます。本人が管理しやすい仕組みを一緒に選びます。"},{"choice":2,"correct":false,"title":"｢通勤するときに駅の階段を使いましょう｣","explanation":"退院直後は体力が低下しており、階段の使用を一律に勧めるのは不適切です。症状と体力に合わせて段階的に活動を調整します。"},{"choice":3,"correct":false,"title":"｢水分は1日 2,000 mL 摂りましょう｣","explanation":"心不全では体液の過剰に注意し、水分量は病状や指示に応じて決めます。2,000mLを誰にでも勧めることはできません。"},{"choice":4,"correct":false,"title":"｢塩分を1日9g 摂りましょう｣","explanation":"塩分の過剰は体液貯留を招き、心不全悪化につながります。9gを積極的に取るのではなく、処方された減塩目標に合わせます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"入院後 10 日。入院治療により全身状態は改善し、夜間の睡眠もとれるように\nなったため、A さんは退院することになった。A さんは｢入院していて体力が落ち\nてしまい、動くと疲れてしまう｣と言っている。また、看護師に｢医師から退院した\nら元の仕事はしてよいといわれました。これまでの生活を続けたいと思っていま\nす。また入院するのは嫌なので、今後の生活で気をつけることはありますか｣と尋\nねてきた。\nこのときの看護師の対応で適切なのはどれか。","choices":["｢薬の管理はお薬カレンダーを使いましょう｣","｢通勤するときに駅の階段を使いましょう｣","｢水分は1日 2,000 mL 摂りましょう｣","｢塩分を1日9g 摂りましょう｣"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":"A さん(70 歳、女性)は1人暮らし。夫とは1年前に死別した。近くの診療所で\n高血圧症と心不全と診断され、内服治療をしていた。月1回は診療所で内服薬の処方\nhypertension heart failure\nと食事指導や体重測定などの生活指導を受けていたが、時々薬を飲んだことを忘れて\nしまうことがあった。日常生活は自立しており、認知機能は問題ない。週2日、事務\n職のパートとして働いており、電車を使って通勤していた。息子(42 歳)と娘(37 歳)\nは仕事のため遠方に住んでいる。1か月前から A さんは家事や外出するときに軽い\n息切れを感じるようになり、2、3日前からは咳と痰が出るようになった。両足のむ\nくみが出てきたため、診療所から自宅近くの病院を紹介され外来受診した。\n身体所見：意識は清明。身長 159 cm、体重 61.3 kg。\n体温 37.1 ℃、呼吸数 21/分、脈拍 95/分、不整、血圧 164/96 mmHg、\n経皮的動脈血酸素飽和度〈SpO2〉92 %(room air)。\n両下肢に軽度の浮腫を認めた。","preceding_context":[{"id":"111-AM-097","question":"外来看護師が A さんに対して優先して確認するのはどれか。"},{"id":"111-AM-098","question":"診察の結果、A さんは心不全の悪化を認めたため入院することになり、個室を\nheart failure\n希望した。入院後、酸素マスクによる酸素療法や利尿薬による薬物療法、塩分制限\nなどの食事療法が開始された。入院3日、夜勤の看護師から日勤の看護師への朝の\n申し送りで、昨晩の A さんは夜間全く眠っていないこと、｢ここはどこですか｣と\n繰り返し尋ねてきたこと、娘が学校から帰ってくるのを待っていると言って病室の\n入り口を気にしていたことが報告された。日勤の看護師は、A さんの睡眠状況を\n改善する必要があると考え、A さんへの対応について検討した。\n看護師の A さんへの対応で適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":99,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[43],"case_pages":[42],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A099"},"exam":111,"year":2022,"session":"AM","number":99},"sources":[]},{"id":"111-AM-100","record":{"id":"111-AM-100","choice_explanations":[{"choice":1,"correct":false,"title":"褐色便","explanation":"褐色は胆汁由来の色素が腸管に届くことで生じます。胆道閉鎖により胆汁の流れが妨げられた場合の特徴とは異なります。"},{"choice":2,"correct":true,"title":"灰白色便","explanation":"胆汁色素が腸管へ届かず、便が白っぽくなります。直接ビリルビンの増加を伴う黄疸と合わせ、胆汁うっ滞を考えます。"},{"choice":3,"correct":false,"title":"タール便","explanation":"黒くタール状の便は消化管出血を考える所見です。胆汁が届かないことによる便色の変化とは異なります。"},{"choice":4,"correct":false,"title":"イチゴゼリー様便","explanation":"イチゴゼリー様の血液・粘液便は腸重積などでみられます。胆道閉鎖症に特徴的な便ではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A ちゃんの便として考えられるのはどれか。","choices":["褐色便","灰白色便","タール便","イチゴゼリー様便"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A ちゃん(生後 24 日、女児)は両親と3人暮らし。母親が母子健康手帳の便色カー\nドを見て、A ちゃんの便色が気になったため、A ちゃんを連れて近所の小児科医院\nを受診した。A ちゃんは在胎 39 週、出生体重 3,100 g、出生時に異常はない。\n現在、混合栄養で体重は 3,700 g である。体温 37.2 ℃、呼吸数 36/分、心拍数\n108/分、整、血圧 78/44 mmHg。眼球結膜に黄染を認める。\n血液検査結果：Hb 12.6 g/dL、白血球 7,800/μL、血小板 21 万/μL、プロトロンビ\nン時間〈PT〉88 %、総ビリルビン 11.3 mg/dL、直接ビリルビン 9.5 mg/dL、AST 96\nU/L、ALT 126 U/L。\n紹介先の病院で腹部超音波検査を実施した結果、A ちゃんは胆道閉鎖症の疑いが\nbiliary atresia\nあり入院した。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":100,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[44],"case_pages":[44],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A100"},"exam":111,"year":2022,"session":"AM","number":100},"sources":[]},{"id":"111-AM-101","record":{"id":"111-AM-101","choice_explanations":[{"choice":1,"correct":true,"title":"話しかけやおしゃぶりの活用など母親ができることを伝える。","explanation":"「何もできない」というつらさを受け止め、声かけや安全にできる関わりを一緒に探します。母親が子どもを支えていると感じられる援助です。"},{"choice":2,"correct":false,"title":"早期発見だったので A ちゃんは早く退院できると説明する。","explanation":"早期発見だったというだけで退院時期を保証できません。根拠のない安心を与えるより、今のつらさに応じた支援をします。"},{"choice":3,"correct":false,"title":"心療内科の受診を勧める。","explanation":"この発言だけで専門外来の受診が必要とは判断できません。まず母親の思いを聴き、今できる支援を行います。"},{"choice":4,"correct":false,"title":"患者家族会を紹介する。","explanation":"家族会は今後の支えになり得ますが、母親は今、子どもに何もできないことをつらく感じています。直ちにできる関わりを伝えることが優先です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A ちゃんは入院7日に術中胆道造影検査で胆道閉鎖症と確定診断された。手術\nbiliary atresia\nは無事に終了した。術後は絶食となり、腹腔ドレーンが挿入され、持続的点滴静脈\n内注射が行われている。母親は疾患や治療について理解している。術後3日、付き\n添っていた母親は看護師に｢A はおなかが空いて泣き止まないし、私は A を抱っこ\nもできず、何もしてあげられません。つらいです｣と涙を浮かべて話した。\n看護師の母親への対応で、最も適切なのはどれか。","choices":["話しかけやおしゃぶりの活用など母親ができることを伝える。","早期発見だったので A ちゃんは早く退院できると説明する。","心療内科の受診を勧める。","患者家族会を紹介する。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":"A ちゃん(生後 24 日、女児)は両親と3人暮らし。母親が母子健康手帳の便色カー\nドを見て、A ちゃんの便色が気になったため、A ちゃんを連れて近所の小児科医院\nを受診した。A ちゃんは在胎 39 週、出生体重 3,100 g、出生時に異常はない。\n現在、混合栄養で体重は 3,700 g である。体温 37.2 ℃、呼吸数 36/分、心拍数\n108/分、整、血圧 78/44 mmHg。眼球結膜に黄染を認める。\n血液検査結果：Hb 12.6 g/dL、白血球 7,800/μL、血小板 21 万/μL、プロトロンビ\nン時間〈PT〉88 %、総ビリルビン 11.3 mg/dL、直接ビリルビン 9.5 mg/dL、AST 96\nU/L、ALT 126 U/L。\n紹介先の病院で腹部超音波検査を実施した結果、A ちゃんは胆道閉鎖症の疑いが\nbiliary atresia\nあり入院した。","preceding_context":[{"id":"111-AM-100","question":"A ちゃんの便として考えられるのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":101,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[45],"case_pages":[44],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A101"},"exam":111,"year":2022,"session":"AM","number":101},"sources":[]},{"id":"111-AM-102","record":{"id":"111-AM-102","choice_explanations":[{"choice":1,"correct":false,"title":"果 汁","explanation":"味や酸味で飲みにくくなる場合があり、生後まもない児に果汁を薬のために用いる必要はありません。薬に適した混ぜ方を確認します。"},{"choice":2,"correct":true,"title":"白 湯","explanation":"少量の白湯など、指示された方法で溶かして飲ませます。大量に混ぜると飲み残して必要量を摂取できないおそれがあります。"},{"choice":3,"correct":false,"title":"人工乳","explanation":"人工乳全体に混ぜると、飲み残しで投与量が不確かになったり、味の変化で哺乳を嫌がったりする可能性があります。"},{"choice":4,"correct":false,"title":"はちみつ","explanation":"乳児にはボツリヌス症予防のため、はちみつを与えません。薬を飲みやすくする目的でも使用しません。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"術後5日、A ちゃんは経口摂取が可能になり順調に経過している。医師から母\n親に、胆汁の排泄を促すために利胆薬の内服が重要であると説明があり、散剤が処\n方された。母親から看護師に｢赤ちゃんに粉の薬をどうやって飲ませたらよいので\nしょうか｣と質問があった。看護師は散剤を( )に混ぜて飲ませることを説明し\nた。\n( )に入るのはどれか。","choices":["果 汁","白 湯","人工乳","はちみつ"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A ちゃん(生後 24 日、女児)は両親と3人暮らし。母親が母子健康手帳の便色カー\nドを見て、A ちゃんの便色が気になったため、A ちゃんを連れて近所の小児科医院\nを受診した。A ちゃんは在胎 39 週、出生体重 3,100 g、出生時に異常はない。\n現在、混合栄養で体重は 3,700 g である。体温 37.2 ℃、呼吸数 36/分、心拍数\n108/分、整、血圧 78/44 mmHg。眼球結膜に黄染を認める。\n血液検査結果：Hb 12.6 g/dL、白血球 7,800/μL、血小板 21 万/μL、プロトロンビ\nン時間〈PT〉88 %、総ビリルビン 11.3 mg/dL、直接ビリルビン 9.5 mg/dL、AST 96\nU/L、ALT 126 U/L。\n紹介先の病院で腹部超音波検査を実施した結果、A ちゃんは胆道閉鎖症の疑いが\nbiliary atresia\nあり入院した。","preceding_context":[{"id":"111-AM-100","question":"A ちゃんの便として考えられるのはどれか。"},{"id":"111-AM-101","question":"A ちゃんは入院7日に術中胆道造影検査で胆道閉鎖症と確定診断された。手術\nbiliary atresia\nは無事に終了した。術後は絶食となり、腹腔ドレーンが挿入され、持続的点滴静脈\n内注射が行われている。母親は疾患や治療について理解している。術後3日、付き\n添っていた母親は看護師に｢A はおなかが空いて泣き止まないし、私は A を抱っこ\nもできず、何もしてあげられません。つらいです｣と涙を浮かべて話した。\n看護師の母親への対応で、最も適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":102,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[45],"case_pages":[44],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A102"},"exam":111,"year":2022,"session":"AM","number":102},"sources":[{"title":"厚生労働省：乳児へのはちみつを避ける","url":"https://www.mhlw.go.jp/stf/seisakunitsuite/bunya/0000161461.html"}]},{"id":"111-AM-103","record":{"id":"111-AM-103","choice_explanations":[{"choice":1,"correct":false,"title":"妊娠 35 週5日","explanation":"公式採点では不正答です。ただし元問題のカレンダーが現在の表示データにないため、35週5日を除外する日付の計算根拠は不明です。"},{"choice":2,"correct":false,"title":"妊娠 35 週6日","explanation":"公式採点では不正答です。予定日を示すカレンダーが欠けており、35週6日との日数差をこの画面だけから確認できません。"},{"choice":3,"correct":true,"title":"妊娠 36 週5日","explanation":"公式正答は36週5日です。予定日を40週0日として逆算する問題ですが、カレンダーが未表示のため、具体的な計算過程は不明として扱います。"},{"choice":4,"correct":false,"title":"妊娠 36 週6日","explanation":"公式採点では不正答です。36週5日との1日の違いを確かめるためのカレンダーがなく、推測で理由を補いません。"}],"status":"UNKNOWN","review_reason":"原問題のカレンダーが現在の問題表示データに含まれず、予定日からの計算根拠を確認できない。公式正答3を維持して不明表示。","fixes_made":[]},"input_anchor":{"question":"看護師は、医師から A さんの母子健康手帳に受診時の妊娠週数と日数を記入す\nるよう依頼された。\nA さんの受診時の妊娠週数および日数で正しいのはどれか。","choices":["妊娠 35 週5日","妊娠 35 週6日","妊娠 36 週5日","妊娠 36 週6日"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A さん(30 歳、初産婦)は X 年2月5日に妊婦健康診査のために来院した。X 年2\n月のカレンダーに A さんの受診日と分娩予定日を示す。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":103,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[46],"case_pages":[46],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A103"},"exam":111,"year":2022,"session":"AM","number":103},"sources":[]},{"id":"111-AM-106","record":{"id":"111-AM-106","choice_explanations":[{"choice":1,"correct":false,"title":"過期産である。","explanation":"40週5日は過期産の時期ではありません。分娩予定日を過ぎることと、過期産の区分に達することを区別します。"},{"choice":2,"correct":false,"title":"高年妊婦である。","explanation":"34歳は本問の高年妊婦の区分には該当しません。初産かどうかという条件と年齢を確認します。"},{"choice":3,"correct":true,"title":"胎児心拍数基線は正常である。","explanation":"胎児心拍数基線130bpmは正常範囲内です。ただし胎児の評価では基線だけでなく、変動や一過性の変化も併せて判断します。"},{"choice":4,"correct":false,"title":"低出生体重児となる可能性が高い。","explanation":"推定体重3,300gは低出生体重を示す値ではありません。また推定胎児体重と実際の出生体重は区別します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"入院時の A さんと胎児の状態で正しいのはどれか。","choices":["過期産である。","高年妊婦である。","胎児心拍数基線は正常である。","低出生体重児となる可能性が高い。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A さん(34 歳、初産婦)は順調な妊娠経過であった。妊娠 40 週5日の午前8時、10\n分毎の規則的な子宮収縮を主訴に来院し、医師の診察の結果、入院となった。入院時\nの胎児心拍数基線は 130 bpm、胎児の推定体重は 3,300 g であった。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":106,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[48],"case_pages":[48],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A106"},"exam":111,"year":2022,"session":"AM","number":106},"sources":[{"title":"日本産婦人科医会：胎児心拍数の評価","url":"https://www.jaog.or.jp/lecture/2-スタートアップ２（ctgの読み方）/"},{"title":"日本産婦人科医会：高年初産","url":"https://www.jaog.or.jp/qa/confinement/jyosei180124/"}]},{"id":"111-AM-107","record":{"id":"111-AM-107","choice_explanations":[{"choice":1,"correct":false,"title":"別室での休憩を促す。","explanation":"夫の休息も必要ですが、今は妻を助けたいと具体的な方法を尋ねています。まず参加できる援助を伝えます。"},{"choice":2,"correct":false,"title":"分娩経過について説明する。","explanation":"経過の説明は安心につながりますが、痛みに対して何ができるかという質問への直接の支援としては不十分です。"},{"choice":3,"correct":false,"title":"A さんと病棟内を歩行するように促す。","explanation":"歩行が役立つ場面もありますが、陣痛時の腰痛への支援を求めているため、まずその場でできる疼痛緩和を伝えます。"},{"choice":4,"correct":true,"title":"産痛を緩和するためのマッサージの実施を促す。","explanation":"Aさんが心地よい部位や強さを確認し、腰のマッサージなどを夫と行います。夫が具体的に参加でき、本人の安心や疼痛緩和にもつながります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"午後0時、助産師が内診したところ、子宮口開大4cm であった。A さんは陣痛\n発作時に腰痛を強く訴えている。A さんの夫(37 歳)は、夫婦で出産体験を共有し\nたいと両親学級を受講しており、入院時から A さんに付き添っている。夫は A さ\nんの陣痛発作時、心配そうに A さんの様子を見つめているが、陣痛間欠時にはう\nとうとしている。訪室した看護師に、夫から｢妻が痛がっているのですが、どうす\nればよいでしょう｣と質問があった。胎児心拍数基線は 140 bpm であった。\nこのときの看護師の夫への対応で最も適切なのはどれか。","choices":["別室での休憩を促す。","分娩経過について説明する。","A さんと病棟内を歩行するように促す。","産痛を緩和するためのマッサージの実施を促す。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A さん(34 歳、初産婦)は順調な妊娠経過であった。妊娠 40 週5日の午前8時、10\n分毎の規則的な子宮収縮を主訴に来院し、医師の診察の結果、入院となった。入院時\nの胎児心拍数基線は 130 bpm、胎児の推定体重は 3,300 g であった。","preceding_context":[{"id":"111-AM-106","question":"入院時の A さんと胎児の状態で正しいのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":107,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[48],"case_pages":[48],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A107"},"exam":111,"year":2022,"session":"AM","number":107},"sources":[]},{"id":"111-AM-108","record":{"id":"111-AM-108","choice_explanations":[{"choice":1,"correct":false,"title":"｢リラックスするためにお風呂に入りましょう｣","explanation":"分娩が進行し破水もしているこの時点では、入浴よりその場で呼吸を整えて支える対応が適切です。"},{"choice":2,"correct":false,"title":"｢赤ちゃんのために我慢しましょう｣","explanation":"我慢を求めるだけではつらさへの支援にならず、本人を追い詰めるおそれがあります。具体的に力を抜く方法を伝えます。"},{"choice":3,"correct":false,"title":"｢トイレに行って排便しましょう｣","explanation":"胎児の下降による圧迫で便意に似た感覚が生じることがあります。排便と決めつけて一人でトイレへ促すのは適切ではありません。"},{"choice":4,"correct":true,"title":"｢息を吐いて力を抜きましょう｣","explanation":"子宮口はまだ全開大していないため、呼気に合わせて余分な力を抜けるよう支援します。つらさを受け止めながら一緒に呼吸を整えます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんの分娩は順調に進行した。午後5時に破水し、午後6時には子宮口開大\n8cm となった。｢便が出そうです。もう、これ以上頑張れない｣と陣痛発作時には\n全身に力が入っている。\nこのときの看護師の声かけで正しいのはどれか。","choices":["｢リラックスするためにお風呂に入りましょう｣","｢赤ちゃんのために我慢しましょう｣","｢トイレに行って排便しましょう｣","｢息を吐いて力を抜きましょう｣"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A さん(34 歳、初産婦)は順調な妊娠経過であった。妊娠 40 週5日の午前8時、10\n分毎の規則的な子宮収縮を主訴に来院し、医師の診察の結果、入院となった。入院時\nの胎児心拍数基線は 130 bpm、胎児の推定体重は 3,300 g であった。","preceding_context":[{"id":"111-AM-106","question":"入院時の A さんと胎児の状態で正しいのはどれか。"},{"id":"111-AM-107","question":"午後0時、助産師が内診したところ、子宮口開大4cm であった。A さんは陣痛\n発作時に腰痛を強く訴えている。A さんの夫(37 歳)は、夫婦で出産体験を共有し\nたいと両親学級を受講しており、入院時から A さんに付き添っている。夫は A さ\nんの陣痛発作時、心配そうに A さんの様子を見つめているが、陣痛間欠時にはう\nとうとしている。訪室した看護師に、夫から｢妻が痛がっているのですが、どうす\nればよいでしょう｣と質問があった。胎児心拍数基線は 140 bpm であった。\nこのときの看護師の夫への対応で最も適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":108,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[49],"case_pages":[48],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A108"},"exam":111,"year":2022,"session":"AM","number":108},"sources":[]},{"id":"111-AM-109","record":{"id":"111-AM-109","choice_explanations":[{"choice":1,"correct":false,"title":"ナルコレプシー\nnarcolepsy","explanation":"ナルコレプシーでは日中の強い眠気や睡眠発作などが中心です。睡眠中に夢に合わせたような激しい動作をする症状とは異なります。"},{"choice":2,"correct":true,"title":"レム睡眠行動障害\nREM sleep behavior disorder","explanation":"レム睡眠中に筋肉の抑制が十分に働かず、夢の内容に沿った叫びや動作が出ます。レビー小体型認知症との関連も重要です。"},{"choice":3,"correct":false,"title":"睡眠時無呼吸症候群\nsleep apnea syndrome","explanation":"睡眠中の呼吸停止やいびきなどが主な特徴です。設問では呼吸より、睡眠中の発声・動作の異常が示されています。"},{"choice":4,"correct":false,"title":"睡眠・覚醒スケジュール障害\nsleep-wake schedule disorder","explanation":"眠る時刻と起きる時刻のずれなどを扱う障害です。夢に関連した行動が現れることとは区別します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんに出現している睡眠障害はどれか。","choices":["ナルコレプシー\nnarcolepsy","レム睡眠行動障害\nREM sleep behavior disorder","睡眠時無呼吸症候群\nsleep apnea syndrome","睡眠・覚醒スケジュール障害\nsleep-wake schedule disorder"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(68 歳、男性、自営業)は、妻(73 歳)と2人暮らし。A さんの就寝時刻は 21\n時で、入眠後 90 分以上が経過した睡眠中に、大声で叫び、腕や足を振り回し暴れる\n行動が繰り返しみられたが、昼寝では夜間のような行動はみられない。日中、台所で\n子どもが遊んでいると言い、妻が台所を確認しても誰もいないことが何度かあった。\n心配になった妻が A さんとともに病院を受診し、Lewy〈レビー〉小体型認知症と診断\ndementia with Lewy bodies\nされた。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":109,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[50],"case_pages":[50],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A109"},"exam":111,"year":2022,"session":"AM","number":109},"sources":[]},{"id":"111-AM-110","record":{"id":"111-AM-110","choice_explanations":[{"choice":1,"correct":false,"title":"A さんに別の病室へ移動することを提案する。","explanation":"部屋の移動が必要になる場合はありますが、環境の変化で混乱が増すこともあります。まず差し迫った転倒を防ぐ対応が重要です。"},{"choice":2,"correct":true,"title":"歩行時は看護師と一緒に歩くように声をかける。","explanation":"幻視をよける動作と動きにくさがあり、転倒のおそれがあります。そばで一緒に歩き、安全を支えながら本人の不安も確かめます。"},{"choice":3,"correct":false,"title":"怒りをコントロールできる方法を見つけるように伝える。","explanation":"認知症の症状がある人に自己管理だけを求めても解決しません。興奮のきっかけや環境を調整して支えます。"},{"choice":4,"correct":false,"title":"床に子どもがいるように見えるのは幻視であることを説明する。","explanation":"幻視だと説明することが役立つ場合もありますが、否定だけでは安心につながりません。ここでは実際に転びそうになっているため、安全確保を優先します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんは定期的に精神科外来を受診することになった。受診6か月後、A さん\nは足の筋肉がこわばり、動きが鈍くなった。また、幻視を訴える頻度が増え、感情\nのコントロールができず、妻に暴言や暴力を振るうことが多くなったため、精神科\n病院に入院となった。入院2日、A さんは歩行時に床に子どもが寝転んでいると\n訴えて、子どもをよける動作で転びそうになった。また、突然、興奮して大声で怒\nり出すため、同室患者が苦情を訴えた。\nA さんへの看護師の対応で適切なのはどれか。","choices":["A さんに別の病室へ移動することを提案する。","歩行時は看護師と一緒に歩くように声をかける。","怒りをコントロールできる方法を見つけるように伝える。","床に子どもがいるように見えるのは幻視であることを説明する。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(68 歳、男性、自営業)は、妻(73 歳)と2人暮らし。A さんの就寝時刻は 21\n時で、入眠後 90 分以上が経過した睡眠中に、大声で叫び、腕や足を振り回し暴れる\n行動が繰り返しみられたが、昼寝では夜間のような行動はみられない。日中、台所で\n子どもが遊んでいると言い、妻が台所を確認しても誰もいないことが何度かあった。\n心配になった妻が A さんとともに病院を受診し、Lewy〈レビー〉小体型認知症と診断\ndementia with Lewy bodies\nされた。","preceding_context":[{"id":"111-AM-109","question":"A さんに出現している睡眠障害はどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":110,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[50],"case_pages":[50],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A110"},"exam":111,"year":2022,"session":"AM","number":110},"sources":[]},{"id":"111-AM-111","record":{"id":"111-AM-111","choice_explanations":[{"choice":1,"correct":true,"title":"短期入所〈ショートステイ〉","explanation":"主な介護者が一時的に不在になる間、宿泊して生活上の支援を受けられます。妻の入院期間の介護を補う目的に合います。"},{"choice":2,"correct":false,"title":"精神科病院への入院","explanation":"病状悪化など治療の必要性は示されていません。介護者の不在だけを理由に精神科入院を選ぶのではありません。"},{"choice":3,"correct":false,"title":"重度訪問介護","explanation":"対象や支援内容に要件がある障害福祉サービスです。本問では一時的な介護者不在を補う短期入所が直接合います。"},{"choice":4,"correct":false,"title":"同行援護","explanation":"同行援護は視覚障害のある人の外出を支援するサービスです。認知症患者の介護者不在に対応する宿泊サービスではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんの入院中に妻は自営業の仕事を減らし、自宅で A さんを介護する準備を\n整えた。A さんが退院し、3か月が経過したころ、A さんの妻が3週間程度の予\n定で入院して手術をすることになった。A さんは杖を使用し散歩ができるが、入\n浴や食事については妻が介護を行っていた。\n妻の入院中に A さんに必要なサービスはどれか。","choices":["短期入所〈ショートステイ〉","精神科病院への入院","重度訪問介護","同行援護"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":"A さん(68 歳、男性、自営業)は、妻(73 歳)と2人暮らし。A さんの就寝時刻は 21\n時で、入眠後 90 分以上が経過した睡眠中に、大声で叫び、腕や足を振り回し暴れる\n行動が繰り返しみられたが、昼寝では夜間のような行動はみられない。日中、台所で\n子どもが遊んでいると言い、妻が台所を確認しても誰もいないことが何度かあった。\n心配になった妻が A さんとともに病院を受診し、Lewy〈レビー〉小体型認知症と診断\ndementia with Lewy bodies\nされた。","preceding_context":[{"id":"111-AM-109","question":"A さんに出現している睡眠障害はどれか。"},{"id":"111-AM-110","question":"A さんは定期的に精神科外来を受診することになった。受診6か月後、A さん\nは足の筋肉がこわばり、動きが鈍くなった。また、幻視を訴える頻度が増え、感情\nのコントロールができず、妻に暴言や暴力を振るうことが多くなったため、精神科\n病院に入院となった。入院2日、A さんは歩行時に床に子どもが寝転んでいると\n訴えて、子どもをよける動作で転びそうになった。また、突然、興奮して大声で怒\nり出すため、同室患者が苦情を訴えた。\nA さんへの看護師の対応で適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":111,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[51],"case_pages":[50],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A111"},"exam":111,"year":2022,"session":"AM","number":111},"sources":[]},{"id":"111-AM-112","record":{"id":"111-AM-112","choice_explanations":[{"choice":1,"correct":false,"title":"脱 毛","explanation":"栄養不良で脱毛が生じることはありますが、栄養補給開始直後に優先して見逃してはいけない変化ではありません。"},{"choice":2,"correct":true,"title":"浮 腫","explanation":"高度の低栄養で栄養を再開すると、再栄養に伴う電解質や体液の変化が起こり得ます。浮腫はその手掛かりで、体重や循環・呼吸状態も観察します。"},{"choice":3,"correct":false,"title":"抑うつ","explanation":"気分の評価は必要ですが、治療開始早期は栄養補給に伴う身体的な合併症への注意が優先されます。"},{"choice":4,"correct":false,"title":"嚥下障害","explanation":"嚥下障害を示す情報はありません。食事を拒む心理と飲み込む機能の障害を同じものとして扱いません。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"治療開始早期に看護師が最も注意すべき観察項目はどれか。","choices":["脱 毛","浮 腫","抑うつ","嚥下障害"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(23 歳、女性)は大学を卒業後、会社に就職して1人暮らしを始めた。入社\n後に｢会社の制服が似合うようになりたい｣とダイエットを始め、次第にるいそうが目\n立つようになった。｢太るのが怖い｣と言って食事を拒否するようになり、体重は1年\n間で 10 kg 減少した。しかし、本人は｢まだ太っているから、痩せないといけない｣と\n話していた。久しぶりに A さんと会った母親が、過度のるいそうを心配して、内科\n受診を勧めた。内科ではるいそう以外に大きな異常を認めず、精神科受診を勧められ\nた。精神科では神経性無食欲症と診断され、外来通院を開始した。その後、低血糖に\nanorexia nervosa\nよるふらつきのため職場で頻回に転倒するようになった。それでも食事を十分に摂ら\nないため、精神科病棟へ入院した。入院時、身長 166 cm、体重 36 kg であった。入\n院後、食事のほかに点滴による栄養補給が始まった。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":112,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[52],"case_pages":[52],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A112"},"exam":111,"year":2022,"session":"AM","number":112},"sources":[{"title":"厚生労働科学研究：神経性やせ症の再栄養時の浮腫","url":"https://mhlw-grants.niph.go.jp/system/files/2013/133151/201324013B/201324013B0032.pdf"}]},{"id":"111-AM-113","record":{"id":"111-AM-113","choice_explanations":[{"choice":1,"correct":false,"title":"体重測定の回数を増やす。","explanation":"体重へのこだわりが強いため、測定回数を増やすだけでは不安を強める可能性があります。計画に沿って確認し、思いを聴きます。"},{"choice":2,"correct":false,"title":"鏡で A さんの全身を映して見せる。","explanation":"見た目を示すだけでは身体像のゆがみや恐怖が解消するとは限らず、羞恥や反発を招くことがあります。"},{"choice":3,"correct":true,"title":"痩せたいと思う気持ちについて話し合う。","explanation":"痩せたいという気持ちや太ることへの恐怖を聴き、背景を理解します。頭ごなしに否定せず、治療に取り組める関係を作ります。"},{"choice":4,"correct":false,"title":"A さんは他の患者よりも痩せていると伝える。","explanation":"他者との体型比較は、さらに比較や競争へのこだわりを強める可能性があります。体型の優劣を示す対応は避けます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"入院後2週が経過した。食事のときに A さんは食べ物を細かく刻み、1時間以\n上時間をかけるが、摂取量は全体の 25 % 程度である。時間があるとベッド上でい\nつもストレッチを行っている。A さんと話し合ったところ｢私はこの病棟で太って\nいるほうだから少しでも痩せなきゃ｣と話した。\n看護師の関わりとして適切なのはどれか。","choices":["体重測定の回数を増やす。","鏡で A さんの全身を映して見せる。","痩せたいと思う気持ちについて話し合う。","A さんは他の患者よりも痩せていると伝える。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A さん(23 歳、女性)は大学を卒業後、会社に就職して1人暮らしを始めた。入社\n後に｢会社の制服が似合うようになりたい｣とダイエットを始め、次第にるいそうが目\n立つようになった。｢太るのが怖い｣と言って食事を拒否するようになり、体重は1年\n間で 10 kg 減少した。しかし、本人は｢まだ太っているから、痩せないといけない｣と\n話していた。久しぶりに A さんと会った母親が、過度のるいそうを心配して、内科\n受診を勧めた。内科ではるいそう以外に大きな異常を認めず、精神科受診を勧められ\nた。精神科では神経性無食欲症と診断され、外来通院を開始した。その後、低血糖に\nanorexia nervosa\nよるふらつきのため職場で頻回に転倒するようになった。それでも食事を十分に摂ら\nないため、精神科病棟へ入院した。入院時、身長 166 cm、体重 36 kg であった。入\n院後、食事のほかに点滴による栄養補給が始まった。","preceding_context":[{"id":"111-AM-112","question":"治療開始早期に看護師が最も注意すべき観察項目はどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":113,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[52],"case_pages":[52],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A113"},"exam":111,"year":2022,"session":"AM","number":113},"sources":[]},{"id":"111-AM-114","record":{"id":"111-AM-114","choice_explanations":[{"choice":1,"correct":true,"title":"家族療法","explanation":"本人と家族の希望のずれや、コミュニケーションを扱う必要があります。誰かを原因と決めつけず、家族が回復を支えられる関係を整えます。"},{"choice":2,"correct":false,"title":"作業療法","explanation":"活動を通じた回復支援に役立ちますが、今示されている親子の対立や家族の関わりに直接取り組む方法ではありません。"},{"choice":3,"correct":false,"title":"自律訓練法","explanation":"緊張の緩和に用いる方法です。退院後の生活をめぐる家族の関係調整を主目的とする療法ではありません。"},{"choice":4,"correct":false,"title":"精神分析療法","explanation":"内的な葛藤などを扱う療法ですが、この場面の具体的な家族間の調整に最も直接対応するのは家族療法です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"入院後3か月が経過した。A さんは体重が 41 kg まで増加し、主治医と相談し\nて、退院の準備をすることになった。看護師に対して、A さんは｢退院後はすぐに\n仕事をしたい｣と話したが、母親は｢ゆっくり自宅で休養してほしい｣と話した。母\n親の面会時に、今後の仕事や生活に関する話題が出ると、A さんはイライラして\n母親と口論になることが多くなった。父親は仕事が忙しいことを理由に、面会に来\nたのは一度のみであった。\n今後導入する必要性が最も高いのはどれか。","choices":["家族療法","作業療法","自律訓練法","精神分析療法"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":"A さん(23 歳、女性)は大学を卒業後、会社に就職して1人暮らしを始めた。入社\n後に｢会社の制服が似合うようになりたい｣とダイエットを始め、次第にるいそうが目\n立つようになった。｢太るのが怖い｣と言って食事を拒否するようになり、体重は1年\n間で 10 kg 減少した。しかし、本人は｢まだ太っているから、痩せないといけない｣と\n話していた。久しぶりに A さんと会った母親が、過度のるいそうを心配して、内科\n受診を勧めた。内科ではるいそう以外に大きな異常を認めず、精神科受診を勧められ\nた。精神科では神経性無食欲症と診断され、外来通院を開始した。その後、低血糖に\nanorexia nervosa\nよるふらつきのため職場で頻回に転倒するようになった。それでも食事を十分に摂ら\nないため、精神科病棟へ入院した。入院時、身長 166 cm、体重 36 kg であった。入\n院後、食事のほかに点滴による栄養補給が始まった。","preceding_context":[{"id":"111-AM-112","question":"治療開始早期に看護師が最も注意すべき観察項目はどれか。"},{"id":"111-AM-113","question":"入院後2週が経過した。食事のときに A さんは食べ物を細かく刻み、1時間以\n上時間をかけるが、摂取量は全体の 25 % 程度である。時間があるとベッド上でい\nつもストレッチを行っている。A さんと話し合ったところ｢私はこの病棟で太って\nいるほうだから少しでも痩せなきゃ｣と話した。\n看護師の関わりとして適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":114,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[53],"case_pages":[52],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A114"},"exam":111,"year":2022,"session":"AM","number":114},"sources":[]},{"id":"111-AM-115","record":{"id":"111-AM-115","choice_explanations":[{"choice":1,"correct":false,"title":"低血糖","explanation":"低血糖は本問で説明するレボドパの代表的な副作用ではありません。薬剤ごとの副作用を対応させます。"},{"choice":2,"correct":false,"title":"体重増加","explanation":"体重増加を、この増量時に特に説明する代表的な副作用とはしません。症状と薬効の変動を観察します。"},{"choice":3,"correct":false,"title":"呼吸器症状","explanation":"呼吸器症状が起きた際の評価は必要ですが、本問で問う代表的な副作用としては不随意運動を選びます。"},{"choice":4,"correct":true,"title":"不随意運動","explanation":"ジスキネジアと呼ばれる、本人の意思に関係ない動きが生じることがあります。出現時間と服薬との関係を記録し、処方調整につなげます。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"外来看護師が A さんと夫に説明する副作用〈有害事象〉の内容で正しいのはどれ\nか。","choices":["低血糖","体重増加","呼吸器症状","不随意運動"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A さん(73 歳、女性)は夫(73 歳)と2人暮らし。6年前に Parkinson〈パーキンソン〉\nParkinson disease\n病と診断され、レボドパ〈L-dopa〉を1日3回内服している。Hoehn-Yahr〈ホーエ\nン・ヤール〉重症度分類のステージⅢ、要介護1である。夫が付き添い神経内科外来\nに月1回、杖歩行で通院している。外来受診のとき、A さんは足がすくんで転びや\nすくなったことを主治医に相談し、レボドパ〈L-dopa〉を1日4回に増量して様子を\n見ることになった。A さんと夫は薬の副作用〈有害事象〉について外来看護師に尋ね\nた。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":115,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[54],"case_pages":[54],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A115"},"exam":111,"year":2022,"session":"AM","number":115},"sources":[{"title":"PMDA：レボドパの副作用","url":"https://www.pmda.go.jp/PmdaSearch/iyakuDetail/ResultDataSetPDF/180095_1164400A1045_1_11"}]},{"id":"111-AM-116","record":{"id":"111-AM-116","choice_explanations":[{"choice":1,"correct":false,"title":"浴室の床の素材","explanation":"床の滑りやすさは確認しますが、今回はいつもと違う時間帯での転倒です。薬効に伴う動きやすさの変化を優先して把握します。"},{"choice":2,"correct":false,"title":"居室から浴室までの距離","explanation":"移動距離も負担に関係しますが、時間帯が変わったという手掛かりから、まずADLの日内変動を確認します。"},{"choice":3,"correct":false,"title":"転倒による打撲痕の状態","explanation":"外傷の確認は必要ですが、今後の入浴を安全にするための最優先の評価としては動作能力の時間帯による違いです。"},{"choice":4,"correct":true,"title":"日常生活動作〈ADL〉の日内変動","explanation":"レボドパの効果などにより、動きやすい時間と動きにくい時間が生じます。本人の生活の中で確認し、安全に動ける時間帯に入浴を調整します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"1か月後の外来受診のときに、A さんは｢いつもと違う時間に入浴したら転んで\nしまった。怪我をしなくてよかった｣と主治医に話した。主治医から勧められ、A\nさんは訪問看護を週に1回利用することになった。\n今後 A さんが安全な入浴をするために訪問看護師がアセスメントする内容で最\nも優先するのはどれか。","choices":["浴室の床の素材","居室から浴室までの距離","転倒による打撲痕の状態","日常生活動作〈ADL〉の日内変動"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A さん(73 歳、女性)は夫(73 歳)と2人暮らし。6年前に Parkinson〈パーキンソン〉\nParkinson disease\n病と診断され、レボドパ〈L-dopa〉を1日3回内服している。Hoehn-Yahr〈ホーエ\nン・ヤール〉重症度分類のステージⅢ、要介護1である。夫が付き添い神経内科外来\nに月1回、杖歩行で通院している。外来受診のとき、A さんは足がすくんで転びや\nすくなったことを主治医に相談し、レボドパ〈L-dopa〉を1日4回に増量して様子を\n見ることになった。A さんと夫は薬の副作用〈有害事象〉について外来看護師に尋ね\nた。","preceding_context":[{"id":"111-AM-115","question":"外来看護師が A さんと夫に説明する副作用〈有害事象〉の内容で正しいのはどれ\nか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":116,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[54],"case_pages":[54],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A116"},"exam":111,"year":2022,"session":"AM","number":116},"sources":[]},{"id":"111-AM-117","record":{"id":"111-AM-117","choice_explanations":[{"choice":1,"correct":true,"title":"通所介護","explanation":"通所先で活動や交流、必要な介護を受けられます。本人の希望に合い、夫が自分の時間を持つ支援にもつながります。"},{"choice":2,"correct":false,"title":"訪問介護","explanation":"自宅での生活援助には役立ちますが、本人が外で活動やレクリエーションに参加したいという希望には直接合いません。"},{"choice":3,"correct":false,"title":"訪問入浴介護","explanation":"自宅での入浴を支えるサービスです。現在の希望である交流や活動参加を中心とするものではありません。"},{"choice":4,"correct":false,"title":"短期入所生活介護","explanation":"宿泊して介護を受ける方法ですが、今回は日中の活動への参加が希望です。まず通所介護が合います。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"3か月後、A さんは｢夫は家事を楽しんでいるようで助かっていますが、友人と\n外出したいと言っています。私も最近は転ぶこともなくなったので、身体を動かし\nたり、レクリエーションに参加してみたいです｣と訪問看護師に話した。\n訪問看護師が A さんに提案するサービスで最も適切なのはどれか。","choices":["通所介護","訪問介護","訪問入浴介護","短期入所生活介護"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":"A さん(73 歳、女性)は夫(73 歳)と2人暮らし。6年前に Parkinson〈パーキンソン〉\nParkinson disease\n病と診断され、レボドパ〈L-dopa〉を1日3回内服している。Hoehn-Yahr〈ホーエ\nン・ヤール〉重症度分類のステージⅢ、要介護1である。夫が付き添い神経内科外来\nに月1回、杖歩行で通院している。外来受診のとき、A さんは足がすくんで転びや\nすくなったことを主治医に相談し、レボドパ〈L-dopa〉を1日4回に増量して様子を\n見ることになった。A さんと夫は薬の副作用〈有害事象〉について外来看護師に尋ね\nた。","preceding_context":[{"id":"111-AM-115","question":"外来看護師が A さんと夫に説明する副作用〈有害事象〉の内容で正しいのはどれ\nか。"},{"id":"111-AM-116","question":"1か月後の外来受診のときに、A さんは｢いつもと違う時間に入浴したら転んで\nしまった。怪我をしなくてよかった｣と主治医に話した。主治医から勧められ、A\nさんは訪問看護を週に1回利用することになった。\n今後 A さんが安全な入浴をするために訪問看護師がアセスメントする内容で最\nも優先するのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":117,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[55],"case_pages":[54],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A117"},"exam":111,"year":2022,"session":"AM","number":117},"sources":[]},{"id":"111-AM-118","record":{"id":"111-AM-118","choice_explanations":[{"choice":1,"correct":true,"title":"症状が日常生活に与える影響","explanation":"食事、睡眠、清潔、安全などが症状によってどの程度妨げられているかを把握します。入院当日に必要な援助と危険の評価に直結します。"},{"choice":2,"correct":false,"title":"アルバイト先の人間関係","explanation":"職場の背景も確認しますが、現在の生活と安全に及ぼす症状の影響を優先します。人間関係だけを原因と決めつけません。"},{"choice":3,"correct":false,"title":"医療用語の理解力","explanation":"分かる言葉で説明する配慮は必要ですが、医療用語を知っているかより、今の困りごとを理解できる方法で聴くことが重要です。"},{"choice":4,"correct":false,"title":"精神疾患の家族歴","explanation":"家族歴は診療情報の一つですが、入院直後の生活援助の優先順位を決める情報としては症状の影響が先です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"入院当日に看護師が行う情報収集で最も優先するのはどれか。","choices":["症状が日常生活に与える影響","アルバイト先の人間関係","医療用語の理解力","精神疾患の家族歴"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":"A さん(28 歳、女性、外国籍)は3年前に日本人の夫と結婚し来日した。簡単な日\n本語を話せたため、来日した半年後からコンビニエンスストアでアルバイトを始め\nた。最近になり、夫は仕事で帰りが遅くなることが多くなった。A さんが｢お客さん\nが自分の悪口を言っている｣と話したが、夫は気にしなかった。その後、アルバイト\n先の上司から｢A さんが奇声を発している｣｢ぶつぶつと独り言を言って歩き回ってい\nる｣と夫に連絡があった。夫が病院に付添い精神科外来を受診し、統合失調症と診断\nschizophrenia\nされて入院となった。入院時、A さんの髪は乱れ、誰かに見張られている気がする\nと怯えていた。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":118,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[56],"case_pages":[56],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A118"},"exam":111,"year":2022,"session":"AM","number":118},"sources":[]},{"id":"111-AM-119","record":{"id":"111-AM-119","choice_explanations":[{"choice":1,"correct":true,"title":"｢A さんの症状と対応について学ぶことができます｣","explanation":"病気の特徴や対応の工夫を学び、家族自身の悩みも整理できます。家族が一人で抱え込まず、支援を受けられる機会として勧めます。"},{"choice":2,"correct":false,"title":"｢ご家族に参加して頂くことが退院の条件です｣","explanation":"家族心理教育への参加を一律に退院の条件とするものではありません。目的を説明し、家族の意思と状況を尊重します。"},{"choice":3,"correct":false,"title":"｢家族同士の自助グループです｣","explanation":"家族同士の交流を含む場合はありますが、専門職による情報提供や支援を含む心理教育と、自助グループは同じものではありません。"},{"choice":4,"correct":false,"title":"｢匿名で参加できます｣","explanation":"参加方法の規定を確認せず、匿名で参加できると保証してはいけません。実施内容や情報の取り扱いを具体的に説明します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"入院後、担当看護師は毎日面会に来ている夫の表情が気になり声をかけた。夫は\n｢先生から統合失調症には様々な症状があるとお聞きしました。入院して妻は落ち\nschizophrenia\nつきましたが、これからどう接していけばいいのか悩んでいます｣と話した。担当\n看護師はチームカンファレンスで夫の様子を伝え、主治医の判断で、夫に家族心理\n教育への参加を促すことになった。\n担当看護師が夫に家族心理教育を勧める声かけで適切なのはどれか。","choices":["｢A さんの症状と対応について学ぶことができます｣","｢ご家族に参加して頂くことが退院の条件です｣","｢家族同士の自助グループです｣","｢匿名で参加できます｣"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":"A さん(28 歳、女性、外国籍)は3年前に日本人の夫と結婚し来日した。簡単な日\n本語を話せたため、来日した半年後からコンビニエンスストアでアルバイトを始め\nた。最近になり、夫は仕事で帰りが遅くなることが多くなった。A さんが｢お客さん\nが自分の悪口を言っている｣と話したが、夫は気にしなかった。その後、アルバイト\n先の上司から｢A さんが奇声を発している｣｢ぶつぶつと独り言を言って歩き回ってい\nる｣と夫に連絡があった。夫が病院に付添い精神科外来を受診し、統合失調症と診断\nschizophrenia\nされて入院となった。入院時、A さんの髪は乱れ、誰かに見張られている気がする\nと怯えていた。","preceding_context":[{"id":"111-AM-118","question":"入院当日に看護師が行う情報収集で最も優先するのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":119,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[56],"case_pages":[56],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A119"},"exam":111,"year":2022,"session":"AM","number":119},"sources":[]},{"id":"111-AM-120","record":{"id":"111-AM-120","choice_explanations":[{"choice":1,"correct":false,"title":"共同生活援助〈グループホーム〉","explanation":"共同生活の場を提供するサービスです。現在は住まいの変更より、日中の活動と孤立の軽減が本人の希望に合います。"},{"choice":2,"correct":false,"title":"短期入所〈ショートステイ〉","explanation":"一時的な宿泊による支援です。継続的な活動や交流の機会を作るという目的にはデイケアが適しています。"},{"choice":3,"correct":false,"title":"通訳のボランティア","explanation":"言語の支援が必要な場合は役立ちますが、この場面では手芸や人との交流への希望が示されています。"},{"choice":4,"correct":true,"title":"精神科デイケア","explanation":"日中に通い、活動や対人交流を通して生活のリズムと社会参加を支えます。手芸が楽しかったことや一人で過ごす寂しさに応じた提案です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"入院後2か月が経過した。A さんは独り言を言うことはあったが、他の入院患\n者と口論になることはなかった。作業療法士から｢A さんは手先が器用で、作業療\n法中は楽しそうに過ごしています｣と情報を得た。退院に向けた担当看護師との面\n談で、A さんは｢手芸が楽しかった｣｢家に1人でいると寂しい｣と話した。\n退院に向けて A さんに提案する社会資源として適切なのはどれか。","choices":["共同生活援助〈グループホーム〉","短期入所〈ショートステイ〉","通訳のボランティア","精神科デイケア"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A さん(28 歳、女性、外国籍)は3年前に日本人の夫と結婚し来日した。簡単な日\n本語を話せたため、来日した半年後からコンビニエンスストアでアルバイトを始め\nた。最近になり、夫は仕事で帰りが遅くなることが多くなった。A さんが｢お客さん\nが自分の悪口を言っている｣と話したが、夫は気にしなかった。その後、アルバイト\n先の上司から｢A さんが奇声を発している｣｢ぶつぶつと独り言を言って歩き回ってい\nる｣と夫に連絡があった。夫が病院に付添い精神科外来を受診し、統合失調症と診断\nschizophrenia\nされて入院となった。入院時、A さんの髪は乱れ、誰かに見張られている気がする\nと怯えていた。","preceding_context":[{"id":"111-AM-118","question":"入院当日に看護師が行う情報収集で最も優先するのはどれか。"},{"id":"111-AM-119","question":"入院後、担当看護師は毎日面会に来ている夫の表情が気になり声をかけた。夫は\n｢先生から統合失調症には様々な症状があるとお聞きしました。入院して妻は落ち\nschizophrenia\nつきましたが、これからどう接していけばいいのか悩んでいます｣と話した。担当\n看護師はチームカンファレンスで夫の様子を伝え、主治医の判断で、夫に家族心理\n教育への参加を促すことになった。\n担当看護師が夫に家族心理教育を勧める声かけで適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午前","question_number":120,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05a_01.pdf","pages":[57],"case_pages":[56],"sha256":"e853d7a86ef06ef41e8622f550dcf9bb3ffa48af076e412394070f237827bfb3"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"A120"},"exam":111,"year":2022,"session":"AM","number":120},"sources":[]},{"id":"111-PM-001","record":{"id":"111-PM-001","choice_explanations":[{"choice":1,"correct":false,"title":"6,800 万人","explanation":"6,800万人は、2017年推計の2065年の人口より少ない値です。将来推計は公表年と対象年、仮定によって値が変わる点を確認します。"},{"choice":2,"correct":true,"title":"8,800 万人","explanation":"2017年の将来推計人口では、2065年は約8,800万人と見込まれています。実測値ではなく、出生や死亡等の仮定を置いた推計です。"},{"choice":3,"correct":false,"title":"1億 800 万人","explanation":"1億800万人は、この推計で示された2065年の人口より多い値です。別の対象年の見通しと混同しません。"},{"choice":4,"correct":false,"title":"1億 2,800 万人","explanation":"1億2,800万人は当該推計の2065年の値ではありません。推計作成時に近い人口規模を、そのまま将来人口としないようにします。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"平成 29 年(2017 年)推計による日本の将来推計人口で令和 47 年(2065 年)の将来\n推計人口に最も近いのはどれか。","choices":["6,800 万人","8,800 万人","1億 800 万人","1億 2,800 万人"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":1,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[7],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B001"},"exam":111,"year":2022,"session":"PM","number":1},"sources":[{"title":"国立社会保障・人口問題研究所：2017年将来人口推計","url":"https://www.ipss.go.jp/pp-zenkoku/e/zenkoku_e2017/pp_zenkoku2017e_gaiyou.html"}]},{"id":"111-PM-002","record":{"id":"111-PM-002","choice_explanations":[{"choice":1,"correct":false,"title":"健康診断","explanation":"健康診断による早期発見は二次予防に当たります。病気が生じた後の機能回復や社会復帰を支える三次予防とは異なります。"},{"choice":2,"correct":false,"title":"早期治療","explanation":"早期発見に続く早期治療は二次予防です。病気の進行を早い段階で防ぐ目的です。"},{"choice":3,"correct":false,"title":"体力づくり","explanation":"健康な段階からの体力づくりは主に一次予防です。病気の発症を防ぐ取り組みとして考えます。"},{"choice":4,"correct":true,"title":"社会復帰のためのリハビリテーション","explanation":"病気による障害を軽減し、生活や仕事への復帰を支えます。発症後の機能と生活を回復する三次予防です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"生活習慣病の三次予防はどれか。","choices":["健康診断","早期治療","体力づくり","社会復帰のためのリハビリテーション"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":2,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[7],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B002"},"exam":111,"year":2022,"session":"PM","number":2},"sources":[]},{"id":"111-PM-003","record":{"id":"111-PM-003","choice_explanations":[{"choice":1,"correct":false,"title":"じん肺","explanation":"じん肺は粉じんの吸入による肺の障害です。画面を見ながら情報機器を操作する作業の代表的な障害ではありません。"},{"choice":2,"correct":true,"title":"視力障害","explanation":"長時間の画面注視は眼精疲労や見えにくさなどにつながります。画面の位置や明るさ、休憩などの作業条件を整えることが重要です。"},{"choice":3,"correct":false,"title":"振動障害","explanation":"振動障害は振動工具などによる影響が代表的です。情報機器作業の視覚的な負担とは原因が異なります。"},{"choice":4,"correct":false,"title":"皮膚障害","explanation":"皮膚障害は化学物質等への接触などで起こります。本問の情報機器作業で最も代表的な健康障害ではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"職業性疾病のうち情報機器〈VDT〉作業による健康障害はどれか。","choices":["じん肺","視力障害","振動障害","皮膚障害"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":3,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[7],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B003"},"exam":111,"year":2022,"session":"PM","number":3},"sources":[]},{"id":"111-PM-004","record":{"id":"111-PM-004","choice_explanations":[{"choice":1,"correct":false,"title":"医療給付","explanation":"医療給付は病気やけがの診療に関わるものです。介護保険の要支援者に対する区分とは異なります。"},{"choice":2,"correct":false,"title":"介護給付","explanation":"介護給付は要介護者に対する給付です。要支援状態に対する予防給付と区別します。"},{"choice":3,"correct":false,"title":"年金給付","explanation":"年金給付は所得保障に関係します。要支援者への介護予防サービスの給付ではありません。"},{"choice":4,"correct":true,"title":"予防給付","explanation":"要支援者に対する介護予防サービスは予防給付に位置付けられます。市町村の総合事業で行うサービスもあり、制度上の区分を確認します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"介護保険における被保険者の要支援状態に関する保険給付はどれか。","choices":["医療給付","介護給付","年金給付","予防給付"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":4,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[7],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B004"},"exam":111,"year":2022,"session":"PM","number":4},"sources":[{"title":"厚生労働省：要介護認定と予防給付","url":"https://www.mhlw.go.jp/topics/kaigo/nintei/gaiyo2.html"}]},{"id":"111-PM-005","record":{"id":"111-PM-005","choice_explanations":[{"choice":1,"correct":false,"title":"保健所長","explanation":"保健所長は看護師免許を付与する権限を持つ者ではありません。申請の窓口と免許を与える者を区別します。"},{"choice":2,"correct":true,"title":"厚生労働大臣","explanation":"看護師免許は厚生労働大臣が与えます。国家試験合格後の登録を経て免許を受ける仕組みです。"},{"choice":3,"correct":false,"title":"都道府県知事","explanation":"都道府県知事が与えるのは准看護師免許です。看護師と准看護師で付与者が異なります。"},{"choice":4,"correct":false,"title":"文部科学大臣","explanation":"文部科学大臣は教育行政に関係しますが、看護師免許を付与する者ではありません。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"看護師免許を付与するのはどれか。","choices":["保健所長","厚生労働大臣","都道府県知事","文部科学大臣"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":5,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[8],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B005"},"exam":111,"year":2022,"session":"PM","number":5},"sources":[{"title":"厚生労働省：保健師助産師看護師法","url":"https://www.mhlw.go.jp/web/t_doc?dataId=80078000&dataType=0&pageNo=1"}]},{"id":"111-PM-006","record":{"id":"111-PM-006","choice_explanations":[{"choice":1,"correct":false,"title":"衝 撃","explanation":"衝撃は危機に直面し混乱する最初の段階です。設問の第2段階ではありません。"},{"choice":2,"correct":false,"title":"承 認","explanation":"承認は現実を認めて向き合う段階で、防御的退行の後に位置付けられます。"},{"choice":3,"correct":false,"title":"適 応","explanation":"適応は現実に対処する新しい方法を見いだす段階です。危機の初期の第2段階とは異なります。"},{"choice":4,"correct":true,"title":"防御的退行","explanation":"第2段階は防御的退行です。現実を否認するなどして衝撃から自分を守ろうとする反応がみられます。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"フィンク, S. L. の危機モデルで第2段階はどれか。\nFink, S. L.","choices":["衝 撃","承 認","適 応","防御的退行"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":6,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[8],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B006"},"exam":111,"year":2022,"session":"PM","number":6},"sources":[{"title":"大阪大学看護学雑誌：フィンクの危機モデル","url":"https://ir.library.osaka-u.ac.jp/repo/ouka/all/56831/njou13_1_025.pdf"}]},{"id":"111-PM-008","record":{"id":"111-PM-008","choice_explanations":[{"choice":1,"correct":true,"title":"青年期","explanation":"選択肢中では青年期の基礎代謝量が最も多くなります。体格や筋肉量などに影響され、体重当たりの値を問う場合とは区別します。"},{"choice":2,"correct":false,"title":"壮年期","explanation":"壮年期は青年期に比べ基礎代謝量が低下する傾向があります。日々の活動による消費エネルギーとは別の指標です。"},{"choice":3,"correct":false,"title":"向老期","explanation":"向老期では筋肉量などの変化とともに基礎代謝量が低下します。選択肢中で最大となる時期ではありません。"},{"choice":4,"correct":false,"title":"老年期","explanation":"老年期は一般に基礎代謝量が低くなります。体温維持などに必要なエネルギーがゼロになるという意味ではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"次の時期のうち基礎代謝量が最も多いのはどれか。","choices":["青年期","壮年期","向老期","老年期"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":8,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[8],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B008"},"exam":111,"year":2022,"session":"PM","number":8},"sources":[]},{"id":"111-PM-009","record":{"id":"111-PM-009","choice_explanations":[{"choice":1,"correct":true,"title":"健康寿命","explanation":"健康上の問題で日常生活が制限されずに生活できる期間を示します。生存期間だけでなく、生活の状態に着目した指標です。"},{"choice":2,"correct":false,"title":"健康余命","explanation":"余命はある年齢から先の期間を表す言い方です。本問で示された指標の名称は健康寿命です。"},{"choice":3,"correct":false,"title":"平均寿命","explanation":"平均寿命は0歳の平均余命です。健康上の制限がある期間も含むため、健康寿命とは一致しません。"},{"choice":4,"correct":false,"title":"平均余命","explanation":"平均余命はある年齢の人が平均してあと何年生きるかを示します。健康上の制限がないという条件は含みません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"世界保健機関〈WHO〉が平成 12 年(2000 年)に提唱した｢健康上の問題で日常生活\nが制限されることなく生活できる期間｣はどれか。","choices":["健康寿命","健康余命","平均寿命","平均余命"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":9,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[9],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B009"},"exam":111,"year":2022,"session":"PM","number":9},"sources":[]},{"id":"111-PM-010","record":{"id":"111-PM-010","choice_explanations":[{"choice":1,"correct":false,"title":"1.0","explanation":"看護職員1人相当では、指定訪問看護ステーションの基本的な人員基準を満たしません。常勤換算で計算することも確認します。"},{"choice":2,"correct":false,"title":"1.5","explanation":"1.5人相当では必要数に不足します。実人数ではなく、勤務時間を常勤の勤務時間に換算した数です。"},{"choice":3,"correct":false,"title":"2.0","explanation":"2.0人相当も基準に届きません。複数職員がいることだけで基準を満たすとは限りません。"},{"choice":4,"correct":true,"title":"2.5","explanation":"基本的な基準は常勤換算で2.5人以上です。人数の計算に加え、常勤職員など他の要件も確認します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"指定訪問看護ステーションには常勤換算で( )人以上の看護職員を配置するこ\nとが定められている。\n( )に入るのはどれか。","choices":["1.0","1.5","2.0","2.5"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":10,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[9],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B010"},"exam":111,"year":2022,"session":"PM","number":10},"sources":[{"title":"厚生労働省：指定訪問看護の人員基準（2020年）","url":"https://www.mhlw.go.jp/web/t_doc?dataId=00tc4892&dataType=1"}]},{"id":"111-PM-011","record":{"id":"111-PM-011","choice_explanations":[{"choice":1,"correct":false,"title":"大静脈","explanation":"大静脈は全身から右心房へ血液を戻します。左心室から出る血管ではありません。"},{"choice":2,"correct":true,"title":"大動脈","explanation":"左心室から大動脈へ血液が送り出され、全身の動脈へ分配されます。体循環の出発点です。"},{"choice":3,"correct":false,"title":"肺静脈","explanation":"肺静脈は肺から左心房へ血液を戻します。酸素の多い血液が流れますが、心臓から出る血管ではありません。"},{"choice":4,"correct":false,"title":"肺動脈","explanation":"肺動脈は右心室から肺へ血液を送ります。体循環ではなく肺循環の血管です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"左心室から全身に血液を送り出す血管はどれか。","choices":["大静脈","大動脈","肺静脈","肺動脈"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":11,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[9],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B011"},"exam":111,"year":2022,"session":"PM","number":11},"sources":[]},{"id":"111-PM-012","record":{"id":"111-PM-012","choice_explanations":[{"choice":1,"correct":false,"title":"乳 腺","explanation":"乳腺は乳汁を導管を通じて分泌する外分泌腺です。血液中へホルモンを分泌する内分泌腺とは異なります。"},{"choice":2,"correct":false,"title":"涙 腺","explanation":"涙腺は涙を眼の表面へ分泌する外分泌腺です。"},{"choice":3,"correct":true,"title":"甲状腺","explanation":"甲状腺はホルモンを血液中へ分泌し、代謝などを調節します。導管を持たない内分泌器官です。"},{"choice":4,"correct":false,"title":"唾液腺","explanation":"唾液腺は導管を通して唾液を口腔内へ出す外分泌腺です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"内分泌器官はどれか。","choices":["乳 腺","涙 腺","甲状腺","唾液腺"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":12,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[9],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B012"},"exam":111,"year":2022,"session":"PM","number":12},"sources":[]},{"id":"111-PM-013","record":{"id":"111-PM-013","choice_explanations":[{"choice":1,"correct":false,"title":"間 脳","explanation":"間脳の視床下部は体温や内分泌、自律機能の調節に重要です。呼吸の基本的なリズムをつくる中枢の所在としては脳幹を選びます。"},{"choice":2,"correct":false,"title":"小 脳","explanation":"小脳は運動の協調や平衡などに関与します。呼吸中枢の代表的な所在ではありません。"},{"choice":3,"correct":false,"title":"大 脳","explanation":"大脳から呼吸を意識的に調節することはできますが、自動的な呼吸の基本中枢とは異なります。"},{"choice":4,"correct":true,"title":"脳 幹","explanation":"脳幹の延髄などが呼吸のリズムをつくり、橋などが調節します。意識していなくても呼吸を続けられる仕組みです。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"呼吸中枢があるのはどれか。","choices":["間 脳","小 脳","大 脳","脳 幹"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":13,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[10],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B013"},"exam":111,"year":2022,"session":"PM","number":13},"sources":[]},{"id":"111-PM-014","record":{"id":"111-PM-014","choice_explanations":[{"choice":1,"correct":false,"title":"心原性ショック","explanation":"心原性ショックは心臓のポンプ機能の障害が中心です。細菌感染を原因として挙げる基本的な分類ではありません。"},{"choice":2,"correct":true,"title":"敗血症性ショック","explanation":"感染に対する全身の反応により血管拡張や循環障害が起こります。重い感染症で血圧低下や臓器障害がある場合に注意します。"},{"choice":3,"correct":false,"title":"アナフィラキシーショック","explanation":"アナフィラキシーは重い全身性の過敏反応です。感染による敗血症性ショックと区別します。"},{"choice":4,"correct":false,"title":"循環血液量減少性ショック","explanation":"出血や脱水などで循環する血液量が不足する状態です。感染を原因とする本問の分類は敗血症性ショックです。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"細菌感染で起こるショックはどれか。","choices":["心原性ショック","敗血症性ショック","アナフィラキシーショック","循環血液量減少性ショック"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":14,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[10],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B014"},"exam":111,"year":2022,"session":"PM","number":14},"sources":[]},{"id":"111-PM-015","record":{"id":"111-PM-015","choice_explanations":[{"choice":1,"correct":false,"title":"発 汗","explanation":"発汗は汗の蒸発によって熱を逃がします。低体温から回復するための熱産生反応とは逆です。"},{"choice":2,"correct":true,"title":"ふるえ","explanation":"筋肉が細かく収縮することで熱を生み出します。寒いときに起こるふるえは、体温を保つ反応です。"},{"choice":3,"correct":false,"title":"乳酸の蓄積","explanation":"乳酸の蓄積は低酸素などに伴う代謝の変化であり、体温を上げるための代表的な調節反応ではありません。"},{"choice":4,"correct":false,"title":"体表面への血流増加","explanation":"皮膚血流が増えると熱を外へ逃がしやすくなります。寒いときは通常、末梢血管が収縮して熱放散を抑えます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"低体温から回復するための生体の反応はどれか。","choices":["発 汗","ふるえ","乳酸の蓄積","体表面への血流増加"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":15,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[10],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B015"},"exam":111,"year":2022,"session":"PM","number":15},"sources":[]},{"id":"111-PM-016","record":{"id":"111-PM-016","choice_explanations":[{"choice":1,"correct":false,"title":"血圧が低下すること","explanation":"血圧低下は循環状態の変化です。貧血の有無を血圧だけで定義することはできません。"},{"choice":2,"correct":false,"title":"脈拍が速くなること","explanation":"頻脈は貧血を補おうとする反応として起こり得ますが、発熱や不整脈などでもみられ、貧血の定義ではありません。"},{"choice":3,"correct":false,"title":"立ち上がると失神を起こすこと","explanation":"立ちくらみや失神には起立性低血圧など複数の原因があります。症状だけで貧血と呼ぶのは適切ではありません。"},{"choice":4,"correct":true,"title":"ヘモグロビン濃度が減少していること","explanation":"血液中のヘモグロビン濃度が基準より低い状態です。酸素を運ぶ能力の低下につながる点を理解します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"貧血の定義で正しいのはどれか。","choices":["血圧が低下すること","脈拍が速くなること","立ち上がると失神を起こすこと","ヘモグロビン濃度が減少していること"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":16,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[10],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B016"},"exam":111,"year":2022,"session":"PM","number":16},"sources":[]},{"id":"111-PM-017","record":{"id":"111-PM-017","choice_explanations":[{"choice":1,"correct":true,"title":"気道確保","explanation":"呼吸が妨げられていないか確認し、気道を保つことを優先します。口を無理に開けて物を入れるのではなく、安全な体位と呼吸の観察で対応します。"},{"choice":2,"correct":false,"title":"周囲の環境整備","explanation":"周囲の危険物を除くことも重要です。ただし設問の優先順位では生命維持に直結する気道と呼吸を先に考えます。"},{"choice":3,"correct":false,"title":"末梢静脈路の確保","explanation":"治療薬の投与に必要になることがありますが、まず気道・呼吸・安全を確保します。"},{"choice":4,"correct":false,"title":"心電図モニターの装着","explanation":"全身状態の把握に役立ちますが、装着作業のために気道確保を遅らせることは適切ではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"全身性けいれん発作を起こしている患者に最も優先して行うのはどれか。","choices":["気道確保","周囲の環境整備","末梢静脈路の確保","心電図モニターの装着"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":17,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[11],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B017"},"exam":111,"year":2022,"session":"PM","number":17},"sources":[]},{"id":"111-PM-018","record":{"id":"111-PM-018","choice_explanations":[{"choice":1,"correct":false,"title":"肝腫大","explanation":"肝腫大は体静脈系のうっ血でみられ、右心不全との関連が重要です。"},{"choice":2,"correct":false,"title":"下腿浮腫","explanation":"下腿浮腫も体静脈系のうっ血の所見です。左右の心不全が合併することはありますが、本問は肺うっ血の症状を選びます。"},{"choice":3,"correct":true,"title":"起坐呼吸","explanation":"左心不全で肺にうっ血すると、横になると息苦しく、上体を起こすと楽になることがあります。これが起坐呼吸です。"},{"choice":4,"correct":false,"title":"頸静脈怒張","explanation":"頸静脈怒張は右心系への血液の戻りが滞る所見です。左心不全に特徴的な呼吸症状とは区別します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"左心不全でみられる症状はどれか。\nleft heart failure","choices":["肝腫大","下腿浮腫","起坐呼吸","頸静脈怒張"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":18,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[11],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B018"},"exam":111,"year":2022,"session":"PM","number":18},"sources":[]},{"id":"111-PM-019","record":{"id":"111-PM-019","choice_explanations":[{"choice":1,"correct":true,"title":"器質性便秘","explanation":"狭窄など腸管の構造的な異常によって便が通りにくくなる便秘です。原因が器質的な変化である点が重要です。"},{"choice":2,"correct":false,"title":"痙攣型便秘","explanation":"腸管の運動や緊張の異常に関係する便秘の分類です。狭窄という構造上の異常とは区別します。"},{"choice":3,"correct":false,"title":"弛緩型便秘","explanation":"腸の動きが弱くなることに関係します。狭窄による通過障害を示す名称ではありません。"},{"choice":4,"correct":false,"title":"直腸性便秘","explanation":"直腸に便が来ても排便しにくいなど、排出の機能に関係する分類です。大腸の狭窄は器質性便秘です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"大腸の狭窄による便秘はどれか。","choices":["器質性便秘","痙攣型便秘","弛緩型便秘","直腸性便秘"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":19,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[11],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B019"},"exam":111,"year":2022,"session":"PM","number":19},"sources":[]},{"id":"111-PM-020","record":{"id":"111-PM-020","choice_explanations":[{"choice":1,"correct":false,"title":"左腕から脱がせ、左腕から着せる。","explanation":"着るときに左腕を先にするのは適切ですが、脱ぐときは動かせる右腕からにします。麻痺側の関節へ無理な力をかけないためです。"},{"choice":2,"correct":false,"title":"左腕から脱がせ、右腕から着せる。","explanation":"脱ぐ側も着る側も逆です。基本は脱健着患で、健側から脱ぎ、患側から着ます。"},{"choice":3,"correct":true,"title":"右腕から脱がせ、左腕から着せる。","explanation":"動かせる右腕から脱いで衣服にゆとりを作り、着るときは左腕を先に通します。麻痺側の負担を減らす方法です。"},{"choice":4,"correct":false,"title":"右腕から脱がせ、右腕から着せる。","explanation":"脱ぐ順序は適切ですが、着るときは左腕を先にします。右腕を後にすると本人も動かして調整しやすくなります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"左片麻痺患者の上衣の交換で適切なのはどれか。","choices":["左腕から脱がせ、左腕から着せる。","左腕から脱がせ、右腕から着せる。","右腕から脱がせ、左腕から着せる。","右腕から脱がせ、右腕から着せる。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":20,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[11],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B020"},"exam":111,"year":2022,"session":"PM","number":20},"sources":[]},{"id":"111-PM-021","record":{"id":"111-PM-021","choice_explanations":[{"choice":1,"correct":true,"title":"降圧薬","explanation":"血圧低下や起立性低血圧により、ふらつきが生じることがあります。立ち上がり時の状態を観察し、転倒を防ぎます。"},{"choice":2,"correct":false,"title":"抗凝固薬","explanation":"抗凝固薬は転倒した場合の出血を重くする可能性がありますが、転倒そのものを起こす代表的な作用とは別です。"},{"choice":3,"correct":false,"title":"気管支拡張薬","explanation":"動悸などの副作用はあり得ますが、本問で転倒リスクを直接高める代表は降圧薬です。"},{"choice":4,"correct":false,"title":"副腎皮質ステロイド薬","explanation":"長期使用による骨への影響などはありますが、転倒のきっかけとなる血圧低下を起こす薬としては降圧薬を選びます。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"転倒・転落を起こすリスクを高める薬はどれか。","choices":["降圧薬","抗凝固薬","気管支拡張薬","副腎皮質ステロイド薬"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":21,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[12],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B021"},"exam":111,"year":2022,"session":"PM","number":21},"sources":[{"title":"厚生労働省：高齢者の医薬品適正使用の指針","url":"https://www.mhlw.go.jp/web/t_doc?dataId=00tc3422&dataType=1"}]},{"id":"111-PM-022","record":{"id":"111-PM-022","choice_explanations":[{"choice":1,"correct":false,"title":"皮下注射","explanation":"皮下注射は皮下組織を狙います。器具によって垂直に刺す方法もありますが、本問の基本的な45〜90度の分類では筋肉内注射を選びます。"},{"choice":2,"correct":false,"title":"皮内注射","explanation":"皮内注射は皮膚の浅い部分に入れるため、皮膚に近い浅い角度で刺します。"},{"choice":3,"correct":true,"title":"筋肉内注射","explanation":"筋肉まで到達するよう、部位や皮下脂肪の厚さ、器具に応じた角度と深さで刺入します。本問では45〜90度が対応します。"},{"choice":4,"correct":false,"title":"静脈内注射","explanation":"表在静脈には血管の走行に沿って浅い角度で刺入します。深い角度では血管を貫通するおそれがあります。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"注射針の刺入角度が 45〜90 度の注射法はどれか。","choices":["皮下注射","皮内注射","筋肉内注射","静脈内注射"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":22,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[12],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B022"},"exam":111,"year":2022,"session":"PM","number":22},"sources":[{"title":"厚生労働省：県立看護大学の採血・注射演習資料","url":"https://www.mhlw.go.jp/shingi/2003/01/s0127-8b.html"}]},{"id":"111-PM-023","record":{"id":"111-PM-023","choice_explanations":[{"choice":1,"correct":false,"title":"薬剤名","explanation":"薬剤名を入力できる機器もありますが、基本的な送液設定として不可欠なのは流量です。"},{"choice":2,"correct":false,"title":"終了時間","explanation":"終了時刻だけでは、どれだけの量を送るか定まりません。流量や予定量を指示と照合します。"},{"choice":3,"correct":false,"title":"投与月日","explanation":"投与日付の記録は必要ですが、ポンプで送る速度を決める項目ではありません。"},{"choice":4,"correct":true,"title":"1時間あたりの流量","explanation":"1時間当たりの量を設定して投与速度を制御します。設定値と指示を確認し、実際の滴下や残量、刺入部も観察します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"点滴静脈内注射で輸液ポンプを使用する際に設定する項目はどれか。","choices":["薬剤名","終了時間","投与月日","1時間あたりの流量"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":23,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[12],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B023"},"exam":111,"year":2022,"session":"PM","number":23},"sources":[]},{"id":"111-PM-024","record":{"id":"111-PM-024","choice_explanations":[{"choice":1,"correct":false,"title":"Ⅰ","explanation":"ステージⅠは皮膚が保たれた状態の消えない発赤などです。水疱による皮膚の損傷を示す段階とは異なります。"},{"choice":2,"correct":true,"title":"Ⅱ","explanation":"部分層の皮膚損傷で、漿液性の水疱などがみられる段階です。血疱など深部損傷が疑われるものは、同じように扱わず評価します。"},{"choice":3,"correct":false,"title":"Ⅲ","explanation":"ステージⅢはより深い全層皮膚欠損で、皮下組織に及びます。通常の水疱だけを示す段階ではありません。"},{"choice":4,"correct":false,"title":"Ⅳ","explanation":"ステージⅣは筋や骨など深部組織に及ぶ損傷です。水疱形成より深い状態です。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"褥瘡の深達度分類で水疱形成のステージはどれか。","choices":["Ⅰ","Ⅱ","Ⅲ","Ⅳ"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":24,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[12],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B024"},"exam":111,"year":2022,"session":"PM","number":24},"sources":[{"title":"厚生労働省：褥瘡の深さによる分類","url":"https://www.mhlw.go.jp/topics/2008/03/dl/tp0305-1i.pdf"}]},{"id":"111-PM-025","record":{"id":"111-PM-025","choice_explanations":[{"choice":1,"correct":false,"title":"病 室","explanation":"病室には生活や観察に必要な明るさを確保しますが、細かな組織を直接見分ける手術野ほど高い照度を常に必要としません。"},{"choice":2,"correct":true,"title":"手術野","explanation":"細かな構造や出血部位を正確に見分ける必要があるため、選択肢中で最も高い照度が必要です。影にも配慮します。"},{"choice":3,"correct":false,"title":"トイレ","explanation":"安全に移動・排泄できる照明は必要ですが、手術野ほどの精密作業を行う場所ではありません。"},{"choice":4,"correct":false,"title":"病棟の廊下","explanation":"安全な移動と案内ができる明るさを確保します。手術野と同じ高照度を求める場所ではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"最も高い照度を必要とするのはどれか。","choices":["病 室","手術野","トイレ","病棟の廊下"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":25,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[13],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B025"},"exam":111,"year":2022,"session":"PM","number":25},"sources":[]},{"id":"111-PM-026","record":{"id":"111-PM-026","choice_explanations":[{"choice":1,"correct":false,"title":"尿 酸","explanation":"尿酸は主にプリン体代謝の終産物です。アンモニアを処理する尿素回路の産物とは異なります。"},{"choice":2,"correct":true,"title":"尿 素","explanation":"肝臓の尿素回路で、毒性の強いアンモニアを尿素に変えます。尿素は血液を通じて腎臓へ運ばれ排泄されます。"},{"choice":3,"correct":false,"title":"亜硝酸","explanation":"亜硝酸は本問の肝臓でのアンモニア処理の最終産物ではありません。窒素を含む物質を名前だけで結び付けないようにします。"},{"choice":4,"correct":false,"title":"一酸化窒素","explanation":"一酸化窒素は血管調節などに働く物質です。アンモニアを安全に排泄するための変換先ではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"生体内でタンパク質が分解され、アミノ酸の代謝が進んで生じたアンモニアは肝\n臓で( )に変換される。\n( )に入るのはどれか。","choices":["尿 酸","尿 素","亜硝酸","一酸化窒素"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":26,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[13],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B026"},"exam":111,"year":2022,"session":"PM","number":26},"sources":[]},{"id":"111-PM-027","record":{"id":"111-PM-027","choice_explanations":[{"choice":1,"correct":false,"title":"熱産生量の増加","explanation":"高齢者で熱産生が増えることが、熱中症を起こしやすい一般的な理由ではありません。暑さへの調節反応の低下に着目します。"},{"choice":2,"correct":false,"title":"熱放散量の増加","explanation":"熱を逃がす能力は低下しやすく、増加ではありません。汗や皮膚血流による放熱が十分に働きにくくなります。"},{"choice":3,"correct":true,"title":"自律性体温調節反応の低下","explanation":"発汗や皮膚血流などの調節反応が低下し、体内の熱を逃がしにくくなります。暑さや口渇を感じにくいことも重なります。"},{"choice":4,"correct":false,"title":"視床下部の体温調節中枢のセットポイントの低下","explanation":"熱中症は発熱のような設定温度の変更が基本ではありません。熱の産生・獲得に対して放散が追いつかない状態です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"若年者よりも高齢者が熱中症を起こしやすい理由はどれか。","choices":["熱産生量の増加","熱放散量の増加","自律性体温調節反応の低下","視床下部の体温調節中枢のセットポイントの低下"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":27,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[13],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B027"},"exam":111,"year":2022,"session":"PM","number":27},"sources":[]},{"id":"111-PM-029","record":{"id":"111-PM-029","choice_explanations":[{"choice":1,"correct":true,"title":"a","explanation":"ALSでは上位・下位運動ニューロンの両方が障害され、痙性や腱反射亢進と筋萎縮などが組み合わさります。表のaが両方ありに対応することを確認します。"},{"choice":2,"correct":false,"title":"b","explanation":"bは上位の徴候あり・下位の徴候なしの組合せです。両方の運動ニューロン障害を示すALSの基本像とは異なります。"},{"choice":3,"correct":false,"title":"c","explanation":"cは上位の徴候なし・下位の徴候ありの組合せです。ALSでは下位の徴候だけでなく上位の徴候もみられます。"},{"choice":4,"correct":false,"title":"d","explanation":"dは両方の徴候なしの組合せです。運動ニューロンが障害されるALSの所見とは合いません。"}],"status":"UNKNOWN","review_reason":"原表のa～dの対応は目視確認済み。ただしゲームの問題文で表配置が崩れているため、表示上の疑義が残る。","fixes_made":[]},"input_anchor":{"question":"上位運動ニューロン徴候および下位運動ニューロン徴候の有無について表に示\nす。\n下位運動ニューロン徴候\nあり なし\n上\n位\nあ\n運 a b\nり\n動\nニ\nュ\nー\nロ\nな\nン c d\nし\n徴\n候\n筋萎縮性側索硬化症〈ALS〉において正しいのはどれか。\namyotrophic lateral sclerosis","choices":["a","b","c","d"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":29,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[15],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B029"},"exam":111,"year":2022,"session":"PM","number":29},"sources":[{"title":"厚生労働省：第111回午後29問の原表（PDF15ページを目視確認）","url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf"}]},{"id":"111-PM-030","record":{"id":"111-PM-030","choice_explanations":[{"choice":1,"correct":false,"title":"診療報酬の点数は3年に1回改定される。","explanation":"診療報酬は原則2年ごとに改定されます。介護報酬の原則3年ごとの改定と混同しません。"},{"choice":2,"correct":false,"title":"診療報酬は都道府県が医療機関に支払う。","explanation":"医療保険の診療報酬は、保険者の負担分などが審査支払機関を通じて支払われます。都道府県が一律に医療機関へ払う制度ではありません。"},{"choice":3,"correct":false,"title":"医療機関への支払いは出来高払いのみである。","explanation":"出来高払いのほか、包括的な支払い方式もあります。医療行為ごとに積み上げる方式だけではありません。"},{"choice":4,"correct":true,"title":"厚生労働大臣の指定を受けた医療機関で利用できる。","explanation":"保険診療を行うには保険医療機関として指定を受ける必要があります。指定と保険医の登録など、保険診療の仕組みを理解します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"診療報酬制度について正しいのはどれか。","choices":["診療報酬の点数は3年に1回改定される。","診療報酬は都道府県が医療機関に支払う。","医療機関への支払いは出来高払いのみである。","厚生労働大臣の指定を受けた医療機関で利用できる。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":30,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[15],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B030"},"exam":111,"year":2022,"session":"PM","number":30},"sources":[{"title":"厚生労働省：診療報酬制度","url":"https://www.mhlw.go.jp/content/001521415.pdf"}]},{"id":"111-PM-031","record":{"id":"111-PM-031","choice_explanations":[{"choice":1,"correct":false,"title":"未成年者喫煙禁止法","explanation":"未成年者喫煙禁止法は古くからある法律で、本問の中で最も新しいものではありません。現在の名称変更と制定時期は区別します。"},{"choice":2,"correct":false,"title":"麻薬及び向精神薬取締法","explanation":"麻薬及び向精神薬取締法は、依存症対策基本法より前に制定されています。法律の改正と新規制定を混同しません。"},{"choice":3,"correct":false,"title":"アルコール健康障害対策基本法","explanation":"アルコール健康障害対策基本法は2013年制定です。ギャンブル等依存症対策基本法より前です。"},{"choice":4,"correct":true,"title":"ギャンブル等依存症対策基本法","explanation":"ギャンブル等依存症対策基本法は2018年制定で、選択肢中で最も新しい法律です。依存症を本人だけの問題とせず、総合的に対策する枠組みです。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"次の法律のうち最も新しく制定されたのはどれか。","choices":["未成年者喫煙禁止法","麻薬及び向精神薬取締法","アルコール健康障害対策基本法","ギャンブル等依存症対策基本法"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":31,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[16],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B031"},"exam":111,"year":2022,"session":"PM","number":31},"sources":[{"title":"厚生労働省：依存症関連対策・法律の制定","url":"https://www.mhlw.go.jp/content/12601000/000371108.pdf"}]},{"id":"111-PM-032","record":{"id":"111-PM-032","choice_explanations":[{"choice":1,"correct":false,"title":"4","explanation":"4分野ではありません。第二次の目標は5分野に整理されています。"},{"choice":2,"correct":true,"title":"5","explanation":"健康日本21の第二次では5分野53項目の目標が設定されました。現在の計画ではなく、設問が指定する第二次の構成を答えます。"},{"choice":3,"correct":false,"title":"6","explanation":"6分野は第二次の目標設定と一致しません。計画の基本的方向と個別項目数を分けて把握します。"},{"choice":4,"correct":false,"title":"7","explanation":"7分野ではありません。過去の計画と後の計画で区分が変わるため、計画名と時期を確認します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"21 世紀における第二次国民健康づくり運動〈健康日本 21(第二次)〉では、( )分野\n53 項目の目標が設定された。\n( )に入る数値はどれか。","choices":["4","5","6","7"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":32,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[16],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B032"},"exam":111,"year":2022,"session":"PM","number":32},"sources":[{"title":"厚生労働省：健康日本21第二次の53目標","url":"https://www.mhlw.go.jp/content/10900000/001398003.pdf"}]},{"id":"111-PM-033","record":{"id":"111-PM-033","choice_explanations":[{"choice":1,"correct":false,"title":"病床の区分は療養病床と一般病床の2種類である。","explanation":"精神病床、感染症病床、結核病床などもあり、療養病床と一般病床だけではありません。"},{"choice":2,"correct":false,"title":"地域医療支援病院は厚生労働大臣の承認が必要である。","explanation":"地域医療支援病院は都道府県知事の承認を受けます。厚生労働大臣の承認を受ける特定機能病院と区別します。"},{"choice":3,"correct":false,"title":"無床診療所の開設には厚生労働大臣への届出が必要である。","explanation":"開設の手続きは開設者等で異なりますが、厚生労働大臣へ一律に届け出るものではありません。"},{"choice":4,"correct":true,"title":"有床診療所は 19 人以下の患者を入院させる施設を有するものである。","explanation":"診療所は無床または19人以下の入院施設を持つ施設です。20人以上の入院施設を持つ病院との区切りです。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"医療法に基づく記述で正しいのはどれか。","choices":["病床の区分は療養病床と一般病床の2種類である。","地域医療支援病院は厚生労働大臣の承認が必要である。","無床診療所の開設には厚生労働大臣への届出が必要である。","有床診療所は 19 人以下の患者を入院させる施設を有するものである。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":33,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[16],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B033"},"exam":111,"year":2022,"session":"PM","number":33},"sources":[{"title":"厚生労働省：医療法","url":"https://www.mhlw.go.jp/web/t_doc?dataId=80090000&dataType=0"}]},{"id":"111-PM-034","record":{"id":"111-PM-034","choice_explanations":[{"choice":1,"correct":false,"title":"物事を否定的にみる。","explanation":"批判的に考えることは、何でも否定することではありません。妥当な根拠があれば受け入れる姿勢も必要です。"},{"choice":2,"correct":true,"title":"根拠に基づいて考える。","explanation":"情報の根拠や前提、論理のつながりを確かめて判断します。思い込みに気づき、必要に応じて判断を修正します。"},{"choice":3,"correct":false,"title":"主観的な情報を重視する。","explanation":"患者の主観的な情報も大切ですが、それだけを偏って重視せず、他の情報と照合して考えます。"},{"choice":4,"correct":false,"title":"直感的に状況を判断する。","explanation":"直感が気づきのきっかけになることはありますが、そのまま結論とせず根拠を確かめることが重要です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"クリティカル・シンキングで適切なのはどれか。","choices":["物事を否定的にみる。","根拠に基づいて考える。","主観的な情報を重視する。","直感的に状況を判断する。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":34,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[16],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B034"},"exam":111,"year":2022,"session":"PM","number":34},"sources":[]},{"id":"111-PM-035","record":{"id":"111-PM-035","choice_explanations":[{"choice":1,"correct":false,"title":"手話で説明する。","explanation":"手話を理解できるとは限らず、構音障害が聴覚障害を意味するわけでもありません。使える意思疎通の方法を確認します。"},{"choice":2,"correct":true,"title":"筆談を提案する。","explanation":"構音が難しくても書く能力が保たれていれば、筆談で意思を伝えられます。本人が使いやすい方法を相談します。"},{"choice":3,"correct":false,"title":"耳元で話しかける。","explanation":"耳元で大きく話す必要があるとは限りません。発音の困難と、聞こえの困難は別です。"},{"choice":4,"correct":false,"title":"不明瞭な言語は繰り返し聞き直す。","explanation":"何度も聞き返すと疲労や焦りにつながります。確認は必要ですが、筆談や選択式など別の手段を組み合わせます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"構音障害がある成人患者への対応で適切なのはどれか。","choices":["手話で説明する。","筆談を提案する。","耳元で話しかける。","不明瞭な言語は繰り返し聞き直す。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":35,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[17],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B035"},"exam":111,"year":2022,"session":"PM","number":35},"sources":[]},{"id":"111-PM-036","record":{"id":"111-PM-036","choice_explanations":[{"choice":1,"correct":false,"title":"看護技術の習得度","explanation":"技術の習得度は看護師の学習評価に関係します。看護過程では患者に設定した目標の達成状況を評価します。"},{"choice":2,"correct":false,"title":"看護教育の活用度","explanation":"教育の活用度は人材育成等の評価です。患者への看護の成果を直接示す項目ではありません。"},{"choice":3,"correct":false,"title":"看護記録の完成度","explanation":"記録を整えることは重要ですが、記録の完成度だけでは患者の状態が改善したか判断できません。"},{"choice":4,"correct":true,"title":"看護目標の達成度","explanation":"患者に設定した目標に対して、実際の反応や変化を比較します。達成できなかった場合は原因を考え、計画を見直します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"看護過程において評価する項目はどれか。","choices":["看護技術の習得度","看護教育の活用度","看護記録の完成度","看護目標の達成度"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":36,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[17],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B036"},"exam":111,"year":2022,"session":"PM","number":36},"sources":[]},{"id":"111-PM-037","record":{"id":"111-PM-037","choice_explanations":[{"choice":1,"correct":false,"title":"手術用持針器 第4級アンモニウム塩","explanation":"手術器具は無菌組織に触れるため滅菌が必要です。低水準の消毒だけでは適切な処理になりません。"},{"choice":2,"correct":true,"title":"ステンレス製便器 熱水消毒","explanation":"耐熱性のあるステンレス製便器は、洗浄後の熱水消毒が可能です。用途と材質に合わせて処理方法を選びます。"},{"choice":3,"correct":false,"title":"軟性内視鏡 高圧蒸気滅菌","explanation":"軟性内視鏡は熱に弱いものが多く、通常の高圧蒸気滅菌を一律に使えません。製品に適した高水準消毒等を行います。"},{"choice":4,"correct":false,"title":"ベッド柵 グルタラール","explanation":"グルタラールは刺激性があり、ベッド柵の通常の環境消毒に用いるものではありません。必要以上に強い消毒薬を選ばないことが重要です。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"医療器材と消毒・滅菌の組合せで正しいのはどれか。","choices":["手術用持針器 第4級アンモニウム塩","ステンレス製便器 熱水消毒","軟性内視鏡 高圧蒸気滅菌","ベッド柵 グルタラール"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":37,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[17],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B037"},"exam":111,"year":2022,"session":"PM","number":37},"sources":[{"title":"厚生労働科学研究：院内感染対策手引き・器材の消毒","url":"https://janis.mhlw.go.jp/material/material/Ver_6.02%E6%9C%AC%E6%96%87170529.pdf"}]},{"id":"111-PM-038","record":{"id":"111-PM-038","choice_explanations":[{"choice":1,"correct":false,"title":"点眼時は上眼瞼を上げる。","explanation":"通常は下眼瞼を軽く引き、下方の結膜囊へ点眼します。上眼瞼を上げることが基本手順ではありません。"},{"choice":2,"correct":false,"title":"点眼容器の先端は眼瞼結膜に当てる。","explanation":"先端がまぶたやまつげに触れると汚染につながります。容器の先端を触れさせずに点眼します。"},{"choice":3,"correct":false,"title":"点眼後は眼球を圧迫する。","explanation":"眼球そのものを圧迫するのは不適切です。必要な場合は閉眼し、目頭の涙囊部をやさしく押さえる方法を用います。"},{"choice":4,"correct":true,"title":"眼から溢れた薬液は拭き取る。","explanation":"皮膚に残った薬液は刺激などの原因となるため、清潔なものでやさしく拭き取ります。目をこすらないようにします。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"点眼薬の投与について正しいのはどれか。","choices":["点眼時は上眼瞼を上げる。","点眼容器の先端は眼瞼結膜に当てる。","点眼後は眼球を圧迫する。","眼から溢れた薬液は拭き取る。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":38,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[17],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B038"},"exam":111,"year":2022,"session":"PM","number":38},"sources":[]},{"id":"111-PM-039","record":{"id":"111-PM-039","choice_explanations":[{"choice":1,"correct":false,"title":"赤血球製剤を 30〜37 ℃で融解する。","explanation":"通常の赤血球製剤は冷蔵保存で、融解する製剤ではありません。新鮮凍結血漿などとの取り扱いの違いを確認します。"},{"choice":2,"correct":false,"title":"血液型検査とクロスマッチ検査用の採血を同時に行う。","explanation":"同じ採血時の取り違えを両検査で見逃さないよう、別の機会に採血することが重要です。同じ試料だけで独立した確認を代替しません。"},{"choice":3,"correct":true,"title":"クロスマッチ検査の結果を医師と看護師で確認する。","explanation":"患者情報と製剤、交差適合試験の結果を複数の医療者で照合します。適合していることを確認してから投与します。"},{"choice":4,"correct":false,"title":"輸血開始から 15 分後にアレルギー反応の初回観察を行う。","explanation":"重い副反応は開始直後にも起こるため、15分まで初回観察を待ちません。開始直後は特に患者のそばで状態を観察します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"52 歳の女性が上腹部痛と吐血を主訴に受診し輸血を行うこととなった。\n輸血時の対応で正しいのはどれか。","choices":["赤血球製剤を 30〜37 ℃で融解する。","血液型検査とクロスマッチ検査用の採血を同時に行う。","クロスマッチ検査の結果を医師と看護師で確認する。","輸血開始から 15 分後にアレルギー反応の初回観察を行う。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":39,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[18],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B039"},"exam":111,"year":2022,"session":"PM","number":39},"sources":[{"title":"日本赤十字社：赤血球製剤の輸血手順","url":"https://www.jrc.or.jp/mr/transfusion/procedure/red_blood_cell/"}]},{"id":"111-PM-040","record":{"id":"111-PM-040","choice_explanations":[{"choice":1,"correct":true,"title":"出血部位を心臓より高く保つ。","explanation":"本問では出血部を心臓より高く保つ方法が正答です。ただし直接圧迫などによる確実な止血が基本で、挙上だけで十分という意味ではありません。"},{"choice":2,"correct":false,"title":"止血帯は幅1cm 未満を用いる。","explanation":"細いひも状のものは局所の神経や組織を傷つけやすくなります。止血帯を使う場合は適切な器具と手順が必要です。"},{"choice":3,"correct":false,"title":"止血帯は連続して4時間使用する。","explanation":"長時間の圧迫は虚血による障害を招きます。4時間連続使用を通常の手順として勧めることはできません。"},{"choice":4,"correct":false,"title":"出血部位を動脈圧より低い圧で圧迫する。","explanation":"動脈からの出血を止めるには、出血部を十分な圧で直接圧迫します。弱い圧では止血できないことがあります。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"四肢の動脈性外出血に対する止血法で適切なのはどれか。","choices":["出血部位を心臓より高く保つ。","止血帯は幅1cm 未満を用いる。","止血帯は連続して4時間使用する。","出血部位を動脈圧より低い圧で圧迫する。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":40,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[18],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B040"},"exam":111,"year":2022,"session":"PM","number":40},"sources":[{"title":"海上保安庁：怪我の応急処置","url":"https://www.kaiho.mlit.go.jp/07kanku/nagasaki/right/rescue/kega.htm"}]},{"id":"111-PM-041","record":{"id":"111-PM-041","choice_explanations":[{"choice":1,"correct":false,"title":"仰臥位で行う。","explanation":"後腸骨稜は背側にあるため、側臥位や腹臥位などで行います。仰臥位のまま穿刺する部位ではありません。"},{"choice":2,"correct":false,"title":"穿刺時は深呼吸を促す。","explanation":"穿刺中に大きく動かないよう説明します。深呼吸を積極的に繰り返すことを基本の指示とはしません。"},{"choice":3,"correct":true,"title":"骨髄液吸引時に痛みが生じる。","explanation":"局所麻酔をしていても、骨髄液を吸引する際に特有の痛みを感じることがあります。事前に説明し、反応を観察します。"},{"choice":4,"correct":false,"title":"終了後、当日の入浴は可能である。","explanation":"当日の入浴は穿刺部の出血や感染などに配慮して制限されます。止血と被覆を確認し、施設の指示を伝えます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"成人の後腸骨稜からの骨髄穿刺で正しいのはどれか。","choices":["仰臥位で行う。","穿刺時は深呼吸を促す。","骨髄液吸引時に痛みが生じる。","終了後、当日の入浴は可能である。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":41,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[18],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B041"},"exam":111,"year":2022,"session":"PM","number":41},"sources":[]},{"id":"111-PM-042","record":{"id":"111-PM-042","choice_explanations":[{"choice":1,"correct":false,"title":"｢腹痛がずっと続いています｣","explanation":"持続する腹痛は身体的な苦痛の表出です。他の苦痛と相互に影響し得ますが、中心は痛みそのものです。"},{"choice":2,"correct":false,"title":"｢吐き気が続くと思うと不安です｣","explanation":"今後も症状が続くことへの不安は心理的な苦痛です。"},{"choice":3,"correct":false,"title":"｢今後の生活にかかるお金が心配です｣","explanation":"生活費の心配は社会的・経済的な苦痛です。必要な制度や相談先への支援も考えます。"},{"choice":4,"correct":true,"title":"｢これまでの自分の人生が意味のないものに思えます｣","explanation":"人生の意味や自分の存在価値が揺らぐ苦痛です。簡単に励まして打ち消さず、本人の思いや大切なことを聴きます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さん(55 歳、男性、会社員)は胃癌の終末期である。\ngastric cancer\nA さんの訴えのうちスピリチュアルペインの表出はどれか。","choices":["｢腹痛がずっと続いています｣","｢吐き気が続くと思うと不安です｣","｢今後の生活にかかるお金が心配です｣","｢これまでの自分の人生が意味のないものに思えます｣"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":42,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[18],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B042"},"exam":111,"year":2022,"session":"PM","number":42},"sources":[]},{"id":"111-PM-043","record":{"id":"111-PM-043","choice_explanations":[{"choice":1,"correct":false,"title":"1回換気量が増加している。","explanation":"呼吸数が増えても、1回の有効な換気が増えるとは限りません。肺気腫では空気を十分に吐き出せず、換気効率が低下します。"},{"choice":2,"correct":false,"title":"呼気よりも吸気を促すと効果的である。","explanation":"吸い込むことだけを促すのではなく、口すぼめ呼吸などでゆっくり呼気を出すことが役立ちます。"},{"choice":3,"correct":false,"title":"経皮的動脈血酸素飽和度〈SpO2〉は上昇している。","explanation":"チアノーゼがみられる状況で、SpO2の上昇を推測するのは不適切です。実際に測定して酸素化を確認します。"},{"choice":4,"correct":true,"title":"病状が進行すると動脈血二酸化炭素分圧〈PaCO2〉が上昇する。","explanation":"病状が進んで有効な肺胞換気が低下すると、二酸化炭素を十分に排出できずPaCO2が上がることがあります。呼吸数だけで換気を判断しません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さん(63 歳、男性)は3年前から肺気腫で定期受診を続けていた。最近、歩行\npulmonary emphysema\n時の息切れが強くなってきたことを自覚し、心配になったため受診した。受診時、\n呼吸数は 34/分で、口唇のチアノーゼがみられた。\nA さんについて正しいのはどれか。","choices":["1回換気量が増加している。","呼気よりも吸気を促すと効果的である。","経皮的動脈血酸素飽和度〈SpO2〉は上昇している。","病状が進行すると動脈血二酸化炭素分圧〈PaCO2〉が上昇する。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":43,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[19],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B043"},"exam":111,"year":2022,"session":"PM","number":43},"sources":[]},{"id":"111-PM-044","record":{"id":"111-PM-044","choice_explanations":[{"choice":1,"correct":false,"title":"カテーテルの刺入部は見えないように覆う。","explanation":"刺入部を観察できないと発赤や滲出などの発見が遅れます。適切な被覆で保護しながら、感染や固定状態を確認できるようにします。"},{"choice":2,"correct":false,"title":"カテーテル刺入部を定期的に消毒する。","explanation":"不明：刺入部の消毒はドレッシング交換時などに行われるため、「定期的に消毒する」を一律に誤りとする根拠は確定できません。公式採点では不正答です。"},{"choice":3,"correct":true,"title":"カテーテルの固定位置を毎日確認する。","explanation":"抜けかけや移動がないか固定位置を毎日確認します。高濃度の輸液を安全に投与するため、刺入部やルートの状態も観察します。"},{"choice":4,"correct":false,"title":"予防的に抗菌薬の投与を行う。","explanation":"カテーテル留置だけを理由に予防的な抗菌薬を常用することはしません。清潔操作や適切な管理で感染を予防します。"}],"status":"UNKNOWN","review_reason":"選択肢2の定期的な刺入部消毒を誤りと断定できない。正答は変更せず、疑義を明記。","fixes_made":[]},"input_anchor":{"question":"中心静脈栄養法を受けている患者の看護について適切なのはどれか。","choices":["カテーテルの刺入部は見えないように覆う。","カテーテル刺入部を定期的に消毒する。","カテーテルの固定位置を毎日確認する。","予防的に抗菌薬の投与を行う。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":44,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[19],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B044"},"exam":111,"year":2022,"session":"PM","number":44},"sources":[{"title":"厚生労働科学研究：カテーテル管理・定期的ドレッシング交換","url":"https://janis.mhlw.go.jp/material/material/Ver_6.02%E6%9C%AC%E6%96%87170529.pdf"}]},{"id":"111-PM-045","record":{"id":"111-PM-045","choice_explanations":[{"choice":1,"correct":false,"title":"痛風結節は疼痛を伴う。","explanation":"痛風結節は尿酸塩が沈着したしこりで、通常は痛みを伴わないこともあります。急性の痛風関節炎の強い痛みと区別します。"},{"choice":2,"correct":true,"title":"痛風発作は飲酒で誘発される。","explanation":"飲酒は尿酸の産生や排泄に影響し、痛風発作の誘因となります。急な大量飲酒を避け、生活習慣を整えることが重要です。"},{"choice":3,"correct":false,"title":"痛風による関節炎の急性期に尿酸降下薬を投与する。\ngout","explanation":"出題時の基本的な対応では急性の炎症をまず抑え、尿酸低下薬を急に開始・変更しません。すでに服用中の薬を自己判断で中止するという意味ではありません。"},{"choice":4,"correct":false,"title":"血清尿酸値 9.0 mg/dL 以下を目標にコントロールする。","explanation":"9.0mg/dL以下では管理目標として高すぎます。治療目標は症状や合併症と合わせて定め、尿酸塩の蓄積を減らします。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"高尿酸血症で正しいのはどれか。\nhyperuricemia","choices":["痛風結節は疼痛を伴う。","痛風発作は飲酒で誘発される。","痛風による関節炎の急性期に尿酸降下薬を投与する。\ngout","血清尿酸値 9.0 mg/dL 以下を目標にコントロールする。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":45,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[19],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B045"},"exam":111,"year":2022,"session":"PM","number":45},"sources":[{"title":"日本痛風・核酸代謝学会：高尿酸血症・痛風治療ガイドライン第2版","url":"https://www.tukaku.jp/securewp/wp-content/uploads/2013/06/tufu-GL2.pdf"}]},{"id":"111-PM-046","record":{"id":"111-PM-046","choice_explanations":[{"choice":1,"correct":false,"title":"空気感染する。","explanation":"HIVは日常生活の空気を介して感染するものではありません。血液や性的接触などの感染経路を理解します。"},{"choice":2,"correct":true,"title":"無症候期がある。","explanation":"感染後、症状が目立たない期間があります。症状がないことは感染がないことを意味せず、検査と継続した診療が重要です。"},{"choice":3,"correct":false,"title":"DNA ウイルスによる。","explanation":"HIVはRNAを遺伝情報として持つレトロウイルスです。逆転写によりDNAを作る性質と区別します。"},{"choice":4,"correct":false,"title":"血液中の B リンパ球に感染する。","explanation":"主にCD4陽性T細胞などに感染し、免疫機能を障害します。Bリンパ球を主な標的とする説明ではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"ヒト免疫不全ウイルス〈HIV〉感染症で正しいのはどれか。\nhuman immunodeficiency virus infection","choices":["空気感染する。","無症候期がある。","DNA ウイルスによる。","血液中の B リンパ球に感染する。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":46,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[19],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B046"},"exam":111,"year":2022,"session":"PM","number":46},"sources":[]},{"id":"111-PM-047","record":{"id":"111-PM-047","choice_explanations":[{"choice":1,"correct":false,"title":"水泳は可能である。","explanation":"水が耳に入る行為は、治癒が確認されて許可されるまで避けます。退院しただけで水泳が可能とは限りません。"},{"choice":2,"correct":false,"title":"耳垢はこまめに除去する。","explanation":"術後の耳を綿棒等で頻繁に触ると損傷や感染につながります。自己流でこまめに除去するよう指導しません。"},{"choice":3,"correct":true,"title":"鼻を強くかむことを禁じる。","explanation":"強く鼻をかむと耳管を通じて中耳の圧が変わり、修復部に負担がかかります。圧を急に上げる行為を避けます。"},{"choice":4,"correct":false,"title":"エレベーターの使用を勧める。","explanation":"気圧変化への配慮が必要で、エレベーターの利用を積極的に勧めることが術後指導の要点ではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"鼓室形成術を受けた患者の退院指導の内容で正しいのはどれか。","choices":["水泳は可能である。","耳垢はこまめに除去する。","鼻を強くかむことを禁じる。","エレベーターの使用を勧める。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":47,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[20],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B047"},"exam":111,"year":2022,"session":"PM","number":47},"sources":[]},{"id":"111-PM-048","record":{"id":"111-PM-048","choice_explanations":[{"choice":1,"correct":true,"title":"下肢の肢位","explanation":"足背のしびれは腓骨神経などの圧迫を考える徴候です。下肢の向きや腓骨頭付近への圧をまず確認します。"},{"choice":2,"correct":false,"title":"牽引の方向","explanation":"牽引方向の確認も必要ですが、足背の感覚変化からは神経が圧迫される肢位を優先して確認します。"},{"choice":3,"correct":false,"title":"重錘の重さ","explanation":"重錘の重さは指示と照合しますが、自己判断で変更せず、まず神経圧迫の原因を観察して報告します。"},{"choice":4,"correct":false,"title":"弾性包帯のずれ","explanation":"包帯の圧迫やずれも観察しますが、設問では足背のしびれから下肢の肢位に着目します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"下腿の介達牽引を受けている患者が足背のしびれを訴えている。\n看護師が確認すべき項目で優先度が高いのはどれか。","choices":["下肢の肢位","牽引の方向","重錘の重さ","弾性包帯のずれ"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":48,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[20],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B048"},"exam":111,"year":2022,"session":"PM","number":48},"sources":[]},{"id":"111-PM-049","record":{"id":"111-PM-049","choice_explanations":[{"choice":1,"correct":false,"title":"肺転移の頻度は低い。","explanation":"不明：前立腺癌は骨やリンパ節への転移が多く、肺にも転移します。ただし「肺転移の頻度が低い」を誤りと断定するには比較対象などの確認が必要です。公式正答は選択肢2のままです。"},{"choice":2,"correct":true,"title":"血清 PSA 値が高値となる。","explanation":"PSAは前立腺に関係する蛋白で、前立腺癌で高値となることがあります。ただし前立腺肥大症などでも上がり、値だけで癌とは診断できません。"},{"choice":3,"correct":false,"title":"患者の多くは 60 歳未満である。","explanation":"高齢になるほど多くみられるため、多くが60歳未満という説明は適切ではありません。"},{"choice":4,"correct":false,"title":"テストステロン補充療法が行われる。","explanation":"多くの前立腺癌は男性ホルモンの影響を受けるため、治療ではその働きを抑えます。テストステロン補充を基本の治療とはしません。"}],"status":"UNKNOWN","review_reason":"選択肢1の肺転移頻度について、比較対象がなく誤りと断定する根拠が不足。","fixes_made":[]},"input_anchor":{"question":"前立腺癌について正しいのはどれか。\nprostate cancer","choices":["肺転移の頻度は低い。","血清 PSA 値が高値となる。","患者の多くは 60 歳未満である。","テストステロン補充療法が行われる。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":49,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[20],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B049"},"exam":111,"year":2022,"session":"PM","number":49},"sources":[{"title":"国立がん研究センター：前立腺がんの転移","url":"https://ganjoho.jp/public/cancer/prostate/treatment.html"}]},{"id":"111-PM-050","record":{"id":"111-PM-050","choice_explanations":[{"choice":1,"correct":false,"title":"低血糖","explanation":"低血糖は抗エストロゲン薬の代表的な副作用ではありません。薬効と症状の関係を考えます。"},{"choice":2,"correct":true,"title":"ほてり","explanation":"エストロゲンの作用が抑えられることで、ほてりなど更年期に似た症状が出ることがあります。生活への影響を確認して支援します。"},{"choice":3,"correct":false,"title":"肺線維症\npulmonary fibrosis","explanation":"肺の障害は薬剤ごとに確認が必要ですが、本問で代表的な副作用として問うのはほてりです。"},{"choice":4,"correct":false,"title":"末梢神経障害","explanation":"末梢神経障害は一部の抗がん薬で問題となります。ホルモン療法と細胞障害性抗がん薬の副作用を混同しません。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"乳癌の患者に対する抗エストロゲン薬の副作用はどれか。\nbreast cancer","choices":["低血糖","ほてり","肺線維症\npulmonary fibrosis","末梢神経障害"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":50,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[20],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B050"},"exam":111,"year":2022,"session":"PM","number":50},"sources":[{"title":"PMDA：タモキシフェン添付文書・ほてり","url":"https://www.pmda.go.jp/PmdaSearch/iyakuDetail/ResultDataSetPDF/300119_4291003F1228_1_08"}]},{"id":"111-PM-051","record":{"id":"111-PM-051","choice_explanations":[{"choice":1,"correct":true,"title":"1秒率の減少","explanation":"加齢で呼出の機能が低下し、1秒率が減少する方向に働きます。術後の痛みや臥床が重なると、痰の排出や換気がさらに難しくなります。"},{"choice":2,"correct":false,"title":"残気量の減少","explanation":"加齢では残気量は増える方向に変化します。肺に残る空気が増え、有効な換気が低下します。"},{"choice":3,"correct":false,"title":"嚥下反射の亢進","explanation":"嚥下反射は低下しやすく、誤嚥のリスクが上がります。亢進するという説明は逆です。"},{"choice":4,"correct":false,"title":"気道の線毛運動の亢進","explanation":"気道の線毛運動は低下しやすく、分泌物を排出する力が弱まります。亢進は合併症を起こす理由ではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"高齢者が術後に呼吸器合併症を発症しやすい理由はどれか。","choices":["1秒率の減少","残気量の減少","嚥下反射の亢進","気道の線毛運動の亢進"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":51,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[21],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B051"},"exam":111,"year":2022,"session":"PM","number":51},"sources":[]},{"id":"111-PM-052","record":{"id":"111-PM-052","choice_explanations":[{"choice":1,"correct":false,"title":"運動時の心拍出量が増大する。","explanation":"運動時に心拍出量を増やす予備力は低下します。安静時に保たれていても負荷への対応力は弱まります。"},{"choice":2,"correct":false,"title":"拡張期血圧が上昇する。","explanation":"高齢では動脈が硬くなり、特に収縮期血圧が上がりやすくなります。拡張期血圧が一律に上昇するとはいえません。"},{"choice":3,"correct":true,"title":"心室壁が厚くなる。","explanation":"加齢に伴い心室壁は厚くなり、拡張しにくくなる変化がみられます。血液を受け入れる機能への影響を考えます。"},{"choice":4,"correct":false,"title":"脈圧が狭小化する。","explanation":"動脈の弾性が低下し、収縮期と拡張期の差である脈圧は広がりやすくなります。狭小化という説明は逆です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"加齢に伴う高齢者の循環器系の変化で正しいのはどれか。","choices":["運動時の心拍出量が増大する。","拡張期血圧が上昇する。","心室壁が厚くなる。","脈圧が狭小化する。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":52,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[21],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B052"},"exam":111,"year":2022,"session":"PM","number":52},"sources":[]},{"id":"111-PM-053","record":{"id":"111-PM-053","choice_explanations":[{"choice":1,"correct":true,"title":"よく利用するスーパーマーケットから自宅までの近道を考える。","explanation":"過去の経験や知識を使って判断する能力です。よく知る道の情報を活用して近道を考えることが該当します。"},{"choice":2,"correct":false,"title":"パソコン教室で操作方法を覚える。","explanation":"新しい操作を学ぶことは、新しい情報を処理する能力に関係します。蓄積した経験を使う結晶性知能の代表ではありません。"},{"choice":3,"correct":false,"title":"携帯電話に電話番号を登録する。","explanation":"新しい機器の操作や情報登録は、新規の学習・処理が中心です。慣れた経験に基づく判断とは区別します。"},{"choice":4,"correct":false,"title":"外国語の単語を暗記する。","explanation":"新たな単語を覚えることは、新規の学習や記憶に関係します。すでに蓄積した知識を使う例ではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"結晶性知能はどれか。","choices":["よく利用するスーパーマーケットから自宅までの近道を考える。","パソコン教室で操作方法を覚える。","携帯電話に電話番号を登録する。","外国語の単語を暗記する。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":53,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[21],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B053"},"exam":111,"year":2022,"session":"PM","number":53},"sources":[]},{"id":"111-PM-054","record":{"id":"111-PM-054","choice_explanations":[{"choice":1,"correct":false,"title":"夫による虐待が最も多い。","explanation":"2019年度の調査では、養護者のうち息子による虐待が最も多く、夫が最多ではありません。"},{"choice":2,"correct":false,"title":"被虐待者の9割が女性である。","explanation":"被虐待者は女性が多いものの、9割という値は当該調査と一致しません。多いことと、具体的な割合は分けて確認します。"},{"choice":3,"correct":false,"title":"心理的虐待が全体の6割を占めている。","explanation":"最も多い種類は身体的虐待であり、心理的虐待が6割という説明は当該調査と一致しません。複数の虐待が重なる場合もあります。"},{"choice":4,"correct":true,"title":"被虐待者の認知症高齢者の日常生活自立度判定基準はランクⅡが最も多い。","explanation":"当該調査の認知症の日常生活自立度ではランクⅡが最も多い区分です。認知症の有無だけでなく、生活上の支援の必要性を把握します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"令和元年度(2019 年度)｢高齢者虐待の防止、高齢者の養護者に対する支援等に関\nする法律に基づく対応状況等に関する調査｣の結果において、養護者による高齢者\n虐待に関する説明で正しいのはどれか。","choices":["夫による虐待が最も多い。","被虐待者の9割が女性である。","心理的虐待が全体の6割を占めている。","被虐待者の認知症高齢者の日常生活自立度判定基準はランクⅡが最も多い。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":54,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[21],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B054"},"exam":111,"year":2022,"session":"PM","number":54},"sources":[{"title":"厚生労働省：2019年度高齢者虐待調査・養護者による虐待","url":"https://www.mhlw.go.jp/content/12304250/001338040.pdf"}]},{"id":"111-PM-055","record":{"id":"111-PM-055","choice_explanations":[{"choice":1,"correct":true,"title":"シルバー人材センター","explanation":"高齢者の経験や能力を生かした就業機会を提供する組織です。地域の仕事を通じ、社会参加にもつながります。"},{"choice":2,"correct":false,"title":"老人福祉センター","explanation":"高齢者の相談や健康増進、教養・レクリエーションなどを支える施設です。就業機会の提供を主な目的とする組織とは異なります。"},{"choice":3,"correct":false,"title":"老人クラブ","explanation":"地域の高齢者が自主的に交流や活動を行う組織です。仕事の受注・提供を担うシルバー人材センターとは区別します。"},{"choice":4,"correct":false,"title":"自治会","explanation":"地域住民による自治的な組織です。高齢者の就業機会を提供する専用の組織ではありません。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"退職した高齢者に就労機会を提供するのはどれか。","choices":["シルバー人材センター","老人福祉センター","老人クラブ","自治会"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":55,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[22],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B055"},"exam":111,"year":2022,"session":"PM","number":55},"sources":[{"title":"厚生労働省：シルバー人材センター事業","url":"https://www.mhlw.go.jp/topics/2004/bukyoku/syokuan/11.html"}]},{"id":"111-PM-056","record":{"id":"111-PM-056","choice_explanations":[{"choice":1,"correct":false,"title":"骨密度の低下","explanation":"骨密度の低下は骨折リスクに関係します。薬の血中の遊離割合が増える理由とは異なります。"},{"choice":2,"correct":false,"title":"胃酸分泌の減少","explanation":"胃酸分泌の変化は吸収に影響することがありますが、薬効が一律に強くなるとはいえません。"},{"choice":3,"correct":false,"title":"消化管運動の低下","explanation":"消化管運動の低下は吸収の速さなどに影響しますが、すべての経口薬の作用を強めるわけではありません。"},{"choice":4,"correct":true,"title":"血清アルブミンの減少","explanation":"蛋白と結合していない薬物が作用します。アルブミンが少ないと、蛋白結合率の高い薬で遊離型の割合が増え、作用が強く出ることがあります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"高齢者に経口薬の薬効が強く現れる理由はどれか。","choices":["骨密度の低下","胃酸分泌の減少","消化管運動の低下","血清アルブミンの減少"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":56,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[22],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B056"},"exam":111,"year":2022,"session":"PM","number":56},"sources":[]},{"id":"111-PM-057","record":{"id":"111-PM-057","choice_explanations":[{"choice":1,"correct":false,"title":"IgA","explanation":"IgAは母乳などを通じた粘膜防御で重要です。胎盤を通って胎児へ移行する主な抗体とは異なります。"},{"choice":2,"correct":false,"title":"IgD","explanation":"IgDは主にB細胞の抗原認識に関係します。母体から胎盤を通じて受け取る抗体の代表ではありません。"},{"choice":3,"correct":true,"title":"IgG","explanation":"IgGは胎盤を通って胎児に移行し、出生後しばらく感染防御を支えます。母乳からのIgAによる防御と区別します。"},{"choice":4,"correct":false,"title":"IgM","explanation":"IgMは分子が大きく、通常は胎盤を通過しません。新生児自身の抗体産生を考える際にも、この違いが重要です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"新生児や乳児が胎児期に母体から受け取った抗体は次のどれか。","choices":["IgA","IgD","IgG","IgM"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":57,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[22],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B057"},"exam":111,"year":2022,"session":"PM","number":57},"sources":[]},{"id":"111-PM-058","record":{"id":"111-PM-058","choice_explanations":[{"choice":1,"correct":true,"title":"女児は乳房の発育から始まる。","explanation":"女児の第二次性徴は通常、乳房の発育が最初の徴候です。その後の発育や初経との順序を理解します。"},{"choice":2,"correct":false,"title":"発現は男児が女児よりも早い。","explanation":"一般に女児の方が男児より早く始まります。個人差があることと、集団の傾向は別です。"},{"choice":3,"correct":false,"title":"初経の開始後に、第二次発育急進が起こる。","explanation":"身長の急な伸びは初経より前に進み、初経後は次第に伸びが緩やかになります。順序が逆です。"},{"choice":4,"correct":false,"title":"精通は 11 歳の男児のほとんどに認められる。","explanation":"精通の時期には個人差があり、11歳のほとんどに認められるとはいえません。年齢だけで発達を一律に判断しません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"第二次性徴で正しいのはどれか。","choices":["女児は乳房の発育から始まる。","発現は男児が女児よりも早い。","初経の開始後に、第二次発育急進が起こる。","精通は 11 歳の男児のほとんどに認められる。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":58,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[22],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B058"},"exam":111,"year":2022,"session":"PM","number":58},"sources":[]},{"id":"111-PM-059","record":{"id":"111-PM-059","choice_explanations":[{"choice":1,"correct":false,"title":"Kaup〈カウプ〉指数で評価する。","explanation":"Kaup指数は主に乳幼児の体格評価に用います。学童では年齢・性別・身長を考慮した標準体重から肥満度などを評価します。"},{"choice":2,"correct":false,"title":"症候性の肥満がほとんどを占める。","explanation":"多くは生活習慣などが関係する単純性肥満です。内分泌疾患等による症候性肥満が大半という説明は異なります。"},{"choice":3,"correct":false,"title":"食事では蛋白質の摂取制限を行う。","explanation":"成長に必要な蛋白質を一律に制限しません。食事全体のバランスと活動を見直し、成長を守りながら支援します。"},{"choice":4,"correct":true,"title":"成人期の生活習慣病のリスク因子である。","explanation":"小児期の肥満は成人期の肥満へ続くことがあり、生活習慣病のリスクとなります。本人を責めず、家族と生活環境を整えます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"学童期の肥満で正しいのはどれか。","choices":["Kaup〈カウプ〉指数で評価する。","症候性の肥満がほとんどを占める。","食事では蛋白質の摂取制限を行う。","成人期の生活習慣病のリスク因子である。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":59,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[23],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B059"},"exam":111,"year":2022,"session":"PM","number":59},"sources":[]},{"id":"111-PM-060","record":{"id":"111-PM-060","choice_explanations":[{"choice":1,"correct":false,"title":"背部の叩打","explanation":"気道の異物を出すための対応であり、食道にある電池を除去する方法ではありません。"},{"choice":2,"correct":false,"title":"緩下薬の使用","explanation":"便に出るのを待つ間にも食道が損傷する危険があります。食道内のボタン電池に緩下薬で対応するのは不適切です。"},{"choice":3,"correct":false,"title":"催吐薬の使用","explanation":"吐かせると損傷や誤嚥の危険があり、確実に取り出せる方法でもありません。"},{"choice":4,"correct":true,"title":"緊急摘出術の実施","explanation":"食道内のボタン電池は短時間で組織を傷つけ、穿孔などに至る危険があります。症状が軽くても緊急に除去する必要があります。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"生後 11 か月の男児。ある日の朝、自宅でボタン型電池を飲み込んだ疑いがあり、\nその日の午前中に外来を受診した。胸部エックス線撮影によって、ボタン型電池が\n食道下部にあることが確認された。\n行われる処置で適切なのはどれか。","choices":["背部の叩打","緩下薬の使用","催吐薬の使用","緊急摘出術の実施"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":60,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[23],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B060"},"exam":111,"year":2022,"session":"PM","number":60},"sources":[{"title":"消費者庁：ボタン電池誤飲の対処","url":"https://www.caa.go.jp/policies/future/project/project_005/investigation/"}]},{"id":"111-PM-061","record":{"id":"111-PM-061","choice_explanations":[{"choice":1,"correct":true,"title":"恐 れ","explanation":"情緒の分化では、生後6か月ころに恐れが現れるとされます。人や物への反応が、快・不快という大まかな反応から次第に分かれていきます。"},{"choice":2,"correct":false,"title":"嫉 妬","explanation":"嫉妬は、自分と他者との関係への理解が進んでから現れる情緒です。生後6か月ころの分化としては、恐れを選びます。"},{"choice":3,"correct":false,"title":"喜 び","explanation":"この問題の情緒分化の枠組みでは、喜びは恐れより後に分化する情緒です。乳児が笑うことと、情緒としての喜びの分化は区別します。"},{"choice":4,"correct":false,"title":"恥ずかしさ","explanation":"恥ずかしさは、他者から見られる自分への意識が発達してから現れます。生後6か月ころに分化する情緒には当たりません。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"正常な成長・発達をしている子どもの情緒の分化で、生後6か月ころからみられ\nるのはどれか。","choices":["恐 れ","嫉 妬","喜 び","恥ずかしさ"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":61,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[23],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B061"},"exam":111,"year":2022,"session":"PM","number":61},"sources":[{"title":"電気通信大学学位論文：情動分化の理論・25～26ページ","url":"https://uec.repo.nii.ac.jp/record/9422/files/1642004_Thesis.pdf"}]},{"id":"111-PM-062","record":{"id":"111-PM-062","choice_explanations":[{"choice":1,"correct":false,"title":"増殖期は基礎体温が上昇する。","explanation":"増殖期は主にエストロゲンが働く低温相です。排卵後、黄体から分泌されるプロゲステロンの作用によって基礎体温が上がります。"},{"choice":2,"correct":false,"title":"プロラクチンによって排卵が起こる。","explanation":"プロラクチンは主に乳汁産生に関わります。排卵を直接引き起こすきっかけは、黄体形成ホルモン〈LH〉の急激な増加です。"},{"choice":3,"correct":false,"title":"プロゲステロンは子宮内膜の増殖を促進する。","explanation":"子宮内膜の増殖を主に促すのはエストロゲンです。プロゲステロンは増殖した内膜を分泌期の状態にし、受精卵の着床に備えます。"},{"choice":4,"correct":true,"title":"排卵直前に黄体形成ホルモン〈LH〉値が高くなる。","explanation":"排卵直前にはLHが急増します。これをLHサージといい、成熟した卵胞から卵子が排出されるきっかけになります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"性周期とホルモンについて正しいのはどれか。","choices":["増殖期は基礎体温が上昇する。","プロラクチンによって排卵が起こる。","プロゲステロンは子宮内膜の増殖を促進する。","排卵直前に黄体形成ホルモン〈LH〉値が高くなる。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":62,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[24],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B062"},"exam":111,"year":2022,"session":"PM","number":62},"sources":[]},{"id":"111-PM-063","record":{"id":"111-PM-063","choice_explanations":[{"choice":1,"correct":false,"title":"配偶者暴力相談支援センターは被害者の保護命令を出すことができる。","explanation":"保護命令を出すのは裁判所です。配偶者暴力相談支援センターは、相談、安全確保や自立のための支援などを担います。"},{"choice":2,"correct":true,"title":"配偶者には事実上婚姻関係と同様の事情にある者が含まれる。","explanation":"DV防止法では、婚姻届を出していなくても、事実上婚姻関係と同様の事情にある者を配偶者に含めています。法律婚だけが対象ではありません。"},{"choice":3,"correct":false,"title":"配偶者からの暴力を発見したときは、保健所へ通報する。","explanation":"法律上の通報先は、配偶者暴力相談支援センターまたは警察官です。保健所をこの通報先として定めているわけではありません。"},{"choice":4,"correct":false,"title":"加害者の矯正が法の目的に含まれる。","explanation":"法の目的は、配偶者からの暴力の防止と被害者の保護です。加害者の矯正を、ここで問われている法律の目的として選ぶことはできません。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"配偶者からの暴力の防止及び被害者の保護等に関する法律〈DV 防止法〉について\n正しいのはどれか。","choices":["配偶者暴力相談支援センターは被害者の保護命令を出すことができる。","配偶者には事実上婚姻関係と同様の事情にある者が含まれる。","配偶者からの暴力を発見したときは、保健所へ通報する。","加害者の矯正が法の目的に含まれる。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":63,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[24],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B063"},"exam":111,"year":2022,"session":"PM","number":63},"sources":[{"title":"内閣府：配偶者暴力防止法","url":"https://www.gender.go.jp/policy/no_violence/e-vaw/law/index2.html"}]},{"id":"111-PM-064","record":{"id":"111-PM-064","choice_explanations":[{"choice":1,"correct":false,"title":"浣腸を行う。","explanation":"前置胎盤では出血への注意が必要です。浣腸は子宮収縮を誘発する可能性があるため、通常の術前処置として安易に実施しません。"},{"choice":2,"correct":false,"title":"夕食が禁食となっているか確認する。","explanation":"絶食の開始時刻は麻酔方法や院内の指示に従います。翌朝の手術という情報だけで前日の夕食が禁食と決めることはできません。"},{"choice":3,"correct":true,"title":"輸血の準備ができているか確認する。","explanation":"前置胎盤の帝王切開では大量出血に備える必要があります。手術前日には輸血に必要な準備が整っているか確認することが重要です。"},{"choice":4,"correct":false,"title":"下肢に間欠的空気圧迫装置を装着する。","explanation":"間欠的空気圧迫装置は周術期の血栓予防に用いますが、手術前日から一律に装着するものではありません。この時点では出血への準備が優先されます。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さん(32 歳、初産婦)は前置胎盤のため妊娠 37 週0日の午前 10 時から帝王切\nplacenta previa\n開術を受ける予定である。\n手術前日の看護師の対応で適切なのはどれか。","choices":["浣腸を行う。","夕食が禁食となっているか確認する。","輸血の準備ができているか確認する。","下肢に間欠的空気圧迫装置を装着する。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":64,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[24],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B064"},"exam":111,"year":2022,"session":"PM","number":64},"sources":[{"title":"日本産婦人科医会：前置胎盤の輸血準備","url":"https://www.jaog.or.jp/sep2012/JAPANESE/MEMBERS/TANPA/H13/010219.htm"}]},{"id":"111-PM-065","record":{"id":"111-PM-065","choice_explanations":[{"choice":1,"correct":false,"title":"成人に比べて肺のガス交換面積が大きい。","explanation":"新生児の肺は発達の途中で、ガス交換面積は成人より小さい状態です。出生後も肺胞の発達が続き、ガス交換の能力が増していきます。"},{"choice":2,"correct":true,"title":"周期性呼吸がみられる。","explanation":"新生児は呼吸調節が未熟なため、呼吸の深さや間隔が周期的に変化することがあります。ただし、長い無呼吸やチアノーゼを伴う場合まで正常とは判断しません。"},{"choice":3,"correct":false,"title":"胸式呼吸が主である。","explanation":"新生児は主に横隔膜を使って呼吸するため、腹式呼吸が主体です。胸郭の動きだけでなく、腹部の動きも観察します。"},{"choice":4,"correct":false,"title":"口呼吸が主である。","explanation":"新生児は鼻呼吸が主体です。鼻閉によって哺乳や呼吸が妨げられることがあり、口呼吸が主とはいえません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"新生児の呼吸の生理的特徴で適切なのはどれか。","choices":["成人に比べて肺のガス交換面積が大きい。","周期性呼吸がみられる。","胸式呼吸が主である。","口呼吸が主である。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":65,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[24],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B065"},"exam":111,"year":2022,"session":"PM","number":65},"sources":[]},{"id":"111-PM-066","record":{"id":"111-PM-066","choice_explanations":[{"choice":1,"correct":false,"title":"病的酩酊\npathological intoxication","explanation":"病的酩酊は飲酒による酩酊の異常な状態です。長期大量飲酒を急に中止した後の症状として問われているのは、離脱に伴う振戦せん妄です。"},{"choice":2,"correct":true,"title":"振戦せん妄\ndelirium tremens","explanation":"大量飲酒が続いていた人が急に断酒すると、離脱症状として振戦、発汗、幻覚や意識の混乱が生じることがあります。振戦せん妄は重い離脱状態です。"},{"choice":3,"correct":false,"title":"アルコール性認知症\nalcohol-related dementia","explanation":"アルコール性認知症は長期の飲酒に関連する認知機能の障害です。急な断酒をきっかけとする急性の離脱状態とは区別します。"},{"choice":4,"correct":false,"title":"Korsakoff〈コルサコフ〉症候群\nKorsakoff syndrome","explanation":"コルサコフ症候群では記憶障害や作話が特徴で、ビタミンB1欠乏が関わります。急な断酒に伴う振戦せん妄を示す名称ではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"長期に大量飲酒をした後で、急に断酒した際にみられるのはどれか。","choices":["病的酩酊\npathological intoxication","振戦せん妄\ndelirium tremens","アルコール性認知症\nalcohol-related dementia","Korsakoff〈コルサコフ〉症候群\nKorsakoff syndrome"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":66,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[25],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B066"},"exam":111,"year":2022,"session":"PM","number":66},"sources":[]},{"id":"111-PM-067","record":{"id":"111-PM-067","choice_explanations":[{"choice":1,"correct":false,"title":"共依存","explanation":"共依存は、相手への過度な世話などによって互いの依存関係が維持される状態です。本問で直接示されているのは、言葉と行動の矛盾したメッセージです。"},{"choice":2,"correct":false,"title":"同一視","explanation":"同一視は、他者の性質や価値観を自分に取り入れることです。母親の言葉と行動が矛盾してAさんを混乱させる関係とは異なります。"},{"choice":3,"correct":false,"title":"ネグレクト","explanation":"ネグレクトは必要な世話や養育などを怠ることです。この場面では世話の不足ではなく、言葉と過度な世話との矛盾が問題になっています。"},{"choice":4,"correct":true,"title":"二重拘束〈ダブルバインド〉","explanation":"「甘えるな」という言葉と、依存を促すような過度の世話が同時に伝えられています。このような相反するメッセージによる拘束を二重拘束といいます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"母親が A さん(27 歳、統合失調症)に対して｢親に甘えてはいけない｣と言いなが\nschizophrenia\nら、過度に A さんの世話をすることで、A さんが混乱していた。\nこの親子関係を示すのはどれか。","choices":["共依存","同一視","ネグレクト","二重拘束〈ダブルバインド〉"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":67,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[25],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B067"},"exam":111,"year":2022,"session":"PM","number":67},"sources":[]},{"id":"111-PM-068","record":{"id":"111-PM-068","choice_explanations":[{"choice":1,"correct":true,"title":"家族との面会","explanation":"家族との面会は、治療上必要な場合には制限の対象となることがあります。隔離中だから自動的に禁止するのではなく、個別に必要性を判断します。"},{"choice":2,"correct":false,"title":"患者からの信書の発信","explanation":"信書の発信は、入院中でも原則として制限できない行為です。隔離中であることを理由に、患者の手紙を一律に止めることはできません。"},{"choice":3,"correct":false,"title":"患者からの退院の請求","explanation":"退院の請求は患者の権利を守る手続です。隔離や治療上の必要性を理由として、この請求自体を制限することはできません。"},{"choice":4,"correct":false,"title":"人権擁護に関する行政機関の職員との電話","explanation":"人権擁護に関する行政機関の職員との電話は、患者の権利保護に関わります。治療上の理由によって自由に制限できる連絡ではありません。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"精神保健及び精神障害者福祉に関する法律〈精神保健福祉法〉において、精神科病\n院で隔離中の患者に対し、治療上で必要な場合に制限できるのはどれか。","choices":["家族との面会","患者からの信書の発信","患者からの退院の請求","人権擁護に関する行政機関の職員との電話"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":68,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[25],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B068"},"exam":111,"year":2022,"session":"PM","number":68},"sources":[{"title":"厚生労働省：精神科病院で制限できない行為","url":"https://www.mhlw.go.jp/web/t_doc?dataId=80134000&dataType=0&pageNo=1"}]},{"id":"111-PM-069","record":{"id":"111-PM-069","choice_explanations":[{"choice":1,"correct":true,"title":"援助時には使い捨てのエプロンを着用する。","explanation":"感染徴候がなくても排泄物には病原体が含まれる可能性があります。排便介助では衣服への汚染を防ぐため、使い捨てエプロンなどを用います。"},{"choice":2,"correct":false,"title":"使用済みのオムツは感染性廃棄物として処分する。","explanation":"家庭で使用したオムツを、感染徴候がない場合まで一律に感染性廃棄物として扱う必要はありません。自治体の分別方法に従って処分します。"},{"choice":3,"correct":false,"title":"使用済みの寝衣は次亜塩素酸ナトリウム液に浸す。","explanation":"感染徴候のない療養者の寝衣を一律に消毒液へ浸す必要はありません。汚れを適切に除いて洗濯し、十分に乾燥させることが基本です。"},{"choice":4,"correct":false,"title":"陰部洗浄で使用したボトルの洗浄に中性洗剤は用いない。","explanation":"洗浄ボトルの汚れを落とすために中性洗剤を使用できます。洗剤で洗浄してよくすすぎ、乾燥させることが清潔保持につながります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"感染徴候のない在宅療養者に対する床上での排便の援助において、訪問看護師が\n行う感染対策で適切なのはどれか。","choices":["援助時には使い捨てのエプロンを着用する。","使用済みのオムツは感染性廃棄物として処分する。","使用済みの寝衣は次亜塩素酸ナトリウム液に浸す。","陰部洗浄で使用したボトルの洗浄に中性洗剤は用いない。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":69,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[26],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B069"},"exam":111,"year":2022,"session":"PM","number":69},"sources":[]},{"id":"111-PM-070","record":{"id":"111-PM-070","choice_explanations":[{"choice":1,"correct":false,"title":"羽毛布団を取り除く。","explanation":"厚い布団は熱の放散を妨げますが、本人は手足の冷えを訴えています。直ちに全部取り除くより、室温を調整しながら寝具も本人に合わせて調整します。"},{"choice":2,"correct":true,"title":"冷房設備で室温を調整する。","explanation":"室温と湿度が高く、体に熱がこもりやすい状況です。冷房で室内環境を整えることが、本人の負担を抑えて熱の放散を助ける対応になります。"},{"choice":3,"correct":false,"title":"頓用の解熱薬を服用してもらう。","explanation":"体温上昇には暑い室内環境が関わっている可能性があります。まず環境を調整して状態を確認し、解熱薬の服用だけで対処しないようにします。"},{"choice":4,"correct":false,"title":"直ちに経口補水液を飲むよう促す。","explanation":"脱水が明らかとはいえず、心不全もあります。経口補水液を直ちに勧めるのではなく、水分管理の指示や循環状態を踏まえて判断します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さん(85 歳、女性)は1人暮らし。うっ血性心不全で臥床して過ごすことが多\ncongestive heart failure\nい。訪問看護師が訪問すると、A さんは体温 37.6 ℃、口唇の乾燥はなく、体熱感\nはあるが手足が冷えると言って羽毛布団を肩まで掛けている。室温 30 ℃、湿度 65\n%、外気温は 32 ℃、冷房設備はあるが使っていない。\nこのときの訪問看護師の対応で適切なのはどれか。","choices":["羽毛布団を取り除く。","冷房設備で室温を調整する。","頓用の解熱薬を服用してもらう。","直ちに経口補水液を飲むよう促す。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":70,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[26],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B070"},"exam":111,"year":2022,"session":"PM","number":70},"sources":[]},{"id":"111-PM-071","record":{"id":"111-PM-071","choice_explanations":[{"choice":1,"correct":true,"title":"装具の交換に必要な物品一式を2回分持参する。","explanation":"旅行先で装具が漏れたり交換が必要になったりする場合に備えます。必要物品を予備も含めて持つことで、外出先でも落ち着いて対処できます。"},{"choice":2,"correct":false,"title":"旅行中の水分摂取は1日 1,000 mL 以内に控える。","explanation":"尿路ストーマがあることだけを理由に水分を制限しません。尿の濃縮や尿路感染を防ぐためにも、個別の指示がない限り適切な水分摂取が必要です。"},{"choice":3,"correct":false,"title":"他の入浴客がいなければ装具を外して入浴できる。","explanation":"尿路ストーマからは自分の意思で止められず尿が流れます。公衆浴場では他の利用者の有無にかかわらず、装具を装着して入浴します。"},{"choice":4,"correct":false,"title":"オストメイト対応のトイレがなければ旅行先を変更する。","explanation":"対応トイレは便利ですが、ないことだけで旅行を中止する必要はありません。利用できる設備や装具の管理方法を事前に確認して準備します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さん(68 歳、男性)は妻(68 歳)と2人暮らし。膀胱癌で尿路ストーマを造設し\nbladder cancer\nている。A さんはストーマ装具の交換に慣れてきたため、妻と日帰りで近くの温\n泉地を旅行する計画を立てており、外来看護師に助言を求めた。\n外来看護師が A さんに助言する内容で適切なのはどれか。","choices":["装具の交換に必要な物品一式を2回分持参する。","旅行中の水分摂取は1日 1,000 mL 以内に控える。","他の入浴客がいなければ装具を外して入浴できる。","オストメイト対応のトイレがなければ旅行先を変更する。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":71,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[26],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B071"},"exam":111,"year":2022,"session":"PM","number":71},"sources":[]},{"id":"111-PM-072","record":{"id":"111-PM-072","choice_explanations":[{"choice":1,"correct":false,"title":"健側に頸部を回旋させ食事の介助をする。","explanation":"嚥下障害で頸部回旋を用いる場合は、障害側へ向ける方法があります。右半身麻痺という情報だけで健側への回旋を一律に勧めるのは適切ではありません。"},{"choice":2,"correct":true,"title":"野菜は繊維に対し垂直に切って調理する。","explanation":"野菜の繊維を断つように切ると、かみ切りやすくなります。食材の硬さや調理方法も調整して、食べやすい形態にすることが大切です。"},{"choice":3,"correct":false,"title":"歯肉出血がみられたら口腔ケアは中止する。","explanation":"出血の原因や程度を確認し、刺激を減らして清潔を保ちます。歯肉出血があるという理由だけで口腔ケアを中止すると、口腔環境が悪化することがあります。"},{"choice":4,"correct":false,"title":"食事中は A さんの好きなテレビ番組を見せる。","explanation":"食事中は食べ物や嚥下に注意を向けられる環境を整えます。テレビによる注意の分散は、安全な摂食を妨げる可能性があります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さん(76 歳、女性)は1人暮らし。脳血管疾患で右半身麻痺があり、障害高齢\ncerebrovascular disease\n者の日常生活自立度判定基準は B-2 である。週に2回の訪問看護を利用している。\n食事の準備と介助および食後の口腔ケアのため訪問介護を利用することになった。\n訪問介護の担当者は、A さんのケアについて訪問看護師に助言を求めた。\n訪問看護師が訪問介護の担当者に助言する内容で正しいのはどれか。","choices":["健側に頸部を回旋させ食事の介助をする。","野菜は繊維に対し垂直に切って調理する。","歯肉出血がみられたら口腔ケアは中止する。","食事中は A さんの好きなテレビ番組を見せる。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":72,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[27],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B072"},"exam":111,"year":2022,"session":"PM","number":72},"sources":[]},{"id":"111-PM-073","record":{"id":"111-PM-073","choice_explanations":[{"choice":1,"correct":false,"title":"勤務帯ごとに各看護師が担当する患者を決めて受け持つ。","explanation":"勤務帯ごとに患者を受け持つ方法は、患者を単位として看護を分担する方式です。機能別看護方式では、患者ではなく業務の内容を基準に分担します。"},{"choice":2,"correct":true,"title":"内容別に分類した看護業務を複数の看護師が分担して実施する。","explanation":"検温、清潔ケア、処置など、看護業務を内容別に分けて担当します。業務を効率的に進めやすい一方、患者の全体像の共有が重要になります。"},{"choice":3,"correct":false,"title":"1人の看護師が1人の患者を入院から退院まで継続して受け持つ。","explanation":"入院から退院まで特定の看護師が継続して責任を持つ説明は、プライマリーナーシングに当たります。業務別に分担する機能別看護とは異なります。"},{"choice":4,"correct":false,"title":"患者を複数のグループに分け、各グループを専属の看護師チームが受け持\nつ。","explanation":"看護師のチームで患者のグループを担当する説明は、チームナーシングに当たります。機能別看護方式は業務の種類ごとの分担が基本です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"機能別看護方式の説明で正しいのはどれか。","choices":["勤務帯ごとに各看護師が担当する患者を決めて受け持つ。","内容別に分類した看護業務を複数の看護師が分担して実施する。","1人の看護師が1人の患者を入院から退院まで継続して受け持つ。","患者を複数のグループに分け、各グループを専属の看護師チームが受け持\nつ。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":73,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[27],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B073"},"exam":111,"year":2022,"session":"PM","number":73},"sources":[]},{"id":"111-PM-074","record":{"id":"111-PM-074","choice_explanations":[{"choice":1,"correct":false,"title":"病院に導入が義務付けられている。","explanation":"クリニカルラダーは看護師の能力開発や評価に用いる仕組みです。すべての病院に導入が義務付けられているわけではありません。"},{"choice":2,"correct":false,"title":"ワーク・ライフ・バランスを目指すものである。","explanation":"ワーク・ライフ・バランスは仕事と生活の調和を図る考え方です。クリニカルラダーが直接示すのは、看護実践能力の段階と成長の目標です。"},{"choice":3,"correct":true,"title":"臨床実践に必要な能力が段階的に表現されている。","explanation":"臨床で必要となる看護実践能力を段階的に示したものです。自分の到達状況を確認し、次に目指す能力や学習課題を考えるために使います。"},{"choice":4,"correct":false,"title":"全国の病院で共通のクリニカルラダーが使用されている。","explanation":"共通の枠組みはありますが、施設独自のラダーもあります。全国の病院が同一のものを使っているとはいえません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"看護におけるクリニカルラダーについて正しいのはどれか。","choices":["病院に導入が義務付けられている。","ワーク・ライフ・バランスを目指すものである。","臨床実践に必要な能力が段階的に表現されている。","全国の病院で共通のクリニカルラダーが使用されている。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":74,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[27],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B074"},"exam":111,"year":2022,"session":"PM","number":74},"sources":[]},{"id":"111-PM-075","record":{"id":"111-PM-075","choice_explanations":[{"choice":1,"correct":false,"title":"国が指定する。","explanation":"災害拠点病院は都道府県が指定します。国は指定に関する要件などを示しますが、個々の病院を国が指定するという説明は適切ではありません。"},{"choice":2,"correct":false,"title":"災害発生時に指定される。","explanation":"災害に備えて平時から指定し、訓練や体制整備を行います。災害が起きてから初めて指定する病院ではありません。"},{"choice":3,"correct":true,"title":"広域搬送の体制を備えている。","explanation":"被災地内で対応しきれない患者を他の地域へ搬送する体制が求められます。災害拠点病院は、広域搬送に対応する拠点としての機能を担います。"},{"choice":4,"correct":false,"title":"地域災害拠点病院は各都道府県に1か所設置される。","explanation":"都道府県に原則1か所の基幹災害拠点病院と、地域災害拠点病院は区別します。地域災害拠点病院は二次医療圏ごとの整備が基本です。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"災害拠点病院の説明で正しいのはどれか。","choices":["国が指定する。","災害発生時に指定される。","広域搬送の体制を備えている。","地域災害拠点病院は各都道府県に1か所設置される。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":75,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[28],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B075"},"exam":111,"year":2022,"session":"PM","number":75},"sources":[{"title":"厚生労働省：災害拠点病院指定要件（2019年）","url":"https://www.mhlw.go.jp/content/10802000/000529357.pdf"}]},{"id":"111-PM-076","record":{"id":"111-PM-076","choice_explanations":[{"choice":1,"correct":false,"title":"ポリオ〈急性灰白髄炎〉\npoliomyelitis","explanation":"ポリオも国際的な感染症対策の対象ですが、この問題でいう三大感染症には含まれません。三大感染症はエイズ、結核、マラリアです。"},{"choice":2,"correct":true,"title":"マラリア\nmalaria","explanation":"世界の三大感染症として、エイズ、結核、マラリアが挙げられます。流行地での予防や診断・治療へのアクセスが国際保健上の課題です。"},{"choice":3,"correct":false,"title":"天然痘\nsmallpox","explanation":"天然痘は世界的な根絶が達成された感染症です。2015年時点で対策が課題となっている三大感染症の一つではありません。"},{"choice":4,"correct":false,"title":"麻 疹\nmeasles","explanation":"麻疹は感染力が強く予防接種が重要ですが、この問題でいう三大感染症の組合せには含まれません。名称として三つをまとめて覚えます。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"平成 27 年(2015 年)時点での世界の三大感染症に入るのはどれか。","choices":["ポリオ〈急性灰白髄炎〉\npoliomyelitis","マラリア\nmalaria","天然痘\nsmallpox","麻 疹\nmeasles"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":76,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[28],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B076"},"exam":111,"year":2022,"session":"PM","number":76},"sources":[{"title":"外務省：2015年の三大感染症資料","url":"https://www.mofa.go.jp/mofaj/gaiko/kansen/kikin/kikin_01.html"}]},{"id":"111-PM-077","record":{"id":"111-PM-077","choice_explanations":[{"choice":1,"correct":false,"title":"鎖 骨","explanation":"鎖骨は肩峰と関節をつくりますが、肩峰そのものがある骨ではありません。肩峰は肩甲骨の一部です。"},{"choice":2,"correct":false,"title":"胸骨柄","explanation":"胸骨柄は胸骨の上部にあり、鎖骨などと関節をつくります。肩峰は胸骨ではなく肩甲骨側の構造です。"},{"choice":3,"correct":true,"title":"肩甲棘","explanation":"肩甲棘は肩甲骨の背面にある隆起で、その外側への延長が肩峰になります。肩峰は鎖骨と肩鎖関節をつくります。"},{"choice":4,"correct":false,"title":"上腕骨","explanation":"上腕骨は肩甲骨の関節窩と肩関節をつくります。肩峰は上腕骨の突起ではなく、肩甲骨に属します。"},{"choice":5,"correct":false,"title":"烏口突起","explanation":"烏口突起も肩甲骨の一部ですが、肩峰とは別の突起です。肩峰は肩甲棘の外側への延長として位置します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"肩峰があるのはどれか。","choices":["鎖 骨","胸骨柄","肩甲棘","上腕骨","烏口突起"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":77,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[28],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B077"},"exam":111,"year":2022,"session":"PM","number":77},"sources":[]},{"id":"111-PM-078","record":{"id":"111-PM-078","choice_explanations":[{"choice":1,"correct":false,"title":"大腿二頭筋","explanation":"大腿二頭筋は主に膝関節を屈曲させ、長頭は股関節の伸展にも働きます。股関節を屈曲させる代表的な筋としては腸腰筋を選びます。"},{"choice":2,"correct":false,"title":"大殿筋","explanation":"大殿筋は主に股関節の伸展に働き、立ち上がりや階段の上りなどに関わります。股関節屈曲の主動作筋ではありません。"},{"choice":3,"correct":false,"title":"中殿筋","explanation":"中殿筋は主に股関節を外転させ、片脚で立つときに骨盤を支えます。股関節屈曲を代表する筋は腸腰筋です。"},{"choice":4,"correct":false,"title":"小殿筋","explanation":"小殿筋は主に股関節の外転や内旋に関わります。この問題で問われる股関節屈曲の代表的な筋には腸腰筋が当たります。"},{"choice":5,"correct":true,"title":"腸腰筋","explanation":"腸腰筋は大腰筋と腸骨筋からなり、大腿を体幹に近づける股関節屈曲に働きます。脚を前へ上げる動作と結び付けて覚えます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"股関節を屈曲させるのはどれか。","choices":["大腿二頭筋","大殿筋","中殿筋","小殿筋","腸腰筋"],"correct_answers":[5],"accepted_answer_sets":[[5]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":78,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[28],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B078"},"exam":111,"year":2022,"session":"PM","number":78},"sources":[]},{"id":"111-PM-079","record":{"id":"111-PM-079","choice_explanations":[{"choice":1,"correct":false,"title":"塩化物イオン","explanation":"塩化物イオンは細胞外液の主要な陰イオンです。赤血球の破壊による見かけの高値として、特に注意するのは細胞内に多いカリウムです。"},{"choice":2,"correct":false,"title":"重炭酸イオン","explanation":"重炭酸イオンは酸塩基平衡に関わります。溶血によって赤血球から大量に流出し、高値となる代表的な電解質としてはカリウムを選びます。"},{"choice":3,"correct":true,"title":"カリウムイオン","explanation":"赤血球内にはカリウムが多く含まれます。溶血するとカリウムが血漿中へ漏れ、体内の状態を反映しない偽の高値になることがあります。"},{"choice":4,"correct":false,"title":"カルシウムイオン","explanation":"カルシウムは溶血によって細胞内から大量に漏れ出す代表的な電解質ではありません。溶血検体で特に問題となるのはカリウムの偽高値です。"},{"choice":5,"correct":false,"title":"ナトリウムイオン","explanation":"ナトリウムは細胞外液に多い電解質です。細胞内に多いカリウムとは分布が異なり、溶血による偽高値の代表には当たりません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"採血時に操作を誤ったため溶血し、採血管内の血漿が暗赤色になってしまった。\nこの血漿の電解質濃度を測定したときに、本来の値よりも高くなるのはどれか。","choices":["塩化物イオン","重炭酸イオン","カリウムイオン","カルシウムイオン","ナトリウムイオン"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":79,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[29],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B079"},"exam":111,"year":2022,"session":"PM","number":79},"sources":[]},{"id":"111-PM-080","record":{"id":"111-PM-080","choice_explanations":[{"choice":1,"correct":false,"title":"尿 素","explanation":"尿素は腎機能の評価に用いられますが、尿細管で再吸収され、食事や代謝の影響も受けます。糸球体濾過量の推定に用いる代表的な生体内物質はクレアチニンです。"},{"choice":2,"correct":false,"title":"イヌリン","explanation":"イヌリンは糸球体濾過量を測定するために用いられますが、検査のために体外から投与する物質です。「生体内物質」という条件に合いません。"},{"choice":3,"correct":false,"title":"ビリルビン","explanation":"ビリルビンはヘモグロビンの分解に関連する物質で、肝臓や胆道の状態などを評価します。糸球体濾過量の推定には用いません。"},{"choice":4,"correct":true,"title":"クレアチニン","explanation":"クレアチニンは筋肉の代謝で生じ、主に腎臓から排泄されます。血清クレアチニン値などを用いて糸球体濾過量を推定します。"},{"choice":5,"correct":false,"title":"パラアミノ馬尿酸","explanation":"パラアミノ馬尿酸は腎血漿流量の測定に用いる物質です。体外から投与するもので、生体内物質による糸球体濾過量の推定という条件に合いません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"糸球体濾過量の推定に用いられる生体内物質はどれか。","choices":["尿 素","イヌリン","ビリルビン","クレアチニン","パラアミノ馬尿酸"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":80,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[29],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":1,"row_id":"B080"},"exam":111,"year":2022,"session":"PM","number":80},"sources":[]},{"id":"111-PM-081","record":{"id":"111-PM-081","choice_explanations":[{"choice":1,"correct":true,"title":"免疫複合体","explanation":"免疫複合体は体内の抗原と抗体が結合してでき、組織への沈着などにより障害を起こすことがあります。生体内部の要因として内因に分類します。"},{"choice":2,"correct":false,"title":"栄養素","explanation":"栄養素の不足や過剰は疾病の原因になりますが、摂取する栄養という外部からの要因です。この問題では内因ではなく外因に分類します。"},{"choice":3,"correct":false,"title":"温 度","explanation":"高温や低温による障害は、外部環境の物理的な要因によるものです。疾病の原因としては外因に当たります。"},{"choice":4,"correct":false,"title":"細 菌","explanation":"細菌は生体外から作用する生物学的な要因です。感染による疾病の原因となりますが、内因には分類しません。"},{"choice":5,"correct":false,"title":"薬 物","explanation":"薬物による有害作用は、外部から取り込まれる化学的な要因によるものです。この原因分類では外因に当たります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"疾病の内因となるのはどれか。","choices":["免疫複合体","栄養素","温 度","細 菌","薬 物"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":81,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[29],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B081"},"exam":111,"year":2022,"session":"PM","number":81},"sources":[]},{"id":"111-PM-082","record":{"id":"111-PM-082","choice_explanations":[{"choice":1,"correct":false,"title":"癌全体に対する発症頻度は約 10 % である。","explanation":"舌癌が癌全体の約10％を占めるという説明は適切ではありません。口腔癌の中での割合と、すべての癌の中での割合を混同しないようにします。"},{"choice":2,"correct":false,"title":"発症年齢は 20 歳代が多い。","explanation":"舌癌は若い世代にも生じますが、20歳代が発症の中心ではありません。若年者にも起こることと、好発年齢であることは区別します。"},{"choice":3,"correct":false,"title":"好発部位は舌尖である。","explanation":"舌癌は舌の側縁に多く、舌尖が代表的な好発部位ではありません。治りにくい潰瘍やしこりなどに注意します。"},{"choice":4,"correct":false,"title":"浸潤は起こさない。","explanation":"舌癌は周囲の組織に浸潤し、リンパ節などへ転移することがあります。浸潤を起こさない腫瘍ではありません。"},{"choice":5,"correct":true,"title":"扁平上皮癌が多い。","explanation":"舌癌の多くは、舌の粘膜を覆う扁平上皮に由来する扁平上皮癌です。発生する部位と、癌の組織型を結び付けて覚えます。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"舌癌について正しいのはどれか。\ntongue cancer","choices":["癌全体に対する発症頻度は約 10 % である。","発症年齢は 20 歳代が多い。","好発部位は舌尖である。","浸潤は起こさない。","扁平上皮癌が多い。"],"correct_answers":[5],"accepted_answer_sets":[[5]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":82,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[30],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B082"},"exam":111,"year":2022,"session":"PM","number":82},"sources":[{"title":"国立がん研究センター：舌がんについて","url":"https://ganjoho.jp/public/cancer/tongue/about.html"}]},{"id":"111-PM-083","record":{"id":"111-PM-083","choice_explanations":[{"choice":1,"correct":false,"title":"基礎疾患として高血圧症が多い。\nhypertension","explanation":"高血圧は認知症のリスクと関連しますが、アルツハイマー病の基礎疾患として必須ではありません。脳血管障害を基盤とする認知症との区別が必要です。"},{"choice":2,"correct":true,"title":"アミロイド β タンパクが蓄積する。","explanation":"アルツハイマー病ではアミロイドβタンパクの蓄積が特徴の一つです。タウタンパクの異常なども関わり、神経細胞の障害につながります。"},{"choice":3,"correct":false,"title":"初期には記銘力障害はみられない。","explanation":"新しいことを覚えにくい記銘力障害は、初期からみられる代表的な症状です。昔の記憶が残っていても、新しい出来事を記憶できないことがあります。"},{"choice":4,"correct":false,"title":"MRI 所見では前頭葉の萎縮が特徴的である。","explanation":"代表的な画像所見は海馬を含む内側側頭葉の萎縮です。前頭葉の萎縮を中心とする説明は、アルツハイマー病の典型的な特徴とは異なります。"},{"choice":5,"correct":false,"title":"脳血流シンチグラフィ所見では頭頂葉の血流増加がある。","explanation":"頭頂葉などでみられるのは血流の低下です。血流増加を特徴とする説明ではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"Alzheimer〈アルツハイマー〉病で正しいのはどれか。\nAlzheimer disease","choices":["基礎疾患として高血圧症が多い。\nhypertension","アミロイド β タンパクが蓄積する。","初期には記銘力障害はみられない。","MRI 所見では前頭葉の萎縮が特徴的である。","脳血流シンチグラフィ所見では頭頂葉の血流増加がある。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":83,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[30],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B083"},"exam":111,"year":2022,"session":"PM","number":83},"sources":[]},{"id":"111-PM-084","record":{"id":"111-PM-084","choice_explanations":[{"choice":1,"correct":false,"title":"先行期","explanation":"先行期は食べ物を認識し、食べる準備をする段階です。食塊が咽頭を通る際の喉頭口の閉鎖は、まだ起こる段階ではありません。"},{"choice":2,"correct":false,"title":"準備期","explanation":"準備期は食べ物をかみ、唾液と混ぜて飲み込みやすい食塊をつくる段階です。喉頭蓋による喉頭口の閉鎖は咽頭期に対応します。"},{"choice":3,"correct":false,"title":"口腔期","explanation":"口腔期では舌を使って食塊を咽頭へ送り込みます。気道を保護しながら咽頭を通過させる段階とは区別します。"},{"choice":4,"correct":true,"title":"咽頭期","explanation":"咽頭期では食塊が咽頭を通過し、喉頭蓋などの働きで気道を保護します。喉頭口の閉鎖は、食物が気管へ入るのを防ぐ仕組みの一部です。"},{"choice":5,"correct":false,"title":"食道期","explanation":"食道期では食塊が食道を通って胃へ送られます。喉頭蓋による喉頭口の閉鎖が主に働くのは、その前の咽頭期です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"食物の嚥下において喉頭蓋が喉頭口を閉鎖する時期はどれか。","choices":["先行期","準備期","口腔期","咽頭期","食道期"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":84,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[30],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B084"},"exam":111,"year":2022,"session":"PM","number":84},"sources":[]},{"id":"111-PM-085","record":{"id":"111-PM-085","choice_explanations":[{"choice":1,"correct":false,"title":"脳血管造影","explanation":"通常の脳血管造影は造影剤を血管内に入れ、X線で血管の形を調べます。放射性同位元素を含む薬剤を用いる検査ではありません。"},{"choice":2,"correct":false,"title":"膀胱鏡検査","explanation":"膀胱鏡検査は内視鏡を用いて膀胱の内部を直接観察します。放射性同位元素の体内分布を画像にする方法ではありません。"},{"choice":3,"correct":false,"title":"頭部 CT 検査","explanation":"通常の頭部CTは体の外からX線を照射して断層像をつくります。放射線を使いますが、放射性同位元素を投与する検査とは異なります。"},{"choice":4,"correct":false,"title":"腹部超音波検査","explanation":"腹部超音波検査は超音波の反射を利用します。X線や放射性同位元素は使用しません。"},{"choice":5,"correct":true,"title":"骨シンチグラフィ","explanation":"骨シンチグラフィでは放射性同位元素を含む薬剤を投与し、骨への集積を画像化します。骨の代謝が活発な部位などを調べる核医学検査です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"放射性同位元素を用いるのはどれか。","choices":["脳血管造影","膀胱鏡検査","頭部 CT 検査","腹部超音波検査","骨シンチグラフィ"],"correct_answers":[5],"accepted_answer_sets":[[5]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":85,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[31],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B085"},"exam":111,"year":2022,"session":"PM","number":85},"sources":[]},{"id":"111-PM-086","record":{"id":"111-PM-086","choice_explanations":[{"choice":1,"correct":true,"title":"介護保険法","explanation":"地域包括支援センターは介護保険法に規定されています。高齢者の総合相談、権利擁護、介護予防の支援などを地域で行う拠点です。"},{"choice":2,"correct":false,"title":"健康増進法","explanation":"健康増進法は国民の健康づくりなどに関する法律です。地域包括支援センターの目的を直接定めている法律ではありません。"},{"choice":3,"correct":false,"title":"社会福祉法","explanation":"社会福祉法は社会福祉事業などの基本を定めています。地域包括支援センターの設置や目的の根拠としては介護保険法を選びます。"},{"choice":4,"correct":false,"title":"地域保健法","explanation":"地域保健法は保健所や市町村保健センターなどに関する法律です。名称が似ていても、地域包括支援センターの根拠法とは異なります。"},{"choice":5,"correct":false,"title":"老人福祉法","explanation":"老人福祉法は高齢者福祉の措置や施設などを定めます。地域包括支援センターの目的を定めているのは介護保険法です。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"地域包括支援センターの目的を定める法律はどれか。","choices":["介護保険法","健康増進法","社会福祉法","地域保健法","老人福祉法"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":86,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[31],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B086"},"exam":111,"year":2022,"session":"PM","number":86},"sources":[{"title":"厚生労働省：介護保険法・地域包括支援センター","url":"https://www.mhlw.go.jp/web/t_doc?dataId=82998034&dataType=0&pageNo=4"}]},{"id":"111-PM-087","record":{"id":"111-PM-087","choice_explanations":[{"choice":1,"correct":false,"title":"Langerhans〈ランゲルハンス〉細胞","explanation":"ランゲルハンス細胞は主に皮膚で抗原提示などを担います。粥腫の形成に関わる代表的な組合せは血管内皮細胞と泡沫細胞です。"},{"choice":2,"correct":false,"title":"メサンギウム細胞","explanation":"メサンギウム細胞は腎臓の糸球体を支えるなどの働きを持ちます。動脈壁の粥腫を構成する代表的な細胞ではありません。"},{"choice":3,"correct":true,"title":"血管内皮細胞","explanation":"血管内皮の機能障害により、脂質や単球が血管壁へ入りやすくなります。内皮細胞の変化は粥状動脈硬化の進行に関わります。"},{"choice":4,"correct":false,"title":"肥満細胞","explanation":"肥満細胞はアレルギー反応などに関わります。炎症との関連はありますが、本問で問う粥腫形成の中心的な細胞としては内皮細胞と泡沫細胞を選びます。"},{"choice":5,"correct":true,"title":"泡沫細胞","explanation":"マクロファージなどが脂質を取り込むと泡沫細胞になります。血管壁への泡沫細胞の蓄積は、粥腫形成の重要な過程です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"動脈硬化症の粥腫形成に関与するのはどれか。2つ選べ。\narteriosclerosis","choices":["Langerhans〈ランゲルハンス〉細胞","メサンギウム細胞","血管内皮細胞","肥満細胞","泡沫細胞"],"correct_answers":[3,5],"accepted_answer_sets":[[3,5]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":87,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[31],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B087"},"exam":111,"year":2022,"session":"PM","number":87},"sources":[]},{"id":"111-PM-088","record":{"id":"111-PM-088","choice_explanations":[{"choice":1,"correct":false,"title":"ジフテリア\ndiphtheria","explanation":"ジフテリアの予防には、毒素を無毒化したトキソイドを用います。弱毒化した病原体を使う生ワクチンではありません。"},{"choice":2,"correct":false,"title":"日本脳炎\nJapanese encephalitis","explanation":"日本脳炎の予防接種は不活化ワクチンです。体内で増殖する弱毒化病原体を使う方式とは異なります。"},{"choice":3,"correct":false,"title":"破傷風\ntetanus","explanation":"破傷風の予防にはトキソイドを用い、毒素に対する免疫をつけます。生ワクチンには分類しません。"},{"choice":4,"correct":true,"title":"結 核\ntuberculosis","explanation":"結核の予防に用いるBCGは、弱毒化した菌を使う生ワクチンです。重い結核の予防を目的に接種します。"},{"choice":5,"correct":true,"title":"麻 疹\nmeasles","explanation":"麻疹の予防には弱毒化したウイルスを使う生ワクチンを用います。風疹と組み合わせたMRワクチンも生ワクチンです。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"予防接種に生ワクチンが使用される疾患はどれか。2つ選べ。","choices":["ジフテリア\ndiphtheria","日本脳炎\nJapanese encephalitis","破傷風\ntetanus","結 核\ntuberculosis","麻 疹\nmeasles"],"correct_answers":[4,5],"accepted_answer_sets":[[4,5]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":88,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[32],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B088"},"exam":111,"year":2022,"session":"PM","number":88},"sources":[{"title":"厚生労働省：生ワクチンの区分","url":"https://www.mhlw.go.jp/stf/seisakunitsuite/bunya/kenkou_iryou/kenkou/kekkaku-kansenshou03/rota_index_00003.html"}]},{"id":"111-PM-089","record":{"id":"111-PM-089","choice_explanations":[{"choice":1,"correct":false,"title":"磁気を用いる。","explanation":"電気けいれん療法は電気刺激を用います。磁気刺激を用いる経頭蓋磁気刺激療法とは、刺激の方法が異なります。"},{"choice":2,"correct":false,"title":"局所麻酔下で行う。","explanation":"修正型電気けいれん療法は全身麻酔下で行います。局所だけを麻酔して意識を保ったまま行う療法ではありません。"},{"choice":3,"correct":true,"title":"筋弛緩薬を用いる。","explanation":"筋弛緩薬を用いて全身の強い筋収縮を抑えます。麻酔や呼吸管理と合わせて、身体への負担やけがの危険を減らします。"},{"choice":4,"correct":false,"title":"発生頻度の高い有害事象は骨折である。","explanation":"筋弛緩薬で強い筋収縮を抑えるため、骨折が高頻度に起こるという説明は適切ではありません。頭痛や一時的な記憶への影響などに注意します。"},{"choice":5,"correct":true,"title":"薬物治療抵抗性のうつ病は適応になる。\ndepression","explanation":"薬物療法で十分な改善が得られないうつ病は適応になります。症状の重さや緊急性なども踏まえ、本人への説明を含めて実施を検討します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"修正型電気けいれん療法について正しいのはどれか。2つ選べ。","choices":["磁気を用いる。","局所麻酔下で行う。","筋弛緩薬を用いる。","発生頻度の高い有害事象は骨折である。","薬物治療抵抗性のうつ病は適応になる。\ndepression"],"correct_answers":[3,5],"accepted_answer_sets":[[3,5]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":89,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[32],"case_pages":[],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B089"},"exam":111,"year":2022,"session":"PM","number":89},"sources":[{"title":"国立精神・神経医療研究センター：修正型ECT","url":"https://hsp.ncnp.go.jp/clinical/department.php?@uid=yqTW51SLmuk1I4AB"}]},{"id":"111-PM-091","record":{"id":"111-PM-091","choice_explanations":[{"choice":1,"correct":true,"title":"トロポニン T","explanation":"トロポニンTは心筋の障害を捉えるために用います。強い胸痛とST変化から急性心筋梗塞が疑われるため、心筋障害の評価に優先度が高い検査です。"},{"choice":2,"correct":false,"title":"乳酸脱水素酵素","explanation":"乳酸脱水素酵素は多くの組織に含まれ、心筋以外の障害でも上昇します。急性の心筋障害を評価するには、より心筋に特異的なトロポニンTを優先します。"},{"choice":3,"correct":false,"title":"血清クレアチニン","explanation":"血清クレアチニンは腎機能の評価に重要ですが、心筋障害を直接示す項目ではありません。この場面では胸痛と心電図変化に対応した評価を優先します。"},{"choice":4,"correct":false,"title":"アスパラギン酸アミノトランスフェラーゼ","explanation":"ASTは肝臓や筋肉などにも含まれ、心筋に特異的ではありません。心筋梗塞が疑われる場面ではトロポニンTによる評価が適しています。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"救急外来到着時に A さんの状態をアセスメントするために優先度が高い血液検\n査項目はどれか。","choices":["トロポニン T","乳酸脱水素酵素","血清クレアチニン","アスパラギン酸アミノトランスフェラーゼ"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":"A さん(50 歳、男性、会社員)は半年ほど前から労作時に胸痛と呼吸困難感があり、\n狭心症と診断され内服治療を受けている。本日明け方から胸部に圧迫感があった。出\nangina pectoris\n勤途中に強い胸痛を自覚し、自ら救急車を要請した。救急外来到着時のバイタルサイ\nンは、体温 35.8 ℃、呼吸数 30/分、脈拍 112/分、血圧 96/52 mmHg、経皮的動脈血\n酸素飽和度〈SpO2〉93 %(酸素2L/分)。意識は清明。12 誘導心電図は V1〜V4 で ST\n上昇、Ⅱ、Ⅲ、aVF で ST 低下がみられた。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":91,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[34],"case_pages":[34],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B091"},"exam":111,"year":2022,"session":"PM","number":91},"sources":[]},{"id":"111-PM-092","record":{"id":"111-PM-092","choice_explanations":[{"choice":1,"correct":false,"title":"心拡大が認められる。","explanation":"提示された心胸郭比48％から心拡大があるとは判断しません。心胸郭比と、肺うっ血を示す肺動脈楔入圧や呼吸音は分けて評価します。"},{"choice":2,"correct":true,"title":"肺うっ血が起きている。","explanation":"Forrester分類Ⅱ群は、心拍出が保たれながら肺うっ血を伴う状態です。肺動脈楔入圧の上昇と両下肺野の副雑音も、肺うっ血を支持します。"},{"choice":3,"correct":false,"title":"末梢循環不全が起きている。","explanation":"心係数は2.4で、Forrester分類Ⅱ群と示されています。この時点では末梢循環不全より、肺うっ血がある状態として評価します。"},{"choice":4,"correct":false,"title":"左心室の収縮力が低下している。","explanation":"提示された左室駆出率58％は、収縮機能の低下を示す値ではありません。駆出率が保たれていても肺うっ血は起こり得ます。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"心臓カテーテル検査の結果、A さんは急性心筋梗塞と診断された。心係数 2.4\nacute myocardial infarction\nL/分/m2、肺動脈楔入圧 20 mmHg で Forrester〈フォレスター〉分類Ⅱ群であった。\n身体所見：両側下肺野で呼吸音が減弱しており、軽度の粗い断続性副雑音が聴取さ\nれる。\n心エコー検査：左室駆出率〈LVEF〉58 %\n胸部エックス線検査：心胸郭比〈CTR〉48 %\nこのときの A さんのアセスメントで適切なのはどれか。","choices":["心拡大が認められる。","肺うっ血が起きている。","末梢循環不全が起きている。","左心室の収縮力が低下している。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(50 歳、男性、会社員)は半年ほど前から労作時に胸痛と呼吸困難感があり、\n狭心症と診断され内服治療を受けている。本日明け方から胸部に圧迫感があった。出\nangina pectoris\n勤途中に強い胸痛を自覚し、自ら救急車を要請した。救急外来到着時のバイタルサイ\nンは、体温 35.8 ℃、呼吸数 30/分、脈拍 112/分、血圧 96/52 mmHg、経皮的動脈血\n酸素飽和度〈SpO2〉93 %(酸素2L/分)。意識は清明。12 誘導心電図は V1〜V4 で ST\n上昇、Ⅱ、Ⅲ、aVF で ST 低下がみられた。","preceding_context":[{"id":"111-PM-091","question":"救急外来到着時に A さんの状態をアセスメントするために優先度が高い血液検\n査項目はどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":92,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[34],"case_pages":[34],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B092"},"exam":111,"year":2022,"session":"PM","number":92},"sources":[{"title":"日本循環器学会：2017年心不全診療ガイドライン・Forrester分類","url":"https://www.j-circ.or.jp/cms/wp-content/uploads/2017/06/JCS2017_tsutsui_h.pdf"}]},{"id":"111-PM-093","record":{"id":"111-PM-093","choice_explanations":[{"choice":1,"correct":false,"title":"側臥位にする。","explanation":"低血圧、顔面蒼白、冷汗があり、まず循環不全の原因を確認します。意識は清明であり、側臥位への変更だけを最初の対応とはしません。"},{"choice":2,"correct":false,"title":"除細動器の準備を行う。","explanation":"除細動の対象となる不整脈は提示されていません。脈拍は整で意識もあるため、まずPCI後の出血などを確認し、速やかに応援を求めます。"},{"choice":3,"correct":true,"title":"穿刺部の出血の有無を確認する。","explanation":"カテーテル治療後の低血圧では、穿刺部からの出血などを直ちに確認します。顔面蒼白や冷汗も循環不全を疑う所見で、迅速な報告と対応が必要です。"},{"choice":4,"correct":false,"title":"鎮痛薬の処方を医師に相談する。","explanation":"帰室時の問題は低血圧と循環不全を疑う所見です。疼痛の訴えは示されておらず、鎮痛薬の相談を最初に行う場面ではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"その後、A さんは経皮的冠動脈形成術〈PCI〉を受けた。帰室時のバイタルサイン\nは、体温 36.2 ℃、呼吸数 20/分、脈拍 58/分、整、血圧 80/40 mmHg、経皮的動\n脈血酸素飽和度〈SpO2〉95 %(酸素1L/分)。顔面は蒼白、冷汗を認めた。意識は清\n明である。\nこのとき看護師が最初に行うことはどれか。","choices":["側臥位にする。","除細動器の準備を行う。","穿刺部の出血の有無を確認する。","鎮痛薬の処方を医師に相談する。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A さん(50 歳、男性、会社員)は半年ほど前から労作時に胸痛と呼吸困難感があり、\n狭心症と診断され内服治療を受けている。本日明け方から胸部に圧迫感があった。出\nangina pectoris\n勤途中に強い胸痛を自覚し、自ら救急車を要請した。救急外来到着時のバイタルサイ\nンは、体温 35.8 ℃、呼吸数 30/分、脈拍 112/分、血圧 96/52 mmHg、経皮的動脈血\n酸素飽和度〈SpO2〉93 %(酸素2L/分)。意識は清明。12 誘導心電図は V1〜V4 で ST\n上昇、Ⅱ、Ⅲ、aVF で ST 低下がみられた。","preceding_context":[{"id":"111-PM-091","question":"救急外来到着時に A さんの状態をアセスメントするために優先度が高い血液検\n査項目はどれか。"},{"id":"111-PM-092","question":"心臓カテーテル検査の結果、A さんは急性心筋梗塞と診断された。心係数 2.4\nacute myocardial infarction\nL/分/m2、肺動脈楔入圧 20 mmHg で Forrester〈フォレスター〉分類Ⅱ群であった。\n身体所見：両側下肺野で呼吸音が減弱しており、軽度の粗い断続性副雑音が聴取さ\nれる。\n心エコー検査：左室駆出率〈LVEF〉58 %\n胸部エックス線検査：心胸郭比〈CTR〉48 %\nこのときの A さんのアセスメントで適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":93,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[35],"case_pages":[34],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B093"},"exam":111,"year":2022,"session":"PM","number":93},"sources":[]},{"id":"111-PM-094","record":{"id":"111-PM-094","choice_explanations":[{"choice":1,"correct":false,"title":"発熱時の冷罨法は禁忌である。","explanation":"発熱は脳の代謝負担を増やすため、体温管理が必要です。冷罨法を一律に禁忌とはせず、悪寒や震えを起こさないよう適切に実施します。"},{"choice":2,"correct":false,"title":"徐脈時は経過観察とする。","explanation":"開頭術後の徐脈は頭蓋内圧亢進などの可能性も考えて評価します。意識や血圧、呼吸などと合わせて確認し、単に経過観察で済ませません。"},{"choice":3,"correct":true,"title":"ベッドの頭側を挙上する。","explanation":"頭側を挙上すると頭部からの静脈還流を助け、頭蓋内圧の上昇を抑えることにつながります。体位は手術後の指示や循環状態に合わせて調整します。"},{"choice":4,"correct":false,"title":"頸部を前屈させる。","explanation":"頸部の強い前屈は頸静脈の還流を妨げ、頭蓋内圧の上昇につながります。頭頸部は圧迫や過度の屈曲を避けて保ちます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"帰室後の看護として適切なのはどれか。","choices":["発熱時の冷罨法は禁忌である。","徐脈時は経過観察とする。","ベッドの頭側を挙上する。","頸部を前屈させる。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A さん(38 歳、会社員、女性)は夫と2人暮らし。通勤中に突然の頭痛を訴えて倒\nれ、救急搬送された。入院後に行った頭部 CT 検査および頭部 MRI 検査で、\n脳腫瘍と診断された。A さんは脳腫瘍摘出のために開頭術を受けた。\nbrain tumor","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":94,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[36],"case_pages":[36],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B094"},"exam":111,"year":2022,"session":"PM","number":94},"sources":[]},{"id":"111-PM-095","record":{"id":"111-PM-095","choice_explanations":[{"choice":1,"correct":false,"title":"｢定期的に髪の毛をそります｣","explanation":"照射部位の皮膚は刺激を受けやすくなります。定期的な剃毛は傷や刺激の原因となるため、皮膚保護の目的で勧める対応ではありません。"},{"choice":2,"correct":false,"title":"｢かゆみが強いときは温めてください｣","explanation":"温めると、かゆみや皮膚の刺激が強くなることがあります。照射部位を温めたりこすったりせず、処方されたケア方法に従います。"},{"choice":3,"correct":true,"title":"｢軟膏は放射線照射前に拭き取ってください｣","explanation":"不明：公式正答は照射前に軟膏を拭き取る対応です。ただし、外用剤の種類や塗布量による違いがあり、この条件で一律に除去する医学的根拠までは確認できていません。実際のケアは照射施設の指示に従います。"},{"choice":4,"correct":false,"title":"｢かゆみは放射線照射の終了日にはおさまります｣","explanation":"皮膚の症状は照射終了後もしばらく続くことがあります。終了日には必ず治まるとは説明せず、症状の観察とケアの継続を伝えます。"}],"status":"UNKNOWN","review_reason":"選択肢3の照射前外用剤除去は、剤形・塗布量や時代による差を解決できない。","fixes_made":[]},"input_anchor":{"question":"脳腫瘍摘出手術の結果、膠芽腫と診断され、A さんは放射線療法と抗癌薬内服\nglioblastoma\nによる化学療法を行うことになった。放射線療法を開始して1週後、A さんが頭\n皮のかゆみを訴えたため、副腎皮質ステロイド軟膏が処方された。\nA さんへの説明として適切なのはどれか。","choices":["｢定期的に髪の毛をそります｣","｢かゆみが強いときは温めてください｣","｢軟膏は放射線照射前に拭き取ってください｣","｢かゆみは放射線照射の終了日にはおさまります｣"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A さん(38 歳、会社員、女性)は夫と2人暮らし。通勤中に突然の頭痛を訴えて倒\nれ、救急搬送された。入院後に行った頭部 CT 検査および頭部 MRI 検査で、\n脳腫瘍と診断された。A さんは脳腫瘍摘出のために開頭術を受けた。\nbrain tumor","preceding_context":[{"id":"111-PM-094","question":"帰室後の看護として適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":95,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[36],"case_pages":[36],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B095"},"exam":111,"year":2022,"session":"PM","number":95},"sources":[{"title":"国立がん研究センター：放射線治療中の皮膚ケア","url":"https://ganjoho.jp/public/support/condition/skin/index.html"}]},{"id":"111-PM-096","record":{"id":"111-PM-096","choice_explanations":[{"choice":1,"correct":false,"title":"｢入浴は控えてください｣","explanation":"入浴を一律に控える必要はありません。皮膚を清潔にし、照射部位を強くこすらず、体調や治療上の指示に合わせて入浴します。"},{"choice":2,"correct":false,"title":"｢食べ物の制限はありません｣","explanation":"治療中は感染予防や薬との相互作用などに応じた食事上の注意が必要です。制限が全くないと断定せず、治療内容と体調に沿って説明します。"},{"choice":3,"correct":true,"title":"｢ガーデニングの時は手袋をしてください｣","explanation":"土に触れる作業では、手袋によって傷や微生物との接触を減らします。治療中の体調や血球の状態によっては作業を控える必要もあり、個別の指示を確認します。"},{"choice":4,"correct":false,"title":"｢発熱を伴わない咳は様子を見てください｣","explanation":"咳は発熱がなくても、感染や治療に伴う肺障害などの症状である可能性があります。発熱がないという理由だけで経過を見るよう勧めません。"},{"choice":5,"correct":true,"title":"｢性交渉の時はコンドームを使用してください｣","explanation":"抗癌薬治療中は妊娠を避ける必要があり、性交渉時のコンドーム使用を説明します。必要な避妊方法や期間は、使用薬の指示に従って確認します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"放射線療法と化学療法が開始されて 10 日が経過した。A さんはガーデニングの\n趣味があり、庭が気になるため週末の外泊を希望し、主治医から許可が出た。\n外泊にあたり A さんへの説明として適切なのはどれか。2つ選べ。","choices":["｢入浴は控えてください｣","｢食べ物の制限はありません｣","｢ガーデニングの時は手袋をしてください｣","｢発熱を伴わない咳は様子を見てください｣","｢性交渉の時はコンドームを使用してください｣"],"correct_answers":[3,5],"accepted_answer_sets":[[3,5]],"case_text":"A さん(38 歳、会社員、女性)は夫と2人暮らし。通勤中に突然の頭痛を訴えて倒\nれ、救急搬送された。入院後に行った頭部 CT 検査および頭部 MRI 検査で、\n脳腫瘍と診断された。A さんは脳腫瘍摘出のために開頭術を受けた。\nbrain tumor","preceding_context":[{"id":"111-PM-094","question":"帰室後の看護として適切なのはどれか。"},{"id":"111-PM-095","question":"脳腫瘍摘出手術の結果、膠芽腫と診断され、A さんは放射線療法と抗癌薬内服\nglioblastoma\nによる化学療法を行うことになった。放射線療法を開始して1週後、A さんが頭\n皮のかゆみを訴えたため、副腎皮質ステロイド軟膏が処方された。\nA さんへの説明として適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":96,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[37],"case_pages":[36],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B096"},"exam":111,"year":2022,"session":"PM","number":96},"sources":[{"title":"国立がん研究センター：感染しやすい・白血球減少","url":"https://ganjoho.jp/public/support/condition/FN/index.html"},{"title":"国立がん研究センター：治療中の性生活への影響","url":"https://ganjoho.jp/public/dia_tre/sexual_health_issues/sexual_health_issues_03.html"}]},{"id":"111-PM-097","record":{"id":"111-PM-097","choice_explanations":[{"choice":1,"correct":false,"title":"｢面会に来てください｣","explanation":"面会は関係を保つ助けになりますが、息子の妻は睡眠不足で体調を崩しています。新たな役割を求めるより、まず休息を確保することが優先されます。"},{"choice":2,"correct":false,"title":"｢家族会に参加しましょう｣","explanation":"家族会は情報交換や支え合いに役立ちますが、今は介護者自身の体調回復が先です。参加を勧めるのは負担や希望を確認してからにします。"},{"choice":3,"correct":true,"title":"｢まずは休息をとりましょう｣","explanation":"介護を担ってきた息子の妻は、睡眠不足から体調を崩しています。施設入所を機にまず休めるよう支援し、介護への責任感による負担を軽くします。"},{"choice":4,"correct":false,"title":"｢認知症への対応を覚えましょう｣","explanation":"認知症への対応を学ぶことは役立ちますが、今さらに課題を課すと負担になります。まず体調と休息を優先し、回復後に必要な支援を考えます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"看護師から A さんに施設について説明したが、その後も A さんは｢ここはどこ｣\nと繰り返し聞いていた。息子の妻は｢私がやらなければいけないことは何ですか｣と\n聞いてきた。\n息子の妻に対する看護師の対応で最も適切なのはどれか。","choices":["｢面会に来てください｣","｢家族会に参加しましょう｣","｢まずは休息をとりましょう｣","｢認知症への対応を覚えましょう｣"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A さん(82 歳、女性)は息子(57 歳、会社員)と息子の妻(55 歳、パート勤務)との3\n人暮らし。3年前に Alzheimer〈アルツハイマー〉型認知症と診断され、認知症高齢者\nAlzheimer disease\nの日常生活自立度判定基準Ⅱb、要介護2である。A さんの介護は、主に息子の妻が\n行っていた。A さんは、声かけがあれば日常生活動作〈ADL〉を自分で行うことがで\nきた。しかし、A さんは徐々に認知症が重度化し、1人で外出すると帰ってくるこ\nとができなくなり、夜間に落ちつきなく動き回ることが多くなった。息子と息子の妻\nは A さんの介護について介護支援専門員に相談していたが、息子の妻は睡眠不足と\nなり、体調を崩してしまった。そのため、A さんは介護老人保健施設に入所するこ\nとになった。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":97,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[38],"case_pages":[38],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B097"},"exam":111,"year":2022,"session":"PM","number":97},"sources":[]},{"id":"111-PM-098","record":{"id":"111-PM-098","choice_explanations":[{"choice":1,"correct":false,"title":"｢他の入所者と話をしましょう｣","explanation":"他の入所者との交流が役立つことはありますが、まず帰宅したい気持ちや理由を受け止めます。直ちに別の活動へ誘うだけでは不安を理解できません。"},{"choice":2,"correct":true,"title":"｢椅子に座ってお話ししませんか｣","explanation":"落ち着いて話せる場へ誘い、夕食を作らなければという本人の思いを聴きます。帰宅願望を頭から否定せず、安心できる関わりを行います。"},{"choice":3,"correct":false,"title":"｢入所中なので家には帰れません｣","explanation":"事実だけを伝えて帰宅を否定すると、不安や反発が強くなることがあります。本人が帰ろうとする理由を受け止めて関わることが必要です。"},{"choice":4,"correct":false,"title":"｢歩くのは危ないのでやめましょう｣","explanation":"歩いていること自体を一律に止めると、本人の行動を制限する対応になります。安全を確保しつつ、帰ろうとする気持ちを聴きます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"入所した日の夕方、A さんは自分の荷物をまとめて｢夕食を作らなければいけな\nいので、家に帰ります｣と施設内を歩いている。\nA さんへの看護師の対応で適切なのはどれか。","choices":["｢他の入所者と話をしましょう｣","｢椅子に座ってお話ししませんか｣","｢入所中なので家には帰れません｣","｢歩くのは危ないのでやめましょう｣"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(82 歳、女性)は息子(57 歳、会社員)と息子の妻(55 歳、パート勤務)との3\n人暮らし。3年前に Alzheimer〈アルツハイマー〉型認知症と診断され、認知症高齢者\nAlzheimer disease\nの日常生活自立度判定基準Ⅱb、要介護2である。A さんの介護は、主に息子の妻が\n行っていた。A さんは、声かけがあれば日常生活動作〈ADL〉を自分で行うことがで\nきた。しかし、A さんは徐々に認知症が重度化し、1人で外出すると帰ってくるこ\nとができなくなり、夜間に落ちつきなく動き回ることが多くなった。息子と息子の妻\nは A さんの介護について介護支援専門員に相談していたが、息子の妻は睡眠不足と\nなり、体調を崩してしまった。そのため、A さんは介護老人保健施設に入所するこ\nとになった。","preceding_context":[{"id":"111-PM-097","question":"看護師から A さんに施設について説明したが、その後も A さんは｢ここはどこ｣\nと繰り返し聞いていた。息子の妻は｢私がやらなければいけないことは何ですか｣と\n聞いてきた。\n息子の妻に対する看護師の対応で最も適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":98,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[38],"case_pages":[38],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B098"},"exam":111,"year":2022,"session":"PM","number":98},"sources":[]},{"id":"111-PM-099","record":{"id":"111-PM-099","choice_explanations":[{"choice":1,"correct":false,"title":"朝の入浴を勧める。","explanation":"朝の入浴が覚醒を促す場合はありますが、眠気が強い状態では負担にもなります。日中の活動と光の刺激によって生活リズムを整える対応が適しています。"},{"choice":2,"correct":true,"title":"日中の散歩に誘う。","explanation":"日中に散歩して光を浴び、体を動かすことは、昼夜の生活リズムを整える助けになります。本人の体調や眠気に合わせて無理なく誘います。"},{"choice":3,"correct":false,"title":"朝は A さんが自分で起きるまで待つ。","explanation":"起きるまで待つだけでは、昼夜逆転の状態が続く可能性があります。朝の光や日中の活動を取り入れ、少しずつ覚醒と睡眠のリズムを整えます。"},{"choice":4,"correct":false,"title":"日中は椅子に座って過ごしてもらう。","explanation":"椅子に座ったまま眠っているため、同じ過ごし方では日中の覚醒が促されません。本人に合う活動を取り入れることが必要です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"入所して1週後。A さんは、朝、声をかけられてもなかなか目を覚まさない。\n午前中は看護師が他の入所者と交流することを目的に共有スペースに誘導するが、\nA さんは共有スペースの椅子に座ったまま眠ってしまい、レクリエーションへ誘\nわれても参加はしない。夕方から夜間にかけて A さんは活動的となり、施設の廊\n下を歩き職員に話しかけている。\nA さんへの看護師の対応で最も適切なのはどれか。","choices":["朝の入浴を勧める。","日中の散歩に誘う。","朝は A さんが自分で起きるまで待つ。","日中は椅子に座って過ごしてもらう。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(82 歳、女性)は息子(57 歳、会社員)と息子の妻(55 歳、パート勤務)との3\n人暮らし。3年前に Alzheimer〈アルツハイマー〉型認知症と診断され、認知症高齢者\nAlzheimer disease\nの日常生活自立度判定基準Ⅱb、要介護2である。A さんの介護は、主に息子の妻が\n行っていた。A さんは、声かけがあれば日常生活動作〈ADL〉を自分で行うことがで\nきた。しかし、A さんは徐々に認知症が重度化し、1人で外出すると帰ってくるこ\nとができなくなり、夜間に落ちつきなく動き回ることが多くなった。息子と息子の妻\nは A さんの介護について介護支援専門員に相談していたが、息子の妻は睡眠不足と\nなり、体調を崩してしまった。そのため、A さんは介護老人保健施設に入所するこ\nとになった。","preceding_context":[{"id":"111-PM-097","question":"看護師から A さんに施設について説明したが、その後も A さんは｢ここはどこ｣\nと繰り返し聞いていた。息子の妻は｢私がやらなければいけないことは何ですか｣と\n聞いてきた。\n息子の妻に対する看護師の対応で最も適切なのはどれか。"},{"id":"111-PM-098","question":"入所した日の夕方、A さんは自分の荷物をまとめて｢夕食を作らなければいけな\nいので、家に帰ります｣と施設内を歩いている。\nA さんへの看護師の対応で適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":99,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[39],"case_pages":[38],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B099"},"exam":111,"year":2022,"session":"PM","number":99},"sources":[]},{"id":"111-PM-100","record":{"id":"111-PM-100","choice_explanations":[{"choice":1,"correct":false,"title":"ズボンのウエスト部分をつかんで引き上げる。","explanation":"ズボンをつかんで引き上げるだけでは姿勢を安定させにくく、衣服がずれる危険もあります。体幹や骨盤を適切に支え、本人の力を生かして介助します。"},{"choice":2,"correct":false,"title":"ベッドの高さを車椅子の座面より低くする。","explanation":"ベッドが車椅子より低いと、立ち上がりや移動の負担が増します。足底の接地を確かめながら、移乗しやすい高さに調整します。"},{"choice":3,"correct":false,"title":"床に離床センサーマットを設置する。","explanation":"離床センサーは離床の検知には役立ちますが、移乗動作を直接支える援助ではありません。この場面では姿勢と循環状態の安全確認を優先します。"},{"choice":4,"correct":true,"title":"車椅子を A さんの左側に準備する。","explanation":"右上下肢に麻痺があるため、健側の左側に車椅子を置きます。使える側の力を生かして移乗しやすい位置関係にします。"},{"choice":5,"correct":true,"title":"移乗前に血圧測定を行う。","explanation":"移乗前に血圧を確認し、姿勢変化による循環への影響に注意します。立位が不安定な状態なので、身体機能と全身状態の両方を確認することが必要です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんへの移乗時の援助で適切なのはどれか。2つ選べ。","choices":["ズボンのウエスト部分をつかんで引き上げる。","ベッドの高さを車椅子の座面より低くする。","床に離床センサーマットを設置する。","車椅子を A さんの左側に準備する。","移乗前に血圧測定を行う。"],"correct_answers":[4,5],"accepted_answer_sets":[[4,5]],"case_text":"A さん(83 歳、男性)は妻(81 歳)と2人暮らし。息子夫婦は共働きで同市内に住ん\nでいる。A さんは自宅の廊下で倒れているところを妻に発見され、救急搬送された。\nA さんは右上下肢に力が入らず、妻の声かけにうなずくが発語はなかった。頭部 CT\nで左中大脳動脈領域の脳梗塞と診断されたため救急外来で血栓溶解療法が行われ、入\ncerebral infarction\n院となった。血栓溶解療法による治療後2週。A さんは右上下肢麻痺、失語などの\n後遺症があるが、自宅への退院を希望したため、機能訓練の目的で回復期リハビリ\nテーション病棟に転棟した。転棟後1日。A さんはベッドから車椅子への移乗動作\nの訓練を始めたが、健側の下肢筋力が低下しているため、立位のときにバランスを崩\nしやすい状況である。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":100,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[40],"case_pages":[40],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B100"},"exam":111,"year":2022,"session":"PM","number":100},"sources":[]},{"id":"111-PM-101","record":{"id":"111-PM-101","choice_explanations":[{"choice":1,"correct":true,"title":"A さんの言葉を推測しながら話す。","explanation":"言いたい内容を推測しながら、本人に「こういうことですか」と確認します。勝手に決めつけず、待つ時間や身振りも使って意思の表出を支えます。"},{"choice":2,"correct":false,"title":"A さんの言い誤りを訂正する。","explanation":"言い誤りをその都度訂正すると、話す意欲が低下することがあります。言葉の正確さを求めるより、伝えようとしている内容を受け止めます。"},{"choice":3,"correct":false,"title":"大きな声で話す。","explanation":"話の理解は保たれているようで、聴力低下は示されていません。大声にするより、分かりやすく話し、返答を待つことが大切です。"},{"choice":4,"correct":false,"title":"話題を変える。","explanation":"言葉が出にくいからと話題を変えると、本人の伝えたいことが置き去りになります。急がずに表出を待ち、必要な手掛かりを補います。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんは妻や看護師との話の内容は理解しているようだが、返答の際に言葉を\n間違えてしまうことや言葉がなかなか出てこないことがある。\nA さんへの看護師の対応で適切なのはどれか。","choices":["A さんの言葉を推測しながら話す。","A さんの言い誤りを訂正する。","大きな声で話す。","話題を変える。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":"A さん(83 歳、男性)は妻(81 歳)と2人暮らし。息子夫婦は共働きで同市内に住ん\nでいる。A さんは自宅の廊下で倒れているところを妻に発見され、救急搬送された。\nA さんは右上下肢に力が入らず、妻の声かけにうなずくが発語はなかった。頭部 CT\nで左中大脳動脈領域の脳梗塞と診断されたため救急外来で血栓溶解療法が行われ、入\ncerebral infarction\n院となった。血栓溶解療法による治療後2週。A さんは右上下肢麻痺、失語などの\n後遺症があるが、自宅への退院を希望したため、機能訓練の目的で回復期リハビリ\nテーション病棟に転棟した。転棟後1日。A さんはベッドから車椅子への移乗動作\nの訓練を始めたが、健側の下肢筋力が低下しているため、立位のときにバランスを崩\nしやすい状況である。","preceding_context":[{"id":"111-PM-100","question":"A さんへの移乗時の援助で適切なのはどれか。2つ選べ。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":101,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[40],"case_pages":[40],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B101"},"exam":111,"year":2022,"session":"PM","number":101},"sources":[]},{"id":"111-PM-102","record":{"id":"111-PM-102","choice_explanations":[{"choice":1,"correct":false,"title":"施設入所の検討を提案する。","explanation":"本人は自宅退院を希望し、日常動作も改善しています。施設を先に提案するより、妻が現在の能力を理解できるよう支援します。"},{"choice":2,"correct":false,"title":"トイレ介助の方法を指導する。","explanation":"トイレ介助の練習は必要になりますが、妻は本人の活動できる姿を十分に見ていません。まず機能訓練の様子を共有し、不安の内容を整理します。"},{"choice":3,"correct":true,"title":"A さんの機能訓練中の様子の見学を勧める。","explanation":"妻は疲れて休む姿を主に見て、退院後の生活を心配しています。機能訓練を見学することで、できることや回復の様子を具体的に理解できます。"},{"choice":4,"correct":false,"title":"息子夫婦にも介護に参加してもらうよう助言する。","explanation":"息子夫婦の支援は相談できますが、協力可能な状況はまだ分かりません。参加を先に求めるより、本人の能力と妻の不安を共有することが優先です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"転棟後5週。A さんは歩行練習が開始となり、病棟内では日常生活動作〈ADL〉\nも徐々に自立してきている。食事は時々むせがみられるが、配膳すれば自力で摂取\nできる。排泄は車椅子でトイレへ移動しており、ズボンの着脱に介助が必要であ\nる。入浴はシャワーチェアーに座り、手が届くところは自分で洗うことができる。\n歯磨きは一部介助が必要である。A さんは早く自宅に帰りたいと話し、午前と午\n後の機能訓練には積極的に参加しているが、機能訓練後は｢疲れて何もしたくない｣\nとベッドで横になり眠っている。夕方に面会に来た妻は｢面会時にいつも疲れたと\n言って眠っているので、このままの状態で退院して家で世話ができるかどうか自信\nがありません。息子夫婦も仕事が忙しいので、介護を手伝ってもらえるかわかりま\nせん｣と言っている。\n看護師の妻への対応で最も適切なのはどれか。","choices":["施設入所の検討を提案する。","トイレ介助の方法を指導する。","A さんの機能訓練中の様子の見学を勧める。","息子夫婦にも介護に参加してもらうよう助言する。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A さん(83 歳、男性)は妻(81 歳)と2人暮らし。息子夫婦は共働きで同市内に住ん\nでいる。A さんは自宅の廊下で倒れているところを妻に発見され、救急搬送された。\nA さんは右上下肢に力が入らず、妻の声かけにうなずくが発語はなかった。頭部 CT\nで左中大脳動脈領域の脳梗塞と診断されたため救急外来で血栓溶解療法が行われ、入\ncerebral infarction\n院となった。血栓溶解療法による治療後2週。A さんは右上下肢麻痺、失語などの\n後遺症があるが、自宅への退院を希望したため、機能訓練の目的で回復期リハビリ\nテーション病棟に転棟した。転棟後1日。A さんはベッドから車椅子への移乗動作\nの訓練を始めたが、健側の下肢筋力が低下しているため、立位のときにバランスを崩\nしやすい状況である。","preceding_context":[{"id":"111-PM-100","question":"A さんへの移乗時の援助で適切なのはどれか。2つ選べ。"},{"id":"111-PM-101","question":"A さんは妻や看護師との話の内容は理解しているようだが、返答の際に言葉を\n間違えてしまうことや言葉がなかなか出てこないことがある。\nA さんへの看護師の対応で適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":102,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[41],"case_pages":[40],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B102"},"exam":111,"year":2022,"session":"PM","number":102},"sources":[]},{"id":"111-PM-103","record":{"id":"111-PM-103","choice_explanations":[{"choice":1,"correct":false,"title":"昏睡状態である。","explanation":"昏睡は重い状態であり、中等度脱水の一般的な所見としては選びません。意識状態は重要な観察項目ですが、問題文にない昏睡を補って判断しません。"},{"choice":2,"correct":false,"title":"流涙は普段と変わらない。","explanation":"脱水では涙の量が減ることがあります。普段と変わらない流涙を、中等度脱水に特徴的な所見とはしません。"},{"choice":3,"correct":false,"title":"体重は3日前と変わらない。","explanation":"脱水では体内の水分が失われ、体重が減少します。発症前の体重との比較は脱水の程度を判断する手掛かりになります。"},{"choice":4,"correct":false,"title":"排尿頻度は普段通りである。","explanation":"脱水では腎臓が水分を保持しようとするため、尿量や排尿回数が減ることがあります。普段通りの排尿は特徴的な所見ではありません。"},{"choice":5,"correct":true,"title":"皮膚のツルゴールは低下している。","explanation":"脱水では皮膚の張りが低下し、つまんだ皮膚が戻りにくくなることがあります。皮膚のツルゴールは、他の所見と合わせて脱水を評価する指標です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A ちゃんにみられる状態はどれか。","choices":["昏睡状態である。","流涙は普段と変わらない。","体重は3日前と変わらない。","排尿頻度は普段通りである。","皮膚のツルゴールは低下している。"],"correct_answers":[5],"accepted_answer_sets":[[5]],"case_text":"A ちゃん(2歳 10 か月、女児)は昨日から下痢と嘔吐を繰り返し、食事が摂れなく\nなったため、母親に抱かれて小児科外来を受診した。診察の結果、ウイルス性胃腸炎\nviral gastroenteritis\nによる中等度の脱水症と診断され入院した。入院時、体温 38.2 ℃、呼吸数 36/分、\ndehydration\n心拍数 136/分であった。3日前の保育所の身体計測では身長 90 cm、体重 12.5 kg で\nあった。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":103,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[42],"case_pages":[42],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B103"},"exam":111,"year":2022,"session":"PM","number":103},"sources":[]},{"id":"111-PM-104","record":{"id":"111-PM-104","choice_explanations":[{"choice":1,"correct":false,"title":"布オムツに切り替える。","explanation":"紙オムツから布オムツへ変更しても感染予防にはつながりません。便の処理時に周囲を汚染しないよう、適切に交換・廃棄することが重要です。"},{"choice":2,"correct":false,"title":"使い捨て手袋は1日1回交換する。","explanation":"手袋はオムツ交換ごとに取り替えます。同じ手袋を使い続けると、便に含まれる病原体を周囲へ広げる原因になります。"},{"choice":3,"correct":true,"title":"オムツ交換後に石けんで手洗いを行う。","explanation":"便に触れる機会があるため、交換後は石けんと流水で手を洗います。手袋を使った場合も、脱いだ後の手洗いが必要です。"},{"choice":4,"correct":false,"title":"アルコール入りのおしり拭きで殿部の清拭を行う。","explanation":"下痢が続く皮膚にアルコールを使うと刺激になります。皮膚を傷めない方法で便を除き、必要に応じて保護することが大切です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A ちゃんは、個室隔離での入院となり、持続点滴静脈内注射が開始された。排\n泄が自立していないため普段から紙オムツを使用している。\nA ちゃんのオムツ交換における注意点について、入院に付き添う母親への看護\n師の説明で適切なのはどれか。","choices":["布オムツに切り替える。","使い捨て手袋は1日1回交換する。","オムツ交換後に石けんで手洗いを行う。","アルコール入りのおしり拭きで殿部の清拭を行う。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A ちゃん(2歳 10 か月、女児)は昨日から下痢と嘔吐を繰り返し、食事が摂れなく\nなったため、母親に抱かれて小児科外来を受診した。診察の結果、ウイルス性胃腸炎\nviral gastroenteritis\nによる中等度の脱水症と診断され入院した。入院時、体温 38.2 ℃、呼吸数 36/分、\ndehydration\n心拍数 136/分であった。3日前の保育所の身体計測では身長 90 cm、体重 12.5 kg で\nあった。","preceding_context":[{"id":"111-PM-103","question":"A ちゃんにみられる状態はどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":104,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[42],"case_pages":[42],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B104"},"exam":111,"year":2022,"session":"PM","number":104},"sources":[]},{"id":"111-PM-105","record":{"id":"111-PM-105","choice_explanations":[{"choice":1,"correct":false,"title":"プレイルームで遊べること","explanation":"個室隔離が続いているため、共有のプレイルーム利用は感染を広げる可能性があります。個室内で楽しめる遊びを工夫します。"},{"choice":2,"correct":false,"title":"アイスクリームを食べてよいこと","explanation":"嘔吐がなくても下痢は続いています。アイスクリームを食べてよいと一律に伝えるのではなく、食事の再開状況や内容について指示を確認します。"},{"choice":3,"correct":false,"title":"個室隔離が明日、解除されること","explanation":"隔離解除の時期は症状や感染対策の基準によって判断します。現在の情報だけで翌日に解除できるとは約束できません。"},{"choice":4,"correct":true,"title":"A ちゃんの好きなおもちゃを自宅から持参してよいこと","explanation":"慣れたおもちゃは安心感を与え、隔離中でも遊ぶ機会をつくれます。清潔に扱える物を選び、個室内で年齢に合った遊びを支援します。"},{"choice":5,"correct":false,"title":"A ちゃんが静かに過ごせるよう看護師の訪室を控えること","explanation":"訪室を控えるだけでは、状態観察や母子への支援が不足します。休息に配慮しながら、遊びや不安への対応も含めて関わります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"入院2日。A ちゃんは、水様便は続いているが嘔吐はなくなった。付き添って\nる母親は｢A は大泣きして、ストレスが溜まっているみたいです。アイスクリーム\nを食べたいみたいです｣と看護師に話した。\nこのときに看護師が母親に伝える内容で適切なのはどれか。","choices":["プレイルームで遊べること","アイスクリームを食べてよいこと","個室隔離が明日、解除されること","A ちゃんの好きなおもちゃを自宅から持参してよいこと","A ちゃんが静かに過ごせるよう看護師の訪室を控えること"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A ちゃん(2歳 10 か月、女児)は昨日から下痢と嘔吐を繰り返し、食事が摂れなく\nなったため、母親に抱かれて小児科外来を受診した。診察の結果、ウイルス性胃腸炎\nviral gastroenteritis\nによる中等度の脱水症と診断され入院した。入院時、体温 38.2 ℃、呼吸数 36/分、\ndehydration\n心拍数 136/分であった。3日前の保育所の身体計測では身長 90 cm、体重 12.5 kg で\nあった。","preceding_context":[{"id":"111-PM-103","question":"A ちゃんにみられる状態はどれか。"},{"id":"111-PM-104","question":"A ちゃんは、個室隔離での入院となり、持続点滴静脈内注射が開始された。排\n泄が自立していないため普段から紙オムツを使用している。\nA ちゃんのオムツ交換における注意点について、入院に付き添う母親への看護\n師の説明で適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":105,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[43],"case_pages":[42],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B105"},"exam":111,"year":2022,"session":"PM","number":105},"sources":[]},{"id":"111-PM-106","record":{"id":"111-PM-106","choice_explanations":[{"choice":1,"correct":false,"title":"｢排泄後は会陰部を消毒しましょう｣","explanation":"排泄後は会陰部を清潔に保ちますが、毎回の消毒を一律に行う必要はありません。やさしく洗浄するなど、指示された清潔ケアを行います。"},{"choice":2,"correct":false,"title":"｢会陰縫合部が痛くなったら温めましょう｣","explanation":"分娩直後の縫合部痛は、出血や腫脹などの確認が必要です。痛みが出たらすぐ温めると決めず、状態を観察して適切な対応を選びます。"},{"choice":3,"correct":false,"title":"｢6時間おきにトイレに行って排尿しましょう｣","explanation":"産後は尿意が分かりにくくなることがあり、膀胱の充満が子宮収縮を妨げます。6時間ごとまで待つのではなく、排尿状況を確認して適切に促します。"},{"choice":4,"correct":true,"title":"｢悪露に血の塊が混じったら看護師に知らせてください｣","explanation":"悪露に血の塊が混じった場合は、出血量や子宮収縮の状態を確認する必要があります。異常の早期発見につながるため、看護師へ知らせるよう説明します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"帰室時に看護師が A さんに行う説明で適切なのはどれか。","choices":["｢排泄後は会陰部を消毒しましょう｣","｢会陰縫合部が痛くなったら温めましょう｣","｢6時間おきにトイレに行って排尿しましょう｣","｢悪露に血の塊が混じったら看護師に知らせてください｣"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A さん(32 歳、初産婦)は妊娠 39 週4日に 3,200 g の男児を経腟分娩で出産した。\n分娩時に会陰切開縫合術を受けた。児の Apgar〈アプガー〉スコアは1分後9点、5\n分後 10 点であった。分娩時の出血量 200 mL、分娩所要時間 12 時間 30 分であった。\n分娩室から病室に帰室する前に尿意を自覚したためトイレまで歩行し、排尿があっ\nた。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":106,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[44],"case_pages":[44],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B106"},"exam":111,"year":2022,"session":"PM","number":106},"sources":[]},{"id":"111-PM-107","record":{"id":"111-PM-107","choice_explanations":[{"choice":1,"correct":false,"title":"会陰縫合部の感染を起こしている。","explanation":"縫合部の痛みはありますが、発赤や腫脹はありません。この情報だけで感染と判断せず、痛みの程度や創部の変化を観察します。"},{"choice":2,"correct":true,"title":"乳房の変化は産褥日数相当である。","explanation":"産褥2日に乳房の張りや初乳の分泌がみられるのは、産褥経過に沿った変化です。分泌量だけでなく、乳房や乳頭の状態も合わせて確認します。"},{"choice":3,"correct":false,"title":"深部静脈血栓症の疑いがある。\ndeep vein thrombosis","explanation":"下肢の浮腫はなく、提示された痛みは会陰縫合部の痛みです。歩きにくさだけから深部静脈血栓症を疑う根拠にはなりません。"},{"choice":4,"correct":false,"title":"子宮復古が遅れている。","explanation":"子宮底が臍下に硬く触れ、悪露も少量であり、復古不全を示す所見ではありません。子宮の高さだけでなく硬さと悪露を合わせて評価します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"産褥2日、A さんは、体温 37.2 ℃、脈拍 76/分、血圧 112/80 mmHg、子宮底を\n臍下2横指に硬く触れ、悪露は赤褐色で少量。会陰縫合部の発赤なし、腫脹なし。\n下肢の浮腫は認めない。乳房緊満があり、左右の乳頭に2本ずつ乳管が開通してお\nり、初乳がにじむ程度に分泌している。A さんは、看護師に会陰縫合部が痛くて\n歩きにくいと話している。\nA さんのアセスメントで適切なのはどれか。","choices":["会陰縫合部の感染を起こしている。","乳房の変化は産褥日数相当である。","深部静脈血栓症の疑いがある。\ndeep vein thrombosis","子宮復古が遅れている。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(32 歳、初産婦)は妊娠 39 週4日に 3,200 g の男児を経腟分娩で出産した。\n分娩時に会陰切開縫合術を受けた。児の Apgar〈アプガー〉スコアは1分後9点、5\n分後 10 点であった。分娩時の出血量 200 mL、分娩所要時間 12 時間 30 分であった。\n分娩室から病室に帰室する前に尿意を自覚したためトイレまで歩行し、排尿があっ\nた。","preceding_context":[{"id":"111-PM-106","question":"帰室時に看護師が A さんに行う説明で適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":107,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[44],"case_pages":[44],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B107"},"exam":111,"year":2022,"session":"PM","number":107},"sources":[]},{"id":"111-PM-108","record":{"id":"111-PM-108","choice_explanations":[{"choice":1,"correct":false,"title":"養育支援訪問","explanation":"養育支援訪問は、養育上の支援が特に必要な家庭を対象とします。母児の経過が順調な本例で、すべての家庭に共通するサービスとしては選びません。"},{"choice":2,"correct":false,"title":"育成医療の給付","explanation":"育成医療は、身体に障害のある児童などの障害を除去・軽減する医療を対象とします。順調に経過する新生児への一般的な訪問サービスではありません。"},{"choice":3,"correct":false,"title":"養育医療の給付","explanation":"養育医療は、入院養育を必要とする未熟児を対象とした医療の給付です。本例のように順調に経過している児に該当するとはいえません。"},{"choice":4,"correct":true,"title":"乳児家庭全戸訪問事業(こんにちは赤ちゃん事業)","explanation":"乳児家庭全戸訪問事業は、乳児のいるすべての家庭への訪問を通じて、育児の情報提供や相談などを行います。母児の経過が順調でも対象になります。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"産褥4日、看護師は A さんに退院指導をすることにした。A さんの児の経過は\n順調である。\nA さんと児が受けられるサービスとして、看護師が退院指導時に説明するのは\nどれか。","choices":["養育支援訪問","育成医療の給付","養育医療の給付","乳児家庭全戸訪問事業(こんにちは赤ちゃん事業)"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A さん(32 歳、初産婦)は妊娠 39 週4日に 3,200 g の男児を経腟分娩で出産した。\n分娩時に会陰切開縫合術を受けた。児の Apgar〈アプガー〉スコアは1分後9点、5\n分後 10 点であった。分娩時の出血量 200 mL、分娩所要時間 12 時間 30 分であった。\n分娩室から病室に帰室する前に尿意を自覚したためトイレまで歩行し、排尿があっ\nた。","preceding_context":[{"id":"111-PM-106","question":"帰室時に看護師が A さんに行う説明で適切なのはどれか。"},{"id":"111-PM-107","question":"産褥2日、A さんは、体温 37.2 ℃、脈拍 76/分、血圧 112/80 mmHg、子宮底を\n臍下2横指に硬く触れ、悪露は赤褐色で少量。会陰縫合部の発赤なし、腫脹なし。\n下肢の浮腫は認めない。乳房緊満があり、左右の乳頭に2本ずつ乳管が開通してお\nり、初乳がにじむ程度に分泌している。A さんは、看護師に会陰縫合部が痛くて\n歩きにくいと話している。\nA さんのアセスメントで適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":108,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[45],"case_pages":[44],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B108"},"exam":111,"year":2022,"session":"PM","number":108},"sources":[{"title":"厚生労働省：乳児家庭全戸訪問事業実施要綱","url":"https://www.mhlw.go.jp/content/000630067.pdf"}]},{"id":"111-PM-109","record":{"id":"111-PM-109","choice_explanations":[{"choice":1,"correct":true,"title":"薬を飲みたくない理由を尋ねる。","explanation":"まず薬を飲みたくない理由や経験を聴きます。副作用への不安など、本人が困っている点を把握することで、納得して続けられる方法を一緒に考えられます。"},{"choice":2,"correct":false,"title":"薬を飲むことを約束してもらう。","explanation":"理由を聴かずに服薬を約束させても、本人の不安や困り事は解決しません。まず服薬への思いを確認し、治療の相談につなげます。"},{"choice":3,"correct":false,"title":"自己判断で薬をやめたことへの反省を促す。","explanation":"反省を求めると、服薬を中断したことや不安を話しにくくなります。相談してくれたことを受け止め、責めずに中断の背景を聴きます。"},{"choice":4,"correct":false,"title":"薬の管理は A さんの妻にしてもらうよう勧める。","explanation":"妻に管理を任せることを先に勧めると、本人の意思や理由が置き去りになります。本人の希望と困難を確認してから、必要な支援を考えます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"看護師の A さんへの対応で最も適切なのはどれか。","choices":["薬を飲みたくない理由を尋ねる。","薬を飲むことを約束してもらう。","自己判断で薬をやめたことへの反省を促す。","薬の管理は A さんの妻にしてもらうよう勧める。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":"A さん(35 歳、男性、会社員)は妻(32 歳、主婦)と子ども(2歳)と3人暮らし。5\n年前にうつ病と診断された。半年前に営業部門に異動し、帰宅後も深夜まで仕事をす\ndepression\nる日が続いていた。｢仕事のことが気になってしまい、焦りと不安ばかりが増して眠\nれない。会社に行くのが苦しい、入院させてもらえないか｣と訴えがあり、休養と薬\n物の調整を目的として精神科病院に入院となった。入院後、A さんから｢実は薬を飲\nむのが嫌で、途中から飲むのをやめていたんです。薬を飲みたくないのですが、どう\nしたらよいでしょうか｣と看護師に相談があった。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":109,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[46],"case_pages":[46],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B109"},"exam":111,"year":2022,"session":"PM","number":109},"sources":[]},{"id":"111-PM-110","record":{"id":"111-PM-110","choice_explanations":[{"choice":1,"correct":false,"title":"公認心理師","explanation":"公認心理師は心理面の相談や支援を担います。今回の中心は生活費や入院費の不安であり、社会制度の活用に詳しい職種との連携が適しています。"},{"choice":2,"correct":false,"title":"作業療法士","explanation":"作業療法士は活動を通して生活機能や社会参加を支援します。経済的な問題や給付の相談では、精神保健福祉士との連携を優先します。"},{"choice":3,"correct":false,"title":"理学療法士","explanation":"理学療法士は主に身体の基本動作や運動機能の回復を支援します。今回の入院費や生活費の相談の中心を担う職種とは異なります。"},{"choice":4,"correct":true,"title":"精神保健福祉士","explanation":"精神保健福祉士は、精神障害のある人の生活や社会制度の利用を支援します。経済的な不安を整理し、利用できる給付や相談先につなげます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"入院後1か月、面会に来た妻から、｢夫の会社から休業給付が出ないかもしれな\nいと言われました。子どもが小さく、生活費もかかるので、入院費用が払えるか心\n配です｣と看護師に相談があった。\n妻の相談に関して、看護師が連携する職種として最も適切なのはどれか。","choices":["公認心理師","作業療法士","理学療法士","精神保健福祉士"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A さん(35 歳、男性、会社員)は妻(32 歳、主婦)と子ども(2歳)と3人暮らし。5\n年前にうつ病と診断された。半年前に営業部門に異動し、帰宅後も深夜まで仕事をす\ndepression\nる日が続いていた。｢仕事のことが気になってしまい、焦りと不安ばかりが増して眠\nれない。会社に行くのが苦しい、入院させてもらえないか｣と訴えがあり、休養と薬\n物の調整を目的として精神科病院に入院となった。入院後、A さんから｢実は薬を飲\nむのが嫌で、途中から飲むのをやめていたんです。薬を飲みたくないのですが、どう\nしたらよいでしょうか｣と看護師に相談があった。","preceding_context":[{"id":"111-PM-109","question":"看護師の A さんへの対応で最も適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":110,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[46],"case_pages":[46],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B110"},"exam":111,"year":2022,"session":"PM","number":110},"sources":[]},{"id":"111-PM-111","record":{"id":"111-PM-111","choice_explanations":[{"choice":1,"correct":false,"title":"就労継続支援","explanation":"就労継続支援は、一般企業で働くことが難しい人などに働く機会や支援を提供します。現在の会社に在籍して休職中の本例では、復職支援が適しています。"},{"choice":2,"correct":true,"title":"リワーク支援","explanation":"リワーク支援は、精神疾患などで休職中の人が職場へ戻る準備をする支援です。生活リズムや作業への取り組みを整え、復職への不安に対応します。"},{"choice":3,"correct":false,"title":"障害者社会適応訓練事業","explanation":"社会適応訓練は社会生活への適応を支援するものですが、本例の課題は在籍する会社への復職です。その目的に直接対応するリワーク支援を選びます。"},{"choice":4,"correct":false,"title":"ジョブコーチによる支援","explanation":"ジョブコーチは職場での適応を支援します。復職後に役立つ場合はありますが、現在は働く準備への不安があり、まずリワーク支援が適しています。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんのうつ症状は改善し、多職種で退院に向けた話し合いを始めた。会社の\n休職制度を利用し休んでいる A さんは、｢薬が効いたので、今後も薬を飲み続ける\nことが大切だと思っている。異動したばかりなので仕事に早く戻らなければと思う\nが、休職してからずっと入院しているので、すぐに働ける自信がない｣と看護師に\n話した。\n退院に向けて A さんが利用する社会資源で適切なのはどれか。","choices":["就労継続支援","リワーク支援","障害者社会適応訓練事業","ジョブコーチによる支援"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(35 歳、男性、会社員)は妻(32 歳、主婦)と子ども(2歳)と3人暮らし。5\n年前にうつ病と診断された。半年前に営業部門に異動し、帰宅後も深夜まで仕事をす\ndepression\nる日が続いていた。｢仕事のことが気になってしまい、焦りと不安ばかりが増して眠\nれない。会社に行くのが苦しい、入院させてもらえないか｣と訴えがあり、休養と薬\n物の調整を目的として精神科病院に入院となった。入院後、A さんから｢実は薬を飲\nむのが嫌で、途中から飲むのをやめていたんです。薬を飲みたくないのですが、どう\nしたらよいでしょうか｣と看護師に相談があった。","preceding_context":[{"id":"111-PM-109","question":"看護師の A さんへの対応で最も適切なのはどれか。"},{"id":"111-PM-110","question":"入院後1か月、面会に来た妻から、｢夫の会社から休業給付が出ないかもしれな\nいと言われました。子どもが小さく、生活費もかかるので、入院費用が払えるか心\n配です｣と看護師に相談があった。\n妻の相談に関して、看護師が連携する職種として最も適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":111,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[47],"case_pages":[46],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B111"},"exam":111,"year":2022,"session":"PM","number":111},"sources":[{"title":"高齢・障害・求職者雇用支援機構：リワーク支援","url":"https://www.jeed.go.jp/location/chiiki/tokyo/reworkshien.html"}]},{"id":"111-PM-112","record":{"id":"111-PM-112","choice_explanations":[{"choice":1,"correct":false,"title":"宅配サービスを利用する。","explanation":"宅配は負担を減らす選択肢ですが、本人は歩いて買い物へ行くことを楽しみにしています。改善した状態と希望を踏まえ、安全に活動する方法を伝えます。"},{"choice":2,"correct":false,"title":"移動には車椅子を利用する。","explanation":"歩行時の息切れは消失しており、車椅子が必要という情報はありません。本人の歩行能力を生かし、無理のない活動を支援します。"},{"choice":3,"correct":false,"title":"荷物は両手に分散して持つ。","explanation":"両手に分けても荷物の総重量による負担は減りません。荷物を軽くするなどの工夫とともに、症状が出た際の休息を説明することが重要です。"},{"choice":4,"correct":true,"title":"途中で息切れを感じたら座って休む。","explanation":"息切れが出たら活動を中断して座り、呼吸が落ち着くまで休みます。休んでも改善しない場合や症状が強い場合は、相談・受診につなげます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"買い物について A さんに助言する内容で最も適切なのはどれか。","choices":["宅配サービスを利用する。","移動には車椅子を利用する。","荷物は両手に分散して持つ。","途中で息切れを感じたら座って休む。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A さん(65 歳、女性、要支援1)は1人暮らし。慢性心不全で定期的に外来受診し\nchronic heart failure\nていた。下肢の浮腫と息切れを自覚し、心不全の増悪があると診断されて入院となっ\nた。入院治療によって、両下肢に軽度の浮腫はあるが歩行による息切れは消失し、退\n院することになった。A さんは退院後の生活について｢近くのスーパーに歩いて買い\n物に行くのが楽しみですが、息切れが心配です。何に気をつけたらよいですか｣と病\n棟看護師に話した。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":112,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[48],"case_pages":[48],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B112"},"exam":111,"year":2022,"session":"PM","number":112},"sources":[]},{"id":"111-PM-113","record":{"id":"111-PM-113","choice_explanations":[{"choice":1,"correct":false,"title":"｢靴は大きめのサイズを選びましょう｣","explanation":"大き過ぎる靴は足に合わず、歩行時の不安定さにつながります。浮腫の状態に合う靴を選ぶことは必要ですが、単に大きめにするのは適切ではありません。"},{"choice":2,"correct":true,"title":"｢外出時は弾性ストッキングを履きましょう｣","explanation":"本例では退院後の安定した状態で、夕方の下肢浮腫への対応が問われています。弾性ストッキングは静脈還流を助けますが、心不全増悪時にも自己判断で使用してよいわけではなく、医療者の指示で用います。"},{"choice":3,"correct":false,"title":"｢下肢の中枢から末梢にマッサージしましょう｣","explanation":"中枢から末梢へのマッサージは、下肢から心臓への還流を助ける方向ではありません。心不全があるため、マッサージ自体の適否も個別に確認します。"},{"choice":4,"correct":false,"title":"｢就寝時には湯たんぽを身体から2、3cm 離して置きましょう｣","explanation":"身体に近い湯たんぽを就寝中に使うと、低温熱傷の危険があります。浮腫の対策にもならず、安全な保温方法を選ぶ必要があります。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"退院後、心不全の増悪を予防する目的で訪問看護を週に1回利用することになっ\nheart failure\nた。A さんは夕方に下肢の浮腫が悪化するのを気にしており、訪問看護師に助言\nを求めた。\n訪問看護師の A さんへの助言で適切なのはどれか。","choices":["｢靴は大きめのサイズを選びましょう｣","｢外出時は弾性ストッキングを履きましょう｣","｢下肢の中枢から末梢にマッサージしましょう｣","｢就寝時には湯たんぽを身体から2、3cm 離して置きましょう｣"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(65 歳、女性、要支援1)は1人暮らし。慢性心不全で定期的に外来受診し\nchronic heart failure\nていた。下肢の浮腫と息切れを自覚し、心不全の増悪があると診断されて入院となっ\nた。入院治療によって、両下肢に軽度の浮腫はあるが歩行による息切れは消失し、退\n院することになった。A さんは退院後の生活について｢近くのスーパーに歩いて買い\n物に行くのが楽しみですが、息切れが心配です。何に気をつけたらよいですか｣と病\n棟看護師に話した。","preceding_context":[{"id":"111-PM-112","question":"買い物について A さんに助言する内容で最も適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":113,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[48],"case_pages":[48],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B113"},"exam":111,"year":2022,"session":"PM","number":113},"sources":[{"title":"Nasuら：安定した慢性心不全患者の圧迫療法（2024年・出題後の研究）","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10830501/"}]},{"id":"111-PM-114","record":{"id":"111-PM-114","choice_explanations":[{"choice":1,"correct":true,"title":"高齢者サロン","explanation":"高齢者サロンは地域の高齢者が集まり、交流や活動を楽しむ場です。同年代とのつながりを広げたいという本人の希望に合っています。"},{"choice":2,"correct":false,"title":"療養通所介護","explanation":"療養通所介護は、医療的な管理を必要とする人などへの通所サービスです。現在の主な希望は地域での交流であり、このサービスを優先する状況ではありません。"},{"choice":3,"correct":false,"title":"通所リハビリテーション","explanation":"通所リハビリテーションは心身機能や生活動作の維持・回復を目的とします。交流の機会にもなりますが、本例の希望には高齢者サロンがより直接対応します。"},{"choice":4,"correct":false,"title":"共同生活援助〈グループホーム〉","explanation":"共同生活援助は、障害のある人が共同生活の場で支援を受けるサービスです。同年代との交流を目的とした集まりとは異なります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"退院後3週、A さんの浮腫は改善し心不全の増悪もなかった。A さんは｢同年代\nheart failure\nの人との交流を広げたいと思っています。利用できるサービスはありますか｣と訪\n問看護師に質問した。\n訪問看護師が地域包括支援センターに相談して A さんに提案する社会資源はど\nれか。","choices":["高齢者サロン","療養通所介護","通所リハビリテーション","共同生活援助〈グループホーム〉"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":"A さん(65 歳、女性、要支援1)は1人暮らし。慢性心不全で定期的に外来受診し\nchronic heart failure\nていた。下肢の浮腫と息切れを自覚し、心不全の増悪があると診断されて入院となっ\nた。入院治療によって、両下肢に軽度の浮腫はあるが歩行による息切れは消失し、退\n院することになった。A さんは退院後の生活について｢近くのスーパーに歩いて買い\n物に行くのが楽しみですが、息切れが心配です。何に気をつけたらよいですか｣と病\n棟看護師に話した。","preceding_context":[{"id":"111-PM-112","question":"買い物について A さんに助言する内容で最も適切なのはどれか。"},{"id":"111-PM-113","question":"退院後、心不全の増悪を予防する目的で訪問看護を週に1回利用することになっ\nheart failure\nた。A さんは夕方に下肢の浮腫が悪化するのを気にしており、訪問看護師に助言\nを求めた。\n訪問看護師の A さんへの助言で適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":114,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[49],"case_pages":[48],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B114"},"exam":111,"year":2022,"session":"PM","number":114},"sources":[]},{"id":"111-PM-115","record":{"id":"111-PM-115","choice_explanations":[{"choice":1,"correct":false,"title":"被災状況の報告","explanation":"被災状況の報告は必要ですが、まず患者の安全や医療機器の状態を把握しなければ、具体的な状況を伝えられません。現場の確認を優先します。"},{"choice":2,"correct":false,"title":"入院患者の避難誘導","explanation":"避難が必要かは建物や火災などの状況によります。揺れが収まった直後は、まず患者と機器の安全を確認し、必要性に応じて避難します。"},{"choice":3,"correct":false,"title":"傷病者の受け入れ準備","explanation":"傷病者の受け入れも重要ですが、まず入院患者への治療が維持されているか確認します。既存患者の安全確認より先に受け入れ準備を行いません。"},{"choice":4,"correct":true,"title":"入院患者の状態の把握","explanation":"転倒や治療の中断などが起きていないか、入院患者の状態を確認します。自身の安全を確保した後は、患者の生命・身体の安全の把握が優先です。"},{"choice":5,"correct":true,"title":"使用中の医療機器の作動状況の確認","explanation":"人工呼吸器や輸液ポンプなどが正常に作動しているか確認します。停電や接続の外れなどにより、生命維持に必要な治療が中断する危険があるためです。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"この時点の看護師の対応として適切なのはどれか。2つ選べ。","choices":["被災状況の報告","入院患者の避難誘導","傷病者の受け入れ準備","入院患者の状態の把握","使用中の医療機器の作動状況の確認"],"correct_answers":[4,5],"accepted_answer_sets":[[4,5]],"case_text":"午前9時頃、震度5強の地震が発生した。二次救急医療機関の救命救急病棟に勤務\nする看護師は、自身の身の安全を確保し、揺れが収まると病院の災害発生時のマニュ\nアルに沿って行動を開始した。病棟には人工呼吸器を使用中の患者が1人、輸液ポン\nプを使用中の患者が3人、酸素療法中の患者3人が入院している。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":115,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[50],"case_pages":[50],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B115"},"exam":111,"year":2022,"session":"PM","number":115},"sources":[]},{"id":"111-PM-116","record":{"id":"111-PM-116","choice_explanations":[{"choice":1,"correct":false,"title":"A 君の既往歴の聴取","explanation":"A君の既往歴の確認は必要ですが、バイタルサインは安定しています。気道熱傷が疑われるBさんの呼吸に関わる対応を優先します。"},{"choice":2,"correct":false,"title":"A 君への鎮痛薬の準備","explanation":"A君の疼痛への対応は必要ですが、気道閉塞の危険への備えが先です。緊急度を比較して優先順位を決めます。"},{"choice":3,"correct":true,"title":"B さんの気道確保の準備","explanation":"火災の煙にさらされ、鼻毛が焦げているため気道熱傷が疑われます。現在のバイタルサインが安定していても、浮腫による気道閉塞に備える必要があります。"},{"choice":4,"correct":false,"title":"B さんの熱傷部位の冷却\nburn","explanation":"熱傷部位の処置は必要ですが、生命に直結する気道の評価と確保への準備が優先です。皮膚の熱傷面積だけで緊急度を判断しません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"発災から3時間後、地震後に発生した火災現場付近から救出された A 君(6歳)\nと母親の B さん(32 歳)の2人が搬送されてきた。A 君は避難時に転倒し、左肘関\n節付近の腫脹と疼痛を訴えていた。バイタルサインに異常はない。B さんは避難す\nる際に A 君が煙に巻き込まれそうになるところをかばい、髪の一部と鼻毛の一部\nが焦げていた。右頰部に2cm ×2cm、右上肢に5cm × 10 cm の紅斑と水疱を認\nめる熱傷を負っていた。バイタルサインに異常はないが、熱傷部位の疼痛を訴えて\nburn burn\nいた。\nトリアージの結果、看護師の初期対応として優先されるのはどれか。","choices":["A 君の既往歴の聴取","A 君への鎮痛薬の準備","B さんの気道確保の準備","B さんの熱傷部位の冷却\nburn"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"午前9時頃、震度5強の地震が発生した。二次救急医療機関の救命救急病棟に勤務\nする看護師は、自身の身の安全を確保し、揺れが収まると病院の災害発生時のマニュ\nアルに沿って行動を開始した。病棟には人工呼吸器を使用中の患者が1人、輸液ポン\nプを使用中の患者が3人、酸素療法中の患者3人が入院している。","preceding_context":[{"id":"111-PM-115","question":"この時点の看護師の対応として適切なのはどれか。2つ選べ。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":116,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[50],"case_pages":[50],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B116"},"exam":111,"year":2022,"session":"PM","number":116},"sources":[]},{"id":"111-PM-117","record":{"id":"111-PM-117","choice_explanations":[{"choice":1,"correct":false,"title":"｢お母さんがしっかりしましょう｣","explanation":"母親も被災しており、「しっかり」と求めると負担や自責感が増します。子どもの反応を説明し、母親自身の不安も受け止めます。"},{"choice":2,"correct":false,"title":"｢A 君が1人になる時間をつくりましょう｣","explanation":"災害後の不安から母親のそばを離れたがらない状態です。無理に一人にするより、安心できる関わりを支援します。"},{"choice":3,"correct":false,"title":"｢A 君に水分を控えるよう声をかけましょう｣","explanation":"夜尿は災害後のストレスに伴う退行として現れることがあります。水分制限で対応するのではなく、安心感を回復できるように支えます。"},{"choice":4,"correct":true,"title":"｢A 君が甘えてきたら抱きしめてあげましょう｣","explanation":"災害後には甘えや夜尿などの退行がみられることがあります。抱きしめるなど、本人が安心できる関わりを通して心の回復を支えます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A 君と B さんはともに入院して治療が始まった。発災から 10 日後、A 君、B さ\nんの治療経過は良好で合併症もなくバイタルサインは安定していた。B さんから看\n護師に｢A は好きなお菓子を食べず、私のそばからずっと離れず甘えてきます。昨\n夜はおねしょをしていたようで、びっくりしました。どうしたらよいのかわかりま\nせん｣と相談があった。\n看護師の対応として適切なのはどれか。","choices":["｢お母さんがしっかりしましょう｣","｢A 君が1人になる時間をつくりましょう｣","｢A 君に水分を控えるよう声をかけましょう｣","｢A 君が甘えてきたら抱きしめてあげましょう｣"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"午前9時頃、震度5強の地震が発生した。二次救急医療機関の救命救急病棟に勤務\nする看護師は、自身の身の安全を確保し、揺れが収まると病院の災害発生時のマニュ\nアルに沿って行動を開始した。病棟には人工呼吸器を使用中の患者が1人、輸液ポン\nプを使用中の患者が3人、酸素療法中の患者3人が入院している。","preceding_context":[{"id":"111-PM-115","question":"この時点の看護師の対応として適切なのはどれか。2つ選べ。"},{"id":"111-PM-116","question":"発災から3時間後、地震後に発生した火災現場付近から救出された A 君(6歳)\nと母親の B さん(32 歳)の2人が搬送されてきた。A 君は避難時に転倒し、左肘関\n節付近の腫脹と疼痛を訴えていた。バイタルサインに異常はない。B さんは避難す\nる際に A 君が煙に巻き込まれそうになるところをかばい、髪の一部と鼻毛の一部\nが焦げていた。右頰部に2cm ×2cm、右上肢に5cm × 10 cm の紅斑と水疱を認\nめる熱傷を負っていた。バイタルサインに異常はないが、熱傷部位の疼痛を訴えて\nburn burn\nいた。\nトリアージの結果、看護師の初期対応として優先されるのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":117,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[51],"case_pages":[50],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B117"},"exam":111,"year":2022,"session":"PM","number":117},"sources":[]},{"id":"111-PM-118","record":{"id":"111-PM-118","choice_explanations":[{"choice":1,"correct":false,"title":"肥満である。","explanation":"体重が75パーセンタイルというだけで肥満とは判断しません。身長との釣り合いや体格の指標を合わせて評価する必要があります。"},{"choice":2,"correct":false,"title":"言語発達に遅れがある。","explanation":"3歳で自分の名前と年齢を答えられており、示された情報から言語発達の遅れとは判断しません。会話や理解なども合わせて確認します。"},{"choice":3,"correct":false,"title":"排泄の自立に遅れがある。","explanation":"排泄の自立には個人差があり、3歳になった時点でオムツを使っているだけで遅れとは断定しません。発達や生活状況を踏まえて支援します。"},{"choice":4,"correct":true,"title":"運動発達は年齢相応である。","explanation":"3歳で一人で階段を昇れることは年齢に沿った運動発達です。スキップはさらに後に獲得する動作で、この時点でできなくても異常とはしません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A 君の発育と発達のアセスメントで正しいのはどれか。","choices":["肥満である。","言語発達に遅れがある。","排泄の自立に遅れがある。","運動発達は年齢相応である。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A 君(男児)は3歳の誕生日を迎えた。生後8か月のときに鶏卵の摂取でアナフィ\nラキシーを起こしたため、かかりつけ医を受診した。それ以降、現在まで A 君は鶏\n卵の摂取を禁止するよう説明されている。鶏卵以外の食物は摂取して問題がない。今\n回、A 君は保育所の入所にあたり、かかりつけ医からアレルギー外来のある B 病院\nを紹介され受診した。3歳児健康診査が今後予定されている。A 君は身長 95 cm(50\nパーセンタイル)、体重 15 kg(75 パーセンタイル)、自分の名前と年齢を答えること\nができる。階段を1人で昇ることができるが、スキップはできない。排泄はオムツに\nしている。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":118,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[52],"case_pages":[52],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B118"},"exam":111,"year":2022,"session":"PM","number":118},"sources":[]},{"id":"111-PM-119","record":{"id":"111-PM-119","choice_explanations":[{"choice":1,"correct":true,"title":"｢成長とともに卵を食べられるようになる子どもは多いです｣","explanation":"鶏卵アレルギーは成長とともに耐性を得て、食べられるようになる子どもが多くいます。ただし自己判断で再開せず、負荷試験などを踏まえ医師の指示に従います。"},{"choice":2,"correct":false,"title":"｢保育所でアレルギー疾患用生活管理指導表を作成します｣","explanation":"生活管理指導表は医師が医学的な管理内容を記載するものです。保育所が独自に診断や除去の内容を決めて作成するものではありません。"},{"choice":3,"correct":false,"title":"｢保育所でのアドレナリン自己注射薬は保護者が投与します｣","explanation":"緊急時に保護者の到着を待つと対応が遅れます。事前に保護者・医師・保育所で情報を共有し、職員が対応できる体制を整えます。"},{"choice":4,"correct":false,"title":"｢給食の際は別室に移動して食べさせましょう｣","explanation":"別室での食事を一律に行う必要はありません。誤食を防ぐ配置や配膳などを工夫し、安全を確保しながら他児と生活できるよう支援します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"B 病院の医師から母親に、アドレナリン自己注射薬を処方のうえ鶏卵の摂取制限\nを継続することと、近日中に鶏卵を用いた食物経口負荷試験を計画することが説明\nされた。母親から看護師に｢A の保育所での生活や将来のことが心配です｣と訴え\nがあった。\n看護師の母親への説明で適切なのはどれか。","choices":["｢成長とともに卵を食べられるようになる子どもは多いです｣","｢保育所でアレルギー疾患用生活管理指導表を作成します｣","｢保育所でのアドレナリン自己注射薬は保護者が投与します｣","｢給食の際は別室に移動して食べさせましょう｣"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":"A 君(男児)は3歳の誕生日を迎えた。生後8か月のときに鶏卵の摂取でアナフィ\nラキシーを起こしたため、かかりつけ医を受診した。それ以降、現在まで A 君は鶏\n卵の摂取を禁止するよう説明されている。鶏卵以外の食物は摂取して問題がない。今\n回、A 君は保育所の入所にあたり、かかりつけ医からアレルギー外来のある B 病院\nを紹介され受診した。3歳児健康診査が今後予定されている。A 君は身長 95 cm(50\nパーセンタイル)、体重 15 kg(75 パーセンタイル)、自分の名前と年齢を答えること\nができる。階段を1人で昇ることができるが、スキップはできない。排泄はオムツに\nしている。","preceding_context":[{"id":"111-PM-118","question":"A 君の発育と発達のアセスメントで正しいのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":119,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[53],"case_pages":[52],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B119"},"exam":111,"year":2022,"session":"PM","number":119},"sources":[{"title":"厚生労働省：保育所アレルギー対応ガイドライン2019年版（こども家庭庁保存）","url":"https://www.cfa.go.jp/assets/contents/node/basic_page/field_ref_resources/e4b817c9-5282-4ccc-b0d5-ce15d7b5018c/cc94d067/20240205_policies_hoiku_86.pdf"}]},{"id":"111-PM-120","record":{"id":"111-PM-120","choice_explanations":[{"choice":1,"correct":false,"title":"虐待にあたることを伝える。","explanation":"現時点で断定して責めると、事情の把握や子どもの安全確保が難しくなることがあります。必要な保護と連携を進めながら、落ち着いて話を聴きます。"},{"choice":2,"correct":false,"title":"乳児期に起こりやすい事故について説明する。","explanation":"複数の時期の紫斑や熱傷痕などがあり、通常の事故予防の説明だけでは不十分です。虐待の可能性を踏まえた安全確保と情報収集が必要です。"},{"choice":3,"correct":false,"title":"児童相談所に通告することへの母親の同意を得る。","explanation":"虐待が疑われる場合の通告に、保護者の同意は必要ありません。同意を得ることを条件にして対応を遅らせないようにします。"},{"choice":4,"correct":true,"title":"プライバシーを保護できる個室で話を聞くと伝える。","explanation":"周囲に聞かれない場所で話せることを伝え、落ち着いて事情を聴きます。母子分離による安全確保と、プライバシーへの配慮を両立させます。"},{"choice":5,"correct":false,"title":"母親の代わりに父親が A ちゃんに面会できると伝える。","explanation":"父親もAちゃんにいら立つと母親が話しており、安全な面会相手とはまだ判断できません。父親なら面会できると約束せず、関係機関と安全性を確認します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"このときの看護師の対応で適切なのはどれか。","choices":["虐待にあたることを伝える。","乳児期に起こりやすい事故について説明する。","児童相談所に通告することへの母親の同意を得る。","プライバシーを保護できる個室で話を聞くと伝える。","母親の代わりに父親が A ちゃんに面会できると伝える。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A ちゃん(6か月、女児)は両親と3人暮らし。母親と小児科外来に来院した。母\n親は｢A は昨日高さ 30 cm のソファから転落して泣いていました。今朝になっても痛\nいのか右手を動かさないので受診しました｣と看護師に話した。看護師が身体計測の\nため A ちゃんの服を脱がせると、顔面、頭部と体幹に最近できた紫斑と、生じてか\nら時間が経った紫斑が複数あった。さらに、両足に多数の円形の熱傷痕があった。A\nちゃんは身長 66.5 cm(50 パーセンタイル)、体重 6.0 kg(3パーセンタイル未満)で\nあった。母親は看護師に｢A は毎晩夜泣きをするし、夫も A にはイライラさせられて\nいます｣と話した。看護師は虐待の可能性があると考えて対応することとし、母子分\n離を図ることとなった。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第111回看護師国家試験","session":"午後","question_number":120,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05c_01.pdf","pages":[54],"case_pages":[54],"sha256":"fd5074d12571f2dd6b99f658590c62282d64cf36f286ab9223fe6ab7b29d0090"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp220421-05seitou.pdf","page":2,"row_id":"B120"},"exam":111,"year":2022,"session":"PM","number":120},"sources":[{"title":"厚生労働省：医療・介護個人情報ガイダンス・法令に基づく通告","url":"https://www.mhlw.go.jp/web/t_doc?dataId=00tc2625&dataType=1"}]},{"id":"112-AM-001","record":{"id":"112-AM-001","choice_explanations":[{"choice":1,"correct":false,"title":"19.4 歳","explanation":"2020年の妻の平均初婚年齢は29.4歳です。19.4歳は当該年の平均とは大きく異なります。婚姻できる年齢と、実際の平均初婚年齢は区別します。"},{"choice":2,"correct":false,"title":"24.4 歳","explanation":"24.4歳は当該年の妻の平均初婚年齢ではありません。統計問題では、過去の傾向だけでなく指定された年の値を確認します。"},{"choice":3,"correct":true,"title":"29.4 歳","explanation":"2020年の人口動態統計では、妻の平均初婚年齢は29.4歳です。すべての婚姻の平均年齢ではなく、初めて結婚した女性の平均である点を押さえます。"},{"choice":4,"correct":false,"title":"34.4 歳","explanation":"34.4歳は当該年の妻の平均初婚年齢ではありません。平均初婚年齢と出産時の母の年齢など、別の統計を混同しないようにします。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"令和2年(2020 年)の人口動態統計における妻の平均初婚年齢はどれか。","choices":["19.4 歳","24.4 歳","29.4 歳","34.4 歳"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":1,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[7],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A001"},"exam":112,"year":2023,"session":"AM","number":1},"sources":[{"title":"厚生労働省：人口動態統計・平均初婚年齢の年次推移","url":"https://www.mhlw.go.jp/content/12601000/000954795.pdf"}]},{"id":"112-AM-002","record":{"id":"112-AM-002","choice_explanations":[{"choice":1,"correct":false,"title":"頭 痛","explanation":"頭痛も自覚症状として挙げられますが、2019年の女性で最多ではありません。この調査では肩こりが最も多い症状です。"},{"choice":2,"correct":true,"title":"肩こり","explanation":"2019年の国民生活基礎調査では、女性の自覚症状で最も多いのは肩こりです。自覚症状の調査であり、医師による診断名の順位ではありません。"},{"choice":3,"correct":false,"title":"体がだるい","explanation":"体がだるいという訴えもありますが、女性の最多の自覚症状ではありません。性別と調査年度を確かめて順位を判断します。"},{"choice":4,"correct":false,"title":"目のかすみ","explanation":"目のかすみも調査対象となる症状ですが、女性で最も多い症状は肩こりです。特定の年齢層ではなく女性全体の結果が問われています。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"令和元年(2019 年)の国民生活基礎調査における女性の有訴者の自覚症状で最も\n多いのはどれか。","choices":["頭 痛","肩こり","体がだるい","目のかすみ"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":2,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[7],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A002"},"exam":112,"year":2023,"session":"AM","number":2},"sources":[{"title":"厚生労働省：2019年国民生活基礎調査・世帯員の健康状況","url":"https://www.mhlw.go.jp/toukei/saikin/hw/k-tyosa/k-tyosa19/dl/04.pdf"}]},{"id":"112-AM-003","record":{"id":"112-AM-003","choice_explanations":[{"choice":1,"correct":false,"title":"喫煙開始年齢","explanation":"喫煙開始年齢そのものは計算式に入りません。喫煙年数が分かっている場合、さらに必要なのは1日の平均喫煙本数です。"},{"choice":2,"correct":false,"title":"受動喫煙年数","explanation":"受動喫煙も健康に影響しますが、ブリンクマン指数の計算には用いません。本人が吸った本数と年数で累積的な喫煙量を表します。"},{"choice":3,"correct":false,"title":"家庭内の喫煙者数","explanation":"家庭内の喫煙者数は受動喫煙の環境を考える情報ですが、この指数の算出項目ではありません。"},{"choice":4,"correct":true,"title":"1日の平均喫煙本数","explanation":"ブリンクマン指数は、1日の平均喫煙本数に喫煙年数を掛けて求めます。本数と期間の両方から喫煙歴の量的な目安を得る指標です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"喫煙指数(Brinkman〈ブリンクマン〉指数)を算出するために、喫煙年数のほかに\n必要なのはどれか。","choices":["喫煙開始年齢","受動喫煙年数","家庭内の喫煙者数","1日の平均喫煙本数"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":3,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[7],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A003"},"exam":112,"year":2023,"session":"AM","number":3},"sources":[]},{"id":"112-AM-004","record":{"id":"112-AM-004","choice_explanations":[{"choice":1,"correct":false,"title":"30 時間","explanation":"週30時間は、労働基準法の原則的な法定労働時間の上限ではありません。個別の短時間勤務の契約とは区別します。"},{"choice":2,"correct":false,"title":"35 時間","explanation":"週35時間を原則の上限とする規定ではありません。法律が定める基本の上限は、休憩を除き週40時間です。"},{"choice":3,"correct":true,"title":"40 時間","explanation":"原則として、休憩時間を除き1週間40時間を超えて労働させてはならないと定められています。法定の例外や時間外労働の手続があることとは区別して理解します。"},{"choice":4,"correct":false,"title":"45 時間","explanation":"45時間は週の原則的な法定労働時間ではありません。時間外労働に関する別の上限の数字と混同しないようにします。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"休憩時間を除いた1週間の労働時間で、超えてはならないと労働基準法で定めら\nれているのはどれか。","choices":["30 時間","35 時間","40 時間","45 時間"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":4,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[7],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A004"},"exam":112,"year":2023,"session":"AM","number":4},"sources":[{"title":"厚生労働省：労働時間・休日","url":"https://www.mhlw.go.jp/stf/seisakunitsuite/bunya/koyou_roudou/roudoukijun/roudouzikan/index.html"}]},{"id":"112-AM-005","record":{"id":"112-AM-005","choice_explanations":[{"choice":1,"correct":false,"title":"4","explanation":"要支援と要介護を合わせた区分は4ではありません。要支援1・2と、要介護1～5に分かれます。"},{"choice":2,"correct":false,"title":"5","explanation":"5は要介護だけの区分数です。問題は要支援も含めた状態区分の数を尋ねています。"},{"choice":3,"correct":false,"title":"6","explanation":"要支援を一つの区分として数えると誤りになります。要支援には1と2の二つの区分があります。"},{"choice":4,"correct":true,"title":"7","explanation":"要支援が2区分、要介護が5区分で、合計7区分です。自立・非該当は、要支援・要介護認定の区分に含めません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"介護保険法における要支援および要介護認定の状態区分の数はどれか。","choices":["4","5","6","7"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":5,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[8],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A005"},"exam":112,"year":2023,"session":"AM","number":5},"sources":[]},{"id":"112-AM-006","record":{"id":"112-AM-006","choice_explanations":[{"choice":1,"correct":false,"title":"疾病の治癒","explanation":"病気の治癒を目指す治療と併行して緩和ケアを行うことはありますが、緩和ケアそのものの中心目標は苦痛を和らげて生活の質を高めることです。"},{"choice":2,"correct":false,"title":"余命の延長","explanation":"余命の延長だけを目標にするものではありません。痛みや不安、生活上の困り事などに対応し、その人らしく過ごせることを支援します。"},{"choice":3,"correct":true,"title":"QOL の向上","explanation":"身体的・心理的・社会的な苦痛などを和らげ、患者と家族の生活の質〈QOL〉を高めることが目標です。終末期だけに限定されるケアではありません。"},{"choice":4,"correct":false,"title":"在院日数の短縮","explanation":"在院日数の短縮は医療体制上の指標ですが、緩和ケアの中心目標ではありません。療養場所にかかわらず、本人と家族の苦痛に対応します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"緩和ケアの目標で正しいのはどれか。","choices":["疾病の治癒","余命の延長","QOL の向上","在院日数の短縮"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":6,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[8],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A006"},"exam":112,"year":2023,"session":"AM","number":6},"sources":[]},{"id":"112-AM-007","record":{"id":"112-AM-007","choice_explanations":[{"choice":1,"correct":false,"title":"階段を昇る。","explanation":"階段を昇る動作は、手すりや介助を使う段階も含め、3歳より前から獲得していきます。より高度なバランスを必要とする片足跳びとは時期が異なります。"},{"choice":2,"correct":false,"title":"ひとりで立つ。","explanation":"ひとりで立つことは、歩行に向かう乳児期後半から幼児期初めの発達です。通常、3歳以降になって初めて獲得する動作ではありません。"},{"choice":3,"correct":false,"title":"ボールを蹴る。","explanation":"ボールを蹴る動作は3歳より前からみられます。片足で繰り返し跳ぶ動作に比べて、早く獲得する運動です。"},{"choice":4,"correct":true,"title":"けんけん〈片足跳び〉をする。","explanation":"片足跳びは、片脚で体を支えながら跳ぶバランスと協調性が必要です。ひとりで立つ、ボールを蹴るなどの動作より後に獲得します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"運動機能の発達で3歳以降に獲得するのはどれか。","choices":["階段を昇る。","ひとりで立つ。","ボールを蹴る。","けんけん〈片足跳び〉をする。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":7,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[8],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A007"},"exam":112,"year":2023,"session":"AM","number":7},"sources":[]},{"id":"112-AM-008","record":{"id":"112-AM-008","choice_explanations":[{"choice":1,"correct":true,"title":"経済的に自立する。","explanation":"成人期には、仕事などを通して経済的に自立し、社会的な役割を担うことが課題になります。成人として生活を成り立たせる課題と結び付けます。"},{"choice":2,"correct":false,"title":"身体的衰退を自覚する。","explanation":"身体的衰退への適応は、主にその後の加齢に伴う時期の課題です。本問の成人期を代表する課題には、経済的な自立が当たります。"},{"choice":3,"correct":false,"title":"正、不正の区別がつく。","explanation":"正しいことと不正なことを区別し、良心を育てることは、より早い発達段階での課題です。成人期の経済的・社会的な自立とは異なります。"},{"choice":4,"correct":false,"title":"読み、書き、計算ができる。","explanation":"読み、書き、計算という基礎的技能の獲得は、主に学童期の課題です。成人期になって初めて達成を目指す課題ではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"ハヴィガースト, R. J. が提唱する成人期の発達課題はどれか。\nHavighust, R. J.","choices":["経済的に自立する。","身体的衰退を自覚する。","正、不正の区別がつく。","読み、書き、計算ができる。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":8,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[8],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A008"},"exam":112,"year":2023,"session":"AM","number":8},"sources":[]},{"id":"112-AM-009","record":{"id":"112-AM-009","choice_explanations":[{"choice":1,"correct":false,"title":"事業所","explanation":"事業所で働く看護師もいますが、2020年の統計で医療機関に次いで多い就業場所ではありません。"},{"choice":2,"correct":false,"title":"市町村","explanation":"市町村は保健師の就業先として重要ですが、本問は看護師の就業場所を尋ねています。職種の違いに注意します。"},{"choice":3,"correct":false,"title":"保健所","explanation":"保健所でも看護職は働きますが、看護師の人数で医療機関の次に多い場所ではありません。"},{"choice":4,"correct":true,"title":"訪問看護ステーション","explanation":"2020年の衛生行政報告例では、選択肢の中で訪問看護ステーションが最も多い就業場所です。看護師が在宅療養を支える場として位置づけられます。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"令和2年(2020 年)の衛生行政報告例における看護師の就業場所で、医療機関(病\n院、診療所)の次に多いのはどれか。","choices":["事業所","市町村","保健所","訪問看護ステーション"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":9,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[9],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A009"},"exam":112,"year":2023,"session":"AM","number":9},"sources":[{"title":"厚生労働省：令和2年衛生行政報告例 表2（選択肢内の比較）","url":"https://www.mhlw.go.jp/toukei/saikin/hw/eisei/20/dl/gaikyo.pdf"}]},{"id":"112-AM-010","record":{"id":"112-AM-010","choice_explanations":[{"choice":1,"correct":false,"title":"視 覚","explanation":"視覚は、眼の網膜で光を受け取る特殊感覚です。皮膚や筋肉などから得る体性感覚とは区別します。"},{"choice":2,"correct":true,"title":"触 覚","explanation":"触覚は皮膚への接触などを感じる体性感覚です。体性感覚には、痛覚や温度覚、身体の位置を感じる深部感覚なども含まれます。"},{"choice":3,"correct":false,"title":"聴 覚","explanation":"聴覚は内耳で音の振動を受け取る特殊感覚です。体表や運動器からの感覚である体性感覚とは異なります。"},{"choice":4,"correct":false,"title":"平衡覚","explanation":"平衡覚は主に内耳の前庭器官が担う特殊感覚です。姿勢の維持には体性感覚も関わりますが、平衡覚自体の分類とは分けて考えます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"体性感覚はどれか。","choices":["視 覚","触 覚","聴 覚","平衡覚"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":10,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[9],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A010"},"exam":112,"year":2023,"session":"AM","number":10},"sources":[]},{"id":"112-AM-011","record":{"id":"112-AM-011","choice_explanations":[{"choice":1,"correct":false,"title":"単 球","explanation":"単球は異物の処理などに関わり、組織でマクロファージになります。健康な成人の末梢血で最も割合が高い白血球ではありません。"},{"choice":2,"correct":false,"title":"好酸球","explanation":"好酸球はアレルギー反応や寄生虫への防御などに関わります。通常、好中球より少ない割合です。"},{"choice":3,"correct":true,"title":"好中球","explanation":"健康な成人の末梢血では、好中球が白血球の中で最も多くを占めます。細菌などを取り込み、初期の感染防御に働きます。"},{"choice":4,"correct":false,"title":"リンパ球","explanation":"リンパ球は抗体産生や細胞性免疫などに関わります。成人の末梢血では、通常は好中球の方が多い割合を占めます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"健康な成人の白血球の中に占める割合が高いのはどれか。","choices":["単 球","好酸球","好中球","リンパ球"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":11,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[9],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A011"},"exam":112,"year":2023,"session":"AM","number":11},"sources":[]},{"id":"112-AM-012","record":{"id":"112-AM-012","choice_explanations":[{"choice":1,"correct":false,"title":"橋","explanation":"橋は呼吸調節などに関わる脳幹の一部です。体温調節の中心として選ぶ部位は視床下部です。"},{"choice":2,"correct":false,"title":"小 脳","explanation":"小脳は運動の協調や姿勢・平衡の調整などに関わります。体温変化に応じた自律的な調節を指令する中心ではありません。"},{"choice":3,"correct":true,"title":"視床下部","explanation":"視床下部は体温の情報を受け、発汗や皮膚血流、震えなどの反応を調節します。体内環境を一定に保つ働きと結び付けて覚えます。"},{"choice":4,"correct":false,"title":"大脳皮質","explanation":"大脳皮質は暑さや寒さを意識し、衣服を調整するなどの行動に関わります。自律的な体温調節の中枢は視床下部です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"体温変化をとらえ、体温調節の指令を出すのはどれか。","choices":["橋","小 脳","視床下部","大脳皮質"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":12,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[9],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A012"},"exam":112,"year":2023,"session":"AM","number":12},"sources":[]},{"id":"112-AM-013","record":{"id":"112-AM-013","choice_explanations":[{"choice":1,"correct":false,"title":"肝囊胞\nliver cyst","explanation":"肝囊胞は肝臓内に液体がたまる袋状の病変です。腸管内への出血による下血を代表的な症状とする疾患ではありません。"},{"choice":2,"correct":true,"title":"大腸癌\ncolon cancer","explanation":"大腸の腫瘍から出血すると、血液が便に混じるなどの症状がみられます。下血では出血源や便の性状を確認することが重要です。"},{"choice":3,"correct":false,"title":"子宮体癌\nuterine corpus cancer","explanation":"子宮体癌では性器出血がみられますが、消化管から血液が排出される下血とは異なります。出血している部位を区別します。"},{"choice":4,"correct":false,"title":"腎細胞癌\nrenal cell carcinoma","explanation":"腎細胞癌では血尿がみられることがあります。尿路からの出血と、消化管からの下血は区別します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"下血がみられる疾患はどれか。","choices":["肝囊胞\nliver cyst","大腸癌\ncolon cancer","子宮体癌\nuterine corpus cancer","腎細胞癌\nrenal cell carcinoma"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":13,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[10],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A013"},"exam":112,"year":2023,"session":"AM","number":13},"sources":[]},{"id":"112-AM-014","record":{"id":"112-AM-014","choice_explanations":[{"choice":1,"correct":false,"title":"足壊疽\nfoot gangrene","explanation":"足壊疽は血流障害や神経障害、感染などが関わり、長期の糖尿病管理上の問題です。代謝の急激な破綻で起こる急性合併症とは区別します。"},{"choice":2,"correct":false,"title":"脳血管疾患\ncerebrovascular disease","explanation":"糖尿病は脳血管疾患のリスクを高めますが、ここで問う糖尿病の急性代謝性合併症には当たりません。"},{"choice":3,"correct":false,"title":"糖尿病網膜症\ndiabetic retinopathy","explanation":"糖尿病網膜症は持続する高血糖によって網膜の細い血管が障害される慢性合併症です。急性合併症ではありません。"},{"choice":4,"correct":true,"title":"ケトアシドーシス昏睡","explanation":"インスリン作用の不足によりケトン体が増加し、アシドーシスや脱水が進むと意識障害を来します。速やかな対応が必要な糖尿病の急性合併症です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"糖尿病の急性合併症はどれか。\ndiabetes mellitus","choices":["足壊疽\nfoot gangrene","脳血管疾患\ncerebrovascular disease","糖尿病網膜症\ndiabetic retinopathy","ケトアシドーシス昏睡"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":14,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[10],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A014"},"exam":112,"year":2023,"session":"AM","number":14},"sources":[]},{"id":"112-AM-015","record":{"id":"112-AM-015","choice_explanations":[{"choice":1,"correct":false,"title":"80 cm 以上","explanation":"日本の診断基準で男性に用いる腹囲の基準は85cm以上です。80cm以上では、提示された国内基準と一致しません。"},{"choice":2,"correct":true,"title":"85 cm 以上","explanation":"日本のメタボリックシンドロームの診断基準では、男性の腹囲は85cm以上です。腹囲だけで診断せず、血圧・血糖・脂質の条件も組み合わせます。"},{"choice":3,"correct":false,"title":"90 cm 以上","explanation":"90cm以上は日本の基準で女性に用いる腹囲です。本問は男性の値を尋ねているため、85cm以上を選びます。"},{"choice":4,"correct":false,"title":"95 cm 以上","explanation":"95cm以上でも腹囲の条件は満たしますが、診断基準の境界値ではありません。基準として定められているのは85cm以上です。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"メタボリックシンドロームの診断基準において男性の腹囲〈ウエスト周囲径〉で正\nmetabolic syndrome\nしいのはどれか。","choices":["80 cm 以上","85 cm 以上","90 cm 以上","95 cm 以上"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":15,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[10],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A015"},"exam":112,"year":2023,"session":"AM","number":15},"sources":[{"title":"厚生労働省：メタボリックシンドロームの診断基準","url":"https://kennet.mhlw.go.jp/information/information/metabolic/m-01-003"}]},{"id":"112-AM-016","record":{"id":"112-AM-016","choice_explanations":[{"choice":1,"correct":false,"title":"CA19-9","explanation":"CA19-9は主に腫瘍マーカーとして用います。炎症などでも上がる場合はありますが、一般的な炎症マーカーとして問う項目ではありません。"},{"choice":2,"correct":false,"title":"抗核抗体","explanation":"抗核抗体は自己免疫疾患の評価などに用います。幅広い炎症反応の程度をみる代表的な項目はCRPです。"},{"choice":3,"correct":true,"title":"C 反応性蛋白質〈CRP〉","explanation":"CRPは炎症に伴って増加する急性期蛋白です。炎症の存在や経過の評価に用いますが、上昇だけで原因疾患や感染の種類を決めることはできません。"},{"choice":4,"correct":false,"title":"リウマトイド因子〈RF〉","explanation":"RFは関節リウマチの評価などに用いる自己抗体です。関節リウマチ以外でも陽性となる場合があり、一般的な炎症の指標とは分けます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"炎症マーカーはどれか。","choices":["CA19-9","抗核抗体","C 反応性蛋白質〈CRP〉","リウマトイド因子〈RF〉"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":16,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[10],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A016"},"exam":112,"year":2023,"session":"AM","number":16},"sources":[]},{"id":"112-AM-017","record":{"id":"112-AM-017","choice_explanations":[{"choice":1,"correct":false,"title":"吸 収","explanation":"吸収は薬が投与部位から血液中へ入る過程で、経口薬では主に消化管が関わります。肝臓の代表的な役割としては代謝を選びます。"},{"choice":2,"correct":false,"title":"分 布","explanation":"分布は血流に乗った薬が各組織へ移る過程です。肝臓にも薬は届きますが、肝臓が主に担う薬物動態上の過程は代謝です。"},{"choice":3,"correct":true,"title":"代 謝","explanation":"肝臓の酵素などによって薬の構造が変化します。代謝により作用が弱まる薬も、代謝されて作用を発揮する薬もあります。"},{"choice":4,"correct":false,"title":"蓄 積","explanation":"蓄積は投与が続くなどして体内に薬がたまることです。肝臓で行われる代表的な処理過程の名称は代謝です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"薬物動態で肝臓が関与するのはどれか。","choices":["吸 収","分 布","代 謝","蓄 積"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":17,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[11],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A017"},"exam":112,"year":2023,"session":"AM","number":17},"sources":[]},{"id":"112-AM-018","record":{"id":"112-AM-018","choice_explanations":[{"choice":1,"correct":true,"title":"座 位","explanation":"上体を起こすと重力によって胃内容が食道へ戻りにくくなります。食後すぐ横にならず、体調に合わせて座位を保つことが逆流予防に役立ちます。"},{"choice":2,"correct":false,"title":"仰臥位","explanation":"仰臥位では胃内容が食道へ逆流しやすくなることがあります。食後の逆流を防ぐ目的では、座位が適しています。"},{"choice":3,"correct":false,"title":"右側臥位","explanation":"右側臥位は胃からの排出と関連して用いられることがありますが、胃食道逆流を防ぐ目的で食後に選ぶ体位は座位です。"},{"choice":4,"correct":false,"title":"半側臥位","explanation":"半側臥位は体圧の分散などに用いますが、食後の逆流予防には上体を起こして重力を利用できる座位が適しています。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"胃から食道への逆流を防ぐために、成人が食後 30 分から1時間程度とるとよい\n体位はどれか。","choices":["座 位","仰臥位","右側臥位","半側臥位"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":18,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[11],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A018"},"exam":112,"year":2023,"session":"AM","number":18},"sources":[]},{"id":"112-AM-019","record":{"id":"112-AM-019","choice_explanations":[{"choice":1,"correct":false,"title":"20〜22 ℃","explanation":"20～22℃では皮膚に冷たく感じられ、全身清拭で体を冷やす可能性があります。清拭には温かいタオルを用い、露出も最小限にします。"},{"choice":2,"correct":false,"title":"30〜32 ℃","explanation":"30～32℃は体表に触れる清拭タオルとしては温かさが不足します。使用中の冷えも考慮して準備します。"},{"choice":3,"correct":true,"title":"40〜42 ℃","explanation":"皮膚に触れるタオルは40～42℃程度が適切です。準備する湯の温度とは区別し、実際に触れる前に温度と本人の感覚を確認します。"},{"choice":4,"correct":false,"title":"50〜52 ℃","explanation":"50～52℃のタオルをそのまま皮膚へ当てると、熱傷の危険があります。特に感覚が低下している人では、本人の訴えだけに頼らず確認します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"全身清拭時に皮膚に触れるタオルの温度で適切なのはどれか。","choices":["20〜22 ℃","30〜32 ℃","40〜42 ℃","50〜52 ℃"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":19,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[11],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A019"},"exam":112,"year":2023,"session":"AM","number":19},"sources":[]},{"id":"112-AM-020","record":{"id":"112-AM-020","choice_explanations":[{"choice":1,"correct":true,"title":"手 袋","explanation":"手袋は患者や周囲の物に触れて汚染されやすいため、最初に外します。外側に素手で触れないようにし、手指衛生を行います。"},{"choice":2,"correct":false,"title":"ガウン","explanation":"ガウンも汚染されますが、まず手袋を外してから汚染面を内側にまとめます。手袋とガウンを一緒に外す手順もありますが、本問では手袋を選びます。"},{"choice":3,"correct":false,"title":"サージカルマスク","explanation":"マスクは呼吸器を守るため、ほかの汚染した防護具を処理してから外します。前面に触れず、ひもなどを持って外します。"},{"choice":4,"correct":false,"title":"フェイスシールド","explanation":"フェイスシールドの前面も汚染している可能性があります。まず手袋を外し、清潔な手で前面を触らないように取り外します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"個人防護具の脱衣手順で最初に外すのはどれか。","choices":["手 袋","ガウン","サージカルマスク","フェイスシールド"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":20,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[11],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A020"},"exam":112,"year":2023,"session":"AM","number":20},"sources":[]},{"id":"112-AM-021","record":{"id":"112-AM-021","choice_explanations":[{"choice":1,"correct":false,"title":"酸化エチレンガス滅菌","explanation":"酸化エチレンガス滅菌はガスを利用し、熱に弱い器材などに用います。オートクレーブによる滅菌とは別の方法です。"},{"choice":2,"correct":true,"title":"高圧蒸気滅菌","explanation":"オートクレーブは高圧下の飽和水蒸気を利用して滅菌します。耐熱性・耐湿性のある器材に適しています。"},{"choice":3,"correct":false,"title":"放射線滅菌","explanation":"放射線滅菌は放射線を利用する方法で、製造段階の医療材料などに用いられます。オートクレーブの原理ではありません。"},{"choice":4,"correct":false,"title":"乾熱滅菌","explanation":"乾熱滅菌は高温の乾いた空気を利用します。水蒸気を用いるオートクレーブとは異なります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"オートクレーブによる滅菌法はどれか。","choices":["酸化エチレンガス滅菌","高圧蒸気滅菌","放射線滅菌","乾熱滅菌"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":21,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[12],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A021"},"exam":112,"year":2023,"session":"AM","number":21},"sources":[]},{"id":"112-AM-022","record":{"id":"112-AM-022","choice_explanations":[{"choice":1,"correct":false,"title":"経口投与","explanation":"経口薬は消化管から吸収されて血液中へ入ります。直接血管内へ入れる静脈内注射に比べ、作用が現れるまでに時間がかかります。"},{"choice":2,"correct":false,"title":"筋肉内注射","explanation":"筋肉内注射は筋肉から血管へ吸収されます。血流などの影響を受けるため、静脈内へ直接投与する方法ほど速くありません。"},{"choice":3,"correct":true,"title":"静脈内注射","explanation":"静脈内注射は直接血液中へ入るため、吸収過程を経ず最も速く全身へ届きます。厳密には「吸収が速い」というより「吸収過程がない」と理解します。"},{"choice":4,"correct":false,"title":"直腸内投与","explanation":"直腸内投与は直腸の粘膜から吸収されます。静脈内注射のように投与直後から全量が血液中へ入るわけではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"薬物の吸収速度が最も速いのはどれか。","choices":["経口投与","筋肉内注射","静脈内注射","直腸内投与"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":22,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[12],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A022"},"exam":112,"year":2023,"session":"AM","number":22},"sources":[]},{"id":"112-AM-023","record":{"id":"112-AM-023","choice_explanations":[{"choice":1,"correct":false,"title":"動脈血酸素分圧〈PaO2〉 60 Torr 以上","explanation":"PaO2が60Torr以上という条件は、低酸素血症に対する一般的な酸素療法開始基準ではありません。症状や病態によって個別の判断は必要です。"},{"choice":2,"correct":true,"title":"動脈血酸素分圧〈PaO2〉 60 Torr 未満","explanation":"室内空気下でPaO2が60Torr未満なら、低酸素血症として酸素療法を検討する基準になります。実際の酸素量や目標は、病態と医師の指示に合わせます。"},{"choice":3,"correct":false,"title":"動脈血二酸化炭素分圧〈PaCO2〉 60 Torr 以上","explanation":"PaCO2は換気の状態を示す値です。高値だけを理由に酸素を増やすのではなく、換気不全への対応を含めて評価します。"},{"choice":4,"correct":false,"title":"動脈血二酸化炭素分圧〈PaCO2〉 60 Torr 未満","explanation":"PaCO2が60Torr未満という条件だけでは、酸素化が不足しているか分かりません。酸素療法の適応にはPaO2などの酸素化の指標を用います。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"室内空気下での呼吸で、成人の一般的な酸素療法の適応の基準はどれか。","choices":["動脈血酸素分圧〈PaO2〉 60 Torr 以上","動脈血酸素分圧〈PaO2〉 60 Torr 未満","動脈血二酸化炭素分圧〈PaCO2〉 60 Torr 以上","動脈血二酸化炭素分圧〈PaCO2〉 60 Torr 未満"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":23,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[12],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A023"},"exam":112,"year":2023,"session":"AM","number":23},"sources":[]},{"id":"112-AM-024","record":{"id":"112-AM-024","choice_explanations":[{"choice":1,"correct":false,"title":"咳 嗽","explanation":"咳嗽は気道の刺激などで起こりますが、CO2ナルコーシスを特徴づける症状ではありません。二酸化炭素の蓄積による意識への影響を捉えます。"},{"choice":2,"correct":false,"title":"徐 脈","explanation":"脈拍の変化が起こる場合はありますが、CO2ナルコーシスの中心的な症状は意識障害です。徐脈だけで判断する状態ではありません。"},{"choice":3,"correct":false,"title":"浮 腫","explanation":"浮腫は循環や体液の異常などでみられます。CO2ナルコーシスに特徴的な神経症状とは異なります。"},{"choice":4,"correct":true,"title":"意識障害","explanation":"換気が不足して二酸化炭素が体内に蓄積すると、眠気や意識低下などを生じます。意識状態の変化は、換気の悪化を捉える重要な所見です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"CO2 ナルコーシスの症状で正しいのはどれか。","choices":["咳 嗽","徐 脈","浮 腫","意識障害"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":24,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[12],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A024"},"exam":112,"year":2023,"session":"AM","number":24},"sources":[]},{"id":"112-AM-025","record":{"id":"112-AM-025","choice_explanations":[{"choice":1,"correct":false,"title":"ビタミン A","explanation":"ビタミンAは視覚や上皮の維持に関わりますが、この設問で母乳栄養児に特有の不足として問われているのはビタミンKです。"},{"choice":2,"correct":false,"title":"ビタミン B","explanation":"ビタミンB群は代謝などに関わります。母体の栄養状態による不足はあり得ますが、本問の一般的な特徴としてはビタミンKを選びます。"},{"choice":3,"correct":false,"title":"ビタミン C","explanation":"ビタミンCはコラーゲンの合成などに関わります。母乳栄養児の出血予防との関連で注意する不足は、ビタミンKです。"},{"choice":4,"correct":false,"title":"ビタミン E","explanation":"ビタミンEは抗酸化作用を持ちますが、この問題で最も適切な不足栄養素ではありません。ビタミンKと血液凝固の関係を押さえます。"},{"choice":5,"correct":true,"title":"ビタミン K","explanation":"母乳にはビタミンKが少なく、新生児は蓄えや腸内細菌による供給も十分ではありません。不足すると出血につながるため、予防的な投与が行われます。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"母乳栄養の児に不足しやすいのはどれか。","choices":["ビタミン A","ビタミン B","ビタミン C","ビタミン E","ビタミン K"],"correct_answers":[5],"accepted_answer_sets":[[5]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":25,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[13],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A025"},"exam":112,"year":2023,"session":"AM","number":25},"sources":[{"title":"日本小児科学会：ビタミンK欠乏性出血症の予防に関する提言","url":"https://www.jpeds.or.jp/society-activities/column/proposals-assertions/50134.html"}]},{"id":"112-AM-026","record":{"id":"112-AM-026","choice_explanations":[{"choice":1,"correct":true,"title":"アセチルコリン","explanation":"神経筋接合部では運動神経からアセチルコリンが放出され、骨格筋側の受容体に作用します。重症筋無力症では、この伝達が自己抗体などで障害されます。"},{"choice":2,"correct":false,"title":"アドレナリン","explanation":"アドレナリンは交感神経系の反応などに関わります。運動神経から骨格筋へ収縮の指令を伝える神経筋接合部の伝達物質ではありません。"},{"choice":3,"correct":false,"title":"ドパミン","explanation":"ドパミンは運動調節など中枢神経で重要ですが、骨格筋の神経筋接合部で直接収縮を起こす伝達物質ではありません。"},{"choice":4,"correct":false,"title":"ノルアドレナリン","explanation":"ノルアドレナリンは主に交感神経の伝達などに関わります。骨格筋の神経筋接合部ではアセチルコリンが働きます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"骨格筋の細胞膜には( )に対する受容体がある。自己抗体がこの受容体の働\nきを阻害すると骨格筋は収縮できなくなる。\n( )に入る神経伝達物質として正しいのはどれか。","choices":["アセチルコリン","アドレナリン","ドパミン","ノルアドレナリン"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":26,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[13],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A026"},"exam":112,"year":2023,"session":"AM","number":26},"sources":[]},{"id":"112-AM-027","record":{"id":"112-AM-027","choice_explanations":[{"choice":1,"correct":true,"title":"アルカローシスである。","explanation":"興奮に伴う過換気で二酸化炭素を多く排出すると、血液がアルカリ性側へ傾きます。この場面では呼吸性アルカローシスを考えます。"},{"choice":2,"correct":false,"title":"ヘマトクリットは基準値よりも高い。","explanation":"ヘマトクリットは血液中の赤血球の割合です。過換気だけで血液が濃縮するとはいえず、高値になる根拠は示されていません。"},{"choice":3,"correct":false,"title":"動脈血酸素飽和度〈SaO2〉は 100 % を超えている。","explanation":"酸素飽和度はヘモグロビンに酸素が結合している割合なので、100％を超えることはありません。過換気でもこの上限は変わりません。"},{"choice":4,"correct":false,"title":"動脈血二酸化炭素分圧〈PaCO2〉は基準値よりも高い。","explanation":"過換気では二酸化炭素が過剰に排出されるため、PaCO2は低下します。高くなるのは換気が不足する場合などです。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"健常な女子(15 歳)が野外のコンサートで興奮し、頻呼吸を起こして倒れた。\nこのときの女子の体内の状態で正しいのはどれか。","choices":["アルカローシスである。","ヘマトクリットは基準値よりも高い。","動脈血酸素飽和度〈SaO2〉は 100 % を超えている。","動脈血二酸化炭素分圧〈PaCO2〉は基準値よりも高い。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":27,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[13],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A027"},"exam":112,"year":2023,"session":"AM","number":27},"sources":[]},{"id":"112-AM-028","record":{"id":"112-AM-028","choice_explanations":[{"choice":1,"correct":false,"title":"最高血中濃度","explanation":"最高血中濃度は投与後の濃度のピークを示します。薬が体内からどの速さで減っていくかを直接表す時間の指標ではありません。"},{"choice":2,"correct":true,"title":"生物学的半減期","explanation":"生物学的半減期は、血中濃度などが半分に低下するまでの時間です。薬の消失の速さを表す目安となり、投与間隔を考える際にも関わります。"},{"choice":3,"correct":false,"title":"濃度曲線下面積","explanation":"濃度曲線下面積は、時間を通じて体が薬にさらされた総量の目安です。濃度が半分になるまでの時間とは異なります。"},{"choice":4,"correct":false,"title":"最高血中濃度到達時間","explanation":"最高血中濃度到達時間は、投与してから濃度がピークになるまでの時間です。主に吸収の速さと関わり、消失の速さの指標とは区別します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"薬物の分解、排泄の速さの指標となるのはどれか。","choices":["最高血中濃度","生物学的半減期","濃度曲線下面積","最高血中濃度到達時間"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":28,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[14],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A028"},"exam":112,"year":2023,"session":"AM","number":28},"sources":[]},{"id":"112-AM-029","record":{"id":"112-AM-029","choice_explanations":[{"choice":1,"correct":false,"title":"B 細胞","explanation":"形質細胞はB細胞から分化しますが、多発性骨髄腫で腫瘍化する段階を正確に示すのは形質細胞です。分化前の名称との区別が必要です。"},{"choice":2,"correct":false,"title":"T 細胞","explanation":"T細胞は細胞性免疫などに関わるリンパ球です。多発性骨髄腫の腫瘍細胞ではありません。"},{"choice":3,"correct":true,"title":"形質細胞","explanation":"抗体をつくる形質細胞が腫瘍化し、骨髄で増殖します。異常な免疫グロブリンの産生や骨の障害などにつながります。"},{"choice":4,"correct":false,"title":"造血幹細胞","explanation":"造血幹細胞はさまざまな血球のもとになる細胞です。多発性骨髄腫は、それより分化の進んだ形質細胞の腫瘍です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"多発性骨髄腫で腫瘍化しているのはどれか。\nmultiple myeloma","choices":["B 細胞","T 細胞","形質細胞","造血幹細胞"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":29,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[14],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A029"},"exam":112,"year":2023,"session":"AM","number":29},"sources":[]},{"id":"112-AM-030","record":{"id":"112-AM-030","choice_explanations":[{"choice":1,"correct":false,"title":"外 傷","explanation":"外傷でもくも膜下出血は起こります。ただし、本問は通常の脳血管疾患としての成因を問う文脈で、公式正答は脳動脈瘤です。外傷性を含む集計と混同しないようにします。"},{"choice":2,"correct":false,"title":"脳腫瘍\nbrain tumor","explanation":"脳腫瘍に伴う出血が起こることはありますが、一般に問われるくも膜下出血の代表的な成因ではありません。"},{"choice":3,"correct":true,"title":"脳動脈瘤\ncerebral aneurysm","explanation":"脳動脈瘤の破裂は、非外傷性くも膜下出血の代表的な原因です。動脈のふくらみが破れ、くも膜下腔へ出血する病態と結び付けて覚えます。"},{"choice":4,"correct":false,"title":"脳動静脈奇形\ncerebral arteriovenous malformation","explanation":"脳動静脈奇形も出血の原因になりますが、非外傷性くも膜下出血の成因としては脳動脈瘤がより多いとされます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"くも膜下出血の成因で最も多いのはどれか。\nsubarachnoid hemorrhage","choices":["外 傷","脳腫瘍\nbrain tumor","脳動脈瘤\ncerebral aneurysm","脳動静脈奇形\ncerebral arteriovenous malformation"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":30,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[14],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A030"},"exam":112,"year":2023,"session":"AM","number":30},"sources":[]},{"id":"112-AM-031","record":{"id":"112-AM-031","choice_explanations":[{"choice":1,"correct":true,"title":"医療保険 健康保険法","explanation":"医療保険の根拠法の一つが健康保険法です。加入する制度により、国民健康保険法など別の法律も根拠となります。"},{"choice":2,"correct":false,"title":"介護保険 高齢者虐待の防止、高齢者の養護者に対する支援等に関\nする法律〈高齢者虐待防止法〉","explanation":"介護保険制度の根拠法は介護保険法です。高齢者虐待防止法は虐待の防止や被害者・養護者への支援を定める法律です。"},{"choice":3,"correct":false,"title":"雇用保険 社会福祉法","explanation":"雇用保険制度の根拠法は雇用保険法です。社会福祉法は社会福祉事業などの基本を定める法律であり、雇用保険の根拠法ではありません。"},{"choice":4,"correct":false,"title":"年金保険 生活困窮者自立支援法","explanation":"年金保険には国民年金法や厚生年金保険法などが関わります。生活困窮者自立支援法は、生活に困窮する人への相談や支援を定めています。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"社会保険制度と根拠法令の組合せで正しいのはどれか。","choices":["医療保険 健康保険法","介護保険 高齢者虐待の防止、高齢者の養護者に対する支援等に関\nする法律〈高齢者虐待防止法〉","雇用保険 社会福祉法","年金保険 生活困窮者自立支援法"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":31,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[14],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A031"},"exam":112,"year":2023,"session":"AM","number":31},"sources":[]},{"id":"112-AM-032","record":{"id":"112-AM-032","choice_explanations":[{"choice":1,"correct":false,"title":"介護医療院","explanation":"介護医療院は介護保険法に基づく施設です。老人福祉法に定める老人福祉施設として、両法に位置付けられる施設ではありません。"},{"choice":2,"correct":false,"title":"介護老人保健施設","explanation":"介護老人保健施設は介護保険法に基づく施設です。老人福祉法の老人福祉施設の一覧に含まれる施設とは区別します。"},{"choice":3,"correct":false,"title":"老人福祉センター","explanation":"老人福祉センターは老人福祉法に基づき、相談や健康増進、教養活動などを支えます。介護保険の通所介護を担う施設とは異なります。"},{"choice":4,"correct":true,"title":"老人デイサービスセンター","explanation":"老人福祉法の老人福祉施設であり、介護保険では通所介護などを行う場として位置づけられます。施設の法的位置づけと提供するサービスを結び付けます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"老人福祉法と介護保険法のいずれにも位置付けられている施設はどれか。","choices":["介護医療院","介護老人保健施設","老人福祉センター","老人デイサービスセンター"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":32,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[15],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A032"},"exam":112,"year":2023,"session":"AM","number":32},"sources":[]},{"id":"112-AM-033","record":{"id":"112-AM-033","choice_explanations":[{"choice":1,"correct":false,"title":"令和2年(2020 年)の新規感染者数は 10 年前に比べ増加している。","explanation":"2020年の新規HIV感染者報告数は、10年前の2010年より少なくなっています。実際の感染者総数と、新たに報告された人数は区別します。"},{"choice":2,"correct":false,"title":"日本では異性間の性的接触による感染が最も多い。","explanation":"日本の報告では、同性間の性的接触による感染が多くを占めます。異性間でも感染は起こりますが、最多という説明は一致しません。"},{"choice":3,"correct":false,"title":"早期に発見して治療を開始すれば完治する。","explanation":"早期に治療を始めてウイルスの増殖を抑えることは重要ですが、通常の治療で体内のHIVが完全に排除されるという意味の完治ではありません。"},{"choice":4,"correct":true,"title":"保健所での HIV 検査は匿名で受けられる。","explanation":"保健所では匿名でHIV検査を受けられます。受検しやすい体制は早期発見と治療につながり、プライバシーを守ることも重要です。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"ヒト免疫不全ウイルス〈HIV〉感染症について正しいのはどれか。\nhuman immunodeficiency virus infection","choices":["令和2年(2020 年)の新規感染者数は 10 年前に比べ増加している。","日本では異性間の性的接触による感染が最も多い。","早期に発見して治療を開始すれば完治する。","保健所での HIV 検査は匿名で受けられる。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":33,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[15],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A033"},"exam":112,"year":2023,"session":"AM","number":33},"sources":[{"title":"国立感染症研究所：HIV/AIDS in Japan, 2020","url":"https://idsc.nih.go.jp/en/surveillance/iasr/pathogens/vol42/500/500t.html"},{"title":"国立感染症研究所：HIV/AIDS in Japan, 2010","url":"https://idsc.niid.go.jp/iasr/32/380/tpc380.html"}]},{"id":"112-AM-034","record":{"id":"112-AM-034","choice_explanations":[{"choice":1,"correct":true,"title":"基準病床数を定める。","explanation":"医療計画では、地域に必要な病床の整備を図るため基準病床数を定めます。都道府県が地域の状況を踏まえて医療提供体制を計画します。"},{"choice":2,"correct":false,"title":"5年ごとに見直しを行う。","explanation":"出題時の医療計画は6年ごとの見直しが基本です。一部の事項では中間見直しがあり、すべてを5年ごととする説明ではありません。"},{"choice":3,"correct":false,"title":"特定機能病院の基準を定める。","explanation":"特定機能病院の承認基準は国が法令等で定めます。都道府県の医療計画がその基準を定めるわけではありません。"},{"choice":4,"correct":false,"title":"一次、二次および三次医療圏を設定する。","explanation":"医療計画で設定するのは二次医療圏と三次医療圏です。一次医療圏という概念まで、同じ法定の設定事項として扱いません。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"医療計画について正しいのはどれか。","choices":["基準病床数を定める。","5年ごとに見直しを行う。","特定機能病院の基準を定める。","一次、二次および三次医療圏を設定する。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":34,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[15],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A034"},"exam":112,"year":2023,"session":"AM","number":34},"sources":[{"title":"厚生労働省：医療計画について","url":"https://www.mhlw.go.jp/web/t_doc?dataId=00tc7556&dataType=1&pageNo=1"}]},{"id":"112-AM-035","record":{"id":"112-AM-035","choice_explanations":[{"choice":1,"correct":false,"title":"70 % エタノール","explanation":"一般的なアルコール消毒だけでは、ノロウイルスに対して十分な効果が得られないことがあります。嘔吐物を除去し、適切な次亜塩素酸ナトリウムで処理します。"},{"choice":2,"correct":false,"title":"ポビドンヨード","explanation":"ポビドンヨードは皮膚などの消毒に用います。床に飛散した嘔吐物の処理に用いる標準的な消毒薬としては選びません。"},{"choice":3,"correct":false,"title":"塩化ベンザルコニウム","explanation":"塩化ベンザルコニウムは、ノロウイルスによる汚染の処理には適していません。ウイルスの性質と消毒薬の効果を対応させて選びます。"},{"choice":4,"correct":true,"title":"次亜塩素酸ナトリウム","explanation":"嘔吐物を静かに除いた後、次亜塩素酸ナトリウムで汚染部位を処理します。必要な濃度は用途に合わせ、防護具の着用と換気にも注意します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"ノロウイルス感染症に罹患した患者の嘔吐物が床に飛び散っている。\nこの処理に使用する消毒薬で適切なのはどれか。","choices":["70 % エタノール","ポビドンヨード","塩化ベンザルコニウム","次亜塩素酸ナトリウム"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":35,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[15],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A035"},"exam":112,"year":2023,"session":"AM","number":35},"sources":[{"title":"厚生労働省：ノロウイルスに関するQ&A","url":"https://www.mhlw.go.jp/stf/seisakunitsuite/bunya/kenkou_iryou/shokuhin/syokuchu/kanren/yobou/040204-1.html"}]},{"id":"112-AM-036","record":{"id":"112-AM-036","choice_explanations":[{"choice":1,"correct":false,"title":"尿量が増加する。","explanation":"循環が低下すると腎臓への血流も減り、尿量は減少する傾向があります。尿量増加は臨死期の典型的な変化ではありません。"},{"choice":2,"correct":false,"title":"全身の筋肉が硬直する。","explanation":"死後には死後硬直が起こりますが、臨死期の全身の筋肉が一律に硬直するわけではありません。死に至る前の変化と死後の変化を区別します。"},{"choice":3,"correct":true,"title":"不規則な呼吸が出現する。","explanation":"呼吸調節や全身状態の変化により、呼吸の深さや間隔が不規則になることがあります。本人の苦痛の有無を観察し、家族にも状況を説明します。"},{"choice":4,"correct":false,"title":"頸動脈が触れなくなった後、橈骨動脈が触れなくなる。","explanation":"循環が弱まると、通常は橈骨動脈など末梢の脈が先に触れにくくなります。頸動脈と橈骨動脈が触れなくなる順序が逆です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"臨死期の身体的変化はどれか。","choices":["尿量が増加する。","全身の筋肉が硬直する。","不規則な呼吸が出現する。","頸動脈が触れなくなった後、橈骨動脈が触れなくなる。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":36,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[16],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A036"},"exam":112,"year":2023,"session":"AM","number":36},"sources":[]},{"id":"112-AM-037","record":{"id":"112-AM-037","choice_explanations":[{"choice":1,"correct":false,"title":"窓を開ける。 寒冷刺激による排尿促進","explanation":"窓を開けることは換気には役立ちますが、寒冷刺激で排尿を促すことを目的にはしません。排泄時の保温とプライバシーに配慮します。"},{"choice":2,"correct":true,"title":"上半身を挙上する。 腹圧のかけやすさによる\n排泄促進","explanation":"上半身を起こすと腹圧をかけやすく、寝たままより自然な排泄姿勢に近づきます。本人の体調や安静度に合わせて調整します。"},{"choice":3,"correct":false,"title":"外陰部にトイレットペーパーを当てる。 尿臭の防止","explanation":"外陰部に紙を当てる目的は、尿の流れを整え、飛散を防ぐことです。尿臭を防止するためという組合せではありません。"},{"choice":4,"correct":false,"title":"便器の底にトイレットペーパーを敷く。 寝具の汚染防止","explanation":"便器の底に紙を敷くと、音や便器への便の付着などを減らせます。寝具の汚染を防ぐには便器の位置や防水シーツなどの工夫が必要です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"成人女性に対するベッド上での排泄援助とその目的の組合せで適切なのはどれ\nか。","choices":["窓を開ける。 寒冷刺激による排尿促進","上半身を挙上する。 腹圧のかけやすさによる\n排泄促進","外陰部にトイレットペーパーを当てる。 尿臭の防止","便器の底にトイレットペーパーを敷く。 寝具の汚染防止"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":37,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[16],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A037"},"exam":112,"year":2023,"session":"AM","number":37},"sources":[]},{"id":"112-AM-038","record":{"id":"112-AM-038","choice_explanations":[{"choice":1,"correct":false,"title":"体温が上昇する。","explanation":"ノンレム睡眠では体の代謝や活動が低下し、体温も低下する方向にあります。体温上昇を代表的な特徴とはしません。"},{"choice":2,"correct":false,"title":"急速な眼球運動がある。","explanation":"急速な眼球運動はレム睡眠の特徴です。ノンレム睡眠との名称の違いも、眼球運動の有無に由来します。"},{"choice":3,"correct":false,"title":"加齢に伴い時間が長くなる。","explanation":"加齢では深いノンレム睡眠が減少する傾向があります。ノンレム睡眠の時間が一律に長くなるという説明は適切ではありません。"},{"choice":4,"correct":true,"title":"睡眠周期の前半にみられる。","explanation":"入眠後はノンレム睡眠に入り、その後レム睡眠へ移ります。睡眠周期の前半にノンレム睡眠があることと、夜の前半に深い睡眠が多いことを結び付けます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"成人のノンレム睡眠の特徴はどれか。","choices":["体温が上昇する。","急速な眼球運動がある。","加齢に伴い時間が長くなる。","睡眠周期の前半にみられる。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":38,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[16],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A038"},"exam":112,"year":2023,"session":"AM","number":38},"sources":[]},{"id":"112-AM-039","record":{"id":"112-AM-039","choice_explanations":[{"choice":1,"correct":false,"title":"胸腔穿刺 胸骨柄","explanation":"胸腔穿刺は胸壁の肋間から胸腔へ行います。胸骨柄を穿刺する方法ではありません。穿刺位置は貯留液の位置などを確認して決めます。"},{"choice":2,"correct":false,"title":"骨髄穿刺 第3・4腰椎間","explanation":"第3・4腰椎間は腰椎穿刺に用いる部位です。骨髄穿刺では腸骨など、骨髄を採取できる骨を選びます。"},{"choice":3,"correct":true,"title":"腹腔穿刺 腹直筋外側の側腹部","explanation":"腹腔穿刺では、血管や臓器への損傷を避けて腹直筋外側の側腹部などを選びます。実施時は画像や腹水の分布を確認します。"},{"choice":4,"correct":false,"title":"腰椎穿刺 上前腸骨棘","explanation":"上前腸骨棘は骨盤の骨の目印です。腰椎穿刺は腰椎間からくも膜下腔へ針を進める検査であり、部位が異なります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"穿刺と穿刺部位の組合せで適切なのはどれか。","choices":["胸腔穿刺 胸骨柄","骨髄穿刺 第3・4腰椎間","腹腔穿刺 腹直筋外側の側腹部","腰椎穿刺 上前腸骨棘"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":39,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[16],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A039"},"exam":112,"year":2023,"session":"AM","number":39},"sources":[]},{"id":"112-AM-040","record":{"id":"112-AM-040","choice_explanations":[{"choice":1,"correct":false,"title":"薬剤師法","explanation":"薬剤師法は薬剤師の資格や業務などを規定します。毒薬の保管方法の根拠法としては医薬品医療機器等法を選びます。"},{"choice":2,"correct":false,"title":"毒物及び劇物取締法","explanation":"毒物及び劇物取締法が対象とする毒物・劇物と、医薬品としての毒薬・劇薬は別の分類です。似た名称でも適用される法律が異なります。"},{"choice":3,"correct":false,"title":"麻薬及び向精神薬取締法","explanation":"麻薬及び向精神薬取締法は、麻薬や向精神薬の取扱いなどを規定します。医薬品の毒薬という区分の保管を定める法律ではありません。"},{"choice":4,"correct":true,"title":"医薬品、医療機器等の品質、有効性及び安全性の確保等に関する法律〈医薬\n品医療機器等法〉","explanation":"医薬品医療機器等法は、毒薬・劇薬を他の物と区別して保管することや、毒薬の保管場所の施錠などを定めています。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"毒薬の保管方法を規定している法律はどれか。","choices":["薬剤師法","毒物及び劇物取締法","麻薬及び向精神薬取締法","医薬品、医療機器等の品質、有効性及び安全性の確保等に関する法律〈医薬\n品医療機器等法〉"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":40,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[17],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A040"},"exam":112,"year":2023,"session":"AM","number":40},"sources":[]},{"id":"112-AM-041","record":{"id":"112-AM-041","choice_explanations":[{"choice":1,"correct":false,"title":"血小板成分製剤 2〜6℃","explanation":"血小板製剤は20～24℃で振とうして保存します。赤血球製剤と同じように冷蔵する保存方法ではありません。"},{"choice":2,"correct":true,"title":"赤血球成分製剤 2〜6℃","explanation":"赤血球製剤は2～6℃で保存します。製剤ごとに保存条件が違うため、血液製剤を一律に同じ温度で扱わないことが重要です。"},{"choice":3,"correct":false,"title":"血漿成分製剤 20〜24 ℃","explanation":"新鮮凍結血漿は凍結状態で保存する製剤です。20～24℃は凍結血漿の保存温度ではありません。融解後の取扱いは別に確認します。"},{"choice":4,"correct":false,"title":"全血製剤 20〜24 ℃","explanation":"全血製剤も2～6℃で保存します。20～24℃で保存する血小板製剤との違いを押さえます。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"輸血用血液製剤と保存温度の組合せで正しいのはどれか。","choices":["血小板成分製剤 2〜6℃","赤血球成分製剤 2〜6℃","血漿成分製剤 20〜24 ℃","全血製剤 20〜24 ℃"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":41,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[17],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A041"},"exam":112,"year":2023,"session":"AM","number":41},"sources":[{"title":"日本赤十字社：輸血用血液製剤の取扱い","url":"https://www.jrc.or.jp/mr/news/pdf/handlingposter1912.pdf"}]},{"id":"112-AM-042","record":{"id":"112-AM-042","choice_explanations":[{"choice":1,"correct":false,"title":"採血針を皮膚に穿刺した直後","explanation":"穿刺直後に解除する手順ではありません。採血管に必要な量を採血し、採血管をホルダーから外した後に駆血を解除します。"},{"choice":2,"correct":false,"title":"真空採血管内への血液の流入が始まったとき","explanation":"血液が流れ始めた段階では採血は終わっていません。本問の採血手順では、採血管を先に外してから駆血を解除します。"},{"choice":3,"correct":false,"title":"真空採血管内への血液の流入が終わったとき","explanation":"血液の流入が止まっても採血管が接続されたままです。管内からの逆流を防ぐため、先に採血管をホルダーから外します。"},{"choice":4,"correct":true,"title":"ホルダーから真空採血管を抜去した後","explanation":"採血管をホルダーから外してから駆血を解除し、その後に針を抜きます。採血管を接続したまま圧の状態を変えないようにする手順です。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"真空採血管とホルダーを用いて静脈血採血を実施するときに、駆血を解除するタ\nイミングで適切なのはどれか。","choices":["採血針を皮膚に穿刺した直後","真空採血管内への血液の流入が始まったとき","真空採血管内への血液の流入が終わったとき","ホルダーから真空採血管を抜去した後"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":42,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[17],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A042"},"exam":112,"year":2023,"session":"AM","number":42},"sources":[{"title":"PMDA：真空採血管添付文書（採血管抜去後の駆血解除）","url":"https://www.pmda.go.jp/PmdaSearch/kikiDetail/OldPdfData/219AFBZX00105000_A_02/1"}]},{"id":"112-AM-043","record":{"id":"112-AM-043","choice_explanations":[{"choice":1,"correct":true,"title":"耳 栓","explanation":"MRIに適した金属を含まない耳栓は、検査時の大きな音から耳を守るために使用します。持込み可能かは施設で確認した物を使います。"},{"choice":2,"correct":false,"title":"携帯電話","explanation":"携帯電話は金属や電子部品を含み、磁場による吸着や故障などの危険があります。検査室へ持ち込みません。"},{"choice":3,"correct":false,"title":"使い捨てカイロ","explanation":"使い捨てカイロには鉄粉が含まれ、磁場や発熱に関する危険があります。衣服に貼ったものも含めて検査前に外します。"},{"choice":4,"correct":false,"title":"キャッシュカード","explanation":"磁気カードは磁場によって記録情報が損なわれる可能性があります。キャッシュカードなどは検査室の外に置きます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"MRI 検査室に持ち込んでよいのはどれか。","choices":["耳 栓","携帯電話","使い捨てカイロ","キャッシュカード"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":43,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[17],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A043"},"exam":112,"year":2023,"session":"AM","number":43},"sources":[]},{"id":"112-AM-044","record":{"id":"112-AM-044","choice_explanations":[{"choice":1,"correct":false,"title":"傷害期では尿量が増加する。","explanation":"傷害期ではストレス反応により水分やナトリウムを保持し、尿量が減る傾向があります。尿量が増えるのは回復に向かう転換期の特徴です。"},{"choice":2,"correct":true,"title":"転換期では循環血液量が増加する。","explanation":"転換期では組織間にたまっていた水分が血管内へ戻り、循環血液量が増加します。その後の利尿も含め、回復への移行を捉えます。"},{"choice":3,"correct":false,"title":"筋力回復期では蛋白の分解が進む。","explanation":"筋力回復期では蛋白の合成が進み、失われた筋肉などを回復させます。分解が優位な傷害期とは方向が異なります。"},{"choice":4,"correct":false,"title":"脂肪蓄積期では活動性が低下する。","explanation":"脂肪蓄積期は体のエネルギー貯蔵が回復していく時期です。活動性の低下を特徴とする段階ではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"ムーア, F. D. が提唱した外科的侵襲を受けた患者の生体反応で正しいのはどれ\nMoore, F. D.\nか。","choices":["傷害期では尿量が増加する。","転換期では循環血液量が増加する。","筋力回復期では蛋白の分解が進む。","脂肪蓄積期では活動性が低下する。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":44,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[18],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A044"},"exam":112,"year":2023,"session":"AM","number":44},"sources":[]},{"id":"112-AM-045","record":{"id":"112-AM-045","choice_explanations":[{"choice":1,"correct":false,"title":"関節を速く動かす。","explanation":"速く動かすと痛みや筋緊張を起こし、組織を傷める可能性があります。関節を支えながら、ゆっくりと動かします。"},{"choice":2,"correct":false,"title":"運動麻痺がある場合は患側から行う。","explanation":"健側から行うと、本人が動きを理解しやすく、正常な可動域の目安も確認できます。患側を最初に強く動かす方法は勧めません。"},{"choice":3,"correct":true,"title":"他動運動は痛みが生じないように行う。","explanation":"他動運動では本人が痛みを感じない範囲を確認しながら動かします。拘縮予防のためでも、痛みを押して可動域を広げようとしません。"},{"choice":4,"correct":false,"title":"徒手筋力テストの結果が1以下の場合は自動運動を促す。","explanation":"MMTが1以下では、十分な関節運動を自力で起こせません。自動運動だけを促すのではなく、状態に合う他動運動などを用います。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"関節拘縮の予防を目的とした関節可動域〈ROM〉訓練で正しいのはどれか。","choices":["関節を速く動かす。","運動麻痺がある場合は患側から行う。","他動運動は痛みが生じないように行う。","徒手筋力テストの結果が1以下の場合は自動運動を促す。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":45,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[18],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A045"},"exam":112,"year":2023,"session":"AM","number":45},"sources":[]},{"id":"112-AM-046","record":{"id":"112-AM-046","choice_explanations":[{"choice":1,"correct":false,"title":"Bq","explanation":"Bq〈ベクレル〉は、放射性物質が放射線を出す能力である放射能を表します。人体が吸収したエネルギー量の単位ではありません。"},{"choice":2,"correct":false,"title":"eV","explanation":"eV〈電子ボルト〉はエネルギーの単位です。物質の質量当たりに吸収された放射線エネルギーを表す吸収線量の単位はGyです。"},{"choice":3,"correct":true,"title":"Gy","explanation":"Gy〈グレイ〉は吸収線量の単位です。放射線から物質が受け取ったエネルギーを質量当たりで示し、放射線治療の線量に用います。"},{"choice":4,"correct":false,"title":"Sv","explanation":"Sv〈シーベルト〉は、放射線の種類や組織への影響を考慮する等価線量・実効線量に用います。吸収線量そのものの単位とは区別します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"放射線治療で人体の吸収線量を表す単位はどれか。","choices":["Bq","eV","Gy","Sv"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":46,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[18],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A046"},"exam":112,"year":2023,"session":"AM","number":46},"sources":[]},{"id":"112-AM-048","record":{"id":"112-AM-048","choice_explanations":[{"choice":1,"correct":false,"title":"散 瞳","explanation":"肺尖部の腫瘍が交感神経に影響すると、散瞳ではなく縮瞳などのホルネル症候群を来すことがあります。"},{"choice":2,"correct":false,"title":"構音障害","explanation":"構音障害は発音に関わる神経や筋肉の障害などでみられます。肺尖部から胸壁への浸潤に特徴的な症状としては上肢の痛みを選びます。"},{"choice":3,"correct":false,"title":"閉眼困難","explanation":"閉眼困難は顔面神経などの障害でみられます。肺尖部の腫瘍による胸壁・腕神経叢への影響を表す症状ではありません。"},{"choice":4,"correct":true,"title":"上肢の疼痛","explanation":"肺尖部の腫瘍が胸壁や近くの腕神経叢に浸潤すると、肩から上肢にかけて痛みが生じます。腫瘍の位置と周囲の神経の関係を押さえます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"右肺尖部の肺癌の胸壁への浸潤による症状はどれか。\nlung cancer","choices":["散 瞳","構音障害","閉眼困難","上肢の疼痛"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":48,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[19],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A048"},"exam":112,"year":2023,"session":"AM","number":48},"sources":[]},{"id":"112-AM-049","record":{"id":"112-AM-049","choice_explanations":[{"choice":1,"correct":false,"title":"15 分以内に食べる。","explanation":"短時間で食べると、多量の食物が急に小腸へ入りやすくなります。よくかみ、ゆっくり食べるよう説明します。"},{"choice":2,"correct":false,"title":"糖質の多い食事を摂る。","explanation":"糖質の多い食事は、急な血糖変化などを通して症状を起こしやすくします。糖質に偏らない食事を考えます。"},{"choice":3,"correct":true,"title":"1回の摂取量を少なくする。","explanation":"1回量を少なくすると、小腸へ一度に流れ込む量を減らせます。必要な栄養は食事を複数回に分けて確保します。"},{"choice":4,"correct":false,"title":"1日の食事回数を少なくする。","explanation":"食事回数を減らすと、必要量を取るために1回量が増えやすくなります。少量ずつ回数を分けることが予防につながります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"胃切除術後のダンピング症候群を予防するための食事指導で適切なのはどれか。\ndumping syndrome","choices":["15 分以内に食べる。","糖質の多い食事を摂る。","1回の摂取量を少なくする。","1日の食事回数を少なくする。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":49,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[20],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A049"},"exam":112,"year":2023,"session":"AM","number":49},"sources":[]},{"id":"112-AM-050","record":{"id":"112-AM-050","choice_explanations":[{"choice":1,"correct":true,"title":"血清アルブミン〈Alb〉","explanation":"アルブミンは肝臓でつくられます。重度の肝硬変では合成能力が低下して血清アルブミンが減り、浮腫や腹水にも関わります。"},{"choice":2,"correct":false,"title":"血清ビリルビン〈Bil〉","explanation":"ビリルビンは肝臓での処理や排泄が障害されると上昇します。低下する項目としては選びません。"},{"choice":3,"correct":false,"title":"血中アンモニア〈NH3〉","explanation":"アンモニアの処理が低下し、血中濃度が上昇することがあります。肝性脳症との関連にも注意します。"},{"choice":4,"correct":false,"title":"プロトロンビン時間〈PT〉","explanation":"凝固因子の合成低下により、PTは時間としては延長します。PT活性の低下と、プロトロンビン時間の短縮を混同しないことが重要です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"重度の肝硬変で基準値よりも低い値を示す血液検査項目はどれか。\ncirrhosis","choices":["血清アルブミン〈Alb〉","血清ビリルビン〈Bil〉","血中アンモニア〈NH3〉","プロトロンビン時間〈PT〉"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":50,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[20],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A050"},"exam":112,"year":2023,"session":"AM","number":50},"sources":[]},{"id":"112-AM-051","record":{"id":"112-AM-051","choice_explanations":[{"choice":1,"correct":false,"title":"男性に多い。","explanation":"ばね指は女性に多く、特に更年期や妊娠・出産期などにもみられます。男性に多いという説明は適切ではありません。"},{"choice":2,"correct":true,"title":"原因は腱の炎症である。","explanation":"腱と腱鞘の間で炎症が起こり、腱の通過が滑らかでなくなります。指の曲げ伸ばしで引っ掛かりや、ばねのような動きが生じます。"},{"choice":3,"correct":false,"title":"好発部位は示指である。","explanation":"母指や中指に多くみられます。示指を代表的な好発部位とする説明は適切ではありません。"},{"choice":4,"correct":false,"title":"積極的にストレッチを行う。","explanation":"強く伸ばしたり繰り返し動かしたりすると、炎症が悪化する可能性があります。安静や治療の指示に合わせ、無理なストレッチを避けます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"成人のばね指で正しいのはどれか。\nsnapping finger","choices":["男性に多い。","原因は腱の炎症である。","好発部位は示指である。","積極的にストレッチを行う。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":51,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[20],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A051"},"exam":112,"year":2023,"session":"AM","number":51},"sources":[]},{"id":"112-AM-052","record":{"id":"112-AM-052","choice_explanations":[{"choice":1,"correct":false,"title":"｢術後2週から性交は可能です｣","explanation":"術後2週で一律に性交を再開してよいとはいえません。創部の治癒や診察結果を踏まえて、再開時期を確認します。"},{"choice":2,"correct":true,"title":"｢定期的に排尿を試みてください｣","explanation":"手術で骨盤内の自律神経に影響が及ぶと、尿意や排尿機能が低下することがあります。尿意だけに頼らず、定期的な排尿と残尿の評価が重要です。"},{"choice":3,"correct":false,"title":"｢調理のときは手袋をしてください｣","explanation":"手袋による調理中の手の保護は、上肢リンパ浮腫などの注意と関連することがあります。広汎子宮全摘出術後に共通する中心的な指導ではありません。"},{"choice":4,"correct":false,"title":"｢退院当日から浴槽の湯に浸かることができます｣","explanation":"入浴の再開は創部の状態などを確認して決めます。退院した日から必ず浴槽につかれると、一律に説明しません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"広汎子宮全摘出術を受けた患者への退院後の生活に関する説明で正しいのはどれ\nか。","choices":["｢術後2週から性交は可能です｣","｢定期的に排尿を試みてください｣","｢調理のときは手袋をしてください｣","｢退院当日から浴槽の湯に浸かることができます｣"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":52,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[20],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A052"},"exam":112,"year":2023,"session":"AM","number":52},"sources":[]},{"id":"112-AM-053","record":{"id":"112-AM-053","choice_explanations":[{"choice":1,"correct":false,"title":"エリスロポエチンが増加する。","explanation":"加齢に伴う造血機能の変化を、エリスロポエチンの単純な増加だけで説明しません。腎機能や貧血の状態にも影響されます。"},{"choice":2,"correct":false,"title":"黄色骨髄が減少する。","explanation":"加齢では造血に関わる赤色骨髄が減り、脂肪の多い黄色骨髄が増える傾向があります。減少という説明は逆です。"},{"choice":3,"correct":false,"title":"顆粒球数が増加する。","explanation":"顆粒球数が加齢に伴って一律に増えるわけではありません。数だけでなく、感染防御に関わる機能の変化も考えます。"},{"choice":4,"correct":true,"title":"赤血球数が減少する。","explanation":"加齢に伴い造血機能が低下し、赤血球数が減少する傾向があります。ただし、明らかな貧血を年齢だけで説明せず、疾患や栄養などの原因を確認します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"老化に伴う血液・造血器系の変化で適切なのはどれか。","choices":["エリスロポエチンが増加する。","黄色骨髄が減少する。","顆粒球数が増加する。","赤血球数が減少する。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":53,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[21],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A053"},"exam":112,"year":2023,"session":"AM","number":53},"sources":[]},{"id":"112-AM-054","record":{"id":"112-AM-054","choice_explanations":[{"choice":1,"correct":false,"title":"身体拘束の実施は担当看護師が決定する。","explanation":"身体拘束は担当看護師一人の判断で決めません。多職種などで必要性と代替方法を検討し、組織として判断・記録します。"},{"choice":2,"correct":false,"title":"ミトン型の手袋の使用は身体拘束ではない。","explanation":"ミトン型手袋でも、本人の手の動きや行動を制限する使い方は身体拘束に当たります。道具の名称だけで判断しません。"},{"choice":3,"correct":false,"title":"本人が身体拘束に同意していれば家族への説明は不要である。","explanation":"本人が同意していても、それだけで身体拘束が正当化されるわけではありません。必要性や方法、期間などを本人・家族に説明し、継続して検討します。"},{"choice":4,"correct":true,"title":"切迫性、非代替性および一時性の全てを満たしている場合に検討される。","explanation":"切迫性、非代替性、一時性の三つをすべて満たす場合に限り、例外的な実施を検討します。実施後も必要性を確認し、できるだけ早く解除を目指します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"高齢者の身体拘束に関する説明で適切なのはどれか。","choices":["身体拘束の実施は担当看護師が決定する。","ミトン型の手袋の使用は身体拘束ではない。","本人が身体拘束に同意していれば家族への説明は不要である。","切迫性、非代替性および一時性の全てを満たしている場合に検討される。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":54,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[21],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A054"},"exam":112,"year":2023,"session":"AM","number":54},"sources":[{"title":"厚生労働省：身体拘束ゼロへの手引き","url":"https://www.mhlw.go.jp/content/12300000/001248430.pdf"}]},{"id":"112-AM-055","record":{"id":"112-AM-055","choice_explanations":[{"choice":1,"correct":true,"title":"介護予防教室","explanation":"介護予防教室は、高齢者が心身機能を保ち、要介護状態の予防などに取り組む機会です。一般介護予防事業として、認定の有無にかかわらず対象になります。"},{"choice":2,"correct":false,"title":"介護老人保健施設","explanation":"介護老人保健施設への入所は、要介護認定などの利用条件があります。65歳以上なら認定なしで利用できる施設ではありません。"},{"choice":3,"correct":false,"title":"夜間対応型訪問介護","explanation":"夜間対応型訪問介護は、介護保険の認定などに基づくサービスです。認定の有無を問わず利用できる一般の教室とは異なります。"},{"choice":4,"correct":false,"title":"通所介護〈デイサービス〉","explanation":"介護保険の通所介護は要介護認定に基づいて利用します。介護予防や総合事業での通所サービスと区別します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"65 歳以上の高齢者が要介護認定の有無に関わらず利用できるのはどれか。","choices":["介護予防教室","介護老人保健施設","夜間対応型訪問介護","通所介護〈デイサービス〉"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":55,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[21],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A055"},"exam":112,"year":2023,"session":"AM","number":55},"sources":[]},{"id":"112-AM-056","record":{"id":"112-AM-056","choice_explanations":[{"choice":1,"correct":false,"title":"入院当日から複数の看護師が関わる。","explanation":"多くの担当者が入れ替わると、環境変化への戸惑いが強くなることがあります。必要な連携を保ちつつ、安心して関係を築けるよう配慮します。"},{"choice":2,"correct":false,"title":"1回の訪室で多くの情報を聴取する。","explanation":"一度に多くを質問すると疲労や混乱につながります。休息を挟み、本人の理解や体調に合わせて必要な情報を集めます。"},{"choice":3,"correct":false,"title":"1日のスケジュールは口頭で説明する。","explanation":"口頭だけでは覚えにくい場合があります。文字や予定表なども使い、本人が理解しやすく確認できる方法で説明します。"},{"choice":4,"correct":true,"title":"退院後の生活を予測して情報収集する。","explanation":"入院中から退院後の住環境、支援者、生活動作などを把握します。治療後にどのように生活を続けるかを考えることが、退院支援につながります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"入院中の高齢者への看護師の対応で適切なのはどれか。","choices":["入院当日から複数の看護師が関わる。","1回の訪室で多くの情報を聴取する。","1日のスケジュールは口頭で説明する。","退院後の生活を予測して情報収集する。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":56,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[21],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A056"},"exam":112,"year":2023,"session":"AM","number":56},"sources":[]},{"id":"112-AM-058","record":{"id":"112-AM-058","choice_explanations":[{"choice":1,"correct":true,"title":"自己中心性","explanation":"幼児期には、自分の見方と他者の見方を区別することがまだ難しい自己中心性がみられます。わがままという評価ではなく、認知発達の特徴として理解します。"},{"choice":2,"correct":false,"title":"心理的離乳","explanation":"心理的離乳は、親への心理的な依存から離れて自立へ向かう思春期などの特徴です。幼児期の自己中心性とは異なります。"},{"choice":3,"correct":false,"title":"ギャングエイジ","explanation":"ギャングエイジは、主に学童期に仲間集団との結び付きが強くなる時期を指します。幼児期を代表する特徴ではありません。"},{"choice":4,"correct":false,"title":"ボディイメージの変容","explanation":"身体の急な変化に伴うボディイメージの変容は、主に思春期などで問題になります。幼児期の代表的な心理社会的特徴としては自己中心性を選びます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"幼児期の心理社会的特徴はどれか。","choices":["自己中心性","心理的離乳","ギャングエイジ","ボディイメージの変容"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":58,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[23],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A058"},"exam":112,"year":2023,"session":"AM","number":58},"sources":[]},{"id":"112-AM-059","record":{"id":"112-AM-059","choice_explanations":[{"choice":1,"correct":false,"title":"鼻をかむ。","explanation":"鼻をかむには、口を閉じて鼻から息を出すなどの調整が必要です。2歳ころまでに一般的に習得する動作としてはスプーンの使用を選びます。"},{"choice":2,"correct":true,"title":"スプーンを使う。","explanation":"手と口の協調が発達すると、スプーンを使って食べられるようになります。こぼしながらでも、自分で食べる経験を支えることが大切です。"},{"choice":3,"correct":false,"title":"夜間のおむつがとれる。","explanation":"夜間の排尿自立は個人差が大きく、2歳ころまでに一律に達成するものではありません。夜間のおむつが必要でも直ちに異常とは判断しません。"},{"choice":4,"correct":false,"title":"洋服のボタンをとめる。","explanation":"ボタンをとめるには細かな指先の調整が必要で、スプーンを使うより後に習得します。発達に合った衣服と援助を選びます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"正常な幼児期の基本的生活習慣で、2歳0か月ころまでに習得するのはどれか。","choices":["鼻をかむ。","スプーンを使う。","夜間のおむつがとれる。","洋服のボタンをとめる。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":59,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[23],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A059"},"exam":112,"year":2023,"session":"AM","number":59},"sources":[]},{"id":"112-AM-060","record":{"id":"112-AM-060","choice_explanations":[{"choice":1,"correct":true,"title":"母子健康包括支援センター","explanation":"出題当時、母子健康包括支援センターは母子保健法に規定されていました。その後のこども家庭センターへの制度再編と、当時の根拠法は区別します。"},{"choice":2,"correct":false,"title":"乳児家庭全戸訪問事業","explanation":"乳児家庭全戸訪問事業は児童福祉法に規定される事業です。母子の健康に関わる事業でも、すべてが母子保健法に基づくわけではありません。"},{"choice":3,"correct":false,"title":"助産施設","explanation":"助産施設は児童福祉法に規定される児童福祉施設です。母子保健法に規定するセンターとは根拠が異なります。"},{"choice":4,"correct":false,"title":"特定妊婦","explanation":"特定妊婦は、出産後の養育について出産前から支援が特に必要と認められる妊婦で、児童福祉法に規定されています。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"母子保健法に規定されているのはどれか。","choices":["母子健康包括支援センター","乳児家庭全戸訪問事業","助産施設","特定妊婦"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":60,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[23],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A060"},"exam":112,"year":2023,"session":"AM","number":60},"sources":[{"title":"厚生労働省：母子保健法新旧対照表（平成29年施行）","url":"https://www.mhlw.go.jp/file/06-Seisakujouhou-11900000-Koyoukintoujidoukateikyoku/h28shinkyu.pdf"}]},{"id":"112-AM-061","record":{"id":"112-AM-061","choice_explanations":[{"choice":1,"correct":false,"title":"黄体は形成後1週間で萎縮する。","explanation":"受精・着床がなければ黄体は排卵後およそ2週間で退縮します。形成後1週間で萎縮するという説明ではありません。"},{"choice":2,"correct":false,"title":"エストロゲンの作用で子宮内膜が分泌期になる。","explanation":"エストロゲンは子宮内膜を増殖させます。分泌期への変化には主にプロゲステロンが作用します。"},{"choice":3,"correct":false,"title":"発育した卵胞の顆粒膜細胞からプロゲステロンが分泌される。","explanation":"発育卵胞の顆粒膜細胞は主にエストロゲン産生に関わります。排卵後の黄体がプロゲステロン分泌の中心です。"},{"choice":4,"correct":true,"title":"エストロゲンのポジティブフィードバックによって黄体形成ホルモンの分泌\nが増加する。","explanation":"排卵前の高いエストロゲン濃度が正のフィードバックを起こし、LHサージを誘発して排卵につながります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"排卵のある正常な月経周期で正しいのはどれか。","choices":["黄体は形成後1週間で萎縮する。","エストロゲンの作用で子宮内膜が分泌期になる。","発育した卵胞の顆粒膜細胞からプロゲステロンが分泌される。","エストロゲンのポジティブフィードバックによって黄体形成ホルモンの分泌\nが増加する。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":61,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[23],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A061"},"exam":112,"year":2023,"session":"AM","number":61},"sources":[]},{"id":"112-AM-062","record":{"id":"112-AM-062","choice_explanations":[{"choice":1,"correct":false,"title":"約6割は原因不明である。","explanation":"不妊の原因には排卵、卵管、精子などの因子があります。原因不明が約6割という説明は適切ではありません。"},{"choice":2,"correct":true,"title":"検査に基礎体温測定がある。","explanation":"基礎体温の推移は排卵や黄体機能を考える参考になります。ただし、基礎体温だけで排卵や不妊の原因を確定しません。"},{"choice":3,"correct":false,"title":"治療の1つに不妊手術がある。","explanation":"不妊手術は妊娠を防ぐための手術です。妊娠を目指す不妊症の治療とは目的が異なります。"},{"choice":4,"correct":false,"title":"女性の年齢は治療効果に影響しない。","explanation":"加齢に伴う卵巣機能や卵子の変化は妊娠率に影響します。女性の年齢は治療を検討する重要な要素です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"不妊症について正しいのはどれか。\ninfertility","choices":["約6割は原因不明である。","検査に基礎体温測定がある。","治療の1つに不妊手術がある。","女性の年齢は治療効果に影響しない。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":62,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[24],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A062"},"exam":112,"year":2023,"session":"AM","number":62},"sources":[]},{"id":"112-AM-063","record":{"id":"112-AM-063","choice_explanations":[{"choice":1,"correct":true,"title":"骨盤入口部に児頭が進入する際、児の頤部が胸壁に近づく。","explanation":"児頭が屈曲し、顎が胸に近づくことで小さい径で産道へ進入します。正常な第1回旋に当たります。"},{"choice":2,"correct":false,"title":"骨盤出口部に達した時点で、児頭の矢状縫合は母体の骨盤の横径に一致す\nる。","explanation":"内回旋によって児頭の矢状縫合は骨盤出口の前後径に近づきます。出口で横径に一致するという説明は適切ではありません。"},{"choice":3,"correct":false,"title":"児頭娩出後、胎児は肩の長軸が骨盤出口部の横径に一致するよう回旋する。","explanation":"肩は骨盤出口の前後径に適合するよう回旋します。児頭娩出後の外回旋は、この肩の回旋を反映します。"},{"choice":4,"correct":false,"title":"児頭が発露したころに胎盤が剝離する。","explanation":"胎盤の剝離と娩出は児の娩出後の分娩第3期に起こります。発露の時点を正常な剝離時期とはしません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"正常な分娩経過はどれか。","choices":["骨盤入口部に児頭が進入する際、児の頤部が胸壁に近づく。","骨盤出口部に達した時点で、児頭の矢状縫合は母体の骨盤の横径に一致す\nる。","児頭娩出後、胎児は肩の長軸が骨盤出口部の横径に一致するよう回旋する。","児頭が発露したころに胎盤が剝離する。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":63,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[24],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A063"},"exam":112,"year":2023,"session":"AM","number":63},"sources":[]},{"id":"112-AM-064","record":{"id":"112-AM-064","choice_explanations":[{"choice":1,"correct":false,"title":"呼吸数が減少する。","explanation":"RDSでは呼吸障害に伴う多呼吸、陥没呼吸、呻吟などがみられます。呼吸数の減少が代表的な初期所見ではありません。"},{"choice":2,"correct":false,"title":"過期産児に発症しやすい。","explanation":"肺の成熟が不十分な早産児に起こりやすい疾患です。過期産児を好発対象とする説明は逆です。"},{"choice":3,"correct":false,"title":"生後 24 時間ころから発症する。","explanation":"出生直後から数時間以内に呼吸障害が現れることが多く、生後24時間ころからの発症を典型とはしません。"},{"choice":4,"correct":true,"title":"肺サーファクタントの欠乏が原因で生じる。","explanation":"肺サーファクタントが不足すると肺胞が虚脱しやすくなり、ガス交換が障害されます。肺の未熟性と関連します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"新生児の呼吸窮迫症候群〈RDS〉で正しいのはどれか。\nrespiratory distress syndrome","choices":["呼吸数が減少する。","過期産児に発症しやすい。","生後 24 時間ころから発症する。","肺サーファクタントの欠乏が原因で生じる。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":64,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[24],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A064"},"exam":112,"year":2023,"session":"AM","number":64},"sources":[]},{"id":"112-AM-065","record":{"id":"112-AM-065","choice_explanations":[{"choice":1,"correct":false,"title":"Down〈ダウン〉症候群\nDownʼs syndrome","explanation":"ダウン症候群は21番染色体の異常による疾患です。運動性・音声チックを組み合わせた本問の特徴とは異なります。"},{"choice":2,"correct":true,"title":"Tourette〈トゥレット〉障害\nTouretteʼs disorder","explanation":"複数の運動性チックと音声チックを特徴とします。汚言を伴う場合もありますが、すべての患者にみられるわけではありません。"},{"choice":3,"correct":false,"title":"注意欠如・多動性障害〈ADHD〉\nattention-deficit/hyperactivity disorder","explanation":"ADHDの中心は不注意、多動性、衝動性です。チックが併存することはあっても、本問の特徴を直接示す診断ではありません。"},{"choice":4,"correct":false,"title":"Lennox-Gastaut〈レノックス・ガストー〉症候群\nLennox-Gastaut syndrome","explanation":"小児期発症の難治性てんかん症候群で、複数の発作型などを特徴とします。運動性・音声チックの疾患とは異なります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"小児期から青年期に発症し、運動性チック、音声チック及び汚言の乱用を伴うの\nはどれか。","choices":["Down〈ダウン〉症候群\nDownʼs syndrome","Tourette〈トゥレット〉障害\nTouretteʼs disorder","注意欠如・多動性障害〈ADHD〉\nattention-deficit/hyperactivity disorder","Lennox-Gastaut〈レノックス・ガストー〉症候群\nLennox-Gastaut syndrome"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":65,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[24],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A065"},"exam":112,"year":2023,"session":"AM","number":65},"sources":[]},{"id":"112-AM-066","record":{"id":"112-AM-066","choice_explanations":[{"choice":1,"correct":false,"title":"リカバリ","explanation":"リカバリは本人にとって意味のある生活や希望を取り戻す過程です。設問の力や技能の獲得を支える概念はエンパワメントです。"},{"choice":2,"correct":false,"title":"ストレングス","explanation":"ストレングスは本人の強みや利用できる資源を指します。それらを生かす支援は重要ですが、設問が示す支援全体の名称とは異なります。"},{"choice":3,"correct":false,"title":"レジリエンス","explanation":"レジリエンスは逆境から回復・適応する力です。権利や自己制御感を支え、力を発揮できるようにする支援とは区別します。"},{"choice":4,"correct":true,"title":"エンパワメント","explanation":"本人の選択や力を尊重し、自分の生活を主体的に決められるよう支えることです。一方的に支援者が決定する援助ではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"患者の権利や力を尊重し、自己制御している感覚を持たせ、患者が社会生活に必\n要な技能や能力を獲得する支援を意味するのはどれか。","choices":["リカバリ","ストレングス","レジリエンス","エンパワメント"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":66,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[25],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A066"},"exam":112,"year":2023,"session":"AM","number":66},"sources":[]},{"id":"112-AM-067","record":{"id":"112-AM-067","choice_explanations":[{"choice":1,"correct":false,"title":"障害基礎年金","explanation":"障害基礎年金の根拠は国民年金法です。障害福祉に関わる制度でも根拠法令を区別します。"},{"choice":2,"correct":false,"title":"一定割合の雇用義務","explanation":"雇用義務は障害者雇用促進法に基づく制度です。障害者総合支援法の医療費支援とは異なります。"},{"choice":3,"correct":false,"title":"精神障害者保健福祉手帳","explanation":"精神障害者保健福祉手帳は精神保健福祉法に基づきます。身体障害者手帳などとも根拠が異なります。"},{"choice":4,"correct":true,"title":"自立支援医療(精神通院医療)","explanation":"精神通院医療の自己負担を軽減する自立支援医療は、障害者総合支援法に基づきます。入院医療とは対象が異なります。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"障害者の日常生活及び社会生活を総合的に支援するための法律〈障害者総合支援\n法〉に基づき、精神障害者に適用されるのはどれか。","choices":["障害基礎年金","一定割合の雇用義務","精神障害者保健福祉手帳","自立支援医療(精神通院医療)"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":67,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[25],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A067"},"exam":112,"year":2023,"session":"AM","number":67},"sources":[{"title":"厚生労働省：自立支援医療","url":"https://www.mhlw.go.jp/stf/seisakunitsuite/bunya/hukushi_kaigo/shougaishahukushi/jiritsu/index.html"}]},{"id":"112-AM-068","record":{"id":"112-AM-068","choice_explanations":[{"choice":1,"correct":true,"title":"成年後見人に A さんの訪問看護計画を説明する。","explanation":"本人の意思を尊重しつつ、成年後見人の権限と必要性を確認して計画を説明します。後見人に医療行為の包括的な同意権があるという意味ではありません。"},{"choice":2,"correct":false,"title":"地域の民生委員に A さんの経済状況を知らせる。","explanation":"民生委員にも守秘義務がありますが、それだけで経済状況を無条件に提供できません。共有の目的、必要性、同意等を確認します。"},{"choice":3,"correct":false,"title":"A さんの訪問記録を電子メールに添付して援助者間で共有する。","explanation":"記録を通常のメールに添付するだけでは誤送信や漏えいの危険があります。必要な範囲と安全な共有手段を確認します。"},{"choice":4,"correct":false,"title":"新たなサービスの利用を検討する他の利用者に A さんのケアプランを見せ\nる。","explanation":"他の利用者への説明に本人のケアプランをそのまま見せると個人情報を漏らします。匿名化した一般的な資料などを用います。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さん(85 歳、男性)は1人暮らしで判断能力が不十分である。4親等以内の親\n族はいない。\n訪問看護事業所における A さんの情報管理で適切なのはどれか。","choices":["成年後見人に A さんの訪問看護計画を説明する。","地域の民生委員に A さんの経済状況を知らせる。","A さんの訪問記録を電子メールに添付して援助者間で共有する。","新たなサービスの利用を検討する他の利用者に A さんのケアプランを見せ\nる。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":68,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[25],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A068"},"exam":112,"year":2023,"session":"AM","number":68},"sources":[]},{"id":"112-AM-069","record":{"id":"112-AM-069","choice_explanations":[{"choice":1,"correct":false,"title":"電気のブレーカーを落とす。","explanation":"通電火災の予防として重要ですが、酸素濃縮器が止まった際には酸素供給の確保を先に行います。"},{"choice":2,"correct":false,"title":"玄関の扉を開けて出口を確保する。","explanation":"避難経路の確保も必要ですが、本問では停電により中断する酸素供給への対応が優先されます。"},{"choice":3,"correct":false,"title":"訪問看護ステーションに連絡をする。","explanation":"連絡による支援要請は必要に応じて行います。連絡を待つ間も酸素療法を継続できるよう備えます。"},{"choice":4,"correct":true,"title":"酸素濃縮器から酸素ボンベに切り替える。","explanation":"電源を必要とする濃縮器からボンベへ切り替え、処方された酸素供給を保ちます。平時から操作と残量を確認します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さん(80 歳、女性)は1人暮らしで、在宅酸素療法〈HOT〉を受けている。訪問\n看護師は A さんに停電時を想定した避難行動の指導を行うことにした。\nA さんの停電時の避難行動で優先度が高いのはどれか。","choices":["電気のブレーカーを落とす。","玄関の扉を開けて出口を確保する。","訪問看護ステーションに連絡をする。","酸素濃縮器から酸素ボンベに切り替える。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":69,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[26],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A069"},"exam":112,"year":2023,"session":"AM","number":69},"sources":[{"title":"厚生労働省：在宅医療機器の課題・停電時の酸素供給","url":"https://www.mhlw.go.jp/file/05-Shingikai-11121000-Iyakushokuhinkyoku-Soumuka/zaitaku2.pdf"}]},{"id":"112-AM-070","record":{"id":"112-AM-070","choice_explanations":[{"choice":1,"correct":true,"title":"福祉用具貸与","explanation":"福祉用具貸与は居宅サービスに位置づけられ、設問の指定・監督主体に対応します。指定都市等への権限移譲は別に確認します。"},{"choice":2,"correct":false,"title":"小規模多機能型居宅介護","explanation":"小規模多機能型居宅介護は地域密着型サービスで、市町村が指定・監督します。"},{"choice":3,"correct":false,"title":"定期巡回・随時対応型訪問介護看護","explanation":"定期巡回・随時対応型訪問介護看護は地域密着型サービスで、市町村が指定・監督します。"},{"choice":4,"correct":false,"title":"認知症対応型共同生活介護〈グループホーム〉","explanation":"認知症対応型共同生活介護は地域密着型サービスです。都道府県を基本とする一般の居宅サービスとは区別します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"介護保険制度における都道府県が指定・監督を行う居宅サービスはどれか。","choices":["福祉用具貸与","小規模多機能型居宅介護","定期巡回・随時対応型訪問介護看護","認知症対応型共同生活介護〈グループホーム〉"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":70,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[26],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A070"},"exam":112,"year":2023,"session":"AM","number":70},"sources":[]},{"id":"112-AM-071","record":{"id":"112-AM-071","choice_explanations":[{"choice":1,"correct":false,"title":"手すりは左手で持つ。","explanation":"麻痺のある左手では十分に体を支えられない可能性があります。健側の右手で安定して握れる手すりを検討します。"},{"choice":2,"correct":false,"title":"左足から浴槽に入る。","explanation":"一般に入るときは健側から、出るときは患側からを基本に、座位と介助を使って安全を確保します。動作は個別に評価します。"},{"choice":3,"correct":false,"title":"浴室内を杖で移動する。","explanation":"濡れた床では杖が滑るおそれがあります。浴室用の手すりや福祉用具を使い、安定した支持を確保します。"},{"choice":4,"correct":true,"title":"浴槽から出るときは入浴台〈バスボード〉を使う。","explanation":"入浴台で腰掛ける位置を確保すると、片脚立ちで浴槽をまたぐ負担を減らせます。固定状態や高さも確認します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さん(70 歳、男性、要介護1)は脳梗塞の後遺症で左不全麻痺がある。家屋内\ncerebral infarction\nは杖を使用して移動が可能である。A さんから｢入浴が不安なので安全な方法を教\nえてほしい｣と訪問看護師に相談があった。\nA さんへの助言で適切なのはどれか。","choices":["手すりは左手で持つ。","左足から浴槽に入る。","浴室内を杖で移動する。","浴槽から出るときは入浴台〈バスボード〉を使う。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":71,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[26],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A071"},"exam":112,"year":2023,"session":"AM","number":71},"sources":[]},{"id":"112-AM-072","record":{"id":"112-AM-072","choice_explanations":[{"choice":1,"correct":false,"title":"看護職員の仕事への動機付けを行う。","explanation":"職員の意欲を高める働きかけは、指揮・動機付けに関わります。実績を評価し修正する統制とは段階が異なります。"},{"choice":2,"correct":false,"title":"病棟の目標をもとに看護活動の年間計画を立案する。","explanation":"目標を具体的な年間活動にするのは計画の段階です。結果と目標を比較する統制ではありません。"},{"choice":3,"correct":false,"title":"褥瘡ケアの改善に取り組むための担当チームを構成する。","explanation":"担当や役割を構成することは組織化です。活動の評価結果に応じた修正とは異なります。"},{"choice":4,"correct":true,"title":"病棟の1年間の業務評価に基づき看護活動の計画を修正する。","explanation":"実績を目標と照らして評価し、必要な修正を行うのが統制です。評価を次の活動改善に結び付けます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"看護マネジメントのプロセスの｢統制｣はどれか。","choices":["看護職員の仕事への動機付けを行う。","病棟の目標をもとに看護活動の年間計画を立案する。","褥瘡ケアの改善に取り組むための担当チームを構成する。","病棟の1年間の業務評価に基づき看護活動の計画を修正する。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":72,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[27],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A072"},"exam":112,"year":2023,"session":"AM","number":72},"sources":[]},{"id":"112-AM-073","record":{"id":"112-AM-073","choice_explanations":[{"choice":1,"correct":true,"title":"1年以内ごとに1回、定期に心理的な負担の程度を把握するための検査を行\nう。","explanation":"ストレスチェックは労働安全衛生法に基づきます。本問の300人の事業場では年1回の実施対象となります。"},{"choice":2,"correct":false,"title":"8時間を超える夜勤の時は1時間以上の休憩時間を確保する。","explanation":"8時間を超える労働の休憩時間は労働基準法に基づきます。労働安全衛生法とは根拠が異なります。"},{"choice":3,"correct":false,"title":"生理日に就業が著しく困難な場合は休暇の請求ができる。","explanation":"生理日の就業が著しく困難な場合の措置は労働基準法に基づきます。"},{"choice":4,"correct":false,"title":"妊娠中は請求すれば時間外労働が免除される。","explanation":"妊産婦の請求に基づく時間外労働等の制限は労働基準法に基づきます。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"職員数が 300 人の病院の看護師の働き方に関するマネジメントで、労働安全衛生\n法に基づいて規定されているのはどれか。","choices":["1年以内ごとに1回、定期に心理的な負担の程度を把握するための検査を行\nう。","8時間を超える夜勤の時は1時間以上の休憩時間を確保する。","生理日に就業が著しく困難な場合は休暇の請求ができる。","妊娠中は請求すれば時間外労働が免除される。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":73,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[27],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A073"},"exam":112,"year":2023,"session":"AM","number":73},"sources":[{"title":"厚生労働省：ストレスチェックQ&A","url":"https://stresscheck.mhlw.go.jp/faq_all.html"},{"title":"厚生労働省：労働基準法","url":"https://www.mhlw.go.jp/web/t_doc?dataId=73022000"}]},{"id":"112-AM-074","record":{"id":"112-AM-074","choice_explanations":[{"choice":1,"correct":false,"title":"高度な治療を目的とした活動","explanation":"高度な治療の導入だけでは住民の身近な健康課題に広く対応できません。地域に適した継続可能な方法が重要です。"},{"choice":2,"correct":false,"title":"医学的研究の遂行を優先した活動","explanation":"研究の遂行を住民の必要より優先しません。住民の健康課題と参加を中心に活動します。"},{"choice":3,"correct":true,"title":"派遣先で入手できる資源を利用した活動","explanation":"現地で利用・維持できる資源を生かすことは適正技術や持続可能性につながり、プライマリヘルスケアの原則に合います。"},{"choice":4,"correct":false,"title":"派遣される専門家チームを中心とする活動","explanation":"専門家だけを中心にせず、住民自身の参加と主体的な取組を支えます。派遣終了後も続く体制を考えます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"国際協力として5歳未満児死亡率の高い地域に1年間派遣されることになった看\n護師が、派遣される地域の住民に対して行う活動でプライマリヘルスケアの原則に\n基づいた活動はどれか。","choices":["高度な治療を目的とした活動","医学的研究の遂行を優先した活動","派遣先で入手できる資源を利用した活動","派遣される専門家チームを中心とする活動"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":74,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[27],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A074"},"exam":112,"year":2023,"session":"AM","number":74},"sources":[]},{"id":"112-AM-075","record":{"id":"112-AM-075","choice_explanations":[{"choice":1,"correct":true,"title":"蝸牛管","explanation":"蝸牛管の基底膜上にコルチ器があり、有毛細胞が音の振動を電気信号へ変換します。"},{"choice":2,"correct":false,"title":"半規管","explanation":"半規管は頭の回転運動を感知し、平衡覚に関わります。音を感知するコルチ器の場所ではありません。"},{"choice":3,"correct":false,"title":"鼓 室","explanation":"鼓室は中耳の空間で、耳小骨によって振動を内耳へ伝えます。コルチ器は内耳にあります。"},{"choice":4,"correct":false,"title":"鼓 膜","explanation":"鼓膜は音波によって振動し耳小骨へ伝えます。有毛細胞がある感覚器そのものではありません。"},{"choice":5,"correct":false,"title":"前 庭","explanation":"前庭は主に直線加速度や重力に対する頭の位置を感知します。聴覚を担う蝸牛とは役割が異なります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"音を感知するラセン器〈Corti〈コルチ〉器〉があるのはどれか。","choices":["蝸牛管","半規管","鼓 室","鼓 膜","前 庭"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":75,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[28],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A075"},"exam":112,"year":2023,"session":"AM","number":75},"sources":[]},{"id":"112-AM-076","record":{"id":"112-AM-076","choice_explanations":[{"choice":1,"correct":false,"title":"フィブリノゲン","explanation":"フィブリノゲンは大きな血漿蛋白で、正常な糸球体ではほとんど濾過されません。"},{"choice":2,"correct":true,"title":"ミオグロビン","explanation":"ミオグロビンは比較的小さい蛋白で、血中に入ると糸球体で濾過されます。大量に出る場合は筋障害などを考えます。"},{"choice":3,"correct":false,"title":"アルブミン","explanation":"アルブミンは正常では濾過障壁により通過が強く制限されます。ごく少量の濾過を否定する意味ではありません。"},{"choice":4,"correct":false,"title":"血小板","explanation":"血小板は血球成分で、正常な糸球体濾過によって尿へ出るものではありません。"},{"choice":5,"correct":false,"title":"赤血球","explanation":"赤血球は正常な濾過障壁を通りません。尿中に多くみられる場合は出血や腎疾患などを評価します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"正常な糸球体で濾過される物質はどれか。","choices":["フィブリノゲン","ミオグロビン","アルブミン","血小板","赤血球"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":76,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[28],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A076"},"exam":112,"year":2023,"session":"AM","number":76},"sources":[]},{"id":"112-AM-077","record":{"id":"112-AM-077","choice_explanations":[{"choice":1,"correct":false,"title":"対流による体熱の放散","explanation":"水の流れによる対流も熱喪失に関わりますが、本問では冷水に直接触れて熱が移る熱伝導が問われています。"},{"choice":2,"correct":false,"title":"放射による体熱の放散","explanation":"放射は電磁波として周囲へ熱を失うことです。冷水との直接接触による急速な熱移動とは異なります。"},{"choice":3,"correct":true,"title":"熱伝導による体熱の放散","explanation":"水は空気より熱を伝えやすく、皮膚から冷水へ熱が移動します。直接接触する物質との温度差による熱喪失です。"},{"choice":4,"correct":false,"title":"代謝による熱エネルギー産生の低下","explanation":"冷水への反応では、体温を保つため代謝を高めようとします。産熱低下が最初の主な原因ではありません。"},{"choice":5,"correct":false,"title":"骨格筋における熱エネルギー産生の低下","explanation":"寒冷刺激では震えなどで筋肉の産熱を増やします。冷水への熱喪失が大きく、その補償が追い付かなくなります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"冷たい川に飛び込んだときに急激に体温が低下する原因で正しいのはどれか。","choices":["対流による体熱の放散","放射による体熱の放散","熱伝導による体熱の放散","代謝による熱エネルギー産生の低下","骨格筋における熱エネルギー産生の低下"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":77,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[28],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A077"},"exam":112,"year":2023,"session":"AM","number":77},"sources":[]},{"id":"112-AM-078","record":{"id":"112-AM-078","choice_explanations":[{"choice":1,"correct":false,"title":"発 熱","explanation":"過剰なインスリンでまず注意するのは低血糖です。発熱は代表的な低血糖症状ではありません。"},{"choice":2,"correct":false,"title":"浮 腫","explanation":"浮腫は本問が問う急性の低血糖症状ではありません。血糖低下に伴う自律神経症状を捉えます。"},{"choice":3,"correct":false,"title":"口渇感","explanation":"口渇は高血糖に伴う脱水などでみられます。インスリン過量による低血糖の代表所見とは異なります。"},{"choice":4,"correct":false,"title":"顔面紅潮","explanation":"低血糖では冷汗や顔面蒼白などがみられます。顔面紅潮を典型的な所見とはしません。"},{"choice":5,"correct":true,"title":"手足のふるえ","explanation":"血糖低下に対する交感神経反応で振戦、動悸、冷汗などが起こります。さらに進むと意識障害を来します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"インスリンを過剰に投与したときに現れる症候で正しいのはどれか。","choices":["発 熱","浮 腫","口渇感","顔面紅潮","手足のふるえ"],"correct_answers":[5],"accepted_answer_sets":[[5]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":78,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[29],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A078"},"exam":112,"year":2023,"session":"AM","number":78},"sources":[]},{"id":"112-AM-079","record":{"id":"112-AM-079","choice_explanations":[{"choice":1,"correct":false,"title":"弁口面積が拡大する。","explanation":"僧帽弁の開口が狭くなり、血液が左房から左室へ流れにくくなります。面積の拡大ではありません。"},{"choice":2,"correct":true,"title":"左心房内圧が上昇する。","explanation":"狭い弁口を通過しにくいため左房内圧が上がり、肺うっ血や左房拡大につながります。"},{"choice":3,"correct":false,"title":"狭心痛を合併することが多い。","explanation":"狭心痛は大動脈弁狭窄などで重要です。僧帽弁狭窄の代表症状は労作時呼吸困難などです。"},{"choice":4,"correct":false,"title":"弁尖の先天的な3尖化が原因となる。","explanation":"僧帽弁の狭窄はリウマチ性変化などで起こります。先天的な3尖化を代表的原因とはしません。"},{"choice":5,"correct":false,"title":"胸骨右縁第2肋間で心雑音を聴取する。","explanation":"僧帽弁狭窄の拡張期雑音は主に心尖部で聴取します。胸骨右縁第2肋間は大動脈弁領域です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"僧帽弁狭窄症について正しいのはどれか。\nmitral stenosis","choices":["弁口面積が拡大する。","左心房内圧が上昇する。","狭心痛を合併することが多い。","弁尖の先天的な3尖化が原因となる。","胸骨右縁第2肋間で心雑音を聴取する。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":79,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[29],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A079"},"exam":112,"year":2023,"session":"AM","number":79},"sources":[]},{"id":"112-AM-081","record":{"id":"112-AM-081","choice_explanations":[{"choice":1,"correct":false,"title":"男性に多い。","explanation":"変形性膝関節症は女性に多く、加齢や肥満などが関わります。男性に多いという説明は適切ではありません。"},{"choice":2,"correct":false,"title":"第一選択は手術療法である。","explanation":"まず運動療法、体重管理、薬物療法などの保存療法を検討します。症状や障害に応じて手術を選びます。"},{"choice":3,"correct":false,"title":"変形性関節症の中で2番目に多い。\nosteoarthritis","explanation":"膝は変形性関節症の主要な好発部位です。「2番目」という順位の根拠は不明のため、この部分は要確認です。"},{"choice":4,"correct":false,"title":"二次性のものが一次性のものより多い。","explanation":"明確な先行疾患などを特定できない一次性が多くを占めます。外傷等に続く二次性の方が多いという説明ではありません。"},{"choice":5,"correct":true,"title":"経時的に進行して 10 年で半数が悪化する。","explanation":"公式正答はこの選択肢です。経時的に進行する疾患ですが、「10年で半数」の対象集団と評価基準の根拠は不明で、確認が必要です。"}],"status":"UNKNOWN","review_reason":"選択肢3の順位及び選択肢5の「10年で半数が悪化」の集団・評価尺度の原典が未確定。公式正答は維持し該当箇所を不明と明記。","fixes_made":[]},"input_anchor":{"question":"変形性膝関節症について正しいのはどれか。\nosteoarthritis of the knee","choices":["男性に多い。","第一選択は手術療法である。","変形性関節症の中で2番目に多い。\nosteoarthritis","二次性のものが一次性のものより多い。","経時的に進行して 10 年で半数が悪化する。"],"correct_answers":[5],"accepted_answer_sets":[[5]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":81,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[30],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A081"},"exam":112,"year":2023,"session":"AM","number":81},"sources":[{"title":"日本整形外科学会：変形性膝関節症","url":"https://www.joa.or.jp/public/sick/condition/knee_osteoarthritis.html"}]},{"id":"112-AM-082","record":{"id":"112-AM-082","choice_explanations":[{"choice":1,"correct":true,"title":"インフルエンザ\ninfluenza","explanation":"インフルエンザは学校感染症の第二種です。感染拡大予防のため、発症後の日数と解熱後の日数などで出席停止期間を判断します。"},{"choice":2,"correct":false,"title":"細菌性赤痢\nshigellosis","explanation":"細菌性赤痢は第三種に分類されます。第二種のインフルエンザと区別します。"},{"choice":3,"correct":false,"title":"ジフテリア\ndiphtheria","explanation":"ジフテリアは第一種です。感染症法の分類と学校感染症の種別を混同しないようにします。"},{"choice":4,"correct":false,"title":"腸チフス\ntyphoid fever","explanation":"腸チフスは第三種です。第二種の代表はインフルエンザや麻疹などです。"},{"choice":5,"correct":false,"title":"流行性角結膜炎\nepidemic keratoconjunctivitis","explanation":"流行性角結膜炎は第三種です。学校での感染拡大に注意しますが、第二種ではありません。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"学校保健安全法で出席停止となる学校感染症のうち、第二種に分類されているの\nはどれか。","choices":["インフルエンザ\ninfluenza","細菌性赤痢\nshigellosis","ジフテリア\ndiphtheria","腸チフス\ntyphoid fever","流行性角結膜炎\nepidemic keratoconjunctivitis"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":82,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[30],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A082"},"exam":112,"year":2023,"session":"AM","number":82},"sources":[{"title":"e-Gov：学校保健安全法施行規則第18条","url":"https://laws.e-gov.go.jp/document?lawid=333M50000080018"}]},{"id":"112-AM-083","record":{"id":"112-AM-083","choice_explanations":[{"choice":1,"correct":false,"title":"脈拍 70/分","explanation":"成人の安静時脈拍70回/分は通常の範囲です。単独では緊急対応を要する値ではありません。"},{"choice":2,"correct":true,"title":"体温 34.4 ℃","explanation":"34.4℃は低体温を示します。測定の確かさと全身状態を確認し、保温や原因評価など速やかな対応が必要です。"},{"choice":3,"correct":false,"title":"呼吸数 14/分","explanation":"呼吸数14回/分は成人の安静時として通常の範囲です。呼吸の深さや努力性も併せて評価します。"},{"choice":4,"correct":false,"title":"血圧 130/80 mmHg","explanation":"130/80mmHgは、この選択肢の中で緊急対応を要する血圧ではありません。普段の値や症状も確認します。"},{"choice":5,"correct":false,"title":"グラスゴー・コーマ・スケール〈GCS〉15 点","explanation":"GCS15点は開眼・言語・運動反応が最良の状態です。意識障害を示す低い点数ではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"成人におけるバイタルサインで緊急に対応が必要なのはどれか。","choices":["脈拍 70/分","体温 34.4 ℃","呼吸数 14/分","血圧 130/80 mmHg","グラスゴー・コーマ・スケール〈GCS〉15 点"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":83,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[30],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A083"},"exam":112,"year":2023,"session":"AM","number":83},"sources":[]},{"id":"112-AM-084","record":{"id":"112-AM-084","choice_explanations":[{"choice":1,"correct":false,"title":"排尿回数の減少","explanation":"加齢により頻尿が起こりやすくなります。膀胱機能や基礎疾患などの影響を評価します。"},{"choice":2,"correct":false,"title":"膀胱容量の増加","explanation":"膀胱の機能的容量は減る傾向があります。容量増加を一般的な変化とはしません。"},{"choice":3,"correct":false,"title":"夜間尿量の減少","explanation":"尿濃縮力や日内リズムの変化などから夜間尿が増えやすくなります。減少という説明は逆です。"},{"choice":4,"correct":true,"title":"残尿量の増加","explanation":"排尿筋の機能低下や排出障害などで残尿が増えやすくなります。残尿は感染や頻尿にも関わります。"},{"choice":5,"correct":false,"title":"尿比重の上昇","explanation":"腎臓の尿濃縮力が低下します。尿比重が一律に上昇する変化として捉えません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"老化による尿の生成と排尿機能の変化はどれか。","choices":["排尿回数の減少","膀胱容量の増加","夜間尿量の減少","残尿量の増加","尿比重の上昇"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":84,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[31],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A084"},"exam":112,"year":2023,"session":"AM","number":84},"sources":[]},{"id":"112-AM-085","record":{"id":"112-AM-085","choice_explanations":[{"choice":1,"correct":false,"title":"BCG 接種前にツベルクリン反応を実施する。","explanation":"定期のBCG接種前にツベルクリン反応を一律に行う制度ではありません。接種対象や禁忌を確認します。"},{"choice":2,"correct":false,"title":"ロタウイルスワクチンは不活化ワクチンである。","explanation":"ロタウイルスワクチンは経口の生ワクチンです。不活化ワクチンではありません。"},{"choice":3,"correct":false,"title":"ポリオウイルスワクチンの定期接種は廃止された。","explanation":"ポリオの定期予防接種は継続されています。経口生ワクチンから不活化ワクチンへ変わったことと廃止を区別します。"},{"choice":4,"correct":false,"title":"麻疹ウイルスワクチンは就学までに4回接種する。","explanation":"麻疹は通常、麻疹風疹混合ワクチンによる2回接種です。就学までに4回という説明ではありません。"},{"choice":5,"correct":true,"title":"ヒトパピローマウイルス〈HPV〉ワクチンは筋肉内注射する。","explanation":"HPVワクチンは筋肉内注射します。製剤、開始年齢、接種歴により接種回数等を確認します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"定期予防接種について正しいのはどれか。","choices":["BCG 接種前にツベルクリン反応を実施する。","ロタウイルスワクチンは不活化ワクチンである。","ポリオウイルスワクチンの定期接種は廃止された。","麻疹ウイルスワクチンは就学までに4回接種する。","ヒトパピローマウイルス〈HPV〉ワクチンは筋肉内注射する。"],"correct_answers":[5],"accepted_answer_sets":[[5]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":85,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[31],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A085"},"exam":112,"year":2023,"session":"AM","number":85},"sources":[]},{"id":"112-AM-086","record":{"id":"112-AM-086","choice_explanations":[{"choice":1,"correct":false,"title":"眼球が突出する。","explanation":"眼球突出は甲状腺眼症などでみられます。緑内障の中心的な病変ではありません。"},{"choice":2,"correct":true,"title":"視神経が萎縮する。","explanation":"視神経が障害され、視野が欠けていきます。失われた視機能の回復が難しいため進行予防が重要です。"},{"choice":3,"correct":false,"title":"硝子体が混濁する。","explanation":"硝子体混濁は硝子体の病変です。緑内障で主に障害されるのは視神経です。"},{"choice":4,"correct":false,"title":"眼底に出血がみられる。","explanation":"視神経乳頭出血を伴う場合はありますが、眼底出血は緑内障全体を特徴づける主要所見としては選びません。"},{"choice":5,"correct":true,"title":"眼圧の上昇が原因となる。","explanation":"眼圧上昇は視神経障害の重要な要因です。ただし、正常範囲の眼圧でも発症する正常眼圧緑内障があります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"緑内障について正しいのはどれか。2つ選べ。\nglaucoma","choices":["眼球が突出する。","視神経が萎縮する。","硝子体が混濁する。","眼底に出血がみられる。","眼圧の上昇が原因となる。"],"correct_answers":[2,5],"accepted_answer_sets":[[2,5]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":86,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[31],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A086"},"exam":112,"year":2023,"session":"AM","number":86},"sources":[]},{"id":"112-AM-087","record":{"id":"112-AM-087","choice_explanations":[{"choice":1,"correct":false,"title":"骨量の減少","explanation":"骨量減少は骨折リスクなどに関わります。体内の水分貯蔵量低下を直接示す選択肢は筋肉量と細胞内液量です。"},{"choice":2,"correct":true,"title":"筋肉量の減少","explanation":"筋肉は水分を多く含みます。筋肉量が減ると体内に保持できる水分量が少なくなります。"},{"choice":3,"correct":true,"title":"細胞内液量の減少","explanation":"細胞内液量が減ると体内の水分予備量が小さくなり、水分不足の影響を受けやすくなります。"},{"choice":4,"correct":false,"title":"渇中枢の感受性の亢進","explanation":"高齢者では口渇を感じる反応が鈍くなることが問題です。感受性の亢進という説明は逆です。"},{"choice":5,"correct":false,"title":"抗利尿ホルモンの反応性の亢進","explanation":"抗利尿作用への腎臓の反応低下などが水分保持を難しくします。反応性の亢進を脱水の要因とはしません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"高齢者に脱水が起こりやすくなる要因はどれか。2つ選べ。","choices":["骨量の減少","筋肉量の減少","細胞内液量の減少","渇中枢の感受性の亢進","抗利尿ホルモンの反応性の亢進"],"correct_answers":[2,3],"accepted_answer_sets":[[2,3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":87,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[32],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A087"},"exam":112,"year":2023,"session":"AM","number":87},"sources":[]},{"id":"112-AM-088","record":{"id":"112-AM-088","choice_explanations":[{"choice":1,"correct":true,"title":"応急入院は 72 時間以内に限られている。","explanation":"応急入院は、必要な同意を直ちに得られない緊急の状況などで行う72時間以内の入院です。"},{"choice":2,"correct":false,"title":"緊急措置入院中の患者は本人と家族が希望すれば退院できる。","explanation":"緊急措置入院は自傷他害のおそれなどを要件とする行政による入院です。本人・家族の希望だけで解除されません。"},{"choice":3,"correct":true,"title":"措置入院中の患者は精神医療審査会へ退院請求を申し出ることができる。","explanation":"退院等を求める権利があります。法上の請求先は都道府県知事で、精神医療審査会が審査する仕組みとして理解します。"},{"choice":4,"correct":false,"title":"精神保健指定医は任意入院中の患者について入院継続を必要と判断しても、\n退院を制限できない。","explanation":"任意入院でも指定医が必要と判断した場合、法律に基づき72時間を限度に退院を制限できる場合があります。"},{"choice":5,"correct":false,"title":"医療保護入院のためには入院の必要性に関する2名の精神保健指定医の一致\nした判断が必要である。","explanation":"2名の指定医の判断の一致が必要なのは通常の措置入院です。医療保護入院の要件とは異なります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"精神保健及び精神障害者福祉に関する法律〈精神保健福祉法〉に基づく入院形態で\n正しいのはどれか。2つ選べ。","choices":["応急入院は 72 時間以内に限られている。","緊急措置入院中の患者は本人と家族が希望すれば退院できる。","措置入院中の患者は精神医療審査会へ退院請求を申し出ることができる。","精神保健指定医は任意入院中の患者について入院継続を必要と判断しても、\n退院を制限できない。","医療保護入院のためには入院の必要性に関する2名の精神保健指定医の一致\nした判断が必要である。"],"correct_answers":[1,3],"accepted_answer_sets":[[1,3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":88,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[32],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A088"},"exam":112,"year":2023,"session":"AM","number":88},"sources":[]},{"id":"112-AM-089","record":{"id":"112-AM-089","choice_explanations":[{"choice":1,"correct":false,"title":"在宅療養には適用できない。","explanation":"在宅療養や地域連携にもパスを活用できます。入院中にしか使えない仕組みではありません。"},{"choice":2,"correct":true,"title":"医療者と患者が治療計画を共有できる。","explanation":"予定する検査・治療・ケアや目標を示すことで、患者と医療者が見通しを共有できます。"},{"choice":3,"correct":false,"title":"バリアンス発生の判断は退院日に行う。","explanation":"予定と異なる経過は生じた時点で把握して評価します。退院日まで判断を待ちません。"},{"choice":4,"correct":false,"title":"多職種間のコミュニケーションが不要になる。","explanation":"パスは情報共有を支えますが、相談や連携を不要にはしません。患者の変化に合わせた調整が必要です。"},{"choice":5,"correct":true,"title":"一定の質を保った治療と看護ケアの提供につながる。","explanation":"標準的な経過とケアを共有することで質のばらつきを減らせます。個別性に応じた変更も行います。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"クリニカルパスについて正しいのはどれか。2つ選べ。","choices":["在宅療養には適用できない。","医療者と患者が治療計画を共有できる。","バリアンス発生の判断は退院日に行う。","多職種間のコミュニケーションが不要になる。","一定の質を保った治療と看護ケアの提供につながる。"],"correct_answers":[2,5],"accepted_answer_sets":[[2,5]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":89,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[32],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A089"},"exam":112,"year":2023,"session":"AM","number":89},"sources":[]},{"id":"112-AM-090","record":{"id":"112-AM-090","choice_explanations":[{"choice":1,"correct":true,"title":"褥瘡発生率","explanation":"褥瘡がどれだけ発生したかはケアの結果を示す指標です。患者のリスクなども考慮して評価します。"},{"choice":2,"correct":true,"title":"患者の満足度","explanation":"患者が受けたケアをどう評価したかはアウトカムの一つです。患者の経験や期待も踏まえて把握します。"},{"choice":3,"correct":false,"title":"研修会の開催回数","explanation":"研修の開催回数は教育活動の実施量です。患者への看護の結果を直接示しません。"},{"choice":4,"correct":false,"title":"新人看護師の離職率","explanation":"離職率は人材管理上の指標です。本問の患者に対する看護アウトカムとしては発生率や満足度を選びます。"},{"choice":5,"correct":false,"title":"退院指導の実施回数","explanation":"指導回数は行った行為の量を示すプロセス指標です。理解や自己管理の変化が結果に当たります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"看護のアウトカムを評価するために収集する情報はどれか。2つ選べ。","choices":["褥瘡発生率","患者の満足度","研修会の開催回数","新人看護師の離職率","退院指導の実施回数"],"correct_answers":[1,2],"accepted_answer_sets":[[1,2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":90,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[33],"case_pages":[],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A090"},"exam":112,"year":2023,"session":"AM","number":90},"sources":[]},{"id":"112-AM-091","record":{"id":"112-AM-091","choice_explanations":[{"choice":1,"correct":true,"title":"尿 量","explanation":"移植腎から尿が出ているかは腎血流と機能を把握する重要な指標です。術直後は尿量の推移と水分出納を注意してみます。"},{"choice":2,"correct":false,"title":"血糖値","explanation":"免疫抑制薬などによる高血糖にも注意しますが、直後の移植腎機能の把握には尿量を優先します。"},{"choice":3,"correct":false,"title":"白血球数","explanation":"感染等の評価に用いますが、手術侵襲でも変化します。移植腎の働きを直ちに示す尿量が優先されます。"},{"choice":4,"correct":false,"title":"シャント音","explanation":"透析用シャントの開存確認も必要ですが、移植直後に最も優先するのは移植腎の機能評価です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんの手術直後に観察すべき項目で優先度が高いのはどれか。","choices":["尿 量","血糖値","白血球数","シャント音"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":"A さん(47 歳、男性、会社員)は妻と2人暮らしで、自宅の室内で犬を飼っている。\n15 年前に慢性糸球体腎炎と診断され、徐々に腎機能低下が認められたので、2年前\nchronic glomerulonephritis\nから慢性腎不全のため血液透析療法を週3回受けている。今回、弟から腎臓の提供の\nchronic renal failure\n申し出があり、生体腎移植の目的で入院した。入院3日、A さんの生体腎移植手術\nは予定通り終了した。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":91,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[34],"case_pages":[34],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A091"},"exam":112,"year":2023,"session":"AM","number":91},"sources":[]},{"id":"112-AM-092","record":{"id":"112-AM-092","choice_explanations":[{"choice":1,"correct":false,"title":"｢犬は今まで通り室内で飼育できます｣","explanation":"動物との接触には感染への配慮が必要です。従来通りでよいと一律に説明せず、排泄物の処理や衛生管理を相談します。"},{"choice":2,"correct":true,"title":"｢グレープフルーツは摂取しないでください｣","explanation":"グレープフルーツはタクロリムスの代謝に影響し、血中濃度を上げるおそれがあります。摂取を避けます。"},{"choice":3,"correct":false,"title":"｢感染予防のため風疹のワクチン接種をしてください｣","explanation":"風疹ワクチンは生ワクチンです。免疫抑制療法中に自己判断で接種せず、移植担当医に確認します。"},{"choice":4,"correct":false,"title":"｢薬を飲み忘れたときは2回分をまとめて服用してください｣","explanation":"2回分をまとめると過量になるおそれがあります。飲み忘れ時は処方時の指示に従い、不明なら医療機関へ確認します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんは術前からタクロリムスなど複数の免疫抑制薬を服用している。A さん\nは｢移植したら免疫抑制薬を飲む必要があることは分かっているのですが、退院後\nは何に気を付ければよいですか｣と看護師に質問した。\nA さんへの看護師の説明で適切なのはどれか。","choices":["｢犬は今まで通り室内で飼育できます｣","｢グレープフルーツは摂取しないでください｣","｢感染予防のため風疹のワクチン接種をしてください｣","｢薬を飲み忘れたときは2回分をまとめて服用してください｣"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(47 歳、男性、会社員)は妻と2人暮らしで、自宅の室内で犬を飼っている。\n15 年前に慢性糸球体腎炎と診断され、徐々に腎機能低下が認められたので、2年前\nchronic glomerulonephritis\nから慢性腎不全のため血液透析療法を週3回受けている。今回、弟から腎臓の提供の\nchronic renal failure\n申し出があり、生体腎移植の目的で入院した。入院3日、A さんの生体腎移植手術\nは予定通り終了した。","preceding_context":[{"id":"112-AM-091","question":"A さんの手術直後に観察すべき項目で優先度が高いのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":92,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[34],"case_pages":[34],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A092"},"exam":112,"year":2023,"session":"AM","number":92},"sources":[{"title":"PMDA：プログラフカプセル添付文書","url":"https://www.pmda.go.jp/PmdaSearch/iyakuDetail/800126_3999014M1022_3_42"}]},{"id":"112-AM-093","record":{"id":"112-AM-093","choice_explanations":[{"choice":1,"correct":false,"title":"蛋白質の摂取制限","explanation":"移植後の腎機能や栄養状態に応じて調整します。移植前と同じ制限を一律に続けるとは限りません。"},{"choice":2,"correct":false,"title":"週3回の通院","explanation":"移植腎が機能すれば週3回の血液透析通院は通常不要になります。ただし定期的な移植後の通院は必要です。"},{"choice":3,"correct":false,"title":"水分の制限","explanation":"機能が回復した移植腎では適切な水分補給が必要です。透析中と同じ水分制限を一律に継続しません。"},{"choice":4,"correct":true,"title":"体重の管理","explanation":"肥満や体液量の変化を把握し、移植腎と全身の健康を保つために体重管理を継続します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんは順調に回復し、移植後の拒絶反応もなく退院することになった。A さ\nんは｢腎臓が悪くなってから気を付けないといけないことが多かったのですが、移\n植してこれまでの制約がなくなりますね｣と話した。\nA さんの退院後の生活で継続が必要なのはどれか。","choices":["蛋白質の摂取制限","週3回の通院","水分の制限","体重の管理"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A さん(47 歳、男性、会社員)は妻と2人暮らしで、自宅の室内で犬を飼っている。\n15 年前に慢性糸球体腎炎と診断され、徐々に腎機能低下が認められたので、2年前\nchronic glomerulonephritis\nから慢性腎不全のため血液透析療法を週3回受けている。今回、弟から腎臓の提供の\nchronic renal failure\n申し出があり、生体腎移植の目的で入院した。入院3日、A さんの生体腎移植手術\nは予定通り終了した。","preceding_context":[{"id":"112-AM-091","question":"A さんの手術直後に観察すべき項目で優先度が高いのはどれか。"},{"id":"112-AM-092","question":"A さんは術前からタクロリムスなど複数の免疫抑制薬を服用している。A さん\nは｢移植したら免疫抑制薬を飲む必要があることは分かっているのですが、退院後\nは何に気を付ければよいですか｣と看護師に質問した。\nA さんへの看護師の説明で適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":93,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[35],"case_pages":[34],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A093"},"exam":112,"year":2023,"session":"AM","number":93},"sources":[]},{"id":"112-AM-094","record":{"id":"112-AM-094","choice_explanations":[{"choice":1,"correct":false,"title":"心膜炎\npericarditis","explanation":"心膜炎を示す胸痛や心電図等の所見は提示されていません。貧血と直接クームス試験陽性が判断の手掛かりです。"},{"choice":2,"correct":true,"title":"溶血性貧血\nhemolytic anemia","explanation":"Hb低下に加え直接クームス試験陽性で、赤血球に対する自己抗体による溶血性貧血が考えられます。"},{"choice":3,"correct":false,"title":"ループス腎炎\nlupus nephritis","explanation":"尿蛋白・尿潜血が陰性で、腎機能値にも明らかな異常がありません。提示所見から最も疑う病変ではありません。"},{"choice":4,"correct":false,"title":"中枢神経ループス\ncentral nervous system lupus","explanation":"神経学的検査に異常がありません。中枢神経症状を示す情報より、血液所見が貧血を示しています。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんに生じている可能性が高いのはどれか。","choices":["心膜炎\npericarditis","溶血性貧血\nhemolytic anemia","ループス腎炎\nlupus nephritis","中枢神経ループス\ncentral nervous system lupus"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(28 歳、女性、美容師)はゴルフが趣味である。同居しているパートナーと\n1週前にゴルフに行った後から、顔面の紅斑、微熱、全身倦怠感および手指の関節痛\nが現れた。病院を受診したところ、全身性エリテマトーデス〈SLE〉と診断され入院し\nsystemic lupus erythematosus\nた。A さんは看護師に｢これまで病気をしたことがなかったので、驚いています｣と\n話した。\nバイタルサイン：体温 37.4 ℃、呼吸数 18/分、脈拍 64/分、整、血圧 110/60 mmHg。\n血液所見：赤血球 260 万/μL、Hb 9.0 g/dL、白血球 7,600/μL、血小板 18 万/μL、尿\n素窒素 16 mg/dL、クレアチニン 0.8 mg/dL、CRP 0.7 mg/dL、直接\nCoombs〈クームス〉試験陽性。\n尿所見：尿蛋白(−)、尿潜血(−)。\n神経学的検査：異常所見なし。\n12 誘導心電図：異常所見なし。\n胸部エックス線写真：異常所見なし。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":94,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[36],"case_pages":[36],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A094"},"exam":112,"year":2023,"session":"AM","number":94},"sources":[]},{"id":"112-AM-095","record":{"id":"112-AM-095","choice_explanations":[{"choice":1,"correct":false,"title":"気にする必要はないと励ます。","explanation":"本人が感じるつらさを否定する言葉になり得ます。外見の変化への思いを受け止めて説明します。"},{"choice":2,"correct":false,"title":"パートナーの面会を制限する。","explanation":"本人の希望を確認せず面会を制限すると、支えを失う可能性があります。治療上の根拠もありません。"},{"choice":3,"correct":false,"title":"外見よりも病気の治療を優先すると説明する。","explanation":"外見への悩みも療養上の大切な問題です。治療を理由に気持ちを軽視しません。"},{"choice":4,"correct":true,"title":"薬の量が減れば満月様顔貌は軽減すると説明する。","explanation":"ステロイドによる満月様顔貌は減量に伴い軽減が期待できます。自己判断で減薬しないことも併せて伝えます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんはステロイドパルス療法の後、副腎皮質ステロイド薬の内服治療が開始\nされた。入院3週ころから満月様顔貌がみられたため、外見の変化に気持ちが落ち\n込むようになった。\nA さんへの対応で適切なのはどれか。","choices":["気にする必要はないと励ます。","パートナーの面会を制限する。","外見よりも病気の治療を優先すると説明する。","薬の量が減れば満月様顔貌は軽減すると説明する。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A さん(28 歳、女性、美容師)はゴルフが趣味である。同居しているパートナーと\n1週前にゴルフに行った後から、顔面の紅斑、微熱、全身倦怠感および手指の関節痛\nが現れた。病院を受診したところ、全身性エリテマトーデス〈SLE〉と診断され入院し\nsystemic lupus erythematosus\nた。A さんは看護師に｢これまで病気をしたことがなかったので、驚いています｣と\n話した。\nバイタルサイン：体温 37.4 ℃、呼吸数 18/分、脈拍 64/分、整、血圧 110/60 mmHg。\n血液所見：赤血球 260 万/μL、Hb 9.0 g/dL、白血球 7,600/μL、血小板 18 万/μL、尿\n素窒素 16 mg/dL、クレアチニン 0.8 mg/dL、CRP 0.7 mg/dL、直接\nCoombs〈クームス〉試験陽性。\n尿所見：尿蛋白(−)、尿潜血(−)。\n神経学的検査：異常所見なし。\n12 誘導心電図：異常所見なし。\n胸部エックス線写真：異常所見なし。","preceding_context":[{"id":"112-AM-094","question":"A さんに生じている可能性が高いのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":95,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[37],"case_pages":[36],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A095"},"exam":112,"year":2023,"session":"AM","number":95},"sources":[]},{"id":"112-AM-096","record":{"id":"112-AM-096","choice_explanations":[{"choice":1,"correct":false,"title":"｢すぐに復職できます｣","explanation":"活動性、疲労、仕事内容を評価して復職を調整します。退院直後から一律に復職可能とは説明しません。"},{"choice":2,"correct":false,"title":"｢避妊は必要ありません｣","explanation":"病状や薬剤が妊娠に影響するため、妊娠時期と避妊を医師と相談します。避妊不要とは説明しません。"},{"choice":3,"correct":true,"title":"｢身体を冷やさないでください｣","explanation":"寒冷で末梢循環障害やレイノー症状が誘発されることがあります。保温し、過度な冷えを避けます。"},{"choice":4,"correct":false,"title":"｢くもりなら屋外でゴルフができます｣","explanation":"曇天でも紫外線は届きます。紫外線による悪化を防ぐ対策と活動量の調整が必要です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんは外来で副腎皮質ステロイド薬の内服治療を継続することになった。A\nさんは｢病気を悪化させないために退院後はどのような生活がよいでしょうか｣と看\n護師に質問した。\nA さんへの退院指導で適切なのはどれか。","choices":["｢すぐに復職できます｣","｢避妊は必要ありません｣","｢身体を冷やさないでください｣","｢くもりなら屋外でゴルフができます｣"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A さん(28 歳、女性、美容師)はゴルフが趣味である。同居しているパートナーと\n1週前にゴルフに行った後から、顔面の紅斑、微熱、全身倦怠感および手指の関節痛\nが現れた。病院を受診したところ、全身性エリテマトーデス〈SLE〉と診断され入院し\nsystemic lupus erythematosus\nた。A さんは看護師に｢これまで病気をしたことがなかったので、驚いています｣と\n話した。\nバイタルサイン：体温 37.4 ℃、呼吸数 18/分、脈拍 64/分、整、血圧 110/60 mmHg。\n血液所見：赤血球 260 万/μL、Hb 9.0 g/dL、白血球 7,600/μL、血小板 18 万/μL、尿\n素窒素 16 mg/dL、クレアチニン 0.8 mg/dL、CRP 0.7 mg/dL、直接\nCoombs〈クームス〉試験陽性。\n尿所見：尿蛋白(−)、尿潜血(−)。\n神経学的検査：異常所見なし。\n12 誘導心電図：異常所見なし。\n胸部エックス線写真：異常所見なし。","preceding_context":[{"id":"112-AM-094","question":"A さんに生じている可能性が高いのはどれか。"},{"id":"112-AM-095","question":"A さんはステロイドパルス療法の後、副腎皮質ステロイド薬の内服治療が開始\nされた。入院3週ころから満月様顔貌がみられたため、外見の変化に気持ちが落ち\n込むようになった。\nA さんへの対応で適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":96,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[37],"case_pages":[36],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A096"},"exam":112,"year":2023,"session":"AM","number":96},"sources":[]},{"id":"112-AM-097","record":{"id":"112-AM-097","choice_explanations":[{"choice":1,"correct":false,"title":"耳元で大きな声で説明する。","explanation":"補聴器使用中に耳元で大声を出すと、音がひずみ不快になることがあります。正面から明瞭に話します。"},{"choice":2,"correct":false,"title":"A さんの身体に触れてから話しかける。","explanation":"突然体に触れると驚かせる可能性があります。まず存在を知らせ、本人の注意を向けてから説明します。"},{"choice":3,"correct":false,"title":"窓際の明るい場所でパンフレットを見せる。","explanation":"羞明があるため強い光や逆光は見づらさを増します。まぶしさを避け、読みやすい照明を調整します。"},{"choice":4,"correct":true,"title":"手術後の注意点はパンフレットに赤色の太い文字で書く。","explanation":"大きく太い文字で重要点を目立たせます。色だけに頼らず、本人に読めるか確認して口頭説明も組み合わせます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"入院当日、病棟の看護師が A さんに対してパンフレットを用いて手術前オリエ\nンテーションを行うことになった。\nA さんへのオリエンテーションの方法で適切なのはどれか。","choices":["耳元で大きな声で説明する。","A さんの身体に触れてから話しかける。","窓際の明るい場所でパンフレットを見せる。","手術後の注意点はパンフレットに赤色の太い文字で書く。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A さん(81 歳、女性)は夫(86 歳)と2人で暮らしている。高血圧症で内服治療をし\nhypertension\nて い る が、血 圧 の コ ン ト ロ ー ル は で き て い る。両 眼 に 老人性白内障 が あ り、\nsenile cataract\n老人性難聴のために補聴器を使用している。認知機能は問題なく、日常生活動作\npresbyacusis\n〈ADL〉はほぼ自立している。1年前から両眼の羞明、霧視が強くなり、視力が低下\nして趣味の編み物ができなくなってきた。また、家の中を移動するときに小さな段差\nにつまずいたりドアにぶつかるなど、歩行時の転倒の危険性が増えた。A さんは自\n宅での生活を安全に送りたい、趣味を続けたいという希望があり、10 日間程度の入\n院で両眼の超音波水晶体乳化吸引術と眼内レンズ挿入術を行うことになった。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":97,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[38],"case_pages":[38],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A097"},"exam":112,"year":2023,"session":"AM","number":97},"sources":[]},{"id":"112-AM-098","record":{"id":"112-AM-098","choice_explanations":[{"choice":1,"correct":false,"title":"手術直後から点眼する。","explanation":"点眼の開始時期は術後の指示を確認します。直後から患者が自己判断で開始するとは説明しません。"},{"choice":2,"correct":false,"title":"洗顔は手術の翌日から行う。","explanation":"眼への汚染や刺激を避ける必要があり、洗顔再開は指示に従います。翌日から一律に可能とはしません。"},{"choice":3,"correct":false,"title":"手術後 24 時間はベッド上で安静にする。","explanation":"経過が安定していれば一律に24時間の床上安静は必要ありません。許可された範囲で活動します。"},{"choice":4,"correct":true,"title":"医師の許可があるまでは頭を振る動作をしない。","explanation":"眼への衝撃や負担を避け、頭を激しく振る動作は控えます。具体的な活動制限と解除時期は術後指示を確認します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんの手術は局所麻酔下で行われ、10 分程度で終了した。手術中および手術\n直後のバイタルサインに問題はなく、病室に戻ってきた。A さんは眼痛や頭痛、\n気分不快などの症状はなく、｢無事に終わって良かった｣と話している。\n手術後の A さんへの説明で適切なのはどれか。","choices":["手術直後から点眼する。","洗顔は手術の翌日から行う。","手術後 24 時間はベッド上で安静にする。","医師の許可があるまでは頭を振る動作をしない。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A さん(81 歳、女性)は夫(86 歳)と2人で暮らしている。高血圧症で内服治療をし\nhypertension\nて い る が、血 圧 の コ ン ト ロ ー ル は で き て い る。両 眼 に 老人性白内障 が あ り、\nsenile cataract\n老人性難聴のために補聴器を使用している。認知機能は問題なく、日常生活動作\npresbyacusis\n〈ADL〉はほぼ自立している。1年前から両眼の羞明、霧視が強くなり、視力が低下\nして趣味の編み物ができなくなってきた。また、家の中を移動するときに小さな段差\nにつまずいたりドアにぶつかるなど、歩行時の転倒の危険性が増えた。A さんは自\n宅での生活を安全に送りたい、趣味を続けたいという希望があり、10 日間程度の入\n院で両眼の超音波水晶体乳化吸引術と眼内レンズ挿入術を行うことになった。","preceding_context":[{"id":"112-AM-097","question":"入院当日、病棟の看護師が A さんに対してパンフレットを用いて手術前オリエ\nンテーションを行うことになった。\nA さんへのオリエンテーションの方法で適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":98,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[38],"case_pages":[38],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A098"},"exam":112,"year":2023,"session":"AM","number":98},"sources":[]},{"id":"112-AM-099","record":{"id":"112-AM-099","choice_explanations":[{"choice":1,"correct":false,"title":"寝る前に温かい緑茶を飲むことを勧める。","explanation":"緑茶にはカフェインが含まれ、入眠を妨げる可能性があります。就寝前の飲み物は内容を選びます。"},{"choice":2,"correct":true,"title":"日中はベッドから離れて過ごすことを促す。","explanation":"日中の臥床を減らし、許可範囲で活動すると昼夜のリズムを整えられます。転倒にも注意します。"},{"choice":3,"correct":false,"title":"眠れなくてもベッドに横になっていることを勧める。","explanation":"長時間の臥床は昼夜の区別を弱めることがあります。眠れない原因や日中の過ごし方を評価します。"},{"choice":4,"correct":false,"title":"夜はよく眠っているので様子をみましょうと伝える。","explanation":"看護師の観察だけで不眠の訴えを否定しません。睡眠の質や困り事を本人に確認します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"手術後2日、A さんは日中はベッドに横になって過ごしている時間が多い。夜\n間に A さんから看護師に｢手術後はゆっくり眠れていません。どうしたらよいで\nしょうか｣という訴えがあった。\nA さんへの看護師の対応で適切なのはどれか。","choices":["寝る前に温かい緑茶を飲むことを勧める。","日中はベッドから離れて過ごすことを促す。","眠れなくてもベッドに横になっていることを勧める。","夜はよく眠っているので様子をみましょうと伝える。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(81 歳、女性)は夫(86 歳)と2人で暮らしている。高血圧症で内服治療をし\nhypertension\nて い る が、血 圧 の コ ン ト ロ ー ル は で き て い る。両 眼 に 老人性白内障 が あ り、\nsenile cataract\n老人性難聴のために補聴器を使用している。認知機能は問題なく、日常生活動作\npresbyacusis\n〈ADL〉はほぼ自立している。1年前から両眼の羞明、霧視が強くなり、視力が低下\nして趣味の編み物ができなくなってきた。また、家の中を移動するときに小さな段差\nにつまずいたりドアにぶつかるなど、歩行時の転倒の危険性が増えた。A さんは自\n宅での生活を安全に送りたい、趣味を続けたいという希望があり、10 日間程度の入\n院で両眼の超音波水晶体乳化吸引術と眼内レンズ挿入術を行うことになった。","preceding_context":[{"id":"112-AM-097","question":"入院当日、病棟の看護師が A さんに対してパンフレットを用いて手術前オリエ\nンテーションを行うことになった。\nA さんへのオリエンテーションの方法で適切なのはどれか。"},{"id":"112-AM-098","question":"A さんの手術は局所麻酔下で行われ、10 分程度で終了した。手術中および手術\n直後のバイタルサインに問題はなく、病室に戻ってきた。A さんは眼痛や頭痛、\n気分不快などの症状はなく、｢無事に終わって良かった｣と話している。\n手術後の A さんへの説明で適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":99,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[39],"case_pages":[38],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A099"},"exam":112,"year":2023,"session":"AM","number":99},"sources":[]},{"id":"112-AM-100","record":{"id":"112-AM-100","choice_explanations":[{"choice":1,"correct":false,"title":"頸部を後屈した体位にする。","explanation":"頸部の過伸展は嚥下しづらさや誤嚥につながります。嚥下状態に合う頭頸部の位置を整えます。"},{"choice":2,"correct":true,"title":"座位時の体幹を安定させる。","explanation":"姿勢が崩れているため、足底や体幹を支持して安定させます。食物を口へ運ぶ動作と嚥下を助けます。"},{"choice":3,"correct":false,"title":"食後に嚥下体操を実施する。","explanation":"嚥下体操は食前の準備として行うことがあります。本問ではまず食事中の姿勢の不安定さに対応します。"},{"choice":4,"correct":false,"title":"こぼさずに摂取できるよう全介助する。","explanation":"自力で食べる力が残っています。姿勢や食具を工夫し、必要な部分だけ介助して能力を生かします。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"看護師の A さんへの食事援助で正しいのはどれか。","choices":["頸部を後屈した体位にする。","座位時の体幹を安定させる。","食後に嚥下体操を実施する。","こぼさずに摂取できるよう全介助する。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さ ん (75 歳、男 性) は 妻 (75 歳) と 2 人 暮 ら し で、15 年 前 に\nParkinson〈パーキンソン〉病と診断された。7年前よりレボドパ〈L-dopa〉を1日3回\nParkinson disease\n内服している。Hoehn & Yahr〈ホーエン・ヤール〉重症度分類のステージⅣで、要介\n護2である。妻は腰痛のため毎日リハビリテーション目的で通院中である。妻の介護\n負担を軽減するため、A さんは毎月 10 日間、介護老人保健施設の短期入所〈ショー\nトステイ〉を利用している。今回は妻の腰痛が増強したため、A さんは予定を早めて\n入所した。A さんは握力が低下しているが、スプーンを使用し自力で食事を摂取し\nている。食事中に姿勢が崩れることが多く、むせや食べこぼしがある。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":100,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[40],"case_pages":[40],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A100"},"exam":112,"year":2023,"session":"AM","number":100},"sources":[]},{"id":"112-AM-101","record":{"id":"112-AM-101","choice_explanations":[{"choice":1,"correct":false,"title":"オンオフ現象","explanation":"オンオフ現象は服薬時刻と必ずしも対応しない急な変動です。本例は服薬後に改善し、時間とともに再発しています。"},{"choice":2,"correct":false,"title":"ジスキネジア","explanation":"ジスキネジアは不随意運動です。本例の薬効低下に伴う動作・発声の悪化とは異なります。"},{"choice":3,"correct":false,"title":"アナフィラキシー反応","explanation":"急性の重いアレルギー反応で、呼吸・循環症状などを生じます。服薬ごとに改善する本例の経過とは合いません。"},{"choice":4,"correct":true,"title":"ウェアリングオフ現象","explanation":"薬の効果が次の服薬前に切れ、症状が戻る現象です。服薬と症状の時刻を記録して治療調整につなげます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんは社交的で短期入所中はいつも介護老人保健施設の利用者や職員と笑顔\nで会話していたが、今回は、会話中に急に表情がなくなり声が聞きとれないほど小\nさくなったり、手足の震えが出現することがあった。食後に薬を内服すると症状は\n改善するが、内服して2時間後には同じような症状が現れることがあった。\nA さんの症状はどれか。","choices":["オンオフ現象","ジスキネジア","アナフィラキシー反応","ウェアリングオフ現象"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A さ ん (75 歳、男 性) は 妻 (75 歳) と 2 人 暮 ら し で、15 年 前 に\nParkinson〈パーキンソン〉病と診断された。7年前よりレボドパ〈L-dopa〉を1日3回\nParkinson disease\n内服している。Hoehn & Yahr〈ホーエン・ヤール〉重症度分類のステージⅣで、要介\n護2である。妻は腰痛のため毎日リハビリテーション目的で通院中である。妻の介護\n負担を軽減するため、A さんは毎月 10 日間、介護老人保健施設の短期入所〈ショー\nトステイ〉を利用している。今回は妻の腰痛が増強したため、A さんは予定を早めて\n入所した。A さんは握力が低下しているが、スプーンを使用し自力で食事を摂取し\nている。食事中に姿勢が崩れることが多く、むせや食べこぼしがある。","preceding_context":[{"id":"112-AM-100","question":"看護師の A さんへの食事援助で正しいのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":101,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[40],"case_pages":[40],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A101"},"exam":112,"year":2023,"session":"AM","number":101},"sources":[]},{"id":"112-AM-102","record":{"id":"112-AM-102","choice_explanations":[{"choice":1,"correct":false,"title":"｢毎日 30 分間の階段昇降を行いましょう｣","explanation":"重症度と転倒リスクを踏まえると、階段昇降を一律に30分続ける指導は危険です。安全な運動を個別に選びます。"},{"choice":2,"correct":true,"title":"｢歩行時に腕を大きく振りましょう｣","explanation":"腕の振りを意識し、歩行のリズムと動きを大きくする工夫です。本人の能力に応じ、必要なら介助下で練習します。"},{"choice":3,"correct":false,"title":"｢小刻みに歩くようにしましょう｣","explanation":"小刻み歩行はパーキンソン病で問題となる歩き方です。さらに小さく歩くよう促すのは適切ではありません。"},{"choice":4,"correct":false,"title":"｢毎日1km 歩きましょう｣","explanation":"距離を一律に指定せず、疲労と転倒リスクを評価します。短い安全な運動を継続できるよう調整します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"妻の腰痛が改善したため、A さんは自宅に戻ることになった。A さんは｢妻に負\n担をかけないように自分で動けるようになりたい。自宅でできる運動や注意するこ\nとを教えてください｣と看護師に話した。\nA さんへの指導で適切なのはどれか。","choices":["｢毎日 30 分間の階段昇降を行いましょう｣","｢歩行時に腕を大きく振りましょう｣","｢小刻みに歩くようにしましょう｣","｢毎日1km 歩きましょう｣"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さ ん (75 歳、男 性) は 妻 (75 歳) と 2 人 暮 ら し で、15 年 前 に\nParkinson〈パーキンソン〉病と診断された。7年前よりレボドパ〈L-dopa〉を1日3回\nParkinson disease\n内服している。Hoehn & Yahr〈ホーエン・ヤール〉重症度分類のステージⅣで、要介\n護2である。妻は腰痛のため毎日リハビリテーション目的で通院中である。妻の介護\n負担を軽減するため、A さんは毎月 10 日間、介護老人保健施設の短期入所〈ショー\nトステイ〉を利用している。今回は妻の腰痛が増強したため、A さんは予定を早めて\n入所した。A さんは握力が低下しているが、スプーンを使用し自力で食事を摂取し\nている。食事中に姿勢が崩れることが多く、むせや食べこぼしがある。","preceding_context":[{"id":"112-AM-100","question":"看護師の A さんへの食事援助で正しいのはどれか。"},{"id":"112-AM-101","question":"A さんは社交的で短期入所中はいつも介護老人保健施設の利用者や職員と笑顔\nで会話していたが、今回は、会話中に急に表情がなくなり声が聞きとれないほど小\nさくなったり、手足の震えが出現することがあった。食後に薬を内服すると症状は\n改善するが、内服して2時間後には同じような症状が現れることがあった。\nA さんの症状はどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":102,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[41],"case_pages":[40],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A102"},"exam":112,"year":2023,"session":"AM","number":102},"sources":[]},{"id":"112-AM-103","record":{"id":"112-AM-103","choice_explanations":[{"choice":1,"correct":false,"title":"γ-グロブリン製剤の投与中も A ちゃんと売店に行けると母親に伝える。","explanation":"投与開始時は急な副反応を観察する必要があります。売店への移動を安易に許可せず、観察できる環境を保ちます。"},{"choice":2,"correct":false,"title":"留置針の自己抜去防止のために右肘関節に抑制帯を使用する。","explanation":"予防的に反対側の肘を拘束する前に、説明や付き添い、安全な固定などの方法を検討します。"},{"choice":3,"correct":false,"title":"心負荷の軽減のために A ちゃんの経口水分摂取を制限する。","explanation":"心機能や水分出納の評価なしに経口水分を制限しません。発熱に伴う水分喪失にも注意します。"},{"choice":4,"correct":true,"title":"心電図モニターの装着を確認する。","explanation":"循環の変化や不整脈などを早期に把握するため、モニターが適切に装着されているか確認します。"},{"choice":5,"correct":true,"title":"留置針の刺入部を観察する。","explanation":"腫脹・発赤・漏れなどを確認し、安全に薬剤を投与できる静脈路か評価します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"γ-グロブリン療法の開始に伴う看護師の対応で適切なのはどれか。2つ選べ。","choices":["γ-グロブリン製剤の投与中も A ちゃんと売店に行けると母親に伝える。","留置針の自己抜去防止のために右肘関節に抑制帯を使用する。","心負荷の軽減のために A ちゃんの経口水分摂取を制限する。","心電図モニターの装着を確認する。","留置針の刺入部を観察する。"],"correct_answers":[4,5],"accepted_answer_sets":[[4,5]],"case_text":"A ちゃん(2歳、男児)は両親、兄(5歳)の4人家族である。3日前から発熱が続\nくため、母親と一緒に外来を受診した。診察の結果、川崎病と診断され、個室に入院\nKawasaki disease\nとなり左手背に点滴静脈内留置針が挿入された。入院中は母親が希望し、A ちゃん\nに付き添っている。A ちゃんに γ-グロブリン療法とアスピリンの内服が開始される\nことになった。看護師が γ-グロブリン療法の開始のために訪室すると、A ちゃんは\n不機嫌にぐずって泣いている。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":103,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[42],"case_pages":[42],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A103"},"exam":112,"year":2023,"session":"AM","number":103},"sources":[]},{"id":"112-AM-104","record":{"id":"112-AM-104","choice_explanations":[{"choice":1,"correct":false,"title":"病室内で A ちゃんと兄を面会させてよいと伝える。","explanation":"面会条件を確認せず病室面会を即座に認める対応ではありません。母親が兄と過ごせる支援を具体的に検討します。"},{"choice":2,"correct":false,"title":"A ちゃんのことに集中するべきであると伝える。","explanation":"兄の反応も家族全体の課題です。入院児だけに集中するよう求めると母親の心配を軽視します。"},{"choice":3,"correct":true,"title":"兄と関わる時間を持てるよう母親に帰宅を促す。","explanation":"病棟でのケアや付き添い交代を調整し、母親が兄と関わる時間を確保します。きょうだいへの支援も必要です。"},{"choice":4,"correct":false,"title":"退院の可否を医師と相談すると伝える。","explanation":"退院は児の病状と治療経過で判断します。まず母親が帰宅できる付き添い体制を検討します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A ちゃんの入院中、母親は一度も自宅に帰らずに付き添いを続けている。入院\n3日の朝に看護師が訪室したところ、母親が｢夫から電話があって、A の入院後、\n兄がほとんど寝ずに大泣きしているらしく、私は心配です｣と話している。\n母親への看護師の対応で適切なのはどれか。","choices":["病室内で A ちゃんと兄を面会させてよいと伝える。","A ちゃんのことに集中するべきであると伝える。","兄と関わる時間を持てるよう母親に帰宅を促す。","退院の可否を医師と相談すると伝える。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A ちゃん(2歳、男児)は両親、兄(5歳)の4人家族である。3日前から発熱が続\nくため、母親と一緒に外来を受診した。診察の結果、川崎病と診断され、個室に入院\nKawasaki disease\nとなり左手背に点滴静脈内留置針が挿入された。入院中は母親が希望し、A ちゃん\nに付き添っている。A ちゃんに γ-グロブリン療法とアスピリンの内服が開始される\nことになった。看護師が γ-グロブリン療法の開始のために訪室すると、A ちゃんは\n不機嫌にぐずって泣いている。","preceding_context":[{"id":"112-AM-103","question":"γ-グロブリン療法の開始に伴う看護師の対応で適切なのはどれか。2つ選べ。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":104,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[42],"case_pages":[42],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A104"},"exam":112,"year":2023,"session":"AM","number":104},"sources":[]},{"id":"112-AM-105","record":{"id":"112-AM-105","choice_explanations":[{"choice":1,"correct":false,"title":"γ-グロブリン療法の副作用(有害事象)である。","explanation":"解熱後の指先の膜様落屑は川崎病の回復期にみられます。この経過だけで薬剤の副作用とは判断しません。"},{"choice":2,"correct":false,"title":"皮膚のツルゴールが低下している。","explanation":"ツルゴールは皮膚の弾力をみる所見です。薄い膜状に皮膚がむける落屑とは異なります。"},{"choice":3,"correct":true,"title":"川崎病の回復期の症状である。\nKawasaki disease","explanation":"川崎病の回復期には指趾の先端から膜様に皮膚がむけることがあります。経過と合わせて評価します。"},{"choice":4,"correct":false,"title":"皮膚科の受診が必要である。","explanation":"典型的な回復期の所見であれば、直ちに皮膚科受診を必要とするわけではありません。非典型的な変化は相談します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"入院4日、A ちゃんは解熱し活気が出てきた。翌日、看護師が A ちゃんを観察\nすると、手指の先端から皮膚が膜のように薄くむけていた。\nこの所見に対する看護師のアセスメントで適切なのはどれか。","choices":["γ-グロブリン療法の副作用(有害事象)である。","皮膚のツルゴールが低下している。","川崎病の回復期の症状である。\nKawasaki disease","皮膚科の受診が必要である。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A ちゃん(2歳、男児)は両親、兄(5歳)の4人家族である。3日前から発熱が続\nくため、母親と一緒に外来を受診した。診察の結果、川崎病と診断され、個室に入院\nKawasaki disease\nとなり左手背に点滴静脈内留置針が挿入された。入院中は母親が希望し、A ちゃん\nに付き添っている。A ちゃんに γ-グロブリン療法とアスピリンの内服が開始される\nことになった。看護師が γ-グロブリン療法の開始のために訪室すると、A ちゃんは\n不機嫌にぐずって泣いている。","preceding_context":[{"id":"112-AM-103","question":"γ-グロブリン療法の開始に伴う看護師の対応で適切なのはどれか。2つ選べ。"},{"id":"112-AM-104","question":"A ちゃんの入院中、母親は一度も自宅に帰らずに付き添いを続けている。入院\n3日の朝に看護師が訪室したところ、母親が｢夫から電話があって、A の入院後、\n兄がほとんど寝ずに大泣きしているらしく、私は心配です｣と話している。\n母親への看護師の対応で適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":105,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[43],"case_pages":[42],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A105"},"exam":112,"year":2023,"session":"AM","number":105},"sources":[]},{"id":"112-AM-106","record":{"id":"112-AM-106","choice_explanations":[{"choice":1,"correct":false,"title":"経皮的動脈血酸素飽和度〈SpO2〉","explanation":"肺水腫などの重い副作用を疑う際には重要です。本問の開始直後に特に注目する頻脈の評価は脈拍です。"},{"choice":2,"correct":false,"title":"血 圧","explanation":"血圧変化も観察しますが、リトドリンの作用で起こりやすい動悸・頻脈を捉える項目が優先です。"},{"choice":3,"correct":false,"title":"呼吸数","explanation":"呼吸状態も継続観察します。呼吸困難が現れた場合には肺水腫などの評価が必要です。"},{"choice":4,"correct":true,"title":"脈 拍","explanation":"リトドリンのβ刺激作用により頻脈や動悸が起こり得ます。開始後の脈拍と自覚症状を確認します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"点滴を開始して 30 分後に看護師が訪室すると、A さんは Fowler〈ファウラー〉\n位で休んでいた。\nこのときの A さんの状態で看護師が注意して観察すべき項目はどれか。","choices":["経皮的動脈血酸素飽和度〈SpO2〉","血 圧","呼吸数","脈 拍"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A さん(33 歳、初産婦、会社員)は夫と2人で暮らしている。妊娠 28 週5日、夕方\nから下腹部に生理痛のような痛みを感じ、少量の性器出血があったため来院した。来\n院時、子宮口2cm 開大、未破水、8分おきに 20 秒持続する子宮収縮があり、\n切迫早産と診断された。子宮収縮抑制薬(リトドリン塩酸塩)の点滴静脈内注射と安静\nthreatened premature delivery\nによる治療が開始された。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":106,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[44],"case_pages":[44],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A106"},"exam":112,"year":2023,"session":"AM","number":106},"sources":[{"title":"PMDA：リトドリン塩酸塩点滴静注液添付文書","url":"https://www.pmda.go.jp/PmdaSearch/bookSearch/01/04987431202035"}]},{"id":"112-AM-107","record":{"id":"112-AM-107","choice_explanations":[{"choice":1,"correct":false,"title":"医師に報告する。","explanation":"報告は必要ですが、まず仰臥位による大血管の圧迫を軽減する体位変換を行います。"},{"choice":2,"correct":false,"title":"血圧測定を行う。","explanation":"血圧も速やかに確認しますが、原因と考えられる圧迫を取り除く対応を先に行えます。"},{"choice":3,"correct":true,"title":"左側臥位にする。","explanation":"増大した子宮による下大静脈圧迫を軽減し、静脈還流を改善します。妊娠後期の仰臥位低血圧を疑う場面です。"},{"choice":4,"correct":false,"title":"酸素吸入を行う。","explanation":"酸素化の評価に応じて実施します。まず体位を変えて循環障害の原因を軽減します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"切迫早産の症状がなくなり、A さんは妊娠 35 週0日で退院した。妊娠 36 週0\nthreatened premature delivery\n日に妊婦健康診査のために来院した。ノンストレステスト〈NST〉を実施中に、｢気\n分が悪い｣とナースコールがあり看護師が訪れると、A さんは仰臥位になってい\nた。\nA さんへの対応で看護師が最初に行うのはどれか。","choices":["医師に報告する。","血圧測定を行う。","左側臥位にする。","酸素吸入を行う。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A さん(33 歳、初産婦、会社員)は夫と2人で暮らしている。妊娠 28 週5日、夕方\nから下腹部に生理痛のような痛みを感じ、少量の性器出血があったため来院した。来\n院時、子宮口2cm 開大、未破水、8分おきに 20 秒持続する子宮収縮があり、\n切迫早産と診断された。子宮収縮抑制薬(リトドリン塩酸塩)の点滴静脈内注射と安静\nthreatened premature delivery\nによる治療が開始された。","preceding_context":[{"id":"112-AM-106","question":"点滴を開始して 30 分後に看護師が訪室すると、A さんは Fowler〈ファウラー〉\n位で休んでいた。\nこのときの A さんの状態で看護師が注意して観察すべき項目はどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":107,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[44],"case_pages":[44],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A107"},"exam":112,"year":2023,"session":"AM","number":107},"sources":[]},{"id":"112-AM-108","record":{"id":"112-AM-108","choice_explanations":[{"choice":1,"correct":true,"title":"早期産である。","explanation":"妊娠22週以降37週未満の出産は早産です。36週5日の出産はこの範囲に含まれます。"},{"choice":2,"correct":false,"title":"異常出血である。","explanation":"経腟分娩で350mLという量だけでは異常出血としません。出血量に加えて全身状態も評価します。"},{"choice":3,"correct":false,"title":"前期破水である。","explanation":"前期破水は陣痛開始前の破水です。本例は分娩開始後、子宮口全開大の後に破水しています。"},{"choice":4,"correct":false,"title":"新生児仮死である。","explanation":"1分後8点、5分後9点は、本問で新生児仮死と判断する値ではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんは妊娠 36 週5日、8時に分娩が開始した。16 時 30 分に子宮口全開大、\n16 時 35 分に自然破水、18 時 30 分に男児を出産した。分娩時出血量は 350 mL、児\nの Apgar〈アプガー〉スコアは1分後8点、5分後9点であった。\nA さんの分娩のアセスメントで適切なのはどれか。","choices":["早期産である。","異常出血である。","前期破水である。","新生児仮死である。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":"A さん(33 歳、初産婦、会社員)は夫と2人で暮らしている。妊娠 28 週5日、夕方\nから下腹部に生理痛のような痛みを感じ、少量の性器出血があったため来院した。来\n院時、子宮口2cm 開大、未破水、8分おきに 20 秒持続する子宮収縮があり、\n切迫早産と診断された。子宮収縮抑制薬(リトドリン塩酸塩)の点滴静脈内注射と安静\nthreatened premature delivery\nによる治療が開始された。","preceding_context":[{"id":"112-AM-106","question":"点滴を開始して 30 分後に看護師が訪室すると、A さんは Fowler〈ファウラー〉\n位で休んでいた。\nこのときの A さんの状態で看護師が注意して観察すべき項目はどれか。"},{"id":"112-AM-107","question":"切迫早産の症状がなくなり、A さんは妊娠 35 週0日で退院した。妊娠 36 週0\nthreatened premature delivery\n日に妊婦健康診査のために来院した。ノンストレステスト〈NST〉を実施中に、｢気\n分が悪い｣とナースコールがあり看護師が訪れると、A さんは仰臥位になってい\nた。\nA さんへの対応で看護師が最初に行うのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":108,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[45],"case_pages":[44],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A108"},"exam":112,"year":2023,"session":"AM","number":108},"sources":[]},{"id":"112-AM-112","record":{"id":"112-AM-112","choice_explanations":[{"choice":1,"correct":false,"title":"過量服薬した場面の振り返りを促す。","explanation":"振り返りは安全確保と状態の安定後に行います。最初は現在も自殺したい気持ちがあるかを確認します。"},{"choice":2,"correct":true,"title":"現在の希死念慮の有無について確認する。","explanation":"現在の希死念慮を直接、非難せずに確認し、再企図の危険と必要な見守りを評価します。"},{"choice":3,"correct":false,"title":"大量の睡眠薬を飲まずに残していた理由を追及する。","explanation":"追及する姿勢は関係を損ね、気持ちを話しにくくします。服薬状況は安全確保のため落ち着いて確認します。"},{"choice":4,"correct":false,"title":"A さんと看護師の間で二度と過量服薬しないと約束する。","explanation":"約束だけでは自殺を防ぐ手段になりません。危険性の評価、環境調整、継続した支援が必要です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんは救急外来で治療を受け会話ができるまでに回復した。\nA さんへの看護師の最初の対応で適切なのはどれか。","choices":["過量服薬した場面の振り返りを促す。","現在の希死念慮の有無について確認する。","大量の睡眠薬を飲まずに残していた理由を追及する。","A さんと看護師の間で二度と過量服薬しないと約束する。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(20 歳、女性)は境界性人格〈パーソナリティ〉障害の診断を受け、精神科外\nborderline personality disorder\n来に通院中である。ある日、人間関係のトラブルから処方されていた睡眠薬を過量服\n薬して自殺企図をしたところを家族に発見され、救命救急センターに搬送された。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":112,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[48],"case_pages":[48],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A112"},"exam":112,"year":2023,"session":"AM","number":112},"sources":[]},{"id":"112-AM-113","record":{"id":"112-AM-113","choice_explanations":[{"choice":1,"correct":true,"title":"ハサミの使用目的を聞く。","explanation":"まず何のために必要かを聴き、気持ちと状況を把握します。そのうえで安全上のルールに沿った代替方法を考えます。"},{"choice":2,"correct":false,"title":"看護師付き添いのもとハサミを貸し出す。","explanation":"夜間は貸し出さない指示があるため、付き添えばよいと独自に例外を作りません。"},{"choice":3,"correct":false,"title":"看護師 B が誤った対応をしたと説明する。","explanation":"他の看護師を批判して対立を深めません。事実を確認し、チームで一貫した対応を共有します。"},{"choice":4,"correct":false,"title":"A さんの行動が心配なので貸し出せないと伝える。","explanation":"心配だけを理由に拒否する前に、使用目的を確認します。本人の求めを理解したうえで制限の理由を説明します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんは身体的な治療を受けた後、精神科病棟に入院することになった。入院\n3日の 22 時、A さんがハサミを貸してほしいとナースステーションに来た。日勤\nの看護師がいる時間帯のみ付き添いでハサミの貸出が可能という主治医からの指示\nを伝えると｢看護師 B は貸してくれたのに。こんなひどい対応をする看護師はあな\nただけだ｣と話し、その場を動かない。\nこのときの A さんへの対応で適切なのはどれか。","choices":["ハサミの使用目的を聞く。","看護師付き添いのもとハサミを貸し出す。","看護師 B が誤った対応をしたと説明する。","A さんの行動が心配なので貸し出せないと伝える。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":"A さん(20 歳、女性)は境界性人格〈パーソナリティ〉障害の診断を受け、精神科外\nborderline personality disorder\n来に通院中である。ある日、人間関係のトラブルから処方されていた睡眠薬を過量服\n薬して自殺企図をしたところを家族に発見され、救命救急センターに搬送された。","preceding_context":[{"id":"112-AM-112","question":"A さんは救急外来で治療を受け会話ができるまでに回復した。\nA さんへの看護師の最初の対応で適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":113,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[48],"case_pages":[48],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A113"},"exam":112,"year":2023,"session":"AM","number":113},"sources":[]},{"id":"112-AM-114","record":{"id":"112-AM-114","choice_explanations":[{"choice":1,"correct":false,"title":"A さんと看護師が関わる頻度を減らす。","explanation":"単純に関わりを減らすと拒絶された感覚につながります。必要な支援と一貫した枠組みを保ちます。"},{"choice":2,"correct":false,"title":"A さんに共感を示す看護師に担当を固定する。","explanation":"共感する人だけに固定すると、スタッフ間の分裂を強める可能性があります。チーム全体で対応を整えます。"},{"choice":3,"correct":false,"title":"A さんに対する感情を看護師同士で表出しないように統一する。","explanation":"スタッフの感情を安全な場で共有し、対応への影響を振り返ることが必要です。表出を一律に禁止しません。"},{"choice":4,"correct":true,"title":"A さんの行動が患者−看護師関係にもたらす影響について評価する。","explanation":"本人とスタッフの相互作用を評価し、感情的な対立を避けた一貫性のある対応を検討します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"入院1週、A さんは看護師ごとに言動や態度を変えることが多く、病棟では A\nさんに対して共感を示す看護師と、拒否的な態度を示す看護師に分かれてしまっ\nた。そのため、病棟の看護師はチームでの対応についてカンファレンスを行った。\nA さんへの看護師のチームとしての対応で適切なのはどれか。","choices":["A さんと看護師が関わる頻度を減らす。","A さんに共感を示す看護師に担当を固定する。","A さんに対する感情を看護師同士で表出しないように統一する。","A さんの行動が患者−看護師関係にもたらす影響について評価する。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A さん(20 歳、女性)は境界性人格〈パーソナリティ〉障害の診断を受け、精神科外\nborderline personality disorder\n来に通院中である。ある日、人間関係のトラブルから処方されていた睡眠薬を過量服\n薬して自殺企図をしたところを家族に発見され、救命救急センターに搬送された。","preceding_context":[{"id":"112-AM-112","question":"A さんは救急外来で治療を受け会話ができるまでに回復した。\nA さんへの看護師の最初の対応で適切なのはどれか。"},{"id":"112-AM-113","question":"A さんは身体的な治療を受けた後、精神科病棟に入院することになった。入院\n3日の 22 時、A さんがハサミを貸してほしいとナースステーションに来た。日勤\nの看護師がいる時間帯のみ付き添いでハサミの貸出が可能という主治医からの指示\nを伝えると｢看護師 B は貸してくれたのに。こんなひどい対応をする看護師はあな\nただけだ｣と話し、その場を動かない。\nこのときの A さんへの対応で適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":114,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[49],"case_pages":[48],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A114"},"exam":112,"year":2023,"session":"AM","number":114},"sources":[]},{"id":"112-AM-115","record":{"id":"112-AM-115","choice_explanations":[{"choice":1,"correct":false,"title":"五十音の文字盤を用いて A ちゃんが指でさした文字を1文字ずつ読み取る。","explanation":"手指の細かな操作ができず、指さしを前提とする方法は本例に合いません。"},{"choice":2,"correct":false,"title":"視線で入力できる意思伝達装置を用いて A ちゃんに文字を入力してもらう。","explanation":"視線に誤動作があるため、現時点で最も確実な伝達方法とは限りません。適合評価が必要です。"},{"choice":3,"correct":true,"title":"閉じた質問〈closed question〉をして A ちゃんのまばたきの回数を確認する。","explanation":"確実にできるまばたきによる「はい・いいえ」を使い、短い閉じた質問で本人の意思を確認します。"},{"choice":4,"correct":false,"title":"感情を絵で表現したカードを見せて A ちゃんが指でさしたカードを確認す\nる。","explanation":"指さしが難しいため、カードを示すだけでは安定して回答できません。残存する運動機能を生かします。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"入学時に担任が A ちゃんの意思を確認する方法で最も適切なのはどれか。","choices":["五十音の文字盤を用いて A ちゃんが指でさした文字を1文字ずつ読み取る。","視線で入力できる意思伝達装置を用いて A ちゃんに文字を入力してもらう。","閉じた質問〈closed question〉をして A ちゃんのまばたきの回数を確認する。","感情を絵で表現したカードを見せて A ちゃんが指でさしたカードを確認す\nる。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A ちゃん(6歳、男児)は父親(50 歳、会社員)、母親(48 歳)、姉(11 歳)と4人で暮\nらしている。Duchenne〈デュシェンヌ〉型筋ジストロフィーで身体障害者手帳(肢体\nDuchenne muscular dystrophy\n不自由1級)が交付されている。喀痰吸引、胃瘻による経管栄養が必要で、訪問看護\nを週に2回利用している。まばたきの回数で｢はい｣と｢いいえ｣の意思表示はできる\nが、視線や上肢の動きには誤動作もあり、構音障害もあるため家族以外では意思の判\n断が難しい。また、手指での細かい操作はできない。A ちゃんは次年度から姉と同\nじ小学校の特別支援学級に通い、通常の学級の児童と交流の予定がある。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":115,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[50],"case_pages":[50],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A115"},"exam":112,"year":2023,"session":"AM","number":115},"sources":[]},{"id":"112-AM-116","record":{"id":"112-AM-116","choice_explanations":[{"choice":1,"correct":false,"title":"児童発達支援","explanation":"主に未就学児の発達支援です。本例の登校前の家庭内介助の負担を直接解決するサービスではありません。"},{"choice":2,"correct":true,"title":"重度訪問介護","explanation":"公式正答は重度訪問介護です。ただし原則の年齢要件と本例の6歳児への適用条件の整合は不明で、制度上の確認が必要です。"},{"choice":3,"correct":false,"title":"放課後等デイサービス","explanation":"放課後の支援であり、母親が訴える登校前の介助負担への直接の対応にはなりません。"},{"choice":4,"correct":false,"title":"短期入所〈ショートステイ〉","explanation":"家族の休息を支えますが、毎朝の在宅介助という本例の希望に直接対応する選択肢ではありません。"}],"status":"UNKNOWN","review_reason":"6歳児に対する重度訪問介護の年齢要件と適用の整合が未確定。公式正答2は維持し、例外適用を推測で説明しない。","fixes_made":[]},"input_anchor":{"question":"A ちゃんが小学校に入学して6か月が経過した。小学校への送迎は母親が行っ\nており、学内での喀痰吸引や経管栄養の注入は小学校に配置されている看護師が\n行っている。A ちゃんは体調も安定しており、小学校での生活にも慣れてきた。A\nちゃんの母親は｢夫は朝早く出勤し、長女もまだ小さく、A を小学校に連れて行く\nまで忙しくて大変です｣と訪問看護師に話した。訪問看護師は保健所の保健師に相\n談し、A ちゃん宅で家族も含めて A ちゃんが利用できる支援サービスを検討する\nことにした。\nA ちゃんと家族に利用を勧める支援サービスで適切なのはどれか。","choices":["児童発達支援","重度訪問介護","放課後等デイサービス","短期入所〈ショートステイ〉"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A ちゃん(6歳、男児)は父親(50 歳、会社員)、母親(48 歳)、姉(11 歳)と4人で暮\nらしている。Duchenne〈デュシェンヌ〉型筋ジストロフィーで身体障害者手帳(肢体\nDuchenne muscular dystrophy\n不自由1級)が交付されている。喀痰吸引、胃瘻による経管栄養が必要で、訪問看護\nを週に2回利用している。まばたきの回数で｢はい｣と｢いいえ｣の意思表示はできる\nが、視線や上肢の動きには誤動作もあり、構音障害もあるため家族以外では意思の判\n断が難しい。また、手指での細かい操作はできない。A ちゃんは次年度から姉と同\nじ小学校の特別支援学級に通い、通常の学級の児童と交流の予定がある。","preceding_context":[{"id":"112-AM-115","question":"入学時に担任が A ちゃんの意思を確認する方法で最も適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":116,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[51],"case_pages":[50],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A116"},"exam":112,"year":2023,"session":"AM","number":116},"sources":[{"title":"厚生労働省：医療的ケア児に関わる年齢別制度","url":"https://www.mhlw.go.jp/content/10802000/001237298.pdf"},{"title":"厚生労働省：障害福祉サービスの内容","url":"https://www.mhlw.go.jp/stf/seisakunitsuite/bunya/hukushi_kaigo/shougaishahukushi/service/naiyou.html"}]},{"id":"112-AM-117","record":{"id":"112-AM-117","choice_explanations":[{"choice":1,"correct":false,"title":"｢学校の行事に参加してみませんか｣","explanation":"学校行事への参加も交流になりますが、母親は同じ経験や苦労を共有できる相手を求めています。"},{"choice":2,"correct":false,"title":"｢短時間でも仕事を始めてはいかがですか｣","explanation":"就労を勧めるだけでは、ケアの経験を理解してもらえない孤立感への対応になりません。"},{"choice":3,"correct":false,"title":"｢お姉ちゃんのお友達の親に話しかけてみませんか｣","explanation":"姉の友人の親との交流が希望に合うとは限りません。障害児を育てる経験の共有が求められています。"},{"choice":4,"correct":true,"title":"｢障害のある子どもを持つ家族の会に参加してみませんか｣","explanation":"同じ立場の家族と経験や気持ちを共有できるピアサポートにつながります。本人の希望を尊重して紹介します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A ちゃんは入学して1度も入院することなく2年生になった。A ちゃんの母親\nはケアに必要な物品を学校の看護師に渡す際に｢A は学校に通うようになり、お友\n達が増えて本当によかったと思います。それに比べて私は仕事をしていないし、A\nに友達ができた喜びや日々の苦労を理解してもらえる友達がいません。A の同級\n生の親には年齢が近くて話しやすい人がいません｣と話した。\nA ちゃんの母親への提案で最も適切なのはどれか。","choices":["｢学校の行事に参加してみませんか｣","｢短時間でも仕事を始めてはいかがですか｣","｢お姉ちゃんのお友達の親に話しかけてみませんか｣","｢障害のある子どもを持つ家族の会に参加してみませんか｣"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A ちゃん(6歳、男児)は父親(50 歳、会社員)、母親(48 歳)、姉(11 歳)と4人で暮\nらしている。Duchenne〈デュシェンヌ〉型筋ジストロフィーで身体障害者手帳(肢体\nDuchenne muscular dystrophy\n不自由1級)が交付されている。喀痰吸引、胃瘻による経管栄養が必要で、訪問看護\nを週に2回利用している。まばたきの回数で｢はい｣と｢いいえ｣の意思表示はできる\nが、視線や上肢の動きには誤動作もあり、構音障害もあるため家族以外では意思の判\n断が難しい。また、手指での細かい操作はできない。A ちゃんは次年度から姉と同\nじ小学校の特別支援学級に通い、通常の学級の児童と交流の予定がある。","preceding_context":[{"id":"112-AM-115","question":"入学時に担任が A ちゃんの意思を確認する方法で最も適切なのはどれか。"},{"id":"112-AM-116","question":"A ちゃんが小学校に入学して6か月が経過した。小学校への送迎は母親が行っ\nており、学内での喀痰吸引や経管栄養の注入は小学校に配置されている看護師が\n行っている。A ちゃんは体調も安定しており、小学校での生活にも慣れてきた。A\nちゃんの母親は｢夫は朝早く出勤し、長女もまだ小さく、A を小学校に連れて行く\nまで忙しくて大変です｣と訪問看護師に話した。訪問看護師は保健所の保健師に相\n談し、A ちゃん宅で家族も含めて A ちゃんが利用できる支援サービスを検討する\nことにした。\nA ちゃんと家族に利用を勧める支援サービスで適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":117,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[51],"case_pages":[50],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A117"},"exam":112,"year":2023,"session":"AM","number":117},"sources":[]},{"id":"112-AM-118","record":{"id":"112-AM-118","choice_explanations":[{"choice":1,"correct":false,"title":"上半身を挙上する。","explanation":"血圧が低下しており、上体挙上で循環がさらに悪化するおそれがあります。吐血による誤嚥防止も必要です。"},{"choice":2,"correct":true,"title":"身体を側臥位にする。","explanation":"反応が鈍く吐血しているため、血液や吐物の誤嚥を防ぐ体位を確保します。吸引と循環への対応も並行します。"},{"choice":3,"correct":false,"title":"頭部の冷罨法を行う。","explanation":"頭部冷却は出血や誤嚥の問題を解決しません。気道と循環を優先します。"},{"choice":4,"correct":false,"title":"酸素療法の準備をする。","explanation":"酸素化は現在保たれています。必要に応じて準備しますが、まず吐物による気道閉塞・誤嚥を防ぎます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"入院時、A さんへの看護師の対応で適切なのはどれか。","choices":["上半身を挙上する。","身体を側臥位にする。","頭部の冷罨法を行う。","酸素療法の準備をする。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(57 歳、男性、無職)は妻(55 歳、会社員)と2人で暮らしている。A さん\nは、飲酒が原因で仕事での遅刻や無断欠勤が続いたため1年前に職場を解雇された。\nそ の 後 も 朝 か ら 自 宅 で 飲 酒 す る 生 活 が 続 き、体 調 が 悪 化 し た た め 受 診 し、\nアルコール性肝硬変とアルコール依存症と診断された。医師から断酒を指導されてい\nalcoholic cirrhosis alcohol dependence\nたが実行できず通院していなかった。\nA さんは最近、倦怠感が強く食欲がなく、1週前から飲酒もできなくなった。妻\nに付き添われて受診した際、外来のトイレで吐血し倒れ食道静脈瘤破裂と診断され入\nrupture of esophageal varices\n院した。\n身体所見：呼びかけに応じるが反応が遅い。腹水や浮腫はない。手指の振戦はない。\n体温 37.0 ℃、呼吸数 22/分、脈拍 98/分、整、血圧 92/50 mmHg、経皮\n的動脈血酸素飽和度〈SpO2〉98 %(room air)。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":118,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[52],"case_pages":[52],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A118"},"exam":112,"year":2023,"session":"AM","number":118},"sources":[]},{"id":"112-AM-119","record":{"id":"112-AM-119","choice_explanations":[{"choice":1,"correct":false,"title":"下 血","explanation":"出血の評価は必要ですが、硬化療法直後には局所の炎症や損傷を示す胸部痛が重要です。"},{"choice":2,"correct":true,"title":"胸部痛","explanation":"硬化剤による局所反応のほか、強い痛みでは食道損傷なども疑います。程度と随伴症状を観察し報告します。"},{"choice":3,"correct":false,"title":"皮下出血","explanation":"出血傾向などで起こりますが、提示検査値と治療直後の場面で最も注意する症状ではありません。"},{"choice":4,"correct":false,"title":"手指の振戦","explanation":"アルコール離脱などでみられますが、硬化療法直後の局所合併症を捉える所見ではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"入 院 当 日、A さ ん は 緊 急 に 内 視 鏡 的 治 療 を 受 け た。入 院 7 日、A さ ん は\n食道静脈瘤の治療のため、食道静脈瘤硬化療法を受けることになった。治療前のバ\nesophageal varices\nイタルサインは、体温 36.7 ℃、呼吸数 16/分、脈拍 72/分、整、血圧 126/70 mmHg\nである。検査所見は、血小板 15 万/μL、プロトロンビン時間〈PT〉10 秒 85 % であ\nる。入院後は吐血していない。\nA さんが食道静脈瘤硬化療法を受けた直後に注意すべき症状はどれか。","choices":["下 血","胸部痛","皮下出血","手指の振戦"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(57 歳、男性、無職)は妻(55 歳、会社員)と2人で暮らしている。A さん\nは、飲酒が原因で仕事での遅刻や無断欠勤が続いたため1年前に職場を解雇された。\nそ の 後 も 朝 か ら 自 宅 で 飲 酒 す る 生 活 が 続 き、体 調 が 悪 化 し た た め 受 診 し、\nアルコール性肝硬変とアルコール依存症と診断された。医師から断酒を指導されてい\nalcoholic cirrhosis alcohol dependence\nたが実行できず通院していなかった。\nA さんは最近、倦怠感が強く食欲がなく、1週前から飲酒もできなくなった。妻\nに付き添われて受診した際、外来のトイレで吐血し倒れ食道静脈瘤破裂と診断され入\nrupture of esophageal varices\n院した。\n身体所見：呼びかけに応じるが反応が遅い。腹水や浮腫はない。手指の振戦はない。\n体温 37.0 ℃、呼吸数 22/分、脈拍 98/分、整、血圧 92/50 mmHg、経皮\n的動脈血酸素飽和度〈SpO2〉98 %(room air)。","preceding_context":[{"id":"112-AM-118","question":"入院時、A さんへの看護師の対応で適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":119,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[53],"case_pages":[52],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A119"},"exam":112,"year":2023,"session":"AM","number":119},"sources":[]},{"id":"112-AM-120","record":{"id":"112-AM-120","choice_explanations":[{"choice":1,"correct":false,"title":"｢断酒をする意思を強く持ちましょう｣","explanation":"依存症を意思の弱さだけの問題にしません。再飲酒につながる状況を整理し、具体的な支援を考えます。"},{"choice":2,"correct":false,"title":"｢肝硬変があるので、今は安静が必要です｣","explanation":"状態評価なしに安静を勧めると、本人が心配する無活動を強めます。安全な生活と活動を検討します。"},{"choice":3,"correct":false,"title":"｢入院中も飲酒をやめられているので大丈夫です｣","explanation":"入院環境で断酒できたことだけで退院後も大丈夫とは言えません。不安を受け止めて支援を整えます。"},{"choice":4,"correct":true,"title":"｢アルコールの問題で悩んでいる人たちとの話し合いに参加してみましょう｣","explanation":"自助グループなどで同じ悩みを持つ人と経験を共有することは、断酒を続ける支えになります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんは食道静脈瘤硬化療法を終えて、アルコール依存症の治療を受けるため\nalcohol dependence\nに精神科病院に転院した。\n転院して2か月、病棟では A さんの退院に向けた話し合いが進められている。\nA さんは｢退院した後にお酒をやめられるか自信がない。体力が落ちており、何も\nしていないとお酒を飲んでしまいそうです｣と悩みを打ち明けた。\nA さんへの看護師の声かけで適切なのはどれか。","choices":["｢断酒をする意思を強く持ちましょう｣","｢肝硬変があるので、今は安静が必要です｣","｢入院中も飲酒をやめられているので大丈夫です｣","｢アルコールの問題で悩んでいる人たちとの話し合いに参加してみましょう｣"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A さん(57 歳、男性、無職)は妻(55 歳、会社員)と2人で暮らしている。A さん\nは、飲酒が原因で仕事での遅刻や無断欠勤が続いたため1年前に職場を解雇された。\nそ の 後 も 朝 か ら 自 宅 で 飲 酒 す る 生 活 が 続 き、体 調 が 悪 化 し た た め 受 診 し、\nアルコール性肝硬変とアルコール依存症と診断された。医師から断酒を指導されてい\nalcoholic cirrhosis alcohol dependence\nたが実行できず通院していなかった。\nA さんは最近、倦怠感が強く食欲がなく、1週前から飲酒もできなくなった。妻\nに付き添われて受診した際、外来のトイレで吐血し倒れ食道静脈瘤破裂と診断され入\nrupture of esophageal varices\n院した。\n身体所見：呼びかけに応じるが反応が遅い。腹水や浮腫はない。手指の振戦はない。\n体温 37.0 ℃、呼吸数 22/分、脈拍 98/分、整、血圧 92/50 mmHg、経皮\n的動脈血酸素飽和度〈SpO2〉98 %(room air)。","preceding_context":[{"id":"112-AM-118","question":"入院時、A さんへの看護師の対応で適切なのはどれか。"},{"id":"112-AM-119","question":"入 院 当 日、A さ ん は 緊 急 に 内 視 鏡 的 治 療 を 受 け た。入 院 7 日、A さ ん は\n食道静脈瘤の治療のため、食道静脈瘤硬化療法を受けることになった。治療前のバ\nesophageal varices\nイタルサインは、体温 36.7 ℃、呼吸数 16/分、脈拍 72/分、整、血圧 126/70 mmHg\nである。検査所見は、血小板 15 万/μL、プロトロンビン時間〈PT〉10 秒 85 % であ\nる。入院後は吐血していない。\nA さんが食道静脈瘤硬化療法を受けた直後に注意すべき症状はどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午前","question_number":120,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05a_01.pdf","pages":[53],"case_pages":[52],"sha256":"884acfda334c298179cded6374cc860630ac6c42c572260f89c64b50818e1406"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"A120"},"exam":112,"year":2023,"session":"AM","number":120},"sources":[]},{"id":"112-PM-001","record":{"id":"112-PM-001","choice_explanations":[{"choice":1,"correct":false,"title":"78.4 年","explanation":"78.4年は2019年の男性の平均寿命ではありません。0歳の平均余命を平均寿命と呼びます。"},{"choice":2,"correct":true,"title":"81.4 年","explanation":"2019年の男性の0歳平均余命は81.41年で、選択肢では81.4年です。その年の死亡状況から算出した指標です。"},{"choice":3,"correct":false,"title":"84.4 年","explanation":"84.4年は指定年の男性の値ではありません。男女や対象年を取り違えずに統計を読みます。"},{"choice":4,"correct":false,"title":"87.4 年","explanation":"87.4年は2019年の女性の平均寿命に近い値です。問題は0歳男児の平均余命を尋ねています。"}],"status":"VERIFIED","review_reason":"問題・全選択肢・公式正答2を照合。2019年の男性の0歳平均余命は81.41年で、選択肢では81.4年です。その年の死亡状況から算出した指標です。","fixes_made":[]},"input_anchor":{"question":"令和元年(2019 年)の0歳男児の平均余命はどれか。","choices":["78.4 年","81.4 年","84.4 年","87.4 年"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":1,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[7],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B001"},"exam":112,"year":2023,"session":"PM","number":1},"sources":[{"title":"厚生労働省 令和元年簡易生命表 男","url":"https://www.mhlw.go.jp/toukei/saikin/hw/life/life19/dl/life19-15.pdf"}]},{"id":"112-PM-002","record":{"id":"112-PM-002","choice_explanations":[{"choice":1,"correct":false,"title":"6.0 g","explanation":"6gは高血圧患者などの減塩目標と混同しやすい値です。第二次の国民全体の平均摂取量の目標とは異なります。"},{"choice":2,"correct":true,"title":"8.0 g","explanation":"健康日本21第二次では、1日の食塩摂取量の平均値を8gとする目標が設定されました。個別の治療目標とは区別します。"},{"choice":3,"correct":false,"title":"10.0 g","explanation":"10gは第二次の目標より多く、減塩目標としては不適切です。実際の摂取状況と政策の目標値を区別します。"},{"choice":4,"correct":false,"title":"12.0 g","explanation":"12gは第二次の目標値を大きく上回ります。塩分過多は血圧上昇につながるため、摂取量の減少を目指します。"}],"status":"VERIFIED","review_reason":"問題・全選択肢・公式正答2を照合。健康日本21第二次では、1日の食塩摂取量の平均値を8gとする目標が設定されました。個別の治療目標とは区別します。","fixes_made":[]},"input_anchor":{"question":"健康日本 21(第二次)における1日の塩分摂取量の目標値で正しいのはどれか。","choices":["6.0 g","8.0 g","10.0 g","12.0 g"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":2,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[7],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B002"},"exam":112,"year":2023,"session":"PM","number":2},"sources":[{"title":"厚生労働省 食環境づくり検討会議事録 第二次の食塩8g目標","url":"https://www.mhlw.go.jp/stf/newpage_18263.html"}]},{"id":"112-PM-003","record":{"id":"112-PM-003","choice_explanations":[{"choice":1,"correct":false,"title":"コレラ\ncholera","explanation":"コレラは汚染された水や食品を介する経口感染です。循環式浴槽の微小な水滴の吸入で問題になる感染症とは異なります。"},{"choice":2,"correct":false,"title":"A 型肝炎\nhepatitis A","explanation":"A型肝炎は主に汚染食品や水からの経口感染です。浴槽の循環設備で増殖する菌の吸入による肺炎ではありません。"},{"choice":3,"correct":true,"title":"レジオネラ肺炎\nlegionella pneumonia","explanation":"浴槽や配管で増殖したレジオネラ属菌を含むエアロゾルを吸入すると肺炎を起こします。循環設備の清掃・消毒が重要です。"},{"choice":4,"correct":false,"title":"後天性免疫不全症候群〈AIDS〉\nacquired immunodeficiency syndrome","explanation":"HIVは血液、性行為、母子感染などで伝播します。共用浴槽の水を介して感染するものではありません。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答3を照合。浴槽や配管で増殖したレジオネラ属菌を含むエアロゾルを吸入すると肺炎を起こします。循環設備の清掃・消毒が重要です。","fixes_made":[]},"input_anchor":{"question":"循環式浴槽の水質汚染で発症するのはどれか。","choices":["コレラ\ncholera","A 型肝炎\nhepatitis A","レジオネラ肺炎\nlegionella pneumonia","後天性免疫不全症候群〈AIDS〉\nacquired immunodeficiency syndrome"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":3,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[7],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B003"},"exam":112,"year":2023,"session":"PM","number":3},"sources":[]},{"id":"112-PM-004","record":{"id":"112-PM-004","choice_explanations":[{"choice":1,"correct":false,"title":"1 割","explanation":"1割負担は高齢者の一定の区分などに適用されます。40歳の国民健康保険加入者の原則的な負担ではありません。"},{"choice":2,"correct":false,"title":"2 割","explanation":"2割負担は未就学児や一定の高齢者などの区分です。40歳の自営業者には原則3割が適用されます。"},{"choice":3,"correct":true,"title":"3 割","explanation":"40歳の国民健康保険加入者は、保険診療の医療費を原則3割負担します。高額療養費などによる負担軽減とは別の規定です。"},{"choice":4,"correct":false,"title":"4 割","explanation":"4割はこの年齢区分の法定の一部負担割合ではありません。40歳では原則3割です。"}],"status":"VERIFIED","review_reason":"問題・全選択肢・公式正答3を照合。40歳の国民健康保険加入者は、保険診療の医療費を原則3割負担します。高額療養費などによる負担軽減とは別の規定です。","fixes_made":[]},"input_anchor":{"question":"国民健康保険に加入している自営業者(40 歳)の医療費の一部負担金の割合はど\nれか。","choices":["1 割","2 割","3 割","4 割"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":4,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[7],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B004"},"exam":112,"year":2023,"session":"PM","number":4},"sources":[{"title":"厚生労働省 医療費の一部負担割合","url":"https://www.mhlw.go.jp/content/000937919.pdf"}]},{"id":"112-PM-005","record":{"id":"112-PM-005","choice_explanations":[{"choice":1,"correct":false,"title":"刑 法","explanation":"刑法にも一定の職種の秘密漏示に関する規定がありますが、看護師の業務上の守秘義務を直接規定するのは保健師助産師看護師法です。"},{"choice":2,"correct":false,"title":"医療法","explanation":"医療法は医療提供体制や医療機関などを定めます。設問の看護師個人の守秘義務の根拠法ではありません。"},{"choice":3,"correct":true,"title":"保健師助産師看護師法","explanation":"保健師助産師看護師法第42条の2に、正当な理由なく業務上知った秘密を漏らしてはならないと規定されています。看護師でなくなった後も同様です。"},{"choice":4,"correct":false,"title":"看護師等の人材確保の促進に関する法律","explanation":"人材確保法は看護職の確保や資質向上などを推進する法律です。設問の守秘義務の直接の根拠ではありません。"}],"status":"VERIFIED","review_reason":"問題・全選択肢・公式正答3を照合。保健師助産師看護師法第42条の2に、正当な理由なく業務上知った秘密を漏らしてはならないと規定されています。看護師でなくなった後も同様です。","fixes_made":[]},"input_anchor":{"question":"看護師は正当な理由がなく、その業務上知り得た人の秘密を漏らしてはならない\nと規定している法律はどれか。","choices":["刑 法","医療法","保健師助産師看護師法","看護師等の人材確保の促進に関する法律"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":5,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[8],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B005"},"exam":112,"year":2023,"session":"PM","number":5},"sources":[{"title":"保健師助産師看護師法","url":"https://laws.e-gov.go.jp/law/323AC0000000203?occasion_date=20210114"}]},{"id":"112-PM-006","record":{"id":"112-PM-006","choice_explanations":[{"choice":1,"correct":false,"title":"6か月","explanation":"6か月では通常、大泉門はまだ閉鎖していません。出生後早期に閉鎖する小泉門と区別します。"},{"choice":2,"correct":true,"title":"1歳6か月","explanation":"大泉門はおおむね1歳から1歳6か月ごろに閉鎖します。選択肢では1歳6か月が最も近い時期です。"},{"choice":3,"correct":false,"title":"2歳6か月","explanation":"2歳6か月は標準的な閉鎖時期より遅い時期です。閉鎖状況は発達や頭囲とあわせて評価します。"},{"choice":4,"correct":false,"title":"3歳6か月","explanation":"3歳6か月は大泉門の一般的な閉鎖時期ではありません。通常は乳児期後半から幼児期初期に閉鎖します。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答2を照合。大泉門はおおむね1歳から1歳6か月ごろに閉鎖します。選択肢では1歳6か月が最も近い時期です。","fixes_made":[]},"input_anchor":{"question":"大泉門が閉鎖する時期に最も近いのはどれか。","choices":["6か月","1歳6か月","2歳6か月","3歳6か月"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":6,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[8],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B006"},"exam":112,"year":2023,"session":"PM","number":6},"sources":[]},{"id":"112-PM-007","record":{"id":"112-PM-007","choice_explanations":[{"choice":1,"correct":true,"title":"生後 3〜 5 日","explanation":"出生後は排尿・排便や不感蒸泄に摂取量が追いつかず、生後3〜5日ごろに最低体重となります。その後は哺乳量増加に伴って回復します。"},{"choice":2,"correct":false,"title":"生後 8〜10 日","explanation":"生後8〜10日は通常、最低体重の時期を過ぎて増加に向かうころです。体重の減少幅や哺乳状況も観察します。"},{"choice":3,"correct":false,"title":"生後 13〜15 日","explanation":"生後13〜15日は通常、出生体重への回復が期待されるころです。この時期に最低となる経過は生理的と即断できません。"},{"choice":4,"correct":false,"title":"生後 18〜20 日","explanation":"生後18〜20日に最低体重となるのは通常の生理的経過ではありません。哺乳不良や疾患などの評価が必要です。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1を照合。出生後は排尿・排便や不感蒸泄に摂取量が追いつかず、生後3〜5日ごろに最低体重となります。その後は哺乳量増加に伴って回復します。","fixes_made":[]},"input_anchor":{"question":"正期産の新生児が生理的体重減少によって最低体重になるのはどれか。","choices":["生後 3〜 5 日","生後 8〜10 日","生後 13〜15 日","生後 18〜20 日"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":7,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[8],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B007"},"exam":112,"year":2023,"session":"PM","number":7},"sources":[]},{"id":"112-PM-008","record":{"id":"112-PM-008","choice_explanations":[{"choice":1,"correct":false,"title":"親密 対 孤立","explanation":"親密対孤立は成人期初期の課題です。親しい相手との持続的な関係を築くことが中心となります。"},{"choice":2,"correct":false,"title":"自律性 対 恥・疑惑","explanation":"自律性対恥・疑惑は幼児期前期の課題です。排泄など自分で行う経験を通して自律性が育ちます。"},{"choice":3,"correct":true,"title":"勤勉性 対 劣等感","explanation":"学童期は学習や作業をやり遂げることで勤勉性を育てる時期です。達成経験が乏しいと劣等感につながります。"},{"choice":4,"correct":false,"title":"自我同一性〈アイデンティティ〉の確立 対 自我同一性〈アイデンティティ〉の\n拡散","explanation":"自我同一性の確立対拡散は青年期の課題です。自分の価値観や将来の役割を探る時期に対応します。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答3を照合。学童期は学習や作業をやり遂げることで勤勉性を育てる時期です。達成経験が乏しいと劣等感につながります。","fixes_made":[]},"input_anchor":{"question":"エリクソンが提唱する発達理論において、学童期に達成すべき心理社会的課題は\nErikson, E. H.\nどれか。","choices":["親密 対 孤立","自律性 対 恥・疑惑","勤勉性 対 劣等感","自我同一性〈アイデンティティ〉の確立 対 自我同一性〈アイデンティティ〉の\n拡散"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":8,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[8],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B008"},"exam":112,"year":2023,"session":"PM","number":8},"sources":[]},{"id":"112-PM-009","record":{"id":"112-PM-009","choice_explanations":[{"choice":1,"correct":false,"title":"4 人","explanation":"家族が成立するために4人いる必要はありません。夫婦など2人でも家族となります。"},{"choice":2,"correct":false,"title":"3 人","explanation":"親と子など3人の家族はありますが、最少人数ではありません。子どもの存在は家族成立の必須条件ではありません。"},{"choice":3,"correct":true,"title":"2 人","explanation":"本問で扱う家族は成員相互の関係を持つ集団であり、最少人数は2人です。単身世帯という世帯の区分とは区別します。"},{"choice":4,"correct":false,"title":"1 人","explanation":"1人で暮らす単身世帯はありますが、本問の家族集団の最少人数は2人です。家族と世帯は同一の概念ではありません。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答3を照合。本問で扱う家族は成員相互の関係を持つ集団であり、最少人数は2人です。単身世帯という世帯の区分とは区別します。","fixes_made":[]},"input_anchor":{"question":"家族成員の最少人数はどれか。","choices":["4 人","3 人","2 人","1 人"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":9,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[9],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B009"},"exam":112,"year":2023,"session":"PM","number":9},"sources":[]},{"id":"112-PM-010","record":{"id":"112-PM-010","choice_explanations":[{"choice":1,"correct":false,"title":"病気の治療","explanation":"病気の診断・治療は医療機関の役割です。市町村保健センターは住民の保健サービスを担います。"},{"choice":2,"correct":true,"title":"住民の健康診査","explanation":"地域保健法では、住民への健康相談、保健指導、健康診査などを市町村保健センターの機能として定めています。"},{"choice":3,"correct":false,"title":"看護師免許申請の受理","explanation":"看護師免許申請の窓口は通常、保健所などです。市町村保健センターの法律上の中心的業務ではありません。"},{"choice":4,"correct":false,"title":"専門的で広域的な健康課題への対応","explanation":"専門的・広域的な地域保健課題への対応は主として保健所の役割です。保健センターは住民に身近な保健サービスを担います。"}],"status":"VERIFIED","review_reason":"問題・全選択肢・公式正答2を照合。地域保健法では、住民への健康相談、保健指導、健康診査などを市町村保健センターの機能として定めています。","fixes_made":[]},"input_anchor":{"question":"地域保健法に規定されている市町村保健センターの業務はどれか。","choices":["病気の治療","住民の健康診査","看護師免許申請の受理","専門的で広域的な健康課題への対応"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":10,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[9],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B010"},"exam":112,"year":2023,"session":"PM","number":10},"sources":[{"title":"地域保健法","url":"https://www.mhlw.go.jp/web/t_doc?dataId=78301000"}]},{"id":"112-PM-011","record":{"id":"112-PM-011","choice_explanations":[{"choice":1,"correct":false,"title":"瞳孔散大","explanation":"瞳孔散大は主に交感神経の作用です。副交感神経は瞳孔括約筋を働かせ、縮瞳を起こします。"},{"choice":2,"correct":false,"title":"気管支拡張","explanation":"気管支拡張は主に交感神経系の作用です。副交感神経は気管支平滑筋を収縮させます。"},{"choice":3,"correct":false,"title":"心拍数の増加","explanation":"心拍数の増加は交感神経の作用です。副交感神経は洞房結節などに作用して心拍数を減らします。"},{"choice":4,"correct":true,"title":"消化液分泌の促進","explanation":"副交感神経は消化管の運動や消化液分泌を促進します。安静時の消化・吸収を進める働きです。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答4を照合。副交感神経は消化管の運動や消化液分泌を促進します。安静時の消化・吸収を進める働きです。","fixes_made":[]},"input_anchor":{"question":"副交感神経の作用で正しいのはどれか。","choices":["瞳孔散大","気管支拡張","心拍数の増加","消化液分泌の促進"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":11,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[9],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B011"},"exam":112,"year":2023,"session":"PM","number":11},"sources":[]},{"id":"112-PM-012","record":{"id":"112-PM-012","choice_explanations":[{"choice":1,"correct":true,"title":"洞房結節","explanation":"正常の心拍は洞房結節の自発的興奮から始まります。ここが心臓の主要なペースメーカーです。"},{"choice":2,"correct":false,"title":"房室結節","explanation":"房室結節は心房からの興奮を受け、伝導を遅らせて心室へ伝えます。正常では最初の興奮部位ではありません。"},{"choice":3,"correct":false,"title":"His〈ヒス〉束","explanation":"ヒス束は房室結節からの興奮を脚へ伝えます。刺激伝導系の途中に位置します。"},{"choice":4,"correct":false,"title":"Purkinje〈プルキンエ〉線維","explanation":"プルキンエ線維は興奮を心室筋へ速く伝える末端側の組織です。正常心拍の開始部位ではありません。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1を照合。正常の心拍は洞房結節の自発的興奮から始まります。ここが心臓の主要なペースメーカーです。","fixes_made":[]},"input_anchor":{"question":"心臓の刺激伝導系で最初の興奮部位はどれか。","choices":["洞房結節","房室結節","His〈ヒス〉束","Purkinje〈プルキンエ〉線維"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":12,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[9],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B012"},"exam":112,"year":2023,"session":"PM","number":12},"sources":[]},{"id":"112-PM-013","record":{"id":"112-PM-013","choice_explanations":[{"choice":1,"correct":false,"title":"球状の細胞である。","explanation":"正常の赤血球は中央がくぼんだ両凹円盤状です。この形がガス交換と細い毛細血管の通過に役立ちます。"},{"choice":2,"correct":false,"title":"腎臓で破壊される。","explanation":"老化した赤血球は主に脾臓や肝臓のマクロファージで処理されます。腎臓はエリスロポエチン産生に関与します。"},{"choice":3,"correct":false,"title":"寿命は約 60 日である。","explanation":"赤血球の寿命は約120日です。約60日という値は標準的な寿命の半分です。"},{"choice":4,"correct":true,"title":"酸素の輸送を担っている。","explanation":"赤血球内のヘモグロビンが酸素と結合し、肺から組織へ運びます。赤血球の主要な機能です。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答4を照合。赤血球内のヘモグロビンが酸素と結合し、肺から組織へ運びます。赤血球の主要な機能です。","fixes_made":[]},"input_anchor":{"question":"成人の正常な赤血球の説明で正しいのはどれか。","choices":["球状の細胞である。","腎臓で破壊される。","寿命は約 60 日である。","酸素の輸送を担っている。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":13,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[10],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B013"},"exam":112,"year":2023,"session":"PM","number":13},"sources":[]},{"id":"112-PM-014","record":{"id":"112-PM-014","choice_explanations":[{"choice":1,"correct":false,"title":"ビリルビン","explanation":"ビリルビン増加で皮膚や粘膜が黄色くなる状態は黄疸です。チアノーゼの青紫色とは異なります。"},{"choice":2,"correct":false,"title":"ヘモグロビン","explanation":"総ヘモグロビン量だけではチアノーゼを説明できません。酸素と結合していないヘモグロビンの絶対量が関係します。"},{"choice":3,"correct":false,"title":"ヘモグロビン A1c〈HbA1c〉","explanation":"HbA1cは糖が結合したヘモグロビンで、血糖管理の指標です。チアノーゼの定義に入る物質ではありません。"},{"choice":4,"correct":true,"title":"脱酸素化ヘモグロビン〈還元ヘモグロビン〉","explanation":"脱酸素化ヘモグロビンの増加で青紫色を呈します。本問では末梢血中5g/dL以上という古典的な基準が示されています。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答4を照合。脱酸素化ヘモグロビンの増加で青紫色を呈します。本問では末梢血中5g/dL以上という古典的な基準が示されています。","fixes_made":[]},"input_anchor":{"question":"チアノーゼとは( )の絶対量が増加して5g/dL 以上になり、皮膚や粘\n膜が紫から青紫色を示す状態のことをいう。\n( )に入るのはどれか。","choices":["ビリルビン","ヘモグロビン","ヘモグロビン A1c〈HbA1c〉","脱酸素化ヘモグロビン〈還元ヘモグロビン〉"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":14,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[10],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B014"},"exam":112,"year":2023,"session":"PM","number":14},"sources":[]},{"id":"112-PM-015","record":{"id":"112-PM-015","choice_explanations":[{"choice":1,"correct":false,"title":"疥 癬\nscabies","explanation":"疥癬はヒゼンダニによる感染で、皮膚接触などが主な経路です。飛沫感染ではありません。"},{"choice":2,"correct":false,"title":"破傷風\ntetanus","explanation":"破傷風は傷口に侵入した破傷風菌の毒素により発症します。患者の咳から飛沫感染する疾患ではありません。"},{"choice":3,"correct":false,"title":"デング熱\ndengue fever","explanation":"デング熱は主に感染した蚊の刺咬で伝播します。通常の飛沫感染ではありません。"},{"choice":4,"correct":true,"title":"インフルエンザ\ninfluenza","explanation":"インフルエンザは咳やくしゃみの飛沫などを介して伝播します。手指衛生と状況に応じた飛沫対策が必要です。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答4を照合。インフルエンザは咳やくしゃみの飛沫などを介して伝播します。手指衛生と状況に応じた飛沫対策が必要です。","fixes_made":[]},"input_anchor":{"question":"飛沫感染するのはどれか。","choices":["疥 癬\nscabies","破傷風\ntetanus","デング熱\ndengue fever","インフルエンザ\ninfluenza"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":15,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[10],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B015"},"exam":112,"year":2023,"session":"PM","number":15},"sources":[]},{"id":"112-PM-016","record":{"id":"112-PM-016","choice_explanations":[{"choice":1,"correct":false,"title":"出 血","explanation":"出血はモルヒネの代表的な副作用ではありません。呼吸抑制、悪心、眠気、便秘などに注意します。"},{"choice":2,"correct":false,"title":"難 聴","explanation":"難聴はモルヒネで代表的に問われる副作用ではありません。薬剤ごとに特徴的な有害事象を区別します。"},{"choice":3,"correct":true,"title":"便 秘","explanation":"モルヒネは腸管運動を抑制して便秘を起こします。耐性が生じにくい副作用のため、排便状況の評価や予防が重要です。"},{"choice":4,"correct":false,"title":"骨髄抑制","explanation":"骨髄抑制は抗がん薬などで問題になります。モルヒネの代表的副作用とは異なります。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答3を照合。モルヒネは腸管運動を抑制して便秘を起こします。耐性が生じにくい副作用のため、排便状況の評価や予防が重要です。","fixes_made":[]},"input_anchor":{"question":"モルヒネの副作用(有害事象)はどれか。","choices":["出 血","難 聴","便 秘","骨髄抑制"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":16,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[10],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B016"},"exam":112,"year":2023,"session":"PM","number":16},"sources":[]},{"id":"112-PM-017","record":{"id":"112-PM-017","choice_explanations":[{"choice":1,"correct":false,"title":"成人では9〜10 cm 幅のマンシェットを用いる。","explanation":"成人用のマンシェットは上腕周囲に合うサイズを選びます。9〜10cm幅は一般的な成人用として狭く、測定値を高くするおそれがあります。"},{"choice":2,"correct":false,"title":"マンシェットの下端と肘窩が重なるように巻く。","explanation":"下端は肘窩より少し上に置き、聴診部位を確保します。肘窩に重ねると聴診器を適切に当てにくくなります。"},{"choice":3,"correct":true,"title":"マンシェットの装着部位と心臓が同じ高さになるようにする。","explanation":"装着部を心臓の高さにそろえることで、水圧による誤差を減らせます。腕は力を抜いて支持します。"},{"choice":4,"correct":false,"title":"マンシェットと腕の間に指が3、4本入る程度の強さで巻く。","explanation":"指3、4本分の余裕は緩すぎます。適切な密着が得られるよう、一般に指1〜2本程度が入る強さで巻きます。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答3を照合。装着部を心臓の高さにそろえることで、水圧による誤差を減らせます。腕は力を抜いて支持します。","fixes_made":[]},"input_anchor":{"question":"上腕動脈で行う聴診法による血圧測定で適切なのはどれか。","choices":["成人では9〜10 cm 幅のマンシェットを用いる。","マンシェットの下端と肘窩が重なるように巻く。","マンシェットの装着部位と心臓が同じ高さになるようにする。","マンシェットと腕の間に指が3、4本入る程度の強さで巻く。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":17,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[11],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B017"},"exam":112,"year":2023,"session":"PM","number":17},"sources":[]},{"id":"112-PM-018","record":{"id":"112-PM-018","choice_explanations":[{"choice":1,"correct":false,"title":"20 ℃","explanation":"20℃は体温より低く、冷刺激で腹痛や不快感を生じやすくなります。適温に温めて使用します。"},{"choice":2,"correct":false,"title":"30 ℃","explanation":"30℃も体温より低く、浣腸液の準備温度としては低めです。選択肢では40℃が適切です。"},{"choice":3,"correct":true,"title":"40 ℃","explanation":"体温程度で注入できるよう、おおむね40℃程度に準備します。加温後は温度を確認し、熱すぎる液を注入しません。"},{"choice":4,"correct":false,"title":"50 ℃","explanation":"50℃は高すぎ、直腸粘膜の熱傷を起こす危険があります。温度を確かめてから使用します。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答3を照合。体温程度で注入できるよう、おおむね40℃程度に準備します。加温後は温度を確認し、熱すぎる液を注入しません。","fixes_made":[]},"input_anchor":{"question":"グリセリン浣腸を準備する際の浣腸液の温度で適切なのはどれか。","choices":["20 ℃","30 ℃","40 ℃","50 ℃"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":18,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[11],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B018"},"exam":112,"year":2023,"session":"PM","number":18},"sources":[]},{"id":"112-PM-019","record":{"id":"112-PM-019","choice_explanations":[{"choice":1,"correct":true,"title":"廃用症候群\ndisuse syndrome","explanation":"不活動が続くと筋萎縮、関節拘縮、起立性低血圧などが生じます。これらをまとめて廃用症候群と呼びます。"},{"choice":2,"correct":false,"title":"緊張病症候群\ncatatonia syndrome","explanation":"緊張病症候群は昏迷、拒絶、興奮など精神運動の異常を示します。不活動に伴う全身機能低下の総称ではありません。"},{"choice":3,"correct":false,"title":"慢性疲労症候群\nchronic fatigue syndrome","explanation":"慢性疲労症候群は強い疲労や活動後の症状悪化などを示す疾患です。単なる不活動による機能低下とは区別します。"},{"choice":4,"correct":false,"title":"シックハウス症候群\nsick house syndrome","explanation":"シックハウス症候群は室内環境に関連する頭痛や粘膜症状などです。不活動の持続が直接の定義ではありません。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1を照合。不活動が続くと筋萎縮、関節拘縮、起立性低血圧などが生じます。これらをまとめて廃用症候群と呼びます。","fixes_made":[]},"input_anchor":{"question":"不活動状態が持続することで生じるのはどれか。","choices":["廃用症候群\ndisuse syndrome","緊張病症候群\ncatatonia syndrome","慢性疲労症候群\nchronic fatigue syndrome","シックハウス症候群\nsick house syndrome"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":19,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[11],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B019"},"exam":112,"year":2023,"session":"PM","number":19},"sources":[]},{"id":"112-PM-020","record":{"id":"112-PM-020","choice_explanations":[{"choice":1,"correct":false,"title":"入浴前後は水分制限をする。","explanation":"発汗で水分を失うため、個別の制限がなければ入浴前後に適切な水分補給をします。一律の水分制限は脱水につながります。"},{"choice":2,"correct":false,"title":"入浴時の湯温は 45 ℃とする。","explanation":"45℃は熱すぎ、循環器への負担や熱傷の危険があります。体調や年齢に合わせたぬるめの湯を用います。"},{"choice":3,"correct":true,"title":"脱衣室と浴室の温度差を小さくする。","explanation":"脱衣室と浴室の温度差を小さくすると、急激な血圧変動を防ぎやすくなります。入浴前に室温も整えます。"},{"choice":4,"correct":false,"title":"浴室に入り、始めに浴槽に浸かるように促す。","explanation":"いきなり浴槽に入らず、かけ湯などで体を湯温に慣らします。急な温度刺激や循環への負担を避けます。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答3を照合。脱衣室と浴室の温度差を小さくすると、急激な血圧変動を防ぎやすくなります。入浴前に室温も整えます。","fixes_made":[]},"input_anchor":{"question":"入浴の援助で正しいのはどれか。","choices":["入浴前後は水分制限をする。","入浴時の湯温は 45 ℃とする。","脱衣室と浴室の温度差を小さくする。","浴室に入り、始めに浴槽に浸かるように促す。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":20,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[11],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B020"},"exam":112,"year":2023,"session":"PM","number":20},"sources":[]},{"id":"112-PM-021","record":{"id":"112-PM-021","choice_explanations":[{"choice":1,"correct":false,"title":"胸骨圧迫","explanation":"胸骨圧迫は主に心停止時の循環維持に用います。反応を失った窒息患者では行いますが、本問の代表的異物除去法は腹部圧迫法です。"},{"choice":2,"correct":false,"title":"人工呼吸","explanation":"人工呼吸は換気を補助する処置です。気道が異物で閉塞したままでは有効な送気ができません。"},{"choice":3,"correct":false,"title":"頭部後屈顎先挙上法","explanation":"頭部後屈顎先挙上は舌根沈下による閉塞を軽減する気道確保法です。固形異物を排出させる手技ではありません。"},{"choice":4,"correct":true,"title":"腹部圧迫法〈Heimlich〈ハイムリック〉法〉","explanation":"腹部圧迫法は横隔膜を押し上げ、気道内の圧力を高めて異物を排出させます。反応のある成人の重い窒息で用いる方法です。"}],"status":"VERIFIED","review_reason":"問題・全選択肢・公式正答4を照合。腹部圧迫法は横隔膜を押し上げ、気道内の圧力を高めて異物を排出させます。反応のある成人の重い窒息で用いる方法です。","fixes_made":[]},"input_anchor":{"question":"成人の気道の異物除去を目的とするのはどれか。","choices":["胸骨圧迫","人工呼吸","頭部後屈顎先挙上法","腹部圧迫法〈Heimlich〈ハイムリック〉法〉"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":21,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[12],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B021"},"exam":112,"year":2023,"session":"PM","number":21},"sources":[{"title":"JRC蘇生ガイドライン2020 BLS","url":"https://www.jrc-cpr.org/wp-content/uploads/2022/07/JRC_0017-0046_BLS.pdf"}]},{"id":"112-PM-022","record":{"id":"112-PM-022","choice_explanations":[{"choice":1,"correct":false,"title":"筋肉内注射","explanation":"筋肉内注射では手指衛生と皮膚消毒、清潔な操作を行います。通常、滅菌手袋までを必要とする処置ではありません。"},{"choice":2,"correct":false,"title":"口腔内吸引","explanation":"口腔内は無菌ではなく、通常は清潔な手袋を用います。下気道への吸引の無菌操作と区別します。"},{"choice":3,"correct":false,"title":"ストーマパウチの交換","explanation":"ストーマパウチ交換は排泄物との接触を防ぐ清潔な手袋を使います。通常、滅菌手袋は必要ありません。"},{"choice":4,"correct":true,"title":"尿道カテーテルの挿入","explanation":"無菌である尿路に細菌を持ち込まないよう、尿道カテーテル挿入には滅菌手袋を用いて無菌操作を行います。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答4を照合。無菌である尿路に細菌を持ち込まないよう、尿道カテーテル挿入には滅菌手袋を用いて無菌操作を行います。","fixes_made":[]},"input_anchor":{"question":"看護師が行う処置で滅菌手袋を使用すべきなのはどれか。","choices":["筋肉内注射","口腔内吸引","ストーマパウチの交換","尿道カテーテルの挿入"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":22,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[12],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B022"},"exam":112,"year":2023,"session":"PM","number":22},"sources":[]},{"id":"112-PM-023","record":{"id":"112-PM-023","choice_explanations":[{"choice":1,"correct":true,"title":"15〜20 度","explanation":"皮膚に対して15〜20度程度の浅い角度で刺入します。血管の走行と深さを確認し、後壁の穿刺を避けます。"},{"choice":2,"correct":false,"title":"35〜40 度","explanation":"35〜40度は静脈採血としては深すぎます。血管を突き抜け、血腫を生じるおそれがあります。"},{"choice":3,"correct":false,"title":"55〜60 度","explanation":"55〜60度は浅い皮下静脈への穿刺に適しません。採血ではもっと小さな角度を用います。"},{"choice":4,"correct":false,"title":"75〜80 度","explanation":"75〜80度はほぼ垂直で、静脈採血には不適切です。血管や周辺組織の損傷につながります。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1を照合。皮膚に対して15〜20度程度の浅い角度で刺入します。血管の走行と深さを確認し、後壁の穿刺を避けます。","fixes_made":[]},"input_anchor":{"question":"静脈血採血の穿刺時の皮膚に対する針の適切な刺入角度はどれか。","choices":["15〜20 度","35〜40 度","55〜60 度","75〜80 度"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":23,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[12],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B023"},"exam":112,"year":2023,"session":"PM","number":23},"sources":[]},{"id":"112-PM-024","record":{"id":"112-PM-024","choice_explanations":[{"choice":1,"correct":false,"title":"40〜 60 回/分","explanation":"40〜60回/分は遅すぎ、必要な血流を維持しにくくなります。推奨されるテンポを保ちます。"},{"choice":2,"correct":false,"title":"70〜 90 回/分","explanation":"70〜90回/分も成人BLSの推奨より遅いテンポです。100〜120回/分を目安とします。"},{"choice":3,"correct":true,"title":"100〜120 回/分","explanation":"成人の胸骨圧迫は100〜120回/分のテンポで行います。適切な深さ、胸郭の戻り、中断を減らすことも重要です。"},{"choice":4,"correct":false,"title":"130〜150 回/分","explanation":"130〜150回/分は速すぎ、圧迫が浅くなったり胸郭の戻りが不十分になったりするおそれがあります。"}],"status":"VERIFIED","review_reason":"問題・全選択肢・公式正答3を照合。成人の胸骨圧迫は100〜120回/分のテンポで行います。適切な深さ、胸郭の戻り、中断を減らすことも重要です。","fixes_made":[]},"input_anchor":{"question":"成人の一次救命処置〈BLS〉における胸骨圧迫の速さ(回数)で正しいのはどれか。","choices":["40〜 60 回/分","70〜 90 回/分","100〜120 回/分","130〜150 回/分"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":24,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[12],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B024"},"exam":112,"year":2023,"session":"PM","number":24},"sources":[{"title":"日本赤十字社 一次救命処置","url":"https://www.jrc.or.jp/about/publication/news/200819_006353.html"}]},{"id":"112-PM-026","record":{"id":"112-PM-026","choice_explanations":[{"choice":1,"correct":false,"title":"僧帽弁は開いている。","explanation":"等容性収縮期は僧帽弁が閉じた後です。房室弁と半月弁の両方が閉じているため心室容積は変化しません。"},{"choice":2,"correct":false,"title":"大動脈弁は開いている。","explanation":"大動脈弁が開くのは左室圧が大動脈圧を上回った後です。開くと駆出が始まり、心室容積が減少します。"},{"choice":3,"correct":false,"title":"左心室の容積は最小である。","explanation":"この時期は拡張末期の血液を保っており、左室容積は最大です。最小となるのは駆出終了後です。"},{"choice":4,"correct":true,"title":"左心室の内圧は大動脈圧よりも低い。","explanation":"等容性収縮期には左室圧は上昇中ですが、大動脈圧よりまだ低い状態です。上回ると大動脈弁が開きます。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答4を照合。等容性収縮期には左室圧は上昇中ですが、大動脈圧よりまだ低い状態です。上回ると大動脈弁が開きます。","fixes_made":[]},"input_anchor":{"question":"心周期に伴う心臓の変化で、収縮期の初期には心室の容積は変わらずに内圧が上\n昇していく。\nこのときの心臓で正しいのはどれか。","choices":["僧帽弁は開いている。","大動脈弁は開いている。","左心室の容積は最小である。","左心室の内圧は大動脈圧よりも低い。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":26,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[13],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B026"},"exam":112,"year":2023,"session":"PM","number":26},"sources":[]},{"id":"112-PM-027","record":{"id":"112-PM-027","choice_explanations":[{"choice":1,"correct":false,"title":"成人の胸管を流れる量は1日約 10 L である。","explanation":"胸管の通常の流量を1日約10Lとはしません。リンパ流量は条件で変わりますが、一般に1日数L程度として学びます。"},{"choice":2,"correct":false,"title":"右上半身のリンパは胸管に流入する。","explanation":"右上半身のリンパは主に右リンパ本幹を経て右静脈角に入ります。胸管はそれ以外の広い領域を集めます。"},{"choice":3,"correct":false,"title":"中枢から末梢への一方向に流れる。","explanation":"リンパは末梢から中枢の静脈へ向かって流れます。リンパ管の弁が逆流を防ぎます。"},{"choice":4,"correct":true,"title":"筋運動を行うと流量は増加する。","explanation":"骨格筋の収縮がリンパ管を圧迫し、弁の働きとともに中枢への流れを促進します。筋運動でリンパ流量は増えます。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答4を照合。骨格筋の収縮がリンパ管を圧迫し、弁の働きとともに中枢への流れを促進します。筋運動でリンパ流量は増えます。","fixes_made":[]},"input_anchor":{"question":"リンパの流れで正しいのはどれか。","choices":["成人の胸管を流れる量は1日約 10 L である。","右上半身のリンパは胸管に流入する。","中枢から末梢への一方向に流れる。","筋運動を行うと流量は増加する。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":27,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[14],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B027"},"exam":112,"year":2023,"session":"PM","number":27},"sources":[]},{"id":"112-PM-028","record":{"id":"112-PM-028","choice_explanations":[{"choice":1,"correct":false,"title":"ウイルス感染が主な病因である。","explanation":"肥大型心筋症では心筋蛋白の遺伝子異常などが関係します。ウイルス感染は心筋炎で代表的に問題となります。"},{"choice":2,"correct":true,"title":"拡張障害が問題となる。","explanation":"肥厚した心筋は十分に弛緩しにくく、左室への充満を妨げます。拡張障害が重要な病態です。"},{"choice":3,"correct":false,"title":"左室内腔は拡大する。","explanation":"典型例では肥厚により左室内腔が狭くなります。心室拡大を主徴とする拡張型心筋症とは区別します。"},{"choice":4,"correct":false,"title":"弁膜に肥厚を認める。","explanation":"中心となる異常は心筋の肥厚です。弁膜の肥厚を主徴とする病気ではありません。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答2を照合。肥厚した心筋は十分に弛緩しにくく、左室への充満を妨げます。拡張障害が重要な病態です。","fixes_made":[]},"input_anchor":{"question":"肥大型心筋症について正しいのはどれか。\nhypertrophic cardiomyopathy","choices":["ウイルス感染が主な病因である。","拡張障害が問題となる。","左室内腔は拡大する。","弁膜に肥厚を認める。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":28,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[14],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B028"},"exam":112,"year":2023,"session":"PM","number":28},"sources":[]},{"id":"112-PM-029","record":{"id":"112-PM-029","choice_explanations":[{"choice":1,"correct":false,"title":"原因はウイルス感染が多い。","explanation":"歯周病は主に歯垢中の細菌に対する炎症です。ウイルス感染を主な原因とする説明は不適切です。"},{"choice":2,"correct":false,"title":"発症の直接因子として飲酒がある。","explanation":"直接の原因は歯垢中の細菌です。飲酒などの生活習慣の影響と、発症の直接因子を区別します。"},{"choice":3,"correct":true,"title":"真性ポケットが形成される歯周炎を含む。\nperiodontitis","explanation":"歯周病には歯肉炎と歯周炎が含まれます。歯周炎では付着の喪失により真性の歯周ポケットができます。"},{"choice":4,"correct":false,"title":"破壊が歯槽骨まで及んでいるのは歯肉炎である。\ngingivitis","explanation":"歯槽骨の破壊まで及ぶのは歯周炎です。歯肉炎は炎症が歯肉に限局し、歯槽骨の破壊を伴いません。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答3を照合。歯周病には歯肉炎と歯周炎が含まれます。歯周炎では付着の喪失により真性の歯周ポケットができます。","fixes_made":[]},"input_anchor":{"question":"歯周病について正しいのはどれか。\nperiodontal disease","choices":["原因はウイルス感染が多い。","発症の直接因子として飲酒がある。","真性ポケットが形成される歯周炎を含む。\nperiodontitis","破壊が歯槽骨まで及んでいるのは歯肉炎である。\ngingivitis"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":29,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[14],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B029"},"exam":112,"year":2023,"session":"PM","number":29},"sources":[]},{"id":"112-PM-030","record":{"id":"112-PM-030","choice_explanations":[{"choice":1,"correct":false,"title":"運動神経麻痺は生じない。","explanation":"帯状疱疹では感覚症状だけでなく、顔面神経麻痺など運動神経障害を伴うこともあります。生じないとはいえません。"},{"choice":2,"correct":true,"title":"感染の既往として水痘がある。\nvaricella","explanation":"水痘に感染した後、神経節に潜伏した水痘・帯状疱疹ウイルスが再活性化して発症します。初感染は水痘です。"},{"choice":3,"correct":false,"title":"ウイルスは発症後1か月で消滅する。","explanation":"ウイルスは神経節に潜伏します。皮疹が治った後1か月で体内から消滅するわけではありません。"},{"choice":4,"correct":false,"title":"単純ヘルペスウイルスの感染が原因である。","explanation":"原因は水痘・帯状疱疹ウイルスです。口唇ヘルペスなどを起こす単純ヘルペスウイルスとは異なります。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答2を照合。水痘に感染した後、神経節に潜伏した水痘・帯状疱疹ウイルスが再活性化して発症します。初感染は水痘です。","fixes_made":[]},"input_anchor":{"question":"帯状疱疹について正しいのはどれか。\nherpes zoster","choices":["運動神経麻痺は生じない。","感染の既往として水痘がある。\nvaricella","ウイルスは発症後1か月で消滅する。","単純ヘルペスウイルスの感染が原因である。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":30,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[14],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B030"},"exam":112,"year":2023,"session":"PM","number":30},"sources":[]},{"id":"112-PM-031","record":{"id":"112-PM-031","choice_explanations":[{"choice":1,"correct":false,"title":"人口動態調査では合計特殊出生率が 1.54 である。","explanation":"2020年の合計特殊出生率は1.33です。1.54は指定年の値ではなく、出生数そのものとも区別します。"},{"choice":2,"correct":false,"title":"労働力調査では共働き世帯が専業主婦世帯より少ない。","explanation":"共働き世帯は専業主婦世帯を上回っています。世帯数の比較は、共働きと専業主婦の定義をそろえて読みます。"},{"choice":3,"correct":false,"title":"人口動態調査では結婚後5年未満の離婚が約半数である。","explanation":"同居期間5年未満の離婚は全体の約半数ではありません。結婚からの期間別の構成割合を、離婚率と混同しないようにします。"},{"choice":4,"correct":true,"title":"雇用均等基本調査では男性の育児休業取得率が 12.65 % である。","explanation":"2020年度の雇用均等基本調査では男性の育児休業取得率は12.65％です。女性の取得率や別年度の値とは区別します。"}],"status":"VERIFIED","review_reason":"問題・全選択肢・公式正答4を照合。2020年度の雇用均等基本調査では男性の育児休業取得率は12.65％です。女性の取得率や別年度の値とは区別します。","fixes_made":[]},"input_anchor":{"question":"令和2年度(2020 年度)の家族に関する調査で正しいのはどれか。","choices":["人口動態調査では合計特殊出生率が 1.54 である。","労働力調査では共働き世帯が専業主婦世帯より少ない。","人口動態調査では結婚後5年未満の離婚が約半数である。","雇用均等基本調査では男性の育児休業取得率が 12.65 % である。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":31,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[15],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B031"},"exam":112,"year":2023,"session":"PM","number":31},"sources":[{"title":"厚生労働省 男女の育児休業取得率の状況","url":"https://www.mhlw.go.jp/content/11901000/001101169.pdf"}]},{"id":"112-PM-032","record":{"id":"112-PM-032","choice_explanations":[{"choice":1,"correct":true,"title":"医療扶助 医療にかかる費用","explanation":"医療扶助は診察、薬剤、治療、入院など必要な医療にかかる費用を対象とします。原則として現物給付です。"},{"choice":2,"correct":false,"title":"教育扶助 高等学校以上の教育にかかる費用","explanation":"教育扶助は義務教育に必要な費用が対象です。高校就学に必要な費用は一定条件で生業扶助により扱われます。"},{"choice":3,"correct":false,"title":"住宅扶助 住宅の購入にかかる費用","explanation":"住宅扶助は家賃や必要な補修などを対象とします。住宅購入資金を給付する制度ではありません。"},{"choice":4,"correct":false,"title":"出産扶助 新生児の育児用品にかかる費用","explanation":"出産扶助は分娩介助や出産に必要な処置などが対象です。新生児の日常的な育児用品の費用全般を指すものではありません。"}],"status":"VERIFIED","review_reason":"問題・全選択肢・公式正答1を照合。医療扶助は診察、薬剤、治療、入院など必要な医療にかかる費用を対象とします。原則として現物給付です。","fixes_made":[]},"input_anchor":{"question":"生活保護法の扶助の種類とその内容の組合せで正しいのはどれか。","choices":["医療扶助 医療にかかる費用","教育扶助 高等学校以上の教育にかかる費用","住宅扶助 住宅の購入にかかる費用","出産扶助 新生児の育児用品にかかる費用"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":32,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[15],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B032"},"exam":112,"year":2023,"session":"PM","number":32},"sources":[{"title":"生活保護法","url":"https://www.mhlw.go.jp/web/t_doc?dataId=82048000&dataType=0"}]},{"id":"112-PM-033","record":{"id":"112-PM-033","choice_explanations":[{"choice":1,"correct":false,"title":"罹患率が高い疾患は有病率が高くなる。","explanation":"有病率は新規発症の頻度だけでなく罹病期間にも左右されます。罹患率が高いだけで有病率も高いとは断定できません。"},{"choice":2,"correct":false,"title":"推計患者数には助産所を利用した者を含む。","explanation":"患者調査の推計患者数は病院と診療所の患者を対象とします。助産所の利用者は含みません。"},{"choice":3,"correct":true,"title":"受療率は人口 10 万人に対する推計患者数である。","explanation":"受療率は、調査日の推計患者数を人口10万人当たりで表した指標です。一定期間の新規発症を表す罹患率とは異なります。"},{"choice":4,"correct":false,"title":"平均在院日数は調査時点で入院している者の在院日数の平均である。","explanation":"平均在院日数は調査対象期間に退院した患者の在院日数から算出します。調査時点の入院患者だけの平均ではありません。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答3を照合。受療率は、調査日の推計患者数を人口10万人当たりで表した指標です。一定期間の新規発症を表す罹患率とは異なります。","fixes_made":[]},"input_anchor":{"question":"健康に関する指標の記述で正しいのはどれか。","choices":["罹患率が高い疾患は有病率が高くなる。","推計患者数には助産所を利用した者を含む。","受療率は人口 10 万人に対する推計患者数である。","平均在院日数は調査時点で入院している者の在院日数の平均である。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":33,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[15],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B033"},"exam":112,"year":2023,"session":"PM","number":33},"sources":[]},{"id":"112-PM-034","record":{"id":"112-PM-034","choice_explanations":[{"choice":1,"correct":false,"title":"摘 便","explanation":"摘便は喀痰吸引等制度で認められた行為には含まれません。制度の研修を受ければすべての医行為ができるわけではありません。"},{"choice":2,"correct":true,"title":"喀痰吸引","explanation":"所定の研修や医師の指示、医療職との連携などの条件を満たせば、介護福祉士は喀痰吸引等を実施できます。"},{"choice":3,"correct":false,"title":"血糖測定","explanation":"穿刺を伴う血糖測定は、この制度で認められた喀痰吸引等の範囲ではありません。本人による測定への補助とは区別します。"},{"choice":4,"correct":false,"title":"インスリン注射","explanation":"インスリンを他者に注射することは、この制度で介護福祉士に認められた行為ではありません。"}],"status":"VERIFIED","review_reason":"問題・全選択肢・公式正答2を照合。所定の研修や医師の指示、医療職との連携などの条件を満たせば、介護福祉士は喀痰吸引等を実施できます。","fixes_made":[]},"input_anchor":{"question":"介護保険法と社会福祉士及び介護福祉士法に基づき、介護福祉士が一定の条件を\n満たす場合に実施できる医行為はどれか。","choices":["摘 便","喀痰吸引","血糖測定","インスリン注射"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":34,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[15],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B034"},"exam":112,"year":2023,"session":"PM","number":34},"sources":[{"title":"厚生労働省 喀痰吸引等制度","url":"https://www.mhlw.go.jp/stf/seisakunitsuite/bunya/hukushi_kaigo/seikatsuhogo/tannokyuuin/index.html"}]},{"id":"112-PM-036","record":{"id":"112-PM-036","choice_explanations":[{"choice":1,"correct":false,"title":"採血時に手袋を着用する。","explanation":"手袋は血液接触の防護に必要ですが、針が刺さること自体を防ぐものではありません。鋭利物の安全な扱いが必要です。"},{"choice":2,"correct":false,"title":"採血部位をアルコールで消毒する。","explanation":"皮膚消毒は穿刺部の感染予防です。使用後の針による針刺し事故を防ぐ対策ではありません。"},{"choice":3,"correct":false,"title":"抜針した採血針はキャップをして破棄する。","explanation":"使用後の針をリキャップすると手指を刺す危険があります。原則としてそのまま専用容器に廃棄します。"},{"choice":4,"correct":true,"title":"針専用の廃棄容器は容量が8割程度に達したら処分する。","explanation":"容器を満杯にせず、規定の充填線や8割程度を目安に交換します。針の突出や廃棄時の接触を防ぎます。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答4を照合。容器を満杯にせず、規定の充填線や8割程度を目安に交換します。針の突出や廃棄時の接触を防ぎます。","fixes_made":[]},"input_anchor":{"question":"針刺し事故を防止する方法で適切なのはどれか。","choices":["採血時に手袋を着用する。","採血部位をアルコールで消毒する。","抜針した採血針はキャップをして破棄する。","針専用の廃棄容器は容量が8割程度に達したら処分する。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":36,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[16],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B036"},"exam":112,"year":2023,"session":"PM","number":36},"sources":[]},{"id":"112-PM-037","record":{"id":"112-PM-037","choice_explanations":[{"choice":1,"correct":false,"title":"Sims〈シムス〉位 腰背部","explanation":"シムス位では胸腹部や屈曲した上側の下肢などを支えます。腰背部に枕を入れる組合せは代表的ではありません。"},{"choice":2,"correct":true,"title":"側臥位 胸腹部","explanation":"側臥位で胸腹部側を枕で支えると、体幹が前に倒れるのを防ぎ、上肢の安楽も得やすくなります。"},{"choice":3,"correct":false,"title":"半座位 前胸部","explanation":"半座位では背部や膝下などを支えてずれや筋緊張を減らします。前胸部の枕はこの体位の標準的な支持位置ではありません。"},{"choice":4,"correct":false,"title":"腹臥位 膝窩部","explanation":"腹臥位では腹部や下腿などを支えます。膝窩部に入れるのは仰臥位などで膝を軽く曲げる際の支持です。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答2を照合。側臥位で胸腹部側を枕で支えると、体幹が前に倒れるのを防ぎ、上肢の安楽も得やすくなります。","fixes_made":[]},"input_anchor":{"question":"安楽な姿勢を保持する体位と枕を挿入する位置の組合せで適切なのはどれか。","choices":["Sims〈シムス〉位 腰背部","側臥位 胸腹部","半座位 前胸部","腹臥位 膝窩部"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":37,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[16],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B037"},"exam":112,"year":2023,"session":"PM","number":37},"sources":[]},{"id":"112-PM-038","record":{"id":"112-PM-038","choice_explanations":[{"choice":1,"correct":false,"title":"灰白色便 Crohn〈クローン〉病\nCrohn disease","explanation":"灰白色便は胆道閉塞などで胆汁色素が腸管に届かないときにみられます。クローン病の代表的便性状ではありません。"},{"choice":2,"correct":false,"title":"鮮紅色便 鉄剤の内服","explanation":"鉄剤の内服で便は黒くなることがあります。鮮紅色便は下部消化管出血などを疑う所見です。"},{"choice":3,"correct":true,"title":"タール便 上部消化管出血","explanation":"上部消化管の血液が消化されると、黒く粘りのあるタール便になります。出血量や循環状態の確認が必要です。"},{"choice":4,"correct":false,"title":"米のとぎ汁様便 急性膵炎\nacute pancreatitis","explanation":"米のとぎ汁様の大量水様便はコレラで特徴的です。急性膵炎の代表所見ではありません。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答3を照合。上部消化管の血液が消化されると、黒く粘りのあるタール便になります。出血量や循環状態の確認が必要です。","fixes_made":[]},"input_anchor":{"question":"便の性状と原因の組合せで正しいのはどれか。","choices":["灰白色便 Crohn〈クローン〉病\nCrohn disease","鮮紅色便 鉄剤の内服","タール便 上部消化管出血","米のとぎ汁様便 急性膵炎\nacute pancreatitis"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":38,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[16],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B038"},"exam":112,"year":2023,"session":"PM","number":38},"sources":[]},{"id":"112-PM-040","record":{"id":"112-PM-040","choice_explanations":[{"choice":1,"correct":false,"title":"マクロファージが創内を清浄化する。","explanation":"マクロファージによる異物や壊死組織の除去は主に炎症期の働きです。成熟期の中心的な変化ではありません。"},{"choice":2,"correct":false,"title":"基底細胞が創面を覆う。","explanation":"基底細胞などによる上皮化は主に増殖期に進みます。創面を覆って皮膚の連続性を回復させます。"},{"choice":3,"correct":false,"title":"肉芽組織を形成する。","explanation":"肉芽組織の形成は増殖期に起こります。毛細血管や線維芽細胞が増え、組織の欠損を埋めます。"},{"choice":4,"correct":true,"title":"瘢痕を形成する。","explanation":"成熟期はコラーゲンの再構築が進み、血管が減って瘢痕が成熟します。創の強度も徐々に増します。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答4を照合。成熟期はコラーゲンの再構築が進み、血管が減って瘢痕が成熟します。創の強度も徐々に増します。","fixes_made":[]},"input_anchor":{"question":"創傷治癒の成熟期の状態はどれか。","choices":["マクロファージが創内を清浄化する。","基底細胞が創面を覆う。","肉芽組織を形成する。","瘢痕を形成する。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":40,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[17],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B040"},"exam":112,"year":2023,"session":"PM","number":40},"sources":[]},{"id":"112-PM-041","record":{"id":"112-PM-041","choice_explanations":[{"choice":1,"correct":false,"title":"筋肉内注射は大殿筋に行う。","explanation":"殿部の筋肉内注射では坐骨神経などの損傷を避ける部位選択が必要です。大殿筋に行うと一律に指定するのは不適切です。"},{"choice":2,"correct":false,"title":"坐薬は肛門から1cm 挿入する。","explanation":"成人では肛門括約筋を越えて入れる必要があります。1cmでは浅く、坐薬が外へ出やすくなります。"},{"choice":3,"correct":false,"title":"バッカル錠は、かんでから飲み込む。","explanation":"バッカル錠は頬粘膜と歯肉の間などで溶かし、粘膜から吸収させます。かんで飲み込む薬ではありません。"},{"choice":4,"correct":true,"title":"点眼薬は下眼瞼結膜の中央に滴下する。","explanation":"下眼瞼を軽く下げ、結膜嚢へ滴下します。容器の先が眼やまつ毛に触れないようにし、角膜への直接滴下を避けます。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答4を照合。下眼瞼を軽く下げ、結膜嚢へ滴下します。容器の先が眼やまつ毛に触れないようにし、角膜への直接滴下を避けます。","fixes_made":[]},"input_anchor":{"question":"成人への与薬方法で正しいのはどれか。","choices":["筋肉内注射は大殿筋に行う。","坐薬は肛門から1cm 挿入する。","バッカル錠は、かんでから飲み込む。","点眼薬は下眼瞼結膜の中央に滴下する。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":41,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[18],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B041"},"exam":112,"year":2023,"session":"PM","number":41},"sources":[]},{"id":"112-PM-042","record":{"id":"112-PM-042","choice_explanations":[{"choice":1,"correct":true,"title":"胸部が濡れている場合は電極パッドを貼る前に拭き取る。","explanation":"濡れた胸部は拭き、パッドを密着させます。水分による電流の漏れや接着不良を防ぎます。"},{"choice":2,"correct":false,"title":"電極パッドは左前胸部に並べて貼る。","explanation":"一般に右前胸部と左側胸部に貼り、心臓を挟む配置にします。左前胸部に並べる配置ではありません。"},{"choice":3,"correct":false,"title":"心電図の解析中にも胸骨圧迫を継続する。","explanation":"解析中は体動による誤判定を避けるため、胸骨圧迫を止め患者に触れません。AEDの指示に従います。"},{"choice":4,"correct":false,"title":"心拍が再開されたら電極パッドを直ちにはがす。","explanation":"再び心停止する可能性があるため、心拍再開後もパッドを付けたまま観察し救急隊へ引き継ぎます。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1を照合。濡れた胸部は拭き、パッドを密着させます。水分による電流の漏れや接着不良を防ぎます。","fixes_made":[]},"input_anchor":{"question":"成人に対する自動体外式除細動器〈AED〉の使用で正しいのはどれか。","choices":["胸部が濡れている場合は電極パッドを貼る前に拭き取る。","電極パッドは左前胸部に並べて貼る。","心電図の解析中にも胸骨圧迫を継続する。","心拍が再開されたら電極パッドを直ちにはがす。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":42,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[18],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B042"},"exam":112,"year":2023,"session":"PM","number":42},"sources":[]},{"id":"112-PM-043","record":{"id":"112-PM-043","choice_explanations":[{"choice":1,"correct":false,"title":"頻 脈","explanation":"頻脈だけで必ず測定値が不正確になるわけではありません。脈波が安定して検出できるかを確認します。"},{"choice":2,"correct":false,"title":"高血圧","explanation":"高血圧そのものは、選択肢の中で代表的な測定誤差の原因ではありません。装着状態と末梢の脈波を確認します。"},{"choice":3,"correct":false,"title":"高体温","explanation":"高体温だけでSpO2測定が妨げられるとはいえません。体動や循環状態などの影響を併せて評価します。"},{"choice":4,"correct":true,"title":"末梢循環不全","explanation":"末梢循環不全では拍動成分を検出しにくく、値が不安定・不正確になります。指先の冷感や脈波も確認します。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答4を照合。末梢循環不全では拍動成分を検出しにくく、値が不安定・不正確になります。指先の冷感や脈波も確認します。","fixes_made":[]},"input_anchor":{"question":"経皮的動脈血酸素飽和度〈SpO2〉の測定値に影響を及ぼすのはどれか。","choices":["頻 脈","高血圧","高体温","末梢循環不全"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":43,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[18],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B043"},"exam":112,"year":2023,"session":"PM","number":43},"sources":[]},{"id":"112-PM-044","record":{"id":"112-PM-044","choice_explanations":[{"choice":1,"correct":false,"title":"頸部の伸展","explanation":"頸部の過度な伸展は頸部神経への負担になり得ますが、薬指・小指のしびれは尺骨神経領域の障害を示唆します。"},{"choice":2,"correct":false,"title":"前腕の回内","explanation":"前腕の回内でも肘部の尺骨神経圧迫に関係し得ます。公式正答は3ですが、2を否定できる条件が設問に乏しく、この点は不明として残します。"},{"choice":3,"correct":true,"title":"肩関節の内旋","explanation":"肩関節を内旋した固定では肘の内側が圧迫され、尺骨神経障害を生じる可能性があります。公式正答は3ですが、体位条件の詳しい記載はありません。"},{"choice":4,"correct":false,"title":"肘関節の伸展","explanation":"肘の伸展だけでは本問の尺骨神経領域のしびれを説明する代表的な要因になりません。圧迫部位や固定方法を確認します。"}],"status":"UNKNOWN","review_reason":"公式正答は3。前腕回内も尺骨神経圧迫の要因になり得るため、2を排除できる体位条件を確認できない。選択肢2・3に不明点を明記。","fixes_made":[]},"input_anchor":{"question":"仰臥位で手術を受けた患者が術後に上肢の薬指と小指のしびれを訴えた。\nしびれの原因として考えられるのはどれか。","choices":["頸部の伸展","前腕の回内","肩関節の内旋","肘関節の伸展"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":44,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[18],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B044"},"exam":112,"year":2023,"session":"PM","number":44},"sources":[]},{"id":"112-PM-045","record":{"id":"112-PM-045","choice_explanations":[{"choice":1,"correct":true,"title":"言語聴覚士","explanation":"言語聴覚士は摂食・嚥下機能を評価し、姿勢、食形態、訓練などを検討します。経口摂取を続けたい本人の希望への連携で優先されます。"},{"choice":2,"correct":false,"title":"作業療法士","explanation":"作業療法士は日常生活動作や上肢機能などを支援します。今回の中心課題である嚥下評価には言語聴覚士が適します。"},{"choice":3,"correct":false,"title":"理学療法士","explanation":"理学療法士は基本動作や呼吸・運動機能の支援に関わります。経口摂取の安全性の直接評価では言語聴覚士が優先です。"},{"choice":4,"correct":false,"title":"介護支援専門員","explanation":"介護支援専門員は在宅サービスを調整します。重要な連携相手ですが、まず嚥下機能と経口摂取の可能性を評価します。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1を照合。言語聴覚士は摂食・嚥下機能を評価し、姿勢、食形態、訓練などを検討します。経口摂取を続けたい本人の希望への連携で優先されます。","fixes_made":[]},"input_anchor":{"question":"A さん(58 歳)は筋萎縮性側索硬化症〈ALS〉で在宅療養をしている。嚥下機能の\namyotrophic lateral sclerosis\n低下が進行したため入院し、胃瘻の造設が検討されているが、経口摂取の継続を希\n望している。\n看護師が連携する職種で優先度が高いのはどれか。","choices":["言語聴覚士","作業療法士","理学療法士","介護支援専門員"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":45,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[19],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B045"},"exam":112,"year":2023,"session":"PM","number":45},"sources":[]},{"id":"112-PM-046","record":{"id":"112-PM-046","choice_explanations":[{"choice":1,"correct":true,"title":"顔を横に向ける。","explanation":"顔を横に向けるなど体位を調整すると、咽頭の分泌物が排出されやすくなります。家族には死前喘鳴の仕組みも説明します。"},{"choice":2,"correct":false,"title":"気管支拡張薬を用いる。","explanation":"咽頭にたまった分泌物による音は気管支攣縮とは異なります。気管支拡張薬を直ちに用いる根拠はありません。"},{"choice":3,"correct":false,"title":"口腔内をガーゼで拭く。","explanation":"口腔ケアは乾燥や汚れに有用ですが、咽頭に貯留した分泌物への対応としては体位調整が優先されます。"},{"choice":4,"correct":false,"title":"雑音が消失するまで吸引する。","explanation":"音が消えるまで繰り返す吸引は苦痛や粘膜損傷を招きます。音だけで苦痛を判断せず、必要性を慎重に検討します。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1を照合。顔を横に向けるなど体位を調整すると、咽頭の分泌物が排出されやすくなります。家族には死前喘鳴の仕組みも説明します。","fixes_made":[]},"input_anchor":{"question":"臨死期にある患者の家族から｢のどがゴロゴロと鳴っていて苦しんでいます。こ\nの苦痛をとってあげたい｣と相談された。看護師が、呼吸音を聴取すると咽頭に雑\n音を認めた。\n患者の苦痛を緩和するための対応で適切なのはどれか。","choices":["顔を横に向ける。","気管支拡張薬を用いる。","口腔内をガーゼで拭く。","雑音が消失するまで吸引する。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":46,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[19],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B046"},"exam":112,"year":2023,"session":"PM","number":46},"sources":[]},{"id":"112-PM-047","record":{"id":"112-PM-047","choice_explanations":[{"choice":1,"correct":false,"title":"糖尿病の患者への投与は禁忌である。\ndiabetes mellitus","explanation":"糖尿病があるだけで吸入ステロイドが禁忌になるわけではありません。投与量や血糖などを評価して使用します。"},{"choice":2,"correct":false,"title":"副作用(有害事象)に不整脈がある。","explanation":"吸入ステロイドでは口腔カンジダ症や嗄声などが代表的です。不整脈は気管支拡張薬などで注意する有害事象と区別します。"},{"choice":3,"correct":false,"title":"重積発作の際に使用する。","explanation":"吸入ステロイドは主に気道炎症を抑える長期管理薬です。重積発作の迅速な解除を単独で担う薬ではありません。"},{"choice":4,"correct":true,"title":"吸入後は含嗽を促す。","explanation":"吸入後にうがいをして口腔内に残った薬剤を除き、口腔カンジダ症や嗄声などを予防します。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答4を照合。吸入後にうがいをして口腔内に残った薬剤を除き、口腔カンジダ症や嗄声などを予防します。","fixes_made":[]},"input_anchor":{"question":"成人の気管支喘息に対する副腎皮質ステロイド薬の吸入で正しいのはどれか。\nbronchial asthma","choices":["糖尿病の患者への投与は禁忌である。\ndiabetes mellitus","副作用(有害事象)に不整脈がある。","重積発作の際に使用する。","吸入後は含嗽を促す。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":47,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[19],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B047"},"exam":112,"year":2023,"session":"PM","number":47},"sources":[]},{"id":"112-PM-048","record":{"id":"112-PM-048","choice_explanations":[{"choice":1,"correct":true,"title":"アミラーゼ〈AMY〉","explanation":"ERCP後の心窩部痛では急性膵炎を疑います。アミラーゼなど膵酵素の上昇を症状と併せて評価します。"},{"choice":2,"correct":false,"title":"アルブミン〈Alb〉","explanation":"アルブミンは栄養状態や肝合成能などを反映します。ERCP直後の急性膵炎の判断に最も直接的な項目ではありません。"},{"choice":3,"correct":false,"title":"カリウム〈K〉","explanation":"カリウムは電解質異常の評価に重要ですが、ERCP後膵炎を特異的に示す指標ではありません。"},{"choice":4,"correct":false,"title":"クレアチンキナーゼ〈CK〉","explanation":"CKは骨格筋や心筋の障害などで上昇します。膵炎を判断する検査としてはアミラーゼが適します。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1を照合。ERCP後の心窩部痛では急性膵炎を疑います。アミラーゼなど膵酵素の上昇を症状と併せて評価します。","fixes_made":[]},"input_anchor":{"question":"A さん(43 歳、男性)は胆道狭窄のため内視鏡的逆行性胆管膵管造影〈ERCP〉検査\nを受けた。検査後に心窩部痛が出現したため血液検査を行い、禁食、抗菌薬および\n蛋白分解酵素阻害薬による治療を行うことになった。\n血液検査の項目で A さんに生じた合併症を判断できるのはどれか。","choices":["アミラーゼ〈AMY〉","アルブミン〈Alb〉","カリウム〈K〉","クレアチンキナーゼ〈CK〉"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":48,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[20],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B048"},"exam":112,"year":2023,"session":"PM","number":48},"sources":[]},{"id":"112-PM-049","record":{"id":"112-PM-049","choice_explanations":[{"choice":1,"correct":false,"title":"12 時間後","explanation":"12時間では遅延型反応を評価するには早すぎます。パッチテストは即時型アレルギー検査と異なります。"},{"choice":2,"correct":false,"title":"24 時間後","explanation":"24時間後だけでは反応が十分に現れないことがあります。通常は48時間後以降に判定します。"},{"choice":3,"correct":false,"title":"36 時間後","explanation":"36時間後は標準的な初回判定時点ではありません。貼付後48時間を目安に除去・判定します。"},{"choice":4,"correct":true,"title":"48 時間後","explanation":"遅延型アレルギーをみる検査で、通常48時間後に判定します。遅れて出る反応をみるため、その後にも判定を行います。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答4を照合。遅延型アレルギーをみる検査で、通常48時間後に判定します。遅れて出る反応をみるため、その後にも判定を行います。","fixes_made":[]},"input_anchor":{"question":"パッチテストで皮膚反応を観察するタイミングはどれか。","choices":["12 時間後","24 時間後","36 時間後","48 時間後"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":49,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[20],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B049"},"exam":112,"year":2023,"session":"PM","number":49},"sources":[]},{"id":"112-PM-050","record":{"id":"112-PM-050","choice_explanations":[{"choice":1,"correct":false,"title":"緑内障\nglaucoma","explanation":"緑内障はステロイドなどで注意する副作用です。本問でシクロホスファミドに特徴的なものは出血性膀胱炎です。"},{"choice":2,"correct":false,"title":"間質性肺炎\ninterstitial pneumonia","explanation":"間質性肺炎もシクロホスファミドの重大な副作用として記載されています。公式正答は4ですが、2を誤りと断定できる理由は不明です。"},{"choice":3,"correct":false,"title":"歯肉の肥厚","explanation":"歯肉増殖はフェニトインや一部の免疫抑制薬などで知られます。シクロホスファミドの特徴的副作用ではありません。"},{"choice":4,"correct":true,"title":"出血性膀胱炎\nhemorrhagic cystitis","explanation":"尿中に排泄される代謝物が膀胱粘膜を障害し、出血性膀胱炎を起こします。血尿・排尿症状の観察が重要です。公式正答は4です。"}],"status":"UNKNOWN","review_reason":"公式正答は4。PMDAのシクロホスファミド情報には間質性肺炎も掲載され、2を誤りと断定できない。該当解説に不明点を明記。","fixes_made":[]},"input_anchor":{"question":"シクロホスファミドを投与している患者で注意が必要なのはどれか。","choices":["緑内障\nglaucoma","間質性肺炎\ninterstitial pneumonia","歯肉の肥厚","出血性膀胱炎\nhemorrhagic cystitis"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":50,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[20],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B050"},"exam":112,"year":2023,"session":"PM","number":50},"sources":[{"title":"PMDA 注射用エンドキサン くすり情報","url":"https://www.pmda.go.jp/PmdaSearch/rdDetail/iyaku/4211401D1033_1?user=2"}]},{"id":"112-PM-051","record":{"id":"112-PM-051","choice_explanations":[{"choice":1,"correct":true,"title":"｢子宮頸部の細胞をこすり取って検査します｣","explanation":"子宮頸部から採取した細胞を用い、高リスクHPVの核酸などを調べます。細胞診とは調べる対象が異なります。"},{"choice":2,"correct":false,"title":"｢HPV ワクチンを接種した人が対象です｣","explanation":"ワクチン接種者だけを対象とする検査ではありません。検査目的や年齢などに応じて適応を判断します。"},{"choice":3,"correct":false,"title":"｢陽性であれば子宮頸癌と診断されます｣\ncancer of the uterine cervix","explanation":"陽性はHPV感染を示しますが、それだけで子宮頸癌とは診断できません。必要に応じ細胞診や精密検査を行います。"},{"choice":4,"correct":false,"title":"｢HPV 抗原検査も同時に行います｣","explanation":"一般的なHPV検査はウイルスの核酸を調べます。HPV抗原検査を必ず同時に行うという説明は不適切です。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1を照合。子宮頸部から採取した細胞を用い、高リスクHPVの核酸などを調べます。細胞診とは調べる対象が異なります。","fixes_made":[]},"input_anchor":{"question":"ヒトパピローマウイルス〈HPV〉検査の説明で正しいのはどれか。","choices":["｢子宮頸部の細胞をこすり取って検査します｣","｢HPV ワクチンを接種した人が対象です｣","｢陽性であれば子宮頸癌と診断されます｣\ncancer of the uterine cervix","｢HPV 抗原検査も同時に行います｣"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":51,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[21],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B051"},"exam":112,"year":2023,"session":"PM","number":51},"sources":[]},{"id":"112-PM-052","record":{"id":"112-PM-052","choice_explanations":[{"choice":1,"correct":false,"title":"75 歳以上の通院率は約9割である。","explanation":"75歳以上の通院者率は約7割で、約9割ではありません。通院している人の割合と外来受療率を区別します。"},{"choice":2,"correct":false,"title":"65 歳以上の半数以上が有訴者である。","explanation":"2019年の65歳以上の有訴者率は人口千対433.6で、約43％です。半数以上ではありません。"},{"choice":3,"correct":false,"title":"65 歳以上の外来受療率は年齢が上がるほど高くなる。","explanation":"外来受療率は患者調査の指標です。国民生活基礎調査の通院者率と異なり、年齢上昇に伴う単純な増加とも限りません。"},{"choice":4,"correct":true,"title":"65 歳以上の自覚症状で男女とも最も多いのは腰痛である。","explanation":"65歳以上に限ると、男女とも腰痛が最も多い自覚症状です。女性全体では肩こりが最多であることと区別します。"}],"status":"VERIFIED","review_reason":"問題・全選択肢・公式正答4を照合。65歳以上に限ると、男女とも腰痛が最も多い自覚症状です。女性全体では肩こりが最多であることと区別します。","fixes_made":[]},"input_anchor":{"question":"令和元年(2019 年)の国民生活基礎調査における高齢者の健康状態で正しいのは\nどれか。","choices":["75 歳以上の通院率は約9割である。","65 歳以上の半数以上が有訴者である。","65 歳以上の外来受療率は年齢が上がるほど高くなる。","65 歳以上の自覚症状で男女とも最も多いのは腰痛である。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":52,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[21],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B052"},"exam":112,"year":2023,"session":"PM","number":52},"sources":[{"title":"2019年国民生活基礎調査 健康状況","url":"https://www.mhlw.go.jp/toukei/saikin/hw/k-tyosa/k-tyosa19/dl/04.pdf"}]},{"id":"112-PM-053","record":{"id":"112-PM-053","choice_explanations":[{"choice":1,"correct":true,"title":"単身世帯","explanation":"指定調査では、高齢者の単身世帯で賃貸住宅の割合が最も高くなります。世帯構成ごとの住居の所有関係を比較する問題です。"},{"choice":2,"correct":false,"title":"三世代世帯","explanation":"三世代世帯は単身世帯より持ち家が多い傾向で、賃貸住宅の割合が最も高い区分ではありません。"},{"choice":3,"correct":false,"title":"夫婦のみの世帯","explanation":"夫婦のみの世帯は、単身世帯より賃貸住宅の割合が低い区分です。世帯数そのものの多さとは区別します。"},{"choice":4,"correct":false,"title":"単身の子どもと同居世帯","explanation":"単身の子どもとの同居世帯は、賃貸住宅の割合が最多の区分ではありません。高齢者が一人で住む単身世帯が正答です。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1を照合。指定調査では、高齢者の単身世帯で賃貸住宅の割合が最も高くなります。世帯構成ごとの住居の所有関係を比較する問題です。","fixes_made":[]},"input_anchor":{"question":"平成 30 年度(2018 年度)の高齢者の住宅と生活環境に関する調査で、高齢者がい\nる世帯で賃貸住宅に住んでいる世帯の割合が最も多いのはどれか。","choices":["単身世帯","三世代世帯","夫婦のみの世帯","単身の子どもと同居世帯"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":53,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[21],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B053"},"exam":112,"year":2023,"session":"PM","number":53},"sources":[]},{"id":"112-PM-054","record":{"id":"112-PM-054","choice_explanations":[{"choice":1,"correct":false,"title":"｢介護は楽しいですよ｣","explanation":"介護を楽しいと決めつけると、不安や負担感を話しにくくなります。まず本人が感じていることを聴きます。"},{"choice":2,"correct":false,"title":"｢介護にはすぐに慣れますよ｣","explanation":"すぐ慣れるという保証はできません。初めて介護する人の不安を軽く扱わず、必要な支援を探ります。"},{"choice":3,"correct":false,"title":"｢家族で介護できるよう頑張りましょう｣","explanation":"家族だけで頑張るよう促すと負担を強めます。本人の思いを確認し、介護サービスなども含めて支援を考えます。"},{"choice":4,"correct":true,"title":"｢介護についてどのような思いがありますか｣","explanation":"開かれた質問で介護への思いや不安を聴くことが出発点です。理解度や生活状況に合わせた具体的支援につなげます。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答4を照合。開かれた質問で介護への思いや不安を聴くことが出発点です。理解度や生活状況に合わせた具体的支援につなげます。","fixes_made":[]},"input_anchor":{"question":"A さん(80 歳、女性)は脳梗塞の後遺症のため要介護5と認定され、治療を終え\ncerebral infarction\nて退院することになった。A さんの息子の妻が｢義母が退院したら同居して、私が\n初めて介護することになります｣と不安そうに看護師に話しかけてきた。\nこのときの看護師の対応で適切なのはどれか。","choices":["｢介護は楽しいですよ｣","｢介護にはすぐに慣れますよ｣","｢家族で介護できるよう頑張りましょう｣","｢介護についてどのような思いがありますか｣"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":54,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[22],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B054"},"exam":112,"year":2023,"session":"PM","number":54},"sources":[]},{"id":"112-PM-055","record":{"id":"112-PM-055","choice_explanations":[{"choice":1,"correct":true,"title":"発達は急速な時期と緩慢な時期がある。","explanation":"発達の速度は一定ではなく、急速に進む時期と比較的緩やかな時期があります。領域ごとの進み方にも違いがあります。"},{"choice":2,"correct":false,"title":"原始反射は生後6〜12 か月にみられる。","explanation":"原始反射は出生時からみられ、多くは乳児期前半に減弱・消失します。生後6〜12か月に初めて現れるものではありません。"},{"choice":3,"correct":false,"title":"基本的な運動発達は脚部から上方へ向かう。","explanation":"基本的な運動発達は頭部から尾側へ進みます。首のすわりが座位や立位に先行します。"},{"choice":4,"correct":false,"title":"新生児期は遺伝よりも環境因子の影響が大きい。","explanation":"新生児期は生物学的成熟や遺伝の影響が大きい時期です。成長に伴い環境や経験の影響も広がります。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1を照合。発達の速度は一定ではなく、急速に進む時期と比較的緩やかな時期があります。領域ごとの進み方にも違いがあります。","fixes_made":[]},"input_anchor":{"question":"子どもの発達で正しいのはどれか。","choices":["発達は急速な時期と緩慢な時期がある。","原始反射は生後6〜12 か月にみられる。","基本的な運動発達は脚部から上方へ向かう。","新生児期は遺伝よりも環境因子の影響が大きい。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":55,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[22],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B055"},"exam":112,"year":2023,"session":"PM","number":55},"sources":[]},{"id":"112-PM-056","record":{"id":"112-PM-056","choice_explanations":[{"choice":1,"correct":false,"title":"永久歯より石灰化度が高い。","explanation":"乳歯は永久歯より石灰化度が低く、エナメル質なども薄いため、むし歯が進みやすい特徴があります。"},{"choice":2,"correct":false,"title":"生後8か月に生えそろう。","explanation":"生後8か月は乳歯が生え始めるころに当たります。生えそろうのは通常2歳半〜3歳ごろです。"},{"choice":3,"correct":true,"title":"胎児期に石灰化が始まる。","explanation":"乳歯の形成と石灰化は胎児期から始まります。萌出して口腔内に見える時期より前に歯が作られます。"},{"choice":4,"correct":false,"title":"本数は永久歯と同じである。","explanation":"乳歯は20本、永久歯は親知らずを含めて32本です。同じ本数ではありません。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答3を照合。乳歯の形成と石灰化は胎児期から始まります。萌出して口腔内に見える時期より前に歯が作られます。","fixes_made":[]},"input_anchor":{"question":"乳歯について正しいのはどれか。","choices":["永久歯より石灰化度が高い。","生後8か月に生えそろう。","胎児期に石灰化が始まる。","本数は永久歯と同じである。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":56,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[22],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B056"},"exam":112,"year":2023,"session":"PM","number":56},"sources":[]},{"id":"112-PM-057","record":{"id":"112-PM-057","choice_explanations":[{"choice":1,"correct":true,"title":"3歳ころまでの主要な遊びである。","explanation":"平行遊びは2〜3歳ごろに多く、他児の近くで同じような遊びをしながら各自が遊びます。共同の目標はまだ明確ではありません。"},{"choice":2,"correct":false,"title":"他の子どもが遊ぶ様子を見て楽しむ。","explanation":"他児の遊びを見て楽しむのは傍観遊びです。平行遊びでは子ども自身も近くで遊びます。"},{"choice":3,"correct":false,"title":"リーダーの存在や役割の分担がある。","explanation":"リーダーや役割分担のある遊びは協同遊びです。平行遊びより社会的な協力が進んだ形です。"},{"choice":4,"correct":false,"title":"他の子どもとおもちゃの貸し借りを行う。","explanation":"玩具の貸し借りなど相互のやり取りが増えるのは連合遊びです。平行遊びでは交流が限られます。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1を照合。平行遊びは2〜3歳ごろに多く、他児の近くで同じような遊びをしながら各自が遊びます。共同の目標はまだ明確ではありません。","fixes_made":[]},"input_anchor":{"question":"子どもの平行遊びで正しいのはどれか。","choices":["3歳ころまでの主要な遊びである。","他の子どもが遊ぶ様子を見て楽しむ。","リーダーの存在や役割の分担がある。","他の子どもとおもちゃの貸し借りを行う。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":57,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[23],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B057"},"exam":112,"year":2023,"session":"PM","number":57},"sources":[]},{"id":"112-PM-058","record":{"id":"112-PM-058","choice_explanations":[{"choice":1,"correct":false,"title":"産後の休業","explanation":"産後休業は労働基準法に規定されています。母体保護法の人工妊娠中絶などの規定とは異なります。"},{"choice":2,"correct":false,"title":"妊娠中の女性の危険有害業務の就業制限","explanation":"妊娠中の危険有害業務の就業制限は労働基準法に基づきます。母体保護法の規定ではありません。"},{"choice":3,"correct":false,"title":"妊娠したことを理由とした不利益な取扱いの禁止","explanation":"妊娠等を理由とする不利益取扱いの禁止は男女雇用機会均等法に規定されています。"},{"choice":4,"correct":true,"title":"経済的理由により母体の健康を著しく害するおそれのある場合の人工妊娠中\n絶","explanation":"身体的・経済的理由で母体の健康を著しく害するおそれがある場合の人工妊娠中絶は、母体保護法の規定に該当します。"}],"status":"VERIFIED","review_reason":"問題・全選択肢・公式正答4を照合。身体的・経済的理由で母体の健康を著しく害するおそれがある場合の人工妊娠中絶は、母体保護法の規定に該当します。","fixes_made":[]},"input_anchor":{"question":"母体保護法に規定されているのはどれか。","choices":["産後の休業","妊娠中の女性の危険有害業務の就業制限","妊娠したことを理由とした不利益な取扱いの禁止","経済的理由により母体の健康を著しく害するおそれのある場合の人工妊娠中\n絶"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":58,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[23],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B058"},"exam":112,"year":2023,"session":"PM","number":58},"sources":[{"title":"母体保護法","url":"https://www.mhlw.go.jp/web/t_doc?dataId=80120000&dataType=0"}]},{"id":"112-PM-059","record":{"id":"112-PM-059","choice_explanations":[{"choice":1,"correct":true,"title":"閉経すると腟の自浄作用が低下する。","explanation":"エストロゲン低下により腟上皮のグリコーゲンが減り、乳酸菌による酸性環境が保ちにくくなります。腟の自浄作用は低下します。"},{"choice":2,"correct":false,"title":"閉経後はエストロゲン分泌が増加する。","explanation":"閉経後は卵巣機能の低下によりエストロゲン分泌が減少します。増加するのは主にFSHなどのゴナドトロピンです。"},{"choice":3,"correct":false,"title":"日本人の閉経の平均年齢は 55 歳である。","explanation":"日本人の平均閉経年齢はおおむね50歳前後です。55歳を平均とする説明は不適切です。"},{"choice":4,"correct":false,"title":"10 か月の連続した無月経の確認で診断される。","explanation":"通常は他の原因がない状態で12か月の無月経を確認し、最後の月経を閉経と判断します。10か月ではありません。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1を照合。エストロゲン低下により腟上皮のグリコーゲンが減り、乳酸菌による酸性環境が保ちにくくなります。腟の自浄作用は低下します。","fixes_made":[]},"input_anchor":{"question":"閉経について正しいのはどれか。","choices":["閉経すると腟の自浄作用が低下する。","閉経後はエストロゲン分泌が増加する。","日本人の閉経の平均年齢は 55 歳である。","10 か月の連続した無月経の確認で診断される。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":59,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[23],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B059"},"exam":112,"year":2023,"session":"PM","number":59},"sources":[]},{"id":"112-PM-060","record":{"id":"112-PM-060","choice_explanations":[{"choice":1,"correct":false,"title":"体温が低下する。 妊娠5週ころ","explanation":"妊娠初期は黄体ホルモンの作用で基礎体温の高温相が持続します。妊娠5週ごろの低下が一般的変化ではありません。"},{"choice":2,"correct":false,"title":"乳房が緊満する。 妊娠 15 週ころ","explanation":"乳房の張りは妊娠初期からみられます。妊娠15週ごろを特徴的な開始時期とする組合せは適切ではありません。"},{"choice":3,"correct":false,"title":"つわりが軽減する。 妊娠 11 週ころ","explanation":"つわりは妊娠初期に強く、一般に妊娠12〜16週ごろに軽減していきます。11週ごろを標準的な軽減時期とはしません。"},{"choice":4,"correct":true,"title":"循環血液量が最大になる。 妊娠 32 週ころ","explanation":"循環血液量は妊娠に伴い増え、32週ごろから妊娠後期に最大に近づきます。胎盤循環や分娩時出血に備える変化です。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答4を照合。循環血液量は妊娠に伴い増え、32週ごろから妊娠後期に最大に近づきます。胎盤循環や分娩時出血に備える変化です。","fixes_made":[]},"input_anchor":{"question":"妊娠に伴う母体の生理的変化とその時期の組合せで正しいのはどれか。","choices":["体温が低下する。 妊娠5週ころ","乳房が緊満する。 妊娠 15 週ころ","つわりが軽減する。 妊娠 11 週ころ","循環血液量が最大になる。 妊娠 32 週ころ"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":60,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[23],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B060"},"exam":112,"year":2023,"session":"PM","number":60},"sources":[]},{"id":"112-PM-061","record":{"id":"112-PM-061","choice_explanations":[{"choice":1,"correct":true,"title":"児が乳頭を吸啜することによってオキシトシンが分泌される。","explanation":"乳頭への吸啜刺激でオキシトシンが分泌され、射乳と子宮収縮を促します。授乳時の後陣痛にも関係します。"},{"choice":2,"correct":false,"title":"子宮が非妊時の大きさに戻るのは分娩後約2週である。","explanation":"子宮が非妊時の大きさに戻るには通常6〜8週程度かかります。2週ごろには腹壁上から触れにくくなりますが、復古完了ではありません。"},{"choice":3,"correct":false,"title":"分娩後は一時的に尿量が減少する。","explanation":"産褥早期は妊娠中に貯留した水分の排泄で尿量が増えます。排尿困難による尿閉とは区別します。"},{"choice":4,"correct":false,"title":"プロゲステロンが増加する。","explanation":"胎盤の娩出に伴いプロゲステロンは急激に減少します。乳汁産生が始まる内分泌変化にも関係します。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1を照合。乳頭への吸啜刺激でオキシトシンが分泌され、射乳と子宮収縮を促します。授乳時の後陣痛にも関係します。","fixes_made":[]},"input_anchor":{"question":"産褥期の生理的変化で正しいのはどれか。","choices":["児が乳頭を吸啜することによってオキシトシンが分泌される。","子宮が非妊時の大きさに戻るのは分娩後約2週である。","分娩後は一時的に尿量が減少する。","プロゲステロンが増加する。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":61,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[24],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B061"},"exam":112,"year":2023,"session":"PM","number":61},"sources":[]},{"id":"112-PM-062","record":{"id":"112-PM-062","choice_explanations":[{"choice":1,"correct":false,"title":"｢災害以外のことを何か考えましょう｣","explanation":"災害以外を考えるよう求めると、体験や悲しみを語る機会を妨げます。本人のペースで気持ちを聴きます。"},{"choice":2,"correct":false,"title":"｢あなたの悲しい気持ちは乗り越えられるものですよ｣","explanation":"乗り越えられると一方的に保証するより、現在の悲しみを受け止めることが先です。回復の速度には個人差があります。"},{"choice":3,"correct":true,"title":"｢悲しい気持ちが止まらないのは異常なことではないですよ｣","explanation":"大災害の直後に強い悲しみが生じることは自然な反応です。異常ではないと伝え、安心して話せる関係を作ります。"},{"choice":4,"correct":false,"title":"｢みんなが大変なのですから A さんも元気を出してください｣","explanation":"他者と比較して元気を求めると、孤立感や罪悪感を強めるおそれがあります。個人の苦痛を尊重します。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答3を照合。大災害の直後に強い悲しみが生じることは自然な反応です。異常ではないと伝え、安心して話せる関係を作ります。","fixes_made":[]},"input_anchor":{"question":"大規模災害が発生し、被災した住民は自治体が設置した避難所に集まり避難生活\nを始めた。発災3日、自治体から派遣された看護師は避難所の片隅で涙ぐんでいる\nA さんへの関わりを始めた。A さんは｢悲しい気持ちが止まりません｣と話してい\nる。\nこのときの A さんへの看護師の発言で適切なのはどれか。","choices":["｢災害以外のことを何か考えましょう｣","｢あなたの悲しい気持ちは乗り越えられるものですよ｣","｢悲しい気持ちが止まらないのは異常なことではないですよ｣","｢みんなが大変なのですから A さんも元気を出してください｣"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":62,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[24],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B062"},"exam":112,"year":2023,"session":"PM","number":62},"sources":[]},{"id":"112-PM-063","record":{"id":"112-PM-063","choice_explanations":[{"choice":1,"correct":true,"title":"心的外傷〈トラウマ〉体験を想定して支援を行う。","explanation":"攻撃性の背景にトラウマや恐怖がある可能性を考え、再び傷つけない関わりを行います。拘束中も説明と尊厳への配慮が必要です。"},{"choice":2,"correct":false,"title":"患者が暴力行為に及んだ場合は積極的に反省を促す。","explanation":"強く反省を迫ると興奮や防衛的反応を強める場合があります。安全確保と感情の理解を優先し、落ち着いて振り返ります。"},{"choice":3,"correct":false,"title":"患者の攻撃性が収まるまで疾患や治療の教育を行うことは避ける。","explanation":"理解できる状態に合わせて短く説明することは必要です。攻撃性がある間の説明を一律に避けるのは適切ではありません。"},{"choice":4,"correct":false,"title":"患者の身体的拘束が解除されてから病棟のスケジュールの説明を行う。","explanation":"予定やケアの見通しは拘束中にも伝えます。情報不足による恐怖を減らし、状況を理解できるよう支援します。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1を照合。攻撃性の背景にトラウマや恐怖がある可能性を考え、再び傷つけない関わりを行います。拘束中も説明と尊厳への配慮が必要です。","fixes_made":[]},"input_anchor":{"question":"精神病床に入院し、身体的拘束が必要となる攻撃性の高い精神疾患患者のケアで\n正しいのはどれか。","choices":["心的外傷〈トラウマ〉体験を想定して支援を行う。","患者が暴力行為に及んだ場合は積極的に反省を促す。","患者の攻撃性が収まるまで疾患や治療の教育を行うことは避ける。","患者の身体的拘束が解除されてから病棟のスケジュールの説明を行う。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":63,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[24],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B063"},"exam":112,"year":2023,"session":"PM","number":63},"sources":[]},{"id":"112-PM-064","record":{"id":"112-PM-064","choice_explanations":[{"choice":1,"correct":true,"title":"就労移行支援","explanation":"就労移行支援は一般就労を希望する障害者に訓練や求職支援を提供します。標準利用期間は原則2年間です。"},{"choice":2,"correct":false,"title":"自立生活援助","explanation":"自立生活援助は地域生活での困り事を定期訪問などで支えるサービスです。設問の就職訓練を中心とする制度ではありません。"},{"choice":3,"correct":false,"title":"ピアサポート","explanation":"ピアサポートは同じような経験を持つ人同士の支援です。24か月の就職訓練を定めたサービス名ではありません。"},{"choice":4,"correct":false,"title":"就労継続支援 A 型","explanation":"就労継続支援A型は雇用契約に基づいて働く場などを提供します。原則2年の一般就労準備を中心とする就労移行支援とは異なります。"}],"status":"VERIFIED","review_reason":"問題・全選択肢・公式正答1を照合。就労移行支援は一般就労を希望する障害者に訓練や求職支援を提供します。標準利用期間は原則2年間です。","fixes_made":[]},"input_anchor":{"question":"一般の事業所や企業に就労を希望する精神障害者に対して行う支援で、24 か月\n間を原則として就職に必要な訓練や求職活動を行うのはどれか。","choices":["就労移行支援","自立生活援助","ピアサポート","就労継続支援 A 型"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":64,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[25],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B064"},"exam":112,"year":2023,"session":"PM","number":64},"sources":[{"title":"厚生労働省 就労移行支援の標準利用期間","url":"https://www.mhlw.go.jp/content/001473458.pdf"}]},{"id":"112-PM-065","record":{"id":"112-PM-065","choice_explanations":[{"choice":1,"correct":true,"title":"外出前に蓄尿バッグの尿を廃棄する。","explanation":"外出前にバッグの尿を捨てると重量や過充満を減らし、移動中の牽引や逆流を防ぎやすくなります。公式正答は1です。"},{"choice":2,"correct":false,"title":"カテーテルは大腿の内側に固定する。","explanation":"男性は尿道の屈曲部に力がかからないよう、一般に下腹部側への固定を検討します。大腿内側へ一律に固定しません。"},{"choice":3,"correct":false,"title":"蓄尿バッグに遮光カバーをかぶせる。","explanation":"遮光自体は一般的な尿路感染予防の要件ではありません。尿量・色の観察やバッグを膀胱より低く保つことが重要です。"},{"choice":4,"correct":false,"title":"カテーテルと蓄尿バッグの接続は外さない。","explanation":"感染予防では閉鎖式回路を保ち、不要に接続を外さないことが推奨されます。公式正答は1ですが、4を誤りとする根拠は不明です。"}],"status":"UNKNOWN","review_reason":"公式正答は1。CDCは閉鎖式回路維持を推奨し、4も適切と考えられる。接続を外す必要がある条件が設問に示されず、不明点を明記。","fixes_made":[]},"input_anchor":{"question":"A さん(70 歳、男性)は神経因性膀胱のため、膀胱留置カテーテルを挿入し在宅\nneurogenic bladder\n療養を開始することになった。\nA さんが行う膀胱留置カテーテルの管理で適切なのはどれか。","choices":["外出前に蓄尿バッグの尿を廃棄する。","カテーテルは大腿の内側に固定する。","蓄尿バッグに遮光カバーをかぶせる。","カテーテルと蓄尿バッグの接続は外さない。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":65,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[25],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B065"},"exam":112,"year":2023,"session":"PM","number":65},"sources":[{"title":"CDC CAUTI Summary of Recommendations","url":"https://www.cdc.gov/infection-control/hcp/cauti/summary-of-recommendations.html"}]},{"id":"112-PM-066","record":{"id":"112-PM-066","choice_explanations":[{"choice":1,"correct":false,"title":"頭を高くする。","explanation":"高温環境と口唇乾燥から熱中症や脱水を疑います。頭を高くすることより、冷却と循環状態の評価が優先です。"},{"choice":2,"correct":true,"title":"腋窩を冷やす。","explanation":"室温を下げ、腋窩などを冷やして体熱の放散を促します。往診を待つ間も意識、呼吸、循環の変化を観察します。"},{"choice":3,"correct":false,"title":"水を飲ませる。","explanation":"胃瘻があり、嚥下能力が不明で嘔気もあるため、安易に飲水させると誤嚥の危険があります。補液方法は状態と指示に沿って判断します。"},{"choice":4,"correct":false,"title":"中枢から末梢に下肢をマッサージする。","explanation":"下肢のマッサージは熱中症への優先対応ではありません。中枢から末梢への強い操作で改善を図る根拠もありません。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答2を照合。室温を下げ、腋窩などを冷やして体熱の放散を促します。往診を待つ間も意識、呼吸、循環の変化を観察します。","fixes_made":[]},"input_anchor":{"question":"A さん(88 歳、女性、要介護1)は長女(58 歳、会社員)と2人暮らしで、胃瘻を\n造設し訪問看護を利用している。看護師の訪問時、A さんは頭痛、嘔気を訴え、\nベッドに横になっていた。バイタルサインは、体温 37.6 ℃、呼吸数 24/分、脈拍\n96/分、整、血圧 102/76 mmHg、口唇が乾燥している。室温は 30 ℃である。長女\nに連絡し、かかりつけ医に往診を依頼することにした。\n医師が到着するまでの訪問看護師の対応で適切なのはどれか。","choices":["頭を高くする。","腋窩を冷やす。","水を飲ませる。","中枢から末梢に下肢をマッサージする。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":66,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[25],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B066"},"exam":112,"year":2023,"session":"PM","number":66},"sources":[]},{"id":"112-PM-067","record":{"id":"112-PM-067","choice_explanations":[{"choice":1,"correct":false,"title":"看護職員以外は配置できない。","explanation":"理学療法士、作業療法士、言語聴覚士などを配置することもできます。看護職員だけに限定されません。"},{"choice":2,"correct":false,"title":"緊急時用の薬剤の保管が義務付けられている。","explanation":"緊急時の薬剤保管がすべての訪問看護ステーションに義務付けられているわけではありません。"},{"choice":3,"correct":true,"title":"訪問看護指示書に基づいて療養者のケアを行う。","explanation":"訪問看護は主治医の訪問看護指示書に基づき、計画を立てて提供します。病状変化時も主治医と連携します。"},{"choice":4,"correct":false,"title":"従事する看護職員は5年以上の臨床経験が必要である。","explanation":"全従事看護職員に5年以上の臨床経験を求める一律の要件はありません。必要な知識・技術と体制は確保します。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答3を照合。訪問看護は主治医の訪問看護指示書に基づき、計画を立てて提供します。病状変化時も主治医と連携します。","fixes_made":[]},"input_anchor":{"question":"指定訪問看護ステーションについて正しいのはどれか。","choices":["看護職員以外は配置できない。","緊急時用の薬剤の保管が義務付けられている。","訪問看護指示書に基づいて療養者のケアを行う。","従事する看護職員は5年以上の臨床経験が必要である。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":67,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[26],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B067"},"exam":112,"year":2023,"session":"PM","number":67},"sources":[]},{"id":"112-PM-068","record":{"id":"112-PM-068","choice_explanations":[{"choice":1,"correct":false,"title":"救急車を要請するよう提案する。","explanation":"在宅での治療方針や症状を確認せず直ちに救急車を勧めるのは適切ではありません。現在の苦痛への支援を行います。"},{"choice":2,"correct":false,"title":"A さんを仰臥位にする介助方法を指導する。","explanation":"仰臥位で咳や呼吸困難が強まることがあります。本人が楽と感じる座位などの姿勢を支えます。"},{"choice":3,"correct":true,"title":"A さんの背中をさすりながら傍にいるよう勧める。","explanation":"本人が心地よいと感じる範囲で背中をさすり、そばにいることは安心につながります。妻ができる具体的な支援です。"},{"choice":4,"correct":false,"title":"一度に2倍量のレスキュー薬の服用を試すよう説明する。","explanation":"レスキュー薬は処方された量と間隔を守ります。看護師が独断で倍量を試すよう説明してはいけません。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答3を照合。本人が心地よいと感じる範囲で背中をさすり、そばにいることは安心につながります。妻ができる具体的な支援です。","fixes_made":[]},"input_anchor":{"question":"A さん(63 歳、男性)は妻と2人暮らしで、肺癌の終末期で在宅医療を受けて医\nlung cancer\n療用麻薬を使用中である。看護師が訪問したとき、A さんは椅子に座って咳をし\nながら苦痛に耐えている様子であった。妻は｢レスキュー薬が効くまでは苦しそう\nなので、何か私にできることはありますか｣と訪問看護師に尋ねた。\nこのときの訪問看護師の妻への対応で適切なのはどれか。","choices":["救急車を要請するよう提案する。","A さんを仰臥位にする介助方法を指導する。","A さんの背中をさすりながら傍にいるよう勧める。","一度に2倍量のレスキュー薬の服用を試すよう説明する。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":68,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[26],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B068"},"exam":112,"year":2023,"session":"PM","number":68},"sources":[]},{"id":"112-PM-070","record":{"id":"112-PM-070","choice_explanations":[{"choice":1,"correct":false,"title":"医療安全支援センターを設置する。","explanation":"医療安全支援センターは都道府県等が設置する相談支援機関です。個々の医療機関に設置を求めるものではありません。"},{"choice":2,"correct":false,"title":"医療安全管理者養成研修を実施する。","explanation":"職員研修は必要ですが、医療安全管理者を養成する研修の主催をすべての医療機関に求める規定ではありません。"},{"choice":3,"correct":true,"title":"医療の安全を確保するための指針を策定する。","explanation":"医療機関は安全管理のための指針を整備し、職員研修や事故報告などの体制を確保します。組織的な事故予防の基盤です。"},{"choice":4,"correct":false,"title":"医療安全管理のために必要な研修を2年に1回実施する。","explanation":"安全管理の職員研修は年2回程度の定期実施などが求められます。2年に1回では間隔が長すぎます。"}],"status":"VERIFIED","review_reason":"問題・全選択肢・公式正答3を照合。医療機関は安全管理のための指針を整備し、職員研修や事故報告などの体制を確保します。組織的な事故予防の基盤です。","fixes_made":[]},"input_anchor":{"question":"医療法に基づき医療機関が医療の安全を確保する目的で行うのはどれか。","choices":["医療安全支援センターを設置する。","医療安全管理者養成研修を実施する。","医療の安全を確保するための指針を策定する。","医療安全管理のために必要な研修を2年に1回実施する。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":70,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[27],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B070"},"exam":112,"year":2023,"session":"PM","number":70},"sources":[{"title":"厚生労働省 医療安全管理のための指針","url":"https://www.mhlw.go.jp/topics/bukyoku/isei/i-anzen/1/torikumi/naiyou/manual/index.html"}]},{"id":"112-PM-071","record":{"id":"112-PM-071","choice_explanations":[{"choice":1,"correct":false,"title":"地域災害拠点病院は市町村が指定する。","explanation":"災害拠点病院は都道府県が指定します。市町村が指定するという説明は不適切です。"},{"choice":2,"correct":true,"title":"災害対策基本法に防災計画の作成が規定されている。","explanation":"災害対策基本法は防災基本計画、地域防災計画などの作成を定めています。災害対策を計画的に進める根拠です。"},{"choice":3,"correct":false,"title":"トリアージは救命困難な患者の治療を優先するために行う。","explanation":"トリアージは限られた資源で救命可能性と緊急度から優先順位を判断します。救命困難な患者を一律に最優先にはしません。"},{"choice":4,"correct":false,"title":"災害派遣医療チーム〈DMAT〉は被災地域の精神科医療および精神保健活動\nを専門的に行う。","explanation":"精神科医療や精神保健の専門支援はDPATの役割です。DMATは主に災害急性期の医療支援を担います。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答2を照合。災害対策基本法は防災基本計画、地域防災計画などの作成を定めています。災害対策を計画的に進める根拠です。","fixes_made":[]},"input_anchor":{"question":"災害時の医療を支える体制で正しいのはどれか。","choices":["地域災害拠点病院は市町村が指定する。","災害対策基本法に防災計画の作成が規定されている。","トリアージは救命困難な患者の治療を優先するために行う。","災害派遣医療チーム〈DMAT〉は被災地域の精神科医療および精神保健活動\nを専門的に行う。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":71,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[27],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B071"},"exam":112,"year":2023,"session":"PM","number":71},"sources":[]},{"id":"112-PM-072","record":{"id":"112-PM-072","choice_explanations":[{"choice":1,"correct":true,"title":"生活習慣の改善について A さんと妻に考えを聞く。","explanation":"まず二人の認識や希望を聴き、文化的背景と生活に合う改善方法を一緒に考えます。一方的な指導より実行可能性が高まります。"},{"choice":2,"correct":false,"title":"食事は1日3回までにするよう指導する。","explanation":"食事回数だけでなく量、内容、間食などの把握が必要です。初回から回数だけを指定する対応は不十分です。"},{"choice":3,"correct":false,"title":"毎日1時間のウォーキングを提案する。","explanation":"虚血性心疾患では運動の安全性や許容量の確認が必要です。いきなり毎日1時間の運動を提案しません。"},{"choice":4,"correct":false,"title":"料理教室に通うことを勧める。","explanation":"料理教室が本人たちの課題や希望に合うかは不明です。まず現在の理解と改善への考えを聴きます。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1を照合。まず二人の認識や希望を聴き、文化的背景と生活に合う改善方法を一緒に考えます。一方的な指導より実行可能性が高まります。","fixes_made":[]},"input_anchor":{"question":"A さん(58 歳、男性)は外国籍の妻(40 歳)と 10 年前に結婚し、2人で暮らして\nいる。虚血性心疾患と診断され、外来看護師による生活指導を妻と一緒に受けるこ\nischemic heart disease\nとになった。初回の面談で、A さんは｢10 年間で体重が 10 kg 増えました。妻の母\n国の習慣で味が濃いおかずや揚げ物とご飯を1日に何度も食べています。最近、2\n人とも運動をしなくなりました｣と話した。\nこのときの外来看護師の A さんと妻への最初の対応で適切なのはどれか。","choices":["生活習慣の改善について A さんと妻に考えを聞く。","食事は1日3回までにするよう指導する。","毎日1時間のウォーキングを提案する。","料理教室に通うことを勧める。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":72,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[28],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B072"},"exam":112,"year":2023,"session":"PM","number":72},"sources":[]},{"id":"112-PM-074","record":{"id":"112-PM-074","choice_explanations":[{"choice":1,"correct":false,"title":"IgA","explanation":"IgAは粘膜や分泌液での防御に重要です。初回抗原刺激で血中に最初に増える抗体はIgMです。"},{"choice":2,"correct":false,"title":"IgD","explanation":"IgDは主にB細胞表面で抗原受容体として働きます。初回感染で最初に多く産生される抗体ではありません。"},{"choice":3,"correct":false,"title":"IgE","explanation":"IgEは即時型アレルギーや寄生虫への防御に関わります。細菌の初回侵入時の代表的な初期抗体ではありません。"},{"choice":4,"correct":false,"title":"IgG","explanation":"IgGはIgMに続いて増え、二次免疫応答で速やかに多く産生されます。血中で最も多い免疫グロブリンです。"},{"choice":5,"correct":true,"title":"IgM","explanation":"初回の抗原刺激ではまずIgMが産生されます。その後、抗体のクラススイッチなどを経てIgGが増加します。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答5を照合。初回の抗原刺激ではまずIgMが産生されます。その後、抗体のクラススイッチなどを経てIgGが増加します。","fixes_made":[]},"input_anchor":{"question":"細菌が体内に初めて侵入したときに最初に産生される免疫グロブリンはどれか。","choices":["IgA","IgD","IgE","IgG","IgM"],"correct_answers":[5],"accepted_answer_sets":[[5]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":74,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[29],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B074"},"exam":112,"year":2023,"session":"PM","number":74},"sources":[]},{"id":"112-PM-075","record":{"id":"112-PM-075","choice_explanations":[{"choice":1,"correct":false,"title":"排尿中枢はホルモンによって制御される。","explanation":"排尿は橋や仙髄などの中枢と自律・体性神経で調節されます。ホルモンによる制御を中心とする説明は誤りです。"},{"choice":2,"correct":false,"title":"排尿反射は交感神経を介して起こる。","explanation":"排尿時の排尿筋収縮は骨盤神経の副交感神経作用です。交感神経は主に蓄尿を助けます。"},{"choice":3,"correct":true,"title":"蓄尿時に内尿道括約筋は収縮する。","explanation":"蓄尿時は内尿道括約筋側が収縮して尿の流出を防ぎます。排尿筋は弛緩して尿をためます。"},{"choice":4,"correct":false,"title":"排尿時に外尿道括約筋は収縮する。","explanation":"排尿時は外尿道括約筋が弛緩し、尿が通過できるようになります。収縮は尿の保持に働きます。"},{"choice":5,"correct":false,"title":"蓄尿時に排尿筋は収縮する。","explanation":"蓄尿時の排尿筋は弛緩します。収縮すると膀胱内圧が高まり、排尿を促します。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答3を照合。蓄尿時は内尿道括約筋側が収縮して尿の流出を防ぎます。排尿筋は弛緩して尿をためます。","fixes_made":[]},"input_anchor":{"question":"膀胱の蓄尿と排尿反射で正しいのはどれか。","choices":["排尿中枢はホルモンによって制御される。","排尿反射は交感神経を介して起こる。","蓄尿時に内尿道括約筋は収縮する。","排尿時に外尿道括約筋は収縮する。","蓄尿時に排尿筋は収縮する。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":75,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[30],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B075"},"exam":112,"year":2023,"session":"PM","number":75},"sources":[]},{"id":"112-PM-076","record":{"id":"112-PM-076","choice_explanations":[{"choice":1,"correct":false,"title":"インスリン","explanation":"ステロイドは血糖を上げる作用があり、インスリンが必ず顕著に低下するとはいえません。主な抑制対象はACTHです。"},{"choice":2,"correct":false,"title":"甲状腺ホルモン","explanation":"甲状腺ホルモンがこの機序で顕著に低下するとは限りません。外因性ステロイドは視床下部・下垂体・副腎系を抑制します。"},{"choice":3,"correct":false,"title":"エストラジオール","explanation":"性腺系への影響はあり得ますが、長期ステロイドによる直接的な負のフィードバックで問われるのはACTHです。"},{"choice":4,"correct":false,"title":"副甲状腺ホルモン〈PTH〉","explanation":"PTHはカルシウム代謝を調節します。長期ステロイド服用で一律に顕著な低下を示すホルモンではありません。"},{"choice":5,"correct":true,"title":"副腎皮質刺激ホルモン〈ACTH〉","explanation":"外から投与された糖質コルチコイドが負のフィードバックをかけ、下垂体のACTH分泌を抑えます。急な中止で副腎不全を起こす危険があります。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答5を照合。外から投与された糖質コルチコイドが負のフィードバックをかけ、下垂体のACTH分泌を抑えます。急な中止で副腎不全を起こす危険があります。","fixes_made":[]},"input_anchor":{"question":"全身性エリテマトーデス〈SLE〉でプレドニゾロンを長期間服用している成人女性\nsystemic lupus erythematosus\nの患者で、血中濃度が顕著に低下しているのはどれか。","choices":["インスリン","甲状腺ホルモン","エストラジオール","副甲状腺ホルモン〈PTH〉","副腎皮質刺激ホルモン〈ACTH〉"],"correct_answers":[5],"accepted_answer_sets":[[5]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":76,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[30],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B076"},"exam":112,"year":2023,"session":"PM","number":76},"sources":[]},{"id":"112-PM-077","record":{"id":"112-PM-077","choice_explanations":[{"choice":1,"correct":false,"title":"Ⅰ","explanation":"Ⅰ誘導は右手と左手の電位差をみる標準肢誘導です。胸骨右縁に単一電極を置く胸部誘導ではありません。"},{"choice":2,"correct":true,"title":"V1","explanation":"V1は第4肋間の胸骨右縁に装着します。肋間と胸骨縁を触れて位置を確認します。"},{"choice":3,"correct":false,"title":"V2","explanation":"V2は第4肋間の胸骨左縁です。V1と左右を取り違えないようにします。"},{"choice":4,"correct":false,"title":"V4","explanation":"V4は第5肋間の左鎖骨中線上です。V3はV2とV4の中間に置きます。"},{"choice":5,"correct":false,"title":"aVR","explanation":"aVRは右上肢の増高単極肢誘導です。第4肋間胸骨右縁に装着する胸部誘導ではありません。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答2を照合。V1は第4肋間の胸骨右縁に装着します。肋間と胸骨縁を触れて位置を確認します。","fixes_made":[]},"input_anchor":{"question":"心電図検査の胸部誘導で電極を第4肋間胸骨右縁に装着するのはどれか。","choices":["Ⅰ","V1","V2","V4","aVR"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":77,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[30],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B077"},"exam":112,"year":2023,"session":"PM","number":77},"sources":[]},{"id":"112-PM-078","record":{"id":"112-PM-078","choice_explanations":[{"choice":1,"correct":true,"title":"下肢末端は温度が下がるので結晶化しやすい。","explanation":"尿酸塩は温度が低いほど溶けにくくなるため、足趾などの末端で結晶化しやすくなります。痛風発作の好発部位に関係します。"},{"choice":2,"correct":false,"title":"男性ホルモンによって腎排泄が増加する。","explanation":"尿酸の腎排泄を促す作用は主に女性ホルモンのエストロゲンで知られます。男性ホルモンの作用とするのは不適切です。"},{"choice":3,"correct":false,"title":"激しい運動で産生が減少する。","explanation":"激しい運動ではATP分解が進み、尿酸産生が増えることがあります。脱水も尿酸値の上昇に関係します。"},{"choice":4,"correct":false,"title":"利尿薬によって排泄される。","explanation":"サイアザイド系などの利尿薬は尿酸排泄を低下させ、高尿酸血症を起こすことがあります。一律に排泄を促すわけではありません。"},{"choice":5,"correct":false,"title":"肝臓で分解される。","explanation":"ヒトでは尿酸をさらに分解するウリカーゼを欠きます。主に腎臓や腸管から排泄されます。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1を照合。尿酸塩は温度が低いほど溶けにくくなるため、足趾などの末端で結晶化しやすくなります。痛風発作の好発部位に関係します。","fixes_made":[]},"input_anchor":{"question":"プリン体の代謝産物である尿酸で正しいのはどれか。","choices":["下肢末端は温度が下がるので結晶化しやすい。","男性ホルモンによって腎排泄が増加する。","激しい運動で産生が減少する。","利尿薬によって排泄される。","肝臓で分解される。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":78,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[31],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B078"},"exam":112,"year":2023,"session":"PM","number":78},"sources":[]},{"id":"112-PM-079","record":{"id":"112-PM-079","choice_explanations":[{"choice":1,"correct":false,"title":"合併症は腹膜炎が多い。\nperitonitis","explanation":"腹膜炎は腹膜透析で重要な合併症です。血液透析では血圧低下や血管アクセスの感染などに注意します。"},{"choice":2,"correct":false,"title":"食事はカルシウムを制限する。","explanation":"カルシウムを一律に制限するのではなく、カルシウム・リンの値などに応じて調整します。リン、塩分、水分などの管理が重要です。"},{"choice":3,"correct":true,"title":"導入初期には不均衡症候群が起こる。\ndisequilibrium syndrome","explanation":"導入初期に血液の尿素が急に減ると、脳との浸透圧差から頭痛、悪心などの不均衡症候群を起こすことがあります。"},{"choice":4,"correct":false,"title":"導入の原因疾患は IgA 腎症が最も多い。\nIgA nephropathy","explanation":"出題当時、透析導入原疾患で最多は糖尿病性腎症です。IgA腎症が最多という説明ではありません。"},{"choice":5,"correct":false,"title":"透析に用いる半透膜はタンパク質が通過する。","explanation":"通常の透析膜は尿素などの小分子を除き、アルブミンなどの主要な蛋白を保つよう設計されています。蛋白全般が通過するという説明は不適切です。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答3を照合。導入初期に血液の尿素が急に減ると、脳との浸透圧差から頭痛、悪心などの不均衡症候群を起こすことがあります。","fixes_made":[]},"input_anchor":{"question":"血液透析について正しいのはどれか。","choices":["合併症は腹膜炎が多い。\nperitonitis","食事はカルシウムを制限する。","導入初期には不均衡症候群が起こる。\ndisequilibrium syndrome","導入の原因疾患は IgA 腎症が最も多い。\nIgA nephropathy","透析に用いる半透膜はタンパク質が通過する。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":79,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[31],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B079"},"exam":112,"year":2023,"session":"PM","number":79},"sources":[]},{"id":"112-PM-080","record":{"id":"112-PM-080","choice_explanations":[{"choice":1,"correct":false,"title":"無菌操作で行う。","explanation":"鼻腔や咽頭を通るため通常は清潔操作で行います。無菌操作を要する尿道カテーテル挿入などと区別します。"},{"choice":2,"correct":false,"title":"挿入時、患者の体位は仰臥位にする。","explanation":"可能なら座位や半座位で挿入し、誤嚥や気道への迷入を防ぎます。仰臥位を基本とはしません。"},{"choice":3,"correct":false,"title":"胃管が咽頭に達するまで頸部を前屈してもらう。","explanation":"咽頭に達した後に頸部を軽く前屈し、食道へ進みやすくします。到達前から前屈を求める組合せは適切ではありません。"},{"choice":4,"correct":true,"title":"胃管が咽頭に達したら嚥下を促す。","explanation":"咽頭に達したら嚥下を促し、その動きに合わせて進めます。咳、呼吸苦などがあれば中止して位置を確認します。"},{"choice":5,"correct":false,"title":"水を注入して胃管の先端が胃内に到達したことを確認する。","explanation":"位置が確かでないまま水を注入すると肺へ入る危険があります。適切な方法で胃内留置を確認するまで注入しません。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答4を照合。咽頭に達したら嚥下を促し、その動きに合わせて進めます。咳、呼吸苦などがあれば中止して位置を確認します。","fixes_made":[]},"input_anchor":{"question":"成人に経鼻経管栄養の胃管を挿入する方法で適切なのはどれか。","choices":["無菌操作で行う。","挿入時、患者の体位は仰臥位にする。","胃管が咽頭に達するまで頸部を前屈してもらう。","胃管が咽頭に達したら嚥下を促す。","水を注入して胃管の先端が胃内に到達したことを確認する。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":80,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[31],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":1,"row_id":"B080"},"exam":112,"year":2023,"session":"PM","number":80},"sources":[]},{"id":"112-PM-081","record":{"id":"112-PM-081","choice_explanations":[{"choice":1,"correct":true,"title":"簡易浴槽","explanation":"簡易浴槽は、他人が使ったものの再利用になじみにくい特定福祉用具として購入費支給の対象です。"},{"choice":2,"correct":false,"title":"特殊寝台","explanation":"特殊寝台は福祉用具貸与の対象です。出題時点の特定福祉用具購入の対象ではありません。"},{"choice":3,"correct":false,"title":"体位変換器","explanation":"体位変換器は貸与の対象です。購入費支給の対象となる簡易浴槽と区別します。"},{"choice":4,"correct":false,"title":"移動用リフト","explanation":"移動用リフト本体は貸与、身体に触れるつり具部分は特定福祉用具販売の対象です。選択肢はリフト本体を指します。"},{"choice":5,"correct":false,"title":"取り付け工事を伴わないスロープ","explanation":"2023年の出題時点では工事不要のスロープは貸与対象です。2024年4月から固定用スロープには貸与・販売の選択制が導入されました。"}],"status":"VERIFIED","review_reason":"問題・全選択肢・公式正答1を照合。簡易浴槽は、他人が使ったものの再利用になじみにくい特定福祉用具として購入費支給の対象です。","fixes_made":["2023年の出題時点と2024年の固定用スロープ選択制導入を区別。"]},"input_anchor":{"question":"介護保険サービスを利用して購入できるのはどれか。","choices":["簡易浴槽","特殊寝台","体位変換器","移動用リフト","取り付け工事を伴わないスロープ"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":81,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[32],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B081"},"exam":112,"year":2023,"session":"PM","number":81},"sources":[{"title":"厚生労働省 福祉用具・住宅改修","url":"https://www.mhlw.go.jp/stf/seisakunitsuite/bunya/0000212398.html"}]},{"id":"112-PM-082","record":{"id":"112-PM-082","choice_explanations":[{"choice":1,"correct":false,"title":"生後6か月","explanation":"出生時約50cmに対し、生後6か月ではおおむね65cm程度です。まだ2倍には達しません。"},{"choice":2,"correct":false,"title":"生後 12 か月","explanation":"1歳の身長はおおむね75cmで、出生時の約1.5倍です。体重が約3倍になることと区別します。"},{"choice":3,"correct":false,"title":"2 歳","explanation":"2歳ではおおむね85cm前後です。出生時の2倍である約100cmには達していません。"},{"choice":4,"correct":true,"title":"4 歳","explanation":"4歳ごろに身長が約100cmとなり、出生時の約50cmの2倍に達します。個人差を含む成長の目安です。"},{"choice":5,"correct":false,"title":"6 歳","explanation":"6歳では通常100cmを超えています。出生時の約2倍になる標準的な時期は4歳ごろです。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答4を照合。4歳ごろに身長が約100cmとなり、出生時の約50cmの2倍に達します。個人差を含む成長の目安です。","fixes_made":[]},"input_anchor":{"question":"標準的な成長をしている正期産児の身長が出生時の約2倍になるのはどれか。","choices":["生後6か月","生後 12 か月","2 歳","4 歳","6 歳"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":82,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[32],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B082"},"exam":112,"year":2023,"session":"PM","number":82},"sources":[]},{"id":"112-PM-083","record":{"id":"112-PM-083","choice_explanations":[{"choice":1,"correct":true,"title":"エストロゲン","explanation":"卵巣由来のエストロゲンは乳房の発育など女子の第二次性徴に大きく関与します。思春期の卵巣機能の発達と結び付きます。"},{"choice":2,"correct":false,"title":"オキシトシン","explanation":"オキシトシンは子宮収縮や射乳に関係します。女子の第二次性徴を主に促すホルモンではありません。"},{"choice":3,"correct":false,"title":"成長ホルモン","explanation":"成長ホルモンは身長や体組織の成長を促しますが、女子特有の性徴に最も関与するのはエストロゲンです。"},{"choice":4,"correct":false,"title":"甲状腺ホルモン","explanation":"甲状腺ホルモンは代謝や正常な成長発達に必要です。女子の第二次性徴に特異的な主役ではありません。"},{"choice":5,"correct":false,"title":"テストステロン","explanation":"テストステロンは主に男子の第二次性徴に関与します。女子でも分泌されますが、本問の中心はエストロゲンです。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1を照合。卵巣由来のエストロゲンは乳房の発育など女子の第二次性徴に大きく関与します。思春期の卵巣機能の発達と結び付きます。","fixes_made":[]},"input_anchor":{"question":"女子の第二次性徴に最も関与するホルモンはどれか。","choices":["エストロゲン","オキシトシン","成長ホルモン","甲状腺ホルモン","テストステロン"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":83,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[32],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B083"},"exam":112,"year":2023,"session":"PM","number":83},"sources":[]},{"id":"112-PM-084","record":{"id":"112-PM-084","choice_explanations":[{"choice":1,"correct":false,"title":"排 泄","explanation":"トイレ歩行は一人でできており、記載上の切迫した問題はありません。頭部をぶつける行動への安全評価が優先です。"},{"choice":2,"correct":false,"title":"個人衛生","explanation":"清潔への関心低下には支援が必要ですが、今は自傷につながる行動への対応が優先されます。"},{"choice":3,"correct":true,"title":"安全を保つ能力","explanation":"幻聴に影響されて走り、壁に頭をぶつけているため、身体損傷の危険が高い状態です。安全を保つ能力を最優先で評価します。"},{"choice":4,"correct":false,"title":"活動と休息のバランス","explanation":"活動と休息の確認も必要ですが、目前の受傷リスクが最も切迫しています。安全を確保したうえで評価を広げます。"},{"choice":5,"correct":false,"title":"孤独と付き合いのバランス","explanation":"他者との交流の少なさは継続的な課題です。現時点では幻聴に伴う危険行動への評価が優先です。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答3を照合。幻聴に影響されて走り、壁に頭をぶつけているため、身体損傷の危険が高い状態です。安全を保つ能力を最優先で評価します。","fixes_made":[]},"input_anchor":{"question":"A さん(25 歳、女性)は統合失調症と診断され、入院2か月が経過した。食事や\nschizophrenia\n水分の摂取、トイレ歩行は1人でできる。歯磨き、入浴への関心はあまりない。幻\n聴が聞こえると突然走り出し、壁に頭をぶつけている。日中はホールで過ごし、自\n分から他の患者と交流はしない。\nA さんのセルフケアのアセスメントで優先度が高いのはどれか。","choices":["排 泄","個人衛生","安全を保つ能力","活動と休息のバランス","孤独と付き合いのバランス"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":84,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[33],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B084"},"exam":112,"year":2023,"session":"PM","number":84},"sources":[]},{"id":"112-PM-085","record":{"id":"112-PM-085","choice_explanations":[{"choice":1,"correct":false,"title":"ヘパリン","explanation":"ヘパリンはAPTTなどの凝固検査で作用を評価します。通常の薬物血中濃度TDMの代表薬ではありません。"},{"choice":2,"correct":false,"title":"インスリン","explanation":"インスリンは血糖値などを用いて用量を調節します。インスリン濃度のTDMを通常行うわけではありません。"},{"choice":3,"correct":true,"title":"ジギタリス","explanation":"ジギタリスは治療域と中毒域が近く、腎機能などで濃度が変動します。TDMで有効性と毒性を評価します。"},{"choice":4,"correct":true,"title":"炭酸リチウム","explanation":"炭酸リチウムは有効域が狭く、脱水や腎機能低下で中毒を起こします。血中濃度を定期的に確認します。"},{"choice":5,"correct":false,"title":"ニトログリセリン","explanation":"ニトログリセリンは症状、血圧などで効果と副作用を評価します。通常TDMを必要とする薬ではありません。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答3、4を照合。ジギタリスは治療域と中毒域が近く、腎機能などで濃度が変動します。TDMで有効性と毒性を評価します。 炭酸リチウムは有効域が狭く、脱水や腎機能低下で中毒を起こします。血中濃度を定期的に確認します。","fixes_made":[]},"input_anchor":{"question":"薬物血中濃度モニタリング〈TDM〉の実施が必要な薬物はどれか。2つ選べ。","choices":["ヘパリン","インスリン","ジギタリス","炭酸リチウム","ニトログリセリン"],"correct_answers":[3,4],"accepted_answer_sets":[[3,4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":85,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[33],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B085"},"exam":112,"year":2023,"session":"PM","number":85},"sources":[]},{"id":"112-PM-086","record":{"id":"112-PM-086","choice_explanations":[{"choice":1,"correct":false,"title":"単相性の睡眠になる。","explanation":"高齢者は夜間睡眠が分断され、日中の居眠りなど多相化しやすくなります。単相性になるとはいえません。"},{"choice":2,"correct":false,"title":"浅い眠りが少なくなる。","explanation":"深い徐波睡眠が減り、浅い眠りが増えやすくなります。浅い眠りが少なくなるという説明は逆です。"},{"choice":3,"correct":false,"title":"総睡眠時間が延長する。","explanation":"総睡眠時間は一般に短縮する傾向があります。必要な睡眠や生活習慣には個人差があります。"},{"choice":4,"correct":true,"title":"中途覚醒の回数が増加する。","explanation":"睡眠が浅くなり、夜間頻尿なども加わって中途覚醒が増えやすくなります。再入眠のしやすさも評価します。"},{"choice":5,"correct":true,"title":"入眠するまでに時間がかかる。","explanation":"入眠までの時間が延びる傾向があります。生活リズム、昼寝、服薬なども影響するため個別に評価します。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答4、5を照合。睡眠が浅くなり、夜間頻尿なども加わって中途覚醒が増えやすくなります。再入眠のしやすさも評価します。 入眠までの時間が延びる傾向があります。生活リズム、昼寝、服薬なども影響するため個別に評価します。","fixes_made":[]},"input_anchor":{"question":"高齢者の睡眠で正しいのはどれか。2つ選べ。","choices":["単相性の睡眠になる。","浅い眠りが少なくなる。","総睡眠時間が延長する。","中途覚醒の回数が増加する。","入眠するまでに時間がかかる。"],"correct_answers":[4,5],"accepted_answer_sets":[[4,5]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":86,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[33],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B086"},"exam":112,"year":2023,"session":"PM","number":86},"sources":[]},{"id":"112-PM-087","record":{"id":"112-PM-087","choice_explanations":[{"choice":1,"correct":false,"title":"血小板数","explanation":"血小板数は加齢だけで明らかに高くなる代表的項目ではありません。異常値は疾患などの原因を検討します。"},{"choice":2,"correct":true,"title":"尿素窒素","explanation":"加齢に伴う腎機能低下などで尿素窒素が上がりやすくなります。ただし脱水や蛋白摂取、消化管出血でも変動します。"},{"choice":3,"correct":false,"title":"白血球数","explanation":"白血球数が加齢だけで高くなるとはいえません。感染時にも反応が乏しい場合があり、症状と併せて評価します。"},{"choice":4,"correct":true,"title":"食後血糖値","explanation":"耐糖能の低下により食後血糖値が上昇しやすくなります。加齢だけと決めつけず糖尿病なども評価します。"},{"choice":5,"correct":false,"title":"AST〈GOT〉","explanation":"ASTの高値を正常加齢の特徴とはしません。肝臓や筋肉の障害などを検討する必要があります。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答2、4を照合。加齢に伴う腎機能低下などで尿素窒素が上がりやすくなります。ただし脱水や蛋白摂取、消化管出血でも変動します。 耐糖能の低下により食後血糖値が上昇しやすくなります。加齢だけと決めつけず糖尿病なども評価します。","fixes_made":[]},"input_anchor":{"question":"高齢者の血液検査の結果で成人の基準値と比較して値が高くなるのはどれか。\n2つ選べ。","choices":["血小板数","尿素窒素","白血球数","食後血糖値","AST〈GOT〉"],"correct_answers":[2,4],"accepted_answer_sets":[[2,4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":87,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[34],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B087"},"exam":112,"year":2023,"session":"PM","number":87},"sources":[]},{"id":"112-PM-088","record":{"id":"112-PM-088","choice_explanations":[{"choice":1,"correct":true,"title":"うつ病患者のリワーク支援を行う。\ndepression","explanation":"リワーク支援は復職と再発予防を支えるリハビリテーションです。発症後の生活機能回復を図る三次予防です。"},{"choice":2,"correct":false,"title":"災害時の精神的支援を行うボランティアを育成する。","explanation":"災害時支援の担い手育成は発症予防や支援体制づくりに位置付けられます。患者の社会復帰を中心とする三次予防ではありません。"},{"choice":3,"correct":false,"title":"自殺企図をして未遂だった人の希死念慮を確認する。","explanation":"自殺未遂後の希死念慮の確認は切迫した危険の早期把握と介入で、ここでは二次予防に整理されます。"},{"choice":4,"correct":true,"title":"精神障害者の長期入院による自発性の低下を予防する。","explanation":"長期入院による自発性低下や社会生活機能の低下を防ぐことは、障害の軽減を目指す三次予防です。"},{"choice":5,"correct":false,"title":"統合失調症のアンチ・スティグマ・キャンペーンを行う。\nschizophrenia","explanation":"社会の偏見を減らす啓発は、ここでは一次予防・地域の環境づくりとして整理されます。個々の患者のリハビリテーションとは異なります。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1、4を照合。リワーク支援は復職と再発予防を支えるリハビリテーションです。発症後の生活機能回復を図る三次予防です。 長期入院による自発性低下や社会生活機能の低下を防ぐことは、障害の軽減を目指す三次予防です。","fixes_made":[]},"input_anchor":{"question":"精神保健における三次予防はどれか。2つ選べ。","choices":["うつ病患者のリワーク支援を行う。\ndepression","災害時の精神的支援を行うボランティアを育成する。","自殺企図をして未遂だった人の希死念慮を確認する。","精神障害者の長期入院による自発性の低下を予防する。","統合失調症のアンチ・スティグマ・キャンペーンを行う。\nschizophrenia"],"correct_answers":[1,4],"accepted_answer_sets":[[1,4]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":88,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[34],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B088"},"exam":112,"year":2023,"session":"PM","number":88},"sources":[]},{"id":"112-PM-089","record":{"id":"112-PM-089","choice_explanations":[{"choice":1,"correct":false,"title":"特別支援学校に転校するよう勧める。","explanation":"本人は元の学校への通学を望んでいます。最初から転校を勧めず、学校と必要な支援や環境調整を検討します。"},{"choice":2,"correct":true,"title":"弟の退行現象に注意するよう説明する。","explanation":"家族の関心や生活の変化で、弟に不安や退行が生じる場合があります。きょうだいの気持ちにも目を向けるよう支援します。"},{"choice":3,"correct":true,"title":"A ちゃんが利用できる社会資源を紹介する。","explanation":"通学、福祉用具、介助などに使える社会資源を紹介し、本人の希望を実現する支援を家族と組み立てます。"},{"choice":4,"correct":false,"title":"A ちゃんのケアは主に母親が行うよう助言する。","explanation":"母親だけを主な介護者と決めると負担が偏ります。家族の状況や意向に応じて役割分担と外部支援を考えます。"},{"choice":5,"correct":false,"title":"事故については家族の間で話題にしないよう指導する。","explanation":"事故を話題にしないと一律に決めず、本人や家族が話したい気持ちを尊重します。体験を整理する機会を妨げないことが大切です。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答2、3を照合。家族の関心や生活の変化で、弟に不安や退行が生じる場合があります。きょうだいの気持ちにも目を向けるよう支援します。 通学、福祉用具、介助などに使える社会資源を紹介し、本人の希望を実現する支援を家族と組み立てます。","fixes_made":[]},"input_anchor":{"question":"A ちゃん(小学4年生、女児)は父親(40 歳、会社員)、母親(40 歳、会社員)、弟\n(小学2年生)と4人で暮らしている。交通事故で頸髄損傷となり、訪問看護を利用\nして在宅療養を開始した。A ちゃんはこれまで通っていた小学校に継続して通学\nすることを希望している。\nA ちゃんの家族への看護師の対応で適切なのはどれか。2つ選べ。","choices":["特別支援学校に転校するよう勧める。","弟の退行現象に注意するよう説明する。","A ちゃんが利用できる社会資源を紹介する。","A ちゃんのケアは主に母親が行うよう助言する。","事故については家族の間で話題にしないよう指導する。"],"correct_answers":[2,3],"accepted_answer_sets":[[2,3]],"case_text":null,"preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":89,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[34],"case_pages":[],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B089"},"exam":112,"year":2023,"session":"PM","number":89},"sources":[]},{"id":"112-PM-091","record":{"id":"112-PM-091","choice_explanations":[{"choice":1,"correct":false,"title":"肝性脳症","explanation":"肝性脳症は肝機能障害や高アンモニア血症などを背景に生じます。本例では著明な高血糖と高浸透圧が意識障害を説明します。"},{"choice":2,"correct":false,"title":"小脳出血","explanation":"小脳出血では頭痛、嘔吐、めまい、失調などが問題になります。本例の検査所見は代謝性の意識障害を強く示します。"},{"choice":3,"correct":false,"title":"ケトアシドーシス〈DKA〉","explanation":"DKAでは明らかなケトン増加と代謝性アシドーシスが特徴です。本例は尿ケトンが±、pH7.32で、HHSに合います。"},{"choice":4,"correct":true,"title":"高浸透圧高血糖状態〈HHS〉","explanation":"血糖904mg/dL、血漿浸透圧394mOsm/L、見当識障害と軽微なケトン所見はHHSを示唆します。足病変の感染が誘因と考えられます。"}],"status":"VERIFIED","review_reason":"問題・全選択肢・公式正答4を照合。血糖904mg/dL、血漿浸透圧394mOsm/L、見当識障害と軽微なケトン所見はHHSを示唆します。足病変の感染が誘因と考えられます。","fixes_made":[]},"input_anchor":{"question":"A さんの状態のアセスメントで適切なのはどれか。","choices":["肝性脳症","小脳出血","ケトアシドーシス〈DKA〉","高浸透圧高血糖状態〈HHS〉"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A さん(61 歳、男性、会社員)はデスクワーク中心の仕事をしている。今朝、職場\nへ出勤したが、自分の机の位置や同僚の名前が分からない等の見当識障害があり、同\n僚に付き添われ救急外来を受診した。頭痛、嘔吐、めまいはない。\n現病歴：4年前に2型糖尿病と診断され、経口糖尿病薬が開始された。1年前から受\ntype2diabetes mellitus\n診を自己判断で中断している。\n身体所見：身 長 170 cm、体 重 100 kg。体 温 38.6 ℃、呼 吸 数 22/分、脈 拍 112/分、\n整、血圧 108/64 mmHg。対光反射(+)、瞳孔不同(−)。歩行可能。右第\n1趾に発赤、腫脹、異臭がある。\n検査所見：白血球 19,200/μL、血糖 904 mg/dL、Na 131 mEq/L、K 3.4 mEq/L、\nヘ モ グ ロ ビ ン A1c 〈HbA1c〉 9.2 %、ア ン モ ニ ア 49 μg/dL、CRP 22\nmg/dL。動脈血液ガス分析 pH 7.32。血漿浸透圧 394 mOsm/L。尿ケト\nン体(±)。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":91,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[36],"case_pages":[36],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B091"},"exam":112,"year":2023,"session":"PM","number":91},"sources":[{"title":"Clinical features and outcomes of hyperglycemic hyperosmolar syndrome","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12532513/"}]},{"id":"112-PM-092","record":{"id":"112-PM-092","choice_explanations":[{"choice":1,"correct":false,"title":"1,400 kcal","explanation":"標準体重約63.6kgに軽労作の25〜30kcal/kgを掛けると約1590〜1910kcalです。1400kcalはこの目安より少なくなります。"},{"choice":2,"correct":true,"title":"1,800 kcal","explanation":"標準体重は1.70²×22≒63.6kgです。デスクワーク中心の25〜30kcal/kgから約1590〜1910kcalとなり、1800kcalが適します。"},{"choice":3,"correct":false,"title":"2,200 kcal","explanation":"2200kcalは本例の標準体重と軽い身体活動に基づく目安を上回ります。実体重100kgをそのまま基準にしません。"},{"choice":4,"correct":false,"title":"2,600 kcal","explanation":"2600kcalは軽労作の本例には多く、肥満の改善を妨げるおそれがあります。活動量に合う設定が必要です。"},{"choice":5,"correct":false,"title":"3,000 kcal","explanation":"3000kcalは本例に勧める量として過大です。目標体重、活動量、栄養状態を踏まえて調整します。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答2を照合。標準体重は1.70²×22≒63.6kgです。デスクワーク中心の25〜30kcal/kgから約1590〜1910kcalとなり、1800kcalが適します。","fixes_made":[]},"input_anchor":{"question":"A さんはインスリン療法、糖尿病足病変に対する抗菌薬治療で全身状態は改善\nした。退院へ向けて、看護師は A さんに食事指導をすることにした。\nA さんに勧める1日の摂取カロリーで最も適切なのはどれか。","choices":["1,400 kcal","1,800 kcal","2,200 kcal","2,600 kcal","3,000 kcal"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(61 歳、男性、会社員)はデスクワーク中心の仕事をしている。今朝、職場\nへ出勤したが、自分の机の位置や同僚の名前が分からない等の見当識障害があり、同\n僚に付き添われ救急外来を受診した。頭痛、嘔吐、めまいはない。\n現病歴：4年前に2型糖尿病と診断され、経口糖尿病薬が開始された。1年前から受\ntype2diabetes mellitus\n診を自己判断で中断している。\n身体所見：身 長 170 cm、体 重 100 kg。体 温 38.6 ℃、呼 吸 数 22/分、脈 拍 112/分、\n整、血圧 108/64 mmHg。対光反射(+)、瞳孔不同(−)。歩行可能。右第\n1趾に発赤、腫脹、異臭がある。\n検査所見：白血球 19,200/μL、血糖 904 mg/dL、Na 131 mEq/L、K 3.4 mEq/L、\nヘ モ グ ロ ビ ン A1c 〈HbA1c〉 9.2 %、ア ン モ ニ ア 49 μg/dL、CRP 22\nmg/dL。動脈血液ガス分析 pH 7.32。血漿浸透圧 394 mOsm/L。尿ケト\nン体(±)。","preceding_context":[{"id":"112-PM-091","question":"A さんの状態のアセスメントで適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":92,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[37],"case_pages":[36],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B092"},"exam":112,"year":2023,"session":"PM","number":92},"sources":[]},{"id":"112-PM-093","record":{"id":"112-PM-093","choice_explanations":[{"choice":1,"correct":true,"title":"｢靴下を履きましょう｣","explanation":"靴下で足を保護し、摩擦や小さな外傷を防ぎます。締め付けが強すぎず、足に合うものを選びます。"},{"choice":2,"correct":false,"title":"｢月に1回、足を観察してください｣","explanation":"足は毎日観察し、傷や発赤、水疱などを早期に発見します。月1回では異常の見逃しにつながります。"},{"choice":3,"correct":true,"title":"｢暖房器具に足を近づけないでください｣","explanation":"知覚低下があると熱さに気づかず熱傷を起こします。暖房器具や湯たんぽなどに足を近づけないようにします。"},{"choice":4,"correct":false,"title":"｢足の傷は痛みが出てから受診してください｣","explanation":"神経障害で傷があっても痛みを感じない場合があります。痛みを待たず、傷や感染所見があれば受診します。"},{"choice":5,"correct":false,"title":"｢鶏眼〈うおのめ〉が出来た場合は自分で削ってください｣\ncorn","explanation":"自分で削ると皮膚を傷つけて感染の入口を作ります。鶏眼などは医療者に相談して処置を受けます。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1、3を照合。靴下で足を保護し、摩擦や小さな外傷を防ぎます。締め付けが強すぎず、足に合うものを選びます。 知覚低下があると熱さに気づかず熱傷を起こします。暖房器具や湯たんぽなどに足を近づけないようにします。","fixes_made":[]},"input_anchor":{"question":"A さんの糖尿病足病変の悪化を防ぐ目的で看護師が行う指導で正しいのはどれ\nか。2つ選べ。","choices":["｢靴下を履きましょう｣","｢月に1回、足を観察してください｣","｢暖房器具に足を近づけないでください｣","｢足の傷は痛みが出てから受診してください｣","｢鶏眼〈うおのめ〉が出来た場合は自分で削ってください｣\ncorn"],"correct_answers":[1,3],"accepted_answer_sets":[[1,3]],"case_text":"A さん(61 歳、男性、会社員)はデスクワーク中心の仕事をしている。今朝、職場\nへ出勤したが、自分の机の位置や同僚の名前が分からない等の見当識障害があり、同\n僚に付き添われ救急外来を受診した。頭痛、嘔吐、めまいはない。\n現病歴：4年前に2型糖尿病と診断され、経口糖尿病薬が開始された。1年前から受\ntype2diabetes mellitus\n診を自己判断で中断している。\n身体所見：身 長 170 cm、体 重 100 kg。体 温 38.6 ℃、呼 吸 数 22/分、脈 拍 112/分、\n整、血圧 108/64 mmHg。対光反射(+)、瞳孔不同(−)。歩行可能。右第\n1趾に発赤、腫脹、異臭がある。\n検査所見：白血球 19,200/μL、血糖 904 mg/dL、Na 131 mEq/L、K 3.4 mEq/L、\nヘ モ グ ロ ビ ン A1c 〈HbA1c〉 9.2 %、ア ン モ ニ ア 49 μg/dL、CRP 22\nmg/dL。動脈血液ガス分析 pH 7.32。血漿浸透圧 394 mOsm/L。尿ケト\nン体(±)。","preceding_context":[{"id":"112-PM-091","question":"A さんの状態のアセスメントで適切なのはどれか。"},{"id":"112-PM-092","question":"A さんはインスリン療法、糖尿病足病変に対する抗菌薬治療で全身状態は改善\nした。退院へ向けて、看護師は A さんに食事指導をすることにした。\nA さんに勧める1日の摂取カロリーで最も適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":93,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[37],"case_pages":[36],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B093"},"exam":112,"year":2023,"session":"PM","number":93},"sources":[]},{"id":"112-PM-094","record":{"id":"112-PM-094","choice_explanations":[{"choice":1,"correct":false,"title":"E1V1M2","explanation":"声を発しているためV1ではなくV2です。痛みから逃れる動作はM4で、伸展反応のM2ではありません。"},{"choice":2,"correct":true,"title":"E1V2M4","explanation":"開眼なしはE1、理解不能な音声はV2、痛み刺激から逃れる動作はM4です。合計は7点となります。"},{"choice":3,"correct":false,"title":"E2V2M2","explanation":"痛みでも開眼しないためE2ではなくE1です。運動反応も伸展ではなく逃避なのでM4です。"},{"choice":4,"correct":false,"title":"E4V5M5","explanation":"自発開眼、見当識のある会話、疼痛部位への手の移動は記載されていません。所見からE1V2M4と判断します。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答2を照合。開眼なしはE1、理解不能な音声はV2、痛み刺激から逃れる動作はM4です。合計は7点となります。","fixes_made":[]},"input_anchor":{"question":"グラスゴー・コーマ・スケール〈GCS〉による A さんの意識レベルの評価はどれ\nか。","choices":["E1V1M2","E1V2M4","E2V2M2","E4V5M5"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(53 歳、女性)は休日に公園を散歩中、階段から落ちて頭部を強打し、意識\nを消失した状態で病院に救急搬送された。病院到着時の A さんは開眼せず、声は発\nしているが理解不能である。痛み刺激には逃れようとする動作がみられる。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":94,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[38],"case_pages":[38],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B094"},"exam":112,"year":2023,"session":"PM","number":94},"sources":[]},{"id":"112-PM-096","record":{"id":"112-PM-096","choice_explanations":[{"choice":1,"correct":false,"title":"仰臥位を保持する。","explanation":"全身状態が良好で背部痛もあり、仰臥位を固定して続ける必要はありません。ドレーンに注意しながら体位を調整します。"},{"choice":2,"correct":true,"title":"頭側を 30 度挙上する。","explanation":"頭側を30度程度挙上すると、頸静脈還流を促し頭蓋内圧の上昇を抑えやすくなります。血圧と神経所見も観察します。"},{"choice":3,"correct":false,"title":"頭側を 60 度挙上する。","explanation":"60度の挙上は30度より循環動態に影響しやすく、術後早期にまず選ぶ角度ではありません。指示と状態に沿って調整します。"},{"choice":4,"correct":false,"title":"頭側を 90 度挙上する。","explanation":"90度の急な挙上は脳灌流低下などの危険があります。まず30度程度で安楽と循環状態を確認します。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答2を照合。頭側を30度程度挙上すると、頸静脈還流を促し頭蓋内圧の上昇を抑えやすくなります。血圧と神経所見も観察します。","fixes_made":[]},"input_anchor":{"question":"開頭手術後2日、A さんの全身状態は良好で、硬膜外ドレーンの排液も異常所\n見はなく経過している。看護師が訪室すると A さんは仰臥位で開眼し、｢目が覚め\nたら病院にいて手術も終えていたので驚きました。今は気分もよいが、寝てばかり\nで背中が痛くなってきたので体勢を変えたい｣と話す。\n看護師の対応で適切なのはどれか。","choices":["仰臥位を保持する。","頭側を 30 度挙上する。","頭側を 60 度挙上する。","頭側を 90 度挙上する。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(53 歳、女性)は休日に公園を散歩中、階段から落ちて頭部を強打し、意識\nを消失した状態で病院に救急搬送された。病院到着時の A さんは開眼せず、声は発\nしているが理解不能である。痛み刺激には逃れようとする動作がみられる。","preceding_context":[{"id":"112-PM-094","question":"グラスゴー・コーマ・スケール〈GCS〉による A さんの意識レベルの評価はどれ\nか。"},{"id":"112-PM-095","question":"A さんは右側の急性硬膜外血腫と診断され、緊急開頭手術を受けることになっ\nacute epidural hematoma\nた。術前のバイタルサインは、体温 37.2 ℃、呼吸数 14/分、脈拍 74/分、整。血圧\nは、搬送時の 134/84 mmHg から 174/66 mmHg に上昇し、痛み刺激に対する反応\nが消失している。\nこのときの A さんの瞳孔の状態はどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":96,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[39],"case_pages":[38],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B096"},"exam":112,"year":2023,"session":"PM","number":96},"sources":[]},{"id":"112-PM-097","record":{"id":"112-PM-097","choice_explanations":[{"choice":1,"correct":false,"title":"うつ熱","explanation":"発熱と炎症反応は感染による急性増悪を示唆します。熱放散の障害で体熱がこもるうつ熱とは考えにくい状態です。"},{"choice":2,"correct":false,"title":"高血圧","explanation":"血圧138/88mmHgだけで高血圧と断定できません。COPDで特徴的に予測される呼吸所見が問われています。"},{"choice":3,"correct":true,"title":"呼気の延長","explanation":"気道狭窄と肺の弾性収縮力低下で息を吐き出しにくくなり、呼気が延長します。COPDの典型的所見です。"},{"choice":4,"correct":false,"title":"皮膚の搔痒感","explanation":"皮膚の搔痒はCOPD急性増悪を直接示す典型所見ではありません。換気障害による呼気延長が適します。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答3を照合。気道狭窄と肺の弾性収縮力低下で息を吐き出しにくくなり、呼気が延長します。COPDの典型的所見です。","fixes_made":[]},"input_anchor":{"question":"このときの A さんの状態はどれか。","choices":["うつ熱","高血圧","呼気の延長","皮膚の搔痒感"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A さん(75 歳、男性)は1人暮らしで、妻とは5年前に死別し、子どもはいない。\n57 歳のときに慢性閉塞性肺疾患〈COPD〉と診断された。他に既往はない。20 歳から\nchronic obstructive pulmonary disease\n喫煙していたが、今は禁煙している。エレベーターのないアパートの4階に住んでお\nり、家事動作時に息苦しさが出現することもあったが、日常生活動作〈ADL〉は自立\nしていた。妻が亡くなってからは食事が不規則になり、インスタント食品ばかり食べ\nていた。入浴はせず、週に1回シャワーを浴びていた。\n1週前から日常生活動作〈ADL〉でも息苦しさが増強し、食欲がなく、ほとんど食\n事をしていなかったが、ジュースを 500 mL/日は飲んでいた。昨日の夕方に 37.8 ℃\nの発熱があったため、本日かかりつけの病院を受診した。\n受診時の身体所見：体 温 37.6 ℃、呼 吸 数 24/分、脈 拍 94/分、整、血 圧 138/88\nmmHg、経皮的動脈血酸素飽和度〈SpO2〉82 %(room air)。\n動脈血液ガス分析(room air)：動脈血酸素分圧〈PaO2〉45 Torr、\n動脈血二酸化炭素分圧〈PaCO2〉58 Torr。\n検査所見：赤血球 420 万/μL、Hb 10.3 g/dL、白血球 9,500/μL、総蛋白 5.8 g/dL、\nアルブミン 3.4 g/dL、空腹時血糖 98 mg/dL、CRP 10.1 mg/dL。\n医師の診察の結果、A さんは慢性閉塞性肺疾患〈COPD〉の急性増悪と診断された。\nchronic obstructive pulmonary disease","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":97,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[40],"case_pages":[40],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B097"},"exam":112,"year":2023,"session":"PM","number":97},"sources":[]},{"id":"112-PM-098","record":{"id":"112-PM-098","choice_explanations":[{"choice":1,"correct":false,"title":"貧 血","explanation":"Hb10.3g/dLで貧血はありますが、酸素開始後の切迫した危険としてCO2蓄積による意識障害が優先されます。"},{"choice":2,"correct":false,"title":"便 秘","explanation":"活動や食事量の低下から便秘に注意は必要です。しかし呼吸状態悪化より優先される危険ではありません。"},{"choice":3,"correct":false,"title":"高血糖","explanation":"空腹時血糖98mg/dLで、高血糖を示す所見はありません。酸素投与中は換気と意識状態を重点的に観察します。"},{"choice":4,"correct":true,"title":"CO2 ナルコーシス","explanation":"すでにPaCO2が58Torrと高く、過剰な酸素でCO2貯留が悪化する可能性があります。酸素を調整し、意識・呼吸・血液ガスを確認します。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答4を照合。すでにPaCO2が58Torrと高く、過剰な酸素でCO2貯留が悪化する可能性があります。酸素を調整し、意識・呼吸・血液ガスを確認します。","fixes_made":["CO2貯留を酸素中止ではなく調整・観察につなぐ説明にした。"]},"input_anchor":{"question":"A さんは入院し、抗菌薬の点滴静脈内注射と酸素投与が開始された。病棟内の\n歩行の許可が出て、食事も全粥食を半分程度は食べることができた。\nA さんに起こりうる症状で最も注意が必要なのはどれか。","choices":["貧 血","便 秘","高血糖","CO2 ナルコーシス"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A さん(75 歳、男性)は1人暮らしで、妻とは5年前に死別し、子どもはいない。\n57 歳のときに慢性閉塞性肺疾患〈COPD〉と診断された。他に既往はない。20 歳から\nchronic obstructive pulmonary disease\n喫煙していたが、今は禁煙している。エレベーターのないアパートの4階に住んでお\nり、家事動作時に息苦しさが出現することもあったが、日常生活動作〈ADL〉は自立\nしていた。妻が亡くなってからは食事が不規則になり、インスタント食品ばかり食べ\nていた。入浴はせず、週に1回シャワーを浴びていた。\n1週前から日常生活動作〈ADL〉でも息苦しさが増強し、食欲がなく、ほとんど食\n事をしていなかったが、ジュースを 500 mL/日は飲んでいた。昨日の夕方に 37.8 ℃\nの発熱があったため、本日かかりつけの病院を受診した。\n受診時の身体所見：体 温 37.6 ℃、呼 吸 数 24/分、脈 拍 94/分、整、血 圧 138/88\nmmHg、経皮的動脈血酸素飽和度〈SpO2〉82 %(room air)。\n動脈血液ガス分析(room air)：動脈血酸素分圧〈PaO2〉45 Torr、\n動脈血二酸化炭素分圧〈PaCO2〉58 Torr。\n検査所見：赤血球 420 万/μL、Hb 10.3 g/dL、白血球 9,500/μL、総蛋白 5.8 g/dL、\nアルブミン 3.4 g/dL、空腹時血糖 98 mg/dL、CRP 10.1 mg/dL。\n医師の診察の結果、A さんは慢性閉塞性肺疾患〈COPD〉の急性増悪と診断された。\nchronic obstructive pulmonary disease","preceding_context":[{"id":"112-PM-097","question":"このときの A さんの状態はどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":98,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[41],"case_pages":[40],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B098"},"exam":112,"year":2023,"session":"PM","number":98},"sources":[]},{"id":"112-PM-099","record":{"id":"112-PM-099","choice_explanations":[{"choice":1,"correct":true,"title":"肺炎球菌ワクチンの接種を勧める。","explanation":"呼吸器感染はCOPD増悪の誘因です。接種歴や適応を確認し、肺炎球菌ワクチンなどの感染予防を勧めます。"},{"choice":2,"correct":false,"title":"水分を制限するよう指導する。","explanation":"水分制限の根拠はなく、脱水は痰を粘稠にします。心不全などの別の制限がなければ適切な摂取を支援します。"},{"choice":3,"correct":false,"title":"糖分を制限するよう指導する。","explanation":"低栄養があり、血糖も正常です。糖分だけを一律に制限するより、必要なエネルギーとバランスの確保が重要です。"},{"choice":4,"correct":true,"title":"配食サービスの利用を勧める。","explanation":"独居で食事が偏り、栄養状態も低下しています。配食サービスは食事の確保と調理負担の軽減につながります。"},{"choice":5,"correct":false,"title":"毎日の散歩を勧める。","explanation":"運動は有用ですが、4階までの階段と息切れがあり、一律に毎日の散歩を勧める前に安全な負荷量や方法を評価します。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1、4を照合。呼吸器感染はCOPD増悪の誘因です。接種歴や適応を確認し、肺炎球菌ワクチンなどの感染予防を勧めます。 独居で食事が偏り、栄養状態も低下しています。配食サービスは食事の確保と調理負担の軽減につながります。","fixes_made":[]},"input_anchor":{"question":"A さ ん は 順 調 に 回 復 し た た め、退 院 が 決 ま っ た。退 院 後 の\n慢性閉塞性肺疾患〈COPD〉の治療は、在宅酸素療法〈HOT〉は導入せずに薬物療法\nchronic obstructive pulmonary disease\nを継続することになった。A さんは、看護師に｢退院後も自宅で生活したい｣と話\nしている。近隣に家事を手伝ってくれる親戚や友人はいない。\nA さんへの退院指導の内容で適切なのはどれか。2つ選べ。","choices":["肺炎球菌ワクチンの接種を勧める。","水分を制限するよう指導する。","糖分を制限するよう指導する。","配食サービスの利用を勧める。","毎日の散歩を勧める。"],"correct_answers":[1,4],"accepted_answer_sets":[[1,4]],"case_text":"A さん(75 歳、男性)は1人暮らしで、妻とは5年前に死別し、子どもはいない。\n57 歳のときに慢性閉塞性肺疾患〈COPD〉と診断された。他に既往はない。20 歳から\nchronic obstructive pulmonary disease\n喫煙していたが、今は禁煙している。エレベーターのないアパートの4階に住んでお\nり、家事動作時に息苦しさが出現することもあったが、日常生活動作〈ADL〉は自立\nしていた。妻が亡くなってからは食事が不規則になり、インスタント食品ばかり食べ\nていた。入浴はせず、週に1回シャワーを浴びていた。\n1週前から日常生活動作〈ADL〉でも息苦しさが増強し、食欲がなく、ほとんど食\n事をしていなかったが、ジュースを 500 mL/日は飲んでいた。昨日の夕方に 37.8 ℃\nの発熱があったため、本日かかりつけの病院を受診した。\n受診時の身体所見：体 温 37.6 ℃、呼 吸 数 24/分、脈 拍 94/分、整、血 圧 138/88\nmmHg、経皮的動脈血酸素飽和度〈SpO2〉82 %(room air)。\n動脈血液ガス分析(room air)：動脈血酸素分圧〈PaO2〉45 Torr、\n動脈血二酸化炭素分圧〈PaCO2〉58 Torr。\n検査所見：赤血球 420 万/μL、Hb 10.3 g/dL、白血球 9,500/μL、総蛋白 5.8 g/dL、\nアルブミン 3.4 g/dL、空腹時血糖 98 mg/dL、CRP 10.1 mg/dL。\n医師の診察の結果、A さんは慢性閉塞性肺疾患〈COPD〉の急性増悪と診断された。\nchronic obstructive pulmonary disease","preceding_context":[{"id":"112-PM-097","question":"このときの A さんの状態はどれか。"},{"id":"112-PM-098","question":"A さんは入院し、抗菌薬の点滴静脈内注射と酸素投与が開始された。病棟内の\n歩行の許可が出て、食事も全粥食を半分程度は食べることができた。\nA さんに起こりうる症状で最も注意が必要なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":99,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[41],"case_pages":[40],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B099"},"exam":112,"year":2023,"session":"PM","number":99},"sources":[]},{"id":"112-PM-100","record":{"id":"112-PM-100","choice_explanations":[{"choice":1,"correct":false,"title":"自立支援医療","explanation":"自立支援医療は更生医療、育成医療、精神通院医療などです。白血病治療の医療費助成として直接該当するのは小児慢性特定疾病制度です。"},{"choice":2,"correct":false,"title":"指定難病の医療費助成","explanation":"白血病の小児には小児慢性特定疾病医療費助成を検討します。指定難病制度と小児の対象疾病の制度を区別します。"},{"choice":3,"correct":false,"title":"未熟児養育医療の給付","explanation":"未熟児養育医療は入院養育が必要な未熟児を対象とします。5歳の白血病治療への制度ではありません。"},{"choice":4,"correct":true,"title":"小児慢性特定疾病医療費助成","explanation":"白血病は小児慢性特定疾病の悪性新生物に含まれます。年齢、病状などの認定基準を満たせば医療費助成を利用できます。"}],"status":"VERIFIED","review_reason":"問題・全選択肢・公式正答4を照合。白血病は小児慢性特定疾病の悪性新生物に含まれます。年齢、病状などの認定基準を満たせば医療費助成を利用できます。","fixes_made":[]},"input_anchor":{"question":"A 君が利用できる制度はどれか。","choices":["自立支援医療","指定難病の医療費助成","未熟児養育医療の給付","小児慢性特定疾病医療費助成"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A 君(5歳)は父親(40 歳)、母親(38 歳)と兄(10 歳)の4人家族である。A 君は生後\n6か月のときに白血病と診断され化学療法で寛解し、退院後は幼稚園に登園してい\nleukemia\nた。4歳になって再発し、兄を骨髄ドナーとした造血幹細胞移植を受けた。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":100,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[42],"case_pages":[42],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B100"},"exam":112,"year":2023,"session":"PM","number":100},"sources":[{"title":"小児慢性特定疾病情報センター 医療従事者用ハンドブック","url":"https://www.shouman.jp/pdf/contents/00_handbook.pdf"}]},{"id":"112-PM-101","record":{"id":"112-PM-101","choice_explanations":[{"choice":1,"correct":false,"title":"｢遊園地には行けません｣","explanation":"終末期でも外出を一律に禁止しません。本人の希望、体調、移動や医療支援の条件を確認して実現方法を考えます。"},{"choice":2,"correct":true,"title":"｢幼稚園に登園できます｣","explanation":"本人の希望と病状に応じ、幼稚園と支援方法を調整して登園を検討できます。終末期であることだけで登園不可とはしません。"},{"choice":3,"correct":true,"title":"｢食べ物の制限はありません｣","explanation":"終末期は食べる楽しみを尊重し、不要な食事制限を避ける趣旨です。ただし誤嚥、衛生、アレルギーなど病状に応じた安全配慮は続けます。"},{"choice":4,"correct":false,"title":"｢痛みが出た場合、自宅では痛みを和らげる治療はできません｣","explanation":"在宅でも医療用麻薬などで痛みを緩和できます。訪問診療・看護と連携し、症状悪化時の連絡方法を整えます。"},{"choice":5,"correct":false,"title":"｢感染対策のため、お兄ちゃんとの接触をできるだけ制限してください｣","explanation":"兄との時間も大切です。家族の体調や手指衛生などに配慮しつつ、一律の接触制限で交流を妨げないようにします。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答2、3を照合。本人の希望と病状に応じ、幼稚園と支援方法を調整して登園を検討できます。終末期であることだけで登園不可とはしません。 終末期は食べる楽しみを尊重し、不要な食事制限を避ける趣旨です。ただし誤嚥、衛生、アレルギーなど病状に応じた安全配慮は続けます。","fixes_made":["食事制限なしの趣旨に、誤嚥・衛生等の個別安全配慮を明記。"]},"input_anchor":{"question":"A 君の造血幹細胞移植は無事に終了したが、終了後6か月で2度目の再発をし、\n化学療法が行われたが寛解しなかった。医師から両親に A 君が終末期にあること、\n余命2か月程度であることが伝えられた。両親は｢2度目の再発と聞いて覚悟をし\nていた。延命するための治療はしなくてよいと考えています。在宅療養に切り替え\nて A と家で過ごしたいが、できることと、できないことを教えてほしいです｣と話\nした。\n両親への看護師の返答で適切なのはどれか。2つ選べ。","choices":["｢遊園地には行けません｣","｢幼稚園に登園できます｣","｢食べ物の制限はありません｣","｢痛みが出た場合、自宅では痛みを和らげる治療はできません｣","｢感染対策のため、お兄ちゃんとの接触をできるだけ制限してください｣"],"correct_answers":[2,3],"accepted_answer_sets":[[2,3]],"case_text":"A 君(5歳)は父親(40 歳)、母親(38 歳)と兄(10 歳)の4人家族である。A 君は生後\n6か月のときに白血病と診断され化学療法で寛解し、退院後は幼稚園に登園してい\nleukemia\nた。4歳になって再発し、兄を骨髄ドナーとした造血幹細胞移植を受けた。","preceding_context":[{"id":"112-PM-100","question":"A 君が利用できる制度はどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":101,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[42],"case_pages":[42],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B101"},"exam":112,"year":2023,"session":"PM","number":101},"sources":[]},{"id":"112-PM-102","record":{"id":"112-PM-102","choice_explanations":[{"choice":1,"correct":false,"title":"｢お兄ちゃんが病状を尋ねてくるのを待ちましょう｣","explanation":"兄が質問するまで何も伝えないと、変化を感じても不安を抱え込む場合があります。理解度に合う説明の機会を支えます。"},{"choice":2,"correct":false,"title":"｢頑張っている A 君のために、お兄ちゃんには治ると説明しましょう｣","explanation":"治ると事実と異なる説明をすると、後で不信や混乱につながります。分かる言葉で誠実に説明します。"},{"choice":3,"correct":true,"title":"｢看護師も同席してお兄ちゃんに説明する機会を設けることができます｣","explanation":"両親だけで抱え込まず、看護師も同席し兄の理解と気持ちを確かめながら伝えます。ドナーとしての罪悪感にも配慮します。"},{"choice":4,"correct":false,"title":"｢ドナーになったお兄ちゃんががっかりするので説明しないでおきましょう｣","explanation":"説明を避けると兄が状況から取り残されるおそれがあります。再発は兄の責任ではないことも含めて支援します。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答3を照合。両親だけで抱え込まず、看護師も同席し兄の理解と気持ちを確かめながら伝えます。ドナーとしての罪悪感にも配慮します。","fixes_made":[]},"input_anchor":{"question":"数日後、両親から｢A が亡くなることを A の兄にどのように説明したらよいで\nしょうか。私たちでは、うまく説明できません｣と相談があった。\n看護師の両親への対応で適切なのはどれか。","choices":["｢お兄ちゃんが病状を尋ねてくるのを待ちましょう｣","｢頑張っている A 君のために、お兄ちゃんには治ると説明しましょう｣","｢看護師も同席してお兄ちゃんに説明する機会を設けることができます｣","｢ドナーになったお兄ちゃんががっかりするので説明しないでおきましょう｣"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A 君(5歳)は父親(40 歳)、母親(38 歳)と兄(10 歳)の4人家族である。A 君は生後\n6か月のときに白血病と診断され化学療法で寛解し、退院後は幼稚園に登園してい\nleukemia\nた。4歳になって再発し、兄を骨髄ドナーとした造血幹細胞移植を受けた。","preceding_context":[{"id":"112-PM-100","question":"A 君が利用できる制度はどれか。"},{"id":"112-PM-101","question":"A 君の造血幹細胞移植は無事に終了したが、終了後6か月で2度目の再発をし、\n化学療法が行われたが寛解しなかった。医師から両親に A 君が終末期にあること、\n余命2か月程度であることが伝えられた。両親は｢2度目の再発と聞いて覚悟をし\nていた。延命するための治療はしなくてよいと考えています。在宅療養に切り替え\nて A と家で過ごしたいが、できることと、できないことを教えてほしいです｣と話\nした。\n両親への看護師の返答で適切なのはどれか。2つ選べ。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":102,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[43],"case_pages":[42],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B102"},"exam":112,"year":2023,"session":"PM","number":102},"sources":[]},{"id":"112-PM-103","record":{"id":"112-PM-103","choice_explanations":[{"choice":1,"correct":false,"title":"小発作","explanation":"小発作では日常生活への影響が小さく、酸素化も比較的保たれます。本例の会話困難とSpO2 92％はより強い発作です。"},{"choice":2,"correct":true,"title":"中発作","explanation":"著明な喘鳴、途切れる会話、SpO2 92％などは、出題時の小児喘息の中発作に合います。症状と酸素化を総合して判定します。"},{"choice":3,"correct":false,"title":"大発作","explanation":"大発作では会話がさらに困難となり、著明な呼吸努力やより強い低酸素を伴います。本例の所見は中発作に整理されます。"},{"choice":4,"correct":false,"title":"呼吸不全","explanation":"呼吸不全の最重症区分では意識低下、呼吸音減弱などが問題になります。本例は会話可能で、そのような所見は示されていません。"}],"status":"VERIFIED","review_reason":"問題・全選択肢・公式正答2を照合。著明な喘鳴、途切れる会話、SpO2 92％などは、出題時の小児喘息の中発作に合います。症状と酸素化を総合して判定します。","fixes_made":[]},"input_anchor":{"question":"A 君の気管支喘息の発作強度はどれか。","choices":["小発作","中発作","大発作","呼吸不全"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A 君(11 歳)は両親と3人で暮らしている。5歳で気管支喘息と診断され、現在は\nbronchial asthma\n抗アレルギー薬とステロイドの吸入薬が処方されている。本日、学校から帰ってきた\n後から咳嗽がみられ元気がなかった。夕食はあまり食べずに就寝した。夜間になり\n｢苦しくて眠れない｣と訴え、母親と救急外来を受診した。口元での喘鳴が著明であ\nり、問診すると途切れ途切れに話した。受診時のバイタルサインは、体温 36.9 ℃、\n呼吸数 32/分、心拍数 120/分、経皮的動脈血酸素飽和度〈SpO2〉92 %(room air)で\nあった。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":103,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[44],"case_pages":[44],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B103"},"exam":112,"year":2023,"session":"PM","number":103},"sources":[{"title":"環境再生保全機構 中発作","url":"https://www.erca.go.jp/yobou/zensoku/basic/glossary/kw58.html"}]},{"id":"112-PM-104","record":{"id":"112-PM-104","choice_explanations":[{"choice":1,"correct":true,"title":"A 君に発言の理由を尋ねる。","explanation":"入院への不安や自分で決めたい気持ちなど、発言の背景を本人に尋ねます。思春期に向かう自立への思いも尊重します。"},{"choice":2,"correct":false,"title":"A 君ではなく母親から病状を聴取する。","explanation":"本人は医療者の問診に答えられます。本人を外して母親だけから情報を得ると、主体性を損ないます。"},{"choice":3,"correct":false,"title":"母親への態度は問題行動であると A 君に忠告する。","explanation":"反抗的な発言だけで問題行動と決めつけるのは不適切です。まず気持ちと理由を理解します。"},{"choice":4,"correct":false,"title":"親子関係に問題があるのではないかと母親に伝える。","explanation":"この一場面だけで親子関係の問題と判断できません。発達段階や病気への思いを丁寧に確認します。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1を照合。入院への不安や自分で決めたい気持ちなど、発言の背景を本人に尋ねます。思春期に向かう自立への思いも尊重します。","fixes_made":[]},"input_anchor":{"question":"救急外来で、吸入と点滴静脈内注射が行われ A 君の症状は軽快した。A 君は、\n医師や看護師による問診には素直に答えているが、心配する母親には｢病院に来る\nほどじゃないんだよ。入院はしないからな｣と発言し、反抗的な態度をとっている。\nこのときの看護師の対応で適切なのはどれか。","choices":["A 君に発言の理由を尋ねる。","A 君ではなく母親から病状を聴取する。","母親への態度は問題行動であると A 君に忠告する。","親子関係に問題があるのではないかと母親に伝える。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":"A 君(11 歳)は両親と3人で暮らしている。5歳で気管支喘息と診断され、現在は\nbronchial asthma\n抗アレルギー薬とステロイドの吸入薬が処方されている。本日、学校から帰ってきた\n後から咳嗽がみられ元気がなかった。夕食はあまり食べずに就寝した。夜間になり\n｢苦しくて眠れない｣と訴え、母親と救急外来を受診した。口元での喘鳴が著明であ\nり、問診すると途切れ途切れに話した。受診時のバイタルサインは、体温 36.9 ℃、\n呼吸数 32/分、心拍数 120/分、経皮的動脈血酸素飽和度〈SpO2〉92 %(room air)で\nあった。","preceding_context":[{"id":"112-PM-103","question":"A 君の気管支喘息の発作強度はどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":104,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[44],"case_pages":[44],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B104"},"exam":112,"year":2023,"session":"PM","number":104},"sources":[]},{"id":"112-PM-105","record":{"id":"112-PM-105","choice_explanations":[{"choice":1,"correct":false,"title":"毎日運動するよう勧める。","explanation":"運動方法の相談も必要ですが、吸入を面倒と感じて中断する問題への対応が先です。無条件の毎日の運動は適切ではありません。"},{"choice":2,"correct":false,"title":"お薬手帳を持ち歩くよう伝える。","explanation":"お薬手帳の携帯は有用ですが、長期管理薬の必要性への誤解や服薬継続の困難を直接解決しません。"},{"choice":3,"correct":true,"title":"A 君と服薬管理について話し合う。","explanation":"症状がない間も炎症を抑える薬が必要なことを説明し、続けにくい理由と実行できる管理方法を本人と話し合います。"},{"choice":4,"correct":false,"title":"喘息発作があったことを母親から担任の先生に伝えるよう提案する。","explanation":"学校との連携も大切ですが、中心課題は本人の薬への認識と管理です。本人の参加を促す支援が優先されます。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答3を照合。症状がない間も炎症を抑える薬が必要なことを説明し、続けにくい理由と実行できる管理方法を本人と話し合います。","fixes_made":[]},"input_anchor":{"question":"A 君は1年前から気管支喘息の急性増悪〈発作〉を起こして救急外来の受診を繰\nbronchial asthma\nり返していることが分かった。看護師が A 君に今の症状に対する認識を確認する\nと｢喘息発作が起きていて、家で吸入をしても治まらなかった｣と答えた。学校生活\nや服薬については｢学校は好きだけど、体育は嫌だな。吸入が面倒くさい。吸入し\nなくても発作が起きなければいいんでしょ｣と話した。看護師は、急性増悪〈発作〉\nを繰り返している A 君のセルフケアへの支援をする必要があると考えた。\nA 君への看護師の対応で最も適切なのはどれか。","choices":["毎日運動するよう勧める。","お薬手帳を持ち歩くよう伝える。","A 君と服薬管理について話し合う。","喘息発作があったことを母親から担任の先生に伝えるよう提案する。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A 君(11 歳)は両親と3人で暮らしている。5歳で気管支喘息と診断され、現在は\nbronchial asthma\n抗アレルギー薬とステロイドの吸入薬が処方されている。本日、学校から帰ってきた\n後から咳嗽がみられ元気がなかった。夕食はあまり食べずに就寝した。夜間になり\n｢苦しくて眠れない｣と訴え、母親と救急外来を受診した。口元での喘鳴が著明であ\nり、問診すると途切れ途切れに話した。受診時のバイタルサインは、体温 36.9 ℃、\n呼吸数 32/分、心拍数 120/分、経皮的動脈血酸素飽和度〈SpO2〉92 %(room air)で\nあった。","preceding_context":[{"id":"112-PM-103","question":"A 君の気管支喘息の発作強度はどれか。"},{"id":"112-PM-104","question":"救急外来で、吸入と点滴静脈内注射が行われ A 君の症状は軽快した。A 君は、\n医師や看護師による問診には素直に答えているが、心配する母親には｢病院に来る\nほどじゃないんだよ。入院はしないからな｣と発言し、反抗的な態度をとっている。\nこのときの看護師の対応で適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":105,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[45],"case_pages":[44],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B105"},"exam":112,"year":2023,"session":"PM","number":105},"sources":[]},{"id":"112-PM-106","record":{"id":"112-PM-106","choice_explanations":[{"choice":1,"correct":false,"title":"貧血がある。","explanation":"Hb12.0g/dLで、記載上は貧血と判断する所見ではありません。バイタルサインも安定しています。"},{"choice":2,"correct":false,"title":"感染徴候がある。","explanation":"発熱、会陰部の発赤・腫脹など感染を示す所見はありません。悪露も産褥1日として矛盾しません。"},{"choice":3,"correct":true,"title":"正常な経過である。","explanation":"硬い子宮底、赤色悪露、授乳時の後陣痛は産褥早期の正常範囲です。体温や排尿も良好です。"},{"choice":4,"correct":false,"title":"子宮復古不全である。","explanation":"子宮は硬く収縮し、大量出血や大きな凝血はありません。子宮復古不全を示す所見ではありません。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答3を照合。硬い子宮底、赤色悪露、授乳時の後陣痛は産褥早期の正常範囲です。体温や排尿も良好です。","fixes_made":[]},"input_anchor":{"question":"A さんの産褥1日のアセスメントで正しいのはどれか。","choices":["貧血がある。","感染徴候がある。","正常な経過である。","子宮復古不全である。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A さん(28 歳、初産婦)は妊娠 38 週1日、順調な経過で経腟分娩した。産後は夫が\n育児休業を取得し、自宅で夫と2人で子育てをする予定である。\n産 褥 1 日、バ イ タ ル サ イ ン は、体 温 36.7 ℃、脈 拍 70/分、整、血 圧 118/68\nmmHg、Hb 12.0 g/dL。子宮底は臍下2横指のところに硬く触れている。悪露は赤\n色で中等量、凝血の混入はない。A さんは授乳時に後陣痛を訴えている。会陰縫合\n部に腫脹や発赤はなく、痛みは自制内である。尿意の自覚があり、残尿感や排尿困難\n感はない。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":106,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[46],"case_pages":[46],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B106"},"exam":112,"year":2023,"session":"PM","number":106},"sources":[]},{"id":"112-PM-107","record":{"id":"112-PM-107","choice_explanations":[{"choice":1,"correct":true,"title":"｢着替え用の衣類が冷たくないか、沐浴前に確認しておきましょう｣","explanation":"沐浴後の熱喪失を抑えるため、衣類やタオルをあらかじめ準備し、冷たくないか確認します。手早く拭いて着衣できる環境を整えます。"},{"choice":2,"correct":false,"title":"｢10 分程度お湯に浸けて赤ちゃんを温めましょう｣","explanation":"長時間湯に浸けると体力消耗や体温変化を招きます。沐浴全体を短時間で済ませ、保温は室温や着衣で行います。"},{"choice":3,"correct":false,"title":"｢ベビーバスには 50 ℃のお湯を準備しましょう｣","explanation":"50℃は熱傷の危険があります。湯温はおおむね38〜40℃程度を目安に、必ず確認します。"},{"choice":4,"correct":false,"title":"｢沐浴する場所の室温は 30 ℃に設定しましょう｣","explanation":"室温30℃は高すぎます。季節や環境に応じ、おおむね24〜26℃程度の快適な室温を整えます。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1を照合。沐浴後の熱喪失を抑えるため、衣類やタオルをあらかじめ準備し、冷たくないか確認します。手早く拭いて着衣できる環境を整えます。","fixes_made":[]},"input_anchor":{"question":"産褥3日、A さんの夫から｢退院後は私が子どもの沐浴をします。子どもの身体\nの洗い方は動画で学んだのですが、沐浴のときに注意することはありますか。寒い\n時期なので心配です｣と看護師に質問があった。\nA さんの夫への説明で適切なのはどれか。","choices":["｢着替え用の衣類が冷たくないか、沐浴前に確認しておきましょう｣","｢10 分程度お湯に浸けて赤ちゃんを温めましょう｣","｢ベビーバスには 50 ℃のお湯を準備しましょう｣","｢沐浴する場所の室温は 30 ℃に設定しましょう｣"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":"A さん(28 歳、初産婦)は妊娠 38 週1日、順調な経過で経腟分娩した。産後は夫が\n育児休業を取得し、自宅で夫と2人で子育てをする予定である。\n産 褥 1 日、バ イ タ ル サ イ ン は、体 温 36.7 ℃、脈 拍 70/分、整、血 圧 118/68\nmmHg、Hb 12.0 g/dL。子宮底は臍下2横指のところに硬く触れている。悪露は赤\n色で中等量、凝血の混入はない。A さんは授乳時に後陣痛を訴えている。会陰縫合\n部に腫脹や発赤はなく、痛みは自制内である。尿意の自覚があり、残尿感や排尿困難\n感はない。","preceding_context":[{"id":"112-PM-106","question":"A さんの産褥1日のアセスメントで正しいのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":107,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[46],"case_pages":[46],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B107"},"exam":112,"year":2023,"session":"PM","number":107},"sources":[]},{"id":"112-PM-108","record":{"id":"112-PM-108","choice_explanations":[{"choice":1,"correct":false,"title":"｢基礎体温法が適しています｣","explanation":"産後は月経・排卵が不規則で、夜間授乳によって基礎体温も測りにくくなります。単独の避妊法として適しません。"},{"choice":2,"correct":false,"title":"｢経口避妊薬は産後1か月から服用できます｣","explanation":"授乳中の複合経口避妊薬は乳汁分泌や血栓症リスクなどから慎重な判断が必要です。産後1か月で一律に再開できるとは説明しません。"},{"choice":3,"correct":true,"title":"｢性交再開時からコンドームを使用しましょう｣","explanation":"初回月経の前に排卵が起こる場合があります。性交再開時からコンドームを正しく使い、妊娠を予防します。"},{"choice":4,"correct":false,"title":"｢母乳を与えている間は妊娠の心配はありません｣","explanation":"授乳中でも排卵・妊娠は起こり得ます。母乳だけを理由に妊娠の心配がないとはいえません。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答3を照合。初回月経の前に排卵が起こる場合があります。性交再開時からコンドームを正しく使い、妊娠を予防します。","fixes_made":[]},"input_anchor":{"question":"産褥5日、子宮収縮は臍恥中央、褐色悪露が少量、歩行時に会陰部痛がある。授\n乳は母乳のみで行っている。A さんは｢この子の世話が大変で、次の妊娠はしばら\nく考えられません。結婚前は経口避妊薬を服用していましたが、産後の避妊はどう\nしたらよいか教えてください｣と看護師に話した。\nA さんへの説明で適切なのはどれか。","choices":["｢基礎体温法が適しています｣","｢経口避妊薬は産後1か月から服用できます｣","｢性交再開時からコンドームを使用しましょう｣","｢母乳を与えている間は妊娠の心配はありません｣"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A さん(28 歳、初産婦)は妊娠 38 週1日、順調な経過で経腟分娩した。産後は夫が\n育児休業を取得し、自宅で夫と2人で子育てをする予定である。\n産 褥 1 日、バ イ タ ル サ イ ン は、体 温 36.7 ℃、脈 拍 70/分、整、血 圧 118/68\nmmHg、Hb 12.0 g/dL。子宮底は臍下2横指のところに硬く触れている。悪露は赤\n色で中等量、凝血の混入はない。A さんは授乳時に後陣痛を訴えている。会陰縫合\n部に腫脹や発赤はなく、痛みは自制内である。尿意の自覚があり、残尿感や排尿困難\n感はない。","preceding_context":[{"id":"112-PM-106","question":"A さんの産褥1日のアセスメントで正しいのはどれか。"},{"id":"112-PM-107","question":"産褥3日、A さんの夫から｢退院後は私が子どもの沐浴をします。子どもの身体\nの洗い方は動画で学んだのですが、沐浴のときに注意することはありますか。寒い\n時期なので心配です｣と看護師に質問があった。\nA さんの夫への説明で適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":108,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[47],"case_pages":[46],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B108"},"exam":112,"year":2023,"session":"PM","number":108},"sources":[]},{"id":"112-PM-109","record":{"id":"112-PM-109","choice_explanations":[{"choice":1,"correct":false,"title":"父親に薬の管理を依頼する。","explanation":"高齢の父親へ一方的に管理を任せると負担が増え、本人の力も活かせません。まず本人と忘れる状況を確認します。"},{"choice":2,"correct":true,"title":"薬を飲み忘れない方法を話し合う。","explanation":"服薬を忘れる場面や理由を本人と整理し、薬箱や生活習慣との組合せなど続けやすい方法を一緒に考えます。"},{"choice":3,"correct":false,"title":"外来受診時に薬局の薬剤師に服薬指導を依頼する。","explanation":"薬剤師との連携は有用ですが、訪問時に本人と実際の困り事を話し合うことが先です。"},{"choice":4,"correct":false,"title":"デイケアの再開を主治医と相談するように提案する。","explanation":"デイケア再開は今後の課題ですが、まず服薬継続を妨げる要因に対応し、生活と症状を安定させます。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答2を照合。服薬を忘れる場面や理由を本人と整理し、薬箱や生活習慣との組合せなど続けやすい方法を一緒に考えます。","fixes_made":[]},"input_anchor":{"question":"このときの訪問看護師の対応で優先度が高いのはどれか。","choices":["父親に薬の管理を依頼する。","薬を飲み忘れない方法を話し合う。","外来受診時に薬局の薬剤師に服薬指導を依頼する。","デイケアの再開を主治医と相談するように提案する。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(58 歳、男性)は、年金の給付を受けて生活している父親(82 歳)と2人暮ら\nしで、母親は2年前に亡くなっている。20 歳のときに統合失調症と診断された。20\nschizophrenia\n歳代で何回か仕事に就いたが長続きはしなかった。40 歳からは無職で、デイケアへ\n通所していた。1年前にデイケアを中断してからは、ほとんどの時間を自宅で過ごし\nているが、月1回の外来通院は継続している。A さんが飲まなかった薬がたくさん\n残っていることを父親が発見し、主治医に相談した。この相談をきっかけに、週1回\nの精神科訪問看護を導入することになった。初回訪問時に A さんは｢薬は飲み忘れた\nんです。心配かけてごめんなさい｣と父親と訪問看護師に話した。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":109,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[48],"case_pages":[48],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B109"},"exam":112,"year":2023,"session":"PM","number":109},"sources":[]},{"id":"112-PM-110","record":{"id":"112-PM-110","choice_explanations":[{"choice":1,"correct":false,"title":"｢朝起きられるように毎朝の日課を何か作りましょう｣","explanation":"薬の影響が疑われる眠気を日課だけで解決しようとするのは不十分です。まず処方に関する相談を支援します。"},{"choice":2,"correct":true,"title":"｢朝に眠気が残ることを主治医に相談してみませんか｣","explanation":"朝まで残る眠気は副作用の可能性があります。自己中断を防ぐため、主治医に相談して薬や服用時刻を検討できるよう支援します。"},{"choice":3,"correct":false,"title":"｢来週は朝早く一緒に散歩へ行けるように訪問しますね｣","explanation":"強い眠気があるまま早朝の散歩を設定しても負担となります。原因への対応が先です。"},{"choice":4,"correct":false,"title":"｢朝起こしてもらうようにお父さんにお願いしてみませんか｣","explanation":"父親に起こしてもらうだけでは薬の持ち越し効果は解決しません。本人の訴えを主治医につなぎます。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答2を照合。朝まで残る眠気は副作用の可能性があります。自己中断を防ぐため、主治医に相談して薬や服用時刻を検討できるよう支援します。","fixes_made":[]},"input_anchor":{"question":"初回訪問から1か月、訪問看護師は A さんが適切に服薬できていることを確認\nした。A さんは｢調子はいいですね。やる気も少し出てきました。主治医は今の薬\nを飲み続けるのがいいと話しています。ただ、夜の薬は朝に眠気が残るので昼まで\n寝てしまいます｣と話した。\nこのときの訪問看護師の A さんへの声かけで最も適切なのはどれか。","choices":["｢朝起きられるように毎朝の日課を何か作りましょう｣","｢朝に眠気が残ることを主治医に相談してみませんか｣","｢来週は朝早く一緒に散歩へ行けるように訪問しますね｣","｢朝起こしてもらうようにお父さんにお願いしてみませんか｣"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(58 歳、男性)は、年金の給付を受けて生活している父親(82 歳)と2人暮ら\nしで、母親は2年前に亡くなっている。20 歳のときに統合失調症と診断された。20\nschizophrenia\n歳代で何回か仕事に就いたが長続きはしなかった。40 歳からは無職で、デイケアへ\n通所していた。1年前にデイケアを中断してからは、ほとんどの時間を自宅で過ごし\nているが、月1回の外来通院は継続している。A さんが飲まなかった薬がたくさん\n残っていることを父親が発見し、主治医に相談した。この相談をきっかけに、週1回\nの精神科訪問看護を導入することになった。初回訪問時に A さんは｢薬は飲み忘れた\nんです。心配かけてごめんなさい｣と父親と訪問看護師に話した。","preceding_context":[{"id":"112-PM-109","question":"このときの訪問看護師の対応で優先度が高いのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":110,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[48],"case_pages":[48],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B110"},"exam":112,"year":2023,"session":"PM","number":110},"sources":[]},{"id":"112-PM-111","record":{"id":"112-PM-111","choice_explanations":[{"choice":1,"correct":false,"title":"生活保護","explanation":"生活保護は経済的困窮に対応する制度です。今回の中心である、支援を受けながら暮らす場の検討にはグループホームが適します。"},{"choice":2,"correct":false,"title":"地域移行支援","explanation":"地域移行支援は主に病院や施設から地域へ移る人を対象とします。Aさんはすでに地域で暮らしています。"},{"choice":3,"correct":true,"title":"グループホーム","explanation":"グループホームでは共同生活の中で食事などの日常生活支援を受けられます。父親亡き後の住まいとして本人と見学などを検討できます。"},{"choice":4,"correct":false,"title":"障害者権利擁護センター","explanation":"権利擁護の相談は虐待や権利侵害などへの支援です。日常生活を支える住居を直接提供するものではありません。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答3を照合。グループホームでは共同生活の中で食事などの日常生活支援を受けられます。父親亡き後の住まいとして本人と見学などを検討できます。","fixes_made":[]},"input_anchor":{"question":"初回訪問から6か月、A さんの状態は安定し、デイケアへ週3回程度は通所で\nきるようになった。一方で、父親は｢A は食事も作れないし、家のことができない\nので、自分が死んだ後のことを考えると1人で生きていけるのかが心配だ。どうし\nたらよいか｣と訪問看護師に相談した。それを聞いた A さんも｢父が死んだ後の生\n活が心配だ｣と話した。\n現時点で A さんと父親へ提案する社会資源で適切なのはどれか。","choices":["生活保護","地域移行支援","グループホーム","障害者権利擁護センター"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A さん(58 歳、男性)は、年金の給付を受けて生活している父親(82 歳)と2人暮ら\nしで、母親は2年前に亡くなっている。20 歳のときに統合失調症と診断された。20\nschizophrenia\n歳代で何回か仕事に就いたが長続きはしなかった。40 歳からは無職で、デイケアへ\n通所していた。1年前にデイケアを中断してからは、ほとんどの時間を自宅で過ごし\nているが、月1回の外来通院は継続している。A さんが飲まなかった薬がたくさん\n残っていることを父親が発見し、主治医に相談した。この相談をきっかけに、週1回\nの精神科訪問看護を導入することになった。初回訪問時に A さんは｢薬は飲み忘れた\nんです。心配かけてごめんなさい｣と父親と訪問看護師に話した。","preceding_context":[{"id":"112-PM-109","question":"このときの訪問看護師の対応で優先度が高いのはどれか。"},{"id":"112-PM-110","question":"初回訪問から1か月、訪問看護師は A さんが適切に服薬できていることを確認\nした。A さんは｢調子はいいですね。やる気も少し出てきました。主治医は今の薬\nを飲み続けるのがいいと話しています。ただ、夜の薬は朝に眠気が残るので昼まで\n寝てしまいます｣と話した。\nこのときの訪問看護師の A さんへの声かけで最も適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":111,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[49],"case_pages":[48],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B111"},"exam":112,"year":2023,"session":"PM","number":111},"sources":[]},{"id":"112-PM-112","record":{"id":"112-PM-112","choice_explanations":[{"choice":1,"correct":true,"title":"脱 水","explanation":"水分摂取の減少、口唇乾燥、発熱、頻脈、高Na血症から脱水が考えられます。入出量と循環状態を評価します。"},{"choice":2,"correct":false,"title":"貧 血","explanation":"Hb12.5g/dLで、本問では貧血を積極的に示す所見ではありません。意識変化の背景には感染や脱水などを考えます。"},{"choice":3,"correct":false,"title":"低栄養","explanation":"食事は摂れており、アルブミン4.0g/dLです。現時点で低栄養を優先的に示す根拠は乏しい状態です。"},{"choice":4,"correct":false,"title":"視空間失認","explanation":"場所が分からない混乱は見当識障害を示します。視覚的な空間認知の障害である視空間失認とは断定できません。"},{"choice":5,"correct":true,"title":"電解質異常","explanation":"Na151mEq/Lは高ナトリウム血症です。水分不足による電解質異常があり、意識変化にも関係し得ます。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1、5を照合。水分摂取の減少、口唇乾燥、発熱、頻脈、高Na血症から脱水が考えられます。入出量と循環状態を評価します。 Na151mEq/Lは高ナトリウム血症です。水分不足による電解質異常があり、意識変化にも関係し得ます。","fixes_made":[]},"input_anchor":{"question":"A さんの状態のアセスメントで適切なのはどれか。2つ選べ。","choices":["脱 水","貧 血","低栄養","視空間失認","電解質異常"],"correct_answers":[1,5],"accepted_answer_sets":[[1,5]],"case_text":"A さん(80 歳、女性)は発熱があり、呼吸状態が悪いため、外来を受診し肺炎と診\npneumonia\n断され緊急入院となった。\n入院時、病室で A さんは｢ここはどこ｣と話し混乱した様子であった。湿性の咳嗽\nがあり、口唇の乾燥が著明である。同居の夫からの情報では、1週前から食事は摂れ\nていたが、水分摂取量が減っていた。3日前から寝て過ごしていたが、トイレには自\n分で行くことができていた。身の回りのことは自立している。入院後に点滴静脈内注\n射 1,500 mL/日の指示があり、抗菌薬が開始された。\n身体所見：身長 152 cm、体重 45 kg、体温 38.0 ℃、呼吸数 32/分、脈拍 120/分、整、\n血圧 107/80 mmHg、経皮的動脈血酸素飽和度〈SpO2〉93 %(room air)。\nジャパン・コーマ・スケール〈JCS〉Ⅰ- 2。\n検査所見：赤血球 447 万/μL、Hb 12.5 g/dL、白血球 16,600/μL、総蛋白 6.2 g/dL、\nアルブミン 4.0 g/dL、血糖 98 mg/dL、Na 151 mEq/L、K 4.0 mEq/L、\nCl 97 mEq/L、Ca 8.7 mg/dL、CRP 23.0 mg/dL。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":112,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[50],"case_pages":[50],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B112"},"exam":112,"year":2023,"session":"PM","number":112},"sources":[]},{"id":"112-PM-113","record":{"id":"112-PM-113","choice_explanations":[{"choice":1,"correct":true,"title":"せん妄\ndelirium","explanation":"感染や脱水、入院環境の変化を背景に急に混乱し、夜間に悪化する変動がみられます。せん妄に合致する経過です。"},{"choice":2,"correct":false,"title":"睡眠時遊行症\nsleepwalking","explanation":"睡眠時遊行症は主にノンレム睡眠中の歩行などです。覚醒時の見当識障害や日内変動を含む本例全体を説明しません。"},{"choice":3,"correct":false,"title":"レム睡眠行動障害\nREM sleep behavior disorder","explanation":"レム睡眠行動障害は夢に伴う動作や発声を示します。夕方からの混乱と注意・認知の変動はせん妄を示唆します。"},{"choice":4,"correct":false,"title":"睡眠時無呼吸症候群\nsleep apnea syndrome","explanation":"睡眠時無呼吸では睡眠中の反復する呼吸停止などが中心です。その所見は示されていません。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1を照合。感染や脱水、入院環境の変化を背景に急に混乱し、夜間に悪化する変動がみられます。せん妄に合致する経過です。","fixes_made":[]},"input_anchor":{"question":"入院当日、A さんは日中は会話ができていたが、夕方からそわそわしながら落\nち着かない様子であった。また、話のつじつまが合わず、朝と夕方を間違え急に大\nきな声を出し、夜中に起きだして自分の荷物を触っていることがあった。翌日、日\n中は眠気を訴えながらも眠ることなく静かに過ごし、夜間は焦燥があり眠れていな\nい。\nA さんの状態はどれか。","choices":["せん妄\ndelirium","睡眠時遊行症\nsleepwalking","レム睡眠行動障害\nREM sleep behavior disorder","睡眠時無呼吸症候群\nsleep apnea syndrome"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":"A さん(80 歳、女性)は発熱があり、呼吸状態が悪いため、外来を受診し肺炎と診\npneumonia\n断され緊急入院となった。\n入院時、病室で A さんは｢ここはどこ｣と話し混乱した様子であった。湿性の咳嗽\nがあり、口唇の乾燥が著明である。同居の夫からの情報では、1週前から食事は摂れ\nていたが、水分摂取量が減っていた。3日前から寝て過ごしていたが、トイレには自\n分で行くことができていた。身の回りのことは自立している。入院後に点滴静脈内注\n射 1,500 mL/日の指示があり、抗菌薬が開始された。\n身体所見：身長 152 cm、体重 45 kg、体温 38.0 ℃、呼吸数 32/分、脈拍 120/分、整、\n血圧 107/80 mmHg、経皮的動脈血酸素飽和度〈SpO2〉93 %(room air)。\nジャパン・コーマ・スケール〈JCS〉Ⅰ- 2。\n検査所見：赤血球 447 万/μL、Hb 12.5 g/dL、白血球 16,600/μL、総蛋白 6.2 g/dL、\nアルブミン 4.0 g/dL、血糖 98 mg/dL、Na 151 mEq/L、K 4.0 mEq/L、\nCl 97 mEq/L、Ca 8.7 mg/dL、CRP 23.0 mg/dL。","preceding_context":[{"id":"112-PM-112","question":"A さんの状態のアセスメントで適切なのはどれか。2つ選べ。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":113,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[51],"case_pages":[50],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B113"},"exam":112,"year":2023,"session":"PM","number":113},"sources":[]},{"id":"112-PM-114","record":{"id":"112-PM-114","choice_explanations":[{"choice":1,"correct":true,"title":"日中の離床を促すために歩行に付き添う。","explanation":"状態に合わせて付き添い歩行を行い、昼間の覚醒と活動を促します。安全を確保しながら睡眠覚醒リズムを整えます。"},{"choice":2,"correct":false,"title":"夜間はベッドからの転落防止のために身体的拘束を行う。","explanation":"身体拘束は恐怖や興奮を強め、せん妄を悪化させ得ます。一律に用いず、見守りや環境調整などを優先します。"},{"choice":3,"correct":false,"title":"睡眠時間の確保のために夕方に3時間の睡眠をとるように勧める。","explanation":"夕方の長い睡眠は夜間の不眠を助長します。日中の活動と夜間の休息を整えます。"},{"choice":4,"correct":false,"title":"症状緩和のためにベンゾジアゼピン系睡眠薬の処方を医師に依頼する。","explanation":"ベンゾジアゼピン系はせん妄を誘発・悪化させることがあります。離脱など特別な適応がない本例で第一に依頼する薬ではありません。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1を照合。状態に合わせて付き添い歩行を行い、昼間の覚醒と活動を促します。安全を確保しながら睡眠覚醒リズムを整えます。","fixes_made":[]},"input_anchor":{"question":"入院2日、病棟の看護師で A さんへの援助の方針について話し合った。\nA さんへの対応で適切なのはどれか。","choices":["日中の離床を促すために歩行に付き添う。","夜間はベッドからの転落防止のために身体的拘束を行う。","睡眠時間の確保のために夕方に3時間の睡眠をとるように勧める。","症状緩和のためにベンゾジアゼピン系睡眠薬の処方を医師に依頼する。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":"A さん(80 歳、女性)は発熱があり、呼吸状態が悪いため、外来を受診し肺炎と診\npneumonia\n断され緊急入院となった。\n入院時、病室で A さんは｢ここはどこ｣と話し混乱した様子であった。湿性の咳嗽\nがあり、口唇の乾燥が著明である。同居の夫からの情報では、1週前から食事は摂れ\nていたが、水分摂取量が減っていた。3日前から寝て過ごしていたが、トイレには自\n分で行くことができていた。身の回りのことは自立している。入院後に点滴静脈内注\n射 1,500 mL/日の指示があり、抗菌薬が開始された。\n身体所見：身長 152 cm、体重 45 kg、体温 38.0 ℃、呼吸数 32/分、脈拍 120/分、整、\n血圧 107/80 mmHg、経皮的動脈血酸素飽和度〈SpO2〉93 %(room air)。\nジャパン・コーマ・スケール〈JCS〉Ⅰ- 2。\n検査所見：赤血球 447 万/μL、Hb 12.5 g/dL、白血球 16,600/μL、総蛋白 6.2 g/dL、\nアルブミン 4.0 g/dL、血糖 98 mg/dL、Na 151 mEq/L、K 4.0 mEq/L、\nCl 97 mEq/L、Ca 8.7 mg/dL、CRP 23.0 mg/dL。","preceding_context":[{"id":"112-PM-112","question":"A さんの状態のアセスメントで適切なのはどれか。2つ選べ。"},{"id":"112-PM-113","question":"入院当日、A さんは日中は会話ができていたが、夕方からそわそわしながら落\nち着かない様子であった。また、話のつじつまが合わず、朝と夕方を間違え急に大\nきな声を出し、夜中に起きだして自分の荷物を触っていることがあった。翌日、日\n中は眠気を訴えながらも眠ることなく静かに過ごし、夜間は焦燥があり眠れていな\nい。\nA さんの状態はどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":114,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[51],"case_pages":[50],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B114"},"exam":112,"year":2023,"session":"PM","number":114},"sources":[]},{"id":"112-PM-115","record":{"id":"112-PM-115","choice_explanations":[{"choice":1,"correct":false,"title":"長男の仕事内容","explanation":"長男の仕事内容そのものは、今回の医療費助成申請で最優先の情報ではありません。本人の費用負担や所得状況を確認します。"},{"choice":2,"correct":true,"title":"A さんの経済状況","explanation":"難病医療費助成の自己負担上限などには所得区分が関係します。自営業を含む経済状況を伝えると、適切な支援につながります。"},{"choice":3,"correct":false,"title":"母親の病状の経過","explanation":"母親の経過は遺伝相談や病気の理解に役立ちますが、医療費助成申請に向けた優先情報は本人の経済状況です。"},{"choice":4,"correct":false,"title":"妹の遺伝子診断の予定","explanation":"妹の検査は妹本人の意思とプライバシーに関わります。本人の医療費助成申請で最優先に伝える内容ではありません。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答2を照合。難病医療費助成の自己負担上限などには所得区分が関係します。自営業を含む経済状況を伝えると、適切な支援につながります。","fixes_made":[]},"input_anchor":{"question":"A さんから保健師に伝える内容で優先度が高いのはどれか。","choices":["長男の仕事内容","A さんの経済状況","母親の病状の経過","妹の遺伝子診断の予定"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(50 歳、男性、自営業)は妻(48 歳)、長男(23 歳、会社員)と3人で暮らして\nいる。3年前から歩行時のふらつきを自覚していたが、日常生活動作〈ADL〉は自立\nしていた。最近、転倒が多くなり医療機関を受診して頭部 CT 検査を受けたところ、\n小脳と脳幹に萎縮を認め、遺伝性の脊髄小脳変性症と診断された。A さんは｢母も同\nspinocerebellar degeneration\nじ疾患で亡くなりました。妹が同じ敷地内に1人で暮らしていますが、妹も転ぶこと\nが多くなり、医師の勧めで遺伝子診断を受ける予定です。明日、保健所に難病の医療\n費助成の申請に行くのですが、保健師に伝えた方がよいことはありますか｣と看護師\nに質問した。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":115,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[52],"case_pages":[52],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B115"},"exam":112,"year":2023,"session":"PM","number":115},"sources":[]},{"id":"112-PM-116","record":{"id":"112-PM-116","choice_explanations":[{"choice":1,"correct":true,"title":"長男が脊髄小脳変性症についてどの程度知っているか確認することを勧め\nる。","explanation":"成人の長男自身が判断できるよう、まず病気や検査についてどの程度理解しているか確かめます。遺伝カウンセリングも検討します。"},{"choice":2,"correct":false,"title":"長男には症状がないので発症前診断では発症の予測はできないと説明する。","explanation":"発症前診断は無症状の段階で遺伝子変化などを調べるものです。予測可能性や限界は病型ごとに異なり、一律に不可能ではありません。"},{"choice":3,"correct":false,"title":"両親の同意があれば長男が発症前診断を受けることができると説明する。","explanation":"長男は成人であり、検査には本人の十分な理解と自発的同意が必要です。両親の同意だけで受けさせることはできません。"},{"choice":4,"correct":false,"title":"長男が頭部 CT 検査を受けることを勧める。","explanation":"無症状の長男にCTを直ちに勧めるより、遺伝性疾患と検査の意味を理解し、本人の希望を確認することが先です。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1を照合。成人の長男自身が判断できるよう、まず病気や検査についてどの程度理解しているか確かめます。遺伝カウンセリングも検討します。","fixes_made":[]},"input_anchor":{"question":"1か月後の定期受診のときに、A さんは｢長男に私の病名と遺伝性の疾患である\nことを伝えました。長男には何も症状はありませんが、発症前診断を受けて欲しい\nと思っています｣と外来の看護師に話した。\n看護師の A さんへの対応で適切なのはどれか。","choices":["長男が脊髄小脳変性症についてどの程度知っているか確認することを勧め\nる。","長男には症状がないので発症前診断では発症の予測はできないと説明する。","両親の同意があれば長男が発症前診断を受けることができると説明する。","長男が頭部 CT 検査を受けることを勧める。"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":"A さん(50 歳、男性、自営業)は妻(48 歳)、長男(23 歳、会社員)と3人で暮らして\nいる。3年前から歩行時のふらつきを自覚していたが、日常生活動作〈ADL〉は自立\nしていた。最近、転倒が多くなり医療機関を受診して頭部 CT 検査を受けたところ、\n小脳と脳幹に萎縮を認め、遺伝性の脊髄小脳変性症と診断された。A さんは｢母も同\nspinocerebellar degeneration\nじ疾患で亡くなりました。妹が同じ敷地内に1人で暮らしていますが、妹も転ぶこと\nが多くなり、医師の勧めで遺伝子診断を受ける予定です。明日、保健所に難病の医療\n費助成の申請に行くのですが、保健師に伝えた方がよいことはありますか｣と看護師\nに質問した。","preceding_context":[{"id":"112-PM-115","question":"A さんから保健師に伝える内容で優先度が高いのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":116,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[52],"case_pages":[52],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B116"},"exam":112,"year":2023,"session":"PM","number":116},"sources":[]},{"id":"112-PM-117","record":{"id":"112-PM-117","choice_explanations":[{"choice":1,"correct":false,"title":"ベッド上で食事を摂るよう説明する。","explanation":"ベッド上での食事に限定すると活動や生活の範囲が狭まります。安全に移動して食べられる方法を検討します。"},{"choice":2,"correct":false,"title":"移乗の介助を妻に依頼するよう勧める。","explanation":"妻は日中仕事をしており、毎回の介助を求めるだけでは生活条件に合いません。本人の自立と安全を支える手段を考えます。"},{"choice":3,"correct":false,"title":"立位でのリハビリテーションを指導する。","explanation":"立ちくらみと転倒があるため、単独で行う立位訓練を直ちに勧めません。起立時の血圧変化や安全性を評価します。"},{"choice":4,"correct":true,"title":"室内の移動を車椅子に変更することを提案する。","explanation":"歩行器での転倒があり、座位で移動できる車椅子を検討します。移乗方法や住環境も評価し、自立できる範囲を保ちます。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答4を照合。歩行器での転倒があり、座位で移動できる車椅子を検討します。移乗方法や住環境も評価し、自立できる範囲を保ちます。","fixes_made":[]},"input_anchor":{"question":"A さんは仕事を辞め、妻が自営業を続け1年が経過した。A さんは歩行器で室\n内を移動し、日中は1人で過ごしていた。転倒したことをきっかけに、訪問看護を\n週1回利用することになった。初回の訪問時に、A さんは｢妻が仕事を続けてくれ\nて感謝しています。妻に迷惑はかけられない。妻が食卓に準備してくれた昼食を食\nべようと起き上がって歩行器に移ろうとしたら、立ちくらみを起こして転んでし\nまった｣と訪問看護師に話した。\n訪問看護師の A さんへの対応で適切なのはどれか。","choices":["ベッド上で食事を摂るよう説明する。","移乗の介助を妻に依頼するよう勧める。","立位でのリハビリテーションを指導する。","室内の移動を車椅子に変更することを提案する。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A さん(50 歳、男性、自営業)は妻(48 歳)、長男(23 歳、会社員)と3人で暮らして\nいる。3年前から歩行時のふらつきを自覚していたが、日常生活動作〈ADL〉は自立\nしていた。最近、転倒が多くなり医療機関を受診して頭部 CT 検査を受けたところ、\n小脳と脳幹に萎縮を認め、遺伝性の脊髄小脳変性症と診断された。A さんは｢母も同\nspinocerebellar degeneration\nじ疾患で亡くなりました。妹が同じ敷地内に1人で暮らしていますが、妹も転ぶこと\nが多くなり、医師の勧めで遺伝子診断を受ける予定です。明日、保健所に難病の医療\n費助成の申請に行くのですが、保健師に伝えた方がよいことはありますか｣と看護師\nに質問した。","preceding_context":[{"id":"112-PM-115","question":"A さんから保健師に伝える内容で優先度が高いのはどれか。"},{"id":"112-PM-116","question":"1か月後の定期受診のときに、A さんは｢長男に私の病名と遺伝性の疾患である\nことを伝えました。長男には何も症状はありませんが、発症前診断を受けて欲しい\nと思っています｣と外来の看護師に話した。\n看護師の A さんへの対応で適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":117,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[53],"case_pages":[52],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B117"},"exam":112,"year":2023,"session":"PM","number":117},"sources":[]},{"id":"112-PM-118","record":{"id":"112-PM-118","choice_explanations":[{"choice":1,"correct":false,"title":"過換気症候群\nhyperventilation syndrome","explanation":"過換気では速い呼吸やしびれなどを生じますが、胸壁の一部が吸気に陥没し呼気に膨らむ奇異性運動は説明できません。"},{"choice":2,"correct":false,"title":"虚血性心疾患\nischemic heart disease","explanation":"虚血性心疾患で胸痛は起こりますが、外傷後の胸壁の奇異性運動を特徴とはしません。"},{"choice":3,"correct":false,"title":"腰椎圧迫骨折\nlumbar compression fracture","explanation":"腰椎圧迫骨折では腰背部痛を生じます。呼吸に伴う胸壁の異常運動は胸部損傷を疑う所見です。"},{"choice":4,"correct":true,"title":"フレイルチェスト〈胸壁動揺〉\nflail chest","explanation":"複数肋骨の多重骨折などで胸壁の一部が不安定になり、吸気時陥没・呼気時膨隆の奇異性運動を示します。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答4を照合。複数肋骨の多重骨折などで胸壁の一部が不安定になり、吸気時陥没・呼気時膨隆の奇異性運動を示します。","fixes_made":[]},"input_anchor":{"question":"B さんに考えられる状態はどれか。","choices":["過換気症候群\nhyperventilation syndrome","虚血性心疾患\nischemic heart disease","腰椎圧迫骨折\nlumbar compression fracture","フレイルチェスト〈胸壁動揺〉\nflail chest"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"午前 10 時、A 県内で大規模災害が発生した。A 県内の救命救急センターに、家屋\n等の倒壊現場から救助された傷病者の受け入れ要請があり病院に搬送された。直ちに\nトリアージが行われた。搬送されてきた B さん(45 歳、男性)には頻呼吸が認められ、\n胸部と背部の痛みを訴え、吸気時に胸郭が陥没し、呼気時には膨隆している。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":118,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[54],"case_pages":[54],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B118"},"exam":112,"year":2023,"session":"PM","number":118},"sources":[]},{"id":"112-PM-119","record":{"id":"112-PM-119","choice_explanations":[{"choice":1,"correct":true,"title":"除細動器の準備","explanation":"K8.2mEq/Lと著明な高カリウム血症があり、不整脈もみられます。心室細動などに備えて除細動器を準備し、心電図監視と緊急治療を進めます。"},{"choice":2,"correct":false,"title":"既往歴の聴取","explanation":"既往歴は重要ですが、現在は高カリウム血症による致死的不整脈の危険が切迫しています。救命対応を優先します。"},{"choice":3,"correct":false,"title":"全身の保温","explanation":"体温35.8℃で保温も検討しますが、高K血症と不整脈への対応がより緊急です。"},{"choice":4,"correct":false,"title":"創傷の洗浄","explanation":"創傷の洗浄は必要でも、循環停止の危険への備えが先です。局所処置より全身状態を優先します。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答1を照合。K8.2mEq/Lと著明な高カリウム血症があり、不整脈もみられます。心室細動などに備えて除細動器を準備し、心電図監視と緊急治療を進めます。","fixes_made":[]},"input_anchor":{"question":"発災6時間、C さん(60 歳、男性)は、職場のがれきの下から救助され、搬送さ\nれてきた。C さんの意識は清明、バイタルサインは、体温 35.8 ℃、脈拍 110/分、\n不整、血圧 90/68 mmHg、経皮的動脈血酸素飽和度〈SpO2〉95 %(room air)である。\nがれきに挟まれていた両下肢は、皮膚の創傷、腫脹および皮下出血が認められた。\n両下肢の感覚は鈍く、麻痺がみられる。足背動脈は触知できる。尿の色は赤褐色で\nある。血液検査の結果、尿素窒素 20 mg/dL、クレアチニンキナーゼ〈CK〉3万\nIU/L、血糖値 110 mg/dL、Na 140 mEq/L、K 8.2 mEq/L であった。\n圧挫症候群〈クラッシュ症候群〉が疑われ、救出後から輸液療法が開始されている。\ncrush syndrome\nこのときの看護師の対応で優先度が高いのはどれか。","choices":["除細動器の準備","既往歴の聴取","全身の保温","創傷の洗浄"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":"午前 10 時、A 県内で大規模災害が発生した。A 県内の救命救急センターに、家屋\n等の倒壊現場から救助された傷病者の受け入れ要請があり病院に搬送された。直ちに\nトリアージが行われた。搬送されてきた B さん(45 歳、男性)には頻呼吸が認められ、\n胸部と背部の痛みを訴え、吸気時に胸郭が陥没し、呼気時には膨隆している。","preceding_context":[{"id":"112-PM-118","question":"B さんに考えられる状態はどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":119,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[54],"case_pages":[54],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B119"},"exam":112,"year":2023,"session":"PM","number":119},"sources":[]},{"id":"112-PM-120","record":{"id":"112-PM-120","choice_explanations":[{"choice":1,"correct":false,"title":"管理栄養士","explanation":"栄養管理は必要ですが、現時点の訴えは透析装置の停電時の安全性です。装置の専門職との連携が優先です。"},{"choice":2,"correct":false,"title":"社会福祉士","explanation":"社会福祉士は生活再建や制度利用を支援します。家族の所在は確認され、今は透析装置への不安への対応が中心です。"},{"choice":3,"correct":false,"title":"理学療法士","explanation":"理学療法士は今後の下肢機能回復などに関わります。透析中の装置管理に関する説明の担当ではありません。"},{"choice":4,"correct":true,"title":"臨床工学技士","explanation":"臨床工学技士は透析装置の操作・保守や停電時対応を担います。装置の安全管理を確認し、患者への説明につなげます。"}],"status":"PASS","review_reason":"問題・全選択肢・公式正答4を照合。臨床工学技士は透析装置の操作・保守や停電時対応を担います。装置の安全管理を確認し、患者への説明につなげます。","fixes_made":[]},"input_anchor":{"question":"C さんは直ちに入院となり、緊急で血液透析が開始されることになった。集中治\n療室のベッドサイドで血液透析が開始され、C さんのバイタルサインは安定した。\n下肢の腫脹、感覚障害は持続している。C さんは｢家族は無事なのか｣｢また地震が\nきて病院が停電になったら、透析の器械は止まらないのか｣と不安な表情で担当看\n護師に訴えた。C さんの家族は避難所にいると連絡があったことを伝えると、C さ\nんは少し落ち着いた表情となった。担当看護師は、次々と搬送される傷病者の受け\n入れ準備をするよう、リーダー看護師に声をかけられた。\nこの時点での C さんへの対応で担当看護師が優先して連携するのはどれか。","choices":["管理栄養士","社会福祉士","理学療法士","臨床工学技士"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"午前 10 時、A 県内で大規模災害が発生した。A 県内の救命救急センターに、家屋\n等の倒壊現場から救助された傷病者の受け入れ要請があり病院に搬送された。直ちに\nトリアージが行われた。搬送されてきた B さん(45 歳、男性)には頻呼吸が認められ、\n胸部と背部の痛みを訴え、吸気時に胸郭が陥没し、呼気時には膨隆している。","preceding_context":[{"id":"112-PM-118","question":"B さんに考えられる状態はどれか。"},{"id":"112-PM-119","question":"発災6時間、C さん(60 歳、男性)は、職場のがれきの下から救助され、搬送さ\nれてきた。C さんの意識は清明、バイタルサインは、体温 35.8 ℃、脈拍 110/分、\n不整、血圧 90/68 mmHg、経皮的動脈血酸素飽和度〈SpO2〉95 %(room air)である。\nがれきに挟まれていた両下肢は、皮膚の創傷、腫脹および皮下出血が認められた。\n両下肢の感覚は鈍く、麻痺がみられる。足背動脈は触知できる。尿の色は赤褐色で\nある。血液検査の結果、尿素窒素 20 mg/dL、クレアチニンキナーゼ〈CK〉3万\nIU/L、血糖値 110 mg/dL、Na 140 mEq/L、K 8.2 mEq/L であった。\n圧挫症候群〈クラッシュ症候群〉が疑われ、救出後から輸液療法が開始されている。\ncrush syndrome\nこのときの看護師の対応で優先度が高いのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第112回看護師国家試験","session":"午後","question_number":120,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05c_01.pdf","pages":[55],"case_pages":[54],"sha256":"137d583931c6ae6a7fa2f3f8655352bdce24735c6f0b2bbbb0b192e6a357d01e"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp230524-05seitou.pdf","page":2,"row_id":"B120"},"exam":112,"year":2023,"session":"PM","number":120},"sources":[]},{"id":"113-PM-091","record":{"id":"113-PM-091","choice_explanations":[{"choice":1,"correct":false,"title":"頸部リンパ節の腫脹","explanation":"N0は所属リンパ節転移を認めない分類です。頸部リンパ節腫脹を示す情報もなく、提示された異常所見ではありません。"},{"choice":2,"correct":true,"title":"拘束性換気障害","explanation":"％肺活量76％は80％未満で、拘束性換気障害に該当します。1秒率73％とは異なる指標です。"},{"choice":3,"correct":false,"title":"低栄養","explanation":"BMIは約23.8で、総蛋白7.7、アルブミン4.2g/dLです。提示情報から低栄養とは判断しません。"},{"choice":4,"correct":false,"title":"貧 血","explanation":"Hb15.6g/dLであり、成人男性の貧血を示す値ではありません。赤血球数も低下していません。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"入院時の所見で正しいのはどれか。","choices":["頸部リンパ節の腫脹","拘束性換気障害","低栄養","貧 血"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(58 歳、男性、会社員)は、身長 175 cm、体重 73 kg である。A さんは、健\n康診断の胸部エックス線撮影で異常陰影を指摘され、3週前に胸部造影 CT 検査を受\nけた。左肺下葉に約8mm の病変が見つかり、精密検査の結果、肺癌(T1N0M0)と診\nlung cancer\n断され、本日、手術目的で入院した。咳嗽、息苦しさ、喀痰はない。喫煙歴があり、\n20 年間 20 本/日、禁煙後 18 年である。\nバ イ タ ル サ イ ン：体 温 36.9 ℃、呼 吸 数 14/分、脈 拍 72/分、整、血 圧 136/76\nmmHg、経皮的動脈血酸素飽和度〈SpO2〉96 %(room air)。\n検査所見：赤血球 510 万/μL、Hb 15.6 g/dL、Ht 47 %、白血球 6,200/μL、血小板 32\n万/μL、総蛋白 7.7 g/dL、アルブミン 4.2 g/dL、空腹時血糖 102 mg/dL。\n呼吸機能所見：%VC76 %、FEV1% 73 %。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":91,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[36],"case_pages":[36],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM91"},"exam":113,"year":2024,"session":"PM","number":91},"sources":[{"title":"日本呼吸器学会：肺機能検査","url":"https://www.jrs.or.jp/citizen/faq/q27.html"}]},{"id":"113-PM-092","record":{"id":"113-PM-092","choice_explanations":[{"choice":1,"correct":true,"title":"気 胸\npneumothorax","explanation":"肺の切除部などから空気が漏れると胸腔に空気がたまり、肺の拡張が妨げられます。術後は気漏や呼吸状態を観察します。"},{"choice":2,"correct":false,"title":"反回神経麻痺","explanation":"リンパ節郭清などに伴って起こる可能性はありますが、肺切除後の代表的な気漏・気胸の方が本問では優先されます。"},{"choice":3,"correct":false,"title":"Horner〈ホルネル〉症候群\nHornerʼs syndrome","explanation":"交感神経の障害で縮瞳、眼瞼下垂などが起こります。左下葉の切除に最も関連する合併症ではありません。"},{"choice":4,"correct":false,"title":"Pancoast〈パンコースト〉症候群\nPancoastʼs syndrome","explanation":"肺尖部の腫瘍浸潤による肩・上肢痛などの症候群です。本例は下葉の小病変で、術後の気漏とは異なります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんは、入院2日目に胸腔鏡下左下葉切除術を受ける予定である。A さんは\n看護師に｢全身麻酔で手術を受けるのは初めてです。医師から手術の説明はあった\nけれど、合併症についてもう一度教えてもらえますか｣と質問した。\nA さんに生じる可能性が高い合併症はどれか。","choices":["気 胸\npneumothorax","反回神経麻痺","Horner〈ホルネル〉症候群\nHornerʼs syndrome","Pancoast〈パンコースト〉症候群\nPancoastʼs syndrome"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":"A さん(58 歳、男性、会社員)は、身長 175 cm、体重 73 kg である。A さんは、健\n康診断の胸部エックス線撮影で異常陰影を指摘され、3週前に胸部造影 CT 検査を受\nけた。左肺下葉に約8mm の病変が見つかり、精密検査の結果、肺癌(T1N0M0)と診\nlung cancer\n断され、本日、手術目的で入院した。咳嗽、息苦しさ、喀痰はない。喫煙歴があり、\n20 年間 20 本/日、禁煙後 18 年である。\nバ イ タ ル サ イ ン：体 温 36.9 ℃、呼 吸 数 14/分、脈 拍 72/分、整、血 圧 136/76\nmmHg、経皮的動脈血酸素飽和度〈SpO2〉96 %(room air)。\n検査所見：赤血球 510 万/μL、Hb 15.6 g/dL、Ht 47 %、白血球 6,200/μL、血小板 32\n万/μL、総蛋白 7.7 g/dL、アルブミン 4.2 g/dL、空腹時血糖 102 mg/dL。\n呼吸機能所見：%VC76 %、FEV1% 73 %。","preceding_context":[{"id":"113-PM-091","question":"入院時の所見で正しいのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":92,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[36],"case_pages":[36],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM92"},"exam":113,"year":2024,"session":"PM","number":92},"sources":[]},{"id":"113-PM-093","record":{"id":"113-PM-093","choice_explanations":[{"choice":1,"correct":false,"title":"｢インフルエンザワクチンは接種できません｣","explanation":"肺切除そのものを理由にインフルエンザワクチンを一律に禁止しません。体調や治療状況に応じて接種を相談します。"},{"choice":2,"correct":false,"title":"｢左手で重い荷物を持たないでください｣","explanation":"術後早期の創痛や活動制限は個別に確認します。肺切除だけを理由に左手での荷物運搬を継続的に禁止する指導ではありません。"},{"choice":3,"correct":true,"title":"｢少しずつ活動量を増やしてください｣","explanation":"疲労や息切れをみながら、休息を挟んで段階的に活動を増やします。無理のない運動で回復を支えます。"},{"choice":4,"correct":false,"title":"｢自宅で酸素吸入を行ってください｣","explanation":"室内気でSpO2は97％で、在宅酸素療法を必要とする情報はありません。肺切除後全員に酸素吸入が必要なわけではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんの手術は予定通りの術式で行われ、肺癌は術前診断通りの病期であった。\nlung cancer\nA さんの術後経過は良好であり、退院日が決定した。A さんのバイタルサインは、\n体温 36.3 ℃、呼吸数 18/分、脈拍 66/分、整、血圧 134/76 mmHg、経皮的動脈血\n酸素飽和度〈SpO2〉97 %(room air)であった。\n退院後の生活指導で正しいのはどれか。","choices":["｢インフルエンザワクチンは接種できません｣","｢左手で重い荷物を持たないでください｣","｢少しずつ活動量を増やしてください｣","｢自宅で酸素吸入を行ってください｣"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A さん(58 歳、男性、会社員)は、身長 175 cm、体重 73 kg である。A さんは、健\n康診断の胸部エックス線撮影で異常陰影を指摘され、3週前に胸部造影 CT 検査を受\nけた。左肺下葉に約8mm の病変が見つかり、精密検査の結果、肺癌(T1N0M0)と診\nlung cancer\n断され、本日、手術目的で入院した。咳嗽、息苦しさ、喀痰はない。喫煙歴があり、\n20 年間 20 本/日、禁煙後 18 年である。\nバ イ タ ル サ イ ン：体 温 36.9 ℃、呼 吸 数 14/分、脈 拍 72/分、整、血 圧 136/76\nmmHg、経皮的動脈血酸素飽和度〈SpO2〉96 %(room air)。\n検査所見：赤血球 510 万/μL、Hb 15.6 g/dL、Ht 47 %、白血球 6,200/μL、血小板 32\n万/μL、総蛋白 7.7 g/dL、アルブミン 4.2 g/dL、空腹時血糖 102 mg/dL。\n呼吸機能所見：%VC76 %、FEV1% 73 %。","preceding_context":[{"id":"113-PM-091","question":"入院時の所見で正しいのはどれか。"},{"id":"113-PM-092","question":"A さんは、入院2日目に胸腔鏡下左下葉切除術を受ける予定である。A さんは\n看護師に｢全身麻酔で手術を受けるのは初めてです。医師から手術の説明はあった\nけれど、合併症についてもう一度教えてもらえますか｣と質問した。\nA さんに生じる可能性が高い合併症はどれか。"}],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":93,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[37],"case_pages":[36],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM93"},"exam":113,"year":2024,"session":"PM","number":93},"sources":[]},{"id":"113-PM-094","record":{"id":"113-PM-094","choice_explanations":[{"choice":1,"correct":false,"title":"発 熱","explanation":"37.1℃の体温だけでは顔面浮腫を説明できません。画像で示された静脈の圧迫が直接の手掛かりです。"},{"choice":2,"correct":false,"title":"貧 血","explanation":"Hb12.8g/dLという所見より、上半身の静脈還流障害が顔面浮腫を説明します。"},{"choice":3,"correct":false,"title":"低蛋白血症\nhypoproteinemia","explanation":"総蛋白とアルブミンは低下していません。低蛋白による膠質浸透圧低下を主因とする根拠がありません。"},{"choice":4,"correct":true,"title":"上大静脈の圧迫","explanation":"縦隔リンパ節が上大静脈を圧迫し、頭頸部からの血液が心臓へ戻りにくくなっています。そのうっ滞で顔面がむくみます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんの顔面の浮腫の原因で考えられるのはどれか。","choices":["発 熱","貧 血","低蛋白血症\nhypoproteinemia","上大静脈の圧迫"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A さん(43 歳、男性、会社員)は、1か月前に右頸部の腫瘤を自覚した。大学病院\nで非 Hodgkin〈ホジキン〉リンパ腫と診断され化学療法導入目的で入院した。\nnon-Hodgkin lymphoma\nバイタルサイン：体温 37.1 ℃、呼吸数 16/分、脈拍 84/分、整。\n身体所見：顔面に浮腫を認める。\n検 査 所 見：Hb 12.8 g/dL、白 血 球 6,400/μL、総 蛋 白 7.6 g/dL、ア ル ブ ミ ン 4.1\ng/dL。\n胸部造影 CT：縦隔リンパ節腫大による上大静脈の圧迫を認める。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":94,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[38],"case_pages":[38],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM94"},"exam":113,"year":2024,"session":"PM","number":94},"sources":[]},{"id":"113-PM-095","record":{"id":"113-PM-095","choice_explanations":[{"choice":1,"correct":false,"title":"脱 毛","explanation":"脱毛は毛根への影響が現れるまで時間を要し、通常は初日の合併症として選びません。"},{"choice":2,"correct":false,"title":"口内炎","explanation":"粘膜障害による口内炎は一般に投与後数日以降に問題となります。初日の急激な変化とは区別します。"},{"choice":3,"correct":false,"title":"低血糖","explanation":"プレドニゾロンではむしろ高血糖に注意します。初日の代表的な合併症として低血糖を選びません。"},{"choice":4,"correct":false,"title":"好中球減少症\nneutropenia","explanation":"骨髄抑制による好中球減少は投与後しばらくして現れます。初日に急速に起こる腫瘍崩壊とは時期が異なります。"},{"choice":5,"correct":true,"title":"腫瘍崩壊症候群\ntumor lysis syndrome","explanation":"治療で腫瘍細胞が急速に壊れると、カリウム、リン、尿酸などが増え、腎障害や不整脈につながります。開始早期から注意します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんは R-CHOP 療法(リツキシマブ、シクロホスファミド、ドキソルビシン、\nビンクリスチン、プレドニゾロン)を受けた。\nA さんの R-CHOP 療法の初日に生じる可能性がある合併症はどれか。","choices":["脱 毛","口内炎","低血糖","好中球減少症\nneutropenia","腫瘍崩壊症候群\ntumor lysis syndrome"],"correct_answers":[5],"accepted_answer_sets":[[5]],"case_text":"A さん(43 歳、男性、会社員)は、1か月前に右頸部の腫瘤を自覚した。大学病院\nで非 Hodgkin〈ホジキン〉リンパ腫と診断され化学療法導入目的で入院した。\nnon-Hodgkin lymphoma\nバイタルサイン：体温 37.1 ℃、呼吸数 16/分、脈拍 84/分、整。\n身体所見：顔面に浮腫を認める。\n検 査 所 見：Hb 12.8 g/dL、白 血 球 6,400/μL、総 蛋 白 7.6 g/dL、ア ル ブ ミ ン 4.1\ng/dL。\n胸部造影 CT：縦隔リンパ節腫大による上大静脈の圧迫を認める。","preceding_context":[{"id":"113-PM-094","question":"A さんの顔面の浮腫の原因で考えられるのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":95,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[38],"case_pages":[38],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM95"},"exam":113,"year":2024,"session":"PM","number":95},"sources":[{"title":"PMDA：リツキサン資料（初回投与後の腫瘍崩壊症候群）","url":"https://www.pmda.go.jp/drugs/2016/P20160308001/380101000_21300AMY00273_B100_1.pdf"}]},{"id":"113-PM-096","record":{"id":"113-PM-096","choice_explanations":[{"choice":1,"correct":false,"title":"1日 1,000 mL の水分摂取","explanation":"水分量は脱水や腎機能などで調整します。1日1000mLという固定量だけでは化学療法による悪心・嘔吐を予防できません。"},{"choice":2,"correct":false,"title":"治療前日の夕食の中止","explanation":"食事を一律に中止しても、薬剤による嘔吐刺激や予期性悪心への対策にはなりません。食べられる方法を検討します。"},{"choice":3,"correct":true,"title":"治療前の制吐薬の投与","explanation":"前回の症状を踏まえ、治療前から予防的な制吐療法を調整します。つらい経験の繰返しと予期性悪心の悪化を防ぎます。"},{"choice":4,"correct":false,"title":"抗癌薬の減量","explanation":"治療効果を維持するため、まず制吐療法などの支持療法を調整します。減量の要否は症状の重さや治療全体を踏まえて医師が判断します。"}],"status":"VERIFIED","review_reason":"","fixes_made":["減量の判断権限だけでなく、支持療法による治療効果維持を説明"]},"input_anchor":{"question":"A さんは R-CHOP 療法終了後も嘔気・嘔吐が続き、制吐薬の追加投与を受け\nた。治療後3日、｢やっと楽になって食事が摂れるようになったけど、やっぱりつ\nらかった。思い出すだけでも気持ち悪くなります｣と話している。\nA さんの次回の R-CHOP 療法において、嘔気・嘔吐への対応で適切なのはどれ\nか。","choices":["1日 1,000 mL の水分摂取","治療前日の夕食の中止","治療前の制吐薬の投与","抗癌薬の減量"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A さん(43 歳、男性、会社員)は、1か月前に右頸部の腫瘤を自覚した。大学病院\nで非 Hodgkin〈ホジキン〉リンパ腫と診断され化学療法導入目的で入院した。\nnon-Hodgkin lymphoma\nバイタルサイン：体温 37.1 ℃、呼吸数 16/分、脈拍 84/分、整。\n身体所見：顔面に浮腫を認める。\n検 査 所 見：Hb 12.8 g/dL、白 血 球 6,400/μL、総 蛋 白 7.6 g/dL、ア ル ブ ミ ン 4.1\ng/dL。\n胸部造影 CT：縦隔リンパ節腫大による上大静脈の圧迫を認める。","preceding_context":[{"id":"113-PM-094","question":"A さんの顔面の浮腫の原因で考えられるのはどれか。"},{"id":"113-PM-095","question":"A さんは R-CHOP 療法(リツキシマブ、シクロホスファミド、ドキソルビシン、\nビンクリスチン、プレドニゾロン)を受けた。\nA さんの R-CHOP 療法の初日に生じる可能性がある合併症はどれか。"}],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":96,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[39],"case_pages":[38],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM96"},"exam":113,"year":2024,"session":"PM","number":96},"sources":[{"title":"国立がん研究センター：吐き気・嘔吐について","url":"https://www.ncc.go.jp/jp/ncce/division/pharmacy/kouganzai/supportivecare_antiemetic.html"}]},{"id":"113-PM-097","record":{"id":"113-PM-097","choice_explanations":[{"choice":1,"correct":false,"title":"溢流性尿失禁\noverflow incontinence of urine","explanation":"尿が膀胱にたまり過ぎてあふれる失禁です。本例では尿閉や多量の残尿を示す情報はありません。"},{"choice":2,"correct":false,"title":"機能性尿失禁\nfunctional incontinence of urine","explanation":"排尿機能以外の移動や認知の障害により間に合わない失禁です。本例は移動・更衣・認知が保たれています。"},{"choice":3,"correct":true,"title":"切迫性尿失禁\nurge incontinence of urine","explanation":"突然の強い尿意を我慢できず漏れる特徴から、切迫性尿失禁を考えます。排尿日誌などで頻度と状況を把握します。"},{"choice":4,"correct":false,"title":"腹圧性尿失禁\nstress incontinence of urine","explanation":"咳やくしゃみなどで腹圧が上がった際の失禁です。本例の強い尿意に続く失禁とは異なります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんの尿失禁の種類で考えられるのはどれか。","choices":["溢流性尿失禁\noverflow incontinence of urine","機能性尿失禁\nfunctional incontinence of urine","切迫性尿失禁\nurge incontinence of urine","腹圧性尿失禁\nstress incontinence of urine"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A さん(71 歳、女性)は夫と 10 年前に死別し、1人で暮らしている。息子は結婚し\nて他県に住んでいる。A さんは、3か月前に脳梗塞を発症して要介護1となり、介\ncerebral infarction\n護老人保健施設に入所した。\nA さんは老人性白内障があるが ADL に支障はなく、認知機能やコミュニケーショ\nsenile cataract\nンに問題はない。食事は自力で摂取できる。紅茶が好きで、毎日カップ2、3杯は飲\nんでいる。我慢できない強い尿意があり尿が漏れてしまうため、下着に尿取りパッド\nを付けている。トイレには自力で移動でき、下着やズボンの上げ下ろしは自立してい\nる。排便は2日に1回である。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":97,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[40],"case_pages":[40],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM97"},"exam":113,"year":2024,"session":"PM","number":97},"sources":[]},{"id":"113-PM-099","record":{"id":"113-PM-099","choice_explanations":[{"choice":1,"correct":false,"title":"2時間ごとに排尿誘導する。","explanation":"定時誘導は失禁対策の一つですが、排泄が自立している本人には必要性を評価します。本問は汚染したパッドによる不潔の予防が中心です。"},{"choice":2,"correct":false,"title":"用手圧迫排尿の方法を指導する。","explanation":"膀胱を圧迫して排出する方法は尿閉などで検討するものです。自己判断で行うと逆流などの危険があります。"},{"choice":3,"correct":false,"title":"排尿の度に陰部を洗浄するように促す。","explanation":"排尿のたびの洗浄は負担や皮膚刺激になり得ます。適度な清潔保持と濡れたパッドの交換を行います。"},{"choice":4,"correct":true,"title":"尿取りパッドの交換回数を増やすように指導する。","explanation":"尿で湿ったパッドを長時間当て続けないようにし、陰部の清潔と皮膚を保ちます。水分摂取や排尿時の症状も確認します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"5日後、A さんは解熱し、少しずつ食欲が出てきた。下腹部痛は消失し、尿失\n禁の回数も少なくなった。\n症状の再燃を防止するための A さんへの対応で適切なのはどれか。","choices":["2時間ごとに排尿誘導する。","用手圧迫排尿の方法を指導する。","排尿の度に陰部を洗浄するように促す。","尿取りパッドの交換回数を増やすように指導する。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A さん(71 歳、女性)は夫と 10 年前に死別し、1人で暮らしている。息子は結婚し\nて他県に住んでいる。A さんは、3か月前に脳梗塞を発症して要介護1となり、介\ncerebral infarction\n護老人保健施設に入所した。\nA さんは老人性白内障があるが ADL に支障はなく、認知機能やコミュニケーショ\nsenile cataract\nンに問題はない。食事は自力で摂取できる。紅茶が好きで、毎日カップ2、3杯は飲\nんでいる。我慢できない強い尿意があり尿が漏れてしまうため、下着に尿取りパッド\nを付けている。トイレには自力で移動でき、下着やズボンの上げ下ろしは自立してい\nる。排便は2日に1回である。","preceding_context":[{"id":"113-PM-097","question":"A さんの尿失禁の種類で考えられるのはどれか。"},{"id":"113-PM-098","question":"4、5日前から A さんは倦怠感を訴え、ベッドで寝ていることが多くなった。\n食欲が落ちてきて、1日の水分摂取量も減少した。トイレでの排尿が間に合わない\nことが多くなり、頻回に尿失禁するようになった。看護師が A さんの尿取りパッ\nドの交換を介助すると尿臭が強く、色も茶褐色であった。A さんが｢おしっこをす\nるとお腹の下の方が痛い。体がだるい｣と看護師に訴えたため、体温を測定すると"}],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":99,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[41],"case_pages":[40],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM99"},"exam":113,"year":2024,"session":"PM","number":99},"sources":[{"title":"NHS・UKHSA：尿路感染予防（パッド交換と清潔保持）","url":"https://www.england.nhs.uk/2023/10/new-awareness-campaign-to-help-reduce-hospital-admissions-for-urinary-tract-infections/"}]},{"id":"113-PM-100","record":{"id":"113-PM-100","choice_explanations":[{"choice":1,"correct":false,"title":"水分摂取を促す。","explanation":"浮腫と高血圧があり、水分の貯留に注意します。尿量や医師の指示を確認せず水分摂取を増やしません。"},{"choice":2,"correct":true,"title":"1日3回の血圧測定を行う。","explanation":"7歳児として高い血圧があり、経時的な測定が必要です。高血圧による頭痛や神経症状も観察します。"},{"choice":3,"correct":false,"title":"食事の持ち込みを許可する。","explanation":"塩分・水分などの調整が必要な場合があり、持込みを無条件に認めません。治療食と家族の理解を確認します。"},{"choice":4,"correct":false,"title":"腰部に消炎鎮痛薬を貼用する。","explanation":"腰痛や貼付薬の適応は示されていません。腎機能と血圧・水分出納の管理が優先です。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A ちゃんの入院時の看護計画で適切なのはどれか。","choices":["水分摂取を促す。","1日3回の血圧測定を行う。","食事の持ち込みを許可する。","腰部に消炎鎮痛薬を貼用する。"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A ちゃん(7歳、女児)は、頭痛、食欲不振、全身倦怠感、肉眼的血尿および両眼\n瞼の浮腫を主訴に来院した。1か月前に扁桃炎に罹患した以外は既往歴に特記すべき\ntonsillitis\nことはない。扁桃炎は抗菌薬を内服し軽快した。検査の結果、溶連菌感染後\ntonsillitis poststreptcoccal\n急性糸球体腎炎と診断されて入院した。入院時、A ちゃんは体温 36.6 ℃、呼吸数\nacute glomerulonephritis\n20/分、心拍数 84/分、血圧 130/80 mmHg で、床上安静の指示が出された。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":100,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[42],"case_pages":[42],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM100"},"exam":113,"year":2024,"session":"PM","number":100},"sources":[]},{"id":"113-PM-101","record":{"id":"113-PM-101","choice_explanations":[{"choice":1,"correct":false,"title":"眼のかゆみ","explanation":"眼瞼浮腫はありますが、かゆみは高血圧に伴う主要な合併症を示しません。"},{"choice":2,"correct":true,"title":"意識障害","explanation":"血圧上昇に頭痛・悪心を伴い、高血圧性脳症による意識障害やけいれんのおそれがあります。速やかな報告と観察が必要です。"},{"choice":3,"correct":false,"title":"耳 漏","explanation":"耳漏は耳の炎症などでみられます。急性腎炎と血圧上昇から予測する症状ではありません。"},{"choice":4,"correct":false,"title":"鼻 閉","explanation":"鼻閉は鼻粘膜の腫脹などで起こります。高血圧性の中枢神経障害を捉える所見ではありません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"入院3日。両眼瞼の浮腫と肉眼的血尿は続いていた。看護師が A ちゃんのベッ\nドサイドを訪れると、A ちゃんは｢頭が痛い。気持ち悪い｣と訴えた。A ちゃんは\n体温 36.6 ℃、呼吸数 20/分、心拍数 92/分、血圧 148/88 mmHg であった。\nこの状況から A ちゃんに起こりうる症状はどれか。","choices":["眼のかゆみ","意識障害","耳 漏","鼻 閉"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A ちゃん(7歳、女児)は、頭痛、食欲不振、全身倦怠感、肉眼的血尿および両眼\n瞼の浮腫を主訴に来院した。1か月前に扁桃炎に罹患した以外は既往歴に特記すべき\ntonsillitis\nことはない。扁桃炎は抗菌薬を内服し軽快した。検査の結果、溶連菌感染後\ntonsillitis poststreptcoccal\n急性糸球体腎炎と診断されて入院した。入院時、A ちゃんは体温 36.6 ℃、呼吸数\nacute glomerulonephritis\n20/分、心拍数 84/分、血圧 130/80 mmHg で、床上安静の指示が出された。","preceding_context":[{"id":"113-PM-100","question":"A ちゃんの入院時の看護計画で適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":101,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[42],"case_pages":[42],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM101"},"exam":113,"year":2024,"session":"PM","number":101},"sources":[]},{"id":"113-PM-102","record":{"id":"113-PM-102","choice_explanations":[{"choice":1,"correct":false,"title":"｢すぐに退院できるから頑張ろう｣","explanation":"退院時期が確定していないのに約束すると信頼を損ないます。いま感じている退屈や寂しさを受け止めます。"},{"choice":2,"correct":false,"title":"｢好きなだけテレビや動画を観ていいよ｣","explanation":"無制限の視聴は生活リズムを崩す可能性があります。安静度に合う遊びや人との交流を組み合わせます。"},{"choice":3,"correct":true,"title":"｢ベッドに寝たままプレイルームに行こう｣","explanation":"床上安静を保ったまま環境を変えることで、交流や気分転換を図れます。移動の可否は安静指示と状態を確認します。"},{"choice":4,"correct":false,"title":"｢夕食後もお母さんに付き添ってもらおう｣","explanation":"母親の事情や本人の希望を確認せず、付き添い延長を前提にしません。病棟でできる支援も考えます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"入院して1週が経過した。症状は軽快傾向にあるが床上安静は続いている。仲が\n良かった同じ病室の児が退院して、A ちゃんはイライラしている。A ちゃんの母\n親は、毎日昼食後から夕食まで面会をしている。\nA ちゃんのストレスに対する看護師の発言で適切なのはどれか。","choices":["｢すぐに退院できるから頑張ろう｣","｢好きなだけテレビや動画を観ていいよ｣","｢ベッドに寝たままプレイルームに行こう｣","｢夕食後もお母さんに付き添ってもらおう｣"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A ちゃん(7歳、女児)は、頭痛、食欲不振、全身倦怠感、肉眼的血尿および両眼\n瞼の浮腫を主訴に来院した。1か月前に扁桃炎に罹患した以外は既往歴に特記すべき\ntonsillitis\nことはない。扁桃炎は抗菌薬を内服し軽快した。検査の結果、溶連菌感染後\ntonsillitis poststreptcoccal\n急性糸球体腎炎と診断されて入院した。入院時、A ちゃんは体温 36.6 ℃、呼吸数\nacute glomerulonephritis\n20/分、心拍数 84/分、血圧 130/80 mmHg で、床上安静の指示が出された。","preceding_context":[{"id":"113-PM-100","question":"A ちゃんの入院時の看護計画で適切なのはどれか。"},{"id":"113-PM-101","question":"入院3日。両眼瞼の浮腫と肉眼的血尿は続いていた。看護師が A ちゃんのベッ\nドサイドを訪れると、A ちゃんは｢頭が痛い。気持ち悪い｣と訴えた。A ちゃんは\n体温 36.6 ℃、呼吸数 20/分、心拍数 92/分、血圧 148/88 mmHg であった。\nこの状況から A ちゃんに起こりうる症状はどれか。"}],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":102,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[43],"case_pages":[42],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM102"},"exam":113,"year":2024,"session":"PM","number":102},"sources":[]},{"id":"113-PM-103","record":{"id":"113-PM-103","choice_explanations":[{"choice":1,"correct":false,"title":"｢検査があることは当日に説明しましょう｣","explanation":"予定が分からないことが不安を強める場合があります。本人に合う方法で前もって見通しを伝えます。"},{"choice":2,"correct":false,"title":"｢予防接種ができるのであれば心配ありません｣","explanation":"予防接種ができても別の検査で不安になることはあります。母親の心配を否定しません。"},{"choice":3,"correct":true,"title":"｢家で A 君に説明できる絵カードをお渡しします｣","explanation":"視覚的に順序を示す絵カードは、検査の見通しを持つ助けになります。家庭で繰り返し確認できるよう支援します。"},{"choice":4,"correct":false,"title":"｢看護師3人で A 君をしっかりと抑えて採血します｣","explanation":"説明によって抑えずに受けられた経験を生かします。最初から身体を押さえる方針にしません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"母親への声かけで適切なのはどれか。","choices":["｢検査があることは当日に説明しましょう｣","｢予防接種ができるのであれば心配ありません｣","｢家で A 君に説明できる絵カードをお渡しします｣","｢看護師3人で A 君をしっかりと抑えて採血します｣"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A 君 (5 歳、男 児) は 共 働 き の 両 親 と 3 人 で 暮 ら し て い る。2 歳 6 か 月 で\n自閉スペクトラム症と診断され、保育所と療育センターに通っている。保育所の健康\nautism spectrum disorder\n診断で低身長を指摘され、受診を勧められて両親と来院した。A 君は待合室を走っ\nたり診察室の扉を開けたりしていた。診察室に入ると｢頑張ろう｣と泣きながら叫び、\n恐怖心を抑えている様子だった。母親は｢A は病院が苦手で、予防接種は A の手足と\n体を看護師さん3人で抑えて行ってきましたが、繰り返し説明することで、抑えなく\nても注射ができるようになりました｣と話した。\n診察の結果、1週後に成長ホルモン分泌刺激試験を行うことになった。母親から\n｢A が血液検査でパニックを起こすのではないかと心配です｣と発言があった。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":103,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[44],"case_pages":[44],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM103"},"exam":113,"year":2024,"session":"PM","number":103},"sources":[]},{"id":"113-PM-104","record":{"id":"113-PM-104","choice_explanations":[{"choice":1,"correct":false,"title":"保育所での A 君の様子","explanation":"保育所での様子も生活把握に役立ちますが、毎晩の家庭での注射を続けるには日課の確認が先です。"},{"choice":2,"correct":true,"title":"A 君と家族の日課","explanation":"家族の帰宅時刻、食事、就寝などを把握し、無理なく注射できる時間と役割を組み立てます。"},{"choice":3,"correct":false,"title":"家族の経済状況","explanation":"医療費の支援が必要な場合は確認しますが、現段階では習得した手技を日常生活に組み込むことが優先です。"},{"choice":4,"correct":false,"title":"祖父母の居住地","explanation":"祖父母の支援を求める場合の情報です。まず本人と同居家族の日課を確認します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"成長ホルモン分泌刺激試験の結果、母親が自宅で毎晩 A 君に成長ホルモン製剤\nを注射することになった。外来で母親は注射の手技を習得し、A 君も注射に慣れ\nた。\n自宅での注射に向けて、母親に確認する事項で優先度が高いのはどれか。","choices":["保育所での A 君の様子","A 君と家族の日課","家族の経済状況","祖父母の居住地"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A 君 (5 歳、男 児) は 共 働 き の 両 親 と 3 人 で 暮 ら し て い る。2 歳 6 か 月 で\n自閉スペクトラム症と診断され、保育所と療育センターに通っている。保育所の健康\nautism spectrum disorder\n診断で低身長を指摘され、受診を勧められて両親と来院した。A 君は待合室を走っ\nたり診察室の扉を開けたりしていた。診察室に入ると｢頑張ろう｣と泣きながら叫び、\n恐怖心を抑えている様子だった。母親は｢A は病院が苦手で、予防接種は A の手足と\n体を看護師さん3人で抑えて行ってきましたが、繰り返し説明することで、抑えなく\nても注射ができるようになりました｣と話した。\n診察の結果、1週後に成長ホルモン分泌刺激試験を行うことになった。母親から\n｢A が血液検査でパニックを起こすのではないかと心配です｣と発言があった。","preceding_context":[{"id":"113-PM-103","question":"母親への声かけで適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":104,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[44],"case_pages":[44],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM104"},"exam":113,"year":2024,"session":"PM","number":104},"sources":[]},{"id":"113-PM-105","record":{"id":"113-PM-105","choice_explanations":[{"choice":1,"correct":false,"title":"｢お母さんが学校で待機する必要があります｣","explanation":"毎晩の自宅注射であり、学校内に母親が待機する必要があるとは限りません。必要な支援を個別に相談します。"},{"choice":2,"correct":false,"title":"｢就学する学級は受入れ先の校長が決定します｣","explanation":"校長一人で一方的に決定するものではありません。本人・保護者の意向と教育的ニーズを踏まえ、教育委員会等と相談します。"},{"choice":3,"correct":false,"title":"｢通常の学級に籍を置くと通級指導は受けられません｣","explanation":"通級による指導は、通常の学級に在籍しながら受ける支援です。在籍すると利用できないという説明は逆です。"},{"choice":4,"correct":true,"title":"｢A 君の特性に合わせた配慮を学校に求めることができます｣","explanation":"本人の特性と困難に合わせ、説明方法や環境などの合理的配慮を相談できます。家庭・療育機関・学校で情報を共有します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"3か月後、自宅での A 君への成長ホルモン製剤の注射は順調に実施されている。\n外来受診時に母親から看護師に｢A が通っている療育センターにも相談しました\nが、A は自閉スペクトラム症であるだけでなく、注射もしているので就学のこと\nautism spectrum disorder\nを考えると心配です。通常の学級に通わせたいと考えているのですが、通常の学級\nへの就学について教えてください｣と相談があった。\n看護師の説明で適切なのはどれか。","choices":["｢お母さんが学校で待機する必要があります｣","｢就学する学級は受入れ先の校長が決定します｣","｢通常の学級に籍を置くと通級指導は受けられません｣","｢A 君の特性に合わせた配慮を学校に求めることができます｣"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A 君 (5 歳、男 児) は 共 働 き の 両 親 と 3 人 で 暮 ら し て い る。2 歳 6 か 月 で\n自閉スペクトラム症と診断され、保育所と療育センターに通っている。保育所の健康\nautism spectrum disorder\n診断で低身長を指摘され、受診を勧められて両親と来院した。A 君は待合室を走っ\nたり診察室の扉を開けたりしていた。診察室に入ると｢頑張ろう｣と泣きながら叫び、\n恐怖心を抑えている様子だった。母親は｢A は病院が苦手で、予防接種は A の手足と\n体を看護師さん3人で抑えて行ってきましたが、繰り返し説明することで、抑えなく\nても注射ができるようになりました｣と話した。\n診察の結果、1週後に成長ホルモン分泌刺激試験を行うことになった。母親から\n｢A が血液検査でパニックを起こすのではないかと心配です｣と発言があった。","preceding_context":[{"id":"113-PM-103","question":"母親への声かけで適切なのはどれか。"},{"id":"113-PM-104","question":"成長ホルモン分泌刺激試験の結果、母親が自宅で毎晩 A 君に成長ホルモン製剤\nを注射することになった。外来で母親は注射の手技を習得し、A 君も注射に慣れ\nた。\n自宅での注射に向けて、母親に確認する事項で優先度が高いのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":105,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[45],"case_pages":[44],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM105"},"exam":113,"year":2024,"session":"PM","number":105},"sources":[{"title":"文部科学省：初めて通級による指導を担当する教師のためのガイド","url":"https://www.mext.go.jp/tsukyu-guide/index.html"}]},{"id":"113-PM-106","record":{"id":"113-PM-106","choice_explanations":[{"choice":1,"correct":false,"title":"｢入院中は毎日、タオルで身体を拭きます｣","explanation":"回復状況によりシャワーなどへ移行できます。入院期間中ずっと清拭だけと一律に決めません。"},{"choice":2,"correct":false,"title":"｢膀胱に入れている管は明日抜きます｣","explanation":"歩行と排尿機能などをみて抜去時期を判断します。必ず翌日まで留置するという説明は本例の予定として適切ではありません。"},{"choice":3,"correct":true,"title":"｢今日から歩行を開始します｣","explanation":"状態は安定しており、鎮痛を図りながら早期離床を進めます。初回歩行はめまいや転倒に注意して介助します。"},{"choice":4,"correct":false,"title":"｢食事は明日からです｣","explanation":"排ガスがあり全身状態も安定しています。指示に従い食事再開を検討でき、翌日まで絶食と決めつけません。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"帝王切開術後1日、午前9時、子宮底は臍下1横指、硬度良好、バイタルサイン\nは体温 36.9 ℃、呼吸数 18/分、脈拍 72/分、整、血圧 110/70 mmHg であった。夜\n間に排ガスを認めた。A さんは｢痛み止めを使用した後は眠れましたが、また痛み\nが出てきました。こんな状態で動けるか心配です。この後の予定を知りたいです｣\nと話した。\nこのときの A さんへの説明で適切なのはどれか。","choices":["｢入院中は毎日、タオルで身体を拭きます｣","｢膀胱に入れている管は明日抜きます｣","｢今日から歩行を開始します｣","｢食事は明日からです｣"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A さん(32 歳、初産婦)は、夫と2人で暮らしている。骨盤位のために妊娠 38 週0\n日に予定帝王切開術で午前 11 時に男児を出産した。分娩時出血量は 480 mL であっ\nた。出生後、手術室で男児と面会をして｢無事に生まれてきてくれてありがとう｣と話\nした。帰室後、子宮底は臍高、硬度良好、悪露は赤色で 20 g であった。後陣痛と創\n部痛があり夜間に鎮痛薬を使用した。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":106,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[46],"case_pages":[46],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM106"},"exam":113,"year":2024,"session":"PM","number":106},"sources":[]},{"id":"113-PM-107","record":{"id":"113-PM-107","choice_explanations":[{"choice":1,"correct":false,"title":"子宮復古が遅れている。","explanation":"産後3日で臍下3横指、悪露は褐色で、子宮復古の遅れを示す情報ではありません。"},{"choice":2,"correct":false,"title":"乳汁分泌が遅れている。","explanation":"移行乳の分泌がみられています。産後3日の所見だけで乳汁分泌の遅れとは判断しません。"},{"choice":3,"correct":true,"title":"母子相互作用がみられる。","explanation":"児へ語りかけ、目を合わせるなど相互の働きかけがあります。授乳技術が未熟でも母子の関係は育まれています。"},{"choice":4,"correct":false,"title":"マタニティブルーズである。","explanation":"慣れない授乳への言葉だけではマタニティブルーズと判断できません。気分や涙もろさなどを具体的に評価します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"帝王切開術後3日、子宮底は臍下3横指、悪露は褐色であった。乳房に熱感があ\nり、乳管は左右とも3本開通しており、移行乳の分泌を認める。看護師が訪室する\nと A さんは｢まだ、お腹の創が痛くて、動くのはつらいです｣と話す。慣れない手\n付きで児に授乳をしながら｢上手にできなくてごめんね｣と児の顔を見て語りかけて\nいる。A さんと児の目と目が合う様子がみられる。\nアセスメントで適切なのはどれか。","choices":["子宮復古が遅れている。","乳汁分泌が遅れている。","母子相互作用がみられる。","マタニティブルーズである。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A さん(32 歳、初産婦)は、夫と2人で暮らしている。骨盤位のために妊娠 38 週0\n日に予定帝王切開術で午前 11 時に男児を出産した。分娩時出血量は 480 mL であっ\nた。出生後、手術室で男児と面会をして｢無事に生まれてきてくれてありがとう｣と話\nした。帰室後、子宮底は臍高、硬度良好、悪露は赤色で 20 g であった。後陣痛と創\n部痛があり夜間に鎮痛薬を使用した。","preceding_context":[{"id":"113-PM-106","question":"帝王切開術後1日、午前9時、子宮底は臍下1横指、硬度良好、バイタルサイン\nは体温 36.9 ℃、呼吸数 18/分、脈拍 72/分、整、血圧 110/70 mmHg であった。夜\n間に排ガスを認めた。A さんは｢痛み止めを使用した後は眠れましたが、また痛み\nが出てきました。こんな状態で動けるか心配です。この後の予定を知りたいです｣\nと話した。\nこのときの A さんへの説明で適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":107,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[46],"case_pages":[46],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM107"},"exam":113,"year":2024,"session":"PM","number":107},"sources":[]},{"id":"113-PM-108","record":{"id":"113-PM-108","choice_explanations":[{"choice":1,"correct":false,"title":"｢授乳の回数を減らしましょう｣","explanation":"授乳を減らすと乳汁がたまり、張りが増す可能性があります。吸着を助け、有効に飲めるよう支援します。"},{"choice":2,"correct":true,"title":"｢授乳前に乳輪を柔らかくしましょう｣","explanation":"乳輪が硬いと児が深く含みにくくなります。授乳前に少量搾乳するなどして柔らかくし、吸着を助けます。"},{"choice":3,"correct":false,"title":"｢授乳と授乳の間は乳房を温めましょう｣","explanation":"授乳間に継続して温めると腫脹や不快感を強めることがあります。張りの状態に合うケアを行います。"},{"choice":4,"correct":false,"title":"｢乳房の緊満が強くなるのはこれからです｣","explanation":"すでに緊満があり困っています。これからさらに強まると一律に予告せず、現在の吸着と排乳を改善します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"帝王切開術後5日、診察の結果、明日退院することになった。A さんの乳房は\n緊満しており、乳管は左右とも5、6本開通している。母児同室を行い、児の哺乳\nの欲求に合わせて1日 10 回の授乳を行っている。｢母乳で育てたいと思っていま\nす。でもおっぱいが張ってつらいです。この子も上手に吸ってくれません｣と看護\n師に話した。\nこのときの看護師の説明で適切なのはどれか。","choices":["｢授乳の回数を減らしましょう｣","｢授乳前に乳輪を柔らかくしましょう｣","｢授乳と授乳の間は乳房を温めましょう｣","｢乳房の緊満が強くなるのはこれからです｣"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(32 歳、初産婦)は、夫と2人で暮らしている。骨盤位のために妊娠 38 週0\n日に予定帝王切開術で午前 11 時に男児を出産した。分娩時出血量は 480 mL であっ\nた。出生後、手術室で男児と面会をして｢無事に生まれてきてくれてありがとう｣と話\nした。帰室後、子宮底は臍高、硬度良好、悪露は赤色で 20 g であった。後陣痛と創\n部痛があり夜間に鎮痛薬を使用した。","preceding_context":[{"id":"113-PM-106","question":"帝王切開術後1日、午前9時、子宮底は臍下1横指、硬度良好、バイタルサイン\nは体温 36.9 ℃、呼吸数 18/分、脈拍 72/分、整、血圧 110/70 mmHg であった。夜\n間に排ガスを認めた。A さんは｢痛み止めを使用した後は眠れましたが、また痛み\nが出てきました。こんな状態で動けるか心配です。この後の予定を知りたいです｣\nと話した。\nこのときの A さんへの説明で適切なのはどれか。"},{"id":"113-PM-107","question":"帝王切開術後3日、子宮底は臍下3横指、悪露は褐色であった。乳房に熱感があ\nり、乳管は左右とも3本開通しており、移行乳の分泌を認める。看護師が訪室する\nと A さんは｢まだ、お腹の創が痛くて、動くのはつらいです｣と話す。慣れない手\n付きで児に授乳をしながら｢上手にできなくてごめんね｣と児の顔を見て語りかけて\nいる。A さんと児の目と目が合う様子がみられる。\nアセスメントで適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":108,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[47],"case_pages":[46],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM108"},"exam":113,"year":2024,"session":"PM","number":108},"sources":[]},{"id":"113-PM-109","record":{"id":"113-PM-109","choice_explanations":[{"choice":1,"correct":false,"title":"｢生きていれば良いことがありますよ｣","explanation":"根拠のない楽観的な励ましは苦痛を理解していないと受け取られ得ます。まずつらさを受け止めます。"},{"choice":2,"correct":false,"title":"｢薬を飲むと数日で効いて楽になります｣","explanation":"抗うつ薬の効果には時間がかかります。数日で必ず楽になると約束せず、経過と安全を確認します。"},{"choice":3,"correct":false,"title":"｢悲しいことが続くときは誰にでもあります｣","explanation":"誰にでもあることと一般化すると、深刻な苦痛を軽視されたと感じさせる場合があります。"},{"choice":4,"correct":true,"title":"｢A さんがつらい状況にあることを私は心配しています｣","explanation":"心配していることを率直に伝え、支援する姿勢を示します。希死念慮の確認と安全確保も継続します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"このときの看護師の対応で適切なのはどれか。","choices":["｢生きていれば良いことがありますよ｣","｢薬を飲むと数日で効いて楽になります｣","｢悲しいことが続くときは誰にでもあります｣","｢A さんがつらい状況にあることを私は心配しています｣"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A さん(65 歳、男性)は、妻と自営業を営んでおり、2人で暮らしている。2か月\n前に仕事で大きな失敗をし、謝罪と対応に追われ、あまり夜に眠れなくなり、食欲不\n振が続いている。1か月前から気分が落ち込み、仕事で妻から間違いを指摘されたこ\nとで自信をなくしていた。A さんは死んでしまいたいと思い、夜に自宅でロープを\n使って自殺を図ろうとしたところを妻に見つけられた。妻に付き添われ、精神科病院\nを受診し、うつ病と診断された。受診当日に入院し、抗うつ薬の内服が開始された。\ndepression\nA さんは｢生きていても仕方がない。どうせ誰も分かってくれない｣と看護師に話し\nた。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":109,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[48],"case_pages":[48],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM109"},"exam":113,"year":2024,"session":"PM","number":109},"sources":[]},{"id":"113-PM-110","record":{"id":"113-PM-110","choice_explanations":[{"choice":1,"correct":true,"title":"せん妄","explanation":"治療後に急に生じた注意障害、見当識障害、興奮からせん妄を考えます。安全を確保し全身状態を観察します。"},{"choice":2,"correct":false,"title":"躁状態","explanation":"躁状態は気分高揚や活動性亢進などを特徴とします。急な注意・見当識の障害が目立つ本例ではせん妄が適切です。"},{"choice":3,"correct":false,"title":"不安発作","explanation":"強い不安だけでは、提示された見当識障害や注意障害を十分に説明できません。"},{"choice":4,"correct":false,"title":"前向性健忘","explanation":"新しい出来事を記憶しにくい状態です。記憶以外にも広く注意・認知が障害されている本例は、せん妄として捉えます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんはその後しばらく会話をしたり、食事も少し食べられたりしていたが、\n入院3日から、臥床したままで1日中全く動かず、昏迷状態になった。検査の結\n果、軽度の脱水以外の異常はなかった。治療として修正型電気けいれん療法が開始\nされることになり、実施後 20 分で A さんは覚醒し、その後の観察中にけいれん発\n作は認めなかった。実施後 30 分、A さんは突然起き上がり興奮し、大きな声で\n｢仕事に行く｣と言って病室から出ていこうとした。看護師が制止し、一緒に座って\n話を聞いたところ、見当識障害、記憶障害、注意障害が認められた。\nA さんの状態で正しいのはどれか。","choices":["せん妄","躁状態","不安発作","前向性健忘"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":"A さん(65 歳、男性)は、妻と自営業を営んでおり、2人で暮らしている。2か月\n前に仕事で大きな失敗をし、謝罪と対応に追われ、あまり夜に眠れなくなり、食欲不\n振が続いている。1か月前から気分が落ち込み、仕事で妻から間違いを指摘されたこ\nとで自信をなくしていた。A さんは死んでしまいたいと思い、夜に自宅でロープを\n使って自殺を図ろうとしたところを妻に見つけられた。妻に付き添われ、精神科病院\nを受診し、うつ病と診断された。受診当日に入院し、抗うつ薬の内服が開始された。\ndepression\nA さんは｢生きていても仕方がない。どうせ誰も分かってくれない｣と看護師に話し\nた。","preceding_context":[{"id":"113-PM-109","question":"このときの看護師の対応で適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":110,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[49],"case_pages":[48],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM110"},"exam":113,"year":2024,"session":"PM","number":110},"sources":[]},{"id":"113-PM-111","record":{"id":"113-PM-111","choice_explanations":[{"choice":1,"correct":false,"title":"森田療法","explanation":"不安などをあるがままに受け止め、行動を重視する療法です。本問の悲観的な認知への直接の働きかけには認知行動療法を選びます。"},{"choice":2,"correct":false,"title":"集団精神療法","explanation":"集団での交流も支援になりますが、失敗を過大に一般化する思考に焦点を当てる方法がより適切です。"},{"choice":3,"correct":true,"title":"認知行動療法","explanation":"「必ず失敗する」などの自動思考を検討し、状況を柔軟に捉え直す練習をします。行動面からの支援も組み合わせます。"},{"choice":4,"correct":false,"title":"社会生活技能訓練〈SST〉","explanation":"社会生活に必要な対人技能などを練習する方法です。悲観的な考えの偏りが中心の本例とは標的が異なります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"入院1か月が経過し、A さんは夜間の睡眠がとれるようになり、食事は全量摂\n取している。妻から間違いを指摘されたことを思い出し、｢何をやってもきっと失\n敗するだけだ。今度はもっと大きな失敗をして仕事を辞めることになる。だから自\n分はだめな人間だ。努力しても意味がない｣と看護師に言った。\nA さんへの治療法で最も適切なのはどれか。","choices":["森田療法","集団精神療法","認知行動療法","社会生活技能訓練〈SST〉"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A さん(65 歳、男性)は、妻と自営業を営んでおり、2人で暮らしている。2か月\n前に仕事で大きな失敗をし、謝罪と対応に追われ、あまり夜に眠れなくなり、食欲不\n振が続いている。1か月前から気分が落ち込み、仕事で妻から間違いを指摘されたこ\nとで自信をなくしていた。A さんは死んでしまいたいと思い、夜に自宅でロープを\n使って自殺を図ろうとしたところを妻に見つけられた。妻に付き添われ、精神科病院\nを受診し、うつ病と診断された。受診当日に入院し、抗うつ薬の内服が開始された。\ndepression\nA さんは｢生きていても仕方がない。どうせ誰も分かってくれない｣と看護師に話し\nた。","preceding_context":[{"id":"113-PM-109","question":"このときの看護師の対応で適切なのはどれか。"},{"id":"113-PM-110","question":"A さんはその後しばらく会話をしたり、食事も少し食べられたりしていたが、\n入院3日から、臥床したままで1日中全く動かず、昏迷状態になった。検査の結\n果、軽度の脱水以外の異常はなかった。治療として修正型電気けいれん療法が開始\nされることになり、実施後 20 分で A さんは覚醒し、その後の観察中にけいれん発\n作は認めなかった。実施後 30 分、A さんは突然起き上がり興奮し、大きな声で\n｢仕事に行く｣と言って病室から出ていこうとした。看護師が制止し、一緒に座って\n話を聞いたところ、見当識障害、記憶障害、注意障害が認められた。\nA さんの状態で正しいのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":111,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[49],"case_pages":[48],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM111"},"exam":113,"year":2024,"session":"PM","number":111},"sources":[]},{"id":"113-PM-112","record":{"id":"113-PM-112","choice_explanations":[{"choice":1,"correct":false,"title":"｢主治医に薬の変更を相談しましょう｣","explanation":"まず睡眠と症状、副作用の具体的状況を評価します。開始1週だけで薬の変更を前提にはしません。"},{"choice":2,"correct":true,"title":"｢睡眠状況を具体的に教えてください｣","explanation":"入眠、途中覚醒、睡眠時間、日中への影響などを聴きます。強迫行為や薬剤の影響を把握して支援につなげます。"},{"choice":3,"correct":false,"title":"｢B さんに別の部署に異動したいと伝えてみましょう｣","explanation":"異動で解決するとは限りません。現在の症状を把握する前に職場変更を勧めません。"},{"choice":4,"correct":false,"title":"｢鍵を閉めたかどうか気になるときは別のことを考えましょう｣","explanation":"簡単な気分転換だけで強迫観念を抑えることは難しく、本人の努力不足のように受け取られるおそれがあります。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"内服を始めて1週後、A さんは看護師に｢鍵を閉めたかどうかの確認が増え、睡\n眠時間が減ってつらい｣と訴えている。\n看護師の声かけで適切なのはどれか。","choices":["｢主治医に薬の変更を相談しましょう｣","｢睡眠状況を具体的に教えてください｣","｢B さんに別の部署に異動したいと伝えてみましょう｣","｢鍵を閉めたかどうか気になるときは別のことを考えましょう｣"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(24 歳、女性)は大学卒業後、一般企業に就職したが、何度も自宅の鍵を閉\nめたかどうかを確認するため、遅刻を繰り返した。連絡せずに複数回の遅刻があった\nことを上司の B さんから強く注意され、うつ状態となったため精神科外来を受診し\nたところ、強迫性障害と診断され、選択的セロトニン再取り込み阻害薬〈SSRI〉が処\nobsessive-compulsive disorder\n方された。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":112,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[50],"case_pages":[50],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM112"},"exam":113,"year":2024,"session":"PM","number":112},"sources":[]},{"id":"113-PM-113","record":{"id":"113-PM-113","choice_explanations":[{"choice":1,"correct":false,"title":"要望に応じ続ける方がよいと助言する。","explanation":"家族が確認行為に応じ続けると、強迫行為の維持につながる場合があります。治療者と段階的な対応を考えます。"},{"choice":2,"correct":false,"title":"治療の効果が得られるまで待つように伝える。","explanation":"母親は現在の関わり方に困っています。効果が出るまで待つだけでなく、理解と負担を確認します。"},{"choice":3,"correct":true,"title":"母親が疾患をどのように理解しているか確認する。","explanation":"疾患の捉え方や困り事を聴いたうえで、巻き込まれを減らす対応を一緒に考えます。"},{"choice":4,"correct":false,"title":"A さんが大きな声を出しても反応しないように助言する。","explanation":"一律の無視を突然勧めると関係の悪化や混乱を招くことがあります。状況を把握して対応を調整します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"受診に同行していた母親からは｢A から『私の代わりに鍵が閉まっているか見て\nきてほしい』といった要望が多い。それに従わないと『どうして私のつらさを分かっ\nてくれないの』と大きな声を出す。どのように関わればよいか分からない｣と看護師\nに相談があった。\n母親への看護師の対応で適切なのはどれか。","choices":["要望に応じ続ける方がよいと助言する。","治療の効果が得られるまで待つように伝える。","母親が疾患をどのように理解しているか確認する。","A さんが大きな声を出しても反応しないように助言する。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A さん(24 歳、女性)は大学卒業後、一般企業に就職したが、何度も自宅の鍵を閉\nめたかどうかを確認するため、遅刻を繰り返した。連絡せずに複数回の遅刻があった\nことを上司の B さんから強く注意され、うつ状態となったため精神科外来を受診し\nたところ、強迫性障害と診断され、選択的セロトニン再取り込み阻害薬〈SSRI〉が処\nobsessive-compulsive disorder\n方された。","preceding_context":[{"id":"113-PM-112","question":"内服を始めて1週後、A さんは看護師に｢鍵を閉めたかどうかの確認が増え、睡\n眠時間が減ってつらい｣と訴えている。\n看護師の声かけで適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":113,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[50],"case_pages":[50],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM113"},"exam":113,"year":2024,"session":"PM","number":113},"sources":[]},{"id":"113-PM-114","record":{"id":"113-PM-114","choice_explanations":[{"choice":1,"correct":false,"title":"外出を控えるよう助言する。","explanation":"外出の回避は生活範囲を狭め、不安への対処を学ぶ機会を減らす可能性があります。"},{"choice":2,"correct":false,"title":"外出するときは誰かに付き添ってもらうよう提案する。","explanation":"付き添いを常に求めると、本人の確認行為に家族等が巻き込まれる可能性があります。"},{"choice":3,"correct":false,"title":"鍵の閉め忘れが気になる理由を考えてみるよう伝える。","explanation":"抽象的に理由を考え続けると反すうにつながる場合があります。具体的な場面と行動に着目します。"},{"choice":4,"correct":true,"title":"鍵の閉め忘れが特に気になるときの前後の状況を振り返るよう促す。","explanation":"不安が高まる前後の出来事、考え、確認行為を整理し、対処を検討します。必要な行動療法は治療者と連携します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"選択的セロトニン再取り込み阻害薬〈SSRI〉の内服を始めてから2か月が経過し、\nA さんは外出中に鍵を閉め忘れたかもしれないという考えが強くなり、外出から\n予定より早く帰宅することがある。A さんは｢鍵を閉め忘れていないかの確認を減\nらしたい｣と看護師に相談した。\nA さんへの看護師の対応で適切なのはどれか。","choices":["外出を控えるよう助言する。","外出するときは誰かに付き添ってもらうよう提案する。","鍵の閉め忘れが気になる理由を考えてみるよう伝える。","鍵の閉め忘れが特に気になるときの前後の状況を振り返るよう促す。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A さん(24 歳、女性)は大学卒業後、一般企業に就職したが、何度も自宅の鍵を閉\nめたかどうかを確認するため、遅刻を繰り返した。連絡せずに複数回の遅刻があった\nことを上司の B さんから強く注意され、うつ状態となったため精神科外来を受診し\nたところ、強迫性障害と診断され、選択的セロトニン再取り込み阻害薬〈SSRI〉が処\nobsessive-compulsive disorder\n方された。","preceding_context":[{"id":"113-PM-112","question":"内服を始めて1週後、A さんは看護師に｢鍵を閉めたかどうかの確認が増え、睡\n眠時間が減ってつらい｣と訴えている。\n看護師の声かけで適切なのはどれか。"},{"id":"113-PM-113","question":"受診に同行していた母親からは｢A から『私の代わりに鍵が閉まっているか見て\nきてほしい』といった要望が多い。それに従わないと『どうして私のつらさを分かっ\nてくれないの』と大きな声を出す。どのように関わればよいか分からない｣と看護師\nに相談があった。\n母親への看護師の対応で適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":114,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[51],"case_pages":[50],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM114"},"exam":113,"year":2024,"session":"PM","number":114},"sources":[]},{"id":"113-PM-115","record":{"id":"113-PM-115","choice_explanations":[{"choice":1,"correct":false,"title":"息苦しいときは非侵襲的陽圧換気の吸気圧を上げる。","explanation":"吸気圧を自己判断で上げず、呼吸状態と回路・マスク等を確認します。設定の変更は治療チームの指示に従います。"},{"choice":2,"correct":false,"title":"人工呼吸器が動かないときはすぐに救急車を要請する。","explanation":"救急要請が必要な場合もありますが、呼吸を確保する対応を遅らせません。指導された用手換気と応援要請を行います。"},{"choice":3,"correct":true,"title":"人工呼吸器が過剰送気を示すときは回路が外れていないか確認する。","explanation":"回路の外れや大きな漏れにより送気が増えることがあります。患者の状態を確認し、接続と機器の表示を点検します。"},{"choice":4,"correct":false,"title":"マスクの周囲から空気が漏れるときはマスクのベルトをきつく締める。","explanation":"過度に締めると皮膚損傷や不快感を招きます。位置、サイズ、密着状態を調整し、改善しなければ相談します。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんの両親に対する看護師の指導で適切なのはどれか。","choices":["息苦しいときは非侵襲的陽圧換気の吸気圧を上げる。","人工呼吸器が動かないときはすぐに救急車を要請する。","人工呼吸器が過剰送気を示すときは回路が外れていないか確認する。","マスクの周囲から空気が漏れるときはマスクのベルトをきつく締める。"],"correct_answers":[3],"accepted_answer_sets":[[3]],"case_text":"A さん(14 歳、男子、特別支援学校の中学生)は Duchenne〈デュシェンヌ〉型筋ジ\nDuchenne muscular dystrophy\nストロフィーで両親、弟(7歳)と2階建ての家に4人で暮らしている。呼吸障害が進\n行したため非侵襲的陽圧換気療法を導入する目的で入院した。A さんの呼吸状態は\n安定し、両親に対するバッグバルブマスクによる用手換気の指導が終了したため、自\n宅に退院し訪問看護を毎日利用して療養生活を続けることになった。両親は｢日常の\n呼吸管理について退院後に対応できるか心配です｣と病棟の看護師に話した。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":115,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[52],"case_pages":[52],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM115"},"exam":113,"year":2024,"session":"PM","number":115},"sources":[{"title":"厚生労働省：人工呼吸器の安全管理","url":"https://www.mhlw.go.jp/topics/bukyoku/isei/i-anzen/1/torikumi/naiyou/manual/2a.html"}]},{"id":"113-PM-116","record":{"id":"113-PM-116","choice_explanations":[{"choice":1,"correct":true,"title":"非常用電源の選び方","explanation":"呼吸器を継続して動かす電源は生命維持に直結します。機器との適合、使用可能時間、充電方法を確認します。"},{"choice":2,"correct":false,"title":"福祉避難所への移動手段","explanation":"避難先と移動手段も重要ですが、移動までの間を含めて換気を維持する電源確保が優先です。"},{"choice":3,"correct":false,"title":"足踏み式吸引器の使用方法","explanation":"停電時の吸引への備えも必要ですが、本例で優先されるのは人工呼吸器の電源です。"},{"choice":4,"correct":false,"title":"ハザードマップの確認方法","explanation":"災害リスクの把握は必要です。そのうえで生命維持に直結する機器を動かす備えを具体化します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"退院後1週。A さんの父親から｢最近、大雨や落雷、地震による被災の報道が多\nくて、A は人工呼吸器を付けているし、弟もまだ小さいので不安です。災害に備\nえ何をすればよいでしょうか｣と訪問看護師に相談があった。\n訪問看護師が A さんの父親に説明する内容で優先度が高いのはどれか。","choices":["非常用電源の選び方","福祉避難所への移動手段","足踏み式吸引器の使用方法","ハザードマップの確認方法"],"correct_answers":[1],"accepted_answer_sets":[[1]],"case_text":"A さん(14 歳、男子、特別支援学校の中学生)は Duchenne〈デュシェンヌ〉型筋ジ\nDuchenne muscular dystrophy\nストロフィーで両親、弟(7歳)と2階建ての家に4人で暮らしている。呼吸障害が進\n行したため非侵襲的陽圧換気療法を導入する目的で入院した。A さんの呼吸状態は\n安定し、両親に対するバッグバルブマスクによる用手換気の指導が終了したため、自\n宅に退院し訪問看護を毎日利用して療養生活を続けることになった。両親は｢日常の\n呼吸管理について退院後に対応できるか心配です｣と病棟の看護師に話した。","preceding_context":[{"id":"113-PM-115","question":"A さんの両親に対する看護師の指導で適切なのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":116,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[52],"case_pages":[52],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM116"},"exam":113,"year":2024,"session":"PM","number":116},"sources":[]},{"id":"113-PM-117","record":{"id":"113-PM-117","choice_explanations":[{"choice":1,"correct":false,"title":"A さんが特別支援学校を2週間休むことを勧める。","explanation":"接触した可能性だけで一律に2週間休む指導ではありません。本人の症状と学校等の対応方針を確認します。"},{"choice":2,"correct":false,"title":"A さんが感染予防の目的で入院することを医師に相談する。","explanation":"感染予防だけを目的に入院を前提とせず、まず家庭での感染対策と症状時の連絡方法を整えます。"},{"choice":3,"correct":false,"title":"A さんは予防接種を受けているのでうつらないと説明する。","explanation":"予防接種を受けても感染する可能性はあります。接種済みでも家庭内の対策を続けます。"},{"choice":4,"correct":true,"title":"ケアを父母で分担し、弟の担当は弟以外と接触しないことを提案する。","explanation":"可能な範囲で担当を分け、感染している弟から他の家族への接触経路を減らします。手洗い、換気、マスク等も組み合わせます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"退院後6か月。A さんは人工呼吸器を装着して特別支援学校に通学することに\nも慣れてきた。A さんの母親から｢弟がインフルエンザと診断された。弟は2階の\n子ども部屋、A は1階のリビングで過ごしている。家族全員がインフルエンザの\n予防接種を受けた。A にインフルエンザがうつらないか心配｣と訪問看護師に連絡\nがあった。\n訪問看護師の対応で適切なのはどれか。","choices":["A さんが特別支援学校を2週間休むことを勧める。","A さんが感染予防の目的で入院することを医師に相談する。","A さんは予防接種を受けているのでうつらないと説明する。","ケアを父母で分担し、弟の担当は弟以外と接触しないことを提案する。"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A さん(14 歳、男子、特別支援学校の中学生)は Duchenne〈デュシェンヌ〉型筋ジ\nDuchenne muscular dystrophy\nストロフィーで両親、弟(7歳)と2階建ての家に4人で暮らしている。呼吸障害が進\n行したため非侵襲的陽圧換気療法を導入する目的で入院した。A さんの呼吸状態は\n安定し、両親に対するバッグバルブマスクによる用手換気の指導が終了したため、自\n宅に退院し訪問看護を毎日利用して療養生活を続けることになった。両親は｢日常の\n呼吸管理について退院後に対応できるか心配です｣と病棟の看護師に話した。","preceding_context":[{"id":"113-PM-115","question":"A さんの両親に対する看護師の指導で適切なのはどれか。"},{"id":"113-PM-116","question":"退院後1週。A さんの父親から｢最近、大雨や落雷、地震による被災の報道が多\nくて、A は人工呼吸器を付けているし、弟もまだ小さいので不安です。災害に備\nえ何をすればよいでしょうか｣と訪問看護師に相談があった。\n訪問看護師が A さんの父親に説明する内容で優先度が高いのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":117,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[53],"case_pages":[52],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM117"},"exam":113,"year":2024,"session":"PM","number":117},"sources":[]},{"id":"113-PM-118","record":{"id":"113-PM-118","choice_explanations":[{"choice":1,"correct":false,"title":"｢入浴直後に照射部位の観察をしましょう｣","explanation":"入浴直後は温熱で皮膚が赤くなり、照射による変化と区別しにくくなります。落ち着いた状態で観察します。"},{"choice":2,"correct":false,"title":"｢照射後は照射部位に冷湿布を貼りましょう｣","explanation":"湿布の刺激や剝がす際の損傷を避けます。痛みや熱感への対応は治療チームに相談します。"},{"choice":3,"correct":false,"title":"｢照射部位の皮膚は乾燥させておきましょう｣","explanation":"皮膚は乾燥しやすいため、状態に応じた保湿が必要です。過度に乾燥させる指導ではありません。"},{"choice":4,"correct":true,"title":"｢照射部位は強くこすらないようにしましょう｣","explanation":"照射部位の皮膚は刺激に弱くなります。優しく洗い、こすらず押さえて水分を取り、摩擦を避けます。"}],"status":"VERIFIED","review_reason":"","fixes_made":[]},"input_anchor":{"question":"放射線外来の看護師が行う A さんへの説明で正しいのはどれか。","choices":["｢入浴直後に照射部位の観察をしましょう｣","｢照射後は照射部位に冷湿布を貼りましょう｣","｢照射部位の皮膚は乾燥させておきましょう｣","｢照射部位は強くこすらないようにしましょう｣"],"correct_answers":[4],"accepted_answer_sets":[[4]],"case_text":"A さん(72 歳、男性)は、妻と2人暮らしで子どもはいない。定年後は2人で旅行\nするのが趣味であった。A さんは、1か月前から残尿感や夜間頻尿が気になり病院\nを受診した結果、前立腺癌と診断され根治的前立腺摘出手術を受けた。退院後は、手\nprostate cancer\n術後の補助療法として、外来で放射線の外照射療法を行うことになっている。","preceding_context":[],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":118,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[54],"case_pages":[54],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM118"},"exam":113,"year":2024,"session":"PM","number":118},"sources":[{"title":"国立がん研究センター：放射線治療中のスキンケア","url":"https://www.ncc.go.jp/jp/ncch/division/nursing/power/010/080/index.html"}]},{"id":"113-PM-119","record":{"id":"113-PM-119","choice_explanations":[{"choice":1,"correct":false,"title":"｢次回から照射中は傍に付き添います｣","explanation":"照射中は医療者の被ばくを避けるため治療室外から見守ります。室内で傍に付き添うと約束しません。"},{"choice":2,"correct":true,"title":"｢治療体位をとるための固定具を工夫してみます｣","explanation":"毎回同じ位置を保ちながら苦痛を減らせるよう、固定具や支持の方法を治療チームと調整します。"},{"choice":3,"correct":false,"title":"｢照射時間を短くできるよう主治医に相談してみます｣","explanation":"照射時間は計画した線量と方法で決まります。まず体位を楽に保つ工夫と不安への説明を行います。"},{"choice":4,"correct":false,"title":"｢照射中に体位変換ができるよう放射線技師に相談します｣","explanation":"照射中の体位変換は照射位置のずれを生じます。つらい場合の合図や中断方法を確認します。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんの放射線療法が開始され初回の照射を終えた。放射線外来の看護師は、\n終了後に A さんへ声をかけた。A さんは｢ベッドは硬いし、最後まで同じ姿勢でい\nることがとても苦痛です。大きな音がするので恐怖も感じます｣と訴えた。\nこのときの看護師の説明で正しいのはどれか。","choices":["｢次回から照射中は傍に付き添います｣","｢治療体位をとるための固定具を工夫してみます｣","｢照射時間を短くできるよう主治医に相談してみます｣","｢照射中に体位変換ができるよう放射線技師に相談します｣"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(72 歳、男性)は、妻と2人暮らしで子どもはいない。定年後は2人で旅行\nするのが趣味であった。A さんは、1か月前から残尿感や夜間頻尿が気になり病院\nを受診した結果、前立腺癌と診断され根治的前立腺摘出手術を受けた。退院後は、手\nprostate cancer\n術後の補助療法として、外来で放射線の外照射療法を行うことになっている。","preceding_context":[{"id":"113-PM-118","question":"放射線外来の看護師が行う A さんへの説明で正しいのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":119,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[54],"case_pages":[54],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM119"},"exam":113,"year":2024,"session":"PM","number":119},"sources":[]},{"id":"113-PM-120","record":{"id":"113-PM-120","choice_explanations":[{"choice":1,"correct":false,"title":"妻が A さんの死を受け入れられるよう妻を励ますこと","explanation":"死を受け入れるよう急がせず、不安や悲しみをそのまま表せる関わりが必要です。"},{"choice":2,"correct":true,"title":"妻が A さんへの思いを看護師 B に語る時間をつくること","explanation":"夫への思いや不安を語る時間をつくり、妻の気持ちを受け止めます。休息や身体状態への支援も行います。"},{"choice":3,"correct":false,"title":"A さんの予後について再度主治医から妻へ説明するよう調整すること","explanation":"理解が不足しているかを確認せず、予後の再説明だけで解決しようとしません。まず妻の思いを聴きます。"},{"choice":4,"correct":false,"title":"妻が A さんの死を受け入れられるまで夜も付き添うよう妻に伝えること","explanation":"睡眠不足とふらつきがあり、夜間の付き添い継続を求めると負担が増します。休息できる体制を整えます。"}],"status":"PASS","review_reason":"","fixes_made":[]},"input_anchor":{"question":"A さんが放射線治療を終了して半年後、腰部と右大腿部の痛みが出現した。倦\n怠感と食欲不振が続いたため病院を受診し精密検査を受けた。骨転移していること\nが分かり、A さんと妻に主治医から余命と治療方針の説明があった。A さんはそ\nの場で｢痛みを取り除いてほしい。つらい治療は受けたくない｣と訴え、3日後に緩\n和ケア病棟に入院した。\n入院翌日、受け持ちの看護師 B が、プリセプターである看護師に｢今朝、奥さん\nの顔色が悪くふらついていたので声をかけると『夫の最期を受け入れられない気が\nして不安です』と打ち明けられました。昨夜も眠らずに A さんに付き添っていたよ\nうでした。奥さんにどう対応したらよいのでしょうか｣と相談した。\nプリセプターである看護師が看護師 B に助言する内容で適切なのはどれか。","choices":["妻が A さんの死を受け入れられるよう妻を励ますこと","妻が A さんへの思いを看護師 B に語る時間をつくること","A さんの予後について再度主治医から妻へ説明するよう調整すること","妻が A さんの死を受け入れられるまで夜も付き添うよう妻に伝えること"],"correct_answers":[2],"accepted_answer_sets":[[2]],"case_text":"A さん(72 歳、男性)は、妻と2人暮らしで子どもはいない。定年後は2人で旅行\nするのが趣味であった。A さんは、1か月前から残尿感や夜間頻尿が気になり病院\nを受診した結果、前立腺癌と診断され根治的前立腺摘出手術を受けた。退院後は、手\nprostate cancer\n術後の補助療法として、外来で放射線の外照射療法を行うことになっている。","preceding_context":[{"id":"113-PM-118","question":"放射線外来の看護師が行う A さんへの説明で正しいのはどれか。"},{"id":"113-PM-119","question":"A さんの放射線療法が開始され初回の照射を終えた。放射線外来の看護師は、\n終了後に A さんへ声をかけた。A さんは｢ベッドは硬いし、最後まで同じ姿勢でい\nることがとても苦痛です。大きな音がするので恐怖も感じます｣と訴えた。\nこのときの看護師の説明で正しいのはどれか。"}],"source":{"organization":"厚生労働省","exam":"第113回看護師国家試験","session":"午後","question_number":120,"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05c_01.pdf","pages":[55],"case_pages":[54],"sha256":"e50d5bb3161bfde77acd8b9703438480b94f2cf09057b545f4f2a9561d42025b"},"answer_source":{"url":"https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/dl/tp240424-05seitou.pdf","page":2,"row_id":"PM120"},"exam":113,"year":2024,"session":"PM","number":120},"sources":[]}]);
